fun findWinner(testCases: List<Pair<Int, List<Int>>>): List<String> {
    val results = mutableListOf<String>()
    for ((n, a) in testCases) {
        val minValue = a.minOrNull()!!
        val idx = a.indexOf(minValue)
        if (idx % 2 == 0) {
            results.add("Mike")
        } else {
            results.add("Joe")
        }
    }
    return results
};1

fun reachingPoints(sx: Int, sy: Int, tx: Int, ty: Int): Boolean {
    var txVar = tx
    var tyVar = ty
    while (txVar > sx && tyVar > sy && txVar != tyVar) {
        if (txVar > tyVar) {
            txVar %= tyVar
            if (txVar == 0) txVar = tyVar
        } else {
            tyVar %= txVar
            if (tyVar == 0) tyVar = txVar
        }
    }
    return when {
        txVar == sx && tyVar == sy -> true
        txVar == sx -> tyVar >= sy && (tyVar - sy) % sx == 0
        tyVar == sy -> txVar >= sx && (txVar - sx) % sy == 0
        else -> false
    }
};1

import java.lang.String
