class PositionList {
    var position: Int = 0
    var next: PositionList? = null
}
 
class LetterList {
    var letter: Char =''
    var repititions: Int = 0
    var positions: PositionList? = null
    var next: LetterList? = null
}
 
var letterSet: LetterList? = null
var duplicatesFound: Boolean = false
 
fun checkAndUpdateLetterList(c: Char, pos: Int) {
    var letterOccurs: Boolean = false
    var letterIterator: LetterList? = null
    var newLetter: LetterList? = null
    var positionIterator: PositionList? = null
    var newPosition: PositionList? = null
 
    if (letterSet == null) {
        letterSet = LetterList()
        letterSet!!.letter = c
        letterSet!!.repititions = 0
 
        letterSet!!.positions = PositionList()
        letterSet!!.positions!!.position = pos
        letterSet!!.positions!!.next = null
 
        letterSet!!.next = null
    } else {
        letterIterator = letterSet
 
        while (letterIterator!= null) {
            if (letterIterator!!.letter == c) {
                letterOccurs = true
                duplicatesFound = true
 
                letterIterator!!.repititions++
                positionIterator = letterIterator!!.positions
 
                while (positionIterator!!.next!= null) {
                    positionIterator = positionIterator!!.next
                }
 
                newPosition = PositionList()
                newPosition!!.position = pos
                newPosition!!.next = null
 
                positionIterator!!.next = newPosition
            }
            if (letterOccurs == false && letterIterator!!.next == null) {
                break
            } else {
                letterIterator = letterIterator!!.next
            }
        }
 
        if (letterOccurs == false) {
            newLetter = LetterList()
            newLetter!!.letter = c
 
            newLetter!!.repititions = 0
 
            newLetter!!.positions = PositionList()
            newLetter!!.positions!!.position = pos
            newLetter!!.positions!!.next = null
 
            newLetter!!.next = null
 
            letterIterator!!.next = newLetter
        }
    }
}
 
