import java.util.LinkedList
import java.util.List
 
fun sieve(limit: Int, primes: MutableList<Int>) {
    val c = BooleanArray(limit)
    for (i in 0 until limit) {
        c[i] = false
    }
    // No need to process even numbers
    var p = 3
    var n = 0
    var p2 = p * p
    while (p2 <= limit) {
        for (i in p2..limit step 2 * p) {
            c[i] = true
        }
        do {
            p += 2
        } while (c[p])
        p2 = p * p
    }
    for (i in 3..limit step 2) {
        if (!c[i]) {
            primes.add(i)
        }
    }
}
 
// Finds the period of the reciprocal of n
fun findPeriod(n: Int): Int {
    var r = 1
    var period = 0
    for (i in 1 until n) {
        r = (10 * r) % n
    }
    var rr = r
    do {
        r = (10 * r) % n
        ++period
    } while (r!= rr)
    return period
}
 
fun main(args: Array<String>) {
    val numbers = intArrayOf(500, 1000, 2000, 4000, 8000, 16000, 32000, 64000)
    val totals = IntArray(numbers.size)
    val primes = LinkedList<Int>()
    val longPrimes = LinkedList<Int>()
    sieve(64000, primes)
    for (prime in primes) {
        if (findPeriod(prime) == prime - 1) {
            longPrimes.add(prime)
        }
    }
    var count = 0
    var index = 0
    for (longPrime in longPrimes) {
        if (longPrime > numbers[index]) {
            totals[index++] = count
        }
        ++count
    }
    totals[numbers.size - 1] = count
    println("The long primes up to " + numbers[0] + " are:")
    println(longPrimes.subList(0, totals[0]))
    println()
    println("The number of long primes up to:")
    for (i in 0..7) {
        println(String.format("  %5d is %d", numbers[i], totals[i]))
    }
};1

