fun isPangram(s: String): Boolean {
    val alphabet = "abcdefghijklmnopqrstuvwxyz"
    val lowerCase = s.toLowerCase()
    val sorted = lowerCase.sorted()
    val set = sorted.toSet()
    return alphabet.all { it in set }
}
 
