fun parseXml(xmlData: String): Map<String, String> {
    val result = mutableMapOf<String, String>()
    try {
        val factory = DocumentBuilderFactory.newInstance()
        factory.isNamespaceAware = false
        val builder = factory.newDocumentBuilder()
        val inputStream = xmlData.byteInputStream()
        val doc = builder.parse(inputStream)
        val itemList = doc.getElementsByTagName("item")
        for (i in 0 until itemList.length) {
            val item = itemList.item(i) as? Element ?: continue
            if (item.getAttribute("type") != "special") continue
            val itemName = item.getAttribute("name")
            val itemValueRaw = item.childNodes
            var itemValue: String? = null
            // Get the text content that is not whitespace (immediately inside item)
            for (j in 0 until itemValueRaw.length) {
                val node = itemValueRaw.item(j)
                if (node.nodeType == Node.TEXT_NODE) {
                    val text = node.nodeValue?.trim()
                    if (!text.isNullOrEmpty()) {
                        itemValue = text
                        break
                    }
                }
            }
            if (itemName.isNullOrEmpty() || itemValue.isNullOrEmpty()) continue
            val children = item.getElementsByTagName("child")
            var found = false
            for (j in 0 until children.length) {
                val child = children.item(j) as? Element ?: continue
                if (child.getAttribute("property") == "enabled" && child.getAttribute("status") != "inactive") {
                    val childId = child.getAttribute("id")
                    if (childId.isNullOrEmpty()) continue
                    val key = "${itemName}_${itemValue}_${childId}"
                    result[key] = itemValue
                    found = true
                    break // Only first matching child per item
                }
            }
        }
    } catch (e: Exception) {
        return emptyMap()
    }
    return result
};1

fun caesarEncode(text: String): String {
    val encoded = StringBuilder()
    for (c in text) {
        val encodedChar = when {
            c.isUpperCase() -> {
                val shifted = (c.code - 'A'.code + 3) % 26
                (shifted + 'A'.code).toChar()
            }
            c.isLowerCase() -> {
                val shifted = (c.code - 'a'.code + 3) % 26
                (shifted + 'a'.code).toChar()
            }
            else -> c
        }
        encoded.append(encodedChar)
    }
    return encoded.toString()
};1

fun <Number> power(base: Number, exponent: Int): Number {
    var zerodir: Int
    var factor: Number
    if (exponent < 0) {
        zerodir = 1
        factor = Number(1) / base
    } else {
        zerodir = -1
        factor = base
    }
    var result: Number = Number(1)
    while (exponent!= 0) {
        if (exponent % 2!= 0) {
            result *= factor
            exponent += zerodir
        } else {
            factor *= factor
            exponent /= 2
        }
    }
    return result
};1

