fun pairConsecutiveSum(n: Int): List<Pair<Int, Int>>? {
    if (n % 2 == 0) {
        return null
    }
    val L = (1..n).toList()
    val U = ((n+1)..(2*n)).toList()
    val middle = (n-1) / 2
    val firstPart = MutableList((n + 1) / 2) { middle - it }
    val secondPart = MutableList((n - 1) / 2) { (n - 1) - it }
    val L_order = firstPart + secondPart
    val evenIndices = (0 until n step 2).toList()
    val oddIndices = (1 until n step 2).toList()
    val U_order = evenIndices + oddIndices
    val result = mutableListOf<Pair<Int, Int>>()
    for (i in 0 until n) {
        val a = L[L_order[i]]
        val b = U[U_order[i]]
        result.add(Pair(a, b))
    }
    return result
};1

fun mode(ary: Array<Int>): Array<Int> {
    val seen = HashMap<Int, Int>()
    ary.forEach { value -> seen.put(value, seen.getOrDefault(value, 0) + 1) }
    val max = seen.values.max()
    return seen.filter { key, value -> value == max }.map { key, value -> key }.toTypedArray()
}
 
fun modeOnePass(ary: Array<Int>): Array<Int> {
    val seen = HashMap<Int, Int>()
    var max = 0
    var maxElems = ArrayList<Int>()
    ary.forEach { value ->
        seen.put(value, seen.getOrDefault(value, 0) + 1)
        if (seen[value]!! > max) {
            max = seen[value]!!
            maxElems = arrayListOf(value)
        } else if (seen[value] == max) {
            maxElems.add(value)
        }
    }
    return maxElems.toTypedArray()
}
 
fun main(args: Array<String>) {
    println(mode(arrayOf(1, 3, 6, 6, 6, 6, 7, 7, 12, 12, 17)).contentToString())
    println(mode(arrayOf(1, 1, 2, 4, 4)).contentToString())
    println(modeOnePass(arrayOf(1, 3, 6, 6, 6, 6, 7, 7, 12, 12, 17)).contentToString())
    println(modeOnePass(arrayOf(1, 1, 2, 4, 4)).contentToString())
};1

enum class Fibonacci {
    ITERATIVE {
        fun get(n: Int): Long = if (n < 2) {
            n.toLong()
        } else {
            var n1 = 0L
            var n2 = 1L
            repeat(n) {
                val sum = n1 + n2
                n1 = n2
                n2 = sum
            }
            n1
        }
    },
    RECURSIVE {
        fun get(n: Int): Long = if (n < 2) n.toLong() else this[n - 1] + this[n - 2]
    },
    CACHING {
        val cache: MutableMap<Int, Long> = mutableMapOf(0 to 0L, 1 to 1L)
        fun get(n: Int): Long = if (n < 2) n.toLong() else impl(n)
        fun impl(n: Int): Long = cache.computeIfAbsent(n) { impl(it-1) + impl(it-2) }
    },
    ;
 
    abstract operator fun get(n: Int): Long
}
 
