fun generateRandomNumbers(n: Int, min: Double, max: Double): List<Double> {
    // Validate `n`
    if (n !is Int) {
        throw IllegalArgumentException("'n' must be an integer, got ${n::class.simpleName}.")
    }
    if (n <= 0) {
        throw IllegalArgumentException("'n' must be a positive integer.")
    }

    // Validate `min` and `max`
    // Only Double types are allowed as function args; but check anyway for clarity
    if (min !is Double && min !is Float && min !is Int) {
        throw IllegalArgumentException("'min' must be a number, got ${min::class.simpleName}.")
    }
    if (max !is Double && max !is Float && max !is Int) {
        throw IllegalArgumentException("'max' must be a number, got ${max::class.simpleName}.")
    }

    if (min >= max) {
        throw IllegalArgumentException("'min' must be less than 'max'.")
    }

