fun maxRepetitions(s1: String, n1: Int, s2: String, n2: Int): Int {
    // If s2 contains characters that are not in s1 at all, the answer is 0
    if (!s1.toSet().containsAll(s2.toSet())) return 0

    val len2 = s2.length
    var indexInS2 = 0
    var countS2 = 0
    val seen = mutableMapOf<Int, Pair<Int, Int>>()
    var block = 0
    while (block < n1) {
        block += 1
        for (ch in s1) {
            if (ch == s2[indexInS2]) {
                indexInS2 += 1
                if (indexInS2 == len2) {
                    indexInS2 = 0
                    countS2 += 1
                }
            }
        }
        if (seen.containsKey(indexInS2)) {
            val (prevBlock, prevCount) = seen[indexInS2]!!
            val loopLen = block - prevBlock
            val loopCount = countS2 - prevCount
            val remainingBlocks = n1 - block
            val loops = remainingBlocks / loopLen
            countS2 += loops * loopCount
            block += loops * loopLen
        } else {
            seen[indexInS2] = Pair(block, countS2)
        }
    }
    return countS2 / n2
};1

fun minimumOperations(arrays: List<List<Int>>): List<Int> {
    val results = mutableListOf<Int>()
    for (a in arrays) {
        val n = a.size
        val cnt = a.groupingBy { it }.eachCount()
        val maxFreq = if (cnt.isEmpty()) 0 else cnt.values.maxOrNull() ?: 0
        val res = maxOf(maxFreq, (n + 1) / 2)
        results.add(res)
    }
    return results
};1

