fun String.digrootPersistence(base: Int = 10): Pair<String, Int> {
    var num = this.toInt(base)
    var persistence = 0
    while (num >= base) {
        num = num.digits(base).sum()
        persistence++
    }
    return Pair(num.toString(base), persistence)
}

fun Int.digits(base: Int): List<Int> {
    val digits = mutableListOf<Int>()
    var num = this
    while (num > 0) {
        digits.add(num % base)
        num /= base
    }
    return digits
}

