fun formatIpAddress(octets: List<Int>): Map<String, Any> {
    // Sanity checks
    if (octets.size != 4) {
        throw IllegalArgumentException("Exactly four octets are required.")
    }
    if (octets.any { it < 0 || it > 255 }) {
        throw IllegalArgumentException("Each octet must be between 0 and 255 inclusive.")
    }

    val ipAddress = octets.joinToString(".") { it.toString() }
    return mapOf("ip" to ipAddress, "sanity" to emptyList<Any>())
};1

 
