fun numDifferentAreas(testCases: List<Pair<Int, List<Int>>>): List<Int> {
    val results = mutableListOf<Int>()
    for ((n, x) in testCases) {
        val diffs = mutableSetOf<Double>()
        for (i in 0 until n) {
            for (j in (i+1) until n) {
                val area = (x[j] - x[i]).toDouble() / 2.0
                if (area != 0.0) {
                    diffs.add(area)
                }
            }
        }
        results.add(diffs.size)
    }
    return results
