fun countIntegerIntersections(t: Int, cases: List<Pair<List<Int>, List<Int>>>): List<Int> {
    val results = mutableListOf<Int>()
    for ((p, q) in cases) {
        val evenP = p.count { it % 2 == 0 }
        val oddP = p.size - evenP
        val evenQ = q.count { it % 2 == 0 }
        val oddQ = q.size - evenQ
        val ans = evenP * evenQ + oddP * oddQ
        results.add(ans)
    }
    return results
};1

 
