fun permute(s: String): List<String> {
    if (s.length <= 1) {
        return listOf(s)
    }
    val result = mutableListOf<String>()
    for (i in s.indices) {
        val currentChar = s[i]
        val rest = s.substring(0, i) + s.substring(i + 1)
        for (p in permute(rest)) {
            result.add(currentChar + p)
        }
    }
    return result
};1

