fun minArrays(n: Int, k: Int, a: List<Int>): Int {
    if (k == 1) {
        if (a.all { it == a[0] }) {
            return 1
        } else {
            return -1
        }
    } else {
        var s = 0
        for (i in 1 until n) {
            if (a[i] > a[i - 1]) {
                s += 1
            }
        }
        if (s == 0) {
            return 1
        } else {
            val m = (s + k - 2) / (k - 1)
            return m
        }
    }
};1

