fun calculate_total_duration(events: List<Pair<String, String>>): Int {
    var totalDuration = 0
    for ((startTime, endTime) in events) {
        val (startHour, startMinute) = startTime.split(":").map { it.toInt() }
        val (endHour, endMinute) = endTime.split(":").map { it.toInt() }
