fun countInversions(arr: List<Int>): Int {
    fun mergeSortAndCount(arr: List<Int>): Pair<List<Int>, Int> {
        if (arr.size <= 1) return Pair(arr, 0)
        val mid = arr.size / 2
        val (left, leftCount) = mergeSortAndCount(arr.subList(0, mid))
        val (right, rightCount) = mergeSortAndCount(arr.subList(mid, arr.size))
        val (merged, splitCount) = mergeAndCount(left, right)
        return Pair(merged, leftCount + rightCount + splitCount)
    }

    fun mergeAndCount(left: List<Int>, right: List<Int>): Pair<List<Int>, Int> {
        val merged = mutableListOf<Int>()
        var i = 0
        var j = 0
        var splitCount = 0
        while (i < left.size && j < right.size) {
            if (left[i] <= right[j]) {
                merged.add(left[i])
                i++
            } else {
                merged.add(right[j])
                splitCount += left.size - i
                j++
            }
        }
        while (i < left.size) {
            merged.add(left[i])
            i++
        }
        while (j < right.size) {
            merged.add(right[j])
            j++
        }
        return Pair(merged, splitCount)
    }

    return mergeSortAndCount(arr).second
};1

