    val weightGains = mutableListOf<Double>()
    for (i in 0 until weight_measurements.size - 1) {
        val (_, weight1) = weight_measurements[i]
        val (_, weight2) = weight_measurements[i + 1]
        val weightGain = weight2 - weight1
        weightGains.add(weightGain)
    }
