fun infix2Postfix(infix: String): String {
    val stack = ArrayDeque<Char>()
    val postFix = StringBuilder()
    val priority = mapOf(
        '^' to 3,
        '*' to 2,
        '/' to 2,
        '%' to 2,
        '+' to 1,
        '-' to 1
    )
    val printWidth = maxOf(infix.length, 7)

    fun pad(s: String, width: Int): String {
        return s.padEnd(width, ' ')
    }

    // Print table header for output
    println(
        listOf(
            "Symbol".padStart(4).padEnd(8),
            pad("Stack", printWidth),
            pad("Postfix", printWidth)
        ).joinToString(" | ")
    )
    println("-".repeat(printWidth * 3 + 7))

    for (x in infix) {
        when {
            x.isLetterOrDigit() -> {
                postFix.append(x)
            }
            x == '(' -> {
                stack.addLast(x)
            }
            x == ')' -> {
                if (stack.isEmpty()) {
                    throw IndexOutOfBoundsException("list index out of range")
                }
                while (stack.last() != '(') {
                    postFix.append(stack.removeLast())
                    if (stack.isEmpty()) {
                        throw IndexOutOfBoundsException("list index out of range")
                    }
                }
                stack.removeLast() // remove '(' from stack
            }
            stack.isEmpty() -> {
                stack.addLast(x)
            }
            else -> {
                while (
                    stack.isNotEmpty() &&
                    stack.last() != '(' &&
                    priority.getOrDefault(x, 0) <= priority.getOrDefault(stack.last(), 0)
                ) {
                    postFix.append(stack.removeLast())
                }
                stack.addLast(x)
            }
        }
        // Output in tabular format
        println(
            listOf(
                x.toString().padStart(4).padEnd(8),
                pad(stack.joinToString(""), printWidth),
                pad(postFix.toString(), printWidth)
            ).joinToString(" | ")
        )
    }

    while (stack.isNotEmpty()) {
        if (stack.last() == '(') {
            throw IllegalArgumentException("invalid expression")
        }
        postFix.append(stack.removeLast())
        // Output in tabular format
        println(
            listOf(
                " ".padStart(4).padEnd(8),
                pad(stack.joinToString(""), printWidth),
                pad(postFix.toString(), printWidth)
            ).joinToString(" | ")
        )
    }

    return postFix.toString()
};1

fun Graph<Cave>.getPossiblePaths(from: Cave, path: List<Cave>, canVisitSmallTwice: Boolean): List<List<Cave>> {
    val pathWithSelf = path + from
    if (from.isEnd) {
        return listOf(pathWithSelf)
    }

    val possibilities = this.adjacencyMap.getOrDefault(from, emptySet())
        .filterNot { it.isStart }
        .filterNot { !canVisitSmallTwice && it.isSmall && path.contains(it) }
    return possibilities.map {
        getPossiblePaths(
            it,
            pathWithSelf,
            canVisitSmallTwice = canVisitSmallTwice && (!it.isSmall || !path.contains(it))
        )
    }.flatten().toSet().toList()
};0

 
typealias DoubleToDouble = (Double) -> Double
 
fun f(x: Double) = x * x * x - 3.0 * x * x + 2.0 * x
 
fun secant(x1: Double, x2: Double, f: DoubleToDouble): Double {
    val e = 1.0e-12
    val limit = 50
    var xa = x1
    var xb = x2
    var fa = f(xa)
    var  i = 0
    while (i++ < limit) {
        var fb = f(xb)
        val d = (xb - xa) / (fb - fa) * fb
        if (Math.abs(d) < e) break
        xa = xb
        fa = fb
        xb -= d
    }
    if (i == limit) {
        println("Function is not converging near (${"%7.4f".format(xa)}, ${"%7.4f".format(xb)}).")
        return -99.0
    }
    return xb
}
 
fun main(args: Array<String>) {
    val step = 1.0e-2
    val e = 1.0e-12
    var x = -1.032
    var s = f(x) > 0.0
    while (x < 3.0) {
        val value = f(x)
        if (Math.abs(value) < e) {
            println("Root found at x = ${"%12.9f".format(x)}")
            s = f(x + 0.0001) > 0.0
        }
        else if ((value > 0.0) != s) {
            val xx = secant(x - step, x, ::f)
            if (xx != -99.0)
                println("Root found at x = ${"%12.9f".format(xx)}")
            else
                println("Root found near x = ${"%7.4f".format(x)}")
            s = f(x + 0.0001) > 0.0
        }
        x += step
    }
};0

fun gnomeSort(a: Array<Int>) {
    var i = 1
    var j = 2
    val len = a.size
    while (i < len) {
        if (a[i - 1] <= a[i]) {
            // for descending sort, use >= for comparison
            i = j
            j++
        } else {
            val temp = a[i - 1]
            a[i - 1] = a[i]
            a[i] = temp
            i--
            if (i == 0) {
                i = j
                j++
            }
        }
    }
}
 
