fun TreeNode.joinToString(separator: String = ", ", prefix: String = "", postfix: String = "", traversal: Traversal = Traversal.PRE_ORDER): String {
    val builder = StringBuilder()

    builder.append(prefix)

    when (traversal) {
        Traversal.PRE_ORDER -> {
            preOrderTraversal(this, builder, separator)
        }
        Traversal.IN_ORDER -> {
            inOrderTraversal(this, builder, separator)
        }
        Traversal.POST_ORDER -> {
            postOrderTraversal(this, builder, separator)
        }
        Traversal.LEVEL_ORDER -> {
            for (i in 1..this.height()) {
                levelOrderTraversal(this, i, builder, separator)
            }
        }
    }

    builder.setLength(builder.length - separator.length)

    builder.append(postfix)

    return builder.toString()
};0

fun ErisMaze.expandMaze(levelMap: LevelMap, level: Int) =
  keys.filter { it != CENTER }.fold(mutableMapOf<Coordinate, ErisTile>()) { acc, coordinate ->
    val adjacentBugs = coordinate.adjacentCoordinatesRecursive(level)
      .map { (level, coordinate) -> levelMap.getValue(level).getValue(coordinate) }.count { it == BUG }
    acc.also {
      acc[coordinate] = when (getValue(coordinate)) {
        BUG -> when (adjacentBugs) {
          1 -> BUG
          else -> EMPTY
        }
        EMPTY -> when (adjacentBugs) {
          1, 2 -> BUG
          else -> EMPTY
        }
      }
    }
  }.toMap().withDefault { EMPTY };0

fun check(first: String, second: String): Boolean = false != check(parse(first), parse(second), true)

fun check(first: ListNode, second: ListNode, root: Boolean = false): Boolean? {
    while (second.value.isNotEmpty()) {
        val left = first.value.removeFirstOrNull() ?: return true
        val right = second.value.removeFirst()
        if (left is NumericNode && right is NumericNode) {
            if (left.value < right.value) return true
            if (right.value < left.value) return false
        } else {
            val b = check(left.asListNode(), right.asListNode())
            if (b != null) return b
        }
    }
    return if (first.value.isNotEmpty() || root) false else null
};0

