fun pSort(a: IntArray): IntArray {
    val list = ArrayList<IntArray>()
    permute(a, a.size, list)
    for (x in list) {
        if (isSorted(x)) {
            return x
        }
    }
    return a
}
 
fun permute(a: IntArray, n: Int, list: MutableList<IntArray>) {
    if (n == 1) {
        val b = IntArray(a.size)
        System.arraycopy(a, 0, b, 0, a.size)
        list.add(b)
        return
    }
    for (i in 0 until n) {
        swap(a, i, n - 1)
        permute(a, n - 1, list)
        swap(a, i, n - 1)
    }
}
 
fun isSorted(a: IntArray): Boolean {
    for (i in 1 until a.size) {
        if (a[i - 1] > a[i]) {
            return false
        }
    }
    return true
}
 
fun swap(arr: IntArray, i: Int, j: Int) {
    val temp = arr[i]
    arr[i] = arr[j]
    arr[j] = temp
