fun getBadgeStatus(
    selfCompatRes: Map<String, Any?>,
    googleCompatRes: Map<String, Any?>,
    dependencyRes: Map<String, Any?>
): String {
    // Priority map: higher value means higher priority.
    val priority = mapOf(
        "compatible" to 2,
        "unknown" to 1,
        "incompatible" to 0
    )

    fun extractStatuses(src: Any?): List<String> {
        if (src !is Map<*, *>) return emptyList()
        val statuses = mutableListOf<String>()
        if ("status" in src && src["status"] is String) {
            statuses.add(src["status"] as String)
        }
        for ((_, v) in src) {
            if (v is Map<*, *> && v["status"] is String) {
                statuses.add(v["status"] as String)
            }
        }
        return statuses
    }

    val allStatuses = extractStatuses(selfCompatRes) +
            extractStatuses(googleCompatRes) +
            extractStatuses(dependencyRes)

    if (allStatuses.isEmpty()) return "unknown"

    return allStatuses.maxByOrNull { priority[it] ?: -1 } ?: "unknown"
};1

