class INW(val wheels: LinkedHashMap<String, List<Any>>) : Iterator<Int> {
    private val isect = wheels.mapValues { (_, wheel) ->
        wheel.map {
            if (it is String) {
                isect[it]!!
            } else {
                it
            }
        }.iterator()
    }
    private val base_wheel_name = isect.keys.iterator().next()
    private val base_wheel = isect[base_wheel_name]!!
    private var base_wheel_pos = 0
    private val ln = base_wheel.size
 
    fun hasNext(): Boolean = true
    fun next(): Int {
        val nxt = base_wheel[base_wheel_pos % ln]
        base_wheel_pos++
        return if (nxt is Int) {
            nxt
        } else {
            next()
        }
    }
 
    fun toString(): String {
        return "Intersecting Number Wheel group:\n" +
                wheels.map { (name, wheel) ->
                    "  $name:" + wheel.joinToString(" ")
                }.joinToString("\n")
    }
 
    fun first(n: Int): String {
        return IntStream.range(0, n).mapToObj { next() }.collect(Collectors.joining(" "))
    }
}
 
