fun calculateTaxLiability(income: Double, brackets: List<Pair<Double, Double>>): Double {
    var totalTax = 0.0
    var lowerLimit = 0.0
    for ((upperLimit, rate) in brackets) {
        val taxable = if (income > upperLimit) {
            upperLimit - lowerLimit
        } else {
            (income - lowerLimit).coerceAtLeast(0.0)
        }
        totalTax += taxable * rate
        lowerLimit = upperLimit
        if (income <= upperLimit) {
            break
        }
    }
    return totalTax
};1

