import kotlin.math.max
import kotlin.math.min
 
data class Range(val low: Double, val high: Double)
 
fun normalizeRange(range: Range): Range {
    return if (range.high < range.low) {
        Range(range.high, range.low)
    } else {
        range
    }
}
 
fun rangeCompare(r1: Range, r2: Range): Int {
    return when {
        r1.low < r2.low -> -1
        r1.low > r2.low -> 1
        r1.high < r2.high -> -1
        r1.high > r2.high -> 1
        else -> 0
    }
}
 
fun normalizeRanges(ranges: Array<Range>) {
    for (i in ranges.indices) {
        ranges[i] = normalizeRange(ranges[i])
    }
    ranges.sortWith(Comparator { r1, r2 -> rangeCompare(r1, r2) })
}
 
fun consolidateRanges(ranges: Array<Range>): Array<Range> {
    normalizeRanges(ranges)
    val out = mutableListOf<Range>()
    for (i in ranges.indices) {
        var j = i
        while (j < ranges.size && ranges[j].low <= ranges[i].high) {
            if (ranges[i].high < ranges[j].high) {
                ranges[i] = Range(ranges[i].low, ranges[j].high)
            }
            j++
        }
        out.add(ranges[i])
        i = j
    }
    return out.toTypedArray()
}
 
