fun wiseMenPermutationCounts(n: Int, adjacency: List<List<Int>>): List<Int> {
    val size = 1 shl n
    val dp = Array(size) { mutableMapOf<Pair<Int, Int>, Long>() }
    for (i in 0 until n) {
        val mask = 1 shl i
        dp[mask][Pair(i, 0)] = 1L
    }
    for (mask in 0 until size) {
        val current = dp[mask]
        if (current.isEmpty()) continue
        val m = Integer.bitCount(mask)
        if (m >= n) continue
        val items = current.entries.toList()
        for ((key, cnt) in items) {
            val (last_i, sVal) = key
            for (newElem in 0 until n) {
                if ((mask and (1 shl newElem)) == 0) {
                    val bit = adjacency[last_i][newElem]
                    val newS = (sVal shl 1) or bit
                    val newMask = mask or (1 shl newElem)
                    val k = Pair(newElem, newS)
                    dp[newMask][k] = dp[newMask].getOrDefault(k, 0L) + cnt
                }
            }
        }
    }
    val fullMask = (1 shl n) - 1
    val result = LongArray(1 shl (n - 1))
    for ((key, cnt) in dp[fullMask]) {
        val s = key.second
        result[s] += cnt
    }
    return result.map { it.toInt() }
};1

