fun nearestNeighbor(cities: List<Pair<Double, Double>>): List<Pair<Double, Double>> {
    val n = cities.size
    if (n == 0) return listOf()
    if (n == 1) return cities.toList()

    fun dist(a: Pair<Double, Double>, b: Pair<Double, Double>): Double {
        val dx = a.first - b.first
        val dy = a.second - b.second
        return Math.hypot(dx, dy)
    }

    val unvisited = mutableSetOf<Int>()
    for (i in 1 until n) {
        unvisited.add(i)
    }
    val pathIndices = mutableListOf(0)

    while (unvisited.isNotEmpty()) {
        val currentIdx = pathIndices.last()
        val currentCity = cities[currentIdx]
        val nearestIdx = unvisited.minWithOrNull(compareBy<{Int},{Double},{Int}>({ idx -> dist(currentCity, cities[idx]) }, { idx -> idx }))
        if (nearestIdx != null) {
            pathIndices.add(nearestIdx)
            unvisited.remove(nearestIdx)
        }
    }
    return pathIndices.map { cities[it] }
};1

fun stringToMd5(text: String): String? {
    /*
    Compute the MD5 hash of a non-empty string.

    Parameters
    ----------
    text : String
        Input string that will be hashed.

    Returns
    -------
    String?
        A 32-character hexadecimal representation of the MD5 digest,
        or null if the input string is empty.
    */
    if (text.isEmpty()) {
        return null
    }
    val md = MessageDigest.getInstance("MD5")
    val digest = md.digest(text.toByteArray(Charsets.UTF_8))
    return digest.joinToString("") { "%02x".format(it) }
};1

fun combinations(
    record: String,
    groups: List<Int>,
    cache: MutableMap<Pair<String, List<Int>>, Long> = HashMap(),
): Long {
    if (groups.isEmpty()) return if ("#" in record) 0 else 1
    if (record.isEmpty()) return 0

    return cache.getOrPut(record to groups) {
        var result = 0L
        if (record.first() in ".?") {
            result += combinations(record = record.drop(1), groups = groups, cache = cache)
        }
        if (record.first() in "#?" && record.length >= groups.first() && "." !in record.take(groups.first()) && record.getOrNull(groups.first()) != '#') {
            result += combinations(record = record.drop(groups.first() + 1), groups = groups.drop(1), cache = cache)
        }
        result
    }
};0

import kotlin.math.exp
import kotlin.math.pow
import kotlin.math.sqrt
import kotlin.math.PI
 
// Calculate the coefficients used by Spouge's approximation (based on the C
// implemetation)
fun calculateCoefficients(numCoeff: Int): List<Double> {
    val c = MutableList(numCoeff) { 0.0 }
    var k1_factrl = 1.0
    c[0] = sqrt(2.0 * PI)
    for (k in 1 until numCoeff) {
        c[k] = exp(numCoeff - k) * (numCoeff - k).toDouble().pow(k - 0.5) / k1_factrl
        k1_factrl *= -(k).toDouble()
    }
    return c
}
 
// The Spouge approximation
fun gamma(coeffs: List<Double>, x: Double): Double {
    val numCoeff = coeffs.size
    var accm = coeffs[0]
    for (k in 1 until numCoeff) {
        accm += coeffs[k] / (x + k)
    }
    accm *= exp(-(x + numCoeff)) * (x + numCoeff).toDouble().pow(x + 0.5)
    return accm / x
}
 
fun main() {
    // estimate the gamma function with 1, 4, and 10 coefficients
    val coeff1 = calculateCoefficients(1)
    val coeff4 = calculateCoefficients(4)
    val coeff10 = calculateCoefficients(10)
 
    val inputs = listOf(
        0.001, 0.01, 0.1, 0.5, 1.0,
        1.461632145, // minimum of the gamma function
        2.0, 2.5, 3.0, 4.0, 5.0, 6.0, 7.0, 8.0, 9.0, 10.0, 50.0, 100.0,
        150.0 // causes overflow for this implemetation
    )
 
    println("%16s%16s%16s%16s%16s".format("gamma( x ) =", "Spouge 1", "Spouge 4", "Spouge 10", "built-in"))
    for (x in inputs) {
        println("gamma(%7.3f) = %16.10g %16.10g %16.10g %16.10g".format(
            x,
            gamma(coeff1, x),
            gamma(coeff4, x),
            gamma(coeff10, x),
            x.toBigDecimal().toBigIntegerExact().toBigDecimal().gamma() // built-in gamma function
        ))
    }
};1

