fun checkSubset(arr1: List<Int>, arr2: List<Int>): Boolean {
    // Function to deduplicate and sort
    fun dedupSort(arr: List<Int>): List<Int> {
        if (arr.isEmpty()) return emptyList()
        val sortedArr = arr.sorted()
        val res = mutableListOf<Int>()
        res.add(sortedArr[0])
        for (num in sortedArr.drop(1)) {
            if (num != res.last()) {
                res.add(num)
            }
        }
        return res
    }

    val a = dedupSort(arr1)
    val b = dedupSort(arr2)

    // Function to check if a is subset of b using binary search
    fun isSub(aSub: List<Int>, bSup: List<Int>): Boolean {
        for (num in aSub) {
            var left = 0
            var right = bSup.size - 1
            var found = false
            while (left <= right) {
                val mid = (left + right) / 2
                if (bSup[mid] == num) {
                    found = true
                    break
                } else if (bSup[mid] < num) {
                    left = mid + 1
                } else {
                    right = mid - 1
                }
            }
            if (!found) return false
        }
        return true
    }

    return isSub(a, b) || isSub(b, a)
};1

