fun countAbcSubsequences(s: String): Int {
    val MOD = 1000000007L
    var a = 0L
    var ab = 0L
    var abc = 0L
    var cnt = 1L
    for (c in s) {
        val (newA, newAB, newABC, newCnt) = when (c) {
            'a' -> arrayOf((a + cnt) % MOD, ab % MOD, abc % MOD, cnt)
            'b' -> arrayOf(a % MOD, (ab + a) % MOD, abc % MOD, cnt)
            'c' -> arrayOf(a % MOD, ab % MOD, (abc + ab) % MOD, cnt)
            else -> arrayOf((a * 3 + cnt) % MOD, (ab * 3 + a) % MOD, (abc * 3 + ab) % MOD, (cnt * 3) % MOD)
        }
        a = newA
        ab = newAB
        abc = newABC
        cnt = newCnt
    }
    return (abc % MOD).toInt()
};1

