fun maxRainwaterTrapped(heights: List<Int>): Int {
    val n = heights.size
    if (n < 3) {
        return 0 // Mindestens drei Gebäude nötig um Wasser zu fangen
    }

    var left = 0
    var right = n - 1
    var leftMax = heights[0]
    var rightMax = heights[n - 1]
    var trapped = 0

    while (left < right) {
        if (leftMax <= rightMax) {
            left++
            leftMax = maxOf(leftMax, heights[left])
            trapped += (leftMax - heights[left])
        } else {
            right--
            rightMax = maxOf(rightMax, heights[right])
            trapped += (rightMax - heights[right])
        }
    }
    return trapped
};1

