fun bankOperations(operations: List<Pair<String, Int>>): Int {
    // Simulate a series of banking operations (deposits and withdrawals).
    // Args:
    //   operations: A list of pairs where each pair contains:
    //     - A string ('deposit' or 'withdraw')
    //     - An integer amount
    // Returns:
    //   The final account balance after processing all operations.
    //   Withdrawals that would result in a negative balance are ignored.

    var balance = 0

    for ((action, amount) in operations) {
        if (action == "deposit") {
            balance += amount
        } else if (action == "withdraw") {
            // Only allow the withdrawal if it won't overdraw the account
            if (balance - amount >= 0) {
                balance -= amount
            }
        }
    }

    return balance
};1

