import java.math.BigInteger
import java.util.concurrent.TimeUnit
 
fun basicHamming(n: Int): BigInteger {
    val two = BigInteger.valueOf(2)
    val three = BigInteger.valueOf(3)
    val five = BigInteger.valueOf(5)
    val h = Array(n) { BigInteger.ZERO }
    h[0] = BigInteger.ONE
    var x2 = BigInteger.valueOf(2)
    var x3 = BigInteger.valueOf(3)
    var x5 = BigInteger.valueOf(5)
    var i = 0
    var j = 0
    var k = 0
 
    // BigUint comparisons are expensive, so do it only as necessary...
    fun min3(x: BigInteger, y: BigInteger, z: BigInteger): Pair<Int, BigInteger> {
        val (cs, r1) = if (y == z) 0x6 to y else if (y < z) 2 to y else 4 to z
        return if (x == r1) cs or 1 to x else if (x < r1) 1 to x else cs to r1
    }
 
    var c = 1
    while (c < n) { // satisfy borrow checker with extra blocks: {  }
        val (cs, e1) = min3(x2, x3, x5)
        h[c] = e1 // vector now owns the generated value
        if ((cs and 1)!= 0) { i += 1; x2 = two * h[i] }
        if ((cs and 2)!= 0) { j += 1; x3 = three * h[j] }
        if ((cs and 4)!= 0) { k += 1; x5 = five * h[k] }
        c += 1
    }
 
    return h[n - 1]
}
 
fun main(args: Array<String>) {
    print("[")
    for (i in 1..20) {
        if (i > 1) print(",")
        print(" ${basicHamming(i)}")
    }
    println(" ]")
    println(basicHamming(1691))
 
    val strt = System.nanoTime()
 
    val rslt = basicHamming(1000000)
 
    val elpsd = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - strt)
 
    val rs = rslt.toString()
    var s = rs
    println("${s.length} digits:")
    while (s.length > 100) {
        val (f, r) = s.splitAt(100)
        s = r
        println(f)
    }
    println(s)
 
    println("This last took $elpsd milliseconds")
};1

fun firstOccurrenceFibMod(f: Int): Int {
    val m = 1013
    if (f == 0) return 0
    if (f == 1) return 1
    var a = 1
    var b = 1
    var index = 2
    while (true) {
        val nextTerm = (a + b) % m
        index += 1
        if (nextTerm == f) {
            return index
        }
        // If we reach the beginning of a possible Pisano period: (b, nextTerm) == (0, 1)
        if (b == 0 && nextTerm == 1) {
            break
        }
        a = b
        b = nextTerm
    }
    return -1
};1

 
