//Evidence of the Monty Hall solution.
 
import kotlin.random.Random
 
const val GAMES = 3000000
 
fun main() {
    var winsbyswitch = 0
    val door = IntArray(3)
 
    for (i in 0 until GAMES) {
        door[0] = if (Random.nextBoolean()) 1 else 0 //give door 1 either a car or a goat randomly.
        if (door[0] == 1) {
            door[1] = 0
            door[2] = 0
        } else {
            door[1] = if (Random.nextBoolean()) 1 else 0
            door[2] = if (door[1] == 1) 0 else 1
        }
        val choice = Random.nextInt(3) //choose a random door.
 
        //if the next door has a goat, and the following door has a car, or vice versa, you'd win if you switch.
        if ((door[(choice + 1) % 3] == 0 && door[(choice + 2) % 3] == 1) || (door[(choice + 2) % 3] == 0 && door[(choice + 1) % 3] == 1)) winsbyswitch++
    }
    println("\nAfter $GAMES games, I won $winsbyswitch by switching.  That is ${winsbyswitch * 100.0 / i}%%. ")
};1

