fun maxProfit(prices: List<Int>): Int {
    // Randfälle: leere Liste oder nur ein Preis -> keine Transaktion möglich
    if (prices.isEmpty() || prices.size < 2) {
        return 0
    }

    var minPriceSoFar = prices[0] // Bisher niedrigster Kaufpreis
    var maxProfit = 0             // Bisher höchster Gewinn

    // Die Liste durchlaufen und minPriceSoFar und maxProfit aktualisieren
    for (i in 1 until prices.size) {
        val price = prices[i]
        // Möglicher Gewinn, wenn wir heute verkaufen
        val potentialProfit = price - minPriceSoFar
        // Maximalen Gewinn aktualisieren
        if (potentialProfit > maxProfit) {
            maxProfit = potentialProfit
        }
        // Bisher niedrigsten Kaufpreis aktualisieren
        if (price < minPriceSoFar) {
            minPriceSoFar = price
        }
    }
    return maxProfit
};1

fun evaluateNarrowRanges(
    pitches: List<Int>,
    minSize: Int,
    penalties: Map<Int, Double>? = null
): Double {
    val effectivePenalties = if (penalties == null || penalties.isEmpty()) {
        mapOf(2 to 1.0, 3 to 0.5)
    } else {
        penalties
    }
    val sortedWidths = effectivePenalties.keys.sorted()

    fun widthToPenalty(width: Int): Double {
        for (w in sortedWidths) {
            if (width <= w) {
                return effectivePenalties[w] ?: 0.0
            }
        }
        return 0.0
    }

    val maxNarrowWidth = sortedWidths.last()
    val n = pitches.size
    var totalPenalty = 0.0
    var i = 0
    while (i < n) {
        var minPitch = pitches.getOrNull(i) ?: break
        var maxPitch = pitches.getOrNull(i) ?: break
        var j = i
        while (j + 1 < n) {
            val nxt = pitches[j + 1]
            minPitch = minOf(minPitch, nxt)
            maxPitch = maxOf(maxPitch, nxt)
            if (maxPitch - minPitch > maxNarrowWidth) {
                break
            }
            j += 1
        }
        val windowLen = j - i + 1
        if (windowLen >= minSize) {
            val width = maxPitch - minPitch
            val penalty = widthToPenalty(width)
            totalPenalty += penalty
            i = j + 1 // skip overlapping
        } else {
            i += 1
        }
    }
    return totalPenalty
};1

