fun consonantShift(s: String): String {
    /*
    Replace every consonant in the input string with the next consonant
    in alphabetical order (wrapping z → b). Vowels (a, e, i, o, u) and
    non-alphabetic characters are left unchanged. Case is preserved.

    Examples
    --------
    consonantShift("abcde") == "acdfe"
    consonantShift("Hello, World!") == "Jemmo, Xosmf!"
    consonantShift("Zzz") == "Bbb"
    */
    val vowels = setOf('a', 'e', 'i', 'o', 'u')
    // Ordered list of consonants
    val consonants = ('a'..'z').filter { it !in vowels }

    // Build a mapping: consonant -> next consonant (casing lowercase)
    val shiftMap = mutableMapOf<Char, Char>()
    val n = consonants.size
    for ((idx, c) in consonants.withIndex()) {
        val nextC = consonants[(idx + 1) % n]
        shiftMap[c] = nextC
        shiftMap[c.uppercaseChar()] = nextC.uppercaseChar()
    }
    // Construct the shifted string
    val resultChars = StringBuilder()
    for (ch in s) {
        resultChars.append(shiftMap.getOrDefault(ch, ch))
    }
    return resultChars.toString()
};1

