fun isStraight2(nums: IntArray): Boolean {

    var max = Int.MIN_VALUE
    var min = Int.MAX_VALUE
    var zeroCount = 0
    for (i in nums) {
        if (i == 0) {
            zeroCount++
        }else{
            if (i == max || i == min) {
                return false
            }
            if (i > max) {
                max = i
            }
            if (i < min) {
                min = i
            }
        }
    }
    return max - min < 5
};0

fun solve(n: Long, p: Int, dir: Boolean): Boolean {
    if (p < 0) return true
    if (n <= p || n >= 1L shl (p + 1)) return false
    val order = if (dir) 0..p else p downTo 0
    when {
        solve(n - (1L shl p), p - 1, !dir) -> order
        solve(n - 1, p - 1, dir) -> order.last..order.last
        else -> return false
    }.forEach { println("${p + 1} ${it + 1}") }
    return true
};0

fun categorizeTodo(todoList: List<String>): Map<String, Int> {
    val categories = listOf(
        "Integration",
        "Functions",
        "Manifest",
        "Constants",
        "Locale",
        "Optimization",
        "CLI",
        "Update",
        "Documentation"
    )
    val counts = mutableMapOf<String, Int>()
    for (cat in categories) {
        counts[cat] = 0
    }
    val canonicalLookup = categories.associateBy { it.lowercase() }
    val pattern = Pattern.compile("#\\s*todo: \\s*(.*)", Pattern.CASE_INSENSITIVE)
    for (item in todoList) {
        val matcher = pattern.matcher(item)
        if (!matcher.find()) continue
        val remainder = matcher.group(1).trim()
        val leading = remainder.takeWhile { it.isLetter() }
        if (leading.isEmpty()) continue
        val catLower = leading.lowercase()
        canonicalLookup[catLower]?.let { canonicalName ->
            counts[canonicalName] = counts.getValue(canonicalName) + 1
        }
    }
    return counts
};1

fun hasPairWithSum(numbers: List<Int>, target: Int): Boolean {
    // Check for duplicates
    if (numbers.size != numbers.toSet().size) {
        return false
    }
    val seen = mutableSetOf<Int>()
    for (num in numbers) {
        val complement = target - num
        if (seen.contains(complement)) {
            // Disallow using the same negative number twice
            if (complement < 0 && num < 0) {
                continue
            }
            return true
        }
        seen.add(num)
    }
    return false
};1

