fun generatePassphrase(length: Int): String {
    /*
    Generate a random passphrase of a given length that contains at least:
      • one alphabet character (upper- or lowercase)
      • one digit
      • one special symbol (any of !"#$%&'()*+,-./:;<=>?@[\]^_`{|}~)
      • one whitespace character (a space)
    Throws IllegalArgumentException if length < 4.
     */
    if (length < 4) {
        throw IllegalArgumentException("length must be at least 4 to satisfy all character requirements.")
    }

    val letters = (('a'..'z') + ('A'..'Z')).joinToString("")
    val digits = ('0'..'9').joinToString("")
    val specials = "!\"#${'$'}%&'()*+,-./:;<=>?@[\\]^_`{|}~"
    val whitespace = " "

    val rng = java.security.SecureRandom()

    val passChars = mutableListOf<Char>(
        letters[rng.nextInt(letters.length)],
        digits[rng.nextInt(digits.length)],
        specials[rng.nextInt(specials.length)],
        whitespace[0]
    )

    val allChars = letters + digits + specials + whitespace

    for (i in 0 until (length - 4)) {
        passChars.add(allChars[rng.nextInt(allChars.length)])
    }

    passChars.shuffle(rng)
    return passChars.joinToString("")
};1

 
import kotlin.math.*
 
typealias Function = (Double) -> Double
 
/**
 * Integrates input function K over time
 * S + (t1 - t0) * (K(t1) + K(t0)) / 2
 */
class Integrator {
    private val start: Long
    private @Volatile var running = false
    private lateinit var func: Function
    private var t0 = 0.0
    private var v0 = 0.0
    private var sum = 0.0
 
    constructor(func: Function) {
        start = System.nanoTime()
        setFunc(func)
        Thread(this::integrate).start()
    }
 
    fun setFunc(func: Function) {
        this.func = func
        v0 = func(0.0)
        t0 = 0.0
    }
 
    fun getOutput() = sum
 
    fun stop() {
        running = false
    }
 
    fun integrate() {
        running = true
        while (running) {
            try {
                Thread.sleep(1)
                update()
            }
            catch(e: InterruptedException) {
                return
            }
        }
    }
 
    fun update() {
        val t1 = (System.nanoTime() - start) / 1.0e9
        val v1 = func(t1)
        val rect = (t1 - t0) * (v0 + v1) / 2.0
        sum  += rect
        t0 = t1
        v0 = v1
    }
}
 
fun main(args: Array<String>) {
    val integrator = Integrator( { sin(PI * it) } )
    Thread.sleep(2000)
 
    integrator.setFunc( { 0.0 } )
    Thread.sleep(500)
 
    integrator.stop()
    println(integrator.getOutput())
};0

