fun firstNPrimes(n: Int): List<Int> {
    // Return the first `n` prime numbers.
    // If n <= 0, return empty list.
    if (n <= 0) return emptyList()
    val primes = mutableListOf<Int>()
    var candidate = 2
    while (primes.size < n) {
        var isPrime = true
        for (p in primes) {
            if (p * p > candidate) break
            if (candidate % p == 0) {
                isPrime = false
                break
            }
        }
        if (isPrime) {
            primes.add(candidate)
        }
        candidate += 1
    }
    return primes
};1

/**
 * 1987. Number of Unique Good Subsequences
 * @see <a href="https://leetcode.com/problems/number-of-unique-good-subsequences/">Source</a>
 */
fun numberOfUniqueGoodSubsequences(binary: String): Int {
    val mod = E + 7
    var ends0 = 0
    var ends1 = 0
    var has0 = 0
    for (i in binary.indices) {
        if (binary[i] == '1') {
            ends1 = (ends0 + ends1 + 1) % mod
        } else {
            ends0 = (ends0 + ends1) % mod
            has0 = 1
        }
    }
    return (ends0 + ends1 + has0) % mod
};0

fun parseMaze(): Pair<Maze, Portals> {
  val input: Maze = System.`in`.bufferedReader().readLines().map { it.toCharArray() }
  val portals: Portals = mutableMapOf()
  for (y in 2..input.size - 2) {
    if (input[y][2] == ' ') continue
    for (x in 2..input[y].size - 2) {
      when (input[y][x]) {
        '.' -> input.checkPortal(x, y, portals)
      }
    }
  }
  return input to portals
};0

fun hasRepeatedSubstring(s: String): String {
    val n = s.length
    for (length in 1 until n) {
        val seen = mutableSetOf<String>()
        for (i in 0..(n - length)) {
            val substr = s.substring(i, i + length)
            if (seen.contains(substr)) {
                return "YES"
            }
            seen.add(substr)
        }
    }
    return "NO"
