    var p = 3   // first odd prime
    var s: BigInteger
    var m: BigInteger
    while (true) {
        m = bigTwo.shiftLeft(p - 1) - BigInteger.ONE
        s = bigFour
        for (i in 1 .. p - 2) s = (s * s - bigTwo) % m
        if (s == BigInteger.ZERO) {
            count +=1
            print("M$p ")
            if (count == MAX) {
                println()
                break
            }
        }
        // obtain next odd prime
        while(true) {
            p += 2
            if (isPrime(p)) break
        }
    }
};0

class StdDevAccumulator {
    var n: Int = 0
    var sum: Double = 0.0
    var sumofsquares: Double = 0.0

    fun add(num: Double): StdDevAccumulator {
        n += 1
        sum += num
        sumofsquares += num * num
        return this
    }

    fun stddev(): Double {
        return Math.sqrt(sumofsquares / n - sum / n * sum / n)
    }

    fun toString(): String {
        return stddev().toString()
    }
}

fun main(args: Array<String>) {
    val sd = StdDevAccumulator()
    var i = 0
    val numbers = listOf(2.0, 4.0, 4.0, 4.0, 5.0, 5.0, 7.0, 9.0)
    for (n in numbers) {
        println("adding $n: stddev of ${++i} samples is ${sd.add(n)}")
    }
};1

 
import kotlin.math.sqrt
import kotlin.math.PI
 
const val EPSILON = 1.0e-16
const val SMALL_PI = '\u03c0'
const val APPROX_EQUALS = '\u2245'
 
class Complex(val real: Double, val imag: Double) {
    operator fun plus(other: Complex) =
        Complex(real + other.real, imag + other.imag)
 
    operator fun times(other: Complex) = Complex(
        real * other.real - imag * other.imag,
        real * other.imag + imag * other.real
    )
 
    fun inv(): Complex {
        val denom = real * real + imag * imag
        return Complex(real / denom, -imag / denom)
    }
 
    operator fun unaryMinus() = Complex(-real, -imag)
 
    operator fun minus(other: Complex) = this + (-other)
 
    operator fun div(other: Complex) = this * other.inv()
 
    val modulus: Double get() = sqrt(real * real + imag * imag)
 
    fun toString() =
        if (imag >= 0.0) "$real + ${imag}i"
        else "$real - ${-imag}i"
}
 
fun main(args: Array<String>) {
    var fact = 1.0
    val x = Complex(0.0, PI)
    var e = Complex(1.0, PI)
    var n = 2
    var pow = x
    do {
        val e0 = e
        fact *= n++
        pow *= x
        e += pow / Complex(fact, 0.0)
    }
    while ((e - e0).modulus >= EPSILON)
    e += Complex(1.0, 0.0)
    println("e^${SMALL_PI}i + 1 = $e $APPROX_EQUALS 0")
};0

