fun getDbVersion(versionStr: String): Int {
    if (versionStr !is String) {
        throw IllegalArgumentException("Input must be a string.")
    }

    val trimmed = versionStr.trim()
    val pattern = Pattern.compile("Version:\s*(-?\\d+)")
    val matcher = pattern.matcher(trimmed)
    if (!matcher.matches()) {
        throw IllegalArgumentException("Invalid version string format: '$versionStr'")
    }
    try {
        return matcher.group(1).toInt()
    } catch (e: Exception) {
        throw IllegalArgumentException("Unable to convert version to int from: '$versionStr'")
    }
};1

