class Array2D(val width: Int, val height: Int) {
    val array2d = Array(height) { Array(width) { 0 } }

    fun resize(width: Int, height: Int) {
        val nheight = height - this.height
        val nwidth = width - this.width
        if (nwidth > 0) {
            for (i in 0..this.height) {
                if (i < height)
                    array2d[i] = array2d[i].copyOf(nwidth)
            }
        } else if (nwidth < 0) {
            for (i in 0..this.height) {
                if (i < height)
                    array2d[i] = array2d[i].copyOfRange(width, nwidth)
            }
        }
        if (nheight > 0) {
            array2d = array2d.copyOf(nheight)
        } else if (nheight < 0) {
            array2d = array2d.copyOfRange(height, nheight)
        }
    }

    fun loop(callback: (Int, Int, Int) -> Unit) {
        for (i in 0..height)
            for (i2 in 0..width)
                callback(array2d[i][i2], i, i2)
    }
}

