fun convertToString(value: Any?): String {
    /*
     * Convert any Kotlin object to its string representation.
     *
     * Parameters
     * ----------
     * value : Any?
     *     The data to be converted into a string.
     *
     * Returns
     * -------
     * String
     *     A string representation of `value`. If calling .toString() raises an
     *     unexpected error, the function falls back to .toString() on Any?. Otherwise,
     *     a safe placeholder string is returned instead.
     */
    return try {
        value.toString()
    } catch (e: Exception) {
        try {
            (value as? Any)?.toString() ?: "<unrepresentable object>"
        } catch (e: Exception) {
            "<unrepresentable object>"
        }
    }
};1

