val s_suits = arrayOf('♣', '♦', '♥', '♠')
val s_nums = arrayOf('A', '2', '3', '4', '5', '6', '7', '8', '9', 'T', 'J', 'Q', 'K')
 
val RMAX32 = (1 shl 31) - 1
var seed = 1
fun rnd(): Int {
    return (seed = (seed * 214013 + 2531011) and RMAX32) shr 16
}
 
fun srnd(x: Int) {
    seed = x
}
 
fun show(c: IntArray) {
    var i = 0
    for (i in 0..51) {
        print("  \u001B[${32 - (1 + c[i]) % 4 / 2}m${s_suits[c[i] % 4]}${s_nums[c[i] / 4]}")
        if (i % 8 == 7 || i == 51) println()
    }
}
 
fun deal(s: Int, t: IntArray) {
    var i = 0
    var j = 0
    srnd(s)
    for (i in 0..51) t[i] = 51 - i
    for (i in 0..50) {
        j = 51 - rnd() % (52 - i)
        val s = t[i]
        t[i] = t[j]
        t[j] = s
    }
}
 
