fun count_altars(N: Int, A: List<Int>, B: List<Int>, C: List<Int>): Long {
    val A_sorted = A.sorted()
    val C_sorted = C.sorted()
    var total = 0L
    for (b in B) {
        val a_less = A_sorted.binarySearch(b).let { idx ->
            if (idx < 0) -idx - 1 else idx
        }
        val c_greater = N - (C_sorted.binarySearch(b).let { idx ->
            if (idx < 0) -idx - 1 else idx + 1
        })
        total += a_less.toLong() * c_greater.toLong()
    }
    return total
};1

