    sums[0] = 1
    sums[1] = 0
    var s: Int
    for (n in 1 .. 8)
        for (i in n * 81 downTo 1)
            for (j in 1 .. 9) {
                s = j * j
                if (s > i) break
                sums[i] += sums[i - s]
            }
    var count89 = 0
    for (i in 1 .. 8 * 81)
        if (endsWith89(i)) count89 += sums[i]
    println("There are $count89 numbers from 1 to 100 million ending with 89")
};0

fun nthroot(n: Int, A: Double, precision: Int): Double {
    val n = n.toBigDecimal()
    val x0 = A / n //step 1: make a while guess.
    var x1 = 1.0 //need it to exist before step 2
    while (true) {
        //step 2:
        x0 = x1
        x1 = (1 / n) * ((n - 1) * x0 + (A / (x0.pow(n - 1))))
        if (x0 == x1) {
            return x1
        }
    }
};1

fun sortDisjoint(valsBegin: IntArray, indicesBegin: IntArray, indicesEnd: IntArray) {
    val temp = ArrayList<Int>()
 
    for (i in indicesBegin.indices)
        temp.add(valsBegin[indicesBegin[i]]) // extract
 
    indicesBegin.sort() // sort
    temp.sort() // sort a C++ container
 
    var j = 0
    for (i in indicesBegin.indices) {
        valsBegin[indicesBegin[i]] = temp[j] // replace
        j++
    }
}
 
 
