fun flattenDict(d: Map<String, Any?>): Map<String, Any?> {
    /*
    Flattens a (potentially) nested dictionary so that the resulting dictionary
    contains no nested structures. Keys of the flattened dictionary represent
    the access path to each leaf value in the original dictionary, joined by
    a dot ('.').
    */

    fun walk(subdict: Map<String, Any?>, prefix: String, out: MutableMap<String, Any?>) {
        for ((key, value) in subdict) {
            val newKey = if (prefix.isNotEmpty()) "$prefix.$key" else key
            if (value is Map<*, *>) {
                @Suppress("UNCHECKED_CAST")
                val m = value as Map<String, Any?>
                if (m.isNotEmpty()) {
                    walk(m, newKey, out)
                } else {
                    out[newKey] = mapOf<String, Any?>()
                }
            } else {
                out[newKey] = value
            }
        }
    }

    val result = mutableMapOf<String, Any?>()
    walk(d, "", result)
    return result
};1

fun getSubsets(inputSet: Set<Int>): List<List<Int>> {
    val elements = inputSet.toList().sorted()
    if (elements.isEmpty()) {
        return listOf(listOf())
    }
    val first = elements[0]
    val rest = elements.drop(1)
    val subsetsRest = getSubsets(rest.toSet())
    return subsetsRest + subsetsRest.map { listOf(first) + it }
};1

