fun findSecondLargestUnique(arr: List<Int>): Int? {
    val unique = mutableListOf<Int>()
    for (num in arr) {
        if (!unique.contains(num)) {
            unique.add(num)
        }
    }
    if (unique.size < 2) {
        return null
    }
    var first = Int.MIN_VALUE
    var second = Int.MIN_VALUE
    for (num in unique) {
        if (num > first) {
            second = first
            first = num
        } else if (num > second && num != first) {
            second = num
        }
    }
    if (second == Int.MIN_VALUE) {
        return null
    }
    return second
};1

