fun bankAccountFinalBalance(
    initialBalance: Int,
    minimumBalance: Int,
    transactions: List<Pair<String, Int>>
): Int {
    /*
    Simulate a simple bank account.

    Parameters
    ----------
    initialBalance : Int
        The starting balance of the account.
    minimumBalance : Int
        The minimum allowed balance. Withdrawals that would bring the
        balance below this threshold are ignored.
    transactions : List<Pair<String, Int>>
        A list of pairs of the form ("deposit" | "withdraw", amount).

    Returns
    -------
    Int
        The balance after processing all transactions.
    */

    var balance = initialBalance

    for ((action, amount) in transactions) {
        when (action) {
            "deposit" -> balance += amount
            "withdraw" -> {
                // Check if withdrawal keeps balance >= minimumBalance
                if (balance - amount >= minimumBalance) {
                    balance -= amount
                }
            }
            else -> {
                // Ignore invalid actions (optional; could throw an error instead)
                continue
            }
        }
    }

    return balance
};1

fun PuzzleSet.day19() = puzzle(day = 19) {
    val (rulesPart, messagesPart) = input.split("\n\n")
    fun parseRule(rest: String) = when {
        rest.startsWith("\"") -> CharRule(rest.removeSurrounding("\"").single())
        else -> rest.split(" | ").map { CompoundRule(it.split(" ").map(String::toInt)) }
            .let { it.singleOrNull() ?: OrRule(it) }
    }

    val initialRules = rulesPart.lines().associate { l ->
        val (numPart, rest) = l.split(": ")
        numPart.toInt() to parseRule(rest)
