/**
 * Build the final structure of shards.
 */
fun List<List<Chunk>>.mapToShards(): List<List<Shard.App>> {

    // Structure the group of chunks mapping them by app and test.
    val list: List<Map<String, Map<String, List<Chunk>>>> = map { group ->
        group.groupBy { chunk ->
            chunk.app
        }.mapValues { (_, chunks) ->
            chunks.groupBy { chunk ->
                chunk.test
            }
        }
    }

    // Convert grouped chunks into the output structures.
    return list.map { map ->
        map.map { (app, tests) ->
            Shard.App(
                name = app,
                tests = tests.map { (test, chunks) ->
                    Shard.Test(
                        name = test,
                        cases = chunks.map { chunk ->
                            Shard.Test.Case(
                                name = chunk.case,
                                duration = chunk.duration
                            )
                        }
                    )
                }
            )
        }
    }
};0

 
fun filter(a: DoubleArray, b: DoubleArray, signal: DoubleArray): DoubleArray {
    val result = DoubleArray(signal.size)
    for (i in 0 until signal.size) {
        var tmp = 0.0
        for (j in 0 until b.size) {
            if (i - j < 0) continue
            tmp += b[j] * signal[i - j]
        }
        for (j in 1 until a.size) {
            if (i - j < 0) continue
            tmp -= a[j] * result[i - j]
        }
        tmp /= a[0]
        result[i] = tmp
    }
    return result
}
 
