fun IntArray.findMid(start: Int = 0, end: Int = lastIndex): Double {
    if (this.isEmpty()) {
        return 0.0
    }
    if (start < 0 || end > lastIndex || start > end) {
        throw IndexOutOfBoundsException()
    }
    val length = end - start + 1
    return if (length % 2 == 1) {
        this[start + length / 2].toDouble()
    } else {
        (this[start + length / 2] + this[end - length / 2]) / 2.0
    }
};0

fun intersperse(numbers: List<Int>, delimiter: Int): List<Int>? {
    // An empty or single-element list is trivially strictly ascending
    if (numbers.size <= 1) {
        return numbers.toList()
    }

    // Validate strict ascending order
    for (i in 0 until numbers.size - 1) {
        if (numbers[i] >= numbers[i + 1]) {
            return null
        }
    }

    // Build the interspersed list
    val interspersed = mutableListOf<Int>()
    for ((index, value) in numbers.withIndex()) {
        interspersed.add(value)
        if (index != numbers.size - 1) {
            interspersed.add(delimiter)
        }
    }

    return interspersed
};1

