import java.util.ArrayList
 
object Heron {
    private val n = 200
 
    fun run() {
        val l = ArrayList<IntArray>()
        for (c in 1..n)
            for (b in 1..c)
                for (a in 1..b)
                    if (gcd(gcd(a, b), c) == 1) {
                        val p = a + b + c
                        val s = p / 2.0
                        val area = Math.sqrt(s * (s - a) * (s - b) * (s - c))
                        if (isHeron(area))
                            l.add(intArrayOf(a, b, c, p, area.toInt()))
                    }
        print("Number of primitive Heronian triangles with sides up to $n: " + l.size)
 
        sort(l)
        print("\n\nFirst ten when ordered by increasing area, then perimeter:" + header)
        for (i in 0 until 10) {
            print(format(l[i]))
        }
        val a = 210
        print("\n\nArea = $a" + header)
        l.filter { it[4] == a }.forEach { print(format(it)) }
    }
 
    fun gcd(a: Int, b: Int): Int {
        var leftover = 1
        var dividend = if (a > b) a else b
        var divisor = if (a > b) b else a
        while (leftover != 0) {
            leftover = dividend % divisor
            if (leftover > 0) {
                dividend = divisor
                divisor = leftover
            }
        }
        return divisor
    }
 
    fun sort(l: MutableList<IntArray>) {
        var swapped = true
        while (swapped) {
            swapped = false
            for (i in 1 until l.size)
                if (l[i][4] < l[i - 1][4] || l[i][4] == l[i - 1][4] && l[i][3] < l[i - 1][3]) {
                    val temp = l[i]
                    l[i] = l[i - 1]
                    l[i - 1] = temp
                    swapped = true
                }
        }
    }
 
    fun isHeron(h: Double) = h.rem(1) == 0.0 && h > 0
 
    private val header = "\nSides           Perimeter   Area"
    fun format(a: IntArray) = "\n%3d x %3d x %3d %5d %10d".format(a[0], a[1], a[2], a[3], a[4])
}
 
fun main(args: Array<String>) = Heron.run();0

 
import kotlin.math.ceil
 
class Complex(val real: Double, val imag: Double) {
 
    constructor(r: Int, i: Int) : this(r.toDouble(), i.toDouble())
 
    operator fun plus(other: Complex) = Complex(real + other.real, imag + other.imag)
 
    operator fun times(other: Complex) = Complex(
        real * other.real - imag * other.imag,
        real * other.imag + imag * other.real
    )
 
    operator fun times(other: Double) = Complex(real * other, imag * other)
 
    fun inv(): Complex {
        val denom = real * real + imag * imag
        return Complex(real / denom, -imag / denom)
    }
 
    operator fun unaryMinus() = Complex(-real, -imag)
 
    operator fun minus(other: Complex) = this + (-other)
 
    operator fun div(other: Complex) = this * other.inv()
 
    // only works properly if 'real' and 'imag' are both integral
    fun toQuaterImaginary(): QuaterImaginary {
        if (real == 0.0 && imag == 0.0) return QuaterImaginary("0")
        var re = real.toInt()
        var im = imag.toInt()
        var fi = -1
        val sb = StringBuilder()
        while (re != 0) {
            var rem = re % -4
            re /= -4
            if (rem < 0) {
                rem = 4 + rem
                re++
            }
            sb.append(rem)
            sb.append(0)
        }
        if (im != 0) {
            var f = (Complex(0.0, imag) / Complex(0.0, 2.0)).real
            im = ceil(f).toInt()
            f = -4.0 * (f - im.toDouble())
            var index = 1
            while (im != 0) {
                var rem = im % -4
                im /= -4
                if (rem < 0) {
                    rem = 4 + rem
                    im++
                }
                if (index < sb.length) {
                    sb[index] = (rem + 48).toChar()
                }
                else {
                    sb.append(0)
                    sb.append(rem)
                }
                index += 2
            }
            fi = f.toInt()
        }
        sb.reverse()
        if (fi != -1) sb.append(".$fi")
        var s = sb.toString().trimStart('0')
        if (s.startsWith(".")) s = "0$s"
        return QuaterImaginary(s)
    }
 
    fun toString(): String {
        val real2 = if (real == -0.0) 0.0 else real  // get rid of negative zero
        val imag2 = if (imag == -0.0) 0.0 else imag  // ditto
        var result = if (imag2 >= 0.0) "$real2 + ${imag2}i" else "$real2 - ${-imag2}i"
        result = result.replace(".0 ", " ").replace(".0i", "i").replace(" + 0i", "")
        if (result.startsWith("0 + ")) result = result.drop(4);0

fun getBit(list: List<String>, position: Int, criteria: Char): Char {
    var count = 0
    list.forEach { //counts how many 1's in the number.
        if (it[position] == '1') {
            count++
        }
    }
    val other = list.size - count //a variable that determines the remaining values (0's).
    return if (criteria == '1') { //most
        if (count >= other) '1'
        else '0'
    } else { //least
        if (count < other) '1'
        else '0'
    }
};0

fun maxProfit(prices: IntArray): Int {
    val maxPossibleSellPrice = Array<Int>(prices.size) { -1 }
    for (index in prices.lastIndex downTo 0) {
        // find the max sell price possible by filling in from the end
        // comparing max price in future and current price
        // for [3, 2, 6, 5, 0, 3] -> [6, 6, 6, 5, 3, 3]
        maxPossibleSellPrice[index] =
            maxOf(maxPossibleSellPrice.getOrNull(index + 1) ?: -1, prices[index])
    }

    var result = 0
    for (index in 0..prices.lastIndex) {
        val sellPrice = maxPossibleSellPrice[index]
        result = maxOf(sellPrice - prices[index], result)
    }
    return result
};0

