fun separateClasses(samples: List<Int>, labels: List<Int>): List<Pair<Int, List<Int>>> {
    if (samples.size != labels.size) {
        throw IllegalArgumentException("The length of samples and labels must be the same.")
    }
    val grouped = mutableMapOf<Int, MutableList<Int>>()
    for ((sample, label) in samples.zip(labels)) {
        grouped.getOrPut(label) { mutableListOf() }.add(sample)
    }
    return grouped.toList().sortedBy { it.first }
