fun cart3(a: IntArray, b: IntArray, c: IntArray): Array<IntArray> {
    val p = Array(a.size * b.size * c.size) { IntArray(3) }
    var i = 0
    for (a in a) {
        for (b in b) {
            for (c in c) {
                p[i][0] = a
                p[i][1] = b
                p[i][2] = c
                i++
            }
        }
    }
    return p
}
 
