fun mostFrequent(arr: List<Int>): Pair<Int?, Int> {
    if (arr.isEmpty()) {
        return Pair(null, 0)
    }

    val freq = arr.groupingBy { it }.eachCount()
    val maxCount = freq.values.maxOrNull() ?: 0
    val candidates = freq.filter { it.value == maxCount }.keys
    val mostFrequentNumber = candidates.minOrNull()!!
    return Pair(mostFrequentNumber, maxCount)
};1

fun maxBeautyColumn(columns: List<Pair<Int, Int>>): Int {
    val sumL = columns.sumOf { it.first }
    val sumR = columns.sumOf { it.second }
    val D = sumL - sumR
    var maxBeauty = kotlin.math.abs(D)
    var bestCol = 0
    for ((i, column) in columns.withIndex()) {
        val (l, r) = column
        val delta = 2 * (r - l)
        val currentBeauty = kotlin.math.abs(D + delta)
        if (currentBeauty > maxBeauty) {
            maxBeauty = currentBeauty
            bestCol = i + 1
        }
    }
    return bestCol
};1

