fun main(args: Array<String>) {
    val LIMIT = 1_000_035
    val primes = primes2(LIMIT)
    val primeset = HashSet(primes)
    val primearray = IntStream.range(0, LIMIT).mapToObj { n -> n in primeset }.collect(Collectors.toList())
    val s = arrayOfNulls<MutableList<IntArray>>(4)
    val unsexy = ArrayList<Int>()
    for (i in 0..3) {
        s[i] = ArrayList()
    }
    for (p in primes) {
        if (p > LIMIT) {
            break
        }
        if (p + 6 in primeset && p + 6 < LIMIT) {
            s[0]!!.add(intArrayOf(p, p + 6))
        } else if (p + 6!in primeset) {
            unsexy.add(p)
            continue
        } else {
            break
        }
        if (p + 12 in primeset && p + 12 < LIMIT) {
            s[1]!!.add(intArrayOf(p, p + 6, p + 12))
        } else {
            continue
        }
        if (p + 18 in primeset && p + 18 < LIMIT) {
            s[2]!!.add(intArrayOf(p, p + 6, p + 12, p + 18))
        } else {
            continue
        }
        if (p + 24 in primeset && p + 24 < LIMIT) {
            s[3]!!.add(intArrayOf(p, p + 6, p + 12, p + 18, p + 24))
        }
    }
    println("SEXY PRIME GROUPINGS:")
    for (i in 0..3) {
        println("  ${s[i]!!.size} ${if (i == 0) "pair" else "triplets"}")
        for (sx in s[i]!!.subList(s[i]!!.size - 5, s[i]!!.size)) {
            println("   " + Arrays.toString(sx))
        }
    }
    println("\nThere are ${unsexy.size} unsexy primes ending with...")
    for (usx in unsexy.subList(unsexy.size - 10, unsexy.size)) {
        println(" $usx")
    }
}
 
fun primes2(limit: Int): List<Int> {
    if (limit < 2) {
        return ArrayList()
    }
    if (limit < 3) {
        return listOf(2)
    }
    val lmtbf = (limit - 3) / 2
    val buf = BooleanArray(lmtbf + 1)
    Arrays.fill(buf, true)
    for (i in 0..((Math.sqrt(limit.toDouble()) - 3) / 2 + 1).toInt()) {
        if (buf[i]) {
            val p = i + i + 3
            var s = p * (i + 1) + i
            while (s <= lmtbf) {
                buf[s] = false
                s += p
            }
        }
    }
    val primes = ArrayList<Int>()
    primes.add(2)
    for (i in 0..lmtbf) {
        if (buf[i]) {
            primes.add(i + i + 3)
        }
    }
    return primes
};1

