fun manageThemeColors(
    initialColors: List<String>,
    operations: List<Pair<String, String?>>
): List<String> {
    // Work on a copy to avoid mutating the original list.
    val colors = initialColors.toMutableList()
    for ((op, color) in operations) {
        when (op) {
            "add" -> {
                if (color != null && !colors.contains(color)) {
                    colors.add(color)
                }
            }
            "remove" -> {
                if (color != null && colors.contains(color)) {
                    colors.remove(color)
                }
            }
            "clear" -> {
                colors.clear()
            }
            // If the operation is unrecognized, ignore it silently.
        }
    }
    return colors
};1

