fun <T : Comparable<T>> median(c: List<T>): Double {
    if (c.isEmpty()) throw RuntimeException("Range cannot be empty")
    val len = c.size
    val m = len / 2
    return if (len % 2 == 1) {
        c[m].toDouble()
    } else {
        (c[m - 1] + c[m]) / 2.0
    }
}
 
fun <T : Comparable<T>> fivenum(c: List<T>): List<Double> {
    val sorted = c.sorted()
    val len = sorted.size
    val m = len / 2
    val lower = if (len % 2 == 1) m else m - 1
    val r2 = median(sorted.subList(0, lower + 1))
    val r3 = median(sorted)
    val r4 = median(sorted.subList(lower + 1, len))
    return listOf(sorted[0].toDouble(), r2, r3, r4, sorted[len - 1].toDouble())
}
 
