fun getGregorianDate(year: Int, dayIndex: Int): Pair<Int, Int> {
    var isLeap = false
    if (year % 400 == 0) {
        isLeap = true
    } else if (year % 100 == 0) {
        isLeap = false
    } else if (year % 4 == 0) {
        isLeap = true
    }
    val months = mutableListOf(31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
    if (isLeap) {
        months[1] = 29
    }
    var remaining = dayIndex
    for (i in months.indices) {
        if (remaining > months[i]) {
            remaining -= months[i]
        } else {
            return Pair(remaining, i + 1)
        }
    }
    throw IllegalArgumentException("Invalid dayIndex for the given year")
};1

fun List<String>.checkMirroredHorizontalWithSmudge(rowsBefore: Int): Boolean {
    var smudge = false
    for (row in rowsBefore..<this.size) {
        val rowMir = rowsBefore * 2 - row - 1
        if (rowMir !in indices) break
        for (col in this[row].indices) {
            if (this[row][col] != this[rowMir][col]) {
                if (!smudge) {
                    smudge = true
                } else {
                    return false
                }
            }
        }

    }
    return smudge
};0

