fun generateParenthesis(n: Int): List<String> {
    val result = mutableListOf<String>()
    fun backtrack(s: String, openCount: Int, closeCount: Int) {
        if (s.length == 2 * n) {
            result.add(s)
            return
        }
        if (openCount < n) {
            backtrack(s + "(", openCount + 1, closeCount)
        }
        if (closeCount < openCount) {
            backtrack(s + ")", openCount, closeCount + 1)
        }
    }
    backtrack("", 0, 0)
    return result
};1

fun factorialWithStack(n: Int): Long {
    if (n < 0) {
        throw IllegalArgumentException("Input must be a non-negative integer.")
    }

    // Simple stack implementation
    class Stack {
        private val data = mutableListOf<Int>()

        fun push(item: Int) {
            data.add(item)
        }

        fun pop(): Int {
            if (data.isEmpty()) {
                throw IndexOutOfBoundsException("Pop from empty stack")
            }
            return data.removeAt(data.size - 1)
        }

        fun size(): Int {
            return data.size
        }
    }

    // Edge case: 0! = 1
    if (n == 0) return 1L

    val stack = Stack()

    // Push numbers n, n-1, ..., 1 onto the stack
    for (number in n downTo 1) {
        stack.push(number)
    }

    var result = 1L
    // Pop items and multiply
    while (stack.size() > 0) {
        result *= stack.pop()
    }

    return result
};1

 
