fun processTimeSeries(
    data: List<Pair<String, Number>>,
    t: Int
): List<Double> {
    // 1. Validate t
    if (t <= 0) {
        throw IllegalArgumentException("t must be a positive integer")
    }

    // 2. Convert timestamps to LocalDateTime and validate
    val formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")
    val parsed: MutableList<Pair<LocalDateTime, Double>> = mutableListOf()
    for ((ts, value) in data) {
        val dt = try {
            LocalDateTime.parse(ts, formatter)
        } catch (e: Exception) {
            throw TypeCastException("timestamps in data must be valid datetime strings")
        }
        parsed.add(dt to value.toDouble())
    }

    // 3. Sort by timestamp ascending
    parsed.sortBy { it.first }
    val values = parsed.map { it.second }

    // 4. Rolling minimum using a monotonic deque (O(n))
    val minima = mutableListOf<Double>()
    val window = ArrayDeque<Pair<Int, Double>>() // (index, value)
    for ((idx, val) in values.withIndex()) {
        while (window.isNotEmpty() && window.first().first <= idx - t) {
            window.removeFirst()
        }
        while (window.isNotEmpty() && window.last().second > val) {
            window.removeLast()
        }
        window.addLast(idx to val)
        minima.add(window.first().second)
    }
    return minima
};1

 
typealias Func<T> = (T) -> T
 
fun cube(n: Int) = n * n * n
 
fun <T> benchmark(n: Int, func: Func<T>, arg: T): LongArray {
    val times = LongArray(n)
    for (i in 0 until n) {
         val m = System.nanoTime()
         func(arg)
         times[i] = System.nanoTime() - m
    }
    return times
}
 
