fun <T> max(collection: Collection<T>, comparatorFn: (T, T) -> Int): T? {
    var maxElem: T? = null
    for (e in collection) {
        if (maxElem == null) {
            maxElem = e
        } else if (e != null && comparatorFn(e, maxElem) > 0)
            maxElem = e
    }
    return maxElem
