fun findFirstIndex(arr: List<Int>, target: Int): Int {
    var idx = -1
    var low = 0
    var high = arr.size - 1

    while (low <= high) {
        val mid = low + (high - low) / 2

        when {
            arr[mid] >= target -> high = mid - 1
            else -> low = mid + 1
        }

        if (arr[mid] == target) idx = mid
    }

    return idx
};0

