fun whoWins(n: Int, s: String, t: String): String {
    val sumTAll = t.sumBy { it.toString().toInt() }
    val values = s.zip(t).map { (sc, tc) -> sc.toString().toInt() + tc.toString().toInt() }.sortedDescending()
    var sumY = 0
    for (i in 0 until 2 * n step 2) {
        sumY += values[i]
    }
    val diff = sumY - sumTAll
    return when {
        diff > 0 -> "First"
        diff < 0 -> "Second"
        else -> "Draw"
    }
};1

