fun maxMoves(N: Int, H: List<Int>): Int {
    if (N <= 1) return 0
    val dp = IntArray(N) {0}
    for (i in N - 2 downTo 0) {
        if (H[i] >= H[i+1]) {
            dp[i] = dp[i+1] + 1
        }
    }
    return dp.maxOrNull() ?: 0
};1

