class FenwickTree(val size: Int) {
    private val n = size
    private val tree = IntArray(n + 2)
    fun update(idxOrg: Int) {
        var idx = idxOrg
        while (idx <= n) {
            tree[idx] += 1
            idx += idx and -idx
        }
    }
    fun query(idx_: Int): Int {
        var res = 0
        var idx = idx_
        if (idx <= 0) return 0
        idx = minOf(idx, n)
        while (idx > 0) {
            res += tree[idx]
            idx -= idx and -idx
        }
        return res
    }
}

fun countMediansLeqX(a: List<Int>, x: Int, N: Int): Int {
    val t = a.map { if (it <= x) 1 else -1 }
    val prefix = mutableListOf(0)
    for (num in t) {
        prefix.add(prefix.last() + num)
    }
    val maxSize = 2 * N + 1
    val evenTree = FenwickTree(maxSize)
    val oddTree = FenwickTree(maxSize)
    var countEven = 0
    var countOdd = 0
    for (j in prefix.indices) {
        val p_j = prefix[j]
        val parity = j % 2
        val targetEven = p_j - 2
        val idxEven = targetEven + N + 1
        val cntE = if (parity == 0) evenTree.query(idxEven) else oddTree.query(idxEven)
        countEven += cntE
        val targetOdd = p_j - 1
        val idxOdd = targetOdd + N + 1
        val cntO = if (parity == 0) oddTree.query(idxOdd) else evenTree.query(idxOdd)
        countOdd += cntO
        val insertIdx = p_j + N + 1
        if (parity == 0) {
            evenTree.update(insertIdx)
        } else {
            oddTree.update(insertIdx)
        }
    }
    return countEven + countOdd
}

fun find_median_of_subsequence_medians(N: Int, a: List<Int>): Int {
    val sortedA = a.toSet().toList().sorted()
    val T = N * (N + 1) / 2
    val k = (T / 2) + 1
    var left = 0
    var right = sortedA.size - 1
    var answer = sortedA.last()
    while (left <= right) {
        val mid = (left + right) / 2
        val x = sortedA[mid]
        val cnt = countMediansLeqX(a, x, N)
        if (cnt >= k) {
            answer = x
            right = mid - 1
        } else {
            left = mid + 1
        }
    }
    return answer
};1

