fun identifyPotentialDiscrepancies(evidenceFiles: List<Map<String, Any>>): List<String> {
    val fileGroups = mutableMapOf<Int, MutableList<Map<String, Any>>>()
    for (file in evidenceFiles) {
        val fileSize = file["filesize"] as Int
        if (!fileGroups.containsKey(fileSize)) {
            fileGroups[fileSize] = mutableListOf()
        }
        fileGroups[fileSize]?.add(file)
    }
    val potentialDiscrepancies = mutableSetOf<String>()
    for (group in fileGroups.values) {
        if (group.size > 1) {
            val modDates = group.map { it["modificationDate"] as String }.toSet()
            if (modDates.size > 1) {
                for (file in group) {
                    potentialDiscrepancies.add(file["filename"] as String)
                }
            }
        }
    }
    return potentialDiscrepancies.toList()
};1

