import java.util.Arrays
 
fun doublyEvenMagicSquare(n: Int): Array<IntArray>? {
    if (n < 4 || n % 4!= 0)
        return null
 
    val bits = 38505
    val size = n * n
    val mult = n / 4
    val result = Array(n) { IntArray(n) }
 
    for (r in 0 until n) {
        for (c in 0 until n) {
            val bitPos = c / mult + (r / mult) * 4
            result[r][c] = if ((bits and (1 shl bitPos))!= 0) r * c + 1 else size - r * c
        }
    }
    return result
}
 
fun numDigits(n: Int): Int {
    var count = 1
    var n = n
 
    while (n >= 10) {
        n /= 10
        count++
    }
 
    return count
}
 
fun printMagicSquare(square: Array<IntArray>, rows: Int) {
    val baseWidth = numDigits(rows * rows) + 3
 
    println("Doubly Magic Square of Order : $rows and Magic Constant : ${(rows * rows + 1) * rows / 2}")
 
    for (i in 0 until rows) {
        for (j in 0 until rows) {
            print(String.format("%${baseWidth - numDigits(square[i][j])}s%d", "", square[i][j]))
        }
        println()
    }
}
 
