fun maxEarnings(n: Int, k: Int, a: List<Int>): Int {
    val m = 1 shl n
    val pairs = mutableListOf<Triple<Int, Int, Int>>()
    for (i in 0 until m) {
        for (bit in 0 until n) {
            val j = i xor (1 shl bit)
            if (j > i) {
                pairs.add(Triple(-(a[i] + a[j]), i, j))
            }
        }
    }
    pairs.sortBy { it.first }
    val used = BooleanArray(m) { false }
    var count = 0
    var total = 0
    for ((negSum, i, j) in pairs) {
        if (!used[i] && !used[j]) {
            total += -negSum
            used[i] = true
            used[j] = true
            count++
            if (count == k) break
        }
    }
    return total
};1

