fun calculate_average(values: Iterable<Any>): Double {
    val vals = values.toList()
    if (vals.isEmpty()) return 0.0
    var total = 0.0
    var count = 0
    for (v in vals) {
        val num = when (v) {
            is Number -> v.toDouble()
            else -> try {
                v.toString().toDouble()
            } catch (e: Exception) {
                throw TypeCastException("Non-numeric value encountered: $v")
            }
        }
        total += num
        count += 1
    }
    return total / count
};1

fun findNeighbors(n: Int, points: List<Pair<Double, Double>>, radius: Double): List<List<Int>> {
    if (n == 0) return emptyList()

    val radiusSq = radius * radius
    val neighbors = MutableList(n) { mutableListOf<Int>() }

    for (i in 0 until n) {
        val (xi, yi) = points[i]
        for (j in i + 1 until n) {
            val dx = xi - points[j].first
            val dy = yi - points[j].second
            if (dx * dx + dy * dy <= radiusSq) {
                neighbors[i].add(j)
                neighbors[j].add(i)
            }
        }
    }
    return neighbors
};1

