fun luckyNumbers(opts: Map<String, Any> = mapOf()): List<Int> {
    /**************************************************************************\
    | OPTIONS                                                                  |
    |**************************************************************************|
    |   even...... boolean............. return even/uneven numbers           |
    |                                     (default: false)                     |
    |                                                                          |
    |   nth....... number............... return nth number                   |
    |                                                                          |
    |   through... number............... return numbers from #1 to number    |
    |               OR array[from, to]... return numbers on index             |
    |                                      from array[from] to array[to]       |
    |                                                                          |
    |   range..... array[from, to]...... return numbers between from and to  |
    \**************************************************************************/

    val even = opts["even"] as? Boolean?: false
    val through = opts["through"] as? Int
    val range = opts["range"] as? List<Int>
    val nth = opts["nth"] as? Int
    val out = mutableListOf<Int>()
    var x = if (even) 2 else 1
    val max = if (range!= null) range[1] * 3 else if (through!= null) through * 12 else if (nth!= null) nth * 15 else 2000

    for (x in x..max) out.add(x) // fill
    for (x in 1 until out.size / 2) { // sieve
        var i = out.size
        while (i-- > 0) {
            if ((i + 1) % out[x] == 0) out.removeAt(i)
        }
    }

    if (nth!= null) return listOf(out[nth - 1])
    if (through!= null) return out.subList(0, through)
    if (range!= null) return out.filter { it >= range[0] && it <= range[1] }
    return out
}

