fun vanEck(): Sequence<Int> {
    var n = 0
    var seen = mutableMapOf<Int, Int>()
    var val = 0
    return generateSequence {
        val result = val
        val last = mapOf(val to n)
        val = n - seen.getOrDefault(val, n)
        seen.putAll(last)
        n++
        result
    }
}

