fun calculate_average_decibel(recordings: List<Map<String, Any>>): Double {
    var totalDuration = 0
    var weightedSum = 0.0
    for (recording in recordings) {
        val duration = (recording["duration"] as Number).toInt()
        val decibel = (recording["decibel"] as Number).toDouble()
        if (duration < 0) {
            throw IllegalArgumentException("Duration cannot be negative.")
        }
        totalDuration += duration
        weightedSum += duration * decibel
    }
    if (totalDuration == 0) {
        throw IllegalArgumentException("Total duration cannot be zero.")
    }
    val averageDecibel = weightedSum / totalDuration
    return String.format("%.2f", averageDecibel).toDouble()
};1

fun dfs(graph: Map<Int, List<Int>>, vert: Int, visited: MutableList<Boolean>): List<Int> {
    visited[vert] = true
    val connectedVerts = mutableListOf<Int>()
    for (neighbour in graph[vert] ?: emptyList()) {
        if (!visited[neighbour]) {
            connectedVerts.addAll(dfs(graph, neighbour, visited))
        }
    }
    return listOf(vert) + connectedVerts
}

fun connectedComponents(graph: Map<Int, List<Int>>): List<List<Int>> {
    val graphSize = graph.size
    val visited = MutableList(graphSize) { false }
    val componentsList = mutableListOf<List<Int>>()
    for (i in 0 until graphSize) {
        if (!visited[i]) {
            val iConnected = dfs(graph, i, visited)
            componentsList.add(iConnected)
        }
    }
    return componentsList
};1

fun Long.modPow(power: Long, mod: Long): Long {
    if (power == 0L) {
        return 1L
    }
    if (power == 1L) {
        return this % mod
    }
    val halfPower = this.modPow(power / 2L, mod)
    return if (power % 2 == 0L) {
        (halfPower * halfPower) % mod
    } else {
        val halfPlusOnePower = (halfPower * this) % mod
        (halfPower * halfPlusOnePower) % mod
    }
};0

fun countPointsAboveXYPlane(points: List<List<Double>>): Int {
    /*
     * Counts how many points in a 3D point cloud lie strictly above the XY-plane
     * (i.e., have z-coordinate > 0).
     *
     * Parameters
     * ----------
     * points : List<List<Double>>
     *     A list where each element is a 3-element list representing
     *     a 3D point [x, y, z].
     *
     * Returns
     * -------
     * Int
     *     Number of points whose z-coordinate is strictly greater than zero.
     */
    var count = 0
    for (point in points) {
        // Ensure the point has at least three components;
        // if not, we ignore it (could also throw an error).
        if (point.size >= 3 && point[2] > 0.0) {
            count += 1
        }
    }
    return count
};1

// O(kN) time | O(1) space
fun mergeKListsNaive(lists: Array<ListNode?>): ListNode? {
    if (lists.isEmpty()) return null
    if (lists.size == 1) return lists[0]

    var head = mergeTwoLists(lists[0], lists[1])
    IntRange(2, lists.size - 1).forEach { head = mergeTwoLists(head, lists[it]) }

    return head
};0

