fun isPrime(n: Int): Boolean {
    if (n < 2) return false
    if (n == 2) return true
    if (n % 2 == 0) return false
    val limit = sqrt(n.toDouble()).toInt()
    var d = 3
    while (d <= limit) {
        if (n % d == 0) return false
        d += 2
    }
    return true
}

fun findKthPositive(arr: List<Int>, k: Int): Int {
    var missingCounter = 0
    val present = arr.toSet()
    var num = 1

    while (true) {
        if (!present.contains(num)) {
            if (!isPrime(num)) {
                missingCounter += 1
                if (missingCounter == k) {
                    return num
                }
            }
        }
        num += 1
    }
};1

