class QuadraticRoots {
    private class Complex(var re: Double, var im: Double) {
 
        fun equals(obj: Any?): Boolean {
            if (obj === this) {
                return true
            }
            if (obj!is Complex) {
                return false
            }
            val other = obj
            return re == other.re && im == other.im
        }
 
        fun toString(): String {
            return if (im == 0.0) {
                String.format("%g", re)
            } else if (re == 0.0) {
                String.format("%gi", im)
            } else {
                String.format("%g %c %gi", re, if (im < 0.0) '-' else '+', Math.abs(im))
            }
        }
    }
 
    fun quadraticRoots(a: Double, b: Double, c: Double): Array<Complex> {
        val roots = arrayOfNulls<Complex>(2)
        val d = b * b - 4.0 * a * c  // discriminant
        val aa = a + a
 
        if (d < 0.0) {
            val re = -b / aa
            val im = sqrt(-d) / aa
            roots[0] = Complex(re, im)
            roots[1] = Complex(re, -im)
        } else if (b < 0.0) {
            // Avoid calculating -b - Math.sqrt(d), to avoid any
            // subtractive cancellation when it is near zero.
            val re = (-b + sqrt(d)) / aa
            roots[0] = Complex(re, 0.0)
            roots[1] = Complex(c / (a * re), 0.0)
        } else {
            // Avoid calculating -b + Math.sqrt(d).
            val re = (-b - sqrt(d)) / aa
            roots[1] = Complex(re, 0.0)
            roots[0] = Complex(c / (a * re), 0.0)
        }
        return roots as Array<Complex>
    }
 
    fun main(args: Array<String>) {
        val equations = arrayOf(
            doubleArrayOf(1.0, 22.0, -1323.0),   // two distinct real roots
            doubleArrayOf(6.0, -23.0, 20.0),     //   with a != 1.0
            doubleArrayOf(1.0, -1.0e9, 1.0),     //   with one root near zero
            doubleArrayOf(1.0, 2.0, 1.0),        // one real root (double root)
            doubleArrayOf(1.0, 0.0, 1.0),        // two imaginary roots
            doubleArrayOf(1.0, 1.0, 1.0)         // two complex roots
        )
        for (i in equations.indices) {
            val roots = quadraticRoots(
                equations[i][0], equations[i][1], equations[i][2])
            println("\na = %g   b = %g   c = %g".format(
                equations[i][0], equations[i][1], equations[i][2]))
