    val sv = BooleanArray(mc + 1)
    val dS = IntArray(10000)
 
    fun sieve() {
        for (a in 9 downTo 0)
            for (b in 9 downTo 0)
                for (c in 9 downTo 0)
                    for (d in 9 downTo 0)
                        dS[a * 10000 + b * 1000 + c * 100 + d] = a + b + c + d
        for (a in 0 until 103)
            for (b in 0 until 1000)
                for (c in 0 until 10000)
                    sv[dS[a * 10000 + b * 1000 + c] + a * 100000000 + b * 10000 + c] = true
    }
 
    val time = measureTimeMillis { sieve() }
    println("Sieving took ${time / 1000.0}s")
    println("\nThe first 50 self numbers are:")
    var count = 0
    for (i in 0 until mc)
        if (!sv[i]) {
            count++
            if (count <= 50) print("$i ")
