    for (i in 0 until mc)
        if (!sv[i]) {
            var limit = 1
            var count = 0
            while (limit <= 1e9.toInt()) {
                count++
                if (count == limit) {
                    println("${count.toString().padStart(12)} ${i.toString().padStart(13)}")
                    limit *= 10
                }
            }
        }
    println("\nOverall took ${time / 1000.0}s")
