val bar = "▁▂▃▄▅▆▇█"
val barcount = bar.length
 
fun sparkline(numbers: List<Double>): Triple<Double, Double, String> {
    val mn = numbers.min()!!
    val mx = numbers.max()!!
    val extent = mx - mn
    val sparkline = numbers.joinToString("") {
        bar[min(barcount - 1, (it - mn) / extent * barcount).toInt()]
    }
    return Triple(mn, mx, sparkline)
}
 
