fun generateVoronoiDiagram(width: Int, height: Int, numCells: Int) {
    val image = BufferedImage(width, height, BufferedImage.TYPE_INT_RGB)
    val nx = IntArray(numCells)
    val ny = IntArray(numCells)
    val nr = IntArray(numCells)
    val ng = IntArray(numCells)
    val nb = IntArray(numCells)
    for (i in 0 until numCells) {
        nx[i] = Random.nextInt(width)
        ny[i] = Random.nextInt(height)
        nr[i] = Random.nextInt(256)
        ng[i] = Random.nextInt(256)
        nb[i] = Random.nextInt(256)
    }
    for (y in 0 until height) {
        for (x in 0 until width) {
            var dmin = hypot(width - 1, height - 1)
            var j = -1
            for (i in 0 until numCells) {
                val d = hypot(nx[i] - x, ny[i] - y)
                if (d < dmin) {
                    dmin = d
                    j = i
                }
            }
            image.setRGB(x, y, Color(nr[j], ng[j], nb[j]).rgb)
        }
    }
    ImageIO.write(image, "png", File("VoronoiDiagram.png"))
}
 
