fun whoIsMoreLikely(T: Int, testCases: List<Triple<Int, String, String>>): List<String> {
    val results = mutableListOf<String>()
    for (i in 0 until T) {
        val (n, r, b) = testCases[i]
        var countRed = 0
        var countBlue = 0
        for (j in 0 until n) {
            val rc = r[j]
            val bc = b[j]
            if (rc > bc) {
                countRed++
            } else if (rc < bc) {
                countBlue++
            }
        }
        if (countRed == 0 && countBlue == 0) {
            results.add("EQUAL")
        } else {
            if (countRed > countBlue) {
                results.add("RED")
            } else if (countBlue > countRed) {
                results.add("BLUE")
            } else {
                results.add("EQUAL")
            }
        }
    }
    return results
};1

