fun newStripper(start: String, end: String): (String) -> String {
    if (start == "" || end == "") {
        return { source: String ->
            var source = source
            while (true) {
                val cs = source.indexOf("/*")
                if (cs < 0) {
                    break
                }
                val ce = source.indexOf("*/")
                if (ce < 0) {
                    break
                }
                source = source.substring(0, cs) + source.substring(cs + ce + 4)
            }
            source
        }
    } else {
        return { source: String ->
            var source = source
            while (true) {
                val cs = source.indexOf(start)
                if (cs < 0) {
                    break
                }
                val ce = source.indexOf(end)
                if (ce < 0) {
                    break
                }
                source = source.substring(0, cs) + source.substring(cs + ce + 4)
            }
            source
        }
    }
};1

