fun deg2rad(d: Double): Double = d * Math.PI / 180
fun rad2deg(r: Double): Double = r * 180 / Math.PI
 
fun mean_angle(deg: List<Double>): Double {
    var sum = 0i
    for (x in deg) {
        sum += Complex.rect(1, deg2rad(x))
    }
    return rad2deg(Complex.phase(sum))
}
 
