fun getAuthorizedUsers(userPermissions: Map<String, Any>): List<String> {
    /**
     * Returns a list of users that have at least one of the
     * required permissions: 'read', 'write', or 'admin'.
     *
     * @param userPermissions Map mapping user identifiers (String) to a
     * value which is usually a List (or could be a single String) of permission strings.
     * @return List of users that possess at least one of the required permissions,
     * returned in the same order as in the input map.
     */
    val REQUIRED = setOf("read", "write", "admin")
    val authorizedUsers = mutableListOf<String>()
    for ((user, perms) in userPermissions) {
        val permsSet: Set<String> = when (perms) {
            is String -> setOf(perms)
            is Iterable<*> -> perms.filterIsInstance<String>().toSet()
            else -> emptySet()
        }
        if (REQUIRED.intersect(permsSet).isNotEmpty()) {
            authorizedUsers.add(user)
        }
    }
    return authorizedUsers
};1

