class Queue {
    private val items = mutableListOf<Any?>()

    fun enqueue(item: Any?) {
        items.add(item)
    }

    fun dequeue(): Any? {
        if (isEmpty()) {
            return null
        }
        return items.removeAt(0)
    }

    fun peek(): Any? {
        if (isEmpty()) {
            return null
        }
        return items[0]
    }

    fun isEmpty(): Boolean {
        return items.isEmpty()
    }
};1

