import kotlin.math.abs
import kotlin.math.max
import kotlin.random.Random
 
// "given"
fun dice5(): Int {
    return Random.nextInt(5) + 1
}
 
// function specified by task "Seven-sided dice from five-sided dice"
fun dice7(): Int {
    var i: Int
    do {
        i = 5 * dice5() + dice5()
    } while (i >= 27)
    return (i / 3) - 1
}
 
// function specified by task "Verify distribution uniformity/Naive"
//
// Parameter "f" is expected to return a random integer in the range 1..n.
// (Values out of range will cause an unceremonious crash.)
// "Max" is returned as an "indication of distribution achieved."
// It is the maximum delta observed from the count representing a perfectly
// uniform distribution.
// Also returned is a boolean, true if "max" is less than threshold
// parameter "delta."
fun distCheck(f: () -> Int, n: Int, repeats: Int, delta: Double): Pair<Double, Boolean> {
    val count = IntArray(n)
    for (i in 0 until repeats) {
        count[f() - 1]++
    }
    val expected = repeats.toDouble() / n
    var max = 0.0
    for (c in count) {
        max = max(max, abs(c - expected))
    }
    return Pair(max, max < delta)
}
 
// Driver, produces output satisfying both tasks.
fun main() {
    val calls = 1000000
    val (max, flatEnough) = distCheck({ dice7() }, 7, calls, 500.0)
    println("Max delta: $max Flat enough: $flatEnough")
    val (max2, flatEnough2) = distCheck({ dice7() }, 7, calls, 500.0)
    println("Max delta: $max2 Flat enough: $flatEnough2")
};1

