import kotlin.math.sign
 
class Tree(val isRed: Boolean, val left: Tree, val value: Int, val right: Tree) {
    companion object {
        val E = Tree(false, null, 0, null)
    }
 
    constructor(c: Boolean, l: Tree?, v: Int, r: Tree?) : this(c, l?: E, v, r?: E)
 
    operator fun component1(): Boolean = isRed
    operator fun component2(): Tree = left
    operator fun component3(): Int = value
    operator fun component4(): Tree = right
 
    fun toString(): String = if (this == E) "[]" else "[$${if (isRed) 'R' else 'B'}$value]"
 
    fun insert(x: Int): Tree = ins(x).makeBlack()
    fun makeBlack(): Tree {
        isRed = false
        return this
    }
 
    fun print(indent: Int = 0) {
        if (this!= E) right.print(indent + 1)
        println(" ".repeat(indent * 4) + toString())
        if (this!= E) left.print(indent + 1)
    }
 
    fun ins(x: Int): Tree = when (sign(x.compareTo(value))) {
        -1 -> Tree(isRed, left.ins(x), value, right).balance()
        1 -> Tree(isRed, left, value, right.ins(x)).balance()
        else -> this
    }
 
    fun balance(): Tree = when {
        this == (false, (true, (true, a, x, b), y, c), z, d) -> Tree(true, Tree(false, a, x, b), y, Tree(false, c, z, d))
        this == (false, (true, a, x, (true, b, y, c)), z, d) -> Tree(true, Tree(false, a, x, b), y, Tree(false, c, z, d))
        this == (false, a, x, (true, (true, b, y, c), z, d)) -> Tree(true, Tree(false, a, x, b), y, Tree(false, c, z, d))
        this == (false, a, x, (true, b, y, (true, c, z, d))) -> Tree(true, Tree(false, a, x, b), y, Tree(false, c, z, d))
        else -> this
    }
}
 
