fun minLcmPair(n: Int): Pair<Int, Int> {
    fun findSpf(x: Int): Int {
        if (x % 2 == 0) {
            return 2
        }
        val maxDivisor = sqrt(x.toDouble()).toInt() + 1
        var i = 3
        while (i <= maxDivisor) {
            if (x % i == 0) {
                return i
            }
            i += 2
        }
        return x
    }
    val spf = findSpf(n)
    val d = n / spf
    val a = d
    val b = n - a
