fun calculateConfusionMetrics(trueLabels: List<Int>, predictedLabels: List<Int>): Map<String, Int> {
    if (trueLabels.size != predictedLabels.size) {
        throw IllegalArgumentException("trueLabels and predictedLabels must be of equal length.")
    }

    var tp = 0
    var tn = 0
    var fp = 0
    var fn = 0

    for ((t, p) in trueLabels.zip(predictedLabels)) {
        val t_bin = if (t == 1) 1 else 0
        val p_bin = if (p == 1) 1 else 0

        if (t_bin == 1 && p_bin == 1) {
            tp += 1
        } else if (t_bin == 0 && p_bin == 0) {
            tn += 1
        } else if (t_bin == 0 && p_bin == 1) {
            fp += 1
        } else { // t_bin == 1 && p_bin == 0
            fn += 1
        }
    }

    val total = tp + tn + fp + fn

    return mapOf(
        "true_pos" to tp,
        "true_neg" to tn,
        "false_pos" to fp,
        "false_neg" to fn,
        "total" to total
    )
};1

fun findPairForCurrentPointY(
    sensor: Point, beacon: Point, point: Point
): Pair<Point, Point> {
    val distance = sensor.calculateDistanceTo(beacon)

    val rightPart = distance - abs(sensor.y - point.y)

    val firstX = sensor.x + rightPart
    val secondX = sensor.x - rightPart

    return Point(minOf(firstX, secondX), point.y) to Point(maxOf(firstX, secondX), point.y)
