fun simulateStep(jets: List<Point>, previous: Step): Step {
    val cave = previous.cave
    var blockCount = previous.blockCount
    var jetCount = previous.jetCount
    var shape = shapes.nth(blockCount++).startingPosition(cave.minY)
    do {
        val movedShape = shape + jets.nth(jetCount++)
        if (movedShape inBoundsOf 0..6 && !movedShape.collides(cave)) {
            shape = movedShape
        }

        shape = shape.moveDown()
    } while (!shape.collides(cave))
    cave += shape.moveUp()
    return Step(cave, blockCount, jetCount, blockCount % shapes.size, jetCount % jets.size)
};0

/**
 * Counts how many times it takes to guess the amount of money.
 *
 * This is a non-standard binary search because it allows you to start
 * on any number (but splits the halves after that).
 */
fun binary(lowerBound: Int, upperBound: Int, guess: Int, actual: Int): Int {
  if (lowerBound > upperBound
      || guess < lowerBound || guess > upperBound
      || actual < lowerBound || actual > upperBound) {
    throw IllegalArgumentException("You entered something wrong...")
  }

  var left: Int = lowerBound
  var right: Int = upperBound
  var iterations: Int = 0
  var isFirst: Boolean = true

  while (true) {
    // On the first runthrough, don't calculate the midpoint; use the guess provided
    val current = if (isFirst) guess else (left + right) / 2
    isFirst = false

    iterations += 1 // Each time we do this, it counts as a guess
    if (current == actual) {
      break;
    } else if (current < actual) {
      left = current + 1
    } else if (current > actual) {
      right = current - 1
    }
  }

  return iterations
};0

fun extrapolate(y: List<Int>, value: Long): Any {
    // Taking into account that x[1]=3*x[0] and x[2]=5*x[0] and value = n*x[0]
    val a = (y[2] - (2 * y[1]) + y[0]) / 2
    val b = y[1] - y[0] - a
    val c = y[0]

    return value * value * a + value * b + c
};0

 
/* in place sort */
fun IntArray.sortDisjoint(indices: Set<Int>) {
    val sortedSubset = this.filterIndexed { index, _ -> index in indices }.sorted()
    if (sortedSubset.size < indices.size)
        throw IllegalArgumentException("Argument set contains out of range indices")
    indices.sorted().forEachIndexed { index, value -> this[value] = sortedSubset[index] }
}
 
