fun findMax(lst: List<Int>): Int? {
    // Returns the maximum integer from the input list.
    // If the list is empty, returns null.
    if (lst.isEmpty()) {
        return null
    }

    // Initialize currentMax with the first element
    var currentMax = lst[0]

    // Iterate through the list starting from the second element
    for (num in lst.drop(1)) {
        if (num > currentMax) {
            currentMax = num
        }
    }

    return currentMax
};1

