fun categorizeSeismicEvents(magnitudes: List<Double>): Map<String, Int> {
    val categories = mutableMapOf(
        "Minor" to 0,
        "Light" to 0,
        "Moderate" to 0,
        "Strong" to 0,
        "Major" to 0,
        "Great" to 0
    )
