            magnitude >= 3.0 && magnitude < 4.0 -> categories["Light"] = categories["Light"]!! + 1
            magnitude >= 4.0 && magnitude < 5.0 -> categories["Moderate"] = categories["Moderate"]!! + 1
            magnitude >= 5.0 && magnitude < 6.0 -> categories["Strong"] = categories["Strong"]!! + 1
            magnitude >= 6.0 && magnitude < 7.0 -> categories["Major"] = categories["Major"]!! + 1
            magnitude >= 7.0 -> categories["Great"] = categories["Great"]!! + 1
        }
    }
    return categories
