import java.io.File
import java.io.InputStream
import java.util.*
 
fun main(args: Array<String>) {
    if (args.size < 1) {
        println("Usage: ${args[0]} [path]")
        return
    }
 
    val src = File(args[0]).readText()
 
    // One pass to find bracket pairs.
    val brackets = HashMap<Int, Int>()
    val scopeStack = Stack<Int>()
    for ((idx, ch) in src.withIndex()) {
        when (ch) {
            '[' -> scopeStack.push(idx)
            ']' -> brackets[scopeStack.pop()] = idx
        }
    }
 
    var pc = 0 // Program counter
    val mem = Array(5000, { 0 }) // Program cemory
    var ptr = 0 // Pointer
    val stack = Stack<Int>() // Bracket stack
 
    val reader = System.`in`
    while (pc < src.length) {
        val val = mem[ptr]
 
        when (src[pc]) {
            '>' -> ptr++
            '<' -> ptr--
 
            '+' -> mem[ptr]++
            '-' -> mem[ptr]--
 
            '[' -> {
                if (val == 0) {
                    pc = brackets[pc]!!
                } else {
                    stack.push(pc)
                }
            }
            ']' -> {
                val matchingBracket = stack.pop()
                if (val!= 0) {
                    pc = matchingBracket - 1
                }
            }
 
            '.' -> print(val.toChar())
            ',' -> mem[ptr] = reader.read()
 
            else -> { /* ignore */ }
        }
 
        pc++
    }
};1

