    if (this is FileSystemNode.Directory) {
        current += onItem(this, acc)
        this.items.forEach {
            current += it.accumulateDirs(0, onItem)
        }
    }
    return current
};0

fun isPrime(n: Int): Boolean {
    var x = Math.floor(Math.sqrt(n.toDouble())).toInt()
    var i = 2
 
    while ((i <= x) && (n % i!= 0)) i++
 
    return (x < i)
}
 
fun smooth(n: Int, s: Int, k: Int): List<Long> {
    var p = mutableListOf<Array<Any>>()
    for (i in 2..n) {
        if (isPrime(i)) {
            p.add(arrayOf(i.toLong(), mutableListOf(1L), 0))
        }
    }
 
    var res = mutableListOf<Long>()
    for (i in 0 until s + k) {
        var m = p[0][1] as MutableList<Long>
        m = m[p[0][2] as Int]
 
        for (j in 1 until p.size) {
            if (p[j][1] as MutableList<Long>[p[j][2] as Int] < m) m = p[j][1] as MutableList<Long>[p[j][2] as Int]
        }
 
        for (j in 0 until p.size) {
            (p[j][1] as MutableList<Long>).add(p[j][0] as Long * m)
            if (p[j][1] as MutableList<Long>[p[j][2] as Int] == m) p[j][2] = (p[j][2] as Int) + 1
        }
 
        res.add(m)
    }
 
    return res.subList(s - 1, s - 1 + k)
}
 
