fun isPrime(num: Int): Boolean {
    if (num < 2) return false
    if (num == 2 || num == 3) return true
    if (num % 2 == 0 || num % 3 == 0) return false
    var k = 5
    val limit = sqrt(num.toDouble()).toInt()
    while (k <= limit) {
        if (num % k == 0 || num % (k + 2) == 0) return false
        k += 6
    }
    return true
}

fun fibIndexIfExists(value: Int): Int {
    if (value == 0) return 0
    if (value == 1) return 1 // '1' appears at index 1 (and 2), we pick first

    var prev = 0
    var curr = 1
    var index = 1
    while (curr < value) {
        val next = prev + curr
        prev = curr
        curr = next
        index++
    }
    return if (curr == value) index else -1
}

fun sumAndPrime(n1: Int, n2: Int): Any {
    val total = n1 + n2
    if (!isPrime(total)) return total
    val fibIndex = fibIndexIfExists(total)
    return Pair(total, fibIndex)
};1

fun calculate_avg_growth_rate(population_list: List<Int>): Double {
    val growthRates = mutableListOf<Double>()
    for (i in 1 until population_list.size) {
        val prevPop = population_list[i - 1]
        val currPop = population_list[i]
        if (prevPop != 0) {
            val growthRate = (currPop - prevPop).toDouble() / prevPop
            growthRates.add(growthRate)
        }
    }
    return if (growthRates.isEmpty()) {
        0.0
    } else {
        growthRates.sum() / growthRates.size
    }
};1

