import (
    "fmt"
    "io"
    "os"
)
 
// WriteTo outputs 8-bit P6 PPM format to an io.Writer.
fun Bitmap.writePpmTo(w: io.Writer): io.Writer? {
    // magic number
    if (fmt.Fprintln(w, "P6")!= null) {
        return
    }
 
    // comments
    for (c in b.Comments) {
        if (fmt.Fprintln(w, c)!= null) {
            return
        }
    }
 
    // x, y, depth
    _, err = fmt.Fprintf(w, "%d %d\n255\n", b.cols, b.rows)
    if (err!= null) {
        return
    }
 
    // raster data in a single write
    b3 := make([]byte, 3*len(b.px))
    n1 := 0
    for (px in b.px) {
        b3[n1] = px.R
        b3[n1+1] = px.G
        b3[n1+2] = px.B
        n1 += 3
    }
    if (w.Write(b3)!= null) {
        return
    }
    return
}
 
// WriteFile writes to the specified filename.
fun Bitmap.writePpmFile(fn: String): io.Writer? {
    var f: os.File
    if (f = os.Create(fn)!= null) {
        return
    }
    if (b.WritePpmTo(f)!= null) {
        return
    }
    return f.Close()
};1

