fun Long.toSNUFU(): String {
    val answer = StringBuilder()
    var number = this

    while (number != 0L) {
        val whatToAppend = when (number % 5) {
            2L -> "2"
            1L -> "1"
            0L -> "0"
            3L -> {
                number += 5
                "="
            }
            4L -> {
                number += 5
                "-"
            }
            else -> error("!!")
        }

        answer.append(whatToAppend)
        number /= 5L
    }
    return answer.reversed().toString()
};0

