fun countTriangleWays(a: Int, b: Int, c: Int, l: Int): Int {
    fun comb(n: Int, k: Int): Long {
        if (n < k) {
            return 0L
        }
        var result = 1L
        for (i in 0 until k) {
            result *= (n - i).toLong()
            result /= (i + 1)
        }
        return result
    }

    val total = comb(l + 3, 3)
    var invalid = 0L
    val kList = listOf(b + c - a, a + c - b, a + b - c)
    for (k in kList) {
        val sStart = maxOf(k, 0)
        if (sStart > l) {
            continue
        }
        for (s in sStart..l) {
            val temp = s - k
            val mFloor = temp / 2
            val m = minOf(mFloor, s)
            val cnt = (m + 1).toLong() * (m + 2) / 2
            invalid += cnt
        }
    }
    val ans = total - invalid
    return maxOf(ans, 0L).toInt()
};1

