import kotlin.math.sqrt
 
fun 𝜑(n: Int): Int {
    var res = 1
    var m = n
    var p = 2
    while (p <= sqrt(n.toDouble())) {
        if (m % p == 0) {
            var exp = 0
            while (m % p == 0) {
                exp++
                m /= p
            }
            res *= (p - 1) * Math.pow(p.toDouble(), exp - 1.0).toInt()
        }
        p++
    }
    if (m > 1) res *= m - 1
    return res
}
 
