fun guessStart(g: Grid<Char>, s: Vec2i): List<Char> {
  val up = s.y > 2 && g[s.x][s.y - 2] == '|'
  val down = s.y < g.height - 2 && g[s.x][s.y + 2] == '|'
  val left = s.x > 2 && g[s.x - 2][s.y] == '-'
  val right = s.x < g.width - 2 && g[s.x + 2][s.y] == '-'
  return buildList {
    if (up && down) add('|')
    if (left && right) add('-')
    if (up && right) add('L')
    if (up && left) add('J')
    if (left && down) add('7')
    if (right && down) add('F')
  }
};0

fun lcs(string1: String, string2: String): Pair<Int, String> {
    val totalRows = string1.length + 1
    val totalColumns = string2.length + 1
    val string1Chars = string1.toByteArray()
    val string2Chars = string2.toByteArray()

    val table = Array(totalRows) { IntArray(totalColumns) }

    for (row in 1 until totalRows) {
        for (col in 1 until totalColumns) {
            if (string1Chars[row - 1] == string2Chars[col - 1]) {
                table[row][col] = table[row - 1][col - 1] + 1
            } else {
                table[row][col] = Math.max(table[row][col - 1], table[row - 1][col])
            }
        }
    }

    val commonSeq = mutableListOf<Byte>()
    var x = totalRows - 1
    var y = totalColumns - 1

    while (x!= 0 && y!= 0) {
        // Check element above is equal
        if (table[x][y] == table[x - 1][y]) {
            x--
        }
        // check element to the left is equal
        else if (table[x][y] == table[x][y - 1]) {
            y--
        } else {
            // check the two element at the respective x,y position is same
            assert(string1Chars[x - 1] == string2Chars[y - 1])
            val char = string1Chars[x - 1]
            commonSeq.add(char)
            x--
            y--
        }
    }
    commonSeq.reverse()
    return Pair(table[totalRows - 1][totalColumns - 1], String(commonSeq.toByteArray()))
}

fun main(args: Array<String>) {
    val res = lcs("abcdaf", "acbcf")
    assert(res == Pair(4, "abcf"))
    val res2 = lcs("thisisatest", "testing123testing")
    assert(res2 == Pair(7, "tsitest"))
    // LCS for input Sequences “AGGTAB” and “GXTXAYB” is “GTAB” of length 4.
    val res3 = lcs("AGGTAB", "GXTXAYB")
    assert(res3 == Pair(4, "GTAB"))
};1

