fun crossp(a: List<Int>, b: List<Int>): List<Int> {
    assert(a.size == b.size && a.size == 3) { "For 3D vectors only" }
    val a1 = a[0]
    val a2 = a[1]
    val a3 = a[2]
    val b1 = b[0]
    val b2 = b[1]
    val b3 = b[2]
    return listOf(a2 * b3 - a3 * b2, a3 * b1 - a1 * b3, a1 * b2 - a2 * b1)
}
 
fun dotp(a: List<Int>, b: List<Int>): Int {
    assert(a.size == b.size) { "Vector sizes must match" }
    return a.zip(b).map { (aterm, bterm) -> aterm * bterm }.sum()
}
 
fun scalartriplep(a: List<Int>, b: List<Int>, c: List<Int>): Int {
    return dotp(a, crossp(b, c))
}
 
fun vectortriplep(a: List<Int>, b: List<Int>, c: List<Int>): List<Int> {
    return crossp(a, crossp(b, c))
}
 
