val rx = Regex("""<div class=\"yst result\">.+?<a href=\"(.*?)\" class=\"\">(.*?)</a>.+?class="abstract ellipsis">(.*?)</p>""")
 
class YahooResult(var title: String, var link: String, var text: String) {
 
    fun toString() = "\nTitle: $title\nLink : $link\nText : $text"
