fun solve(i: Int, j: Int, n: Int, m: Int, curr: Int): Boolean {
    if (i <= 0 || j <= 0 || i > n || j > m) return false
    if (dp[i][j] != -1) return dp[i][j] != 0
    if (i == n && j == m) return curr == 0
    if (solve(i + 1, j, n, m, curr - j) || solve(i, j + 1, n, m, curr - i)) {
        dp[i][j] = 1
        return true
    }
    dp[i][j] = 0
    return false
};0

