fun permute(v: List<String>, m: Boolean): List<List<String>> {
    var p = -1
    var j: Int
    var k: Int
    var f: Boolean
    var r: List<List<String>>
    var l = v.size
    var q = 1
    var i = l + 1
    while (--i > 0) {
        q *= i
    }
    var x = listOf(List(l, { i -> 0 }), List(l, { i -> 0 }), List(l, { i -> 0 }), List(l, { i -> 0 }))
    j = q
    k = l + 1
    i = -1
    while (++i < l) {
        x[2][i] = i
        x[1][i] = x[0][i] = j /= --k
    }
    r = List(q, { i -> List(l, { j -> "" }) })
    while (++p < q) {
        i = -1
        while (++i < l) {
            if (!--x[1][i]) {
                x[1][i] = x[0][i]
                x[2][i] = (x[2][i] + 1) % l
            }
            r[p][i] = if (m) x[3][i] else v[x[3][i]]
            x[3][i] = x[2][i]
            f = false
            j = i
            while (!f) {
                f = true
                if (x[3][--j] == x[2][i]) {
                    x[3][i] = x[2][i] = (x[2][i] + 1) % l
                    f = false
                }
            }
        }
    }
    return r
}
 
