fun Array<BooleanArray>.biggestArea(): Int {
    require(isNotEmpty() && first().isNotEmpty()) { "The inputted rectangle can't be empty" }
    val heights = IntArray(first().size)
    var maxArea = 0
    forEach {
        for (i in it.indices)
            if (it[i])
                heights[i]++
            else
                heights[i] = 0
        val area = heights.maxVolume()
        if (area > maxArea)
            maxArea = area
    }
    return maxArea
