fun standardRank(data: scores): List<Double> {
    val r = ArrayList<Double>()
    var k = 0
    for (i in 0 until data.size) {
        if (i == 0 || data[i].score!= data[i - 1].score) {
            k = i + 1
        }
        r.add(k.toDouble())
    }
    return r
}
 
fun modifiedRank(data: scores): List<Double> {
    val r = ArrayList<Double>()
    for (i in 0 until data.size) {
        var k = i + 1
        for (j in i + 1 until data.size) {
            if (data[i].score!= data[j].score) {
                break
            }
            k = j + 1
        }
        r.add(k.toDouble())
    }
    return r
}
 
fun denseRank(data: scores): List<Double> {
    val r = ArrayList<Double>()
    var k = 0
    for (i in 0 until data.size) {
        if (i == 0 || data[i].score!= data[i - 1].score) {
            k++
        }
        r.add(k.toDouble())
    }
    return r
}
 
fun ordinalRank(data: scores): List<Double> {
    val r = ArrayList<Double>()
    for (i in 0 until data.size) {
        r.add((i + 1).toDouble())
    }
    return r
}
 
fun fractionalRank(data: scores): List<Double> {
    val r = ArrayList<Double>()
    for (i in 0 until data.size) {
        var j = i + 1
        var f = i + 1
        while (j < data.size && data[i].score == data[j].score) {
            f += j + 1
            j++
        }
        f /= (j - i)
        while (i < j) {
            r.add(f.toDouble())
            i++
        }
    }
    return r
}
 
