fun oddMagicSquare(n: Int): Array<IntArray> {
    if (n % 2 == 0 || n <= 0) {
        throw IllegalArgumentException("Need odd positive number")
    }
    val result = Array(n) { IntArray(n) }
    for (i in 0 until n) {
        for (j in 0 until n) {
            result[i][j] = n * ((i + j + 1 + n / 2) % n) + ((i + 2 * j - 5) % n) + 1
        }
    }
    return result
}
 
