fun doQuineMcClusky(initCubes: List<Cube>, termCount: Int, usefulCubes: List<Cube>, dontCares: List<Cube>) {
    var partitions = partitionCubesByOneCount(initCubes)
    val primeImplicants = mutableListOf<Cube>()
    while (true) {
        val (nextCubes, leftovers) = reduceOneStep(partitions, termCount)
        primeImplicants.addAll(leftovers)
        printPartitions(partitions, leftovers)
        println("")
        println("")
        if (nextCubes.isEmpty()) break
        partitions = partitionCubesByOneCount(nextCubes)
    }
    val distinctPrimeImplicants = primeImplicants.distinct()

    val primeImplicantStrings = distinctPrimeImplicants.map { cube -> cube.minTerms.joinToString { it.toString() } }
    val maxWidth = primeImplicantStrings.maxOf { it.length }
    val paddingString = "".padStart(maxWidth)
    val allCubes = usefulCubes.joinToString(" | ") { cube -> "%3s".format(cube.minTerms[0].toString()) }
    println("$paddingString | $allCubes")
    for ((idx, primeImplicant) in distinctPrimeImplicants.withIndex()) {
        val implicantString = "%${maxWidth}s".format(primeImplicantStrings[idx])
        val cubeString =
            usefulCubes.joinToString(" | ") { if (it.minTerms[0] in primeImplicant.minTerms) " ✓ " else "   " }
        println("$implicantString | $cubeString")
    }

    val minCovers =
        findMinCovers(distinctPrimeImplicants, usefulCubes.map { it.minTerms[0] }, dontCares.map { it.minTerms[0] })
    println("\nMin-covers:")
    for (cover in minCovers) println("$cover")
};0

import java.util.ArrayList
import java.util.Arrays
 
typealias Tree = Long
 
val list = ArrayList<Tree>()
var cap = 0
var len = 0
val offset = IntArray(32)
 
fun append(t: Tree) {
    if (len == cap) {
        cap = if (cap == 0) 2 else cap * 2
        list.ensureCapacity(cap)
    }
    list.add(1 or (t shl 1))
    len++
}
 
fun show(t: Tree, len: Int) {
    for (i in 0 until len) {
        print(if (t and 1 == 1L) "(" else ")")
        t shr= 1
    }
}
 
fun listtrees(n: Int) {
    for (i in offset[n] until offset[n + 1]) {
        show(list[i], n * 2)
        println()
    }
}
 
/* assemble tree from subtrees
    n:   length of tree we want to make
    t:   assembled parts so far
    sl:  length of subtree we are looking at
    pos: offset of subtree we are looking at
    rem: remaining length to be put together
*/
fun assemble(n: Int, t: Tree, sl: Int, pos: Int, rem: Int) {
    if (rem == 0) {
        append(t)
        return
    }
 
    if (sl > rem) // need smaller subtrees
        pos = offset[sl] = rem
    else if (pos >= offset[sl + 1]) {
        // used up sl-trees, try smaller ones
        if (--sl == 0) return
        pos = offset[sl]
    }
 
    assemble(n, t shl (2 * sl) or list[pos], sl, pos, rem - sl)
    assemble(n, t, sl, pos + 1, rem)
}
 
fun mktrees(n: Int) {
    if (offset[n + 1]!= 0) return
    if (n > 0) mktrees(n - 1)
 
    assemble(n, 0, n - 1, offset[n - 1], n - 1)
    offset[n + 1] = len
}
 
fun main(args: Array<String>) {
    var n = 5
    if (args.size > 0) {
        n = args[0].toInt()
    }
    if (n <= 0 || n > 25) n = 5
 
    // init 1-tree
    append(0)
 
    mktrees(n)
    System.err.printf("Number of %d-trees: %d\n", n, offset[n + 1] - offset[n])
    listtrees(n)
};1

fun countPrimeOddNumbersUnder100(arr: List<Int>): Int {
    // 100 までの奇数の素数を前計算
    val sieve = BooleanArray(101) { true }
    sieve[0] = false
    sieve[1] = false
    for (i in 2..Math.sqrt(100.0).toInt()) {
        if (sieve[i]) {
            for (j in i * i..100 step i) {
                sieve[j] = false
            }
        }
    }
    val oddPrimes = (3..100 step 2).filter { sieve[it] }.toSet()
    var res = 0
    for (num in arr) {
        val absNum = kotlin.math.abs(num)
        if (absNum <= 100 && num % 2 != 0 && absNum in oddPrimes) {
            res++
        }
    }
    return res
};1

 
typealias Func = () -> Unit
 
fun doChar(odd: Boolean, f: Func?): Boolean {
    val c = System.`in`.read()
    if (c == -1) return false // end of stream reached
    val ch = c.toChar()
 
    fun writeOut() {
        print(ch)
        if (f != null) f()
    }
 
    if (!odd) print(ch)
    if (ch.isLetter()) return doChar(odd, ::writeOut)
    if (odd) {
        if (f != null) f()
        print(ch)
    }
    return ch != '.'
}
 
fun main(args: Array<String>) {
    repeat(2) {
