class RGBColour(red: Int, green: Int, blue: Int) {
    init {
        if (!red.between(0, 255) &&!green.between(0, 255) &&!blue.between(0, 255)) {
            throw IllegalArgumentException("invalid RGB parameters: ${listOf(red, green, blue).inspect()}")
        }
    }

    val red = red
    val green = green
    val blue = blue

    val r: Int
        get() = red
    val g: Int
        get() = green
    val b: Int
        get() = blue

    companion object {
        val RED = RGBColour(255, 0, 0)
        val GREEN = RGBColour(0, 255, 0)
        val BLUE = RGBColour(0, 0, 255)
        val BLACK = RGBColour(0, 0, 0)
        val WHITE = RGBColour(255, 255, 255)
    }
}

class Pixmap(width: Int, height: Int) {
    val width = width
    val height = height

    private val data = fill(RGBColour.WHITE)

    fun fill(colour: RGBColour): Array<Array<RGBColour>> {
        return Array(width) { Array(height) { colour } }
    }

    fun validatePixel(x: Int, y: Int) {
        if (!x.between(0, width - 1) &&!y.between(0, height - 1)) {
            throw IllegalArgumentException("requested pixel ($x, $y) is outside dimensions of this bitmap")
        }
    }

    operator fun get(x: Int, y: Int): RGBColour {
        validatePixel(x, y)
        return data[x][y]
    }

    fun getPixel(x: Int, y: Int): RGBColour {
        return this[x, y]
    }

    operator fun set(x: Int, y: Int, colour: RGBColour) {
        validatePixel(x, y)
        data[x][y] = colour
    }

    fun setPixel(x: Int, y: Int, colour: RGBColour) {
        this[x, y] = colour
    }
};1

/**
 * Returns the greatest integer less than [n] that is a multiple of this one.
 *
 * @throws IllegalArgumentException If this number is negative or 0, or if [n] is negative.
 */
fun Long.prevMultipleBelow(n: Long): Long {
    require(this > 0L) { "Number must be positive: $this" }
    require(n >= 0L) { "Argument must be non-negative: $n" }
    return if (n % this == 0L) n - this else prevMultipleAtMost(n)
