import kotlin.text.*
 
fun ishex(x: Int): Boolean {
    return (x >= '0' && x <= '9') || (x >= 'a' && x <= 'f') || (x >= 'A' && x <= 'F')
}
 
fun decode(s: String, dec: String?): Int {
    var o = 0
    val end = s.length
    var c: Int
    for (i in 0..end) {
        c = s[i]
        if (c == '+') c =''
        else if (c == '%' && (!ishex(s[i + 1]) ||!ishex(s[i + 2]) ||!s.substring(i + 1, i + 3).toInt(16).also { c = it }))
            return -1
        if (dec!= null) dec[o] = c.toChar()
        o++
    }
    return o - dec!!.length
}
 
