fun calculate_days_away(travelDates: List<Pair<String, String>>): Int {
    val formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")
    var totalDays = 0
    for ((startDate, endDate) in travelDates) {
        val start = LocalDate.parse(startDate, formatter)
        val end = LocalDate.parse(endDate, formatter)
        totalDays += (end.toEpochDay() - start.toEpochDay()).toInt() + 1
    }
