// Stand-in for the argument wrapper object
data class _FormatArg(val value: Any)

fun prepareInterpolationArguments(args: Any): Any {
    return when (args) {
        is _FormatArg -> args.value
        is Iterable<*> -> {
            val values = args.map {
                if (it is _FormatArg) it.value else throw IllegalArgumentException("All args must be _FormatArg")
            }
            when (values.size) {
                0 -> emptyArray<Any>()
                1 -> values[0]
                else -> values.toTypedArray()
            }
        }
        else -> throw IllegalArgumentException("`args` must be a _FormatArg instance or an iterable of _FormatArg instances")
    }
}

fun customStringInterpolation(value: ByteArray, args: Any): ByteArray {
    if (value !is ByteArray) {
        throw IllegalArgumentException("`value` must be a ByteArray")
    }
    val stringValue = value.toString(Charsets.UTF_8)
    val interpolatedArgs = prepareInterpolationArguments(args)
    try {
        val result: String = when (interpolatedArgs) {
            is Array<*> -> String.format(stringValue, *interpolatedArgs)
            else -> String.format(stringValue, interpolatedArgs)
        }
        return result.toByteArray(Charsets.UTF_8)
    } catch (e: Exception) {
        throw IllegalArgumentException("Interpolation error: ${e.message}")
    }
};1

