fun leonardo(n: Int, l0: Int, l1: Int, add: Int): List<Int> {
    val leo = MutableList(n) { 0 }
    leo[0] = l0
    leo[1] = l1
    for (i in 2 until n) {
        leo[i] = leo[i - 1] + leo[i - 2] + add
    }
    return leo
