fun findDiffPosition(s1: String, s2: String): Int {
    // Returns the index of the first differing character between s1 and s2.
    // If the strings are identical, returns -1.
    // If one string is a prefix of the other, returns length of shorter string.
    val minLen = minOf(s1.length, s2.length)
    for (i in 0 until minLen) {
        if (s1[i] != s2[i]) {
            return i
        }
    }
    return if (s1.length == s2.length) -1 else minLen
};1

fun List<Operation>.modifyAndRun(): Int? {
    forEachIndexed { index, operation ->
        when (operation.name) {
            "jmp", "nop" -> {
                val modifiedOperations = toMutableList()
                val modifiedOperationName = when (operation.name) {
                    "jmp" -> "nop"
                    "nop" -> "jmp"
                    else -> operation.name
                }
                modifiedOperations[index] = Operation(modifiedOperationName, operation.argument)

                val program = Program(modifiedOperations)
                val result = program.run()

                if (program.terminated()) {
                    return result
                }
            }
        }
    }
    return null
};0

/**
 * Edits text via carrying lines which are longer than size.
 * @param text text which will be edited.
 * @param size maximal acceptable length of a line.
 * @return edited text, each line in it is not longer than size. Words can be cut in the middle.
 */
fun chompToSize(text: String, size: Int): StringBuilder {
    val stringBuilder = StringBuilder()

    for (_line in text.lines()) {
        var line = _line
        while (line.isNotEmpty())
            if (size >= line.length) {
                stringBuilder.append(line)
                break
            } else {
                var part = line.substring(0, size)
                if (part.lastIndexOf(" ") != -1) {
                    line = line.substring(part.lastIndexOf(" ") + 1)
                    part = (if (part.lastIndexOf(" ") == 0)
                        part.substring(1)
                    else
                        part.substring(0, part.lastIndexOf(" ")))
                } else
                    line = line.substring(size)
                stringBuilder.append(part).append("\n")
            }
        stringBuilder.append("\n")
    }

    return stringBuilder
};0

 
infix fun Int.ipow(exp: Int): Int =
    when {
        this ==  1 -> 1
        this == -1 -> if (exp and 1 == 0) 1 else -1
        exp <  0   -> throw IllegalArgumentException("invalid exponent")
        exp == 0   -> 1
        else       -> {
            var ans = 1
            var base = this
            var e = exp
            while (e > 1) {
                if (e and 1 == 1) ans *= base
                e = e shr 1
                base *= base
            }
            ans * base
        }
    }
 
infix fun Double.dpow(exp: Int): Double {
    var ans = 1.0
    var e   = exp
    var base = if (e < 0) 1.0 / this else this
    if (e < 0) e = -e
    while (e > 0) {
        if (e and 1 == 1) ans *= base
        e = e shr 1
        base *= base
    }
    return ans
}
 
fun main(args: Array<String>) {
    println("2  ^ 3   = ${2 ipow 3}")
    println("1  ^ -10 = ${1 ipow -10}")
    println("-1 ^ -3  = ${-1 ipow -3}")
    println()
    println("2.0 ^ -3 = ${2.0 dpow -3}")
    println("1.5 ^ 0  = ${1.5 dpow 0}")
    println("4.5 ^ 2  = ${4.5 dpow 2}")
};0

