fun calculateCosineSimilarity(vector1: List<Double>, vector2: List<Double>): Double {
    // Überprüfen, ob die Vektoren gleiche Länge haben
    if (vector1.size != vector2.size) {
        throw IllegalArgumentException("Vectors must be of the same length.")
    }

    // Skalarprodukt berechnen
    val dotProduct = vector1.zip(vector2).sumByDouble { (a, b) -> a * b }

    // Beträge berechnen
    val magnitude1 = sqrt(vector1.sumByDouble { it * it })
    val magnitude2 = sqrt(vector2.sumByDouble { it * it })

    // Falls ein Betrag 0 ist, Fehler werfen
    if (magnitude1 == 0.0 || magnitude2 == 0.0) {
        throw IllegalArgumentException("Cosine similarity is undefined for zero-magnitude vectors.")
    }

    // Kosinus-Ähnlichkeit berechnen
    return dotProduct / (magnitude1 * magnitude2)
};1

fun calculateStudentGrade(name: String, rollNo: Int, marks: List<Int>): String {
    /*
    Calculate the grade of a student based on five subject marks.

    Parameters
    ----------
    name : String
        Student's name (not used for calculation, but kept for completeness).
    rollNo : Int
        Student's roll number (not used for calculation, but kept for completeness).
    marks : List<Int>
        A list containing exactly five integer marks (typically in the range 0–100).

    Returns
    -------
    String
        The letter grade of the student:
            - 'A' for an average >= 90
            - 'B' for an average >= 80 and < 90
            - 'C' for an average >= 70 and < 80
            - 'D' for an average >= 60 and < 70
            - 'F' for an average < 60
    */
    if (marks.size != 5) {
        throw IllegalArgumentException("Exactly five marks must be provided.")
    }

    for (m in marks) {
        // Kotlin lists are typed, so all will be Int. If later you get generic input, use smart cast.
        if (m < 0) {
            throw IllegalArgumentException("Marks cannot be negative.")
        }
    }

    val averageScore = marks.sum().toDouble() / marks.size

    val grade = when {
        averageScore >= 90 -> "A"
        averageScore >= 80 -> "B"
        averageScore >= 70 -> "C"
        averageScore >= 60 -> "D"
        else -> "F"
    }
    return grade
};1

