import kotlin.math.sqrt
 
const val n = 200
const val header = "\nSides          P   A"
 
fun gcd(a: Int, b: Int): Int {
    var dividend = a
    var divisor = b
    var leftover = 1
    if (a < b) {
        dividend = b
        divisor = a
    }
 
    while (leftover!= 0) {
        leftover = dividend % divisor
        if (leftover > 0) {
            dividend = divisor
            divisor = leftover
        }
    }
    return divisor
}
 
fun is_heron(h: Double): Boolean {
    return h > 0 && h % 1 == 0.0
}
 
fun main() {
    val l = mutableListOf<List<Int>>()
    for (c in 1..n) {
        for (b in 1..c) {
            for (a in 1..b) {
                if (gcd(gcd(a, b), c) == 1) {
                    val p = a + b + c
                    val s = p / 2.0
                    val area = sqrt(s * (s - a.toDouble()) * (s - b.toDouble()) * (s - c.toDouble()))
                    if (is_heron(area)) {
                        l.add(listOf(a, b, c, p, area.toInt()))
                    }
                }
            }
        }
    }
 
    println("Number of primitive Heronian triangles with sides up to $n: ${l.size}")
    l.sortBy { it[4] }
    println("\n\nFirst ten when ordered by increasing area, then perimeter:" + header)
    for (i in 0..9) { println(l[i]) }
 
    val a = 210
    println("\n\nArea = $a$header")
    for (it in l) {
        if (it[4] == a) {
            println(it)
        }
    }
};1

