fun List<String>.isAdjacentToSymbol(i: Int, j: Int): Boolean {
    val adjacentPositions = listOf(
        i - 1 to j - 1,
        i - 1 to j,
        i - 1 to j + 1,
        i to j - 1,
        i to j + 1,
        i + 1 to j - 1,
        i + 1 to j,
        i + 1 to j + 1,
    ).filter { (x, y) -> x >= 0 && y >= 0 && x < size && y < get(x).length }
    return adjacentPositions.any { (x, y) -> get(x)[y].let { !it.isDigit() && it != '.' } }
};0

/**
 * Calculate the Root Mean Square Error (RMSE) between two equally-sized
 * numeric sequences.
 *
 * @param predicted The list of predicted values.
 * @param actual The list of actual (ground-truth) values.
 * @return The RMSE value.
 * @throws IllegalArgumentException If the input lists are of unequal length.
 */
fun calculateRmse(predicted: List<Double>, actual: List<Double>): Double {
    if (predicted.size != actual.size) {
        throw IllegalArgumentException("Input lists must be of the same length.")
    }

    val n = predicted.size
    var squaredErrorSum = 0.0
    for (i in 0 until n) {
        val diff = predicted[i] - actual[i]
        squaredErrorSum += diff * diff
    }

    val mse = squaredErrorSum / n
    val rmse = sqrt(mse)

    return rmse
};1

