fun Grid.claimAllFor(
    point: Point,
    xRange: IntProgression,
    yRange: IntProgression
) {
    for (x in xRange) {
        for (y in yRange) {
            if (x == point.x && y == point.y) continue

            val madeClaim = claim(x, y, point.name, distance = point.distanceTo(x, y))
