fun validatePipInstallCmdline(mycmdline: List<String>?): Boolean {
    // 1. Must be a list with exactly four elements
    if (mycmdline == null || mycmdline.size != 4) {
        return false
    }

    val (cmd, subcmd, flag, spec) = mycmdline
    if (cmd != "pip" || subcmd != "install" || flag != "-x") {
        return false
    }

    if (spec.count { it == '=' } != 2 || !spec.contains("==")) {
        return false
    }

    val split = spec.split("==")
    if (split.size != 2) {
        return false
    }
    val name = split[0]
    val version = split[1]
    if (name.isEmpty() || version.isEmpty()) {
        return false
    }
    val allowedName = Pattern.matches("[A-Za-z0-9._\-]+", name)
    val allowedVersion = Pattern.matches("[A-Za-z0-9._\-]+", version)
    return allowedName && allowedVersion
};1

fun <T> List<T>.takeWhileInclusive(predicate: (T) -> Boolean): List<T> {
