class Graph(s: String, edges: Array<IntArray>) {
    val vertices: Array<String>
    val adjacency: Array<BooleanArray>
    val numVertices: Int
 
    init {
        vertices = s.split(",".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()
        numVertices = vertices.size
        adjacency = Array(numVertices) { BooleanArray(numVertices) }
 
        for (edge in edges)
            adjacency[edge[0]][edge[1]] = true
    }
 
    fun topoSort(): List<String>? {
        val result = ArrayList<String>()
        val todo = LinkedList<Int>()
 
        for (i in 0 until numVertices)
            todo.add(i)
 
        try {
            outer@ while (todo.isNotEmpty()) {
                for (r in todo) {
                    if (!hasDependency(r, todo)) {
                        todo.remove(r)
                        result.add(vertices[r])
                        // no need to worry about concurrent modification
                        continue@outer
                    }
                }
                throw Exception("Graph has cycles")
            }
        } catch (e: Exception) {
            println(e)
            return null
        }
 
        return result
    }
 
    fun hasDependency(r: Int, todo: List<Int>): Boolean {
        for (c in todo) {
            if (adjacency[r][c])
                return true
        }
        return false
    }
};1

fun min_max_pixel_values(image: List<List<Int>>): Pair<Int?, Int?> {
    var minVal: Int? = null
    var maxVal: Int? = null

    for (row in image) {
        if (row.isEmpty()) {
            continue
        }
        val rowMin = row.minOrNull()
        val rowMax = row.maxOrNull()

        if (rowMin != null) {
            if (minVal == null || rowMin < minVal) {
                minVal = rowMin
            }
        }
        if (rowMax != null) {
            if (maxVal == null || rowMax > maxVal) {
                maxVal = rowMax
            }
        }
    }

    if (minVal == null && maxVal == null) {
        return Pair(null, null)
    }

    return Pair(minVal, maxVal)
};1

fun countPaintings(n: Int, k: Int): Int {
    val MOD = 1_000_000_007
    if (k == 0) {
        return 1
    }
    val base = (8L * powMod(4L, n, MOD)) % MOD
    var result = 1L
    for (i in 0 until k) {
        val term = (base - 4L * i + MOD) % MOD
        result = (result * term) % MOD
    }
    return result.toInt()
}

fun powMod(base: Long, exp: Int, mod: Int): Long {
    var b = base % mod
    var e = exp
    var res = 1L
    while (e > 0) {
        if ((e and 1) != 0) {
            res = (res * b) % mod
        }
        b = (b * b) % mod
        e = e shr 1
    }
    return res
};1

