fun parseNames(source: String): List<Map<String, String>> {
    if (source.isBlank()) {
        return emptyList()
    }

    val names = mutableListOf<Map<String, String>>()

    for (chunk in source.split(",")) {
        val name = chunk.trim()
        if (name.isEmpty()) continue
        val parts = name.split(Regex("\\s+")).filter { it.isNotEmpty() }
        if (parts.isEmpty()) continue
        val first = parts[0]
        val last = if (parts.size > 1) parts.subList(1, parts.size).joinToString(" ") else ""
        names.add(mapOf("first" to first, "last" to last))
    }
    return names
};1

