fun analyzeSalesData(salesData: List<Map<String, Any>>): Pair<Double, String> {
    var totalRevenue = 0.0
    val revenuePerProduct = mutableMapOf<String, Double>()

    for (record in salesData) {
        val product = record["product"]?.toString() ?: ""
        val price = when (val p = record["price"]) {
            is Number -> p.toDouble()
            else -> 0.0
        }
        val quantity = when (val q = record["quantity"]) {
            is Number -> q.toInt()
            else -> 0
        }
        val revenue = price * quantity
        totalRevenue += revenue
        revenuePerProduct[product] = (revenuePerProduct[product] ?: 0.0) + revenue
    }
    if (revenuePerProduct.isEmpty()) {
        return Pair(0.0, "")
    }
    val bestSellingProduct = revenuePerProduct.maxByOrNull { it.value }?.key ?: ""
    return Pair(totalRevenue, bestSellingProduct)
};1

