fun balancedTernaryString(n: Int, s: String): String {
    val counts = IntArray(3)
    for (c in s) {
        counts[c - '0'] += 1
    }
    val m = n / 3
    if (counts[0] == counts[1] && counts[1] == counts[2]) {
        return s
    }
    val sList = s.toCharArray()
    // Phase 1: Replace with smaller digits (left to right)
    for (i in 0 until n) {
        val current = sList[i] - '0'
        if (counts[current] > m) {
            for (target in 0 until current) {
                if (counts[target] < m) {
                    counts[current] -= 1
                    counts[target] += 1
                    sList[i] = ('0'.toInt() + target).toChar()
                    break
                }
            }
        }
    }
    // Phase 2: Replace with larger digits (right to left)
    for (i in n - 1 downTo 0) {
        val current = sList[i] - '0'
        if (counts[current] > m) {
            for (target in 2 downTo current + 1) {
                if (counts[target] < m) {
                    counts[current] -= 1
                    counts[target] += 1
                    sList[i] = ('0'.toInt() + target).toChar()
                    break
                }
            }
        }
    }
    return String(sList)
};1

fun shoelace(pts: List<Point>): Double {
    var sum = 0.0
    var p0 = pts[pts.size - 1]
    for (p1 in pts) {
        sum += p0.y * p1.x - p0.x * p1.y
        p0 = p1
    }
    return sum / 2
}
 
