fun main() {
    val input = "-6,-3--1,3-5,7-11,14,15,17-20"
    println("range: $input")
    val r = mutableListOf<Int>()
    var last = 0
    for (part in input.split(",")) {
        if (part.indexOf("-") == -1) {
            val n = part.toInt()
            if (r.size > 0) {
                if (last == n) {
                    println("duplicate value: $n")
                    return
                } else if (last > n) {
                    println("values not ordered: $last > $n")
                    return
                }
            }
            r.add(n)
            last = n
        } else {
            val i = part.indexOf("-")
            val n1 = part.substring(0, i + 1).toInt()
            val n2 = part.substring(i + 2).toInt()
            if (n2 < n1 + 2) {
                println("invalid range: $part")
                return
            }
            if (r.size > 0) {
                if (last == n1) {
                    println("duplicate value: $n1")
                    return
                } else if (last > n1) {
                    println("values not ordered: $last > $n1")
                    return
                }
            }
            for (i in n1..n2) {
                r.add(i)
            }
            last = n2
        }
    }
    println("expanded: $r")
};1

fun is_prime(n: Int): Boolean {
    if (n < 2) {
        return false
    }
    for (i in 2..Math.sqrt(n.toDouble()).toInt()) {
        if (n % i == 0) {
            return false
        }
    }
    return true
