fun main(args: Array<String>) {
  val head = if (args.size > 0) args[0].toInt() else 10
  val file = if (args.size > 1) File(args[1]) else null
  val counts = HashMap<String, Int>()
  val word = StringBuilder()
  val alpha = { c: Char -> c in 'A'..'Z' || c in 'a'..'z' }
  val lower = { c: Char -> c.toLowerCase() }
  val it = if (file!= null) file.inputStream().bufferedReader() else System.`in`.bufferedReader()
  for (c in it.readText()) {
    if (alpha(c)) {
      word.append(lower(c))
    } else if (word.isNotEmpty()) {
      counts[word.toString()] = counts.getOrDefault(word.toString(), 0) + 1
      word.setLength(0)
    }
  }
  if (word.isNotEmpty()) counts[word.toString()] = counts.getOrDefault(word.toString(), 0) + 1
  val out = ArrayList<Map.Entry<String, Int>>()
  for (count in counts) out.add(count)
  out.sortWith(Comparator { a, b -> b.value - a.value })
  if (out.size > head) out.subList(head, out.size).clear()
  for (count in out) {
    println("${count.key} ${count.value}")
  }
};1

