val PLAUSIBILITY_RATIO = 2
 
fun plausibilityCheck(comment: String, x: Int, y: Int): Boolean {
    println("\n  Checking plausibility of: $comment")
    if (x > PLAUSIBILITY_RATIO * y) {
        println("    PLAUSIBLE. As we have counts of $x vs $y, a ratio of ${x / y} times")
    } else {
        if (x > y) {
            println("    IMPLAUSIBLE. As although we have counts of $x vs $y, a ratio of ${x / y} times does not make it plausible")
        } else {
            println("    IMPLAUSIBLE, probably contra-indicated. As we have counts of $x vs $y, a ratio of ${x / y} times")
        }
    }
    return x > PLAUSIBILITY_RATIO * y
}
 
fun simpleStats(url: String = "http://wiki.puzzlers.org/pub/wordlists/unixdict.txt"): Pair<Int, Int> {
    val words = URL(url).readText().toLowerCase().split(" ")
    val cie = words.filter { "cie" in it }.size
    val cei = words.filter { "cei" in it }.size
    val notCie = words.filter { Pattern.compile("(^ie|[^c]ie)").matcher(it).find() }.size
    val notCei = words.filter { Pattern.compile("(^ei|[^c]ei)").matcher(it).find() }.size
    return Pair(cei, cie)
}
 
