        println("\nOVERALL IT IS PLAUSIBLE!")
    } else {
        println("\nOVERALL IT IS IMPLAUSIBLE!")
    }
    println("(To be plausible, one count must exceed another by $PLAUSIBILITY_RATIO times)")
}
 
