fun primeFactorization(n: Int): String {
    var num = n
    val factors = mutableListOf<Int>()
    var d = 2
    while (d * d <= num) {
        while (num % d == 0) {
            factors.add(d)
            num /= d
        }
        d += 1
    }
    if (num > 1) {
        factors.add(num)
    }
    return factors.joinToString(" ")
};1

