import java.util.Arrays
 
class Factors(var list: IntArray, var count: Int)
 
fun xferFactors(fctrs: Factors, flist: IntArray, flix: Int) {
    var ix: Int
    var ij: Int
    val newSize = fctrs.count + flix
    if (newSize > flix) {
        fctrs.list = Arrays.copyOf(fctrs.list, newSize)
    } else {
        fctrs.list = IntArray(newSize)
    }
    for (ij in 0 until flix) {
        ix = fctrs.count + ij
        fctrs.list[ix] = flist[ij]
    }
    fctrs.count = newSize
}
 
fun factor(num: Int, fctrs: Factors): Factors {
    val flist = IntArray(301)
    var flix = 0
    fctrs.count = 0
    fctrs.list = IntArray(0)
    var dvsr: Int
    for (dvsr in 1..num) {
        if (num % dvsr!= 0) continue
        if (flix == 300) {
            xferFactors(fctrs, flist, flix)
            flix = 0
        }
        flist[flix++] = dvsr
        flist[flix++] = num / dvsr
    }
    if (dvsr * dvsr == num)
        flist[flix++] = dvsr
    if (flix > 0)
        xferFactors(fctrs, flist, flix)
    return fctrs
}
 
