fun zz(n: Int): List<Int> {
    val r = MutableList(n * n) { 0 }
    var i = 0
    val n2 = n * 2
    for (d in 1..n2) {
        val x = d - n
        val y = d - 1
        val j = n2 - d
        if (j > d) {
            for (k in 0 until j) {
                if (d and 1 == 0) {
                    r[(x + k) * n + y - k] = i
                } else {
                    r[(y - k) * n + x + k] = i
                }
                i++
            }
        }
    }
    return r
}
 
