fun Grid<Rock>.rollWest() {
    for (y in minY..maxY) {
        for (x in minX..maxX) {
            if (this[x,y] == Rock.ROUND) {
                var dest = y
                while (dest > 0 && this[x,dest-1] == Rock.BLANK) dest--
                this[x,y] = Rock.BLANK
                this[x,dest] = Rock.ROUND
            }
        }
    }
