fun maximumSuitCost(a: Int, b: Int, c: Int, d: Int, e: Int, f: Int): Int {
    // We can produce at most min(a, d) suits of type 1 (tie + jacket)
    // and min(b, c, d) suits of type 2 (scarf + vest + jacket)
    // However, jackets are shared between both types; we must optimize for value
    return if (e > f) {
        // Make type 1 suits first (they are more valuable)
        val type1 = minOf(a, d)
        val jacketsLeft = d - type1
        val type2 = minOf(b, c, jacketsLeft)
        type1 * e + type2 * f
    } else {
        // Make type 2 suits first (they are more valuable or equal)
        val type2 = minOf(b, c, d)
        val jacketsLeft = d - type2
        val type1 = minOf(a, jacketsLeft)
        type1 * e + type2 * f
    }
};1

 
