import java.math.BigInteger
 
class DigitalRoot {
    fun calcDigitalRoot(number: String, base: Int): IntArray {
        var bi = BigInteger(number, base)
        var additivePersistence = 0
        if (bi.signum() < 0) {
            bi = bi.negate()
        }
        var biBase = BigInteger.valueOf(base.toLong())
        while (bi.compareTo(biBase) >= 0) {
            number = bi.toString(base)
            bi = BigInteger.ZERO
            for (i in 0 until number.length) {
                bi = bi.add(BigInteger(number.substring(i, i + 1), base))
            }
            additivePersistence++
        }
        return intArrayOf(additivePersistence, bi.intValue())
    }
 
    fun main(args: Array<String>) {
        for (arg in args) {
            val results = calcDigitalRoot(arg, 10)
            println(arg + " has additive persistence " + results[0] + " and digital root of " + results[1])
        }
    }
};1

