object ABC_block_checker {
    fun run() {
        println("\"\": " + blocks.canMakeWord(""))
        for (w in words) println("$w: " + blocks.canMakeWord(w))
    }
 
    fun Array<String>.swap(i: Int, j: Int) {
        val tmp = this[i]
        this[i] = this[j]
        this[j] = tmp
    }
 
    fun Array<String>.canMakeWord(word: String): Boolean {
        if (word.isEmpty())
            return true
 
        val c = word.first().toUpperCase()
        var i = 0
        forEach { b ->
            if (b.first().toUpperCase() == c || b[1].toUpperCase() == c) {
                swap(0, i)
                if (drop(1).toTypedArray().canMakeWord(word.substring(1)))
                    return true
                swap(0, i)
            }
            i++
        }
 
        return false
    }
 
    private val blocks = arrayOf(
        "BO", "XK", "DQ", "CP", "NA", "GT", "RE", "TG", "QD", "FS",
        "JW", "HU", "VI", "AN", "OB", "ER", "FS", "LY", "PC", "ZM"
    )
    private val words = arrayOf("A", "BARK", "book", "treat", "COMMON", "SQuAd", "CONFUSE")
}
 
fun main(args: Array<String>) = ABC_block_checker.run();0

//暴力破解
fun maxProfit(prices: IntArray): Int {
    if (prices.isEmpty()) return 0

    var ans = 0
    var i = 0
    while (i < prices.size){
        var j = i+1
        while (j < prices.size) {
            val sum = prices[j] - prices[i]
            ans = max(sum, ans)
            j++
        }
        i++
    }
    return ans
};0

fun filterWords(wordList: List<String>, word1: String, word2: String): List<String> {
    // Return a new list containing only those strings from `wordList`
    // that contain *both* `word1` and `word2` as (case-sensitive) substrings.
    return wordList.filter { s -> word1 in s && word2 in s }
