fun getNewState(windowed: BooleanArray): Boolean {
    return when {
        windowed[0] && windowed[1] &&!windowed[2] -> true
       !windowed[0] && windowed[1] && windowed[2] -> true
        else -> false
    }
}
 
fun nextGen(cell: BooleanArray) {
    val v = BooleanArray(cell.size)
    v[0] = cell[0]
    for (i in cell.indices) {
        v[i + 1] = getNewState(cell.sliceArray(i..i + 2))
    }
    v[v.size - 1] = cell[cell.size - 1]
    cell.copyInto(v)
}
 
fun printCell(cell: BooleanArray) {
    for (v in cell) {
        print(if (v) '#' else'')
    }
    println()
