import kotlin.math.sum
 
fun equilibriumIndices(v: IntArray): List<Int> {
    var right = v.sum()
    var left = 0
 
    return v.indices.fold(mutableListOf()) { out, i ->
        right -= v[i]
        if (left == right) {
            out.add(i)
        }
        left += v[i]
 
        out
    }
}
 
