fun calculate(num1: Double, num2: Double, operation: String): Any {
    // Normalize the operation string to lower-case to allow case-insensitive input
    when (operation.lowercase()) {
        "add" -> return num1 + num2
        "subtract" -> return num1 - num2
        "multiply" -> return num1 * num2
        "divide" -> {
            if (num2 == 0.0) return "Error: Division by zero"
            return num1 / num2
        }
        else -> throw IllegalArgumentException("Unsupported operation '$operation'. Use 'add', 'subtract', 'multiply', or 'divide'.")
    }
};1

