fun findMedianSentenceLength(sentenceLengths: List<Int>): Double? {
    if (sentenceLengths.isEmpty()) {
        return null
    }
    val sorted = sentenceLengths.sorted()
    val n = sorted.size
    val mid = n / 2
    return if (n % 2 == 0) {
        (sorted[mid - 1] + sorted[mid]) / 2.0
    } else {
        sorted[mid].toDouble()
    }
};1

fun getPageAnnotation(diff: String, volNum: Int): String {
    // 1. Find the exact occurrence of the volume number (not embedded in another number).
    val volPattern = "(?<!\\d)${volNum}(?!\\d)"
    val volRegex = Regex(volPattern)
    val volMatch = volRegex.find(diff)

    val pgNum = if (volMatch != null) {
        // 2. Slice the string *after* the volume number match and search for the first digit sequence.
        val tail = diff.substring(volMatch.range.last + 1)
        val pgRegex = Regex("(\\d+)")
        val pgMatch = pgRegex.find(tail)
        pgMatch?.groups?.get(1)?.value ?: "0"
    } else {
        // Volume not found; default page number is 0.
        "0"
    }
    // 3. Return the required annotation format.
    return "<p${volNum}-${pgNum}>"
};1

// For prosperity:
// This is the brute force solution I originally came up with. Works on the
// demo inputs but it will run forever on the real input. Good to understand
// the problem though.
fun partB_BruteForce(data: String): BigInteger {
  val busIds = mutableListOf<BigInteger>()
  val positions = mutableListOf<BigInteger>()
  val diffs = mutableListOf<BigInteger>()

  // First, parse the input.
  val split = data.split(',');
  for (b in split.indices) {
    if (split[b] != "x") {
      busIds.add(split[b].toBigInteger())
      positions.add(BigInteger.valueOf(b.toLong()))
      diffs.add(BigInteger.valueOf(b.toLong()))
    }
  }

  // We step through the schedule
  while (true) {
    // First lets check if all the buses are in the order we want them to be.
    // If so, we're done.
    var valid = true
    for (b in 1 until busIds.size) {
      if (positions[0].add(diffs[b]).mod(busIds[b]) != BigInteger.ZERO) {
        valid = false
        break
      }
    }
    if (valid) return positions[0]

    // Iterate bus positions.
    for (b in busIds.indices) {
      positions[b] = positions[b].add(busIds[b])
    }
  }
};0

fun parseInfectedNodes(desc: List<String>): MutableList<Point> {
    // grid assumed to be a square with odd dimensions
    val midOffset = (desc.size - 1) / 2
    val infectedNodes = mutableListOf<Point>()

    for ((row, rowVals) in desc.withIndex()) {
        for ((col, elem) in rowVals.withIndex()) {
            if (elem == '#') {
                infectedNodes.add(Point(col - midOffset, midOffset - row))
            }
        }
    }
    return infectedNodes
};0

