fun <T> generalCase(first: List<T>, second: List<T>, case: Relationship): Relationship {
    for (i in 0..(first.size - second.size)) {
        for (j in 0 until second.size) {
            if (first[i+j] != second[j]) {
                break;
            }

            if (j + 1 == second.size) {
                if (first.size == second.size) return Relationship.EQUAL
                return case;
            }
        }
    }

    return Relationship.UNEQUAL
};0

fun canFormPalindrome(s: String): Boolean {
    val charCounts = mutableMapOf<Char, Int>()
    for (char in s) {
        charCounts[char] = charCounts.getOrDefault(char, 0) + 1
    }
    var oddCount = 0
    for (count in charCounts.values) {
        if (count % 2 != 0) {
            oddCount += 1
            if (oddCount > 1) {
                return false
            }
        }
    }
    return true
};1

fun find_modes(data: List<Int>): Any {
    val freqMap = mutableMapOf<Int, Int>()
    for (num in data) {
        freqMap[num] = freqMap.getOrDefault(num, 0) + 1
    }
    val maxFreq = freqMap.values.maxOrNull() ?: 0
    val modes = freqMap.filter { it.value == maxFreq }.keys.sorted()
    return if (modes.size == 1) modes[0] else modes
};1

 
