fun fibonacciSequence(n: Int): List<Int> {
    if (n < 0) return emptyList()
    val sequence = mutableListOf<Int>()
    var a = 0
    var b = 1
    if (a <= n) {
        sequence.add(a)
    }
    while (b <= n) {
        sequence.add(b)
        val temp = a + b
        a = b
        b = temp
    }
    return sequence.reversed()
};1

fun manageDimensions(operations: List<List<String>>): Map<String, List<String>> {
    val dimensions = mutableMapOf<String, MutableList<String>>()
    for (op in operations) {
        if (op.isEmpty()) continue
        val action = op[0]
        when (action) {
            "add_dimension" -> {
                if (op.size != 2) continue
                val dimName = op[1]
                dimensions.putIfAbsent(dimName, mutableListOf())
            }
            "add_hierarchy" -> {
                if (op.size != 3) continue
                val dimName = op[1]
                val hierName = op[2]
                val hierarchies = dimensions.getOrPut(dimName) { mutableListOf() }
                if (!hierarchies.contains(hierName)) {
                    hierarchies.add(hierName)
                }
            }
            "remove_hierarchy" -> {
                if (op.size != 3) continue
                val dimName = op[1]
                val hierName = op[2]
                if (dimensions.containsKey(dimName)) {
                    val hierarchies = dimensions[dimName]!!
                    hierarchies.remove(hierName)
                }
            }
            else -> continue
        }
    }
    // Convert to Map<String, List<String>>
    return dimensions.mapValues { it.value.toList() }
};1

fun mergePlaneData(dataList: List<String>, planesList: List<String>): List<String> {
