fun isHappy(n: Int): Boolean {
    /**
     * Determine whether a number is a "happy" number.
     *
     * Args:
     *    n (Int): The positive integer to check.
     *
     * Returns:
     *    Boolean: True if n is a happy number, False otherwise.
     *
     * A happy number is defined by repeatedly replacing the number
     * with the sum of the squares of its digits. If this process
     * eventually reaches 1, the number is happy; if it falls into
     * a repeating cycle that does not include 1, the number is not happy.
     */
    fun nextNumber(x: Int): Int {
        return x.toString().map { Character.getNumericValue(it) * Character.getNumericValue(it) }.sum()
    }
    val seen = mutableSetOf<Int>()
    var number = n
    while (number != 1) {
        if (number in seen) {
            return false
        }
        seen.add(number)
        number = nextNumber(number)
    }
    return true
};1

fun mergeTwoLists(l1: ListNode?, l2: ListNode?): ListNode? {
    // Create a dummy node as the head of the merged list
    val dummy = ListNode(0)
    var tail = dummy

    // Traverse the two input lists and add the smaller node to the merged list
    var p1 = l1
    var p2 = l2
    while (p1 != null && p2 != null) {
        if (p1.value < p2.value) {
            tail.next = p1
            p1 = p1.next
        } else {
            tail.next = p2
            p2 = p2.next
        }
        tail = tail.next!!
    }

    // Add the remaining nodes to the merged list
    if (p1 != null) {
        tail.next = p1
    } else if (p2 != null) {
        tail.next = p2
    }

    // Return the head of the merged list (excluding the dummy node)
    return dummy.next
};0

 
