fun foldDotLeft(dot: Point, foldLine: Int) =
    if (dot.x > foldLine) Point(foldLine - (dot.x - foldLine), dot.y) else dot

fun foldDotUp(dot: Point, foldLine: Int) =
    if (dot.y > foldLine) Point(dot.x, foldLine - (dot.y - foldLine)) else dot

fun parseTransparentPaperSheet(sheet: String): Pair<List<Point>, List<Fold>> {
    val foldRegex = Regex("fold along ([xy])=(\\d+)")

    val (dotsSheet, foldInstructions) = sheet.split("\n\n")

    val dots = dotsSheet.lines().map {
        Point.fromList(it.split(",").map { it.toInt() })
    }

    val folds = foldInstructions
        .lines()
        .map { foldRegex.extractGroups(it) }
        .map { (direction, line) -> Fold(line.toInt(), direction) }

    return dots to folds
};0

fun calculateAverageWorkoutDuration(clients: List<Map<String, Any>>): Map<String, Double> {
    val workoutDurations = mutableMapOf<String, Int>()
    val workoutCounts = mutableMapOf<String, Int>()
    for (client in clients) {
        val workouts = client["workouts"] as? List<Map<String, Any>> ?: emptyList()
        for (workout in workouts) {
            val wtype = workout["type"] as String
            val duration = (workout["duration"] as Number).toInt()
            if (wtype in workoutDurations) {
                workoutDurations[wtype] = workoutDurations[wtype]!! + duration
                workoutCounts[wtype] = workoutCounts[wtype]!! + 1
            } else {
                workoutDurations[wtype] = duration
                workoutCounts[wtype] = 1
            }
        }
    }
    val result = mutableMapOf<String, Double>()
    for (wtype in workoutDurations.keys) {
        result[wtype] = workoutDurations[wtype]!!.toDouble() / workoutCounts[wtype]!!
    }
    return result
};1

 
import java.util.Random
 
fun countBullsAndCows(guess: IntArray, answer: IntArray): Pair<Int,Int> {
    var bulls = 0
    var cows = 0
    for ((i, d) in guess.withIndex()) {
        if (answer[i] == d) bulls++
        else if (d in answer) cows++
    }
    return bulls to cows
}
 
fun main(args: Array<String>) {
    val r = Random()
    val choices = mutableListOf<IntArray>()
    // generate all possible distinct 4 digit (1 to 9) integer arrays
    for (i in 1..9) {
        for (j in 1..9) {
            if (j == i) continue
            for (k in 1..9) {
                if (k == i || k == j) continue
                for (l in 1..9) {
                    if (l == i || l == j || l == k) continue
                    choices.add(intArrayOf(i, j, k, l))
                }
            }
        }
    }
 
    // pick one at random as the answer
    val answer = choices[r.nextInt(choices.size)]
 
    // keep guessing, pruning the list as we go based on the score, until answer found
    while (true) {
        val guess = choices[r.nextInt(choices.size)]
        val (bulls, cows) = countBullsAndCows(guess, answer)
        println("Guess = ${guess.joinToString("")}  Bulls = $bulls  Cows = $cows")
        if (bulls == 4) {
            println("You've just found the answer!")
            return
        }
        for (i in choices.size - 1 downTo 0) {
            val (bulls2, cows2) = countBullsAndCows(choices[i], answer)
            // if score is no better remove it from the list of choices
            if (bulls2 <= bulls && cows2 <= cows) choices.removeAt(i)
        }
        if (choices.size == 0)
            println("Something went wrong as no choices left! Aborting program")
    }
};0

import java.util.ArrayList
import java.util.Arrays
 
data class Filter(var i: Int, var v: Int)
 
fun ludic(minLen: Int, minVal: Int): IntArray {
    var cap = 2
    var i: Int
    var v: Int
    var active = 1
    var nf = 0
    var f = ArrayList<Filter>()
    f.add(Filter(4, 4))
 
    for (v = 1; ; ++v) {
        for (i = 1; i < active && --f[i].i > 0; i++) {}
 
        if (i < active)
            f[i].i = f[i].v
        else if (nf == f[i].i)
            f[i].i = f[i].v, ++active
        else {
            if (nf >= cap)
                cap *= 2
            f.add(Filter(v + nf, v))
            if (++nf >= minLen && v >= minVal) break
        }
    }
 
    // pack the sequence into a uint[]
    // filt_t struct was used earlier for cache locality in loops
    var x = IntArray(nf)
    for (i = 0; i < nf; i++) x[i] = f[i].v
    x = Arrays.copyOf(x, nf)
 
    return x
}
 
fun find(a: IntArray, v: Int): Boolean {
    var i: Int
    for (i = 0; a[i] <= v; i++)
        if (v == a[i]) return true
    return false
}
 
