fun calculateGardenArea(gardenShapes: List<Triple<String, Double, Double?>>): Double {
    var totalArea = 0.0
    for (shapeInfo in gardenShapes) {
        val shapeType = shapeInfo.first
        when (shapeType) {
            "circle" -> {
                val radius = shapeInfo.second
                val area = PI * radius * radius
                totalArea += area
            }
            "rectangle" -> {
                val width = shapeInfo.second
                val height = shapeInfo.third ?: 0.0
                val area = width * height
                totalArea += area
            }
            "triangle" -> {
                val base = shapeInfo.second
                val height = shapeInfo.third ?: 0.0
                val area = 0.5 * base * height
                totalArea += area
            }
        }
    }
    return totalArea
};1

