import java.lang.String
 
class VCipher {
    fun encrypt(txt: String, pw: String, d: Int): String {
        var pwi = 0
        var tmp: Int
        var ns = ""
        txt.toUpperCase()
        pw.toUpperCase()
        for (t in txt) {
            if (t < 65) {
                continue
            }
            tmp = t - 65 + d * (pw[pwi] - 65)
            if (tmp < 0) {
                tmp += 26
            }
            ns += (65 + (tmp % 26)).toChar()
            if (++pwi == pw.length) {
                pwi = 0
            }
        }
 
        return ns
    }
}
 
fun main(args: Array<String>) {
    val v = VCipher()
 
    val s0 = "Beware the Jabberwock, my son! The jaws that bite, the claws that catch!"
    val pw = "VIGENERECIPHER"
 
    println(s0 + "\n" + pw + "\n")
    val s1 = v.encrypt(s0, pw, 1)
    println("Encrypted: " + s1)
    s1 = v.encrypt(s1, "VIGENERECIPHER", -1)
    println("Decrypted: " + s1)
};1

