const val threshold = 1L shl 47
 
fun indexOf(s: List<Long>, search: Long): Int {
    for ((i, e) in s.withIndex()) {
        if (e == search) {
            return i
        }
    }
    return -1
}
 
fun contains(s: List<Long>, search: Long): Boolean {
    return indexOf(s, search) > -1
}
 
fun maxOf(i1: Int, i2: Int): Int {
    return if (i1 > i2) i1 else i2
}
 
fun sumProperDivisors(n: Long): Long {
    if (n < 2) {
        return 0
    }
    val sqrt = sqrt(n.toDouble()).toLong()
    var sum = 1L
    for (i in 2..sqrt) {
        if (n % i!= 0L) {
            continue
        }
        sum += i + n / i
    }
    if (sqrt * sqrt == n) {
        sum -= sqrt
    }
    return sum
}
 
fun classifySequence(k: Long): Pair<List<Long>, String> {
    if (k == 0L) {
        throw IllegalArgumentException("Argument must be positive.")
    }
    var last = k
    val seq = mutableListOf<Long>()
    seq.add(k)
    while (true) {
        last = sumProperDivisors(last)
        seq.add(last)
        val n = seq.size
        var aliquot = ""
        when {
            last == 0L -> aliquot = "Terminating"
            n == 2 && last == k -> aliquot = "Perfect"
            n == 3 && last == k -> aliquot = "Amicable"
            n >= 4 && last == k -> aliquot = "Sociable[${n - 1}]"
            last == seq[n - 2] -> aliquot = "Aspiring"
            contains(seq.subList(1, maxOf(1, n - 2)), last) -> aliquot = "Cyclic[${n - 1 - indexOf(seq, last)}]"
            n == 16 || last > threshold -> aliquot = "Non-Terminating"
        }
        if (aliquot!= "") {
            return Pair(seq, aliquot)
        }
    }
}
 
fun joinWithCommas(seq: List<Long>): String {
    var res = seq.toString()
    res = res.replace(" ", ", ")
    return res
}
 
fun main() {
    println("Aliquot classifications - periods for Sociable/Cyclic in square brackets:\n")
    for (k in 1..10) {
        val (seq, aliquot) = classifySequence(k.toLong())
        println(String.format("%2d: %-15s %s", k, aliquot, joinWithCommas(seq)))
    }
    println()
 
    val s = listOf(11L, 12L, 28L, 496L, 220L, 1184L, 12496L, 1264460L, 790L, 909L, 562L, 1064L, 1488L)
    for (k in s) {
        val (seq, aliquot) = classifySequence(k)
        println(String.format("%7d: %-15s %s", k, aliquot, joinWithCommas(seq)))
    }
    println()
 
    val k = 15355717786080L
    val (seq, aliquot) = classifySequence(k)
    println(String.format("%d: %-15s %s", k, aliquot, joinWithCommas(seq)))
};1

fun solve() {
    readln()
    val s = readln().map { it - 'a' }.toIntArray()
    val count = IntArray(M)
    for (c in s) count[c]++
    val byFreq = count.indices.sortedByDescending { count[it] }
    var answer = s.size + 1
    var answerString = ""
    val a = IntArray(s.size)
    val aCount = IntArray(M)
    for (diff in 1..M) {
        if (s.size % diff != 0) continue
        val need = s.size / diff
        val use = byFreq.take(diff).toSet()
        a.fill(-1)
        aCount.fill(0)
        var current = s.size
        for (i in s.indices) {
            if (s[i] in use && aCount[s[i]] < need) {
                a[i] = s[i]
                aCount[s[i]]++
                current--
            }
        }
        if (current < answer) {
            answer = current
            var j = 0
            for (i in s.indices) {
                if (a[i] != -1) continue
                while (j !in use || aCount[j] == need) j++
                a[i] = j
                aCount[j]++
            }
            answerString = a.joinToString("") { ('a'.code + it).toChar().toString() }
        }
    }
    println(answer)
    println(answerString)
};0

fun largestMultipleOfThree(digits: IntArray): String {
    var sum = 0
    val ds = IntArray(ARRAY_SIZE)
    for (d in digits) {
        ++ds[d]
        sum += d
    }
    while (sum % 3 != 0) {
        val n = if (sum % 3 == 1) m1 else m2
        for (i in n) {
            if (ds[i] > 0) {
                --ds[i]
                sum -= i
                break
            }
        }
    }
    val sb = StringBuilder()
    for (i in ARRAY_SIZE - 1 downTo 0) {
        sb.append(ZERO_CHAR.plus(i).toString().repeat(ds[i]))
    }
    return if (sb.isNotEmpty() && sb[0] == ZERO_CHAR) "0" else sb.toString()
