import java.lang.Math.sqrt
 
fun countDivisors(n: Int): Int {
    var count = 0
    for (i in 1..sqrt(n.toDouble()).toInt()) {
        if (n % i == 0) {
            if (i == n / i) {
                count++
            } else {
                count += 2
            }
        }
    }
    return count
}
 
