    println("The first $MAX terms of the sequence are:")
    var n = 0
    for (i in 1..Int.MAX_VALUE) {
        val k = countDivisors(i)
        if (k <= MAX && seq[k - 1] == 0) {
            seq[k - 1] = i
            n++
        }
        if (n == MAX) {
            break
        }
    }
    for (i in 0 until MAX) {
        print("${seq[i]} ")
    }
    println()
};1

