import kotlin.math.floor
 
const val N = 6364136223846793005L
 
var state = 0x853c49e6748fea9bL
var inc = 0xda3e39cb94b95bdbL
 
fun pcg32_int(): Int {
    val old = state
    state = old * N + inc
    val shifted = (old shr 18 xor old) shr 27
    val rot = old shr 59
    return (shifted shr rot or (shifted shl ((-rot + 1) and 31))) and 0xffffffff
}
 
fun pcg32_float(): Double {
    return pcg32_int().toDouble() / (1L shl 32)
}
 
fun pcg32_seed(seed_state: Long, seed_sequence: Long) {
    state = 0
    inc = (seed_sequence shl 1) or 1
    pcg32_int()
    state = state + seed_state
    pcg32_int()
}
 
fun main() {
    val counts = IntArray(5)
    var i = 0
 
    pcg32_seed(42, 54)
    println(pcg32_int())
    println(pcg32_int())
    println(pcg32_int())
    println(pcg32_int())
    println(pcg32_int())
    println()
 
    pcg32_seed(987654321, 1)
    for (i in 0..99999) {
        val j = floor(pcg32_float() * 5.0).toInt()
        counts[j]++
    }
 
    println("The counts for 100,000 repetitions are:")
    for (i in 0..4) {
        println("  $i : ${counts[i]}")
    }
};1

