/**
 * Find identical pattern elements in the two patterns subject to constraints:
 *
 * 1. matches must be in order i.e., in the patterns a:[x,y] and b:[y,x], pattern elements
 *    x and y cannot both match.
 * 2. every pattern element in the shorter pattern must be allowed to match one element
 *    in the longer pattern.
 */
fun findExactMatchIndices(a : Pattern, b : Pattern) : ArrayList<MatchIndices> {

  val patterns = sort(a, b)
  val left = patterns.first
  val right = patterns.second
  val matches = arrayListOf(MatchIndices(-1, -1))

  left().withIndex().forEach { patternElement ->

    val prevMatchIndex = matches[matches.lastIndex].rightIndex
    val searchRangeStart = Math.max(patternElement.index, prevMatchIndex + 1)
    val searchRangeEnd = right().size - left().size + patternElement.index

    var i = searchRangeStart

    while (i <= searchRangeEnd) {
      if (patternElement.value == right()[i]) {
        matches.add(MatchIndices(patternElement.index, i))
        break
      }
      ++i
    }
  }

  return (matches + arrayListOf(MatchIndices(left().lastIndex+1, right().lastIndex+1)))
    as ArrayList<MatchIndices>
};0

fun parseLineAndComplete(line: String): Long {
    val openerStack: MutableList<Char> = mutableListOf()

    line.forEach {
        if (OPENERS.contains(it)) {
            openerStack.add(it)
        } else {
            val prev = openerStack.last()
            if (CLOSERS.indexOf(it) != OPENERS.indexOf(prev)) {
                return 0
            } else {
                openerStack.removeLast()
            }
        }
    }
    return openerStack.reversed().fold(0) { sum, opener ->
        val openerIndex = OPENERS.indexOf(opener)
        (sum * 5) + GOOD_VALUES.get(openerIndex)
    }
};0

fun getEveryoneAnswers(filename: String): List<Set<Char>> {
    val result = mutableListOf<Set<Char>>()
    var set: Set<Char> = setOf()
    var lineSet: Set<Char>
    var firstPass = true

    readAllLines(filename).map { line ->
        if (line.isBlank()) {
            result.add(set)
            firstPass = true
        } else {
            lineSet = line.toSet()

            if (firstPass) {
                set = lineSet
                firstPass = false
            } else if (set.isNotEmpty()) {
                set = set.intersect(lineSet)
            }
        }
    }

    result.add(set)

    return result
};0

class TreeNode(var `val`: Int = 0, var left: TreeNode? = null, var right: TreeNode? = null)

fun checkBst(root: TreeNode?): Map<String, Int?> {
    fun validate(node: TreeNode?): Triple<Boolean, Int, Int> {
        if (node == null) return Triple(true, Int.MAX_VALUE, Int.MIN_VALUE)
        val (leftValid, leftMin, leftMax) = validate(node.left)
        val (rightValid, rightMin, rightMax) = validate(node.right)
        val currentValid = leftValid && rightValid && (node.`val` > leftMax) && (node.`val` < rightMin)
        return if (currentValid) {
            val currentMin = minOf(leftMin, node.`val`)
            val currentMax = maxOf(rightMax, node.`val`)
            Triple(true, currentMin, currentMax)
        } else {
            Triple(false, 0, 0)
        }
    }
    if (root == null) return mapOf("min" to null, "max" to null)
    val (isValid, minVal, maxVal) = validate(root)
    return if (isValid) {
        mapOf("min" to minVal, "max" to maxVal)
    } else {
        mapOf("min" to null, "max" to null)
    }
};1

