fun countingSort(data: List<Int>, min: Int, max: Int): List<Int> {
    // create and fill counting bucket with 0
    val count = MutableList(data.size) { 0 }
    for (num in data) {
        count[num - min] = count[num - min] + 1
    }
    var z = 0
    for (i in min..max) {
        while (count[i - min] > 0) {
            data[z] = i
            z++
            count[i - min] = count[i - min] - 1
        }
    }
    return data
}
 
