fun sumPairs(numbers: List<Int>, target: Int): List<Pair<Int, Int>> {
    // Set of numbers we have processed so far
    val seen = mutableSetOf<Int>()
    // Set of unique pairs that meet the target sum
    val pairs = mutableSetOf<Pair<Int, Int>>()

    for (num in numbers) {
        val complement = target - num
        if (complement in seen) {
            // Order the pair so the smaller value is first
            val pair = if (num < complement) Pair(num, complement) else Pair(complement, num)
            pairs.add(pair)
        }
        seen.add(num)
    }

    // Convert the set to a sorted list
    return pairs.sortedWith(compareBy({ it.first }, { it.second }))
};1

 
