fun OneArray<Int>.los(): Int {
    val A = this
    val n = size

    // los(i): len of los of A[i..n] that MUST include A[i]
    // loos(i): len of loos of A[i..n] that MUST include A[i]
    //          where loos of X[1..n] satisfies the reversed condition of los of X
    // memoization structure: two 1d arrs, los[1..n], loos[1..n]
    val los = OneArray(n) { 1 }
    val loos = OneArray(n) { 1 }

    // assuming max { } = 0
    // los(i) = 1 + max_k { loos(k) } where k > i and A[k] < A[i]
    // loos(i) = 1 + max_k { los(k) } where k > i and A[k] > A[i]
    // dependency: los(i), loos(i) depends on loos(k), los(k), where k > i
    //             that is, entries to the right
    // eval order: outer loop for i decreasing from n - 1 down to 1
    for (i in n - 1 downTo 1) {
        // inner loop k with no specific order, say increasing from i + 1 to n
        los[i] = 1 + ((i + 1..n)
                .filter { k -> A[k] < A[i] }
                .map { k -> loos[k] }
                .max() ?: 0)
        loos[i] = 1 + ((i + 1..n)
                .filter { k -> A[k] > A[i] }
                .map { k -> los[k] }
                .max() ?: 0)
    }
    // time: O(n^2)

//  los.prettyPrintln()
//  loos.prettyPrintln()

    // we want max_i { los(i) }
    return los.max() ?: 0
};0

val VALID_OSES = setOf("linux", "windows", "macos")
val VALID_ARCHES = setOf("amd64", "arm", "x86")
val VALID_VARIANTS = setOf("server", "desktop")

fun validatePlatform(platform: String): Triple<String, String, String?> {
    val parts = platform.trim().split('/')
    if (parts.size != 2 && parts.size != 3) {
        throw IllegalArgumentException("Platform must be in the format 'OS/ARCH' or 'OS/ARCH/VARIANT'")
    }
    val osPart = parts[0].lowercase()
    val archPart = parts[1].lowercase()
    val variantPart: String? = if (parts.size == 3) parts[2].lowercase() else null

    if (osPart !in VALID_OSES) {
        throw IllegalArgumentException("Invalid OS '$osPart'. Valid options: ${VALID_OSES.sorted()}")
    }
    if (archPart !in VALID_ARCHES) {
        throw IllegalArgumentException("Invalid architecture '$archPart'. Valid options: ${VALID_ARCHES.sorted()}")
    }
    if (variantPart != null && variantPart !in VALID_VARIANTS) {
        throw IllegalArgumentException("Invalid variant '$variantPart'. Valid options: ${VALID_VARIANTS.sorted()}")
    }
    return Triple(osPart, archPart, variantPart)
};1

fun goRight(currentState: RopeState, visitedByTail: MutableSet<Point>, steps: Int): RopeState {
    var newState = currentState
    for (step in 1..steps) {
        val head = newState.head.right()
        var tail = newState.tail
        if ((tail.x - head.x).absoluteValue > 1) {
            tail = if (head.y == tail.y) {
                tail.right()
            } else {
                if (head.y > tail.y) {
                    tail.up().right()
                } else {
                    tail.down().right()
                }
            }
            visitedByTail.add(tail)
        }
        newState = RopeState(head, tail)
    }

    return newState
};0

