fun createArrayMoreEfficientWithDivision(arr: IntArray): IntArray {
    val product = arr.reduce { acc, v -> acc * v }
    val result = IntArray(arr.size)
    for ((i, v) in arr.withIndex()) {
        result[i] = product / v
    }

