fun scheduleScreenings(screenings: List<Pair<String, String>>): List<Pair<String, String>> {
    val sortedScreenings = screenings.sortedBy { it.second }
    val schedule = mutableListOf<Pair<String, String>>()
    var currentEnd = "00:00"
    for ((start, end) in sortedScreenings) {
        if (start >= currentEnd) {
            schedule.add(Pair(start, end))
            currentEnd = end
        }
    }
    return schedule
