fun minimalRotation(s: String): String {
    val n = s.length
    if (n == 0) return s
    var minRot = s
    for (i in 1 until n) {
        val current = s.substring(i) + s.substring(0, i)
        if (current < minRot) {
            minRot = current
        }
    }
    return minRot
};1

fun reflect(s: String): String {
