fun manageWords(words: List<String>, newWords: List<String>): List<String> {
    // Use a mutable set to guarantee uniqueness.
    val uniqueWords = words.toMutableSet()
    uniqueWords.addAll(newWords)
    // Return as a sorted list (ascending lexicographical order).
    return uniqueWords.sorted()
