import kotlin.math.*
 
object Sphere {
    private const val shades = ".:!*oe%&#@"
    private val light = doubleArrayOf(30.0, 30.0, -50.0)
 
    fun normalize(v: DoubleArray) {
        val len = sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2])
        v[0] /= len
        v[1] /= len
        v[2] /= len
    }
 
    fun dot(x: DoubleArray, y: DoubleArray): Double {
        val d = x[0] * y[0] + x[1] * y[1] + x[2] * y[2]
        return if (d < 0) -d else 0.0
    }
 
    fun drawSphere(r: Double, k: Double, ambient: Double) {
        val vec = DoubleArray(3)
        for (i in floor(r).toInt()..ceil(r).toInt()) {
            val x = i + 0.5
            for (j in floor(-2 * r).toInt()..ceil(2 * r).toInt()) {
                val y = j / 2.0 + 0.5
                if (x * x + y * y <= r * r) {
                    vec[0] = x
                    vec[1] = y
                    vec[2] = sqrt(r * r - x * x - y * y)
                    normalize(vec)
                    val b = pow(dot(light, vec), k) + ambient
                    val intensity = if (b <= 0) shades.length - 2 else max(1 - b * (shades.length - 1), 0.0).toInt()
                    print(shades[intensity])
                } else
                    print(' ')
            }
            println()
        }
    }
}
 
fun main() {
    Sphere.normalize(Sphere.light)
    Sphere.drawSphere(6.0, 4.0, 0.1)
    Sphere.drawSphere(10.0, 2.0, 0.4)
};1

