fun analyzeTranscript(transcript: String, keywords: List<String>): Map<String, Int> {
    val counts = mutableMapOf<String, Int>()
    val transcriptLower = transcript.lowercase()
    for (kw in keywords) {
        // \b for word boundaries, escape keyword for special characters
        val pattern = Pattern.compile("\\b" + Pattern.quote(kw.lowercase()) + "\\b")
        val matcher = pattern.matcher(transcriptLower)
        var found = 0
        while (matcher.find()) {
            found += 1
        }
        counts[kw] = found
    }
    return counts
