fun simulateTennisGame(pointsWon: List<String>): Pair<Int, Int> {
    var scoreA = 0
    var scoreB = 0
    var gamesWonA = 0
    var gamesWonB = 0
    for (point in pointsWon) {
        if (point == "Player A") {
            scoreA += 1
        } else {
            scoreB += 1
        }
        if (scoreA >= 4 && scoreA >= scoreB + 2) {
            gamesWonA += 1
            scoreA = 0
            scoreB = 0
        } else if (scoreB >= 4 && scoreB >= scoreA + 2) {
            gamesWonB += 1
            scoreA = 0
            scoreB = 0
        }
    }
    return Pair(gamesWonA, gamesWonB)
};1

fun rearrangeList(lst: List<Int>): List<Int> {
