fun countIslands(datasets: List<List<String>>): List<Int> {
    val result = mutableListOf<Int>()
    for (dataset in datasets) {
        val grid = Array(12) { IntArray(12) }
        for (i in 0 until 12) {
            for (j in 0 until 12) {
                grid[i][j] = dataset[i][j].toString().toInt()
            }
        }
        val visited = Array(12) { BooleanArray(12) }
        var count = 0
        for (i in 0 until 12) {
            for (j in 0 until 12) {
                if (grid[i][j] == 1 && !visited[i][j]) {
                    val q: ArrayDeque<Pair<Int, Int>> = ArrayDeque()
                    q.add(Pair(i, j))
                    visited[i][j] = true
                    while (q.isNotEmpty()) {
                        val (x, y) = q.removeFirst()
                        for ((dx, dy) in listOf(Pair(-1, 0), Pair(1, 0), Pair(0, -1), Pair(0, 1))) {
                            val nx = x + dx
                            val ny = y + dy
                            if (nx in 0..11 && ny in 0..11 && grid[nx][ny] == 1 && !visited[nx][ny]) {
                                visited[nx][ny] = true
                                q.add(Pair(nx, ny))
                            }
                        }
                    }
                    count++
                }
            }
        }
        result.add(count)
    }
    return result
};1

 
import java.util.LinkedList
 
class Queue<E> {
    private val data = LinkedList<E>()
 
    val size get() = data.size
 
    val empty get() = size == 0
 
    fun push(element: E) = data.add(element)
 
    fun pop(): E {
        if (empty) throw RuntimeException("Can't pop elements from an empty queue")
        return data.removeFirst()
    }
 
   val top: E
        get() {
            if (empty) throw RuntimeException("Empty queue can't have a top element")
            return data.first()
        }
 
    fun clear() = data.clear()
 
    fun toString() = data.toString()
}
 
fun main(args: Array<String>) {
    val q = Queue<Int>()
    (1..5).forEach { q.push(it) }
    println(q)
    println("Size of queue = ${q.size}")
    print("Popping: ")
    (1..3).forEach { print("${q.pop()} ") }
    println("\nRemaining in queue: $q")
    println("Top element is now ${q.top}")
    q.clear()
