fun executeRebootSteps(rebootSteps: List<RebootStep>, min: Int, max: Int): Int {
    val region = Cuboid(Coord3d(min, min, min), Coord3d(max, max, max))
    return rebootSteps
        .filter { region.intersects(it.cuboid) }
        .fold(mutableMapOf<Coord3d, Boolean>()) { map, rebootStep ->
            rebootStep.cuboid.getCubes()
                .filter { region.contains(it) }
                .fold(map) { map2, coord3d ->
                    map2[coord3d] = rebootStep.turnOn
                    map2
                }
        }
        .count { it.value }
};0

// matkronprod.kt
// Prime function:
// mkp function: Return the Kronecker product of the a and b matrices.
// Note: both a and b must be matrices, i.e., 2D rectangular arrays.
fun mkp(a:Array<Array<Int>>,b:Array<Array<Int>>):Array<Array<Int>> {
  var t:Array<Array<Int>> = Array(a.size, {Array(b[0].size, {0})})
  for (i in 0..a.size-1) {
    for (j in 0..b[0].size-1) {
      for (k in 0..a[0].size-1) {
        t[i][j] += a[i][k] * b[k][j]
      }
    }
  }
  return t
}
