fun normalFormStrings(N: Int): List<String> {
    fun generatePatterns(n: Int): List<List<Int>> {
        val patterns = mutableListOf<List<Int>>()
        fun backtrack(current: List<Int>, maxNum: Int) {
            if (current.size == n) {
                patterns.add(current)
                return
            }
            for (nextNum in 0..(maxNum + 1)) {
                backtrack(current + listOf(nextNum), maxOf(maxNum, nextNum))
            }
        }
        if (n == 0) {
            return emptyList()
        }
        backtrack(listOf(0), 0)
        return patterns
    }
    val patterns = generatePatterns(N)
    val strings = patterns.map { pattern ->
        pattern.map { 'a'.toInt() + it }.map { it.toChar() }.joinToString("")
    }.sorted()
    return strings
};1

