fun mkdirCount(testCases: List<Pair<List<String>, List<String>>>): List<Int> {
    val results = mutableListOf<Int>()
    for ((existingDirs, wantedDirs) in testCases) {
        val existing = mutableSetOf<String>()
        for (path in existingDirs) {
            val parts = path.split("/").filter { it.isNotEmpty() }
            for (i in 1..parts.size) {
                val parent = parts.subList(0, i).joinToString("/")
                existing.add(parent)
            }
        }
        var count = 0
        for (path in wantedDirs) {
            val parts = path.split("/").filter { it.isNotEmpty() }
            val current = mutableListOf<String>()
            for (p in parts) {
                current.add(p)
                val currPath = current.joinToString("/")
                if (!existing.contains(currPath)) {
                    existing.add(currPath)
                    count += 1
                }
            }
        }
        results.add(count)
    }
    return results
};1

