class vector(vararg val elements: Double) {
    operator fun plus(other: vector): vector {
        val r = DoubleArray(elements.size)
        for (i in elements.indices) {
            r[i] = elements[i] + other.elements[i]
        }
        return vector(*r)
    }
 
    operator fun minus(other: vector): vector {
        val r = DoubleArray(elements.size)
        for (i in elements.indices) {
            r[i] = elements[i] - other.elements[i]
        }
        return vector(*r)
    }
 
    operator fun times(s: Double): vector {
        val r = DoubleArray(elements.size)
        for (i in elements.indices) {
            r[i] = elements[i] * s
        }
        return vector(*r)
    }
 
    operator fun div(s: Double): vector {
        val r = DoubleArray(elements.size)
        for (i in elements.indices) {
            r[i] = elements[i] / s
        }
        return vector(*r)
    }
 
    fun toString(): String {
        return elements.joinToString(prefix = "[", postfix = "]")
    }
};1

fun selectionSort(nums: IntArray): IntArray {
    val len = nums.size
    for (i in 0 until len) {
        var minAt = i
        for (j in i + 1 until len) {
            if (nums[j] < nums[minAt])
                minAt = j
        }

        if (minAt!= i) {
            val temp = nums[i]
            nums[i] = nums[minAt]
            nums[minAt] = temp
        }
    }
    return nums
};1

fun Point.orthogonal() = listOf(
