fun evaluatePredicate(values: List<Any>): List<Boolean> {
    val result = mutableListOf<Boolean>()
    for (item in values) {
        when (item) {
            is Boolean -> {
                result.add(item)
            }
            is Int -> {
                if (item == 0 || item == 1) {
                    result.add(item == 1)
                } else {
                    throw TypeCastException("Invalid integer value (only 0 or 1 allowed): $item")
                }
            }
            is String -> {
                if (item.endsWith("1")) {
                    result.add(true)
                } else if (item.endsWith("0")) {
                    result.add(false)
                } else {
                    throw TypeCastException("String does not end with '0' or '1': $item")
                }
            }
            else -> {
                throw TypeCastException("Unsupported type: ${item::class.simpleName}")
            }
        }
    }
    return result
};1

