fun main(args: Array<String>) {
    val games = args.map { it.toInt() }
    if (games.isEmpty()) {
        games.add(Random.nextInt(32000))
    }
 
    val origDeck = arrayOf("A", "2", "3", "4", "5", "6", "7", "8", "9", "T", "J", "Q", "K")
       .flatMap { suit ->
            arrayOf("C", "D", "H", "S").map { suit + it }
        }
 
    games.forEach { seed ->
        val deck = origDeck.toMutableList()
 
        var state = seed
        for (len in 52 downTo 2) {
            state = ((214013 * state) + 2531011) and 0x7fff_ffff
            val index = (state shr 16) % len
            val last = len - 1
            val temp = deck[index]
            deck[index] = deck[last]
            deck[last] = temp
        }
 
        deck.reverse()
 
        println("Game #$seed")
        for (i in 0 until deck.size step 8) {
            println(" " + deck.subList(i, i + 8).joinToString(" "))
        }
        println()
    }
