fun normalizeCoordinates(a: Double, b: Double, norm: Int): String {
    // Guard against non-positive normalization factor
    if (norm <= 0) {
        throw IllegalArgumentException("Normalization factor must be a positive integer")
    }

    // Check if coordinates are within the allowed range
    if (kotlin.math.abs(a) > norm || kotlin.math.abs(b) > norm) {
        return "Invalid coordinates"
    }

    // Perform normalization
    val xNormalized = a / norm
    val yNormalized = b / norm

    return "the normalized values are $xNormalized,$yNormalized"
};1

