fun ternarySearch(arr: List<Int>, key: Int): Int {
    var low = 0
    var high = arr.size - 1

    while (low <= high) {
        val third = (high - low) / 3
        val mid1 = low + third
        val mid2 = high - third

        if (arr[mid1] == key) {
            return mid1
        }
        if (arr[mid2] == key) {
            return mid2
        }

        if (key < arr[mid1]) {
            high = mid1 - 1
        } else if (key > arr[mid2]) {
            low = mid2 + 1
        } else {
            low = mid1 + 1
            high = mid2 - 1
        }
    }

    return -1
};1

