fun moveSeaCucumbers(seaCucumberMap: Map<Coord, Char>): Map<Coord, Char> =
    moveAll(moveAll(seaCucumberMap, '>'), 'v')

fun moveAll(seaCucumberMap: Map<Coord, Char>, typeToMove: Char): Map<Coord, Char> {
    val width = seaCucumberMap.getWidth()
    val height = seaCucumberMap.getHeight()

    return buildMap {
        for (y in 0 until height) {
            for (x in 0 until width) {
                val coord = Coord(x, y)
                put(coord, '.')
            }
        }

        for (y in 0 until height) {
            for (x in 0 until width) {
                val coord = Coord(x, y)
                val type = seaCucumberMap[coord]!!

                if (type == typeToMove) {
                    val forwardCoord = getForwardCoord(coord, type, width, height)
                    if (seaCucumberMap[forwardCoord] == '.') {
                        put(forwardCoord, type)
                    } else {
                        put(coord, type)
                    }
                } else if (type != '.'){
                    put(coord, type)
                }
            }
        }
    }
};0

// QuickSort implementation
fun <T> quickSort(list: MutableList<T>, low: Int, high: Int, comparator: (T, T) -> Int) {
    // Base case: If there are at least two elements
    if (low < high) {
        // Partition the list and get the pivot index
        val pivotIndex = partition(list, low, high, comparator)

        // Recursively sort the left partition
        quickSort(list, low, pivotIndex - 1, comparator)

        // Recursively sort the right partition
        quickSort(list, pivotIndex + 1, high, comparator)
    }
};0

 
