//----------------------------------------------------------------------------- Stack Solution
fun isValidParenthesesStack(s: String): Boolean {
    if (s.length % 2 != 0) return false
    val map = mapOf('}' to '{', ')' to '(', ']' to '[')
    val stack = Stack<Char>()
    s.forEach {
        if (it == '}' || it == ')' || it == ']') {
            if (stack.isEmpty() || stack.peek() != map[it]) return false
            stack.pop()
        } else stack.push(it)
    }
    return stack.isEmpty()
};0

