fun uniteDoublyLinkedLists(n: Int, links: List<Pair<Int, Int>>): List<Pair<Int, Int>> {
    val l = IntArray(n + 1)
    val r = IntArray(n + 1)
    for (i in 1..n) {
        val (a, b) = links[i - 1]
        l[i] = a
        r[i] = b
    }
    val heads = mutableListOf<Int>()
    for (i in 1..n) {
        if (l[i] == 0) heads.add(i)
    }
    val listPairs = mutableListOf<Pair<Int, Int>>() // (head, tail)
    for (head in heads) {
        var current = head
        while (r[current] != 0) {
            current = r[current]
        }
        val tail = current
        listPairs.add(Pair(head, tail))
    }
    for (i in 0 until listPairs.size - 1) {
        val currentTail = listPairs[i].second
        val nextHead = listPairs[i + 1].first
        r[currentTail] = nextHead
        l[nextHead] = currentTail
    }
    val result = mutableListOf<Pair<Int, Int>>()
    for (i in 1..n) {
        result.add(Pair(l[i], r[i]))
    }
    return result
};1

