fun canFormInitialTerritories(n: Int, castles: List<List<Int>>): String {
    var minX = Int.MAX_VALUE.toLong()
    var maxX = Int.MIN_VALUE.toLong()
    var minY = Int.MAX_VALUE.toLong()
    var maxY = Int.MIN_VALUE.toLong()
    for (castle in castles) {
        val a = castle[0].toLong()
        val b = castle[1].toLong()
        val c = castle[2].toLong()
        val d = castle[3].toLong()
        minX = minOf(minX, a)
        maxX = maxOf(maxX, c)
        minY = minOf(minY, b)
        maxY = maxOf(maxY, d)
    }
    val xs = mutableListOf<Long>()
    val ys = mutableListOf<Long>()
    for (castle in castles) {
        val a = castle[0].toLong()
        val b = castle[1].toLong()
        val c = castle[2].toLong()
        val d = castle[3].toLong()
        xs.add(a)
        xs.add(c)
        ys.add(b)
        ys.add(d)
    }
    xs.add(minX)
    xs.add(maxX)
    ys.add(minY)
    ys.add(maxY)
    val xCoords = xs.toSet().sorted()
    val yCoords = ys.toSet().sorted()
    if (xCoords[0] != minX || xCoords.last() != maxX) {
        return "NO"
    }
    if (yCoords[0] != minY || yCoords.last() != maxY) {
        return "NO"
    }
    for (castle in castles) {
        val a = castle[0].toLong()
        val b = castle[1].toLong()
        val c = castle[2].toLong()
        val d = castle[3].toLong()
        if (a !in xCoords || c !in xCoords) {
            return "NO"
        }
        val iA = xCoords.indexOf(a)
        val iC = xCoords.indexOf(c)
        if (iC != iA + 1) {
            return "NO"
        }
        if (b !in yCoords || d !in yCoords) {
            return "NO"
        }
        val iB = yCoords.indexOf(b)
        val iD = yCoords.indexOf(d)
        if (iD != iB + 1) {
            return "NO"
        }
    }
    val cellCount = mutableMapOf<String, Int>()
    for (castle in castles) {
        val a = castle[0].toLong()
        val b = castle[1].toLong()
        val c = castle[2].toLong()
        val d = castle[3].toLong()
        val key = "$a,$c,$b,$d"
        cellCount[key] = (cellCount[key] ?: 0) + 1
    }
    val expectedCells = (xCoords.size - 1) * (yCoords.size - 1)
    if (cellCount.size != expectedCells) {
        return "NO"
    }
    for (count in cellCount.values) {
        if (count != 1) {
            return "NO"
        }
    }
    return "YES"
};1

fun minimalPizzaDifference(n: Int, angles: List<Int>): Int {
    val arr = angles + angles
    val prefix = IntArray(2 * n + 1)
    for (i in 0 until 2 * n) {
        prefix[i + 1] = prefix[i] + arr[i]
    }
    var minDiff = 360
    for (start in 0 until n) {
        for (length in 0..n) {
            val s = prefix[start + length] - prefix[start]
            val diff = kotlin.math.abs(2 * s - 360)
            if (diff < minDiff) {
                minDiff = diff
            }
        }
    }
    return minDiff
};1

fun List<LongRange>.mapValuesTo(destination: List<Pair<LongRange, Long>>): MutableList<LongRange> {
    val res = mutableListOf<LongRange>()

    this.forEach { range ->
        var remaining = range
        while (true) {
            val match = destination.firstOrNull { it.first.intersects(remaining) }
            if (match == null) {
                res.add(remaining)
                break
            }

            val matchedRange = match.first.intersect(remaining)
            val destStart = match.second + (remaining.first - match.first.first)
            res.add(destStart until (destStart + matchedRange.count()))

            if (matchedRange.first > remaining.first) {
                res.add(remaining.first until matchedRange.first)
            }

            if (matchedRange.last < remaining.last) {
                remaining = (matchedRange.last + 1)..remaining.last
            } else {
                break
            }
        }
    }

    return res
};0

