fun berpizza(queries: List<List<Int>>): List<Int> {
    val customerQueue: ArrayDeque<Int> = ArrayDeque() // customer numbers in order of arrival
    val heap = PriorityQueue<Pair<Int, Int>>(compareBy({ it.first }, { it.second })) // (-m, customerNum)
    var customerNum = 0
    val results = mutableListOf<Int>()
    val served = mutableSetOf<Int>()
    for (query in queries) {
        if (query[0] == 1) {
            val m = query[1]
            customerNum += 1
            heap.add(Pair(-m, customerNum))
            customerQueue.add(customerNum)
        } else if (query[0] == 2) {
            while (customerQueue.isNotEmpty() && served.contains(customerQueue.first())) {
                customerQueue.removeFirst()
            }
            val u = customerQueue.removeFirst()
            served.add(u)
            results.add(u)
        } else if (query[0] == 3) {
            while (heap.isNotEmpty()) {
                val (negM, v) = heap.poll()
                if (!served.contains(v)) {
                    served.add(v)
                    results.add(v)
                    break
                }
            }
        }
    }
    return results
};1

 
val rand = java.util.Random()
 
fun basicStats(sampleSize: Int) {
    if (sampleSize < 1) return
    val r = DoubleArray(sampleSize)
    val h = IntArray(10) // all zero by default
    /*
       Generate 'sampleSize' random numbers in the interval [0, 1)
       and calculate in which box they will fall when drawing the histogram
    */
    for (i in 0 until sampleSize) {
        r[i] = rand.nextDouble()
        h[(r[i] * 10).toInt()]++
    }
 
    // adjust one of the h[] values if necessary to ensure they sum to sampleSize
    val adj = sampleSize - h.sum()
    if (adj != 0) {
        for (i in 0..9) {
            h[i] += adj
            if (h[i] >= 0) break
            h[i] -= adj
        }
    }
 
    val mean = r.average()
    val sd = Math.sqrt(r.map { (it - mean) * (it - mean) }.average())
 
    // Draw a histogram of the data with interval 0.1
    var numStars: Int
    // If sample size > 500 then normalize histogram to 500
    val scale = if (sampleSize <= 500) 1.0 else 500.0 / sampleSize
    println("Sample size $sampleSize\n")
    println("  Mean ${"%1.6f".format(mean)}  SD ${"%1.6f".format(sd)}\n")
    for (i in 0..9) {
        print("  %1.2f : ".format(i / 10.0))
        print("%5d ".format(h[i]))
        numStars = (h[i] * scale + 0.5).toInt()
        println("*".repeat(numStars))
    }
    println()
}
 
fun main(args: Array<String>) {
    val sampleSizes = intArrayOf(100, 1_000, 10_000, 100_000)
    for (sampleSize in sampleSizes) basicStats(sampleSize)
};0

import java.awt.Color
import java.awt.image.BufferedImage
import java.io.File
import java.io.IOException
import javax.imageio.ImageIO
import kotlin.math.pow
import kotlin.math.sqrt
 
typealias Vector = DoubleArray
 
fun normalize(v: Vector) {
    val invLen = 1 / sqrt(dot(v, v))
    v[0] *= invLen
    v[1] *= invLen
    v[2] *= invLen
}
 
fun dot(x: Vector, y: Vector): Double {
    return x[0] * y[0] + x[1] * y[1] + x[2] * y[2]
}
 
fun drawSphere(r: Int, k: Double, amb: Double, dir: Vector): BufferedImage {
    val w = r * 4
    val h = r * 3
    val img = BufferedImage(w, h, BufferedImage.TYPE_BYTE_GRAY)
    val vec = Vector(3)
    for (x in -r until r) {
        for (y in -r until r) {
            if (z := r * r - x * x - y * y; z >= 0) {
                vec[0] = x.toDouble()
                vec[1] = y.toDouble()
                vec[2] = sqrt(z.toDouble())
                normalize(vec)
                val s = dot(dir, vec)
                var lum = 255 * (s.pow(k) + amb) / (1 + amb)
                if (lum < 0) {
                    lum = 0.0
                } else if (lum > 255) {
                    lum = 255.0
                }
                img.setRGB(x, y, Color(lum.toInt(), lum.toInt(), lum.toInt()).rgb)
            }
        }
    }
    return img
}
 
fun main() {
    val dir = Vector(3)
    dir[0] = -30.0
    dir[1] = -30.0
    dir[2] = 50.0
    normalize(dir)
    val img = drawSphere(200, 1.5, 0.2, dir)
    try {
        ImageIO.write(img, "png", File("sphere.png"))
    } catch (e: IOException) {
        e.printStackTrace()
    }
};1

fun rotate(matrix: MutableList<MutableList<Int>>) {
    val n = matrix.size
    // Transpose the matrix
    for (i in 0 until n) {
        for (j in i + 1 until n) {
            val temp = matrix[i][j]
            matrix[i][j] = matrix[j][i]
            matrix[j][i] = temp
        }
    }
    // Reverse each row
    for (row in matrix) {
        row.reverse()
    }
};1

 
