fun complexPrimeSort(l1: List<Int>, l2: List<Int>): List<Int> {
    // Count how many times 2 appears in each list
    val countL1 = l1.count { it == 2 }
    val countL2 = l2.count { it == 2 }

    // Determine how many 2's are common to both lists
    val commonCount = minOf(countL1, countL2)

    // Build the resulting list of 2's (if any) and reverse it
    val result = MutableList(commonCount) { 2 }
    result.reverse() // reversing has no visible effect but fulfills the requirement

    return result
};1

