fun run(data: List<List<String>>): Int {
    data class Point(val x: Int, val y: Int)

    fun String.toPoints(origin: Point): List<Point> {
        val op: (Point) -> Point = when (val dir = this[0]) {
            'U' -> { it -> it.copy(y = it.y + 1) }
            'D' -> { it -> it.copy(y = it.y - 1) }
            'R' -> { it -> it.copy(x = it.x + 1) }
            'L' -> { it -> it.copy(x = it.x - 1) }
            else -> error("Encountered unexpected direction: $dir")
        }

        val res = mutableListOf<Point>()
        var tail = origin
        for (i in 0 until substring(1).toInt()) {
            op(tail).also {
                tail = it
                res.add(it)
            }
        }

        return res
    }

    fun <T> Iterable<Iterable<T>>.intersectAll(): Iterable<T> {
        val itr = iterator()
        var res = if (itr.hasNext()) itr.next().toSet() else emptySet()

        while (itr.hasNext()) res = res.intersect(itr.next())

        return res
    }

    return data.map { path ->
        var tail = Point(0, 0)
        path.flatMap { segment -> segment.toPoints(tail).also { tail = it.last() } }
    }.intersectAll()
        .filter { it != Point(0, 0) }
        .map { abs(it.x) + abs(it.y) }
        .min()!!
};0

 
const val MAX = 120
 
fun isPrime(n: Int) : Boolean {
    if (n < 2) return false
    if (n % 2 == 0) return n == 2
    if (n % 3 == 0) return n == 3
    var d : Int = 5
    while (d * d <= n) {
        if (n % d == 0) return false
        d += 2
        if (n % d == 0) return false
        d += 4
    }
    return true
}
 
fun countPrimeFactors(n: Int) =
    when {
        n == 1  -> 0
        isPrime(n) -> 1
        else -> {
            var nn = n
            var count = 0
            var f = 2
            while (true) {
                if (nn % f == 0) {
                    count++
                    nn /= f
                    if (nn == 1) break
                    if (isPrime(nn)) f = nn
                } else if (f >= 3) {
                    f += 2
                } else {
                    f = 3
                }
            }
            count
        }
    }
 
fun main() {
    println("The attractive numbers up to and including $MAX are:")
    var count = 0
    for (i in 1..MAX) {
        val n = countPrimeFactors(i)
        if (isPrime(n)) {
            System.out.printf("%4d", i)
            if (++count % 20 == 0) println()
        }
    }
    println()
};0

