fun currencyConversion(name1: String, value1: Number, name2: String, value2: Number): Double {
    // Type checking
    if (name1 !is String || name2 !is String) {
        throw IllegalArgumentException("Currency names must be strings.")
    }
    if (value1 !is Number || value2 !is Number) {
        throw IllegalArgumentException("Currency values must be numeric (Int or Double).")
    }
    val v1 = value1.toDouble()
    val v2 = value2.toDouble()
    // Value checking
    if (v1 <= 0.0 || v2 <= 0.0) {
        throw IllegalArgumentException("Currency values must be positive numbers greater than zero.")
    }
    // Conversion rate calculation
    try {
        return v1 / v2
    } catch (e: ArithmeticException) { // For completeness
        throw IllegalArgumentException("Conversion rate undefined: division by zero encountered.")
    }
};1

fun compareObjects(function: (Any) -> Any, a: Any, b: Any): Boolean {
    val resultA = function(a)
    val resultB = function(b)
    if (resultA is Comparable<*> && resultB is Comparable<*>) {
        @Suppress("UNCHECKED_CAST")
        val comparableA = resultA as Comparable<Any?>
        return comparableA > resultB
    } else {
        throw TypeCastException("Returned values are not comparable.")
    }
};1

