 * javascript bf interpreter
 * by
 */
 
fun execute(code: String): Boolean {
    val mem = arrayOfNulls<Int>(30000)
    var sp = 10000
    val opcode = code
    val oplen = opcode.length
    var ip = 0
    val loopstack = ArrayList<Int>()
    var output = ""
 
    for (i in 0..29999) mem[i] = 0
 
    while (ip < oplen) {
        when (opcode[ip]) {
            '+' -> mem[sp] = mem[sp]!! + 1
            '-' -> mem[sp] = mem[sp]!! - 1
            '>' -> sp++
            '<' -> sp--
            '.' -> if (mem[sp]!= 10 && mem[sp]!= 13) {
                output += mem[sp]!!.toChar()
            } else {
                puts(output)
                output = ""
            }
            ',' -> {
                val s = console.input()
                if (s == null) exit(0)
                mem[sp] = s[0].toInt()
            }
            '[' -> if (mem[sp]!= 0) {
                loopstack.add(ip)
            } else {
                var k = ip
                var j = 0
                while (k < oplen) {
                    if (opcode[k] == '[') j++
                    if (opcode[k] == ']') j--
                    if (j == 0) break
                    k++
                }
                if (j == 0) ip = k
                else {
                    puts("Unmatched loop")
                    return false
                }
            }
            ']' -> ip = loopstack.removeAt(loopstack.size - 1) - 1
            else -> {
            }
        }
        ip++
    }
    return true
}
 
