fun getParameterCombinations(
    params: Map<String, List<Any>>,
    mode: String = "grid",
    nIter: Int = 25
): List<Map<String, Any>> {
    if (mode != "grid" && mode != "random") {
        throw IllegalArgumentException("mode must be either 'grid' or 'random'.")
    }
    val keys = params.keys.toList()
    if (mode == "grid") {
        if (keys.isEmpty()) {
            return listOf(emptyMap())
        }
        fun cartesianProduct(lists: List<List<Any>>): List<List<Any>> {
            if (lists.isEmpty()) return listOf(emptyList())
            return lists.first().flatMap { item ->
                cartesianProduct(lists.drop(1)).map { rest -> listOf(item) + rest }
            }
        }
        val valueLists: List<List<Any>> = keys.map { params[it] ?: listOf() }
        val combos = cartesianProduct(valueLists)
        return combos.map { values ->
            keys.zip(values).toMap()
        }
    }
    // mode == "random"
    if (keys.isEmpty()) {
        return List(nIter) { emptyMap() }
    }
    val random = Random.Default
    val combinations = mutableListOf<Map<String, Any>>()
    repeat(nIter) {
        val combo = keys.associateWith { k ->
            val candidates = params[k] ?: emptyList()
            candidates[random.nextInt(candidates.size)]
        }
        combinations.add(combo)
    }
    return combinations
};1

import java.util.Arrays
import java.util.stream.Collectors
 
enum class Mode {
    ENCRYPT,
    DECRYPT,
}
 
fun main(args: Array<String>) {
    val plainText = "WELLDONEISBETTERTHANWELLSAID"
    println("The original plaintext is : $plainText")
    println("\nThe left and right alphabets after each permutation during encryption are :\n")
    val cipherText = exec(plainText, Mode.ENCRYPT, true)
    println("\nThe ciphertext is : $cipherText")
    val plainText2 = exec(cipherText, Mode.DECRYPT)
    println("\nThe recovered plaintext is : $plainText2")
}
 
fun exec(text: String, mode: Mode, showSteps: Boolean = false): String {
    val left = "HXUCZVAMDSLKPEFJRIGTWOBNYQ".toCharArray()
    val right = "PTLNBQDEOYSFAVZKGJRIHWXUMC".toCharArray()
    val eText = CharArray(text.length)
    val temp = CharArray(26)
 
    for (i in 0 until text.length) {
        if (showSteps) println("${left.joinToString("")} ${right.joinToString("")}")
        var index = 0
        if (mode == Mode.ENCRYPT) {
            index = right.indexOf(text[i])
            eText[i] = left[index]
        } else {
            index = left.indexOf(text[i])
            eText[i] = right[index]
        }
        if (i == text.length - 1) break
 
        // permute left
 
        for (j in index until 26) temp[j - index] = left[j]
        for (j in 0 until index) temp[26 - index + j] = left[j]
        var store = temp[1]
        for (j in 2 until 14) temp[j - 1] = temp[j]
        temp[13] = store
        temp.copyInto(left, 0)
 
        // permute right
 
        for (j in index until 26) temp[j - index] = right[j]
        for (j in 0 until index) temp[26 - index + j] = right[j]
        store = temp[0]
        for (j in 1 until 26) temp[j - 1] = temp[j]
        temp[25] = store
        store = temp[2]
        for (j in 3 until 14) temp[j - 1] = temp[j]
        temp[13] = store
        temp.copyInto(right, 0)
    }
 
    return String(eText)
};1

