import java.util.Arrays
import java.util.stream.Collectors
import java.util.stream.IntStream
 
/* Partial application helper. */
class PApply<F, Arg>(val f: F, val arg: Arg) {
    /*
     * The return type of F only gets deduced based on the number of arguments
     * supplied. PApply otherwise has no idea whether f takes 1 or 10 args.
     */
    fun <Args> invoke(vararg args: Args): Any {
        return f.invoke(arg, *args)
    }
}
 
fun <F, Arg> papply(f: F, arg: Arg): PApply<F, Arg> {
    return PApply(f, arg)
}
 
/* Apply f to cont. */
fun <F> fs(f: F, cont: IntArray): IntArray {
    return IntStream.range(0, cont.size).map { f.invoke(cont[it]) }.toArray()
}
 
fun f1(x: Int): Int {
    return x * 2
}
 
fun f2(x: Int): Int {
    return x * x
}
 
fun main(args: Array<String>) {
    val xs = intArrayOf(0, 1, 2, 3)
