    val fsf1 = papply(::fs, ::f1)
    val fsf2 = papply(::fs, ::f2)
 
    println("xs:\n" +
            "\tfsf1: " + Arrays.stream(fsf1.invoke(xs)).boxed().collect(Collectors.toList()) + '\n' +
            "\tfsf2: " + Arrays.stream(fsf2.invoke(xs)).boxed().collect(Collectors.toList()) + "\n\n" +
            "ys:\n" +
            "\tfsf1: " + Arrays.stream(fsf1.invoke(ys)).boxed().collect(Collectors.toList()) + '\n' +
            "\tfsf2: " + Arrays.stream(fsf2.invoke(ys)).boxed().collect(Collectors.toList()))
