fun calculate_total_playtime(song_durations: List<String>): String {
    var totalSeconds = 0
    for (duration in song_durations) {
        val parts = duration.split(":")
        val minutes = parts[0].toInt()
        val seconds = parts[1].toInt()
        totalSeconds += minutes * 60 + seconds
    }
    val totalMinutes = totalSeconds / 60
    val remainingSeconds = totalSeconds % 60
    return String.format("%02d:%02d", totalMinutes, remainingSeconds)
};1

fun generateDoubledFibonacci(n: Any?): List<Int> {
    if (n !is Int || n is Boolean || n <= 0) {
        throw IllegalArgumentException("n must be a positive integer greater than 0")
    }
    val fibSequence = mutableListOf<Int>()
    var a = 0
    var b = 1
    repeat(n) {
        fibSequence.add(a)
        val temp = a + b
        a = b
        b = temp
    }
    val doubledFib = fibSequence.map { it * 2 }
    return doubledFib
};1

