fun findMode(arr: List<Int>): List<Int> {
    if (arr.isEmpty()) return emptyList()
    val count = arr.groupingBy { it }.eachCount()
    val maxFreq = count.values.maxOrNull() ?: return emptyList()
    val modes = count.filter { it.value == maxFreq }.keys.toList()
    return modes
};1

fun slugCleaner(slug: String, separator: String = "-"): String {
    // Guard against empty input
    if (slug.isEmpty()) {
        return ""
    }

    var resultSlug = slug

    // If a custom separator (different from the default) is given,
    // replace it with the default separator first.
    if (separator != "-") {
        resultSlug = resultSlug.replace(separator, "-")
    }

    // Now strip any leading/trailing default separators and return.
    return resultSlug.trim('-')
};1

fun getHighBudgetMovies(movies: List<Map<String, Any>>, budgetThreshold: Int): List<String> {
