import kotlin.random.Random
 
class Pistol(private val method: String) {
    private var fired = false
    private val cylinder = Array(6) { false }
    private var trigger = 0
 
    fun rshift() {
        trigger = if (trigger == 0) 5 else trigger - 1
    }
 
    fun load() {
        while (cylinder[trigger]) rshift()
        cylinder[trigger] = true
        rshift()
    }
 
    fun unload() {
        cylinder.fill(false)
    }
 
    fun spin() {
        trigger = Random.nextInt(6)
    }
 
    fun fire() {
        if (cylinder[trigger]) fired = true
        rshift()
    }
 
    fun exec(): Boolean {
        if (method.isEmpty()) {
            println("No method provided")
            return false
        }
        for (x in method.indices) {
            when (method[x]) {
                'F' -> fire()
                'L' -> load()
                'S' -> spin()
                'U' -> unload()
                else -> println("Unknown character in method: ${method[x]}")
            }
        }
        return fired
    }
}
 
