data class Quadruple<A, B, C, D>(val first: A, val second: B, val third: C, val fourth: D)

fun findHighestLowestScore(studentScores: List<Int>): Quadruple<Int, Int, Int, Int> {
    if (studentScores.isEmpty()) {
        throw IllegalArgumentException("The studentScores list must contain at least one score.")
    }
    var highestScore = studentScores[0]
    var lowestScore = studentScores[0]
    var idxHighest = 0
    var idxLowest = 0
    for ((idx, score) in studentScores.withIndex()) {
        if (score > highestScore) {
            highestScore = score
            idxHighest = idx
        }
        if (score < lowestScore) {
            lowestScore = score
            idxLowest = idx
        }
    }
    return Quadruple(highestScore, idxHighest, lowestScore, idxLowest)
};1

