fun analyticFibonacci(n: Int): Int {
  val sqrt_5 = sqrt(5.0)
  val p = (1 + sqrt_5) / 2
  val q = 1 / p
  return (Math.pow(p, n.toDouble()) + Math.pow(q, n.toDouble())) / sqrt_5 + 0.5
}
 
