fun hasTargetSum(nums: List<Int>, target: Int): Boolean {
    fun backtrack(start: Int, currSum: Int): Boolean {
        if (currSum == target) {
            return true
        }
        if (currSum > target) {
            return false
        }
        for (i in start until nums.size) {
            if (backtrack(i + 1, currSum + nums[i])) {
                return true
            }
        }
        return false
    }
    return backtrack(0, 0)
};1

fun massiveRefactoring(n: Int, initial: List<String>, target: List<String>): Triple<String, String?, String?> {
    val changed = mutableListOf<Pair<String, String>>()
    val unchanged = mutableListOf<Pair<String, String>>()

    for (i in 0 until n) {
        if (initial[i] != target[i]) {
            changed.add(Pair(initial[i], target[i]))
        } else {
            unchanged.add(Pair(initial[i], target[i]))
        }
    }

    if (changed.isEmpty()) {
        return Triple("NO", null, null)
    }

    val (w, wPrime) = changed[0]
    var k = -1
    for (i in w.indices) {
        if (w[i] != wPrime[i]) {
            k = i
            break
        }
    }
    if (k == -1) {
        return Triple("NO", null, null)
    }
    val candidates = mutableListOf<Pair<String, String>>()
    for (i in 0..k) {
        val maxL = w.length - i
        val minL = k - i + 1
        for (L in minL..maxL) {
            if (i + L > w.length) continue
            val s = w.substring(i, i + L)
            val firstOccurrence = w.indexOf(s)
            if (firstOccurrence != i) continue
            if (w.substring(0, i) != wPrime.substring(0, i)) continue
            if (w.substring(i + L) != wPrime.substring(i + L)) continue
            val t = wPrime.substring(i, i + L)
            val replaced = w.substring(0, i) + t + w.substring(i + L)
            if (replaced != wPrime) continue
            candidates.add(Pair(s, t))
        }
    }
    for ((s, t) in candidates) {
        var valid = true
        for ((wJ, wJPrime) in changed) {
            val idx = wJ.indexOf(s)
            if (idx == -1) {
                valid = false
                break
            }
            val replacedJ = wJ.substring(0, idx) + t + wJ.substring(idx + s.length)
            if (replacedJ != wJPrime) {
                valid = false
                break
            }
        }
        if (!valid) continue
        for ((wJ, _) in unchanged) {
            if (wJ.contains(s)) {
                valid = false
                break
            }
        }
        if (valid) {
            return Triple("YES", s, t)
        }
    }
    return Triple("NO", null, null)
};1

// contributed to rosettacode.org by Peter Helcmanovsky
// BCT = Binary-Coded Ternary: pairs of bits form one digit [0,1,2] (0b11 is invalid digit)
 
fun main(args: Array<String>) {
    // parse N from first argument, if no argument, use 3 as default value
    val n = if (args.size > 0) args[0].toInt() else 3
    // check for valid N (0..9) - 16 requires 33 bits for BCT form 1<<(n*2) => hard limit
    if (n < 0 || 9 < n) {                       // but N=9 already produces 370MB output
        println("N out of range (use 0..9): %d".format(n))
        return
    }
 
    val size_bct = 1 shl (n * 2)          // 3**n in BCT form (initial value for loops)
    // draw the carpet, two nested loops counting down in BCT form of values
    var y = size_bct
    do {                                        // all lines loop
        y = bct_decrement(y)                   // --Y (in BCT)
        var x = size_bct
        do {                                    // line loop
            x = bct_decrement(x)               // --X (in BCT)
            // check if x has ternary digit "1" at same position(s) as y -> output space (hole)
            print(if ((x and y and bct_low_bits)!= 0)'' else '#')
        } while (0 < x)
        println()
    } while (0 < y)
}
 
val bct_low_bits = 0x55555555
 
fun bct_decrement(v: Int): Int {
    var v = v
    --v            // either valid BCT (v-1), or block of bottom 0b00 digits becomes invalid 0b11
    return v xor (v and (v shr 1) and bct_low_bits)     // fix all 0b11 to 0b10 (digit "2")
};1

