private abstract class TreeNode(private val name: String, var parent: TreeNode?, val children: MutableList<TreeNode>?) {
    open val totalSize: Long
        get() {
            return children?.sumOf { it.totalSize } ?: 0
        }

    fun addChild(node: TreeNode) {
        node.parent = this
        children?.add(node)
    }

    fun getChildByName(name: String): TreeNode {
        return children?.firstOrNull { it.name == name } ?: this
    }

    fun getAllSubdirectories(): List<DirNode> {
        return getAllSubNodes().filterIsInstance<DirNode>()
    }

    fun getAllSubNodes(): List<TreeNode> {
        val result = mutableListOf<TreeNode>()
        if (children != null) {
            for (child in children) {
                result.addAll(child.getAllSubNodes())
                result.add(child)
            }
        }
        return result
    }
};0

fun lexicographicallySmallestString(S: String): String {
    var best = S
    val n = S.length
    for (i in 0 until n) {
        val removed = S[i]
        val remaining = S.substring(0, i) + S.substring(i + 1)
        for (j in 0 until n) {
            val newStr = remaining.substring(0, j) + removed + remaining.substring(j)
            if (newStr < best) {
                best = newStr
            }
        }
    }
    return best
};1

fun parseCitation(citationString: String): Map<String, Any?> {
    val result = mutableMapOf<String, Any?>(
        "author" to mutableListOf<String>(),
        "journal" to null,
        "volume" to null,
        "issue" to null,
        "pages" to null,
        "year" to null,
        "publisher" to null,
        "doi" to null
    )

    // 1) Extract DOI (last occurrence of text within double quotes)
    val doiPattern = Pattern.compile("\"([^\"]+)\"")
    val doiMatcher = doiPattern.matcher(citationString)
    var lastDoi: String? = null
    while (doiMatcher.find()) {
        lastDoi = doiMatcher.group(1)?.trim()
    }
    if (lastDoi != null) {
        result["doi"] = lastDoi
    }

    // 2) Process each line for the remaining tags
    val tagMap = mapOf(
        "%A" to Pair("author", true),
        "%J" to Pair("journal", false),
        "%V" to Pair("volume", false),
        "%N" to Pair("issue", false),
        "%P" to Pair("pages", false),
        "%D" to Pair("year", false),
        "%I" to Pair("publisher", false)
    )

    val lines = citationString.lines()
    for (rawLine in lines) {
        val line = rawLine.trim()
        if (line.isEmpty()) continue
        if (line.count { it == '"' } > 0 && line.startsWith('"')) {
            // Probably DOI line, already captured
            continue
        }
        for ((tag, keyMulti) in tagMap) {
            val (key, multiValued) = keyMulti
            val tagPrefix = "$tag "
            if (line.startsWith(tagPrefix)) {
                val value = line.substring(tagPrefix.length).trim()
                if (multiValued) {
                    @Suppress("UNCHECKED_CAST")
                    (result[key] as MutableList<String>).add(value)
                } else {
                    result[key] = value
                }
                break
            }
        }
    }
    return result
};1

fun buildStacks(stackLines: List<String>): Stacks {
    val size = stackLines.last().split("  ").size
    val parsedStackLines = stackLines
        .map { line -> parseStackLine(line, size) }
        .dropLast(1)
    val stacks = (0 until size)
        .map { column ->
            parsedStackLines
                .map { it[column] }
                .map(Char::toString)
                .filter(String::isNotBlank)
        }
        .map(::ArrayDeque)

    return Stacks(stacks)
};0

fun countTriplets(array: LongArray, ratio: Long): Long {
    fun modR(iv: IndexedValue<Long>) = iv.value % ratio == 0L
    fun divR(iv: IndexedValue<Long>) = IndexedValue(iv.index, iv.value / ratio)

    fun List<IndexedValue<Long>>.indexes() = map { (index, _) -> index }

    fun candidates(power: Int) =
        (0 until power).fold(array.withIndex()) { curArr, _ ->
            curArr.filter(::modR).map(::divR)
        }.groupBy { (_, value) -> value }
         .mapValues { (_, indexedValues) -> indexedValues.indexes() }

    val (iCandidates, jCandidates, kCandidates) =
        listOf(0, 1, 2).map(::candidates)

    val commonBases = kCandidates.keys.filter { v ->
        (v in iCandidates) && (v in jCandidates)
    }

    return commonBases.map { v ->
        val kvCandidates = kCandidates.getValue(v)
        val jvCandidates = jCandidates.getValue(v)
        val ivCandidates = iCandidates.getValue(v)

        countTriplesForSingleBaseValue(ivCandidates, jvCandidates, kvCandidates)
    }.sum()
};0

fun minRestDays(n: Int, a: List<Int>): Int {
    val INF = Int.MAX_VALUE / 2
    var dp = IntArray(3) { INF } // 0 - last was rest, 1 - last was contest, 2 - last was sport
    dp[0] = 0
    for (i in 0 until n) {
        val newDp = IntArray(3) { INF }
        for (last in 0..2) {
            // rest is always an option
            var v = dp[last] + 1
            if (v < newDp[0]) {
                newDp[0] = v
            }
            // contest possible
            if ((a[i] == 1 || a[i] == 3) && last != 1) {
                v = dp[last]
                if (v < newDp[1]) {
                    newDp[1] = v
                }
            }
            // sport possible
            if ((a[i] == 2 || a[i] == 3) && last != 2) {
                v = dp[last]
                if (v < newDp[2]) {
                    newDp[2] = v
                }
            }
        }
        dp = newDp
    }
    return dp.minOrNull() ?: 0
};1

fun solve(previous: Int, choice: Long, seq: List<InequationType>, available: Set<Int>): Minmax {
    var min = 9999999999L
    var max = 0L
    if (seq.isEmpty()) {
        return Minmax(choice, choice)
    }
    for (i in available) {
        val canUse = when (seq[0]) {
            InequationType.KT -> true
            InequationType.LT -> previous < i
            InequationType.GT -> previous > i
        }
        if (!canUse) {
            continue
        }
        val result = solve(i, choice * 10 + i, seq.subList(1, seq.size), available - i)
        min = minOf(min, result.min)
        max = maxOf(max, result.max)
    }
    return Minmax(min, max)
};0

fun pernicious(w: Int): Boolean {
    val ff = 1 shl 32 - 1
    val mask1 = ff / 3
    val mask3 = ff / 5
    val maskf = ff / 17
    val maskp = ff / 255
    var w = w
    w -= w shr 1 and mask1
    w = w and mask3 + w shr 2 and mask3
    w = (w + w shr 4) and maskf
    return 0xa08a28ac shr (w * maskp shr 24) and 1!= 0
}
 
