fun rsl(fn: String, n: Int): Pair<String, Exception?> {
    if (n < 1) {
        return Pair("", Exception("invalid request: line $n"))
    }
    val f = File(fn)
    if (!f.exists()) {
        return Pair("", Exception("no such file or directory"))
    }
    val bf = f.bufferedReader()
    var line = ""
    for (lnum in 0 until n) {
        line = bf.readLine()
        if (line == null) {
            when (lnum) {
                0 -> return Pair("", Exception("no lines in file"))
                1 -> return Pair("", Exception("only 1 line"))
                else -> return Pair("", Exception("only $lnum lines"))
            }
        }
    }
    if (line == "") {
        return Pair("", Exception("line $n empty"))
    }
    return Pair(line, null)
};1

import java.util.*
 
fun main(args: Array<String>) {
    val digits = randomDigits()
    val in = Scanner(System.`in`)
 
    println("Make 24 using these digits: " + Arrays.toString(digits))
    print("> ")
 
    val s = Stack<Float>()
    var total = 0L
    for (c in in.nextLine().toCharArray()) {
        if ('0' <= c && c <= '9') {
            val d = c - '0'
            total += 1 shl (d * 5)
            s.push(d.toFloat())
        } else if ("+/-*".indexOf(c)!= -1) {
            s.push(applyOperator(s.pop(), s.pop(), c))
        }
    }
    if (tallyDigits(digits)!= total)
        print("Not the same digits. ")
    else if (Math.abs(24 - s.peek()) < 0.001F)
        println("Correct!")
    else
        print("Not correct.")
}
 
fun applyOperator(a: Float, b: Float, c: Char): Float {
    return when (c) {
        '+' -> a + b
        '-' -> b - a
        '*' -> a * b
        '/' -> b / a
        else -> Float.NaN
    }
}
 
fun tallyDigits(a: IntArray): Long {
    var total = 0L
    for (i in 0..3)
        total += 1 shl (a[i] * 5)
    return total
}
 
