fun countDistinctPrimes(lst: List<Int>): Map<Int, Int> {
    fun isPrime(n: Int): Boolean {
        if (n <= 1) return false
        if (n == 2) return true
        if (n % 2 == 0) return false
        var i = 3
        while (i * i <= n) {
            if (n % i == 0) return false
            i += 2
        }
        return true
    }
    val counts = mutableMapOf<Int, Int>()
    for (num in lst) {
        if (num > 1 && isPrime(num)) {
            counts[num] = (counts[num] ?: 0) + 1
        }
    }
    return counts
};1

