fun fibonacci(n: Int): List<Int> {
    // Handle non-positive input
    if (n <= 0) {
        return emptyList()
    }

    // n == 1 → only the first term
    if (n == 1) {
        return listOf(0)
    }

    // Initialize the list with the first two Fibonacci numbers
    val seq = mutableListOf(0, 1)

    // Generate the rest of the sequence up to n terms
    for (i in 2 until n) {
        seq.add(seq[seq.size - 1] + seq[seq.size - 2])
    }

    return seq
};1

fun minOperationsToNiceMatrix(t: Int, testcases: List<Triple<Int, Int, List<List<Int>>>>): List<Int> {
    val results = mutableListOf<Int>()
    for (idx in 0 until t) {
        val (n, m, matrix) = testcases[idx]
        val visited = Array(n) { BooleanArray(m) { false } }
        var total = 0
        for (i in 0 until n) {
            for (j in 0 until m) {
                if (!visited[i][j]) {
                    val group = setOf(
                        Pair(i, j),
                        Pair(i, m - 1 - j),
                        Pair(n - 1 - i, j),
                        Pair(n - 1 - i, m - 1 - j)
                    )
                    val elements = mutableListOf<Int>()
                    for ((x, y) in group) {
                        elements.add(matrix[x][y])
                        visited[x][y] = true
                    }
                    elements.sort()
                    val k = elements.size
                    val median = elements[k / 2]
                    total += elements.sumOf { kotlin.math.abs(it - median) }
                }
            }
        }
        results.add(total)
    }
    return results
};1

 
import java.io.FileOutputStream
