fun move(it: Holder, amount: Long): Holder {

    var repeat = abs(amount)
    if(amount<0)
        repeat+=1

    var index = 0
    var current = it
    while(index < repeat) {
        current = if (amount < 0) current.left!! else current.right!!
        index+=1
    }

//    var current = it
//    repeat(abs(amount.toInt()) + if (amount < 0) 1 else 0) {
//        current = if (amount < 0) current.left!! else current.right!!
//    }
    return current
};0

import java.net.InetAddress
