fun parseIpPort(netloc: String): Pair<InetAddress, Int?> {
    return try {
        InetAddress.getByName(netloc) to null
    } catch (e: UnknownHostException) {
        val url = URL("//$netloc")
        url.host to url.port
    }
}
 
