fun String.toInstruction(): Instruction {
    val inputRegex = "move (\\d+) from (\\d+) to (\\d+)".toRegex()
    val (qty, from, to) = inputRegex
        .matchEntire(this)
        ?.destructured
        ?: throw IllegalArgumentException("Incorrect input line $this")

    return Instruction(qty.toInt(), from.toInt(), to.toInt())
};0

fun countLabels(labels: List<List<String>>): List<Map<String, Any>> {
    val counts = mutableMapOf<String, Int>()
    for (sublist in labels) {
        for (label in sublist) {
            counts[label] = counts.getOrDefault(label, 0) + 1
        }
    }
    val result = counts.map { (label, count) -> mapOf("label" to label, "count" to count) }
    return result.sortedWith(compareBy({ -(it["count"] as Int) }, { it["label"] as String }))
};1

