fun numWaysToConstruct(parts: List<Int>): List<Int> {
    val MOD = 1_000_000_007
    val maxN = if (parts.isNotEmpty()) parts.maxOrNull()!! else 0
    val maxSize = maxN + 2
    val fib = IntArray(maxSize + 1)
    fib[0] = 0
    fib[1] = 1
    for (i in 2..maxSize) {
        fib[i] = ((fib[i - 1].toLong() + fib[i - 2].toLong()) % MOD).toInt()
    }
    val result = mutableListOf<Int>()
    for (n in parts) {
        result.add(fib[n + 1])
    }
    return result
};1

fun uniqueVectors(gvecs: List<Triple<Int, Int, Int>>): List<Triple<Int, Int, Int>> {
    val seen = mutableSetOf<Triple<Int, Int, Int>>()
    val unique = mutableListOf<Triple<Int, Int, Int>>()

    for (vec in gvecs) {
        if (!seen.contains(vec)) {
            seen.add(vec)
            unique.add(vec)
        }
    }

    return unique
};1

 
