import java.util.*
import java.util.Collections.reverse
 
const val UniqueSymbols = 1 shl 8
const val SampleString = "this is an example for huffman encoding"
 
typealias HuffCode = List<Boolean>
typealias HuffCodeMap = Map<Char, HuffCode>
 
interface INode {
    val f: Int
}
 
class InternalNode(val left: INode, val right: INode) : INode {
    override val f = left.f + right.f
}
 
class LeafNode(override val f: Int, val c: Char) : INode
 
class NodeCmp : Comparator<INode> {
    fun compare(lhs: INode, rhs: INode) = rhs.f.compareTo(lhs.f)
}
 
fun buildTree(frequencies: IntArray): INode {
    val trees = PriorityQueue<INode>(NodeCmp())
 
    for (i in 0 until UniqueSymbols) {
        if (frequencies[i]!= 0)
            trees.add(LeafNode(frequencies[i], i.toChar()))
    }
    while (trees.size > 1) {
        val childR = trees.poll()
        val childL = trees.poll()
 
        val parent = InternalNode(childR, childL)
        trees.add(parent)
    }
    return trees.poll()
}
 
fun generateCodes(node: INode, prefix: HuffCode, outCodes: HuffCodeMap) {
    if (node is LeafNode) {
        outCodes[node.c] = prefix
    } else if (node is InternalNode) {
        val leftPrefix = prefix + false
        generateCodes(node.left, leftPrefix, outCodes)
 
        val rightPrefix = prefix + true
        generateCodes(node.right, rightPrefix, outCodes)
    }
}
 
fun main(args: Array<String>) {
    // Build frequency table
    val frequencies = IntArray(UniqueSymbols)
    var ptr = 0
    while (ptr < SampleString.length) {
        ++frequencies[SampleString[ptr++]]
    }
 
    val root = buildTree(frequencies)
 
    val codes = HashMap<Char, HuffCode>()
    generateCodes(root, emptyList(), codes)
 
    for ((key, value) in codes) {
        println("$key ${value.reversed()}")
    }
};1

fun sumsqd(n: Int): Int {
    var sq = 0
    var t = n
    while (t > 0) {
        val d = t % 10
        sq += d * d
        t /= 10
    }
    return sq
}
 
fun <T> cycle(a: T, f: (T) -> T): T {
    var t = a
    var h = f(a)
 
    while (t!= h) {
        t = f(t)
        h = f(f(h))
    }
    return t
}
 
fun ishappy(n: Int): Boolean {
    return cycle(n, ::sumsqd) == 1
}
 
