fun tallyUniqueNumbers(matrix: List<List<List<Int>>>): Map<Int, Int> {
    val counter = mutableMapOf<Int, Int>()
    for (plane in matrix) {
        for (row in plane) {
            for (num in row) {
                counter[num] = counter.getOrDefault(num, 0) + 1
            }
        }
    }
    return counter
