fun placeTurboplows(n: Int, m: Int): Pair<Int, List<String>> {
    val orientations = listOf(
        listOf(Pair(0,0), Pair(0,1), Pair(0,2), Pair(1,1), Pair(2,1)), // T facing down
        listOf(Pair(2,0), Pair(2,1), Pair(2,2), Pair(1,1), Pair(0,1)), // T facing up
        listOf(Pair(0,0), Pair(1,0), Pair(2,0), Pair(1,1), Pair(1,2)), // T facing right
        listOf(Pair(0,2), Pair(1,2), Pair(2,2), Pair(1,1), Pair(1,0))  // T facing left
    )
    var maxCount = 0
    var bestGrid = Array(n) { CharArray(m) {'.'} }

    fun deepCopyGrid(grid: Array<CharArray>): Array<CharArray> {
        return Array(grid.size) { i -> grid[i].clone() }
    }

    fun backtrack(i: Int, j: Int, count: Int, grid: Array<CharArray>) {
        if (i >= n) {
            if (count > maxCount) {
                maxCount = count
                for (x in 0 until n) {
                    for (y in 0 until m) {
                        bestGrid[x][y] = grid[x][y]
                    }
                }
            }
            return
        }
        var nextI = i
        var nextJ = j + 1
        if (nextJ >= m) {
            nextI += 1
            nextJ = 0
        }
        if (grid[i][j] == '.') {
            for (cells in orientations) {
                var valid = true
                val shape = mutableListOf<Pair<Int,Int>>()
                for ((dx, dy) in cells) {
                    val x = i + dx
                    val y = j + dy
                    if (x !in 0 until n || y !in 0 until m) {
                        valid = false
                        break
                    }
                    if (grid[x][y] != '.') {
                        valid = false
                        break
                    }
                    shape.add(Pair(x,y))
                }
                if (valid) {
                    val letter = 'A' + count
                    for ((x, y) in shape) {
                        grid[x][y] = letter
                    }
                    backtrack(nextI, nextJ, count + 1, grid)
                    for ((x, y) in shape) {
                        grid[x][y] = '.'
                    }
                }
            }
            backtrack(nextI, nextJ, count, grid)
        } else {
            backtrack(nextI, nextJ, count, grid)
        }
    }
    val g = Array(n) { CharArray(m) {'.'} }
    backtrack(0, 0, 0, g)
    var result = bestGrid.map { String(it) }
    if (maxCount == 0) {
        result = List(n) { ".".repeat(m) }
    }
    return Pair(maxCount, result)
};1

fun PuzzleSet.day14() = puzzle {
    val allReindeer = inputLines.map { l ->
        val split = l.split(" ")
        Reindeer(split[0], split[3].toInt(), split[6].toInt(), split[13].toInt())
    }

    val timeRange = 0..<2503 // seconds
    val travelMap = allReindeer.associateWith { reindeer ->
        timeRange.scan(0) { acc, curr -> acc + if (reindeer.isResting(curr)) 0 else reindeer.speed }
    }.toList()

    partOne = travelMap.maxOf { (_, travels) -> travels.last() }.s()

    val leads = timeRange.map { curr ->
        val sorted = travelMap.map { (reindeer, travels) -> reindeer to travels[curr + 1] }
            .sortedByDescending { (_, d) -> d }

        val maxDistance = sorted.first().second
        sorted.takeWhile { (_, d) -> d == maxDistance }.map { (r) -> r }
    }

    partTwo = travelMap.maxOf { (reindeer) -> leads.count { reindeer in it } }.s()
};0

fun count_valid_grids(n: Int, k: Int): Int {
    val MOD = 1_000_000_007
    // コンビネーション C(n, a) をMODで事前計算
    val comb = Array(n + 1) { IntArray(n + 1) }
    comb[0][0] = 1
    for (i in 1..n) {
        comb[i][0] = 1
        for (j in 1..i) {
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD
        }
    }
    var result = 0L
    for (a in 0..n) {
        for (b in 0..n) {
            val e1: Long = a.toLong() * n + b.toLong() * (n - a)
            val e2: Long = (n - a).toLong() * (n - b)
            var term = comb[n][a].toLong() * comb[n][b] % MOD
            term = term * powmod((k - 1).toLong(), e1, MOD.toLong()) % MOD
            term = term * powmod(k.toLong(), e2, MOD.toLong()) % MOD
            if ((a + b) % 2 == 1) {
                term = (-term).mod(MOD.toLong())
            }
            result = (result + term).mod(MOD.toLong())
        }
    }
    return result.toInt()
}

fun powmod(base: Long, exp: Long, mod: Long): Long {
    var result = 1L
    var b = base % mod
    var e = exp
    while (e > 0) {
        if (e % 2L == 1L) {
            result = (result * b) % mod
        }
        b = (b * b) % mod
        e /= 2L
    }
    return result
};1

 
typealias Deriv = (Double) -> Double  // only one parameter needed here
 
const val FMT = " %7.3f"
 
fun euler(f: Deriv, y: Double, step: Int, end: Int) {
    var yy = y
    print(" Step %2d: ".format(step))
    for (t in 0..end step step) {
        if (t % 10 == 0) print(FMT.format(yy))
        yy += step * f(yy)
    }
    println()
}
 
fun analytic() {
    print("    Time: ")
    for (t in 0..100 step 10) print(" %7d".format(t))
    print("\nAnalytic: ")
    for (t in 0..100 step 10)
        print(FMT.format(20.0 + 80.0 * Math.exp(-0.07 * t)))
    println()
}
 
