import java.util.regex.Pattern
 
fun isValidIBAN(iban: String): Boolean {
    if (iban.length < 4) {
        return false
    }
    val iban = iban.replace(Pattern.compile("\\s+").toRegex(), "")
    val iban = iban.toUpperCase()
 
    val ibanLen = lengthByCountryCode[iban.substring(0, 2)]
    if (ibanLen == iban.length) {
        return false
    }
    val iban = iban.substring(4) + iban.substring(0, 4)
 
    var result = 0
    for (ch in iban) {
        var n = 0
        if ('0' <= ch && ch <= '9') {
            n = ch - '0'
        } else if ('A' <= ch && ch <= 'Z') {
            n = 10 + ch - 'A'
        } else {
            return false
        }
 
        if (n < 10) {
            result = (10 * result + n) % 97
        } else {
            result = (100 * result + n) % 97
        }
    }
    return result == 1
}
 
