// O(m + n) time | O(1) space
fun merge(nums1: IntArray, m: Int, nums2: IntArray, n: Int) {
    var high1 = m - 1
    var high2 = n - 1

    for (i in nums1.size - 1 downTo 0) {
        when {
            high2 < 0 -> return
            high1 >= 0 && nums1[high1] > nums2[high2] -> nums1[i] = nums1[high1--]
            else -> nums1[i] = nums2[high2--]
        }
    }
};0

