/**
 * Questions 47: Give a matrix with m * n, different number(more than 0) in different lattice, you can start in left-top,
 * and you can move a lattice toward bottom or right, until to right-bottom,
 * find the best way to get the sum of numbers on the path
 */
fun getBiggestNumber(matrix: Array<IntArray>): Int {
    require(matrix.isNotEmpty() && matrix.first().isNotEmpty()) { "The matrix can't be empty" }
    val first = matrix.first().first()
    return when {
        matrix.size == 1 && matrix.first().size == 1 -> matrix.first().first()
        matrix.size > 1 && matrix.first().size == 1 -> matrix.getBiggestNumber(1, 0, first)
        matrix.size == 1 && matrix.first().size > 1 -> matrix.getBiggestNumber(0, 1, first)
        else -> max(
            matrix.getBiggestNumber(0, 1, first),
            matrix.getBiggestNumber(1, 0, first),
        )
    }
};0

fun maxPartitionK(S: String): Int {
    val n = S.length
    if (n == 0) return 0

    val Base = 911382629L
    val Mod = 1000000000000000003L

    val prefix = LongArray(n + 1) { 0L }
    val power = LongArray(n + 1) { 1L }
    for (i in 0 until n) {
        prefix[i + 1] = (prefix[i] * Base + S[i].code.toLong()) % Mod
        power[i + 1] = (power[i] * Base) % Mod
    }

    fun getHash(l: Int, r: Int): Long {
        var res = (prefix[r + 1] - prefix[l] * power[r - l + 1]) % Mod
        if (res < 0) res += Mod
        return res
    }

    var currentStart = 0
    var prevStart = 0
    var prevEnd = -1
    var K = 0

    for (i in 0 until n) {
        val currentEnd = i
        if (K == 0) {
            K += 1
            prevStart = currentStart
            prevEnd = currentEnd
            currentStart = i + 1
        } else {
            val prevLength = prevEnd - prevStart + 1
            val currentLength = currentEnd - currentStart + 1
            if (currentLength != prevLength) {
                K += 1
                prevStart = currentStart
                prevEnd = currentEnd
                currentStart = i + 1
            } else {
                val currentH = getHash(currentStart, currentEnd)
                val prevH = getHash(prevStart, prevEnd)
                if (currentH != prevH) {
                    K += 1
                    prevStart = currentStart
                    prevEnd = currentEnd
                    currentStart = i + 1
                }
            }
        }
    }
    if (currentStart <= n - 1) {
        val remainingLength = (n - 1) - currentStart + 1
        if (K == 0) {
            K += 1
        } else {
            val prevH = getHash(prevStart, prevEnd)
            val currentH = getHash(currentStart, n - 1)
            if (currentH != prevH) {
                K += 1
            }
        }
    }
    return K
};1

fun findMax(nums: List<Int>): Int? {
    // Returns the maximum integer in the list `nums`.
    // If the list is empty, returns null.
    if (nums.isEmpty()) {
        return null
    }

    var currentMax = nums[0] // Initialize with the first element
    for (i in 1 until nums.size) {
        val num = nums[i]
        if (num > currentMax) {
            currentMax = num
        }
    }
    return currentMax
