fun tiltHorizontal(grid: List<CharArray>, west: Boolean): Int {
    val spaces = IntArray(grid.size)
    var sum = 0
    val progression = grid[0].indices.run { if (west) this else reversed() }
    for (i in progression) {
        for (j in grid.indices) when (val cell = grid[j][i]) {
            '#' -> spaces[j] = 0
            '.' -> spaces[j]++
            else -> {
                if (spaces[j] > 0) {
                    val dest = if (west) i - spaces[j] else i + spaces[j]
                    grid[j][dest] = cell
                    grid[j][i] = '.'
                }
                sum += grid.size - j
            }
        }
    }
    return sum
};0

import kotlin.math.sqrt
 
class Integer
 
  fun divisors(): List<Int> {
    val res = mutableListOf(1, this)
    for (n in 2..sqrt(this.toDouble()).toInt()) {
      val (div, mod) = this.divMod(n)
      if (mod == 0) {
        res.add(n)
        res.add(div)
      }
    }
    return res.distinct().sorted()
  }
 
  fun zumkeller(): Boolean {
    val divs = divisors()
    val sum = divs.sum()
    if (sum % 2!= 0 || sum < this * 2) return false
    val half = sum / 2
    val maxCombiSize = divs.size / 2
    for (combiSize in 1..maxCombiSize) {
      val combis = divs.combinations(combiSize)
      if (combis.any { it.sum() == half }) return true
    }
    return false
  }
 
}
 
