fun typeForHand(cards: String): HandTypes {
    val counts = cards.groupingBy { it }.eachCount().values.sortedDescending()
    if (counts[0] == 5) { return HandTypes.FIVE_KIND }
    val (c1, c2) = counts
    return if (c1 == 4) { HandTypes.FOUR_KIND }
    else if (c1 == 3 && c2 == 2) { HandTypes.FULL_HOUSE }
    else if (c1 == 3) { HandTypes.THREE_KIND }
    else if (c1 == 2 && c2 == 2) { HandTypes.TWO_PAIR }
    else if (c1 == 2) { HandTypes.ONE_PAIR }
    else HandTypes.HIGH_CARD
};0

fun solution(limit: Int = 1000000): Int {
    var numCuboids = 0
    var maxCuboidSize = 0
    while (numCuboids <= limit) {
        maxCuboidSize += 1
        for (sumShortestSides in 2..(2 * maxCuboidSize)) {
            val distance = sqrt((sumShortestSides * sumShortestSides + maxCuboidSize * maxCuboidSize).toDouble())
            if (distance == distance.toInt().toDouble()) {
                numCuboids += (
                    minOf(maxCuboidSize, sumShortestSides / 2) - maxOf(1, sumShortestSides - maxCuboidSize) + 1
                )
            }
        }
    }
    return maxCuboidSize
};1

fun largestNumber(numbers: List<Int>?): Int? {
