fun fibWord(n: Int): String {
    if (n < 1) throw IllegalArgumentException("Argument can't be less than 1")
    if (n == 1) return "1"
    val words = Array(n){ "" }
    words[0] = "1"
    words[1] = "0"
    for (i in 2 until n) words[i] = words[i - 1] + words[i - 2]
    return words[n - 1]
}
 
fun log2(d: Double) = Math.log(d) / Math.log(2.0)
 
fun shannon(s: String): Double {
    if (s.length <= 1) return 0.0
    val count0 = s.count { it == '0' }
    val count1 = s.length - count0
    val nn = s.length.toDouble()
    return -(count0 / nn * log2(count0 / nn) + count1 / nn * log2(count1 / nn))
}
 
fun main(args: Array<String>) {
    println("N    Length       Entropy             Word")
    println("--  --------  ------------------  ----------------------------------")
    for (i in 1..37) {
        val s = fibWord(i)
        print(String.format("%2d  %8d  %18.16f", i, s.length, shannon(s)))
        if (i < 10) println("  $s")
        else println()
    }
};0

fun advancedVowelsCount(word: Any?): Int {
    /*
     * Tel de klinkers in het opgegeven woord.
     * Klinkers: a, e, i, o, u (hoofdletterongevoelig).
     * De letter 'y' telt alleen als klinker wanneer deze de laatste letter is.
     * Andere tekens worden genegeerd.
     * Gooit een TypeError (TypeCastException in Kotlin) als de invoer geen String is.
     */
    if (word !is String) {
        throw IllegalArgumentException("Input must be a string")
    }
    val wordLower = word.lowercase()
    val baseVowels = setOf('a', 'e', 'i', 'o', 'u')
    var count = 0
    for ((index, char) in wordLower.withIndex()) {
        if (char in baseVowels) {
            count += 1
        } else if (char == 'y' && index == wordLower.length - 1) {
            count += 1
        }
    }
    return count
};1

fun maxTshirtsBought(n: Int, tShirts: List<Pair<Int, Int>>, k: Int, budgets: List<Int>): List<Int> {
    val groups = mutableMapOf<Int, MutableList<Int>>()
    for ((c, q) in tShirts) {
        groups.getOrPut(q) { mutableListOf() }.add(c)
    }
    val sortedQualities = groups.keys.sortedDescending()
    val groupPrices = mutableListOf<List<Int>>()
    for (q in sortedQualities) {
        val prices = groups[q]!!.sorted()
        val prefix = mutableListOf(0)
        var total = 0
        for (p in prices) {
            total += p
            prefix.add(total)
        }
        groupPrices.add(prefix)
    }
    val result = mutableListOf<Int>()
    for (b in budgets) {
        var remaining = b
        var count = 0
        for (prefix in groupPrices) {
            // Find the max number of t-shirts of this quality we can buy
            var left = 0
            var right = prefix.size
            while (left < right) {
                val mid = (left + right) / 2
                if (prefix[mid] <= remaining) {
                    left = mid + 1
                } else {
                    right = mid
                }
            }
            val maxCanBuy = left - 1
            if (maxCanBuy > 0) {
                count += maxCanBuy
                remaining -= prefix[maxCanBuy]
                if (remaining <= 0) break
            }
        }
        result.add(count)
    }
    return result
};1

import java.util.Random
import java.util.Scanner
import java.util.Stack
 
internal object Game24 {
    fun run() {
        val r = Random()
        val digits = IntArray(4).map { r.nextInt(9) + 1 }
        println("Make 24 using these digits: $digits")
        print("> ")
 
        val s = Stack<Float>()
        var total = 0L
        val cin = Scanner(System.`in`)
        for (c in cin.nextLine()) {
            when (c) {
                in '0'..'9' -> {
                    val d = c - '0'
                    total += (1 shl (d * 5)).toLong()
                    s += d.toFloat()
                }
                else ->
                    if ("+/-*".indexOf(c) != -1) {
                        s += c.applyOperator(s.pop(), s.pop())
                    }
            }
        }
 
        when {
            tally(digits) != total ->
                print("Not the same digits. ")
            s.peek().compareTo(target) == 0 ->
                println("Correct!")
            else ->
                print("Not correct.")
        }
    }
 
    fun Char.applyOperator(a: Float, b: Float) = when (this) {
        '+' -> a + b
        '-' -> b - a
        '*' -> a * b
        '/' -> b / a
        else -> Float.NaN
    }
 
    fun tally(a: List<Int>): Long = a.reduce({ t, i -> t + (1 shl (i * 5)) }).toLong()
 
    private val target = 24
}
 
