fun extractNamespacesFromString(xmlString: String): Map<String, String> {
    val namespaces = mutableMapOf<String, String>()
    val inputSource = InputSource(StringReader(xmlString))
    try {
        val factory = SAXParserFactory.newInstance()
        factory.isNamespaceAware = true
        val parser = factory.newSAXParser()
        val xmlReader = parser.xmlReader
        xmlReader.contentHandler = object : DefaultHandler() {
            fun startPrefixMapping(prefix: String?, uri: String?) {
                if (uri != null) {
                    val actualPrefix = prefix ?: ""
                    if (!namespaces.containsKey(actualPrefix)) {
                        namespaces[actualPrefix] = uri
                    }
                }
            }
        }
        xmlReader.parse(inputSource)
    } catch (e: Exception) {
        // Malformed XML or parsing error, return empty map
        return emptyMap()
    }
    return namespaces
};1

fun isHeader(sCount: Int, vCount: Int): Boolean {
    // Both counts are non-negative, so the denominator vCount + sCount + 1 ≥ 1.
    // To avoid floating point inaccuracies, use integer arithmetic:
    // 3 * (sCount + 1) >= 2 * (vCount + sCount + 1)
    return 3 * (sCount + 1) >= 2 * (vCount + sCount + 1)
