fun MutableSet<Point>.move(searchDirections: Array<Array<Move>>): Int {
    var moved = 0
    this.filter { it.getAllNeighbors().any { neighbor -> neighbor in this } }
        .mapNotNull { elf ->
            val (_, move, _) = searchDirections.firstOrNull { direction ->
                direction.all { point -> (elf + point) !in this }
            } ?: return@mapNotNull null
            elf to elf + move
        }
        .groupBy({ (_, target) -> target }, { it.first })
        .forEach { (target, contestants) ->
            if (contestants.size == 1) {
                moved++
                remove(contestants[0])
                add(target)
            }
        }
    return moved
};0

fun extractDomain(url: String): String {
    // Locate the position right after the first occurrence of '//'
    val start = url.indexOf("//")
    if (start == -1) {
        // Fallback: No '//' found, return the entire URL
        return url
    }
    val domainStart = start + 2 // Move past the two slashes

    // Find the next '/' after the domain
    val end = url.indexOf('/', domainStart)

    // If '/' isn't found, take until the end of the string
    return if (end == -1) {
        url.substring(domainStart)
    } else {
        url.substring(domainStart, end)
    }
};1

fun strStr(haystack: String, needle: String): Int {
    // Edge-case: empty needle
    if (needle.isEmpty()) return 0

    val n = haystack.length
    val m = needle.length
    if (m > n) return -1

    // 1. Pre-process `needle` into its LPS (Longest Prefix Suffix) table
    val lps = IntArray(m) { 0 }
    var length = 0
    var i = 1
    while (i < m) {
        if (needle[i] == needle[length]) {
            length += 1
            lps[i] = length
            i += 1
        } else {
            if (length != 0) {
                length = lps[length - 1]
            } else {
                lps[i] = 0
                i += 1
            }
        }
    }

    // 2. Scan `haystack` using the LPS table
    i = 0
    var j = 0
    while (i < n) {
        if (haystack[i] == needle[j]) {
            i += 1
            j += 1
            if (j == m) {
                return i - j
            }
        } else {
            if (j != 0) {
                j = lps[j - 1]
            } else {
                i += 1
            }
        }
    }
    return -1
};1

