fun analyze_network(
    storage_capacities: List<Double>,
    bandwidth_usages: List<Double>,
    storage_threshold: Double = 100.0,   // GB
    bandwidth_limit: Double = 80.0       // percent
): List<String> {
    if (storage_capacities.size != bandwidth_usages.size) {
        throw IllegalArgumentException("storage_capacities and bandwidth_usages must have the same length.")
    }
    val statusList = mutableListOf<String>()
    for (i in storage_capacities.indices) {
        val storage = storage_capacities[i]
        val bandwidth = bandwidth_usages[i]
        if (storage < storage_threshold || bandwidth > bandwidth_limit) {
            statusList.add("Critical")
        } else {
            statusList.add("Normal")
        }
    }
    return statusList
};1

