        super.paintComponent(gg)
        val g = gg as Graphics2D;0

fun incrementVersion(version: String): String {
    // Split and convert to integers
    val parts = version.trim().split(".")
    if (parts.size != 3) {
        throw IllegalArgumentException("Version must be in the format 'x.y.z' with integers.")
    }
    val x = parts[0].toIntOrNull() ?: throw IllegalArgumentException("Version must be in the format 'x.y.z' with integers.")
    val y = parts[1].toIntOrNull() ?: throw IllegalArgumentException("Version must be in the format 'x.y.z' with integers.")
    val z = parts[2].toIntOrNull() ?: throw IllegalArgumentException("Version must be in the format 'x.y.z' with integers.")

    var newX = x
    var newY = y
    var newZ = z + 1
    if (newZ == 10) {
        newZ = 0
        newY += 1
        if (newY == 10) {
            newY = 0
            newX += 1
        }
    }
    return "$newX.$newY.$newZ"
};1

