fun findPairs(nums: IntArray, k: Int): Int {
    val countMap = mutableMapOf<Int, Int>()
    nums.forEach {
        countMap[it] = countMap.getOrDefault(it, 0) + 1
    }
    val seen = mutableSetOf<Pair<Int, Int>>()
    for (it in nums.distinct()) {
        val other = k + it
        val pair = Pair(minOf(other, it), maxOf(other, it))

        // already seen
        if (seen.contains(pair)) {
            continue
        }
        // other == it is the case when k = 0
        // It requires preventing self match in the [countMap]
        if (other == it && countMap[it]!! > 1) { // given k=0, [it] is repeated in the [nums]
            seen.add(pair)
            continue
        } else if (other == it) { // given k=0, [it] is not repeated so don't add this to [seen]
            continue
        }
        if (countMap.containsKey(other)) {
            seen.add(pair)
        }
    }
    return seen.size
};0

fun parse(path: String): Schematic {
    val parts = mutableListOf<Part>()
    val symbols = mutableListOf<Symbol>()

    val data = File(path).readLines()
    for ((y, line) in data.withIndex()) {
        val (matchedParts, matchedSymbols) = PATTERN.findAll(line)
            .partition { it.value[0].isDigit() }

        parts.addAll(matchedParts.map {
            val a = it.range.first
            val b = it.range.last

            val rx = (a - 1)..(b + 1)
            val ry = (y - 1)..(y + 1)

            Part(rx, ry, it.value.toInt())
        })

        symbols.addAll(matchedSymbols.map {
            Symbol(x = it.range.first, y, it.value[0])
        })
    }

    return Schematic(parts, symbols)
};0

