class Vector(val x: Double, val y: Double) {
    companion object {
        fun polar(r: Double, angle: Double = 0.0): Vector {
            return Vector(r * cos(angle), r * sin(angle))
        }
    }
 
    operator fun plus(other: Vector): Vector {
        return Vector(x + other.x, y + other.y)
    }
 
    operator fun unaryMinus(): Vector {
        return Vector(-x, -y)
    }
 
    operator fun minus(other: Vector): Vector {
        return this + (-other)
    }
 
    operator fun times(scalar: Double): Vector {
        return Vector(x * scalar, y * scalar)
    }
 
    operator fun div(scalar: Double): Vector {
        return Vector(x / scalar, y / scalar)
    }
 
    val r: Double
        get() = hypot(x, y)
 
    val angle: Double
        get() = atan2(y, x)
 
    val polar: Pair<Double, Double>
        get() = Pair(r, angle)
 
    val rect: Pair<Double, Double>
        get() = Pair(x, y)
 
    fun toString(): String {
        return "Vector[$x, $y]"
    }
}
 
