import java.util.ArrayList
import java.util.Collections
 
fun UpTo(n: Int, offset: Int = 0): ArrayList<Int> {
    val retval = ArrayList<Int>(n)
    for (ii in 0 until n)
        retval.add(ii + offset)
    return retval
}
 
class JohnsonTrotterState(n: Int) {
    val values_ = UpTo(n, 1)
    val positions_ = UpTo(n + 1, -1)    // size is n+1, first element is not used
    val directions_ = ArrayList<Boolean>(n + 1)
    var sign_ = 1
 
    init {
        for (ii in 0..n)
            directions_.add(false)
    }
 
    fun LargestMobile(): Int {  // returns 0 if no mobile integer exists
        for (r in values_.size - 1 downTo 0) {
            val loc = positions_[r] + if (directions_[r]) 1 else -1
            if (loc >= 0 && loc < values_.size && values_[loc] < r)
                return r
        }
        return 0
    }
 
    fun IsComplete(): Boolean = LargestMobile() == 0
 
    fun inc() { // implement Johnson-Trotter algorithm
        val r = LargestMobile()
        val rLoc = positions_[r]
        val lLoc = rLoc + if (directions_[r]) 1 else -1
        val l = values_[lLoc]
        // do the swap
        Collections.swap(values_, lLoc, rLoc)
        Collections.swap(positions_, l, r)
        sign_ = -sign_
        // change directions
        for (pd in directions_.listIterator(r + 1))
            pd =!pd
    }
}
 
