class StdDev {
    var n = 0
    var sum = 0.0
    var sum2 = 0.0

    fun sd(x: Double): Double {
        n++
        sum += x
        sum2 += x * x

        return Math.sqrt(sum2 / n - sum * sum / n / n)
    }

    companion object {
        @JvmStatic
        fun main(args: Array<String>) {
            val testData = doubleArrayOf(2.0, 4.0, 4.0, 4.0, 5.0, 5.0, 7.0, 9.0)
            val sd = StdDev()

            for (x in testData) {
                println(sd.sd(x))
            }
        }
    }
};1

fun <T, R> apply(f: (T) -> R, t: T): R = f(t)
 
fun <T, R> y(f: (T) -> R): (T) -> R = { t -> apply(y(f), t) }
 
fun fac(n: Int): Int {
    val almostFac = { f: (Int) -> Int, x: Int -> if (x == 0) 1 else x * f(x - 1) }
    return y(almostFac)(n)
}
 
fun fib(n: Int): Int {
    val almostFib = { f: (Pair<Int, Int>) -> Int, x: Pair<Int, Int> ->
        val (a0, a1) = x
        when (a0) {
            0 -> a1
            1 -> a0 + a1
            else -> f(Pair(a1, a0 + a1))
        }
    }
    return y(almostFib)(Pair(1, 1))
}
 
