fun electionResults(votes: List<String>): Pair<Map<String, Int>, String> {
    // Tally the votes
    val tally = votes.groupingBy { it }.eachCount()

    // If no votes were cast, treat it as a tie
    if (tally.isEmpty()) {
        return Pair(emptyMap(), "Tie")
    }

    // Find the highest vote count
    val maxVotes = tally.values.maxOrNull() ?: 0

    // All candidates who have the highest vote count
    val topCandidates = tally.filter { it.value == maxVotes }.keys.toList()

    // Decide the winner
    val winner = if (topCandidates.size == 1) topCandidates[0] else "Tie"

    return Pair(tally, winner)
};1

