fun validateData(read: Map<String, Any>): String {
    val expected = mapOf(
        "read_group" to 0,
        "digitisation" to 8192.0,
        "offset" to 23.0,
        "range" to 1467.61,
        "sampling_rate" to 4000.0
    )
    for (key in listOf("read_group", "digitisation", "offset", "range", "sampling_rate")) {
        val expectedValue = expected[key]
        val readValue = read[key]
        if (expectedValue is Double && readValue is Double) {
            if (readValue != expectedValue) return key
        } else if (expectedValue is Int && readValue is Int) {
            if (readValue != expectedValue) return key
        } else {
            if (readValue != expectedValue) return key
        }
    }
