fun parseCommand(line: String): Pair<String, WorkFlow> {
    val openIndex = line.indexOf('{')
    val closesIndex = line.indexOf('}')
    val label = line.substring(0, openIndex)
    val rules = line.substring(openIndex + 1, closesIndex).split(',').map { it.trim() }

    val rulesList = rules.subList(0, rules.lastIndex).map { r ->
        r.split(':').let { (s1, ll) ->
            val (property, number) = s1.split('<', '>')
            val supplier = when (property) {
                "a" -> Part::a
                "x" -> Part::x
                "m" -> Part::m
                "s" -> Part::s
                else -> throw IllegalArgumentException("Could not handle $property")
            }
            if (s1.contains('<')) {
                buildLessRule(supplier, number.toInt(), ll)
            } else {
                buildMoreRule(supplier, number.toInt(), ll)
            }
        }
    }
    return Pair(label, WorkFlow(rulesList, rules.last))
};0

var TREE_LIST = mutableListOf<Int>()
var OFFSET = mutableListOf<Int>()
 
fun append(t: Int) {
    TREE_LIST.add(1 or (t shl 1))
}
 
fun show(t: Int, l: Int) {
    var l = l
    while (l > 0) {
        l--
        if (t and 1 == 1) {
            print('(')
        } else {
            print(')')
        }
        t = t shr 1
    }
}
 
fun listTrees(n: Int) {
    for (i in OFFSET[n]..OFFSET[n + 1] - 1) {
        show(TREE_LIST[i], n * 2)
        println()
    }
}
 
fun assemble(n: Int, t: Int, sl: Int, pos: Int, rem: Int) {
    if (rem == 0) {
        append(t)
        return
    }
 
    if (sl > rem) {
        sl = rem
        pos = OFFSET[sl]
    } else if (pos >= OFFSET[sl + 1]) {
        sl--
        if (sl == 0) {
            return
        }
        pos = OFFSET[sl]
    }
 
    assemble(n, t shl (2 * sl) or TREE_LIST[pos], sl, pos, rem - sl)
    assemble(n, t, sl, pos + 1, rem)
}
 
fun makeTrees(n: Int) {
    if (OFFSET[n + 1]!= 0) {
        return
    }
    if (n > 0) {
        makeTrees(n - 1)
    }
    assemble(n, 0, n - 1, OFFSET[n - 1], n - 1)
    OFFSET[n + 1] = TREE_LIST.size
}
 
fun test(n: Int) {
    if (n < 1 || n > 12) {
        throw IllegalArgumentException("Argument must be between 1 and 12")
    }
 
    append(0)
 
    makeTrees(n)
    println("Number of %d-trees: %d".format(n, OFFSET[n + 1] - OFFSET[n]))
    listTrees(n)
}
 
fun main(args: Array<String>) {
