import kotlin.streams.asSequence
 
fun main() {
    val target = "METHINKS IT IS LIKE A WEASEL"
    val C = 100
    val P = 0.05
 
    // Start with a random string the same length as the target.
    var parent = Random.nextString(target.length)
 
    println("START:       ${parent.padEnd(20)} fitness: ${fitness(target, parent)}")
    var i = 0
 
    while (parent!= target) {
        // Create C mutated strings + the current parent.
        val candidates = (0..C).asSequence()
           .map { if (it > 0) mutate(parent, P) else parent }
 
        // select the fittest
        parent = candidates.maxBy { fitness(target, it) }!!
 
        ++i
        println("     #$i ${parent.padEnd(20)} fitness: ${fitness(target, parent)}")
    }
 
    println("END: #$i ${parent.padEnd(20)}")
}
 
fun fitness(target: String, current: String): Int {
    return target.zip(current).map { if (it.first == it.second) 1 else 0 }.sum()
