fun sumOfDecimals(S: String, T: String): Int {
    val MOD = 1000000007
    val n = S.length
    var current_lt = 0L
    var current_lt_sum = 0L
    var current_eq = 1L
    var current_eq_sum = 0L
    for (i in 0 until n) {
        val s_digit = S[i].toString().toInt()
        val t_char = T[i]
        val digits = if (t_char == '?') (0..9) else listOf(t_char.toString().toInt())
        var new_lt = 0L
        var new_lt_sum = 0L
        var new_eq = 0L
        var new_eq_sum = 0L
        // Process transitions from eq state
        if (current_eq > 0) {
            for (d in digits) {
                if (d < s_digit) {
                    new_lt = (new_lt + current_eq) % MOD
                    new_lt_sum = (new_lt_sum + current_eq_sum * 10 % MOD + d * current_eq % MOD) % MOD
                } else if (d == s_digit) {
                    new_eq = (new_eq + current_eq) % MOD
                    new_eq_sum = (new_eq_sum + current_eq_sum * 10 % MOD + d * current_eq % MOD) % MOD
                }
            }
        }
        // Process transitions from lt state
        if (current_lt > 0) {
            for (d in digits) {
                new_lt = (new_lt + current_lt) % MOD
                new_lt_sum = (new_lt_sum + current_lt_sum * 10 % MOD + d * current_lt % MOD) % MOD
            }
        }
        current_lt = new_lt
        current_lt_sum = new_lt_sum
        current_eq = new_eq
        current_eq_sum = new_eq_sum
    }
    return (((current_lt_sum + current_eq_sum) % MOD) + MOD) % MOD .toInt()
};1

fun executeProgram(code: IntArray, noun: Int, verb: Int): Int {
  var pointer = 0
  code[1] = noun
  code[2] = verb
  while (code[pointer] != 99) {
    code[code[pointer + 3]] = when (code[pointer]) {
      1 -> code[code[pointer + 1]] + code[code[pointer + 2]]
      2 -> code[code[pointer + 1]] * code[code[pointer + 2]]
      else -> throw IllegalArgumentException("Invalid opcode ${code[pointer]}")
    }
    pointer += 4
  }
  return code[0]
};0

fun calculateGiniCoefficient(incomes: List<Double>): Double {
    if (incomes.isEmpty()) return 0.0
    val sortedIncomes = incomes.sorted()
    val n = sortedIncomes.size
    var cumulative = 0.0
    for ((i, income) in sortedIncomes.withIndex()) {
        cumulative += (i + 1) * income
    }
    val total = sortedIncomes.sum()
    val gini = (2 * cumulative) / (n * total) - (n + 1).toDouble() / n
    return String.format("%.2f", kotlin.math.abs(gini)).toDouble()
};1

fun isEligibleForLoan(income: Double, debts: List<Double>, loanAmount: Double, interestRate: Double, loanTerm: Int): Boolean {
    val totalMonthlyDebts = debts.sum()
    val monthlyInterestRate = interestRate / (100 * 12)
    val totalPayments = loanTerm * 12
    val monthlyLoanPayment = if (monthlyInterestRate == 0.0) {
        loanAmount / totalPayments
    } else {
        val pow = Math.pow(1 + monthlyInterestRate, totalPayments.toDouble())
        (loanAmount * monthlyInterestRate * pow) / (pow - 1)
    }
    val debtToIncomeRatio = ((totalMonthlyDebts + monthlyLoanPayment) / income) * 100
    return debtToIncomeRatio <= 36
};1

