const val LIMIT = 42
 
fun isPrime(n: Long): Boolean {
    if (n % 2 == 0L) return n == 2L
    if (n % 3 == 0L) return n == 3L
    var d = 5L
    while (d * d <= n) {
        if (n % d == 0L) return false
        d += 2
        if (n % d == 0L) return false
        d += 4
    }
    return true
}
 
