    for (title in titles) {
        val cleanTitle = title.lowercase().filter { !punctuation.contains(it) }
        val words = cleanTitle.split(" ").filter { it.isNotEmpty() }
        for (word in words) {
            wordFreq[word] = wordFreq.getOrDefault(word, 0) + 1
        }
    }
    return wordFreq
