object KnightTour {
    private const val N = 8
    private val moves = arrayOf(intArrayOf(+1, -2), intArrayOf(+2, -1), intArrayOf(+2, +1), intArrayOf(+1, +2),
            intArrayOf(-1, +2), intArrayOf(-2, +1), intArrayOf(-2, -1), intArrayOf(-1, -2))
    private class ListMoves(var x: Int, var y: Int)
 
//  public static void main(String[] args) {
    @JvmStatic fun main(args: Array<String>) {
        val board = Array(N) { IntArray(N) }
        for (i in 0 until N) {
            for (j in 0 until N) {
                board[i][j] = 0
            }
        }
 
        var x = 0
        var y = 0
 
        val list = ArrayList<ListMoves>()
        list.add(ListMoves(x, y))
 
        do {
            if (movePossible(board, x, y)) {
                val move = board[x][y]
                board[x][y]++
                x += moves[move][0]
                y += moves[move][1]
                list.add(ListMoves(x, y))
            } else {
                if (board[x][y] >= 8) {
                    board[x][y] = 0
                    list.removeAt(list.size - 1)
                    if (list.size == 0) {
                        println("No solution found.")
                        return
                    }
                    x = list[list.size - 1].x
                    y = list[list.size - 1].y
                }
                board[x][y]++
            }
        } while (list.size < N * N)
 
        var last_x = list[0].x
        var last_y = list[0].y
        val letters = "ABCDEFGH"
        for (i in 1 until list.size) {
            println(String.format("%2d:  ", i) + letters[last_x] + (last_y + 1) + " - " + letters[list[i].x] + (list[i].y + 1))
            last_x = list[i].x
            last_y = list[i].y
        }
    }
 
//  static boolean movePossible(int[][] board, int cur_x, int cur_y) {
    fun movePossible(board: Array<IntArray>, cur_x: Int, cur_y: Int): Boolean {
        if (board[cur_x][cur_y] >= 8) {
            return false
        }
 
        val new_x = cur_x + moves[board[cur_x][cur_y]][0]
        val new_y = cur_y + moves[board[cur_x][cur_y]][1]
 
        if (new_x >= 0 && new_x < N && new_y >= 0 && new_y < N && board[new_x][new_y] == 0) {
            return true
        }
 
        return false
    }
