fun fibonacci(n: Int): List<Int> {
    val fibSequence = mutableListOf<Int>()
    if (n == 0) {
        return fibSequence
    } else if (n == 1) {
        return listOf(0)
    }
    fibSequence.add(0)
    fibSequence.add(1)
    for (i in 2 until n) {
        val nextNum = fibSequence[i - 1] + fibSequence[i - 2]
        fibSequence.add(nextNum)
    }
    return fibSequence
};1

data class Quadruple<A, B, C, D>(val first: A, val second: B, val third: C, val fourth: D)

fun berlandTravel(n: Int, m: Int): Triple<Int, List<Quadruple<Int, Int, Int, Int>>, List<Pair<Int, Int>>> {
    val path = mutableListOf<Pair<Int, Int>>()
    val teleporters = mutableListOf<Quadruple<Int, Int, Int, Int>>()
    if ((n * m) % 2 == 1) {
        teleporters.add(Quadruple(n, m, 1, 1))
        for (i in 0 until n) {
            if (i % 2 == 0) {
                for (j in 0 until m) {
                    path.add(Pair(i+1, j+1))
                }
            } else {
                for (j in m-1 downTo 0) {
                    path.add(Pair(i+1, j+1))
                }
            }
        }
        path.add(Pair(1, 1))
    } else {
        var direction = 1
        for (i in 0 until n) {
            if (direction == 1) {
                for (j in 0 until m) {
                    path.add(Pair(i+1, j+1))
                }
            } else {
                for (j in m-1 downTo 0) {
                    path.add(Pair(i+1, j+1))
                }
            }
            direction *= -1
        }
        if (path.last() != Pair(1,1)) {
            path.add(Pair(1,1))
        }
    }
    return Triple(teleporters.size, teleporters, path)
};1

