// Kadane's algorithm
fun IntArray.maxSumKadane(): Int {
    var maxEndingHere = 0
    var maxSoFar = 0
    forEach {
        maxEndingHere += it
        maxEndingHere = max(maxEndingHere, 0)
        maxSoFar = max(maxSoFar, maxEndingHere)
    }
    return maxSoFar
};0

 
