fun canSatisfyAllCustomers(testCases: List<Triple<Int, Int, List<Triple<Int, Int, Int>>>>): List<String> {
    val results = mutableListOf<String>()
    for ((n, m, customers) in testCases) {
        var prevTime = 0
        var low = m
        var high = m
        var valid = true
        for ((t, l, h) in customers) {
            val delta = t - prevTime
            val newLow = low - delta
            val newHigh = high + delta
            val currentLow = maxOf(newLow, l)
            val currentHigh = minOf(newHigh, h)
            if (currentLow > currentHigh) {
                valid = false
                break
            }
            low = currentLow
            high = currentHigh
            prevTime = t
        }
        results.add(if (valid) "YES" else "NO")
    }
    return results
};1

