fun isKprime(n: Int, k: Int): Boolean {
    var primes = 0
    var f = 2
    var rem = n
    while (primes < k && rem > 1) {
        while (rem % f == 0 && rem > 1) {
            rem /= f
            primes++
        }
        f++
    }
    return rem == 1 && primes == k
}
 
class KPrimeGen(val k: Int) : Iterator<Int> {
    var n = 1
    fun hasNext(): Boolean = true
    fun next(): Int {
        n++
        while (!isKprime(n, k)) {
            n++
        }
        return n
    }
}
 
fun kprimeGenerator(k: Int): KPrimeGen = KPrimeGen(k)
 
