fun middleThreeDigits(x: Int): String {
    val s = x.toString()
    val len = s.length
    if (len < 3) {
        throw IllegalArgumentException("Too short")
    } else if (len % 2 == 0) {
        throw IllegalArgumentException("Even number of digits")
    } else {
        return s.substring(len/2 - 1, len/2 + 2)
    }
}
 
