/**
 * Questions 8: Give you a binary node, find the node's next node in binary's in-order.
 * The binary node has 3 points, left(point to left sub-node), right(point to right sub-node), father(point to father node)
 */
fun BinaryTreeNodeWithFather<Char>.findInOrderNextElement(): Char? = father?.let {
    right?.findFarLeftNode() ?: when {
        it.left === this -> father!!.value
        it.right === this -> father!!.findFatherThatLeftTree()
        else -> throw IllegalArgumentException("This is a exceptional binary tree")
    }
} ?: right?.findFarLeftNode();0

fun getFinalPosition(movements: List<Pair<Char, Int>>): Pair<Int, Int> {
    var x = 0
    var y = 0
    for ((direction, steps) in movements) {
        when (direction) {
            'N' -> y += steps
            'S' -> y -= steps
            'E' -> x += steps
            'W' -> x -= steps
        }
    }
    return Pair(x, y)
};1

fun isValidMove(chessboard: List<List<String>>, move: Pair<Pair<Int, Int>, Pair<Int, Int>>): Boolean {
    // Helper functions
    fun onBoard(r: Int, c: Int): Boolean = r in 0 until 8 && c in 0 until 8

    fun isEmpty(r: Int, c: Int): Boolean {
        val piece = chessboard[r][c]
        return piece == null || piece == "" || piece == "." || piece == " "
    }

    fun isWhite(piece: String): Boolean = piece.uppercase() == piece && piece != "" && piece != "." && piece != " "

    // Unpack move
    val (start, end) = move
    val (sr, sc) = start
    val (er, ec) = end

    if (!onBoard(sr, sc) || !onBoard(er, ec)) {
        return false
    }

    val piece = chessboard[sr][sc]
    if (piece != "P" && piece != "p") {
        return false
    }

    val destPiece = chessboard[er][ec]
    val whiteTurn = isWhite(piece)

    val forward = if (whiteTurn) -1 else 1
    val startRank = if (whiteTurn) 6 else 1

    // Forward pushes (same column)
    if (ec == sc) {
        if (!isEmpty(er, ec)) {
            return false
        }
        if (er == sr + forward) {
            return true
        }
        if (sr == startRank && er == sr + 2 * forward && isEmpty(sr + forward, sc)) {
            return true
        }
        return false
    }

    // Captures (diagonal, one square)
    if (kotlin.math.abs(ec - sc) == 1 && er == sr + forward) {
        if (destPiece == "" || destPiece == "." || destPiece == null || destPiece == " ") {
            return false
        }
        if (whiteTurn && destPiece.lowercase() == destPiece && destPiece != "" && destPiece != "." && destPiece != " ") {
            return true
        }
        if (!whiteTurn && destPiece.uppercase() == destPiece && destPiece != "" && destPiece != "." && destPiece != " ") {
            return true
        }
        return false
    }

    return false
};1

fun findLowestRiskPath(array: Array<IntArray>) {
    val length = array.size
    val width = array.first().size
    val delta = Array(length) { IntArray(width) { Int.MAX_VALUE } }
    val visited = Array(length) { BooleanArray(width) }

    delta[0][0] = 0
    queue.add(Position(0 to 0, 0))
    while (!visited[length - 1][width - 1]) {
        val (xy, risk) = queue.remove()
        val (x, y) = xy
        if (visited[x][y]) continue
        visited[x][y] = true

        edgeRelax(array, delta, visited, x - 1, y, risk)
        edgeRelax(array, delta, visited, x + 1, y, risk)
        edgeRelax(array, delta, visited, x, y - 1, risk)
        edgeRelax(array, delta, visited, x, y + 1, risk)
    }

    println(delta[length - 1][width - 1])
};0

 
import java.net.URL
import java.net.MalformedURLException
 
fun parseUrl(url: String) {
    var u: URL
    var scheme: String
    try {
        u = URL(url)
        scheme = u.protocol
    }
    catch (ex: MalformedURLException) {
        val index = url.indexOf(':')
        scheme = url.take(index)
        u = URL("http" + url.drop(index))
    }
    println("Parsing $url")
    println("  scheme   =  $scheme")
 
    with(u) {
        if (userInfo != null) println("  userinfo =  $userInfo")
        if (!host.isEmpty())  println("  domain   =  $host")
        if (port != -1)       println("  port     =  $port")
        if (!path.isEmpty())  println("  path     =  $path")
        if (query != null)    println("  query    =  $query")
        if (ref != null)      println("  fragment =  $ref")
    }
    println()
}
 
