fun calculateAverageScores(scores: List<Pair<String, Int>>): Map<String, Double> {
    val studentScores = mutableMapOf<String, MutableList<Int>>()
    for ((name, score) in scores) {
        if (name in studentScores) {
            studentScores[name]?.add(score)
        } else {
            studentScores[name] = mutableListOf(score)
        }
    }
    val averageScores = mutableMapOf<String, Double>()
    for ((name, sList) in studentScores) {
        val avg = sList.sum().toDouble() / sList.size
        averageScores[name] = String.format("%.2f", avg).toDouble()
    }
    return averageScores
