fun isPrime(n: Long): Boolean {
    return when {
        n == 0L || n == 1L -> false
        n == 2L -> true
        n % 2 == 0L -> false
        else -> {
            val sqrtLimit = Math.sqrt(n.toDouble()).toLong()
            (3..sqrtLimit step 2).none { n % it == 0L }
        }
    }
}
 
