    val len = input.size
 
    val map = TreeMap<String, IntArray> { a, b -> b.compareTo(a) }
    for (i in 0 until len) {
        val key = input[i].split("\\s+".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()[0]
        var arr: IntArray? = map[key]
        if (arr == null)
            arr = intArrayOf(i, 0)
        arr[1]++
        map[key] = arr
    }
    val groups = map.values.toTypedArray()
 
    standardRanking(len, groups)
    modifiedRanking(len, groups)
    denseRanking(len, groups)
    ordinalRanking(len)
    fractionalRanking(len, groups)
}
 
fun standardRanking(len: Int, groups: Array<IntArray>) {
    println("\nStandard ranking")
    var rank = 0
    var group = 0
    for (i in 0 until len) {
        if (group < groups.size && i == groups[group][0]) {
            rank = i + 1
            group++
        }
        println(String.format("%d %s", rank, input[i]))
    }
}
 
fun modifiedRanking(len: Int, groups: Array<IntArray>) {
    println("\nModified ranking")
    var rank = 0
    var group = 0
    for (i in 0 until len) {
        if (group < groups.size && i == groups[group][0])
            rank += groups[group++][1]
        println(String.format("%d %s", rank, input[i]))
    }
}
 
fun denseRanking(len: Int, groups: Array<IntArray>) {
    println("\nDense ranking")
    var rank = 0
    for (i in 0 until len) {
        if (rank < groups.size && i == groups[rank][0])
            rank++
        println(String.format("%d %s", rank, input[i]))
    }
}
 
fun ordinalRanking(len: Int) {
    println("\nOrdinal ranking")
    for (i in 0 until len)
        println(String.format("%d %s", i + 1, input[i]))
}
 
fun fractionalRanking(len: Int, groups: Array<IntArray>) {
    println("\nFractional ranking")
    var rank = 0f
    var tmp = 0
    var group = 0
    for (i in 0 until len) {
        if (group < groups.size && i == groups[group][0]) {
            tmp += groups[group++][1]
            rank = (i + 1 + tmp) / 2.0f
        }
        println(String.format("%2.1f %s", rank, input[i]))
    }
};1

/**
 * Returns a sequence containing the runs of equal elements and their respective count as Pairs.
 */
fun <T> Sequence<T>.runs(): Sequence<Pair<T, Int>> = sequence {
    val iterator = iterator()
    if (iterator.hasNext()) {
        var current = iterator.next()
        var count = 1
        while (iterator.hasNext()) {
            val next: T = iterator.next()
            if (next != current) {
                yield(current to count)
                current = next
                count = 0
            }
            count++
        }
        yield(current to count)
    }
};0

fun OneArray<Char>.maxQ(quality: (OneArray<Char>) -> Int): Int {
    val S = this
    val n = S.size

    // dp(i) = max sum of qualities of S[1..i]
    // memoization structure: 1d array dp[1..n] : dp[i] = dp(i)
    val dp = OneArray(n) { 0 }
    // space complexity: O(n)

    // base case:
    // dp(1) = quality(S[1..1])
    dp[1] = quality(S[1..1])
    // time complexity: O(1)

    // recursive case:
    // dp(i) = max{ dp(k) + S[k + 1..i] }, 1 <= k < i
    // dependency: dp(i) depends on dp[k] : k < i, that is entries to the left
    // evaluation order: outer loop for i from 2 to n (left to right)
    for (i in 2..n) {
        // inner loop for k from 1 until i
        dp[i] = (1 until i)
                .map { k -> dp[k] + quality(S[k..i]) }
                .max()!!
    }
    // time complexity: O(n^3)

    dp.prettyPrintln()

    // we want dp(n)
    return dp[n]
    // overall space complexity: O(n)
    // overall runtime complexity: O(n^3)
};0

