import java.util.ArrayList
import java.util.Arrays
import java.util.Collections
import java.util.List
import java.util.stream.Collectors
import java.util.stream.IntStream
 
fun main(args: Array<String>) {
    println("Unique-numbers combinations in range 1-7:")
    filterUnique(1, 8).forEach { println(it) }
    println("\nUnique-numbers combinations in range 3-9:")
    filterUnique(3, 10).forEach { println(it) }
    println("\nNumber of combinations in range 0-9: " + combinations(0, 10).size + ".")
}
 
//Generates all the valid solutions for the problem in the specified range [from, to)
fun combinations(from: Int, to: Int): List<List<Int>> {
    if (from > to)
        return emptyList() //Return nothing if limits are invalid
 
    val pool = IntStream.range(from, to).boxed().collect(Collectors.toList()) //Here we'll save our values
 
    val solutions = ArrayList<List<Int>>() //List for the solutions
 
    //Brute-force calculation of valid values...
    for (a in pool)
        for (b in pool)
            for (c in pool)
                for (d in pool)
                    for (e in pool)
                        for (f in pool)
                            for (g in pool)
                                if (a == c + d && b + c == e + f && d + e == g)
                                    solutions.add(Arrays.asList(a, b, c, d, e, f, g))
    return solutions
}
 
//Filter the list generated from "combinations" and return only lists with no repetitions
fun filterUnique(from: Int, to: Int): List<List<Int>> {
    //Helper lambda to check repetitions:
    //If the count is > 1 for an element, there must be a repetition inside the range
    val hasNonUniqueValues = { range: List<Int>, target: Int ->
        Collections.frequency(range, target) > 1
    }
 
    //Generates all the solutions...
    val results = combinations(from, to)
 
    //For each solution, find duplicates inside
    for (subrange in results) {
        var repetition = false
 
        //If some element is repeated, repetition becomes true
        for (x in subrange)
            repetition = repetition or hasNonUniqueValues(subrange, x)
 
        if (repetition) //If repetition is true, remove the current subrange from the list
            results.remove(subrange)
    }
 
    return results //Finally return remaining results
};1

fun move(round: Int, elves: Set<Pair<Int, Int>>): Set<Pair<Int, Int>> {
    val elvesDestinations = elves.toMutableSet()
    val considerationOrder = considerationOrders[round % 4]

    val destinationCount = mutableMapOf<Pair<Int, Int>, Int>()
    val proposedMoves = mutableMapOf<Pair<Int, Int>, Pair<Int, Int>>()
    // first half
    for (elf in elves) {
        if (eightNeighbour(elf).any { elves.contains(it) }) {
            considerationOrder.firstOrNull() { consideration ->
                directionNeighbour(elf, consideration).all { !elves.contains(it) }
            }?.let { offset ->
                val moveDirection = offset[1]
                val proposedDestination = Pair(elf.first + moveDirection.first, elf.second + moveDirection.second)
                destinationCount[proposedDestination] = destinationCount.getOrDefault(proposedDestination, 0) + 1
                proposedMoves[elf] = proposedDestination
            }
        }
        // otherwise no elves around, don't move
    }

    for ((elf, destination) in proposedMoves) {
        if (destinationCount[destination] == 1) {
            elvesDestinations.remove(elf)
            elvesDestinations.add(destination)
        }
    }

    return elvesDestinations
};0

class Graph(private val graph: Map<String, List<String>>, private val sourceVertex: String) {
    private val parent = mutableMapOf<String, String?>()

    fun breathFirstSearch() {
        val visited = mutableSetOf(sourceVertex)
        parent[sourceVertex] = null
        val queue: ArrayDeque<String> = ArrayDeque()
        queue.add(sourceVertex)

        while (queue.isNotEmpty()) {
            val vertex = queue.removeFirst()
            for (adjacentVertex in graph[vertex] ?: emptyList()) {
                if (adjacentVertex !in visited) {
                    visited.add(adjacentVertex)
                    parent[adjacentVertex] = vertex
                    queue.add(adjacentVertex)
                }
            }
        }
    }

    fun shortestPath(targetVertex: String): String {
        if (targetVertex == sourceVertex) {
            return sourceVertex
        }
        val targetVertexParent = parent[targetVertex]
        if (targetVertexParent == null) {
            val msg = "No path from vertex: $sourceVertex to vertex: $targetVertex"
            throw IllegalArgumentException(msg)
        }
        return shortestPath(targetVertexParent) + "->" + targetVertex
    }
};1

