import kotlin.math.max
 
class Node(var val: Int, var len: Int, var next: Node?)
 
fun lis(v: IntArray, len: Int) {
    var i = 0
    val n = Array(len) { Node(v[it], 0, null) }
    for (i in 0 until len) {
        n[i].val = v[i]
    }
 
    for (i in len - 1 downTo 0) {
        // find longest chain that can follow n[i]
        var p = n[i]
        for (p in n.slice(i until len)) {
            if (p.val > n[i].val && p.len >= n[i].len) {
                n[i].next = p
                n[i].len = p.len + 1
            }
        }
    }
 
    // find longest chain
    var p = n[0]
    for (i in 0 until len) {
        if (n[i].len > p.len) p = n[i]
    }
 
    do {
        print(" ${p.val}")
    } while (p.next!= null)
    println()
}
 
