fun extractMp2Energy(outputStr: String): Double? {
    // Regex:
    // (?:Total\s+MP2\s+energy|MP2\s+energy) -> either phrase variant
    // \s*[:=]?\s*                           -> optional whitespace and separator
    // (-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)  -> signed float with optional exponent
    val pattern = Pattern.compile(
        "(?:Total\\s+MP2\\s+energy|MP2\\s+energy)\\s*[:=]?\\s*" +
        "(-?\\d+(?:\\.\\d+)?(?:[eE][+-]?\\d+)?)"
    )
    val matcher = pattern.matcher(outputStr)
    if (matcher.find()) {
        return try {
            matcher.group(1)?.toDouble()
        } catch (e: NumberFormatException) {
            null
        }
    }
    return null
};1

