fun makeValley(arr: IntArray): IntArray {
    val sarr = arr.sortedArrayDescending()
    val n = sarr.size
    val half = n / 2 + (n % 2)
    val last = n - if (n % 2 == 0) 1 else 0
    return (0 until n)
            .map { i -> if (i < half) sarr[i * 2] else sarr[last - ((i - n / 2) * 2)] }
            .toList().toIntArray()
};0

