fun getInstanceNameToIdMap(instanceInfo: Map<String, Map<String, Any>>): Map<String, String> {
    val nameToId = mutableMapOf<String, String>()
    var unnamedCounter = 0

    for ((instanceId, details) in instanceInfo) {
        var name: String? = null

        // Try to get tags from 'Tags' or 'tags' (case-sensitive)
        val tagsCollection = details["Tags"] ?: details["tags"]
        if (tagsCollection != null) {
            when (tagsCollection) {
                is List<*> -> {
                    // List of dicts: [{'Key':'Name','Value':'foo'}, ...]
                    for (tag in tagsCollection) {
                        if (tag is Map<*, *>) {
                            val keyField = (tag["Key"] ?: tag["key"]) as? String
                            if (keyField == "Name") {
                                name = (tag["Value"] ?: tag["value"]) as? String
                                break
                            }
                        }
                    }
                }
                is Map<*, *> -> {
                    // Map: {"Name":"foo", ...}
                    name = tagsCollection["Name"] as? String
                }
            }
        }

        if (name.isNullOrEmpty()) {
            name = "unnamed${unnamedCounter}"
            unnamedCounter++
        }

        nameToId[name] = instanceId
    }

    return nameToId
};1

fun extractProjectInfo(req: String): Map<String, String?> {
    var projectName: String? = null
    var firstName: String? = null
    var lastName: String? = null
    var email: String? = null

    req.lines().forEach { lineRaw ->
        val line = lineRaw.trim()
        if (line.isEmpty()) return@forEach
        if (!line.contains(":")) return@forEach
        val (keyRaw, valueRaw) = line.split(":", limit = 2)
        val key = keyRaw.trim().lowercase()
        val value = valueRaw.trim()
        when (key) {
            "name" -> projectName = value
            "owner" -> {
                val parts = value.split(" ").filter { it.isNotEmpty() }
                if (parts.isNotEmpty()) {
                    firstName = parts[0]
                    lastName = if (parts.size > 1) parts.last() else ""
                }
            }
            "email" -> email = value
        }
    }

    var ownerType = "external"
    if (email != null) {
        val domain = email.substringAfter("@", "").lowercase()
        if ("example.edu" in domain) {
            ownerType = "internal"
        }
    }

    return mapOf(
        "project_name" to projectName,
        "first_name" to firstName,
        "last_name" to lastName,
        "owner_type" to ownerType
    )
};1

fun digitalRootBase(x: Int, b: Int): Pair<Int, Int> {
    if (x < b)
        return Pair(0, x)
    var fauxroot = 0
    while (b <= x) {
        x = x / b
        fauxroot += x % b
    }
    val rootobj = digitalRootBase(fauxroot, b)
    rootobj.first += 1
    return rootobj
};1

