import kotlin.math.pow
 
fun f(x: Double): Double {
    return (x.pow(3.0) - 3 * x.pow(2.0) + 2 * x)
}
 
fun main() {
    val step = 0.001 // Smaller step values produce more accurate and precise results
    val start = -1.0
    val stop = 3.0
    var value = f(start)
    var sign = (value > 0)
 
    // Check for root at start
    if (0 == value) {
        println("Root found at $start")
    }
 
    for (x in start + step..stop step step) {
        value = f(x)
 
        if ((value > 0)!= sign) {
            // We passed a root
            println("Root found near $x")
        } else if (0 == value) {
            // We hit a root
            println("Root found at $x")
        }
 
        // Update our sign
        sign = (value > 0)
    }
};1

