fun getEventKeywords(dictEventWindows: Map<String, List<String>>, n: Int): Map<String, List<List<String>>> {
    val useAllWords = n <= 0
    val result = mutableMapOf<String, List<List<String>>>()

    for ((freqThresh, windows) in dictEventWindows) {
        val processedWindows = mutableListOf<List<String>>()
        for (window in windows) {
            if (window.trim().isEmpty()) {
                processedWindows.add(emptyList())
                continue
            }
            val words = window.trim().split(Regex("\\s+")).filter { it.isNotEmpty() }
            val keywords = if (useAllWords) words else words.take(n)
            processedWindows.add(keywords)
        }
        result[freqThresh] = processedWindows
    }
    return result
};1

