import java.util.HashMap
import java.util.HashSet
import java.util.LinkedList
import java.util.Queue
import java.util.Stack
 
typealias Vertex = Int
 
interface Graph {
  fun vertices(): List<Vertex>
  fun neighbors(v: Vertex): List<Vertex>
  fun weight(u: Vertex, v: Vertex): Int
}
 
class ig(val vert: List<Vertex>, val edges: HashMap<Vertex, HashMap<Vertex, Int>>) : Graph {
  fun edge(u: Vertex, v: Vertex, w: Int) {
    if (!edges.containsKey(u)) {
      edges[u] = HashMap()
    }
    edges[u]!![v] = w
  }
  fun vertices(): List<Vertex> = vert
  fun neighbors(v: Vertex): List<Vertex> = edges[v]!!.keys.toList()
  fun weight(u: Vertex, v: Vertex): Int = edges[u]!![v]!!
}
 
fun ig.path(vv: List<Vertex>): String {
  if (vv.isEmpty()) {
    return ""
  }
  var s = vv[0].toString()
  for (v in vv.subList(1, vv.size)) {
    s += " -> " + v
  }
  return s
}
 
val Infinity = Int.MAX_VALUE
 
fun floydWarshall(g: Graph): Pair<HashMap<Vertex, HashMap<Vertex, Int>>, HashMap<Vertex, HashMap<Vertex, Vertex?>>> {
  val vert = g.vertices()
  val dist = HashMap<Vertex, HashMap<Vertex, Int>>()
  val next = HashMap<Vertex, HashMap<Vertex, Vertex?>>()
  for (u in vert) {
    dist[u] = HashMap()
    next[u] = HashMap()
    for (v in vert) {
      dist[u]!![v] = Infinity
    }
    dist[u]!![u] = 0
    for (v in g.neighbors(u)) {
      dist[u]!![v] = g.weight(u, v)
      next[u]!![v] = v
    }
  }
  for (k in vert) {
    for (i in vert) {
      for (j in vert) {
        if (dist[i]!![k]!! < Infinity && dist[k]!![j]!! < Infinity) {
          if (dist[i]!![j]!! > dist[i]!![k]!! + dist[k]!![j]!!) {
            dist[i]!![j] = dist[i]!![k]!! + dist[k]!![j]!!
            next[i]!![j] = next[i]!![k]
          }
        }
      }
    }
  }
  return Pair(dist, next)
}
 
fun path(u: Vertex, v: Vertex, next: HashMap<Vertex, HashMap<Vertex, Vertex?>>): List<Vertex> {
  if (next[u]!![v] == null) {
    return emptyList()
  }
  val path = LinkedList<Vertex>()
  path.add(u)
  var u = u
  while (u!= v) {
    u = next[u]!![v]!!
    path.add(u)
  }
  return path
}
 
fun main(args: Array<String>) {
  val g = ig(listOf(1, 2, 3, 4), HashMap())
  g.edge(1, 3, -2)
  g.edge(3, 4, 2)
  g.edge(4, 2, -1)
  g.edge(2, 1, 4)
  g.edge(2, 3, 3)
 
  val (dist, next) = floydWarshall(g)
  println("pair\tdist\tpath")
  for (u in dist.keys) {
    for (v in dist[u]!!.keys) {
      if (u!= v) {
        println("$u -> $v\t${dist[u]!![v]}\t${g.path(path(u, v, next))}")
      }
    }
  }
};1

