import kotlin.math.min
 
data class Deck(val v: IntArray)
 
val n = 12
val d = 0
val best = IntArray(16)
 
fun tryswaps(a: Deck, f: Int, s: Int) {
#   define A a.v
#   define B b.v
    if (d > best[n]) best[n] = d
    while (true) {
        if ((A[s] == s || (A[s] == -1 && (f and (1 shl s))!= 0))
            && (d + best[s] >= best[n] || A[s] == -1))
            break;
 
        if (d + best[s] <= best[n]) return
        if (s == 0) return
    }
 
    d++
    val b = Deck(a.v.copyOf())
    for (i in 1..s) {
        val k = 1 shl i
        if (A[i]!= i && (A[i]!= -1 || (f and k)!= 0))
            continue;
 
        for (j in 0 until i) B[i - j] = A[j]
        tryswaps(b, f or k, s)
    }
    d--
}
 
fun main() {
    val x = Deck(IntArray(16) { -1 })
    x.v[0] = 0
 
    for (n in 1 until 13) {
        tryswaps(x, 1, n - 1)
        println("%2d: %d".format(n, best[n]))
    }
};1

