fun determineWinner(nominees: List<String>, votes: List<Int>): String {
    if (nominees.size != votes.size) {
        return "Invalid input"
    }
    val maxVotes = votes.maxOrNull() ?: return "Invalid input"
    val candidates = nominees.withIndex()
        .filter { it.index < votes.size && votes[it.index] == maxVotes }
        .map { it.value }
    return candidates.minOrNull() ?: "Invalid input"
};1

