fun calculateEvaluationMetrics(predictedLabels: List<Int>, targetLabels: List<Int>): Map<String, Double> {
    if (predictedLabels.size != targetLabels.size) {
        throw IllegalArgumentException("predictedLabels and targetLabels must be of the same length.")
    }
    if (predictedLabels.isEmpty()) {
        return mapOf(
            "accuracy" to 0.0,
            "precision" to 0.0,
            "recall" to 0.0,
            "f1_score" to 0.0
        )
    }

    var tp = 0
    var fp = 0
    var tn = 0
    var fn = 0

    for ((pred, trueLabel) in predictedLabels.zip(targetLabels)) {
        when {
            pred == 1 && trueLabel == 1 -> tp++
            pred == 1 && trueLabel == 0 -> fp++
            pred == 0 && trueLabel == 0 -> tn++
            pred == 0 && trueLabel == 1 -> fn++
            else -> throw IllegalArgumentException("Labels must be 0 or 1.")
        }
    }

    val total = tp + fp + tn + fn
    val accuracy = if (total != 0) (tp + tn).toDouble() / total else 0.0
    val precision = if (tp + fp != 0) tp.toDouble() / (tp + fp) else 0.0
    val recall = if (tp + fn != 0) tp.toDouble() / (tp + fn) else 0.0
    val f1Score = if (precision != 0.0 && recall != 0.0) 2 * precision * recall / (precision + recall) else 0.0

    return mapOf(
        "accuracy" to accuracy,
        "precision" to precision,
        "recall" to recall,
        "f1_score" to f1Score
    )
};1

fun parse(value: String): Packet {
    if (value.firstOrNull()?.isDigit() == true) return PacketValue(value.toInt())
    return PacketList(
        packets = buildList {
            var openBrackets = 0
            var lastComma = 0
            value.forEachIndexed { idx, c ->
                when {
                    c == '[' -> openBrackets++
                    c == ']' -> if (--openBrackets == 0) add(parse(value.substring(lastComma + 1 until idx)))
                    c == ',' && openBrackets == 1 -> add(parse(value.substring(lastComma + 1 until idx))).also { lastComma = idx }
                }
            }
        }
    )
};0

