class HilbertCurve(var currentX: Double, var currentY: Double, var currentAngle: Int, var lineLength: Double) {
    fun rewrite(order: Int): String {
        var str = "A"
        for (i in 0 until order) {
            val tmp = StringBuilder()
            for (ch in str) {
                when (ch) {
                    'A' -> tmp.append("-BF+AFA+FB-")
                    'B' -> tmp.append("+AF-BFB-FA+")
                    else -> tmp.append(ch)
                }
            }
            str = tmp.toString()
        }
        return str
    }
    fun execute(order: Int): String {
        var data = "M $currentX $currentY "
        for (ch in rewrite(order)) {
            when (ch) {
                'F' -> data = drawLine(data)
                '+' -> turn(90)
                '-' -> turn(-90)
                else -> {}
            }
        }
        return data
    }
    fun drawLine(data: String): String {
        val theta = toRadians(currentAngle.toDouble())
        currentX += lineLength * cos(theta)
        currentY -= lineLength * sin(theta)
        return data + "L $currentX $currentY "
    }
    fun turn(angle: Int) {
        currentAngle = (currentAngle + angle) % 360
    }
    companion object {
        @Throws(IOException::class)
        fun save(file: String, size: Int, order: Int) {
            val x = 10.0
            val y = 10.0
            val rect = "rect(0,0,$size,$size)"
            val hilbert = HilbertCurve(x, y, 0, 10.0)
            val document = """
                <svg width="$size" height="$size" xmlns="http://www.w3.org/2000/svg">
                    <rect width="100%" height="100%" fill="white"/>
                    <path fill="none" stroke="black" stroke-width="1" d="${hilbert.execute(order)}"/>
                </svg>
            """.trimIndent()
            Files.write(Paths.get(file), document.toByteArray(StandardCharsets.UTF_8), StandardOpenOption.CREATE)
        }
    }
}
 
