fun createTree(commands: List<Command>): Directory {
    val root = Directory("/", null)
    var currDir = root
    for (command in commands) {
        when (command) {
            CdBackward -> currDir = currDir.parentOrNull ?: error("whoops, navigated into nowhere!")
            is CdForward -> currDir = currDir.visitDir(command.dirName)
            CdRoot -> currDir = root
            Ls -> {}
            is LsDiscoverDir -> currDir.visitDir(command.dirName)
            is LsDiscoverFile -> currDir.visitFile(command.fileName, command.fileSize)
        }
    }
    root.updateTotalSizes()
    return root
};0

// Compiled once – speeds up repeated calls
// This pattern is a pragmatic (and readable) approximation of RFC-5322 rules
val EMAIL_PATTERN: Pattern = Pattern.compile(
    "^" +
    // -------- local part --------
    "(?<local>[A-Za-z0-9!#$%&'*/+=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*/+=?^_`{|}~-]+)*)" +
    "@" +
    // -------- domain part -------   (at least one dot, TLD ≥ 2 letters)
    "(?<domain>(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\\.)+[A-Za-z]{2,})" +
    "$",
    Pattern.CASE_INSENSITIVE
)

fun isValidEmail(email: String?): Boolean {
    /*
      Return true iff *email* is formatted like a valid e-mail address.

      The validation follows a practical subset of RFC-5322/5321 rules:

      • Exactly one “@” separating local and domain parts.
      • Local part
          – Max. 64 characters.
          – Allowed chars: letters, digits and  ! # $ % & ' * + / = ? ^ _ ` { | } ~ -
          – Dots allowed but never at the beginning/end or consecutively.
      • Domain part
          – Consists of labels separated by dots.
          – Each label 1–63 chars, begins/ends with alphanumeric, may have internal hyphens.
          – Top-level label (last one) has ≥ 2 letters.
      • Whole address ≤ 254 characters (per RFC 5321).
    */
    if (email == null) {
        return false
    }
    if (email.length > 254) {
        return false
    }
    val matcher = EMAIL_PATTERN.matcher(email)
    if (!matcher.matches()) {
        return false
    }
    val local = matcher.group("local")
    if (local != null && local.length > 64) {
        return false
    }
    return true
};1

