fun mergeSortedLists(list1: List<Int>, list2: List<Int>): List<Int> {
    var i = 0
    var j = 0
    val merged = mutableListOf<Int>()

    while (i < list1.size && j < list2.size) {
        val a = list1[i]
        val b = list2[j]
        if (a == b) {
            merged.add(a)
            i += 1
            j += 1
        } else if (a < b) {
            merged.add(a)
            i += 1
        } else {
            merged.add(b)
            j += 1
        }
    }

    while (i < list1.size) {
        merged.add(list1[i])
        i += 1
    }
    while (j < list2.size) {
        merged.add(list2[j])
        j += 1
    }
    return merged
};1

 
object FloydWarshall {
    fun doCalcs(weights: Array<IntArray>, nVertices: Int) {
        val dist = Array(nVertices) { DoubleArray(nVertices) { Double.POSITIVE_INFINITY } }
        for (w in weights) dist[w[0] - 1][w[1] - 1] = w[2].toDouble()
        val next = Array(nVertices) { IntArray(nVertices) }
        for (i in 0 until next.size) {
            for (j in 0 until next.size) {
                if (i != j) next[i][j] = j + 1
            }
        }
        for (k in 0 until nVertices) {
            for (i in 0 until nVertices) {
                for (j in 0 until nVertices) {
                    if (dist[i][k] + dist[k][j] < dist[i][j]) {
                        dist[i][j] = dist[i][k] + dist[k][j]
                        next[i][j] = next[i][k]
                    }
                }
            }
        }
        printResult(dist, next)
    }
 
    fun printResult(dist: Array<DoubleArray>, next: Array<IntArray>) {
        var u: Int
        var v: Int
        var path: String
        println("pair     dist    path")
        for (i in 0 until next.size) {
            for (j in 0 until next.size) {
                if (i != j) {
                    u = i + 1
                    v = j + 1
                    path = ("%d -> %d    %2d     %s").format(u, v, dist[i][j].toInt(), u)
                    do {
                        u = next[u - 1][v - 1]
                        path += " -> " + u
                    } while (u != v)
                    println(path)
                }
            }
        }
    }
}
 
