fun List<String>.toMonkey(): Monkey {
    val startItems = this[1].substringAfter(": ").split(", ").map { it.toLong() }.toMutableList()
    val operationValue = this[2].substringAfterLast(" ")
    val testParameter = this[3].substringAfterLast(" ").toLong()
    val trueMonkey = this[4].substringAfterLast(" ").toInt()
    val falseMonkey = this[5].substringAfterLast(" ").toInt()

    return Monkey(
        items = startItems,
        operation = when {
            operationValue == "old" -> ({ it * it })
            '*' in this[2] -> ({ it * operationValue.toLong() })
            else -> ({ it + operationValue.toLong() })
        },
        test = { i -> (i % testParameter).toInt() == 0 },
        trueMonkey = trueMonkey,
        falseMonkey = falseMonkey
    )
};0

fun setPingOffset(inputStr: String): String {
    val cmdPrefix = "/set_offset "
    if (!inputStr.startsWith(cmdPrefix)) {
        return "Invalid input"
    }
    val numberPart = inputStr.substring(cmdPrefix.length).trim()
    // Reject empty remainder
    if (numberPart == "") {
        return "Invalid input"
    }
    // Attempt to parse the integer safely
    val offsetValue = numberPart.toIntOrNull() ?: return "Invalid input"
    // Check if numberPart contains anything other than valid integer characters
    if (numberPart != offsetValue.toString()) {
        return "Invalid input"
    }
    return "Offset set to $offsetValue"
};1

fun Array<Array<Int>>.getMoves(
    source: Pair<Pair<Int, Int>, CardinalDirection>,
    directions: Set<CardinalDirection>,
    allowedDistance: IntRange
): List<Move> {
    val moves = mutableListOf<Move>()
    directions.forEach {
        var i = 1
        var current = source.first.adjacent(it)
        var cost = 0L
        while (i <= allowedDistance.last && isValidCoord(current)) {
            cost += this[current.first][current.second]
            if (i in allowedDistance) {
                moves.add(Move(current, it, cost))
            }
            current = current.adjacent(it)
            i++
        }
    }
    return moves
