import kotlin.math.abs
import kotlin.math.floor
import kotlin.math.min
 
class SubtractiveGenerator(
    /// m in the formula
    val modulo: Int,
    /// i and j in the formula
    val offsets: Pair<Int, Int>,
    /// r in the formula. It is used as a ring buffer.
    val state: MutableList<Int>,
    /// n in the formula
    var position: Int
) {
    fun next(): Int {
        val stateSize = offsets.first
 
        assert(state.size == stateSize)
 
        position = (position + 1) % offsets.first
 
        val i1 = (position - offsets.first).rem(stateSize)
        val i2 = (position - offsets.second).rem(stateSize)
 
        val p1 = state[i1]
        val p2 = state[i2]
 
        state[position] = (p1 - p2).rem(modulo)
 
        return state[position]
    }
}
 
/// Returns a pre-seeded subtractive generator, which generates the same
/// sequences as Bentley's generator, as used in xpat2.
fun getSeededXpat2Gen(seed: Int): SubtractiveGenerator {
    val gen = SubtractiveGenerator(1_000_000_000, 55 to 24, mutableListOf(), 0)
 
    val stateSize = gen.offsets.first
 
    val preState = mutableListOf(seed, 1)
    for (i in 2 until stateSize) {
        preState.add((preState[i - 2] - preState[i - 1]).rem(gen.modulo))
    }
 
    for (i in 0 until stateSize) {
        gen.state.add(preState[(34 * (i + 1)) % 55])
    }
 
    gen.position = 54
    for (i in 0 until 165) {
        gen.next()
    }
 
    return gen
}
 
