fun solve(): Int {
    val (n, hei) = readInts()
    data class Ladder(val id: Int, val x: Int, val yFrom: Int, val yTo: Int)
    val ladders = List(n) { val (x, yFrom, yTo) = readInts(); Ladder(it, x, yFrom, yTo) }

    val e = Array(n + 2) { IntArray(n + 2) }
    val ys = ladders.flatMap { listOf(it.yFrom, it.yTo) }.toSet().sorted()
    for ((y, yNext) in ys.zipWithNext()) {
        val idsOrdered = ladders.filter { (it.yFrom <= y) && (y < it.yTo) }.sortedBy { it.x }.map { it.id }
        for ((i, j) in idsOrdered.zipWithNext()) {
            e[i][j] += yNext - y
            e[j][i] += yNext - y
        }
    }
    val inf = n * hei
    ladders.forEach {
        if (it.yFrom == 0) { e[n][it.id] = inf }
        if (it.yTo == hei) { e[it.id][n + 1] = inf }
    }
    return edmonsKarp(e, n, n + 1).takeIf { it < inf } ?: -1
};0

fun findMedianSortedArrays(nums1: IntArray, nums2: IntArray): Double {
    // Ensure nums1 is the smaller array to keep binary search minimal
    var a = nums1
    var b = nums2
    if (a.size > b.size) {
        val temp = a
        a = b
        b = temp
    }
    val m = a.size
    val n = b.size
    if (m == 0 && n == 0) {
        throw IllegalArgumentException("Both input arrays are empty.")
    }
    var left = 0
    var right = m
    while(true) {
        val i = (left + right) / 2
        val j = (m + n + 1) / 2 - i

        val maxLeftX = if (i == 0) Double.NEGATIVE_INFINITY else a[i - 1].toDouble()
        val minRightX = if (i == m) Double.POSITIVE_INFINITY else a[i].toDouble()

        val maxLeftY = if (j == 0) Double.NEGATIVE_INFINITY else b[j - 1].toDouble()
        val minRightY = if (j == n) Double.POSITIVE_INFINITY else b[j].toDouble()

        if (maxLeftX <= minRightY && maxLeftY <= minRightX) {
            return if ((m + n) % 2 == 0) {
                (maxOf(maxLeftX, maxLeftY) + minOf(minRightX, minRightY)) / 2.0
            } else {
                maxOf(maxLeftX, maxLeftY)
            }
        } else if (maxLeftX > minRightY) {
            right = i - 1
        } else {
            left = i + 1
        }
    }
};1

fun gcd(m: Int, n: Int): Int {
    // Compute the greatest common divisor (GCD) of two integers
    // using the Euclidean algorithm.
    var a = kotlin.math.abs(m)
    var b = kotlin.math.abs(n)
    while (b != 0) {
        val temp = b
        b = a % b
        a = temp
    }
    return a
};1

