    val predDigit = pred(tmp, pos)
    tmp.forEach {
        if (it[pos] == predDigit.char) {
            filtered.add(it)
        }
    }
    return if (filtered.size > 1) {
        filter(filtered, pos + 1, pred)
    } else {
        filtered[0]
    }
