            Arrays.asList(3.0, 2.0, 2.0, -6.0),
            Arrays.asList(1.0, 3.0, 3.0, -1.0),
            Arrays.asList(5.0, -2.0, -3.0, 3.0))
    val b = Arrays.asList(-3.0, -32.0, -47.0, 49.0)
    println("Solution = " + cramersRule(mat, b))
