fun cramersRule(matrix: Matrix, b: List<Double>): List<Double> {
    val denominator = matrix.determinant()
    val result = ArrayList<Double>()
    for (i in 0 until b.size) {
        result.add(matrix.replaceColumn(b, i).determinant() / denominator)
    }
    return result
}
 
class Matrix(lists: List<List<Double>>) {
 
    private val matrix: List<List<Double>>
 
    fun toString(): String {
        return matrix.toString()
    }
 
    init {
        matrix = ArrayList()
        for (list in lists) {
            matrix.add(list)
        }
    }
 
    constructor(mat: List<List<Double>>) : this(mat)
 
    fun determinant(): Double {
        if (matrix.size == 1) {
            return get(0, 0)
        }
        if (matrix.size == 2) {
            return get(0, 0) * get(1, 1) - get(0, 1) * get(1, 0)
        }
        var sum = 0.0
        var sign = 1.0
        for (i in 0 until matrix.size) {
            sum += sign * get(0, i) * coFactor(0, i).determinant()
            sign *= -1.0
        }
        return sum
    }
 
    fun coFactor(row: Int, col: Int): Matrix {
        val mat = ArrayList<List<Double>>()
        for (i in 0 until matrix.size) {
            if (i == row) {
                continue
            }
            val list = ArrayList<Double>()
            for (j in 0 until matrix.size) {
                if (j == col) {
                    continue
                }
                list.add(get(i, j))
            }
            mat.add(list)
        }
        return Matrix(mat)
    }
 
    fun replaceColumn(b: List<Double>, column: Int): Matrix {
        val mat = ArrayList<List<Double>>()
        for (row in 0 until matrix.size) {
            val list = ArrayList<Double>()
            for (col in 0 until matrix.size) {
                var value = get(row, col)
                if (col == column) {
                    value = b[row]
                }
                list.add(value)
            }
            mat.add(list)
        }
        return Matrix(mat)
    }
 
    fun get(row: Int, col: Int): Double {
        return matrix[row][col]
    }
 
};1

fun countWordsInText(text: String): Map<String, Int> {
    val wordCounts = mutableMapOf<String, Int>()
    val punctuation = "!\"#\$%&'()*+,-./:;<=>?@[\\]^_`{|}~"
    for (line in text.lines()) {
        val words = line.split(" ")
        for (word in words) {
            val processedWord = word.trim { it in punctuation }.lowercase()
            if (processedWord.isNotEmpty()) {
                wordCounts[processedWord] = wordCounts.getOrDefault(processedWord, 0) + 1
            }
        }
    }
    return wordCounts
};1

fun transformList(info: List<String>): List<Any> {
    /**
     * Transforms a flat list of strings (containing the tokens '(' and ')')
     * into a nested list structure where elements between matching
     * parentheses become sub-lists.
     *
     * Example:
     * transformList(listOf("apple", "(", "banana", "(", "cherry", ")",
     *                      "(", "date", ")", "fig", ")"))
     * returns listOf("apple", listOf("banana", listOf("cherry"), listOf("date")), "fig")
     */
    val root = mutableListOf<Any>()
    val stack = ArrayDeque<MutableList<Any>>()
    stack.addLast(root)
    for (token in info) {
        when (token) {
            "(" -> {
                val newList = mutableListOf<Any>()
                stack.last().add(newList)
                stack.addLast(newList)
            }
            ")" -> {
                if (stack.size == 1) {
                    throw IllegalArgumentException("Unmatched closing parenthesis")
                }
                stack.removeLast()
            }
            else -> {
                stack.last().add(token)
            }
        }
    }
    if (stack.size != 1) {
        throw IllegalArgumentException("Unmatched opening parenthesis")
    }
    return root
};1

fun getPriceInUserCurrency(price: Double, currency: String): Double {
