// A doubly linked list of strings;
 
import java.util.Iterator;
 
class ListEntry(var value: String?, var next: ListEntry?, var prev: ListEntry?)
 
class LinkedList(var next: ListEntry?, var prev: ListEntry?)
 
fun NewList(): LinkedList {
    val le = ListEntry(null, null, null)
    return LinkedList(le, le)
}
 
fun LL_Append(ll: LinkedList, newVal: String): Boolean {
    val le = ListEntry(newVal, null, null)
    if (ll.prev!= null) {
        le.prev = ll.prev
        le.prev!!.next = le
    } else {
        ll.next = le
    }
    ll.prev = le
    return true
}
 
fun LI_Insert(iter: LIterator, newVal: String): Boolean {
    val crnt = iter.link
    val le = ListEntry(newVal, null, null)
    if (crnt == iter.head) {
        le.prev = null
        le.next = crnt!!.next
        crnt.next = le
        if (le.next!= null) {
            le.next!!.prev = le
        } else {
            crnt.prev = le
        }
    } else {
        le.prev = if (crnt == null) iter.head!!.prev else crnt.prev
        le.next = crnt
        if (le.prev!= null) {
            le.prev!!.next = le
        } else {
            iter.head!!.next = le
        }
        if (crnt!= null) {
            crnt.prev = le
        } else {
            iter.head!!.prev = le
        }
    }
    return true
}
 
class LIterator(var head: LinkedList, var link: ListEntry?)
 
fun LL_GetIterator(ll: LinkedList): LIterator {
    return LIterator(ll, ll)
}
 
fun LLI_Delete(iter: LIterator) {
    iter.head = null
    iter.link = null
}
 
fun LLI_AtEnd(iter: LIterator): Boolean {
    return iter.link == null
}
 
fun LLI_Value(iter: LIterator): String? {
    return if (iter.link!= null) iter.link!!.value else null
}
 
fun LLI_Next(iter: LIterator): Boolean {
    if (iter.link!= null) iter.link = iter.link!!.next
    return iter.link!= null
}
 
fun LLI_Prev(iter: LIterator): Boolean {
    if (iter.link!= null) iter.link = iter.link!!.prev
    return iter.link!= null
}
 
fun main() {
    val contents = arrayOf("Read", "Orage", "Yeller", "Glean", "Blew", "Burple")
    val ll = NewList() //new linked list
    val iter: LIterator
    for (ix in contents.indices) { //insert contents
        LL_Append(ll, contents[ix])
    }
    iter = LL_GetIterator(ll) //get an iterator
    println("forward")
    while (LLI_Next(iter)) { //iterate forward
        println("value=${LLI_Value(iter)}")
    }
    LLI_Delete(iter) //delete iterator
    println("\nreverse")
    iter = LL_GetIterator(ll)
    while (LLI_Prev(iter)) { //iterate reverse
        println("value=${LLI_Value(iter)}")
    }
    LLI_Delete(iter)
};1

