fun game(level: String, cards: Int, sets: Int) {
    // create deck
    val d = IntArray(81) { it }
    val found = mutableListOf<IntArray>()
    while (found.size!= sets) {
        found.clear()
        // deal
        d.shuffle()
        //  consider all triplets
        for (i in 2 until cards) {
            val c1 = d[i]
            for (j in 1 until i) {
                val c2 = d[j]
                for (k in 0 until j) {
                    val c3 = d[k]
                    if (isASet(c1, c2, c3)) {
                        found.add(intArrayOf(c1, c2, c3))
                    }
                }
            }
        }
    }
    // found the right number
    println("$level game.  $cards cards, $sets sets.")
    println("Cards:")
    for (i in 0 until cards) {
        println("  ${d[i]}")
    }
    println("Sets:")
    for (s in found) {
        println("  ${s[0]}")
        println("  ${s[1]}")
        println("  ${s[2]}")
    }
}
 
fun isASet(c1: Int, c2: Int, c3: Int): Boolean {
    for (f in 1..80 step 3) {
        if ((c1 / f % 3 + c2 / f % 3 + c3 / f % 3) % 3!= 0) {
            return false // not a set
        }
    }
    return true
};1

