import java.time.DayOfWeek
import java.time.LocalDate
import java.time.Month
import java.time.temporal.ChronoUnit
import java.time.temporal.TemporalAdjusters
import kotlin.math.floor
 
fun getEasterDay(year: Int): LocalDate {
    val k = floor(year / 100.0)
    val d = (19 * (year % 19) + ((15 - ((13.0 + 8.0 * k) / 25.0).toInt() + k.toInt() - (k / 4.0).toInt()) % 30)) % 30
    val e = (2 * (year % 4) + 4 * (year % 7) + 6 * d + ((4 + k.toInt() - (k / 4.0).toInt()) % 7)) % 7
 
    val month = when {
        d + e < 10 -> Month.MARCH
        d == 29 && e == 6 -> Month.APRIL
        d == 28 && e == 6 -> Month.APRIL
        else -> Month.APRIL
    }
    val day = when {
        d + e < 10 -> 22 + d + e
        d == 29 && e == 6 -> 19
        d == 28 && e == 6 -> 18
        else -> d + e - 9
    }
 
    return LocalDate.of(year, month, day)
}
 
