fun String.toOperation(): (Long) -> Long =
  if (this == "old * old") {
    { x: Long -> x * x }
  } else if (this.startsWith("old * ")) {
    { x: Long -> x * this.drop(6).toLong() }
  } else if (this.startsWith("old + ")) {
    { x: Long -> x + this.drop(6).toLong() }
  } else {
    throw IllegalArgumentException(this)
  };0

