fun lastFridaysOfYear(year: Int): List<Calendar> {
    val result = mutableListOf<Calendar>()
    for (month in 1..12) {
        val date = GregorianCalendar(year, month, 1).apply {
            add(Calendar.MONTH, 1)
            add(Calendar.DAY_OF_MONTH, -1)
        }
        while (date.get(Calendar.DAY_OF_WEEK)!= Calendar.FRIDAY) {
            date.add(Calendar.DAY_OF_MONTH, -1)
        }
        result.add(date)
    }
    return result
}
 
