fun intersperse(numbers: List<Int>, delimeter: Int): List<Int> {
    // Empty or single-element lists need no interspersion
    if (numbers.size <= 1) {
        return numbers.toList() // return a shallow copy
    }
    val result = mutableListOf<Int>()
    val skipInterval = if (delimeter < 0) Math.abs(delimeter) else null
    for (idx in numbers.indices) {
        result.add(numbers[idx])
        // No delimiter after the last real element
        if (idx == numbers.size - 1) {
            break
        }
        if (delimeter >= 0) {
            // Always insert when delimiter is non-negative
            result.add(delimeter)
        } else {
            // Insert unless this is the k-th, 2k-th, 3k-th ... element (1-based)
            if ((idx + 1) % skipInterval!! != 0) {
                result.add(delimeter)
            }
            // otherwise: skip insertion
        }
    }
    return result
};1

