import java.util.EnumSet
import java.util.stream.Collectors
import java.util.stream.IntStream
 
enum class Peg(val value: Int) {
    A(1), B(2), C(3), D(4), E(5), F(6), G(7), H(8)
}
 
val connections = listOf(
        Pair(Peg.A, Peg.C), Pair(Peg.A, Peg.D), Pair(Peg.A, Peg.E),
        Pair(Peg.B, Peg.D), Pair(Peg.B, Peg.E), Pair(Peg.B, Peg.F),
        Pair(Peg.G, Peg.C), Pair(Peg.G, Peg.D), Pair(Peg.G, Peg.E),
        Pair(Peg.H, Peg.D), Pair(Peg.H, Peg.E), Pair(Peg.H, Peg.F),
        Pair(Peg.C, Peg.D), Pair(Peg.D, Peg.E), Pair(Peg.E, Peg.F)
)
 
fun ok(conn: Pair<Peg, Peg>, perm: List<Int>): Boolean {
    val thisPeg = conn.first.value - 1
    val thatPeg = conn.second.value - 1
    return Math.abs(perm[thisPeg] - perm[thatPeg])!= 1
}
 
fun solve(): List<List<Int>> {
    val range = IntStream.range(1, 9).boxed().collect(Collectors.toList())
    return range.permutations().filter { perm ->
        connections.all { ok(it, perm) }
    }
}
 
fun main(args: Array<String>) {
    val solutions = solve()
    println("A, B, C, D, E, F, G, H = ${solutions[0]}")
}
 
fun <T> Iterable<T>.permutations(): List<List<T>> {
    if (this.count() == 1) return listOf(listOf(this.first()))
    return this.flatMap { element ->
        this.filter { it!= element }.permutations().map { listOf(element) + it }
    }
};1

