fun Matrix<GraphNode>.detectBasins() = flatten().fold(emptySet<Basin>()) { basins, currentNode ->
    when {
        currentNode.height == 9 -> basins // skip the highest points
        basins.any { it.contains(currentNode.point) } -> basins // skip points that already belong to some basin
        else ->
            // run bfs starting in the current node and add it to the set of basins
            basins + runBfs(queue = ArrayDeque(listOf(currentNode)))
                .map(GraphNode::point)
                .toSet()
                .let(::Basin)
    }
};0

fun fibonacciSequenceUpTo(n: Int): Any {
    if (n <= 0) {
        return "Invalid input"
    }
    var a = 0
    var b = 1
    val sequence = mutableListOf<Int>()
    while (a <= n) {
        sequence.add(a)
        val temp = a
        a = b
        b = temp + b
    }
    return sequence
};1

 
fun repString(s: String): MutableList<String> {
    val reps = mutableListOf<String>()
    if (s.length < 2) return reps
    for (c in s) if (c != '0' && c != '1') throw IllegalArgumentException("Not a binary string")
    for (len in 1..s.length / 2) {
        val t = s.take(len)
        val n = s.length / len
        val r = s.length % len
        val u = t.repeat(n) + t.take(r)
        if (u == s) reps.add(t)
    }
    return reps
}
 
fun main(args: Array<String>) {
    val strings = listOf(
        "1001110011",
        "1110111011",
