        "101",
        "11",
        "00",
        "1"
    )
    println("The (longest) rep-strings are:\n")
    for (s in strings) {
        val reps = repString(s)
        val size = reps.size
        println("${s.padStart(10)} -> ${if (size > 0) reps[size - 1] else "Not a rep-string"}")
