fun stripControlChars(arg: String): String {
    val arrForm = arg.toCharArray()
    val buffer = StringBuilder(arg.length) //This many chars at most
 
    for (ch in arrForm)
        if (!Character.isISOControl(ch)) buffer.append(ch) //Only add to buffer if not a control char
 
    return buffer.toString()
}
 
fun stripExtended(arg: String): String {
    val buffer = StringBuilder(arg.length) //Max length
    for (ch in arg) {
        val num = ch.toInt() //In.NET, chars are UTF-16
        //The basic characters have the same code points as ASCII, and the extended characters are bigger
        if ((num >= 32) && (num <= 126)) buffer.append(ch)
    }
    return buffer.toString()
};1

