fun play(round: String): Int {
    val (opp, me) = round.split(' ')

    val outcome = when (opp) {
        "A" -> when (me) {
            "X" -> 3
            "Y" -> 6
            "Z" -> 0
            else -> 0
        }
        "B" -> when (me) {
            "X" -> 0
            "Y" -> 3
            "Z" -> 6
            else -> 0
        }
        "C" -> when (me) {
            "X" -> 6
            "Y" -> 0
            "Z" -> 3
            else -> 0
        }
        else -> 0
    }

    val shape =
        when (me) {
            "X" -> 1
            "Y" -> 2
            "Z" -> 3
            else -> 0
        }
    return shape + outcome
};0

