fun lcm(numbers: List<Int>): Long {
  return numbers.flatMap { it.factors.withCounts().entries }
    .groupBy { (k, _) -> k }
    .map { (k, v) -> k to v.maxOf { it.value } }
    .fold(1L) { acc, (n, e) -> acc * n.toLong().pow(e) }
};0

import kotlin.math.exp
import kotlin.math.pow
import kotlin.math.sqrt
import kotlin.random.Random
 
fun GammaInc_Q(a: Double, x: Double): Double {
    val a1 = a - 1
    val a2 = a - 2
    fun f0(t: Double) = t.pow(a1) * exp(-t)
    fun df0(t: Double) = (a1 - t) * t.pow(a2) * exp(-t)
    var y = a1
    while (f0(y) * (x - y) > 2.0e-8 && y < x) {
        y += 0.3
    }
    if (y > x) {
        y = x
    }
    var h = 3.0e-4
    var n = y / h
    h = y / n
    val hh = 0.5 * h
    var gamax = h * (0 until n).sumByDouble { f0(h * it) + hh * df0(h * it) }
    return gamax / gamma_spounge(a)
}
 
var c: List<Double>? = null
fun gamma_spounge(z: Double): Double {
    if (c == null) {
        var k1_factrl = 1.0
        c = mutableListOf(sqrt(2.0 * Math.PI))
        for (k in 1 until 12) {
            c.add(exp(12 - k) * (12 - k).toDouble().pow(k - 0.5) / k1_factrl)
            k1_factrl *= -k
        }
    }
    var accm = c!![0]
    for (k in 1 until 12) {
        accm += c!![k] / (z + k)
    }
    accm *= exp(-(z + 12)) * (z + 12).toDouble().pow(z + 0.5)
    return accm / z
}
 
fun chi2UniformDistance(dataSet: List<Int>): Double {
    val expected = dataSet.sum().toDouble() / dataSet.size
    val cntrd = dataSet.map { it - expected }
    return cntrd.sumByDouble { it * it } / expected
}
 
fun chi2Probability(dof: Int, distance: Double): Double {
    return 1.0 - GammaInc_Q(0.5 * dof, 0.5 * distance)
}
 
fun chi2IsUniform(dataSet: List<Int>, significance: Double): Boolean {
    val dof = dataSet.size - 1
    val dist = chi2UniformDistance(dataSet)
    return chi2Probability(dof, dist) > significance
}
 
