import java.io.PrintStream
 
fun main(args: Array<String>) {
    val neighbours = arrayOf(intArrayOf(2, 2), intArrayOf(-2, 2), intArrayOf(2, -2), intArrayOf(-2, -2), intArrayOf(3, 0), intArrayOf(0, 3), intArrayOf(-3, 0), intArrayOf(0, -3))
    var cnt = 0
    var pWid = 0
    var pHei = 0
 
    fun is_valid(a: Int, b: Int): Boolean {
        return -1 < a && a < pWid && -1 < b && b < pHei
    }
 
    fun iterate(pa: Array<IntArray>, x: Int, y: Int, v: Int): Int {
        if (v > cnt) {
            return 1
        }
 
        for (i in neighbours.indices) {
            val a = x + neighbours[i][0]
            val b = y + neighbours[i][1]
            if (is_valid(a, b) && pa[a][b] == 0) {
                pa[a][b] = v
                val r = iterate(pa, a, b, v + 1)
                if (r == 1) {
                    return r
                }
                pa[a][b] = 0
            }
        }
        return 0
    }
 
    fun solve(pz: String, w: Int, h: Int): Pair<Int, Array<IntArray>> {
        var cnt = 0
        var pWid = 0
        var pHei = 0
 
        val pa = Array(w) { IntArray(h) { -1 } }
        var f = 0
        pWid = w
        pHei = h
        for (j in 0 until h) {
            for (i in 0 until w) {
                if (pz[f] == '1') {
                    pa[i][j] = 0
                    cnt++
                }
                f++
            }
        }
 
        for (y in 0 until h) {
            for (x in 0 until w) {
                if (pa[x][y] == 0) {
                    pa[x][y] = 1
                    if (1 == iterate(pa, x, y, 2)) {
                        return Pair(1, pa)
                    }
                    pa[x][y] = 0
                }
            }
        }
 
        return Pair(0, pa)
    }
 
    val r = solve("011011011111111111111011111000111000001000", 7, 6)
    if (r.first == 1) {
        for (j in 0 until 6) {
            for (i in 0 until 7) {
                if (r.second[i][j] == -1) {
                    System.out.print("   ")
                } else {
                    System.out.printf(" %02d", r.second[i][j])
                }
            }
            println()
        }
    } else {
        System.out.print("No solution!")
    }
};1

