import java.awt.Point
import java.util.Scanner
 
fun main(args: Array<String>) {
    val sc = Scanner(System.`in`)
 
    val key = prompt("Enter an encryption key (min length 6): ", sc, 6)
    val txt = prompt("Enter the message: ", sc, 1)
    val jti = prompt("Replace J with I? y/n: ", sc, 1)
 
    val changeJtoI = jti.equals("y", ignoreCase = true)
 
    createTable(key, changeJtoI)
 
    val enc = encode(prepareText(txt, changeJtoI))
 
    println("\nEncoded message: ")
    println(enc)
    println("\nDecoded message: ")
    println(decode(enc))
}
 
fun prompt(promptText: String, sc: Scanner, minLen: Int): String {
    var s: String
    do {
        print(promptText)
        s = sc.nextLine().trim()
    } while (s.length < minLen)
    return s
}
 
fun prepareText(s: String, changeJtoI: Boolean): String {
    var s = s.toUpperCase().replace("[^A-Z]".toRegex(), "")
    return if (changeJtoI) s.replace("J", "I") else s.replace("Q", "")
}
 
fun createTable(key: String, changeJtoI: Boolean) {
    charTable = Array(5) { CharArray(5) }
    positions = Array(26) { Point() }
 
    var s = prepareText(key + "ABCDEFGHIJKLMNOPQRSTUVWXYZ", changeJtoI)
 
    val len = s.length
    for (i in 0 until len) {
        val c = s[i]
        if (positions[c - 'A'] == null) {
            charTable[i / 5][i % 5] = c
            positions[c - 'A'] = Point(i % 5, i / 5)
        }
    }
}
 
fun encode(s: String): String {
    val sb = StringBuilder(s)
 
    for (i in 0..sb.length - 1 step 2) {
        if (i == sb.length - 1) {
            sb.append(if (sb.length % 2 == 1) 'X' else "")
        } else if (sb[i] == sb[i + 1]) {
            sb.insert(i + 1, 'X')
        }
    }
    return codec(sb, 1)
}
 
fun decode(s: String): String {
    return codec(StringBuilder(s), 4)
}
 
fun codec(text: StringBuilder, direction: Int): String {
    val len = text.length
    for (i in 0..len - 1 step 2) {
        val a = text[i]
        val b = text[i + 1]
 
        val row1 = positions[a - 'A'].y
        val row2 = positions[b - 'A'].y
        val col1 = positions[a - 'A'].x
        val col2 = positions[b - 'A'].x
 
        if (row1 == row2) {
            col1 = (col1 + direction) % 5
            col2 = (col2 + direction) % 5
 
        } else if (col1 == col2) {
            row1 = (row1 + direction) % 5
            row2 = (row2 + direction) % 5
 
        } else {
            val tmp = col1
            col1 = col2
            col2 = tmp
        }
 
        text.setCharAt(i, charTable[row1][col1])
        text.setCharAt(i + 1, charTable[row2][col2])
    }
    return text.toString()
};1

fun <T> List<T>.indicesOf(predicate: (T) -> Boolean): List<Int> {
    val result = mutableListOf<Int>()
    this.forEachIndexed { index, t ->
        if (predicate(t)) result += index
    }
    return result
};0

 
