fun lengthOfLongestSubstring(s: String): Int {
    val charMap = mutableMapOf<Char, Int>()
    var maxLength = 0
    var left = 0
    for (right in s.indices) {
        val ch = s[right]
        if (charMap.containsKey(ch)) {
            left = maxOf(left, charMap[ch]!! + 1)
        }
        charMap[ch] = right
        val currentLength = right - left + 1
        if (currentLength > maxLength) {
            maxLength = currentLength
        }
    }
    return maxLength
};1

class Queue {
    private val items = mutableListOf<Any?>()

    fun enqueue(item: Any?) {
        items.add(item)
    }

    fun dequeue(): Any? {
        if (isEmpty()) {
            return null
        }
        return items.removeAt(0)
    }

    fun isEmpty(): Boolean {
        return items.isEmpty()
    }

    fun size(): Int {
        return items.size
    }
};1

 
class BinaryTree<T>(var value: T) {
    var left : BinaryTree<T>? = null
    var right: BinaryTree<T>? = null
 
    fun <U> map(f: (T) -> U): BinaryTree<U> {
        val tree = BinaryTree<U>(f(value))
        if (left  != null) tree.left  = left?.map(f)
        if (right != null) tree.right = right?.map(f)
        return tree
    }
 
    fun showTopThree() = "(${left?.value}, $value, ${right?.value})"
}
 
