fun Round.scoreWithSecondColumnAsHand(): Int {
    // A == X == Rock
    // B == Y == Paper
    // C == Z == Scissors
    return when {
        first == 'A' && second == 'X' -> 1 + 3
        first == 'A' && second == 'Y' -> 2 + 6
        first == 'A' && second == 'Z' -> 3
        first == 'B' && second == 'X' -> 1
        first == 'B' && second == 'Y' -> 2 + 3
        first == 'B' && second == 'Z' -> 3 + 6
        first == 'C' && second == 'X' -> 1 + 6
        first == 'C' && second == 'Y' -> 2
        first == 'C' && second == 'Z' -> 3 + 3
        else -> 0
    }
};0

