fun binomial(n: Int, k: Int): Int {
    if (n < k) {
        return 0
    }
    if (n == 0 || k == 0) {
        return 1
    }
    var num = 1
    for (i in k + 1..n) {
        num *= i
    }
    var den = 1
    for (i in 2..n - k) {
        den *= i
    }
    return num / den
}
 
fun pascalUpperTriangular(n: Int): Array<IntArray> {
    val m = Array(n) { IntArray(n) }
    for (i in 0 until n) {
        for (j in 0 until n) {
            m[i][j] = binomial(j, i)
        }
    }
    return m
}
 
fun pascalLowerTriangular(n: Int): Array<IntArray> {
    val m = Array(n) { IntArray(n) }
    for (i in 0 until n) {
        for (j in 0 until n) {
            m[i][j] = binomial(i, j)
        }
    }
    return m
}
 
fun pascalSymmetric(n: Int): Array<IntArray> {
    val m = Array(n) { IntArray(n) }
    for (i in 0 until n) {
        for (j in 0 until n) {
            m[i][j] = binomial(i + j, i)
        }
    }
    return m
}
 
