fun <A> isSorted(aa: List<A>, ordered: (A, A) -> Boolean): Boolean {
  fun loop(head: A, tail: List<A>): Boolean =
    when {
      head == null -> true
      tail.isEmpty() -> true
      ordered(head, tail.head) -> loop(tail.head, tail.tail)
      else -> false
    }
  return loop(aa.head, aa.tail)
};0

fun calculate_average_points(players: List<Map<String, Any>>): Map<String, Double> {
    val averagePoints = mutableMapOf<String, Double>()
    for (player in players) {
        val name = player["name"] as String
        @Suppress("UNCHECKED_CAST")
        val points = player["points"] as List<Int>
        val totalPoints = points.sum()
        val numGames = points.size
        val average = if (numGames > 0) totalPoints.toDouble() / numGames else 0.0
        averagePoints[name] = String.format("%.2f", average).toDouble()
    }
    return averagePoints
};1

