import kotlin.math.sqrt
 
val shades = listOf('.', ':', '!', '*', 'o', 'e', '&', '#', '%', '@')
 
fun normalize(v: List<Double>): List<Double> {
    val len = sqrt(v[0]*v[0] + v[1]*v[1] + v[2]*v[2])
    return listOf(v[0]/len, v[1]/len, v[2]/len)
}
 
fun dot(x: List<Double>, y: List<Double>): Double {
    val d = x[0]*y[0] + x[1]*y[1] + x[2]*y[2]
    return if (d < 0) -d else 0.0
}
 
fun drawSphere(r: Double, k: Double, ambient: Double, light: List<Double>) {
    for (i in -r.toInt()..r.toInt()) {
        val x = i + 0.5
        var line = ""
 
        for (j in (-2*r).toInt()..(2*r).toInt()) {
            val y = j/2 + 0.5
            if (x*x + y*y <= r*r) {
                val vec = normalize(listOf(x, y, sqrt(r*r - x*x - y*y)))
                val b = Math.pow(dot(light, vec), k) + ambient
                val intensity = ((1-b)*(shades.size-1)).toInt()
                line += if (0 <= intensity && intensity < shades.size) shades[intensity] else shades[0]
            } else {
                line += " "
            }
        }
 
        println(line)
    }
}
 
