fun preprocessData(data: List<List<Any>>): List<List<Any>> {
    val MEAN = 50.0
    val STD = 10.0
    val processed = mutableListOf<List<Any>>()
    for (row in data) {
        // Copy original row
        val newRow = row.toMutableList()
        // Extract scores, assumed to be numeric
        val readingScore = (row[5] as Number).toDouble()
        val writingScore = (row[6] as Number).toDouble()
        // Z-score normalization
        val zReading = (readingScore - MEAN) / STD
        val zWriting = (writingScore - MEAN) / STD
        // Average of standardized scores
        val avgZ = (zReading + zWriting) / 2.0
        // Append new values
        newRow.add(zReading)
        newRow.add(zWriting)
        newRow.add(avgZ)
        processed.add(newRow)
    }
    return processed
};1

