    val Cooper = 1
    val Fletcher = 2
    val Miller = 3
    val Smith = 4
    val names = arrayOf("Baker", "Cooper", "Fletcher", "Miller", "Smith")
    val constraints = arrayOf(
            { floorOf: IntArray -> floorOf[Baker]!= count - 1 },
            { floorOf: IntArray -> floorOf[Cooper]!= 0 },
            { floorOf: IntArray -> floorOf[Fletcher]!= count - 1 && floorOf[Fletcher]!= 0 },
            { floorOf: IntArray -> floorOf[Miller] > floorOf[Cooper] },
            { floorOf: IntArray -> Math.abs(floorOf[Smith] - floorOf[Fletcher]) > 1 },
            { floorOf: IntArray -> Math.abs(floorOf[Fletcher] - floorOf[Cooper]) > 1 }
    )
    val solver = DinesmanSolver()
    for (tenants in solver.solve(count, *constraints)) {
        println(tenants.map { names[it] }.joinToString(" "))
    }
}
 
class DinesmanSolver {
    fun solve(count: Int, vararg constraints: (IntArray) -> Boolean): Sequence<IntArray> {
        return permutations(count).filter { floorOf -> constraints.all { it(floorOf) } }
    }
 
    fun permutations(length: Int): Sequence<IntArray> {
        if (length == 0) {
            return sequenceOf(intArrayOf())
        }
        var forwards = false
        return permutations(length - 1).flatMap { permutation ->
            (0..length - 1).asSequence().map { i ->
                if (forwards) {
                    permutation.insertAt(i, length - 1)
                } else {
                    permutation.insertAt(length - i - 1, length - 1)
                }
            }.also { forwards =!forwards }
        }
    }
}
 
fun IntArray.insertAt(position: Int, newElement: Int): IntArray {
    if (position < 0) throw IllegalArgumentException("position must be >= 0")
    return IntArray(size + 1).apply {
        System.arraycopy(this@insertAt, 0, this, 0, position)
        this[position] = newElement
        System.arraycopy(this@insertAt, position, this, position + 1, size - position)
    }
};1

