fun foodWays(n: Int): Int {
    fun fastDoubling(k: Int): Int {
        fun fib(k: Int): Pair<Int, Int> {
            if (k == 0) return Pair(0, 1)
            val (a, b) = fib(k shr 1)
            val c = a * (2 * b - a)
            val d = a * a + b * b
            return if ((k and 1) == 1) Pair(d, c + d) else Pair(c, d)
        }
        return fib(k).first
    }
    val totalWays = fastDoubling(n + 2)
    return totalWays * totalWays
};1

