fun twoPointer(nums: List<Int>, target: Int): List<Int> {
    var i = 0
    var j = nums.size - 1
    while (i < j) {
        val sum = nums[i] + nums[j]
        if (sum == target) {
            return listOf(i, j)
        } else if (sum < target) {
            i += 1
        } else {
            j -= 1
        }
    }
    return listOf()
};1

