fun rpnCalculate(expr: String) {
    if (expr.isEmpty()) throw IllegalArgumentException("Expresssion cannot be empty")
    println("For expression = $expr\n")
    println("Token           Action             Stack")
    val tokens = expr.split(' ').filter { it != "" }
    val stack = mutableListOf<Double>()
    for (token in tokens) {
        val d = token.toDoubleOrNull()
        if (d != null) {
            stack.add(d)
            println(" $d   Push num onto top of stack  $stack")
        }
        else if ((token.length > 1) || (token !in "+-*/^")) {
            throw IllegalArgumentException("$token is not a valid token")
        }
        else if (stack.size < 2) {
            throw IllegalArgumentException("Stack contains too few operands")
        }
        else {
            val d1 = stack.removeAt(stack.lastIndex)
            val d2 = stack.removeAt(stack.lastIndex)
            stack.add(when (token) {
                "+"  -> d2 + d1
                "-"  -> d2 - d1
                "*"  -> d2 * d1
                "/"  -> d2 / d1
                else -> Math.pow(d2, d1)
            })
            println(" $token     Apply op to top of stack    $stack")
        }
    }
    println("\nThe final value is ${stack[0]}")
}
 
fun main(args: Array<String>) {
    val expr = "3 4 2 * 1 5 - 2 3 ^ ^ / +"
    rpnCalculate(expr)
};0

fun dropRock(startPoint: Pair<Int, Int>, blockers: Set<Pair<Int, Int>>, floor: Int): Pair<Int, Int> {
    var (x, y) = startPoint
    var hasMove = true
    while (hasMove && y < floor) {
        if (x to y + 1 !in blockers) {
            y++
            continue
        }
        if (x - 1 to y + 1 !in blockers) {
            x--
            y++
            continue
        }
        if (x + 1 to y + 1 !in blockers) {
            x++
            y++
            continue
        }
        else hasMove = false
    }
    return x to y
};0

fun removeDuplicates(lst: List<Int>): List<Int> {
    // Remove duplicates from a list of integers while preserving order.
    // Parameters:
    //     lst: The input list containing integers (possibly with duplicates).
    // Returns:
    //     A new list containing only the first occurrence of each integer from the original list, in the same order.
    val seen = mutableMapOf<Int, Boolean>() // Map for fast look-ups of already seen integers
    val unique = mutableListOf<Int>() // Result list to accumulate unique integers in order
    for (value in lst) {
        if (!seen.containsKey(value)) {
            seen[value] = true
            unique.add(value)
        }
    }
    return unique
};1

