fun findMax(data: Any?): Int {
    // Top-level type check
    if (data !is List<*>) {
        throw IllegalArgumentException("Input must be a 2-D list.")
    }
    if (data.isEmpty()) {
        throw IllegalArgumentException("Input list must not be empty.")
    }
    var maxVal: Int? = null
    for ((rowIdx, row) in data.withIndex()) {
        if (row !is List<*>) {
            throw IllegalArgumentException("Row $rowIdx is not a list.")
        }
        if (row.isEmpty()) {
            throw IllegalArgumentException("Row $rowIdx must not be empty.")
        }
        for ((colIdx, value) in row.withIndex()) {
            // Not Int or is Boolean (Kotlin Boolean is not subclass of Int, just type check for Int)
            if (value !is Int) {
                throw IllegalArgumentException("Element at ($rowIdx, $colIdx) is not an integer.")
            }
            if (maxVal == null || value > maxVal) {
                maxVal = value
            }
        }
    }
    // As per spec, the input is non-empty, so maxVal will always be set
    return maxVal!!
};1

