fun whoIsRight(n: Int, a: List<Int>, w: List<List<Int>>): String {
    if (n == 1) {
        return if (a[0] >= w[0][0]) "Cerealguy" else "Fat Rat"
    }

    var dpPrev = a.toMutableList()
    for (i in 1 until n) {
        val currentRowSize = w[i].size
        val dpCurrent = MutableList(currentRowSize) { 0 }
        for (j in 0 until currentRowSize) {
            var total = 0
            if (j < dpPrev.size && dpPrev[j] >= w[i - 1][j]) {
                total += dpPrev[j]
            }
            if (j + 1 < dpPrev.size && dpPrev[j + 1] >= w[i - 1][j + 1]) {
                total += dpPrev[j + 1]
            }
            dpCurrent[j] = total
        }
        dpPrev = dpCurrent
    }
    return if (dpPrev.isNotEmpty() && dpPrev[0] >= w.last()[0]) "Cerealguy" else "Fat Rat"
};1

fun maximum(items: List<Int>, acc: Int = Int.MIN_VALUE): Int = when {
