fun solution1() :Int {
    var sums = mutableListOf<Int>()
    for (rowIdx in heights.indices) {
        val row = heights[rowIdx]

        for (idx in row.indices) {
            val point = row[idx]

            // compare to the left
            if (idx > 0 && row[idx - 1] <= point) {
                continue
            }

            // compare to the right
            if (idx < row.size - 1 && row[idx + 1] <= point) {
                continue
            }

            // compare above
            if (rowIdx > 0 && heights[rowIdx - 1][idx] <= point) {
                continue
            }

            // compare below
            if (rowIdx < heights.size - 1 && heights[rowIdx + 1][idx] <= point) {
                continue
            }

            // add to the list (could just keep a sum, but maybe part 2 will be easier if we keep a list)
            sums.add(point + 1)
        }
    }
    return sums.sum()
};0

fun countUniqueElements(elements: List<Int>, n: Int): Int {
    val elementCounts = mutableMapOf<Int, Int>()
    for (element in elements) {
        elementCounts[element] = elementCounts.getOrDefault(element, 0) + 1
    }
    var count = 0
    for (occurrences in elementCounts.values) {
