fun polycarpsWritingImplements(cases: List<Quintuple<Int, Int, Int, Int, Int>>): List<Pair<Int, Int?>> {
    val res = mutableListOf<Pair<Int, Int?>>()
    for ((a, b, c, d, k) in cases) {
        val pens = (a + c - 1) / c
        val pencils = (b + d - 1) / d
        if (pens + pencils > k) {
            res.add(Pair(-1, null))
        } else {
            res.add(Pair(pens, pencils))
        }
    }
    return res
}

