fun mergeSort(arr: List<Int>): List<Int> {
    // Base case: an array of length 0 or 1 is already sorted.
    if (arr.size <= 1) {
        return arr.toList() // Return a copy
    }

    // Recursive case: split the array, sort each half, then merge.
    val mid = arr.size / 2
    val leftSorted = mergeSort(arr.subList(0, mid))
    val rightSorted = mergeSort(arr.subList(mid, arr.size))

    // Merge two sorted sub-arrays into one sorted result.
    val merged = mutableListOf<Int>()
    var i = 0
    var j = 0
    while (i < leftSorted.size && j < rightSorted.size) {
        if (leftSorted[i] <= rightSorted[j]) {
            merged.add(leftSorted[i])
            i += 1
        } else {
            merged.add(rightSorted[j])
            j += 1
        }
    }
    // Append any remaining elements from either sub-array.
    merged.addAll(leftSorted.subList(i, leftSorted.size))
    merged.addAll(rightSorted.subList(j, rightSorted.size))
    return merged
};1

