fun processSpectralData(spectralData: Map<Int, Double>): Pair<Double, Int> {
    // Total number of data points
    val count = spectralData.size

    // Compute the average spectral value
    val totalValue = spectralData.values.sum()
    val averageValue = totalValue / count

    // Determine the wavelength with the maximum spectral value
    // maxKey will hold the wavelength (map key) where the value is highest
    val maxWavelength = spectralData.maxByOrNull { it.value }?.key ?: spectralData.keys.first()

    // Return Pair(averageValue, wavelengthOfMaxValue)
    return Pair(averageValue, maxWavelength)
};1

