val e = charArrayOf('²', '³', '⁴', '⁵', '⁶', '⁷')
 
fun pp(c: List<Long>): String {
    if (c.size == 1) {
        return c[0].toString()
    }
    val p = c.size - 1
    var s = if (c[p]!= 1L) c[p].toString() else ""
    for (i in p downTo 1) {
        s += "x"
        if (i!= 1) {
            s += e[i - 2]
        }
        if (c[i - 1] < 0) {
            s += " - ${-c[i - 1]}"
        } else {
            s += " + ${c[i - 1]}"
        }
    }
    return s
}
 
fun aks(p: Int): Boolean {
    val c = bc(p)
    c[p]--
    c[0]++
    for (d in c) {
        if (d % p!= 0L) {
            return false
        }
    }
    return true
};1

