fun searchInRangeArray(rangeArray: Array<IntRange>, key: Int): Int {
    var low = 0
    var high = rangeArray.size - 1
    while (low <= high) {
        val mid = (low + high) / 2
        val midRange = rangeArray[mid]
        when {
            key in midRange -> return mid
            key < midRange.first -> high = mid - 1
            else -> low = mid + 1
        }
    }
    return -1
};0

