fun generateUrls(actions: List<String>, parameters: Map<String, Any>): Map<String, String> {
    // Create a stable (deterministic) query string by sorting keys alphabetically.
    val query = if (parameters.isNotEmpty()) {
        parameters.toSortedMap().entries.joinToString("&") { "${it.key}=${it.value}" }
    } else {
        ""
    }

    val urls = mutableMapOf<String, String>()
    for (action in actions) {
        val path = "/$action"
        val url = if (query.isNotEmpty()) "$path?$query" else path
        urls[action] = url
    }

    return urls
};1

fun findSuspiciousPerformances(performances: List<Pair<String, Int>>): Map<String, List<Int>> {
