fun generateSecureString(length: Int): String {
    // A valid secure string needs at least 3 characters: one of each required type
    if (length < 3) return ""

    val uppercase = ('A'..'Z').toList()
    val lowercase = ('a'..'z').toList()
    val digits = ('0'..'9').toList()
    val allChars = uppercase + lowercase + digits

    val result = mutableListOf<Char>()
    result += uppercase.random()
    result += lowercase.random()
    result += digits.random()

    val remainingLength = length - 3
    repeat(remainingLength) {
        result += allChars.random()
    }

    result.shuffle(Random.Default)

    return result.joinToString("")
};1

