fun analyzeSurveyResponses(responses: List<String>): Map<String, Double> {
    val responseCounts = mutableMapOf<String, MutableMap<String, Int>>()
    for (response in responses) {
        val (level, surveillanceType) = response.split(":", limit = 2)
        if (!responseCounts.containsKey(surveillanceType)) {
            responseCounts[surveillanceType] = mutableMapOf("uncomfortable" to 0, "total" to 0)
        }
        responseCounts[surveillanceType]!!["total"] = responseCounts[surveillanceType]!!["total"]!! + 1
        if (level == "uncomfortable") {
            responseCounts[surveillanceType]!!["uncomfortable"] = responseCounts[surveillanceType]!!["uncomfortable"]!! + 1
        }
    }
    val result = mutableMapOf<String, Double>()
    for ((surveillanceType, counts) in responseCounts) {
        val total = counts["total"] ?: 0
        val uncomfortable = counts["uncomfortable"] ?: 0
        val percent = if (total > 0) {
            (uncomfortable.toDouble() / total.toDouble()) * 100.0
        } else {
            0.0
        }
        result[surveillanceType] = String.format("%.2f", percent).toDouble()
    }
    return result
};1

