fun analyzePenalties(matches: List<Map<String, Any>>, penaltyThreshold: Int): Map<String, Int> {
    val teamPenalties = mutableMapOf<String, Int>()
    for (match in matches) {
        val team = match["team"] as String
        val penalties = match["penalties"] as Int
        if (!teamPenalties.containsKey(team)) {
            teamPenalties[team] = 0
        }
        if (penalties > penaltyThreshold) {
            teamPenalties[team] = teamPenalties[team]!! + 1
        }
    }
    // Remove teams with zero matches exceeding threshold
    return teamPenalties.filter { it.value > 0 }
};1

fun testEqual(lists: List<List<Any?>>): Any {
    val result = mutableListOf<Any?>()

    for (sub in lists) {
        // Empty sub-list
        if (sub.isEmpty()) {
            result.add(null)
            continue
        }
        val first = sub[0]
        val firstType = first?.javaClass

        // Check that all elements share the exact same type
        for (item in sub) {
            if (item?.javaClass != firstType) {
                return "Error: The list elements should be of the same data types."
            }
        }
        // All items have the same type: are they also all equal?
        if (sub.all { it == first }) {
            result.add(first)
        } else {
            result.add(null)
        }
    }
    return result
};1

