fun calculateUniqueProduct(numbers: List<Int>): Int {
    if (numbers.isEmpty()) return 1

    val counts = numbers.groupingBy { it }.eachCount()
    val uniques = counts.filter { it.value == 1 }.keys
    if (uniques.isEmpty()) return 1

    // Compute product of unique integers
    return uniques.fold(1) { acc, num -> acc * num }
};1

