fun colorPathCounts(N: Int, colors: List<Int>, edges: List<Pair<Int, Int>>): List<Int> {
    val adj = Array(N + 1) { mutableListOf<Int>() }
    for ((a, b) in edges) {
        adj[a].add(b)
        adj[b].add(a)
    }

    val colorNodes = mutableMapOf<Int, MutableList<Int>>()
    for ((i, col) in colors.withIndex()) {
        colorNodes.computeIfAbsent(col) { mutableListOf() }.add(i + 1)
    }

    val totalPairs = N * (N + 1) / 2
    val answers = mutableListOf<Int>()
    for (k in 1..N) {
        val visited = BooleanArray(N + 1)
        for (node in colorNodes[k] ?: emptyList()) {
            visited[node] = true
        }
        var sumNoK = 0
        for (u in 1..N) {
            if (!visited[u] && colors[u - 1] != k) {
                val q: Queue<Int> = ArrayDeque()
                q.add(u)
                visited[u] = true
                var cnt = 0
                while (q.isNotEmpty()) {
                    val v = q.poll()
                    cnt += 1
                    for (nei in adj[v]) {
                        if (!visited[nei] && colors[nei - 1] != k) {
                            visited[nei] = true
                            q.add(nei)
                        }
                    }
                }
                sumNoK += cnt * (cnt + 1) / 2
            }
        }
        val ans = totalPairs - sumNoK
        answers.add(ans)
    }
    return answers
};1

fun dictToCsv(dictData: List<Map<String, Any>>): List<String> {
    if (dictData.isEmpty()) return emptyList()

    val headerKeys = dictData[0].keys.toList()
    val headerRow = headerKeys.joinToString(",")

    fun csvEscape(value: Any): String {
        var text = value.toString()
        if (text.contains('"')) {
            text = text.replace("\"", "\"\"")
        }
        return if (text.contains(',') || text.contains('"')) {
            "\"$text\""
        } else {
            text
        }
    }

    val dataRows = dictData.map { record ->
        headerKeys.map { key -> csvEscape(record[key] ?: "") }.joinToString(",")
    }

    return listOf(headerRow) + dataRows
};1

fun adjustGrowthMedium(importRates: List<Number>, minThreshold: Double = 0.000001): List<Double> {
    // Ensures every import rate in the provided list meets or exceeds the specified minimum threshold.
    return importRates.map { rate -> maxOf(rate.toDouble(), minThreshold) }
};1

fun parseTrueFalseTargets(trueInput: String, falseInput: String): Pair<Int,Int> {
    val throwTargetRegex = "^\\s*If (?:true|false): throw to monkey (\\d+)$".toRegex()
    val (trueTarget) = throwTargetRegex.matchEntire(trueInput)!!.destructured
    val (falseTarget) = throwTargetRegex.matchEntire(falseInput)!!.destructured
    return Pair(trueTarget.toInt(), falseTarget.toInt())
};0

