fun oddCubes(n: Int): List<Int> {
    // Validate n is integer and greater than zero
    if (n <= 0) {
        throw IllegalArgumentException("Input must be greater than zero.")
    }
    // Pre-compute odd numbers below 20
    val oddNumbers = (1 until 20).filter { it % 2 != 0 }
    if (n > oddNumbers.size) {
        throw IllegalArgumentException("Cannot generate $n cubes; only ${oddNumbers.size} odd numbers are less than 20.")
    }
    return oddNumbers.take(n).map { it * it * it }
};1

fun aboveAverageScores(scores: List<Int>): List<Int> {
    if (scores.isEmpty()) {
        return emptyList()
    }
    val averageScore = scores.sum().toDouble() / scores.size
    return scores.filter { it > averageScore }
};1

fun <T : Comparable<T>> generatePermutations(lst: List<T>): List<List<T>> {
    if (lst.isEmpty()) return emptyList()
    val current = lst.sorted().toMutableList()
    val permutations = mutableListOf<List<T>>()
    permutations.add(current.toList())
    val n = lst.size
    while (true) {
        // Find the largest index k such that current[k] < current[k+1]
        var k = -1
        for (i in 0 until n - 1) {
            if (current[i] < current[i + 1]) {
                k = i
            }
        }
        if (k == -1) {
            break
        }
        // Find the largest index l greater than k such that current[k] < current[l]
        var l = n - 1
        while (current[l] <= current[k]) {
            l -= 1
        }
        // Swap current[k] and current[l]
        val temp = current[k]
        current[k] = current[l]
        current[l] = temp
        // Reverse from current[k+1] to end
        val subList = current.subList(k + 1, n)
        subList.reverse()
        permutations.add(current.toList())
    }
    return permutations
};1

fun redistribute(banks: MutableList<Int>) {

    val max = banks.max()!!
    var index = banks.indexOf(max)
    var blocksToAlloc = max

    banks[index] = 0

    while (blocksToAlloc > 0) {

        ++index

        if (index >= banks.size) {
            index = 0
        }

        ++banks[index]
        --blocksToAlloc

    }

};0

fun purchaseTablets(prices: List<Int>, budget: Int): Pair<Int, Int> {
    val sortedPrices = prices.sorted()
    var totalCost = 0
    var count = 0
    for (price in sortedPrices) {
        if (totalCost + price <= budget) {
            totalCost += price
            count += 1
        } else {
            break
        }
    }
    return Pair(count, totalCost)
};1

