class Node<T: Number>(var data: T, var prev: Node<T>? = null, var next: Node<T>? = null) {
    fun toString(): String {
        val sb = StringBuilder(this.data.toString())
        var node = this.next
        while (node != null) {
            sb.append(" -> ", node.data.toString())
            node = node.next
        }
        return sb.toString()
    }
}
 
