fun canPerformAllSwaps(n: Int): Pair<Boolean, List<Pair<Int, Int>>?> {
    // Only n == 1 or n % 4 == 0 works
    if (n == 1) {
        return Pair(true, emptyList())
    }
    if (n % 4 != 0) {
        return Pair(false, null)
    }
    val swaps = mutableListOf<Pair<Int, Int>>()
    var i = 0
    while (i < n) {
        val a = i + 1
        val b = i + 2
        val c = i + 3
        val d = i + 4
        swaps.add(Pair(a, b))
        swaps.add(Pair(c, d))
        swaps.add(Pair(a, c))
        swaps.add(Pair(b, d))
        swaps.add(Pair(a, d))
        swaps.add(Pair(b, c))
        i += 4
    }
    return Pair(true, swaps)
};1

