class iterateNumbers {
    init {
        var baseNumberSquared = 0L //the base number multiplied by itself
        var baseNumber = 0L  //the number to be squared, this one will be iterated

        do  //this sets up the loop
        {
            baseNumber += 1 //add one to the base number
            baseNumberSquared = baseNumber * baseNumber //multiply the base number by itself and store the value as baseNumberSquared
        } while (Right6Digits(baseNumberSquared)!= 269696) //this will continue the loop until the right 6 digits of the base number squared are 269,696

        println("The smallest integer whose square ends in 269,696 is " + baseNumber)
        println("The square is " + baseNumberSquared)

    }

    fun Right6Digits(baseNumberSquared: Long): Long {

        val numberAsString = baseNumberSquared.toString() //this is converts the number to a different type so it can be cut up

        if (numberAsString.length < 6) {
            return baseNumberSquared
        } //if the number doesn't have 6 digits in it, just return it to try again.

        val numberAsString1 = numberAsString.substring(numberAsString.length - 6)  //this extracts the last 6 digits from the number

        return numberAsString1.toLong() //return the last 6 digits of the number

    }
};1

fun lowestCommonDenominator(a: Long, b: Long): Long {
    val biggerNum = if (a > b) a else b
    var lcm = biggerNum
    while (true) {
        if (((lcm % a) == 0L) && ((lcm % b) == 0L)) {
            break
        }

        lcm += biggerNum
    }

    return lcm
};0

fun solve(): Int {
    val n = readInt()
    val s = readLn().map { "()".indexOf(it) }
    val a = readLn()
    val must = IntArray(n) { -1 }
    val diff = BooleanArray(n)
    for (i in a.indices) {
        if (a[i] == '0') continue
        if (must[i] == 1) return -1
        must[i] = 0
        must[i + 3] = 1
        diff[i + 2] = true
    }
    val inf = n + 1
    val ans = s.indices.fold(listOf(0, 0)) { prev, i -> List(2) { j ->
        if (must[i] == 1 - j) inf else
            (s[i] xor j) + if (diff[i]) prev[1 - j] else prev.minOrNull()!!
    }}.minOrNull()!!
    return if (ans >= inf) -1 else ans
};0

fun renderParticles(particles: List<Pair<String, Int>>): List<String> {
    // Secondary ranking within the same pass
    fun secondaryRank(ptype: String): Pair<Int, String> = when (ptype) {
        "bond" -> Pair(0, "")
        "other" -> Pair(1, "")
        else -> Pair(2, ptype)
    }

    val particlesSorted = particles.sortedWith(compareBy({ it.second }, { secondaryRank(it.first).first }, { secondaryRank(it.first).second }))
    return particlesSorted.map { it.first }
};1

/**
 * 递归方案
 */
fun sumArr(newNum: IntArray, nums: IntArray, index: Int): Int {
    if (index == 0) {
        newNum[0] = nums[0]
        return nums[0]
    }
    newNum[index] = nums[index] + sumArr(newNum, nums, index - 1)

    return newNum[index]
};0

 
