fun checkTemperatures(n: Int, m: Int, minT: Int, maxT: Int, temps: List<Int>): String {
    for (temp in temps) {
        if (temp < minT || temp > maxT) {
            return "Incorrect"
        }
    }
    var required = 0
    if (!temps.contains(minT)) {
        required += 1
    }
    if (!temps.contains(maxT)) {
        required += 1
    }
    return if (required > n - m) {
        "Incorrect"
    } else {
        "Correct"
    }
};1

fun findMostFrequentCulturalElement(data: List<Any>): String {
    val flattenedData = mutableListOf<String>()
    for (item in data) {
        when (item) {
            is String -> flattenedData.add(item)
            is Pair<*, *> -> {
                flattenedData.add(item.first.toString())
                flattenedData.add(item.second.toString())
            }
        }
    }
    val allWords = mutableListOf<String>()
    val pattern = Pattern.compile("\\w+")
    for (text in flattenedData) {
        val matcher = pattern.matcher(text.lowercase())
        while (matcher.find()) {
            allWords.add(matcher.group())
        }
    }
    val wordCounts = allWords.groupingBy { it }.eachCount()
    return wordCounts.maxByOrNull { it.value }?.key ?: ""
};1

fun zigzag(m: Int, n: Int): List<List<Int>> {
    if (m <= 0 || n <= 0) return emptyList()

    val matrix = MutableList(m) { MutableList(n) { 0 } }
    var value = 1

    // There are m + n - 1 diagonals in total (indexed by r + c)
    for (d in 0 until (m + n - 1)) {
        val rowRange = if (d % 2 == 0) 0 until m else (m - 1 downTo 0)
        for (r in rowRange) {
            val c = d - r
            if (c in 0 until n) {
                matrix[r][c] = value
                value++
            }
        }
    }

    return matrix
};1

fun sumEvenProductOdd(lst: List<Any?>): Pair<Int, Int> {
    val filtered = lst.filter {
        // Filter only Ints, but ignore Boolean (which is a subtype of Int in Python, but not in Kotlin; but we mimic the intent)
        it is Int && it !is Boolean
    }.map { it as Int }
    if (filtered.isEmpty()) {
        return Pair(0, 0)
    }
    var evenSum = 0
    var oddProduct: Int? = null
    for (num in filtered) {
        if (num % 2 == 0) {
            evenSum += num
        } else {
            oddProduct = if (oddProduct == null) num else oddProduct * num
        }
    }
    if (oddProduct == null) {
        oddProduct = 0
    }
    return Pair(evenSum, oddProduct)
};1

object FibFibMemo {
    private val cache = mutableMapOf<Int, Int>()

    fun fibfib(k: Int): Int {
        if (cache.containsKey(k)) {
            return cache[k]!!
        }
        val result = when (k) {
            0, 1 -> 0
            2 -> 1
            in 3..Int.MAX_VALUE -> fibfib(k-1) + fibfib(k-2) + fibfib(k-3)
            else -> fibfib(k+3) - fibfib(k+2) - fibfib(k+1)
        }
        cache[k] = result
        return result
    }
}

fun evenFibfib(n: Int): Int {
    val first = FibFibMemo.fibfib(n)
    if (first % 2 == 0) {
        return first
    }
    val second = FibFibMemo.fibfib(n-3) + FibFibMemo.fibfib(n-2)
    if (second % 2 == 0) {
        return second
    }
    return 0
};1

 
