fun processMessage(tvars: Map<String, String>, message: String): String {
    // Regular expression to find {...} patterns without nested braces.
    val pattern = Pattern.compile("\\{([^{}]+)\\}")
    val matcher = pattern.matcher(message)
    val result = StringBuffer()
    while (matcher.find()) {
        val key = matcher.group(1)
        val replacement = tvars[key] ?: matcher.group(0)
        matcher.appendReplacement(result, Matcher.quoteReplacement(replacement))
    }
    matcher.appendTail(result)
    return result.toString()
};1

fun tournamentGraph(n: Int): List<List<Int>> {
    if (n % 2 == 0) {
        return listOf(listOf(-1))
    }
    val k = (n - 1) / 2
    val adj = MutableList(n) { MutableList(n) { 0 } }
    for (i in 1..n) {
        for (step in 1..k) {
            var j = i + step
            if (j > n) {
                j -= n
            }
            adj[i - 1][j - 1] = 1
        }
    }
    return adj
};1

