fun get_all_sets(hand: List<Array<String>>): List<List<Array<String>>> {
    return hand.combinations(3).filter { candidate ->
        val grouped_features = candidate.flatten().groupBy { it }
        grouped_features.values.none { v -> v.size == 2 }
    }
}
 
fun get_puzzle_and_answer(hand_size: Int, num_sets_goal: Int): Pair<List<Array<String>>, List<List<Array<String>>>> {
    var hand: List<Array<String>>
    var sets: List<List<Array<String>>>
    do {
        hand = DECK.shuffled().take(hand_size)
        sets = get_all_sets(hand)
    } while (sets.size!= num_sets_goal)
    return Pair(hand, sets)
}
 
