fun checkCoverAttributes(position: Int, tilt: Int): Pair<Int?, Int?> {
    // Validate position and tilt values for a cover.
    // position: Int (0–100 inclusive)
    // tilt: Int (0–90 inclusive)
    // Returns Pair(null, null) if out of range, else Pair(tilt, position)
    return if (position !in 0..100 || tilt !in 0..90) {
        Pair(null, null)
    } else {
        Pair(tilt, position)
    }
