import java.util.*
 
const val EL_COUNT = 77
const val LLEN = 11
 
class cocktailSort {
    fun sort(arr: IntArray, len: Int) {
        var notSorted = true
        while (notSorted) {
            notSorted = false
            for (a in 0 until len - 1) {
                if (arr[a] > arr[a + 1]) {
                    sSwap(arr, a, a + 1)
                    notSorted = true
                }
            }
 
            if (!notSorted) break
            notSorted = false
 
            for (a in len - 1 downTo 0) {
                if (arr[a - 1] > arr[a]) {
                    sSwap(arr, a, a - 1)
                    notSorted = true
                }
            }
        }
    }
 
    fun sSwap(arr: IntArray, a: Int, b: Int) {
        val t = arr[a]
        arr[a] = arr[b]
        arr[b] = t
    }
}
 
fun main(args: Array<String>) {
    val cs = cocktailSort()
    val arr = IntArray(EL_COUNT)
 
    for (x in 0 until EL_COUNT)
        arr[x] = Random().nextInt(EL_COUNT) + 1
 
    println("Original: ")
    println("==========")
    for (x in 0 until EL_COUNT step LLEN) {
        for (s in x until x + LLEN)
            print("${arr[s]}, ")
 
        println()
    }
 
    cs.sort(arr, EL_COUNT)
 
    println()
    println()
    println("Sorted: ")
    println("========")
    for (x in 0 until EL_COUNT step LLEN) {
        for (s in x until x + LLEN)
            print("${arr[s]}, ")
 
        println()
    }
};1

