fun uniq(seq: String): String {
    val seen = HashSet<Char>()
    val sb = StringBuilder()
    for (c in seq) {
        if (c!in seen) {
            seen.add(c)
            sb.append(c)
        }
    }
    return sb.toString()
}
 
fun partition(seq: String, n: Int): List<String> {
    val result = ArrayList<String>()
    for (i in 0..seq.length - 1 step n) {
        result.add(seq.substring(i, Math.min(i + n, seq.length)))
    }
    return result
}
 
fun playfair(key: String, from: Char = 'J', to: Char? = null): Pair<String, String> {
    val to = if (to == null) if (from == 'J') 'I' else null else to
 
    fun canonicalize(s: String): String {
        return s.toUpperCase().filter { it.isLetter() }.replace(from, to)
    }
 
    // Build 5x5 matrix.
    val m = partition(uniq(canonicalize(key + "ABCDEFGHIKLMNOPQRSTUVWXYZ")), 5)
 
    // Pregenerate all forward translations.
    val enc = HashMap<String, String>()
 
    // Map pairs in same row.
    for (row in m) {
        for (i in 0..4) {
            for (j in 0..4) {
                if (i!= j) {
                    enc[row[i] + row[j]] = row[(i + 1) % 5] + row[(j + 1) % 5]
                }
            }
        }
    }
 
    // Map pairs in same column.
    for (c in m.map { it.toList() }.transpose()) {
        for (i in 0..4) {
            for (j in 0..4) {
                if (i!= j) {
                    enc[c[i] + c[j]] = c[(i + 1) % 5] + c[(j + 1) % 5]
                }
            }
        }
    }
 
    // Map pairs with cross-connections.
    for (i1 in 0..4) {
        for (j1 in 0..4) {
            for (i2 in 0..4) {
                for (j2 in 0..4) {
                    if (i1!= i2 && j1!= j2) {
                        enc[m[i1][j1] + m[i2][j2]] = m[i1][j2] + m[i2][j1]
                    }
                }
            }
        }
    }
 
    // Generate reverse translations.
    val dec = enc.map { it.value to it.key }.toMap()
 
    fun sub_enc(txt: String): String {
        val lst = Pattern.compile("(.)(?:(?!\\1)(.))?").matcher(canonicalize(txt)).results().map { it.groupValues[1] + it.groupValues[2] }.toList()
        return lst.joinToString(" ") { enc[it]!! }
    }
 
    fun sub_dec(encoded: String): String {
        return partition(canonicalize(encoded), 2).joinToString(" ") { dec[it]!! }
    }
 
    return Pair(sub_enc, sub_dec)
}
 
