fun computeBridges(graph: Map<Int, List<Int>>): List<Pair<Int, Int>> {
    val n = graph.size
    val low = IntArray(n) { 0 }
    val visited = BooleanArray(n) { false }
    val bridges = mutableListOf<Pair<Int, Int>>()

    fun dfs(at: Int, parent: Int, id_: Int) {
        visited[at] = true
        low[at] = id_
        var currId = id_ + 1
        for (to in graph[at] ?: emptyList()) {
            if (to == parent) {
                continue
            }
            if (!visited[to]) {
                dfs(to, at, currId)
                low[at] = minOf(low[at], low[to])
                if (currId <= low[to]) {
                    bridges.add(if (at < to) Pair(at, to) else Pair(to, at))
                }
            } else {
                low[at] = minOf(low[at], low[to])
            }
        }
    }

    for (i in graph.keys) {
        if (!visited[i]) {
            dfs(i, -1, 0)
        }
    }
    return bridges
};1

fun sortAndCount(numbers: List<Int>): Pair<List<Int>, Map<Int, Int>> {
    // Create a sorted copy of the list
    val sortedList = numbers.sorted()

    // Count occurrences using groupingBy and eachCount
    val countsMap = numbers.groupingBy { it }.eachCount()

    return Pair(sortedList, countsMap)
