fun findAbbreviationsLength(commandTableText: String): Map<String, Int> {
    val commandTable = mutableMapOf<String, Int>()
    var word: String? = null
    var abbrLen: Int? = null
    for (token in commandTableText.split(" ")) {
        if (word == null) {
            word = token
        } else {
            abbrLen = token.toIntOrNull()
            if (abbrLen == null) {
                commandTable[word] = word!!.length
                word = token
            } else {
                commandTable[word] = abbrLen
                word = null
            }
        }
    }
    return commandTable
}
 
 
fun findAbbreviations(commandTable: Map<String, Int>): Map<String, String> {
    val abbreviations = mutableMapOf<String, String>()
    for ((command, minAbbrLen) in commandTable) {
        for (l in minAbbrLen..command.length) {
            val abbr = command.substring(0, l).toLowerCase()
            abbreviations[abbr] = command.toUpperCase()
        }
    }
    return abbreviations
}
 
 
fun parseUserString(userString: String, abbreviations: Map<String, String>): String {
    val userWords = userString.split(" ")
    val commands = userWords.map { abbreviations.getOrDefault(it.toLowerCase(), "*error*") }
    return commands.joinToString(" ")
}
 
 
