fun String.parsePackets(): ListPacket {
    val topLevel = ListPacket(mutableListOf(), null)
    var currentList = topLevel
    var stringBuffer = ""

    this.toCharArray().drop(1).dropLast(1).forEach { char ->
        when (char) {
            '[' -> {
                val newList = ListPacket(mutableListOf(), currentList)
                currentList.list.add(newList)
                currentList = newList
            }

            ']' -> {
                if (stringBuffer.isNotEmpty()) {
                    currentList.list.add(IntPacket(stringBuffer.toInt(), currentList))
                    stringBuffer = ""
                }

                currentList = currentList.parent ?: error("parent null")
            }

            ',' -> {
                if (stringBuffer.isNotEmpty()) {
                    currentList.list.add(IntPacket(stringBuffer.toInt(), currentList))
                    stringBuffer = ""
                }
            }

            else -> stringBuffer += char
        }
    }

    if (stringBuffer.isNotEmpty()) {
        currentList.list.add(IntPacket(stringBuffer.toInt(), currentList))
        stringBuffer = ""
    }

    return topLevel
};0

fun findLowestFuel(positions: List<Int>, calc : (List<Int>, Int) -> Int = ::calculateFuel) : Pair<Int, Int> {
    val positionsSorted = positions.sortedDescending()
    var min : Int = -1
    var minIndex : Int = -1
    for (i in 0..positionsSorted.first()) {
        var fuel = calc(positionsSorted, i)
        if (min == -1 || (fuel < min)) {
            min = fuel
            minIndex = i
        }
    }
    return Pair(min, minIndex)
};0

fun visibleFromLeft(tree: Int, i: Int, j: Int, grid: Array<Array<Int>>): Boolean {
    if (j == 0) return true

    var highest = -1
    for (jj in j - 1 downTo 0) {
        if (highest < grid[i][jj])
            highest = grid[i][jj]
    }
    return highest < tree
};0

