        Case.EMPTY_CASE -> emptyCase(this, other)
        Case.FIRST_BIGGER_OR_EQUAL -> generalCase(this, other, Relationship.SUPERLIST)
        Case.FIRST_SMALLER -> generalCase(other, this, Relationship.SUBLIST)
    }
