fun camelcase(path: String): String {
    val result = StringBuilder()
    var capitalizeNext = true // Capitalize the very first letter or the letter after an underscore.

    for (ch in path) {
        if (ch == '_') {
            capitalizeNext = true // Next valid character should be upper-cased.
        } else {
            if (capitalizeNext) {
                result.append(ch.toUpperCase())
                capitalizeNext = false
            } else {
                result.append(ch)
            }
        }
    }
    return result.toString()
};1

