fun teamScore(N: Int, scores: List<Int>): Int {
    val sortedScores = scores.sortedDescending()
    var ans = 0
    for (i in 0 until N) {
        if (sortedScores[i] >= i + 1) {
            ans = i + 1
        } else {
            break
        }
    }
    return ans
};1

fun firstActiveSensor(sensors: List<Int>): Int {
    // Return the 1-based index of the first active (value == 1) sensor.
    // If no sensor is active, return 0.
    for ((idx, state) in sensors.withIndex()) {
        if (state == 1) {
            return idx + 1
        }
    }
    return 0
};1

fun parseString(str: String): Triple<Int, Int, Sign> {
    val sign = when {
        str.startsWith("+") -> Sign.Positive
        str.startsWith("-") -> Sign.Negative
        else -> Sign.Positive
    }
    if ("." !in str) {
        return Triple(str.toInt(), 1, sign)
    }

    val numStr = str.replace(".", "")
    val numOfDecimalPlaces = str.substringAfter(".").length

    return Triple(numStr.toInt(), 10.pow(numOfDecimalPlaces), sign)
};0

