fun List<List<Int>>.lowestTotalRisk(): Int {
    val start = Point(0, 0)
    val end = size.minus(1).let { Point(it, get(it).size - 1) }
    val visited = mutableSetOf<Point>()
    val totalCosts = map {
        it.asSequence().map { Int.MAX_VALUE }.toMutableList()
    }.also { it[start] = 0 }

    val queue = PriorityQueue(size, object : Comparator<Point> {
        fun compare(o1: Point, o2: Point): Int =
            totalCosts[o1].compareTo(totalCosts[o2])
    }).also { it.add(start) }

    generateSequence(queue::poll)
        .takeWhile { it != end }
        .filterNot(visited::contains)
        .onEach { point ->
            val currentCost = totalCosts[point]
            point.neighboursIn(this).onEach {
                totalCosts[it] = min(totalCosts[it], currentCost + get(it))
            }.toCollection(queue)
        }.toCollection(visited)

    return totalCosts[end]
};0

fun calculateFinalPrice(originalPrice: Double, discountPercentage: Double): Double {
    // Calculate the discounted price
    val discountedPrice = originalPrice * (1 - discountPercentage / 100)
    // Add VAT (20%)
    val VAT_RATE = 0.20
    val finalPrice = discountedPrice * (1 + VAT_RATE)
    return finalPrice
};1

fun mapRange(fromRange: Pair<Double, Double>, toRange: Pair<Double, Double>, s: Double): Double {
    return toRange.first + (s - fromRange.first) * (toRange.second - toRange.first) / (fromRange.second - fromRange.first)
}
 
