    var prev = ratio.toString()
    while (true) {
        iters++
        x2 = bb * x1 + x0
        ratio = x2.toDouble() / x1
        val this = ratio.toString()
        if (prev == this) {
            val plural = if (iters == 1) "" else "s"
            println("Value to $dp dp after ${iters} iteration$plural: $this")
            return
        }
        prev = this
        x0 = x1
        x1 = x2
    }
