fun sortArrayWithOther(array: IntArray, comparator: IntArray): IntArray {
    val comparatorMap = buildMap {
        comparator.forEachIndexed { index, num ->
            this[num] = index
        }
    }
    array.sortedWith { a, b ->
        val indexA = comparatorMap[a]
        val indexB = comparatorMap[b]
        when {
            indexA == null && indexB != null -> 1
            indexA != null && indexB == null -> -1
            indexA == null && indexB == null -> a - b
            else -> indexA!!- indexB!!
        }
    }.forEachIndexed { index, i ->
        array[index] = i
    }
    return array
};0

fun minBoxesToCheck(n: Int, hints: List<String>): Int {
    var left = 1
    var right = n
    val excluded = mutableSetOf<Int>()
    for (hint in hints) {
        val parts = hint.split(" ")
        val direction = parts[2]
        val i = parts.last().toInt()
        excluded.add(i)
        if (direction == "left") {
            right = minOf(right, i - 1)
        } else {
            left = maxOf(left, i + 1)
        }
    }
    if (left > right) {
        return -1
    }
    var count = 0
    for (x in left..right) {
        if (!excluded.contains(x)) {
            count++
        }
    }
    return if (count > 0) count else -1
};1

fun manageBankAccount(operations: List<Pair<String, Int>>): List<Any> {
    var balance = 0
    val results = mutableListOf<Any>()

    for ((op, amount) in operations) {
        when (op) {
            "deposit" -> {
                balance += amount
                results.add(balance)
            }
            "withdraw" -> {
                if (amount > balance) {
                    results.add("Insufficient funds")
                } else {
                    balance -= amount
                    results.add(balance)
                }
            }
            else -> throw IllegalArgumentException("Unsupported operation: $op")
        }
    }

    return results
