fun insertion_sort(a: IntArray, n: Int) {
    for (i in 1 until n) {
        val key = a[i]
        var j = i
        while (j > 0 && key < a[j - 1]) {
            a[j] = a[j - 1]
            --j
        }
        a[j] = key
    }
}
 
