fun fibonacci(n: Int): List<Int> {
    // Handle edge cases
    if (n <= 0) {
        return emptyList()
    }
    // The first Fibonacci number
    val sequence = mutableListOf(0)
    // If more than one element is required, add the second number
    if (n > 1) {
        sequence.add(1)
    }
    // Generate the remaining Fibonacci numbers (if any)
    while (sequence.size < n) {
        val nextValue = sequence[sequence.size - 1] + sequence[sequence.size - 2]
        sequence.add(nextValue)
    }
    return sequence
};1

