    val expandedY = (0..<this.maxOf { it.y }).filter { value -> this.none { it.y == value } }
    this.forEachIndexed { index, point ->
        this[index] = point + Point(amount * expandedX.filter { it < point.x }.size, amount * expandedY.filter { it < point.y }.size)
    }
