fun removeDuplicateElements(items: List<Any>, key: ((Any) -> Any)? = null): List<Any> {
    // Select the key function
    val keyFunc = key ?: { x: Any -> x }

    val seenHashable = mutableSetOf<Any?>()   // Tracks hashable keys we've encountered
    val seenLinear   = mutableListOf<Any?>()  // Tracks non-hashable keys (kept in a list)
    val result       = mutableListOf<Any>()

    for (item in items) {
        val k = keyFunc(item)
        var isHashable = true
        var alreadySeen = false
        try {
            // Try hashable path
            alreadySeen = seenHashable.contains(k)
        } catch (e: Exception) {
            isHashable = false
        }
        if (isHashable) {
            if (alreadySeen) {
                continue
            }
            seenHashable.add(k)
        } else {
            // Fallback to linear search for non-hashables
            if (seenLinear.any { it == k }) {
                continue
            }
            seenLinear.add(k)
        }
        // If we get here, it’s the first occurrence
        result.add(item)
    }
    return result
};1

