fun straddle(s: String): String {
    return s.toUpperCase().map { c -> T[0][T.indexOfFirst { it.contains(c) }].plus(T[0][T.indexOfFirst { it.contains(c) }]) }.joinToString("")
}
 
fun unstraddle(s: String): String {
    return s.map { c ->
        if (c in arrayOf(T[2][0], T[3][0])) {
            val i = arrayOf(T[2][0], T[3][0]).indexOf(c)
            val n = T[2 + i][T[0].indexOf(s[1])]
            if (n == "/") s[2] else n
        } else {
            T[1][T[0].indexOf(c)]
        }
    }.joinToString("")
}
 
