import kotlin.collections.*
import kotlin.math.*
 
fun main(args: Array<String>) {
    //const max = 100
    // Use 1685 (the highest with a unique answer) instead
    // of 100 just to make it work a little harder :).
    val max = 1685
    var all = ArrayList<Pair<Int, Int>>()
    for (a in 2 until max) {
        for (b in a + 1 until max - a) {
            all.add(Pair(a, b))
        }
    }
    println("There are ${all.size} pairs where a+b < $max (and a<b)")
    val products = countProducts(all)
 
    // Those for which no sum decomposition has unique product to are
    // S mathimatician's possible pairs.
    var sPairs = ArrayList<Pair<Int, Int>>()
    pairs@ for (p in all) {
        val s = p.first + p.second
        // foreach a+b=s (a<b)
        for (a in 2 until s / 2 + s % 2) {
            val b = s - a
            if (products[a * b] == 1) {
                // Excluded because P would have a unique product
                continue@pairs
            }
        }
        sPairs.add(p)
    }
    println("S starts with ${sPairs.size} possible pairs.")
    //fmt.Println("S pairs:", sPairs)
    val sProducts = countProducts(sPairs)
 
    // Look in sPairs for those with a unique product to get
    // P mathimatician's possible pairs.
    var pPairs = ArrayList<Pair<Int, Int>>()
    for (p in sPairs) {
        if (sProducts[p.first * p.second] == 1) {
            pPairs.add(p)
        }
    }
    println("P then has ${pPairs.size} possible pairs.")
    //fmt.Println("P pairs:", pPairs)
    val pSums = countSums(pPairs)
 
    // Finally, look in pPairs for those with a unique sum
    var final = ArrayList<Pair<Int, Int>>()
    for (p in pPairs) {
        if (pSums[p.first + p.second] == 1) {
            final.add(p)
        }
    }
 
    // Nicely show any answers.
    when (final.size) {
        1 -> println("Answer: ${final[0].first} and ${final[0].second}")
        0 -> println("No possible answer.")
        else -> println("${final.size} possible answers: $final")
    }
}
 
fun countProducts(list: ArrayList<Pair<Int, Int>>): HashMap<Int, Int> {
    val m = HashMap<Int, Int>()
    for (p in list) {
        m[p.first * p.second] = m.getOrDefault(p.first * p.second, 0) + 1
    }
    return m
}
 
fun countSums(list: ArrayList<Pair<Int, Int>>): HashMap<Int, Int> {
    val m = HashMap<Int, Int>()
    for (p in list) {
        m[p.first + p.second] = m.getOrDefault(p.first + p.second, 0) + 1
    }
    return m
}
 
