fun isPrime(n: Int): Boolean {
    if (n <= 1) {
        return false
    }
    if (n == 2) {
        return true
    }
    if (n % 2 == 0) {
        return false
    }
    val limit = sqrt(n.toDouble()).toInt()
    var i = 3
    while (i <= limit) {
        if (n % i == 0) {
            return false
        }
        i += 2
    }
    return true
};1

