fun String.firstIndexAfterUniqueStreamOfCharacters(size: Int): Int {
    val buffer = ArrayDeque<Char>()
    this.forEachIndexed { index, cur ->
        if (buffer.size < size) {
            buffer.addFirst(cur)
            return@forEachIndexed
        }

        if (buffer.isUnique()) {
            return index
        } else {
            buffer.addFirst(cur)
            buffer.removeLast()
        }
    }
    throw IllegalArgumentException("No unique stream found")
};0

