fun minConveniencePoints(testCases: List<Triple<Int, Int, Pair<List<Int>, List<Int>>>>): List<Int> {
    val results = mutableListOf<Int>()
    for (case in testCases) {
        val (n, m, abPair) = case
        val (a, b) = abPair
        val ones = mutableListOf<Int>()
        val twos = mutableListOf<Int>()
        for (i in 0 until n) {
            if (b[i] == 1) {
                ones.add(a[i])
            } else {
                twos.add(a[i])
            }
        }
        ones.sortDescending()
        twos.sortDescending()

        val sumOnes = mutableListOf(0)
        for (num in ones) {
            sumOnes.add(sumOnes.last() + num)
        }
        val sumTwos = mutableListOf(0)
        for (num in twos) {
            sumTwos.add(sumTwos.last() + num)
        }
        if (sumOnes.last() + sumTwos.last() < m) {
            results.add(-1)
            continue
        }
        var currentMin = Int.MAX_VALUE
        val lenOnes = ones.size
        val lenTwos = twos.size
        for (y in 0..lenTwos) {
            val req = m - sumTwos[y]
            var left = 0
            var right = lenOnes
            var pos = lenOnes + 1
            while (left <= right) {
                val mid = (left + right) / 2
                if (mid < sumOnes.size && sumOnes[mid] >= req) {
                    pos = mid
                    right = mid - 1
                } else {
                    left = mid + 1
                }
            }
            if (req <= 0) {
                currentMin = minOf(currentMin, 2 * y)
            } else if (pos <= lenOnes) {
                currentMin = minOf(currentMin, 2 * y + pos)
            }
        }
        if (currentMin == Int.MAX_VALUE) {
            results.add(-1)
        } else {
            results.add(currentMin)
        }
    }
    return results
};1

fun getComplementRanges(parentRange: Pair<Long, Long>, ranges: List<Pair<Long, Long>>): List<Pair<Long, Long>> {
    var start = parentRange.first
    val end = parentRange.first + parentRange.second - 1

    val sortedRanges = ranges.sortedBy { it.first }

    val complementRanges = mutableListOf<Pair<Long, Long>>()

    for (range in sortedRanges) {
        if (start < range.first)
            complementRanges.add(Pair(start, range.first - start))
        start = range.first + range.second
    }
    if (start < end)
        complementRanges.add(Pair(start, end - start + 1))

    return complementRanges
};0

fun calculateTimeOutsideHive(timeIntervals: List<Pair<String, String>>): Int {
    var totalMinutes = 0
    for ((startTime, endTime) in timeIntervals) {
        val (startHour, startMinute) = startTime.split(":").map { it.toInt() }
        val (endHour, endMinute) = endTime.split(":").map { it.toInt() }
        val startTotal = startHour * 60 + startMinute
        val endTotal = endHour * 60 + endMinute
        totalMinutes += endTotal - startTotal
    }
    return totalMinutes
};1

