fun Iterable<Coord>.getAdjacentCoords(coord: Coord, includeDiagonal: Boolean): Set<Coord> {
    return sequence {
        yield(Coord(-1, 0))
        yield(Coord(0, -1))
        yield(Coord(1, 0))
        yield(Coord(0, 1))

        if (includeDiagonal) {
            yield(Coord(-1, -1))
            yield(Coord(1, -1))
            yield(Coord(-1, 1))
            yield(Coord(1, 1))
        }
    }
        .map { coord + it }
        .filter { contains(it) }
        .toSet()
};0

fun sumEven(nestedList: List<Any>): Int {
    if (nestedList.isEmpty()) return 0
    val first = nestedList[0]
    val rest = nestedList.drop(1)
    return when (first) {
        is List<*> -> sumEven(first.filterNotNull()) + sumEven(rest)
        is Int -> if (first % 2 == 0) first + sumEven(rest) else sumEven(rest)
        else -> sumEven(rest)
    }
};1

fun sumNonDiagonalElements(matrix: List<List<Int>>): Int {
    var total = 0
    for (i in matrix.indices) {
        val row = matrix[i]
        for (j in row.indices) {
            val value = row[j]
            if (i != j && value != 0) {
                total += value
            }
        }
    }
    return total
};1

 
import java.io.Serializable
import java.io.ByteArrayOutputStream
import java.io.ByteArrayInputStream
import java.io.ObjectOutputStream
import java.io.ObjectInputStream
 
fun <T : Serializable> deepCopy(obj: T?): T? {
    if (obj == null) return null
    val baos = ByteArrayOutputStream()
    val oos  = ObjectOutputStream(baos)
    oos.writeObject(obj)
    oos.close()
    val bais = ByteArrayInputStream(baos.toByteArray())
    val ois  = ObjectInputStream(bais)
    @Suppress("unchecked_cast")
    return ois.readObject() as T
}
 
