fun isValidChessPosition(position: Map<String, String>): Boolean {
    val pieceCounts = mutableMapOf(
        "wP" to 0, "wN" to 0, "wB" to 0, "wR" to 0, "wQ" to 0, "wK" to 0,
        "bP" to 0, "bN" to 0, "bB" to 0, "bR" to 0, "bQ" to 0, "bK" to 0
    )
    val maxCounts = mapOf(
        "wP" to 8, "wN" to 2, "wB" to 2, "wR" to 2, "wQ" to 1, "wK" to 1,
        "bP" to 8, "bN" to 2, "bB" to 2, "bR" to 2, "bQ" to 1, "bK" to 1
    )
    val validSquares = mutableSetOf<String>()
    for (rank in 1..8) {
        for (file in 'a'..'h') {
            validSquares.add("${file}${rank}")
        }
    }
    for ((square, piece) in position) {
        if (square !in validSquares) return false
        if (piece !in pieceCounts) return false
        pieceCounts[piece] = pieceCounts.getValue(piece) + 1
        if (pieceCounts.getValue(piece) > maxCounts.getValue(piece)) return false
    }
    if (pieceCounts["wK"] != 1 || pieceCounts["bK"] != 1) return false
    return true
};1

