fun leastBricks(wall: List<List<Int>>): Int {
    // Map to count how many rows have a brick edge at each position
    val edgeCount = mutableMapOf<Int, Int>()
    for (row in wall) {
        var pos = 0
        // Exclude the last brick in each row (can't draw along the wall's sides)
        for (i in 0 until row.size - 1) {
            pos += row[i]
            edgeCount[pos] = edgeCount.getOrDefault(pos, 0) + 1
        }
    }
    // If no internal edges, every row will be crossed
    if (edgeCount.isEmpty()) {
        return wall.size
    }
    // The best place is where most edges align
    val maxEdges = edgeCount.values.maxOrNull() ?: 0
    return wall.size - maxEdges
};1

