data class P(val x: Int, val y: Int, val sum: Int, val prod: Int)
 
fun main(args: Array<String>) {
    val candidates = mutableListOf<P>()
    for (x in 2..49) {
        for (y in x + 1..100 - x) {
            candidates.add(P(x, y, x + y, x * y))
        }
    }
 
    val sums = candidates.groupBy { it.sum }
    val prods = candidates.groupBy { it.prod }
 
    val fact1 = candidates.filter { sums[it.sum]!!.all { prods[it.prod]!!.size > 1 } }
    val fact2 = fact1.filter { prods[it.prod]!!.intersect(fact1).size == 1 }
    val fact3 = fact2.filter { sums[it.sum]!!.intersect(fact2).size == 1 }
    print("The only solution is : ")
    for ((x, y, _, _) in fact3) println("x = $x, y = $y")
};0

fun enumeratePaths(connections: Collection<Connection>, canVisitFunction: (Path, Room) -> Boolean): List<Path> {
    val result = mutableListOf<Path>()
    val pathsToVisit: Deque<Path> = LinkedList()
    pathsToVisit.addFirst(Path(Room.START))

    while (!pathsToVisit.isEmpty()) {
        val pathToVisit = pathsToVisit.removeFirst()

        val endPoint = pathToVisit.last()
        if (endPoint == Room.END) {
            result.add(pathToVisit)
        } else {
            connections.asSequence()
                .filter { it.from == endPoint }
                .filter { canVisitFunction(pathToVisit, it.to) }
                .forEach {
                    val newPath = pathToVisit.add(it.to)
                    pathsToVisit.addFirst(newPath)
                }
        }
    }

    return result
};0

fun maxProfit2(prices: IntArray): Int {
    /**
     *  [7, 1, 5, 3, 6, 4]
     * We first assign the minprice a very large value
     * */
    var minprice = Int.MAX_VALUE // very large value
    var maxprofit = 0
    for (i in prices.indices) {
        /**
         * At this point we check if the current price[i] is less than the min price
         * to keep track of the lowest value on the graph as we go......
         * */
        if (prices[i] < minprice)
        {
            minprice = prices[i] // | 7 || 1 |||  1 |||| 1
        }
        /**
         * We then keep track of the largest value on the graph in the same loop
         * to keep track of the maximum profit that could be attained on the graph above
         * as we proceed
         *
         *
         * */
        else if (prices[i] - minprice > maxprofit)
        {
            maxprofit = prices[i] - minprice // ||| 4 |||| 4 ||||| 5
        }
    }
    return maxprofit
};0

