fun Long.toSNAFU(): String {
    if (this == 0L) return ""

    val mod = this % 5
    val (carry, n) = if (mod > 2) 1 to mod - 5L else 0 to mod
    val digit = when (n) {
        -2L -> "="
        -1L -> "-"
        else -> n.toString()
    }
    return (this / 5 + carry).toSNAFU() + digit
};0

