import java.util.Random
 
class Field(val w: Int, val h: Int) {
    val s = Array(h) { BooleanArray(w) }
 
    fun set(x: Int, y: Int, b: Boolean) {
        s[y][x] = b
    }
 
    fun next(x: Int, y: Int): Boolean {
        var on = 0
        for (i in -1..1) {
            for (j in -1..1) {
                if (state(x + i, y + j) &&!(j == 0 && i == 0)) {
                    on++
                }
            }
        }
        return on == 3 || on == 2 && state(x, y)
    }
 
    fun state(x: Int, y: Int): Boolean {
        var y = y
        var x = x
        while (y < 0) {
            y += h
        }
        while (x < 0) {
            x += w
        }
        return s[y % h][x % w]
    }
}
 
class Life(w: Int, h: Int) {
    val a = Field(w, h)
    val b = Field(w, h)
    val w = w
    val h = h
 
    init {
        val random = Random()
        for (i in 0..(w * h / 2)) {
            a.set(random.nextInt(w), random.nextInt(h), true)
        }
    }
 
    fun step() {
        for (y in 0..h) {
            for (x in 0..w) {
                b.set(x, y, a.next(x, y))
            }
        }
        val tmp = a
        a = b
        b = tmp
    }
 
    fun toString(): String {
        val buf = StringBuilder()
        for (y in 0..h) {
            for (x in 0..w) {
                var b =''
                if (a.state(x, y)) {
                    b = '*'
                }
                buf.append(b)
            }
            buf.append('\n')
        }
        return buf.toString()
    }
}
 
fun main(args: Array<String>) {
    val l = Life(80, 15)
    for (i in 0..300) {
        l.step()
        println(l)
    }
};1

 
