import kotlin.math.*
 
typealias Ifctn = (Double) -> Double
 
fun Simpson3_8(f: Ifctn, a: Double, b: Double, N: Int): Double {
    var j = 0
    var l1 = 0.0
    val h = (b - a) / N
    val h1 = h / 3.0
    var sum = f(a) + f(b)
 
    for (j in 3 * N - 1 downTo 0) {
        l1 = if (j % 3!= 0) 3.0 else 2.0
        sum += l1 * f(a + h1 * j)
    }
    return h * sum / 8.0
}
 
fun Gamma_Spouge(z: Double): Double {
    var k = 0
    val cspace = DoubleArray(A)
    var coefs: DoubleArray? = null
    var accum = 0.0
    val a = A
 
    if (coefs == null) {
        var k1_factrl = 1.0
        coefs = cspace
        coefs[0] = sqrt(2.0 * PI)
        for (k in 1 until A) {
            coefs[k] = exp(a - k) * pow(a - k, k - 0.5) / k1_factrl
            k1_factrl *= -k
        }
    }
 
    accum = coefs[0]
    for (k in 1 until A) {
        accum += coefs[k] / (z + k)
    }
    accum *= exp(-(z + a)) * pow(z + a, z + 0.5)
    return accum / z
}
 
var aa1 = 0.0
fun f0(t: Double): Double {
    return pow(t, aa1) * exp(-t)
}
 
fun GammaIncomplete_Q(a: Double, x: Double): Double {
    var y = 0.0
    val h = 1.5e-2 // approximate integration step size
 
    // this cuts off the tail of the integration to speed things up
    y = aa1 = a - 1
    while ((f0(y) * (x - y) > 2.0e-8) && (y < x)) y +=.4
    if (y > x) y = x
 
    return 1.0 - Simpson3_8(f0, 0.0, y, (y / h).toInt()) / Gamma_Spouge(a)
};1

