import java.io.InputStream
import java.io.PrintStream
import java.util.Scanner
import java.util.Stack
 
enum class Direction {
    LEFT, UP, RIGHT, DOWN
}
 
fun main(args: Array<String>) {
    val dataLength = 100
    val progString = """
       /==!/======ECHO==,==.==#
       |   |
$==>==@/==@/==<==#"""
 
    val stack = Stack<Triple<Int, Int, Direction>>()
    val data = IntArray(dataLength)
    var dp = 0
    var ipx = 0
    var ipy = 0
    var direction = Direction.RIGHT
 
    val lines = progString.split("\n")
    val lmax = lines.map { it.length }.max()!!
    val lines2 = lines.map { it.padEnd(lmax) }
    for ((y, li) in lines2.withIndex()) {
        if (li.indexOf("\$")!= -1) {
            ipx = li.indexOf("\$")
            ipy = y
        }
    }
 
    val instruction = mapOf(
        '>' to { dp += 1 },
        '<' to { dp -= 1; if (dp < 0) running = false },
        '+' to { data[dp] += 1 },
        '-' to { data[dp] -= 1 },
        ',' to { data[dp] = System.`in`.read() },
        '.' to { System.out.print(data[dp].toChar()) },
        '/' to {
            var d = direction.ordinal
            d += if (d % 2 == 0) 3 else 5
            direction = Direction.values()[d % 4]
        },
        '\\' to {
            var d = direction.ordinal
            d += if (d % 2 == 0) 1 else -1
            direction = Direction.values()[d]
        },
        '!' to { ipnext() },
        '?' to { if (data[dp] == 0) ipnext() },
        '@' to { stack.push(Triple(ipx, ipy, direction)) },
        '#' to { if (stack.size > 0) { val (x, y, d) = stack.pop(); ipx = x; ipy = y; direction = d } },
        '\n' to { running = false }
    )
 
    fun inboundsx(plus: Boolean) = if (plus) ipx < lmax else ipx > 1
    fun inboundsy(plus: Boolean) = if (plus) ipy < lines2.size else ipy > 1
    fun ipnext() {
        if (direction == Direction.RIGHT && inboundsx(true)) ipx += 1
        else if (direction == Direction.LEFT && inboundsx(false)) ipx -= 1
        else if (direction == Direction.DOWN && inboundsy(true)) ipy += 1
        else if (direction == Direction.UP && inboundsy(false)) ipy -= 1
    }
 
    var running = true
    while (running) {
        val cmdCode = lines2[ipy][ipx]
        if (instruction.containsKey(cmdCode)) {
            instruction[cmdCode]!!()
        }
        ipnext()
    }
    System.exit(data[dp])
};1

import java.math.BigInteger
 
fun bernoulli(n: Int): BigInteger {
    val A = Array(n + 1) { BigInteger.ZERO }
    for (m in 0..n) {
        A[m] = BigInteger.ONE.divide(BigInteger.valueOf(m + 1))
        for (j in m downTo 1) {
            A[j - 1] = BigInteger.valueOf(j).multiply(A[j - 1].subtract(A[j]))
        }
    }
    return A[0]
}
 
