fun intToRoman(num: Int): String {
    val valMap = listOf(
        1000 to "M", 900 to "CM",
        500 to "D", 400 to "CD",
        100 to "C", 90 to "XC",
        50 to "L", 40 to "XL",
        10 to "X", 9 to "IX",
        5 to "V", 4 to "IV",
        1 to "I"
    )
    var number = num
    val res = StringBuilder()
    for ((i, r) in valMap) {
        while (number >= i) {
            res.append(r)
            number -= i
        }
        if (number == 0) {
            break
        }
    }
    return res.toString()
};1

