/**
 * Questions 56-2: Find a number in an IntArray that only appear once, all other numbers appear thirds
 */
fun IntArray.findNumberAppearOnce(): Int {
    require(isNotEmpty()) { "The IntArray is illegal" }
    val bitsSum = IntArray(32)
    forEach { num ->
        var bitMusk = 1
        for (j in 31 downTo 0) {
            val bit = num and bitMusk
            if (bit != 0)
                bitsSum[j]++
            bitMusk = bitMusk shl 1
        }
    }

    var result = 0
    repeat(32) {
        result = result shl 1
        result += bitsSum[it] % 3
    }
    return result
};0

const val MOD = 1000000007

fun cannibalisticAnts(testCases: List<Int>): List<List<Int>> {
    fun modPow(base: Long, exp: Long, mod: Long): Long {
        var result = 1L
        var b = base % mod
        var e = exp
        while (e > 0) {
            if (e and 1L == 1L) {
                result = (result * b) % mod
            }
            b = (b * b) % mod
            e = e shr 1
        }
        return result
    }
    val inv2 = modPow(2L, (MOD - 2).toLong(), MOD.toLong()).toInt()
    val inv4 = modPow(4L, (MOD - 2).toLong(), MOD.toLong()).toInt()
    val results = mutableListOf<List<Int>>()
    for (n in testCases) {
        if (n == 1) {
            results.add(listOf(1))
        } else if (n == 2) {
            results.add(listOf(0, 1))
        } else {
            val res = mutableListOf<Int>()
            for (i in 1..n) {
                if (i == 1) {
                    res.add(0)
                } else {
                    if (n % 2 == 0 && i == n) {
                        res.add(inv2)
                    } else {
                        res.add(inv4)
                    }
                }
            }
            results.add(res)
        }
    }
    return results
};1

