class GenFibonacci(val buf: List<Long>, var sum: Long, var idx: Int) : Iterator<Long> {
    fun hasNext(): Boolean {
        return true
    }
 
    fun next(): Long {
        val result = sum
        sum -= buf[idx]
        buf[idx] += sum
        sum += buf[idx]
        idx = (idx + 1) % buf.size
        return result
    }
}
 
fun print(buf: List<Long>, len: Int) {
    var sum = 0L
    for (elt in buf) {
        sum += elt
        print("\t$elt")
    }
    val iter = GenFibonacci(buf, sum, 0)
    for (x in iter.take(len)) {
        print("\t$x")
    }
}
 
