import java.util.ArrayList
import java.util.List
 
fun ludicUpTo(n: Int): List<Int> {
    val ludics = ArrayList<Int>(n)
    for (i in 1..n) { //fill the initial list
        ludics.add(i)
    }
 
    //start at index 1 because the first ludic number is 1 and we don't remove anything for it
    for (cursor in 1 until ludics.size) {
        val thisLudic = ludics[cursor] //the first item in the list is a ludic number
        var removeCursor = cursor + thisLudic //start removing that many items later
        while (removeCursor < ludics.size) {
            ludics.removeAt(removeCursor) //remove the next item
            removeCursor = removeCursor + thisLudic - 1 //move the removal cursor up as many spaces as we need to
            //then back one to make up for the item we just removed
        }
    }
    return ludics
}
 
fun getTriplets(ludics: List<Int>): List<List<Int>> {
    val triplets = ArrayList<List<Int>>()
    for (i in 0 until ludics.size - 2) { //only need to check up to the third to last item
        val thisLudic = ludics[i]
        if (ludics.contains(thisLudic + 2) && ludics.contains(thisLudic + 6)) {
            val triplet = ArrayList<Int>(3)
            triplet.add(thisLudic)
            triplet.add(thisLudic + 2)
            triplet.add(thisLudic + 6)
            triplets.add(triplet)
        }
    }
    return triplets
}
 
