fun validateQuotedStringList(inputString: String): Boolean {
    val s = inputString
    val n = s.length

    fun skipWs(idx: Int): Int {
        var i = idx
        while (i < n && s[i].isWhitespace()) {
            i++
        }
        return i
    }

    var i = skipWs(0)
    if (i == n) {
        return false
    }

    while (true) {
        // 1) Expect a quoted item
        if (i >= n || (s[i] != '\'' && s[i] != '"')) {
            return false
        }
        val quote = s[i]
        i += 1

        while (i < n) {
            val ch = s[i]
            if (ch == '\\') {
                i += 2
                continue
            }
            if (ch == quote) {
                i += 1
                break
            }
            i += 1
        }
        if (i > n || (i > 0 && s.getOrNull(i-1) != quote)) {
            // Ran off the end, no closing quote
            return false
        }

        i = skipWs(i)

        if (i == n) {
            return true
        }
        if (s[i] != ',') {
            return false
        }
        i += 1
        i = skipWs(i)

        if (i == n) {
            return false
        }
    }
};1

fun convertMatrixToList(matrix: List<List<Int>>): Map<Int, List<Pair<Int, Int>>> {
    val adjacencyList = mutableMapOf<Int, MutableList<Pair<Int, Int>>>()
    val n = matrix.size
    if (n == 0) {
        return adjacencyList
    }
    // Ensure the matrix is square
    for (row in matrix) {
        if (row.size != n) {
            throw IllegalArgumentException("Input must be a square adjacency matrix.")
        }
    }
    for (i in 0 until n) {
        val neighbors = mutableListOf<Pair<Int, Int>>()
        for ((j, weight) in matrix[i].withIndex()) {
            if (weight != 0) {
                neighbors.add(Pair(j, weight))
            }
        }
        adjacencyList[i] = neighbors
    }
    return adjacencyList
};1

