enum class Associativity {
    /** a / b / c = (a / b) / c */
    left,
    /** a ^ b ^ c = a ^ (b ^ c) */
    right,
    /** a + b + c = (a + b) + c = a + (b + c) */
    both
}

val operators = mapOf(
    '+' to Operator(2, Associativity.both),
    '-' to Operator(2, Associativity.left),
    '*' to Operator(3, Associativity.both),
    '/' to Operator(3, Associativity.left),
    '^' to Operator(4, Associativity.right)
)

data class Operator(val precedence: Int, val associativity: Associativity)

class NumberNode(val text: String) {
    fun toString(): String = text
}

class InfixNode(val fnname: String, val operands: List<Node>) {
    fun toString(parentPrecedence: Int): String {
        val op = operators[fnname]?: throw Error("invalid operator")
        val leftAdd = if (op.associativity == Associativity.right) 0.01 else 0.0
        val rightAdd = if (op.associativity == Associativity.left) 0.01 else 0.0
        if (operands.size!= 2) throw Error("invalid operand count")
        val result = "${operands[0].toString(op.precedence + leftAdd)} $fnname ${operands[1].toString(op.precedence + rightAdd)}"
        return if (parentPrecedence > op.precedence) "( $result )" else result
    }
}

fun rpnToTree(tokens: String): Node {
    val stack = mutableListOf<Node>()
    println("input = $tokens")
    for (token in tokens.split(" ")) {
        if (token in operators) {
            val op = operators[token]?: throw Error("invalid operator")
            val arity = 2 // all of these operators take 2 arguments
            if (stack.size < arity) throw Error("stack error")
            stack.add(InfixNode(token, stack.subList(stack.size - arity, stack.size)))
        } else {
            stack.add(NumberNode(token))
        }
        println("read $token, stack = [${stack.joinToString(", ")}]")
    }
    if (stack.size!= 1) throw Error("stack error")
    return stack[0]
}

