class Pixmap(val width: Int, val height: Int) {
    private val pixels = Array(width * height) { RGBColour(0, 0, 0) }

    operator fun get(x: Int, y: Int): RGBColour = pixels[x + y * width]
    operator fun set(x: Int, y: Int, value: RGBColour) {
        pixels[x + y * width] = value
    }

    fun toGrayscale(): Pixmap {
        val gray = Pixmap(width, height)
        for (x in 0 until width) {
