    //     Boolean? :
    //         - true  -> if value represents "true"  (case-insensitive)
    //         - false -> if value represents "false" (case-insensitive)
    //         - null  -> for any other input
    if (value == null) {
        return null
    }
    val normalized = value.trim().lowercase()
