fun State.simulateRound() {
    val proposalsByTarget = positions.groupBy { currPos ->
        val neighbours = currPos.neighboursIncludingDiagonals()
        when {
            neighbours.none { it in positions } -> null
            else -> strategies
                .asSequence()
                .mapNotNull { it(neighbours, positions) }
                .firstOrNull()
        }
    }
    isMoving = false
    positions = buildSet {
        for ((target, sources) in proposalsByTarget) {
            when  {
                sources.size > 1 || target == null -> addAll(sources)
                else -> {
                    add(target)
                    isMoving = true
                }
            }
        }
    }
    strategies += strategies.removeFirst()
};0

fun combination(n: Int, m: Int): ULong {
    if (m == 0 || m == n) return 1u
    if (m == 1) return n.toULong()
    if (memo.containsKey(Pair(n, m))) {
        return memo[Pair(n, m)]!!
    }
    val result = combination(n - 1, m - 1) + combination(n - 1, m)
    memo[Pair(n, m)] = result
    return result
};0

 
fun meanAngle(angles: DoubleArray): Double {
    val sinSum = angles.sumByDouble {  Math.sin(it * Math.PI / 180.0) }
    val cosSum = angles.sumByDouble {  Math.cos(it * Math.PI / 180.0) }
    return Math.atan2(sinSum / angles.size, cosSum / angles.size) * 180.0 / Math.PI
}
 
