fun rightrect(f: (Double) -> Double, left: Double, right: Double): Double {
    return f(right)
}
 
fun trapezium(f: (Double) -> Double, left: Double, right: Double): Double {
    return (f(left) + f(right)) / 2.0
}
 
fun simpson(f: (Double) -> Double, left: Double, right: Double): Double {
    return (f(left) + 4 * f((left + right) / 2.0) + f(right)) / 6.0
}
 
fun integrate(f: (Double) -> Double, a: Double, b: Double, steps: Int, method: (Double, Double, Double) -> Double): Double {
    val delta = 1.0 * (b - a) / steps
    var total = 0.0
    for (i in 0 until steps) {
        val left = a + i * delta
        val right = left + delta
        total += delta * method(f, left, right)
    }
    return total
}
 
