fun def_int(f: (Double) -> Double, a: Double, b: Double): Double {
    val l = when (f) {
        Math::sin -> { x: Double -> -Math.cos(x) }
        else -> { x: Double -> x * x * x / 3.0 }
    }
    return l(b) - l(a)
}
 
