fun strandSort(arr: MutableList<Int>, reverse: Boolean = false, solution: MutableList<Int>? = null): List<Int> {
    val comparator: (Int, Int) -> Boolean = if (reverse) { { a, b -> a > b } } else { { a, b -> a < b } }
    val res = solution ?: mutableListOf()
    if (arr.isEmpty()) return res

    val sublist = mutableListOf(arr.removeAt(0))
    var i = 0
    while (i < arr.size) {
        val item = arr[i]
        if (comparator(item, sublist.last())) {
            sublist.add(item)
            arr.removeAt(i)
        } else {
            i++
        }
    }

    if (res.isEmpty()) {
        res.addAll(sublist)
    } else {
        while (sublist.isNotEmpty()) {
            val item = sublist.removeAt(0)
            var inserted = false
            for ((j, v) in res.withIndex()) {
                if (!comparator(item, v)) {
                    res.add(j, item)
                    inserted = true
                    break
                }
            }
            if (!inserted) {
                res.add(item)
            }
        }
    }

    strandSort(arr, reverse, res)
    return res
};1

