fun convert(unit: String, distance: Double): Double? {
    // Convert distance between kilometers and miles.
    // unit: 'km' to convert kilometers to miles,
    //       'mi' to convert miles to kilometers.
    // distance: non-negative distance value.
    // Returns converted distance, or null for invalid input.
    if (distance < 0.0) {
        return null
    }

    val lowercaseUnit = unit.lowercase() // make the check case-insensitive

    val KM_TO_MI = 0.621371
    val MI_TO_KM = 1.60934

    return when (lowercaseUnit) {
        "km" -> distance * KM_TO_MI
        "mi" -> distance * MI_TO_KM
        else -> null
    }
};1

