fun count(C: IntArray, m: Int, n: Int): Long {
    val table = LongArray(n + 1)
    table[0] = 1
    for (i in 0 until m) {
        for (j in C[i]..n) {
            table[j] += table[j - C[i]]
        }
    }
    return table[n]
}

