data class Quadruple<A, B, C, D>(val first: A, val second: B, val third: C, val fourth: D)

fun rgbToCmyk(rInput: Int, gInput: Int, bInput: Int): Quadruple<Int, Int, Int, Int> {
    // In Kotlin, types are checked at compile-time, but to stay faithful to the error handling,
    // check that inputs are Int. This is implicit, unless callers use Java reflection.
    if (
        rInput !is Int || gInput !is Int || bInput !is Int
    ) {
        val msg = "Expected Int, found (${rInput::class}, ${gInput::class}, ${bInput::class})"
        throw IllegalArgumentException(msg)
    }
    if (rInput !in 0..255 || gInput !in 0..255 || bInput !in 0..255) {
        throw IllegalArgumentException("Expected int of the range 0..255")
    }
    val r = rInput / 255.0
    val g = gInput / 255.0
    val b = bInput / 255.0
    val k = 1 - maxOf(r, g, b)
    if (k == 1.0) {
        return Quadruple(0, 0, 0, 100)
    }
    val c = Math.round(100 * (1 - r - k) / (1 - k)).toInt()
    val m = Math.round(100 * (1 - g - k) / (1 - k)).toInt()
    val y = Math.round(100 * (1 - b - k) / (1 - k)).toInt()
    val kOut = Math.round(100 * k).toInt()
    return Quadruple(c, m, y, kOut)
};1

