fun largest_rectangle_area(maps: List<List<List<Int>>>): List<Int> {
    fun compute_max_area(grid: List<List<Int>>): Int {
        val S = Array(6) { IntArray(6) { 0 } }
        for (i in 0 until 5) {
            for (j in 0 until 5) {
                S[i + 1][j + 1] = grid[i][j] + S[i][j + 1] + S[i + 1][j] - S[i][j]
            }
        }
        var maxArea = 0
        for (x1 in 0 until 5) {
            for (x2 in x1 until 5) {
                for (y1 in 0 until 5) {
                    for (y2 in y1 until 5) {
                        val height = x2 - x1 + 1
                        val width = y2 - y1 + 1
                        val area = height * width
                        val sumVal = S[x2 + 1][y2 + 1] - S[x1][y2 + 1] - S[x2 + 1][y1] + S[x1][y1]
                        if (sumVal == area) {
                            if (area > maxArea) {
                                maxArea = area
                            }
                        }
                    }
                }
            }
        }
        return maxArea
    }
    val results = mutableListOf<Int>()
    for (grid in maps) {
        results.add(compute_max_area(grid))
    }
    return results
};1

