fun solve(from: Char = 'A', toInclusive: Char = 'Z'): Int {
    val s = readLn()
    val letters = toInclusive - from + 1
    val inf = letters + 1
    val e = List(letters) { IntArray(letters) { inf } }
    repeat(readInt()) {
        val (u, v) = readLn().map { it - from }
        e[u][v] = 1
    }
    for (k in e.indices) {
        e[k][k] = 0
        for (i in e.indices) {
            for (j in e.indices) {
                e[i][j] = minOf(e[i][j], e[i][k] + e[k][j])
            }
        }
    }
    fun cost(k: Int): Int? {
        return s.sumOf { c -> e[c - from][k].also { if (it == inf) return null } }
    }
    return e.indices.mapNotNull { cost(it) }.minOrNull() ?: -1
};0

fun minimumCommunalSpaces(customerArrivals: List<Pair<Int, Int>>): Int {
    val times = customerArrivals.map { it.first }.sorted()
    val events = mutableListOf<Pair<Int, String>>()
    for (t in times) {
        events.add(Pair(t, "arrive"))
        events.add(Pair(t + 30, "leave"))
    }
    events.sortWith(compareBy({ it.first }, { it.second }))
    var maxCustomers = 0
    var currentCustomers = 0
    for ((_, kind) in events) {
        if (kind == "arrive") {
            currentCustomers += 1
            if (currentCustomers > maxCustomers) {
                maxCustomers = currentCustomers
            }
        } else {
            currentCustomers -= 1
        }
    }
    // each space can hold up to 5 customers simultaneously
    return (maxCustomers + 4) / 5
};1

fun connectTables(hosts: List<String>): Map<String, String> {
    val statusMap = mutableMapOf<String, String>()
    for (host in hosts) {
        var numPart = ""
        var i = host.length - 1
        while (i >= 0 && host[i].isDigit()) {
            numPart = host[i] + numPart
            i--
        }
        if (numPart.isNotEmpty()) {
            val number = numPart.toInt()
            statusMap[host] = if (number % 2 == 0) "Connected" else "Failed"
        } else {
            statusMap[host] = "Failed"
        }
    }
    return statusMap
};1

fun OneArray<OneArray<Int>>.find(x: Int): Int {
    val A = this
    val k = size
    val n = map { size }.sum()

    // find the closest number in each array w/ binary search
    // now we have k numbers, traverse through them to find the best one
    return A.map { it.binSearch(x) }.min() ?: -1

    // let si represent the size of the i-th array
    // then s1 + s2 + s3 + ... + sk = n
    // and we will spend log(s1) + log(s2) + ... + log(sk) time
    // since si < n for all i, it is at most O(k log n)
    // finally, we will do O(k) work to find the best one
    // therefore the total time would be O(k log n + k) = O (k log n)
};0

