        '+' to Operator('+', 2),
        '-' to Operator('-', 2),
        '/' to Operator('/', 3),
        '*' to Operator('*', 3),
        '^' to Operator('^', 4, true)
)
 
class Expression(val ex: String, val op: Operator? = null)
 
fun PostfixToInfix(postfix: String): String {
    val stack = Stack<Expression>()
 
    for (token in Pattern.compile("\\s+").split(postfix)) {
        val c = token[0]
 
        val op = operators[c]
        if (op!= null && token.length == 1) {
            val rhs = stack.pop()
            val lhs = stack.pop()
 
            val opPrec = op.precedence
 
            val lhsPrec = lhs.op?.precedence?: Int.MAX_VALUE
            val rhsPrec = rhs.op?.precedence?: Int.MAX_VALUE
 
            if (lhsPrec < opPrec || (lhsPrec == opPrec && c == '^'))
                lhs.ex = '(' + lhs.ex + ')'
 
            if (rhsPrec < opPrec || (rhsPrec == opPrec && c!= '^'))
                rhs.ex = '(' + rhs.ex + ')'
 
            stack.push(Expression(String.format("%s %c %s", lhs.ex, op.token, rhs.ex), op))
        } else {
            stack.push(Expression(token))
        }
 
        // print intermediate result
        println("$token -> ${stack.asReversed().joinToString(", ", "[", "]") { it.ex }}")
    }
    return stack.peek().ex
};1

