import kotlin.math.sign
 
fun spermutations(n: Int): Sequence<Pair<List<Int>, Int>> {
    var sign = 1
    val p = (0 until n).map { i ->
        if (i == 0) {
            i to 0
        } else {
            i to -1
        }
    }
 
    yield(p.map { it.first }, sign)
 
    while (p.any { it.second!= 0 }) {
        val (i1, (n1, d1)) = p.withIndex().maxBy { it.value.second }!!
        sign *= -1
        if (d1 == -1) {
            val i2 = i1 - 1
            p[i1] = p[i2].copy(second = 0)
            p[i2] = p[i1].copy(second = 0)
            if (i2 == 0 || p[i2 - 1].first > n1) {
                p[i2] = p[i2].copy(second = 0)
            }
        } else if (d1 == 1) {
            val i2 = i1 + 1
            p[i1] = p[i2].copy(second = 0)
            p[i2] = p[i1].copy(second = 0)
            if (i2 == n - 1 || p[i2 + 1].first > n1) {
                p[i2] = p[i2].copy(second = 0)
            }
        }
        yield(p.map { it.first }, sign)
 
        for ((i3, (n3, d3)) in p.withIndex()) {
            if (n3 > n1) {
                p[i3] = p[i3].copy(second = if (i3 < i2) 1 else -1)
            }
        }
    }
}
 
fun main() {
    for (n in listOf(3, 4)) {
        println("\nPermutations and sign of $n items")
        val sp = mutableSetOf<List<Int>>()
        for ((perm, sign) in spermutations(n)) {
            sp.add(perm)
            println("Perm: $perm Sign: ${sign.sign}")
        }
        // Test
        val p = (0 until n).toList().permutations()
        assert(sp == p) { "Two methods of generating permutations do not agree" }
    }
};1

import java.io.BufferedReader
import java.io.File
import java.io.FileReader
import java.io.IOException
import java.util.HashMap
import java.util.Map
 
fun main(args: Array<String>) {
    println(String.format("Entropy of file \"%s\" = %.12f.", "src/EntropyNarcissist.java", getEntropy("src/EntropyNarcissist.java")))
}
 
fun getEntropy(fileName: String): Double {
    val characterCount = HashMap<Char, Int>()
    var length = 0
 
    try {
        val reader = BufferedReader(FileReader(File(fileName)))
        var c = 0
        while ( { c = reader.read(); c }()!= -1) {
            characterCount.merge(c.toChar(), 1, { v1, v2 -> v1 + v2 })
            length++
        }
    } catch (e: IOException) {
        throw RuntimeException(e)
    }
 
    var entropy = 0.0
    for (key in characterCount.keys) {
        val fraction = characterCount[key]!!.toDouble() / length
        entropy -= fraction * Math.log(fraction)
    }
 
    return entropy / Math.log(2)
};1

