fun advancedMedian(data: List<Any>, cmpFunc: (Number, Number) -> Int): Double {
    fun flatten(obj: Any): List<Double> = when(obj) {
        is List<*> -> obj.flatMap { flatten(it!!) }
        is Int -> if (obj is Boolean) throw TypeError("Non-numeric value encountered: $obj") else listOf(obj.toDouble())
        is Double -> listOf(obj)
        is Float -> listOf(obj.toDouble())
        is Long -> listOf(obj.toDouble())
        else -> throw TypeError("Non-numeric value encountered: $obj")
    }

    fun merge(left: List<Double>, right: List<Double>): List<Double> {
        val merged = mutableListOf<Double>()
        var i = 0
        var j = 0
        while (i < left.size && j < right.size) {
            if (cmpFunc(left[i], right[j]) <= 0) {
                merged.add(left[i])
                i++
            } else {
                merged.add(right[j])
                j++
            }
        }
        while (i < left.size) {
            merged.add(left[i])
            i++
        }
        while (j < right.size) {
            merged.add(right[j])
            j++
        }
        return merged
    }

    fun mergesort(seq: List<Double>): List<Double> {
        if (seq.size <= 1) return seq
        val mid = seq.size / 2
        val left = mergesort(seq.subList(0, mid))
        val right = mergesort(seq.subList(mid, seq.size))
        return merge(left, right)
    }

    if (cmpFunc !is Function2<*, *, *>) {
        throw TypeError("cmpFunc must be a callable comparison function.")
    }

    val flat = flatten(data)
    if (flat.isEmpty()) {
        throw ValueError("Cannot compute the median of an empty collection.")
    }
    val ordered = mergesort(flat)
    val n = ordered.size
    val mid = n / 2
    return if (n % 2 == 1) {
        ordered[mid]
    } else {
        (ordered[mid - 1] + ordered[mid]) / 2.0
    }
}

