import java.util.*
 
sealed class List<out T> {
    class Node<T>(val children: List<List<T>>) : List<T>()
    class Leaf<T>(val value: T) : List<T>()
}
 
fun <T> List<T>.iterator(): Iterator<List<T>> = when (this) {
    is List.Node -> NodeIterator(children.iterator())
    is List.Leaf -> LeafIterator(this)
}
 
class NodeIterator<T>(val children: Iterator<List<List<T>>>) : Iterator<List<T>> {
    fun hasNext(): Boolean = children.hasNext()
    fun next(): List<T> = children.next()
}
 
class LeafIterator<T>(val leaf: List.Leaf<T>) : Iterator<List<T>> {
    fun hasNext(): Boolean = true
    fun next(): List<T> = leaf
}
 
fun <T> List<T>.flatten(): Iterator<T> = FlattenIterator(iterator())
 
class FlattenIterator<T>(val stack: Stack<Iterator<List<T>>>, val curr: Iterator<List<T>>) : Iterator<T> {
    constructor(curr: Iterator<List<T>>) : this(Stack(), curr)
 
    fun hasNext(): Boolean {
        while (true) {
            if (curr.hasNext()) {
                return true
            } else if (stack.isEmpty()) {
                return false
            } else {
                curr = stack.pop()
            }
        }
    }
 
    fun next(): T {
        while (true) {
            val next = curr.next()
            when (next) {
                is List.Node -> {
                    stack.push(next.iterator())
                    curr = stack.peek()
                }
                is List.Leaf -> return next.value
            }
        }
    }
}
 
