fun processShops(n: Int, q: Int, a: IntArray, queries: List<Triple<Int, Int, Int>>): List<Int> {
    val res = mutableListOf<Int>()
    val shopCosts = a.copyOf()
    for (query in queries) {
        val t = query.first
        val x = query.second
        val y = query.third
        if (t == 1) {
            // type 1: for 0 <= i < x, set a[i] = max(a[i], y)
            for (i in 0 until x) {
                if (shopCosts[i] < y) {
                    shopCosts[i] = y
                }
            }
        } else {
            // type 2: man with y money from a[x-1] to a[n-1]
            var cnt = 0
            var money = y
            for (i in (x - 1) until n) {
                if (shopCosts[i] <= money) {
                    money -= shopCosts[i]
                    cnt++
                }
            }
            res.add(cnt)
        }
    }
    return res
};1

