fun cardinalRelation(x: List<Int>, y: List<Int>, relation: String, refineOverlapping: Boolean = false): Boolean {
    // Each rectangle is given as (x1, y1, x2, y2)
    // (x1, y1): top-left corner
    // (x2, y2): bottom-right corner
    // We assume x1 <= x2 and y1 <= y2

    val (ax1, ay1, ax2, ay2) = x
    val (bx1, by1, bx2, by2) = y

    // Compute horizontal & vertical intersection lengths
    val interW = minOf(ax2, bx2) - maxOf(ax1, bx1)
    val interH = minOf(ay2, by2) - maxOf(ay1, by1)

    when (relation) {
        "above" -> {
            // Entire x–rectangle is strictly above y–rectangle
            return ay2 < by1
        }
        "below" -> {
            return ay1 > by2
        }
        "left_of" -> {
            return ax2 < bx1
        }
        "right_of" -> {
            return ax1 > bx2
        }
        "overlapping", "non_overlapping" -> {
            val overlaps: Boolean = if (refineOverlapping) {
                (interW > 0) && (interH > 0)
            } else {
                (interW >= 0) && (interH >= 0)
            }
            return if (relation == "overlapping") overlaps else !overlaps
        }
        else -> throw IllegalArgumentException("Unknown relation: $relation")
    }
};1

