fun canPartition(nums: List<Int>): Boolean {
    /*
     * Bestimmt, ob die gegebene Liste von nicht-negativen Ganzzahlen in
     * zwei Teilmengen mit gleicher Summe aufgeteilt werden kann.
     *
     * Argumente:
     *   nums (List<Int>): Liste der nicht-negativen Ganzzahlen.
     *
     * Rückgabewert:
     *   Boolean: true, falls eine solche Partition existiert, sonst false.
     */
    val total = nums.sum()
    // Wenn die Gesamtsumme ungerade ist, ist eine Aufteilung unmöglich
    if (total and 1 == 1) {
        return false
    }
    val target = total / 2
    // Bitset DP: Bit k ist gesetzt, wenn Teilmenge mit Summe k erreichbar ist
    var dp = 1
    for (num in nums) {
        dp = dp or (dp shl num)
        // Frühes Beenden: Wenn Zielsumme erreichbar, nicht weiter prüfen
        if (((dp shr target) and 1) == 1) {
            return true
        }
    }
    return false
};1

fun filterFiles(fileNames: List<String>, extension: String): List<String> {
    val result = mutableListOf<String>()
    for (name in fileNames) {
        val parts = name.split('.').toMutableList()
        if (parts.size >= 2 && name.substringAfterLast('.') == extension) {
            if (name.substringBeforeLast('.') != "") {
                result.add(name)
            } else {
                // To handle names like ".txt" which should also be considered
                if (name.startsWith('.') && name.substring(1) == extension) {
                    result.add(name)
                }
            }
        }
    }
    return result
};1

fun buildPaths2(paths: MutableList<MutableList<String>>, map: Map<String, List<String>>) {
    val allPaths = mutableListOf<MutableList<String>>()
    allPaths.addAll(paths)
    paths.removeAll() { true }
    var allDone = true

    for (path in allPaths) {
        val lastFragment = path.last()
        val canDupeSmall = !hasDupeSmall(path)
        if (lastFragment == "end") {
            paths.add(path)
            continue
        }
        allDone = false;
        val dests = map.getOrDefault(lastFragment, emptyList())
        for (dest in dests) {
            if (!dest.isLowercase()) {
                addPath(path, dest, paths)
            } else {
                if (dest == "start") continue
                if (path.contains(dest)) {
                    if (canDupeSmall) {
                        addPath(path, dest, paths)
                    }
                } else {
                    addPath(path, dest, paths)
                }
            }
        }
    }
    if (!allDone) buildPaths2(paths, map)
};0

 
typealias Matrix = Array<DoubleArray>
typealias Op = Double.(Double) -> Double
 
fun Double.dPow(exp: Double) = Math.pow(this, exp)
 
fun Matrix.elementwiseOp(other: Matrix, op: Op): Matrix {
    require(this.size == other.size && this[0].size == other[0].size)
    val result = Array(this.size) { DoubleArray(this[0].size) }
    for (i in 0 until this.size) {
        for (j in 0 until this[0].size) result[i][j] = this[i][j].op(other[i][j])
    }
    return result
}
 
fun Matrix.elementwiseOp(d: Double, op: Op): Matrix {
    val result = Array(this.size) { DoubleArray(this[0].size) }
    for (i in 0 until this.size) {
        for (j in 0 until this[0].size) result[i][j] = this[i][j].op(d)
    }
    return result
}
 
