// O(log(min(m, n)))
fun findMedianSortedArrays(nums1: IntArray, nums2: IntArray): Double {
    val a = if (nums1.size < nums2.size) nums1 else nums2
    val b = if (nums1.size < nums2.size) nums2 else nums1

    var l = 0
    var r = a.size
    var i: Int
    var j: Int
    var found: Boolean
    do {
        i = (l + r) / 2
        j = (a.size + b.size) / 2 - i
        found = true

        if (i > 0 && i <= a.size && j >= 0 && j < b.size && a[i - 1] > b[j]) {
            r = i - 1
            found = false
        }

        if (i >= 0 && i < a.size && j > 0 && j <= b.size && b[j - 1] > a[i]) {
            l = i + 1
            found = false
        }
    } while (!found)

    val left = maxOf(
        if (i > 0 && i <= a.size) a[i - 1] else Int.MIN_VALUE,
        if (j > 0 && j <= b.size) b[j - 1] else Int.MIN_VALUE)

    val right =  minOf(
        if (i >= 0 && i < a.size) a[i] else Int.MAX_VALUE,
        if (j >= 0 && j < b.size) b[j] else Int.MAX_VALUE)

    return if ((a.size + b.size) % 2 == 0)
        (left + right) / 2.0
    else
        right / 1.0
};0

object Jaro {
    fun distance(s1: String, s2: String): Double {
        val s1_len = s1.length
        val s2_len = s2.length
        if (s1_len == 0 && s2_len == 0) return 1.0
        val match_distance = Math.max(s1_len, s2_len) / 2 - 1
        val s1_matches = BooleanArray(s1_len)
        val s2_matches = BooleanArray(s2_len)
        var matches = 0
        for (i in 0..s1_len - 1) {
            val start = Math.max(0, i - match_distance)
            val end = Math.min(i + match_distance + 1, s2_len)
            (start..end - 1).find { j -> !s2_matches[j] && s1[i] == s2[j] } ?. let {
                s1_matches[i] = true
                s2_matches[it] = true
                matches++
            }
        }
        if (matches == 0) return 0.0
        var t = 0.0
        var k = 0
        (0..s1_len - 1).filter { s1_matches[it] }.forEach { i ->
            while (!s2_matches[k]) k++
            if (s1[i] != s2[k]) t += 0.5
            k++
        }
 
        val m = matches.toDouble()
        return (m / s1_len + m / s2_len + (m - t) / m) / 3.0
    }
}
 
fun main(args: Array<String>) {
    println(Jaro.distance("MARTHA", "MARHTA"))
    println(Jaro.distance("DIXON", "DICKSONX"))
    println(Jaro.distance("JELLYFISH", "SMELLYFISH"))
};0

