fun countCycles(n: Int, s: List<Int>, p: List<Int>): Int {
    val vis = BooleanArray(n) { false }
    val posInP = IntArray(n + 1)
    for ((idx, value) in p.withIndex()) {
        posInP[value] = idx
    }
    var cycles = 0
    for (i in 0 until n) {
        if (!vis[i]) {
            cycles += 1
            var j = i
            while (!vis[j]) {
                vis[j] = true
                j = posInP[s[j]]
            }
        }
    }
    return cycles
}

fun possibleShifts(testCases: List<Triple<Int, Int, List<Int>>>): List<List<Int>> {
    val results = mutableListOf<List<Int>>()
    for ((n, m, pOrig) in testCases) {
        val p0 = pOrig.map { it - 1 } // 0-based
        val cnt = IntArray(n)
        val pos = IntArray(n)
        for (i in 0 until n) {
            pos[p0[i]] = i
        }
        for (k in 0 until n) {
            var good = 0
            for (i in 0 until n) {
                if ((p0[i] - i).mod(n) == (n - k).mod(n)) {
                    good += 1
                }
            }
            cnt[k] = good
        }
        val candidates = mutableListOf<Int>()
        val threshold = n - 2 * m
        for (k in 0 until n) {
            if (cnt[k] >= threshold) {
                // Create the shifted identity
                val s = List(n) { ((it - k + n) % n) + 1 }
                val cycles = countCycles(n, s, pOrig)
                if (n - cycles <= m) {
                    candidates.add(k)
                }
            }
        }
        results.add(candidates.sorted())
    }
