fun twoSum(nums: List<Int>, target: Int): Pair<Int, Int>? {
    val seen = mutableSetOf<Int>()
    for (num in nums) {
        val complement = target - num
        if (complement in seen) {
            return Pair(complement, num)
        }
        seen.add(num)
    }
    return null
