fun maxNonOverlapping(nums: List<Int>, target: Int): Pair<Int, List<List<Int>>> {
    // prefixSum -> rightmost index where that prefix was seen *after* last accepted sub-array
    var prefixToIndex = mutableMapOf<Int, Int>(0 to -1) // empty prefix before start
    var prefixSum = 0
    val chosenRanges = mutableListOf<Pair<Int, Int>>()

    for ((i, x) in nums.withIndex()) {
        prefixSum += x
        if (prefixToIndex.containsKey(prefixSum - target)) {
            val start = prefixToIndex[prefixSum - target]!! + 1
            val end = i
            chosenRanges.add(Pair(start, end))
            // Reset state so that future sub-arrays cannot overlap
            prefixSum = 0
            prefixToIndex = mutableMapOf(0 to i)
        } else {
            prefixToIndex[prefixSum] = i
        }
    }
    // Materialise the actual sub-arrays
    val subArrays = chosenRanges.map { (s, e) -> nums.slice(s..e) }
    return Pair(subArrays.size, subArrays)
};1

