    val wta = arrayOf(intArrayOf(1, 5, 3, 7, 2), intArrayOf(5, 3, 7, 2, 6, 4, 5, 9, 1, 2), intArrayOf(2, 6, 3, 5, 2, 8, 1, 4, 2, 2, 5, 3, 5, 7, 4, 1), intArrayOf(5, 5, 5, 5), intArrayOf(5, 6, 7, 8), intArrayOf(8, 7, 7, 6), intArrayOf(6, 7, 10, 7, 6))
    val blk = ""
