    val tb = "██"
    val wr = "≈≈"
    val mt = "  "
    for (i in wta.indices) {
        var bpf: Int
        var blk = ""
        do {
            var floor = ""
            bpf = 0
            for (j in wta[i].indices) {
                if (wta[i][j] > 0) {
                    floor += tb
                    wta[i][j] -= 1
                    bpf += 1
                } else floor += if (j > 0 && j < wta[i].size - 1) wr else mt
            }
            if (bpf > 0) blk = floor + lf + blk
        } while (bpf > 0)
        while (blk.contains(mt + wr)) blk = blk.replace(mt + wr, mt + mt)
        while (blk.contains(wr + mt)) blk = blk.replace(wr + mt, mt + mt)
        if (args.size > 0) println("\n$blk")
        println("Block ${i + 1} retains ${(blk.length - blk.replace(wr, "").length) / 2} water units.")
