fun minOperationsToAvoidArrest(N: Int, K: Int, M: Int, R: List<Int>): Int {
    fun combinations(n: Int, k: Int): Sequence<List<Int>> = sequence {
        val pool = (0 until n).toList()
        val indices = (0 until k).toMutableList()
        if (k > n) return@sequence
        yield(indices.map { pool[it] })
        while (true) {
            var i = k - 1
            while (i >= 0 && indices[i] == i + n - k) i--
            if (i < 0) break
            indices[i]++
            for (j in i+1 until k) {
                indices[j] = indices[j-1] + 1
            }
            yield(indices.map { pool[it] })
        }
    }
    for (c in 0..N) {
        for (comb in combinations(N, c)) {
            val S = comb.toSet()
            var valid = true
            for (i in 0..N-K) {
                val window = (i until i+K).map { R[it] + if (it in S) 1 else 0 }
                val maxw = window.maxOrNull() ?: 0
                val cnt = window.count { it == maxw }
                if (cnt >= M) {
                    valid = false
                    break
                }
            }
            if (valid) {
                return c
            }
        }
    }
    return -1
};1

