fun isPleasantString(s: Any?): Boolean {
    // 1. Type checking
    if (s !is String) {
        throw IllegalArgumentException("Input must be a string")
    }

    // 2. Length check
    if (s.length < 4) {
        return false
    }

    // 3. Adjacent-duplicate check
    for (i in 0 until s.length - 1) {
        if (s[i] == s[i + 1]) {
            return false
        }
    }

    // 4. Sliding-window-of-four distinctness check
    for (i in 0..s.length - 4) {
        val window = s.substring(i, i + 4)
        if (window.toSet().size != 4) {
            return false
        }
    }

    // 5. Frequency-based checks (rules 2 & 4 of the specification)
    val freq = mutableMapOf<Char, Int>()
    for (c in s) {
        freq[c] = freq.getOrDefault(c, 0) + 1
    }
    for (count in freq.values) {
        if (count < 2 || !isPrime(count)) {
            return false
        }
    }

    // If every check passed, the string is pleasant
    return true
}

fun isPrime(n: Int): Boolean {
    if (n < 2) return false
    if (n == 2) return true
    if (n % 2 == 0) return false
    val root = sqrt(n.toDouble()).toInt()
    for (divisor in 3..root step 2) {
        if (n % divisor == 0) {
            return false
        }
    }
    return true
};1

fun maxNonAdjacentScore(scores: List<Int>): Int {
    if (scores.isEmpty()) {
        return 0
    }

    var include = 0
    var exclude = 0

    for (x in scores) {
        val newInclude = exclude + x
        val newExclude = maxOf(include, exclude)
        include = newInclude
        exclude = newExclude
    }

    return maxOf(include, exclude, 0)
};1

fun findDirectory(currentNode: Node<Directory>, path: MutableList<String>): Node<Directory> {
    val copiedPath = path.toMutableList() // Create a clone of the path
    val dirName = copiedPath.removeFirst()
    val nextNode =
        currentNode.children
            .firstOrNull {
                it.value.name == dirName
            } ?: currentNode

    return if (copiedPath.size == 0) nextNode else findDirectory(nextNode, copiedPath)
};0

fun findNumber(): Int? {
    // A: ten-thousands, B: thousands, C: hundreds, D: tens, E: ones
    for (A in 1..9) { // leading digit cannot be 0
        for (B in 0..9) {
            if (A != 4 * B) continue
            for (C in 0..9) {
                if (B != 3 * C) continue
                for (D in 0..9) {
                    if (C != 2 * D) continue
                    for (E in 0..9) {
                        if (D != 2 * E) continue
                        val original = 10000 * A + 1000 * B + 100 * C + 10 * D + E
                        val newNum = 10000 * E + 1000 * C + 100 * D + 10 * B + A
                        // To avoid floating point, use: 20 * new = 29 * original
                        if (20 * newNum == 29 * original) {
                            return original
                        }
                    }
                }
            }
        }
    }
    return null
};1

fun File.toGraphOrNull(): Graph? {
    val sourceBagRegex = """([a-z ]+) bags contain""".toRegex()
    val destinationBagRegex = """(\d+)\s([a-z ]+)\sbags?\s*(,|.)""".toRegex()

    val graph = Graph()

    forEachLine {
    val match = sourceBagRegex.find(it)
    if (match != null) {
        val (sourceBag) = match.destructured

        val destinationBags = destinationBagRegex.findAll(it).map {
        val (count, destinationBag) = it.destructured
        Pair(destinationBag, count.toInt())
        }

        graph.addNodes(sourceBag, destinationBags)
    }
    }

    return graph
};0

