fun averageSleep(n: Int, k: Int, a: List<Int>): Double {
    var currentSum = a.take(k).sum()
    var total = currentSum
    for (i in k until n) {
        currentSum += a[i] - a[i - k]
        total += currentSum
    }
    return total.toDouble() / (n - k + 1)
};1

