fun categorizeLoveStories(stories: Map<String, Int>): Map<String, List<String>> {
    val eras = mutableMapOf(
        "Ancient" to mutableListOf<String>(),
        "Medieval" to mutableListOf<String>(),
        "Renaissance" to mutableListOf<String>(),
        "Industrial" to mutableListOf<String>(),
        "Modern" to mutableListOf<String>(),
        "Contemporary" to mutableListOf<String>()
    )
    for ((title, year) in stories) {
        when {
            year < 500 -> eras["Ancient"]!!.add(title)
            year < 1500 -> eras["Medieval"]!!.add(title)
            year < 1700 -> eras["Renaissance"]!!.add(title)
            year < 1900 -> eras["Industrial"]!!.add(title)
            year < 2000 -> eras["Modern"]!!.add(title)
            else -> eras["Contemporary"]!!.add(title)
        }
    }
    return eras
};1

fun findMissingNumbers(arr: List<Int>): List<Int> {
    // If the array is empty, return empty list (should not occur as per spec)
    if (arr.isEmpty()) return emptyList()

    val missing = mutableListOf<Int>()
    var prev = -1 // Start one below the smallest possible value (0)

    for (num in arr) {
        if (num == prev) {
            continue // Skip duplicates
        }
        if (num - prev > 1) {
            // There is a gap; add all numbers between prev and num
            for (i in prev + 1 until num) {
                missing.add(i)
            }
        }
        prev = num
    }
    // No further action needed; after the last element up to max(arr), none are missing
    return missing
};1

fun hamming() = sequence {
    val queues = hashMapOf(2 to arrayListOf<Int>(), 3 to arrayListOf<Int>(), 5 to arrayListOf<Int>())
    var nextHam = 1
    while (true) {
        yield(nextHam)
        for (base in queues.keys) queues[base]!!.add(nextHam * base)
        nextHam = queues.values.map { it[0] }.min()!!
        for (base in queues.keys) if (queues[base]!![0] == nextHam) queues[base]!!.removeAt(0)
    }
}
 
