const val MOD = 1000000007L

fun computeSum(N: Int): Long {
    val nLong = N.toLong()
    val sqrtN = sqrt(nLong.toDouble()).toLong()
    var total = 0L
    for (x in 1L..sqrtN) {
        total = (total + x * (nLong / x) % MOD) % MOD
    }
    for (y in 1L..sqrtN) {
        var a = (nLong / (y + 1)) + 1
        val b = nLong / y
        val aNew = max(a, sqrtN + 1)
        if (aNew > b) continue
        val cnt = b - aNew + 1
        val sumX = ((aNew + b) * cnt) / 2
        total = (total + y * (sumX % MOD) % MOD) % MOD
    }
    return total % MOD
};1

fun calculate_average_pollution(readings: List<Map<String, Any>>, startDate: String, endDate: String): Double? {
    val formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")
    val start = LocalDate.parse(startDate, formatter)
    val end = LocalDate.parse(endDate, formatter)

    val levels = mutableListOf<Double>()
    for (reading in readings) {
        val dateStr = reading["date"] as String
        val pollutionLevel = reading["pollution_level"] as Double
        val date = LocalDate.parse(dateStr, formatter)
        if (date >= start && date <= end) {
            levels.add(pollutionLevel)
        }
    }
    if (levels.isEmpty()) {
        return null
    }
    return levels.sum() / levels.size
};1

fun simulateProcess(context: String?, simulator: String?, trace: String?, depth: Int?): Map<String, String> {
    fun validStr(value: String?): Boolean {
        return value != null && value != ""
    }

    if (!validStr(context)) {
        return mapOf("result" to "error")
    }
    if (!validStr(simulator)) {
        return mapOf("result" to "error")
    }
    if (!validStr(trace)) {
        return mapOf("result" to "error")
    }
    if (depth == null) {
        return mapOf("result" to "error")
    }
    // Negative values are allowed unless forbidden.
    return mapOf("result" to "ok")
