fun calculateAvgPace(raceTime: String): String {
    val (minutes, seconds) = raceTime.split(":").map { it.toInt() }
    val totalSeconds = minutes * 60 + seconds
    val avgPaceSeconds = totalSeconds / 2.0
    val paceMinutes = (avgPaceSeconds / 60).toInt()
    val paceSeconds = avgPaceSeconds % 60
    val paceSecondsStr = if (paceSeconds % 1.0 == 0.0) {
        "${paceSeconds.toInt()}"
    } else {
        // Format to 1 decimal, but trim trailing .0 if present
        val str = "%.1f".format(paceSeconds)
        if (str.endsWith(".0")) str.substring(0, str.length - 2) else str
    }
    return "$paceMinutes:$paceSecondsStr"
};1

