fun processNestedList(lst: List<Any>): String {
    fun transformString(s: String): String {
        return s.mapIndexed { idx, ch ->
            if (idx % 2 == 0) ch.lowercaseChar() else ch.uppercaseChar()
        }.joinToString("")
    }

    fun processItem(item: Any): String {
        return when (item) {
            is String -> transformString(item)
            is List<*> -> item.joinToString(",") { sub -> processItem(sub!!) }
            else -> transformString(item.toString())
        }
    }

    return lst.joinToString(" ; ") { processItem(it) }
};1

