fun findDuplicates(nums: List<Int>): List<Int> {
    // Count the frequency of each number
    val counts = mutableMapOf<Int, Int>()
    for (num in nums) {
        counts[num] = counts.getOrDefault(num, 0) + 1
    }
    // Extract numbers that appear more than once
    val duplicates = counts.filter { it.value > 1 }.keys.toList()
    // Return in ascending order
    return duplicates.sorted()
};1

fun manageMembership(operations: List<String>): List<Boolean> {
    val members = mutableSetOf<String>()
    val results = mutableListOf<Boolean>()

    for (op in operations) {
        val trimmedOp = op.trim()
        when {
            trimmedOp.startsWith("add_member(") && trimmedOp.endsWith(")") -> {
                val member = trimmedOp.substring("add_member(".length, trimmedOp.length - 1)
                members.add(member)
            }
            trimmedOp.startsWith("remove_member(") && trimmedOp.endsWith(")") -> {
                val member = trimmedOp.substring("remove_member(".length, trimmedOp.length - 1)
                members.remove(member)
            }
            trimmedOp.startsWith("is_member(") && trimmedOp.endsWith(")") -> {
                val member = trimmedOp.substring("is_member(".length, trimmedOp.length - 1)
                results.add(members.contains(member))
            }
            else -> {
                // Invalid operation, can skip or throw an exception
                // For now, we ignore invalid operations
            }
        }
    }
    return results
};1

import java.lang.Double.MAX_VALUE
import java.lang.Double.MIN_VALUE
import java.lang.Math.abs
 
data class Point(val x: Double, val y: Double)
 
data class Edge(val s: Point, val e: Point) {
    operator fun invoke(p: Point) : Boolean = when {
        s.y > e.y -> Edge(e, s).invoke(p)
        p.y == s.y || p.y == e.y -> invoke(Point(p.x, p.y + epsilon))
        p.y > e.y || p.y < s.y || p.x > Math.max(s.x, e.x) -> false
        p.x < Math.min(s.x, e.x) -> true
        else -> {
            val blue = if (abs(s.x - p.x) > MIN_VALUE) (p.y - s.y) / (p.x - s.x) else MAX_VALUE
            val red = if (abs(s.x - e.x) > MIN_VALUE) (e.y - s.y) / (e.x - s.x) else MAX_VALUE
            blue >= red
        }
    }
 
    val epsilon = 0.00001
}
 
