fun getPi(numThrows: Int): Double {
    var inCircle = 0
    for (i in 0 until numThrows) {
        //a square with a side of length 2 centered at 0 has
        //x and y range of -1 to 1
        val randX = Math.random() * 2 - 1 //range -1 to 1
        val randY = Math.random() * 2 - 1 //range -1 to 1
        //distance from (0,0) = sqrt((x-0)^2+(y-0)^2)
        val dist = Math.hypot(randX, randY)
        if (dist < 1) { //circle with diameter of 2 has radius of 1
            inCircle++
        }
    }
    return 4 * inCircle / numThrows.toDouble()
}
 
