fun findBestWay(x: Int, y: Int, d: Int, f: List<Flower>, e: Int): Int {
    val g = f.filter { it.y <= y }

    return g.mapIndexed { i, it ->
        when {
            g.size == 1 && it.x * d >= x * d -> it.c
            g.size == 1 && it.x * d <= x * d && it.c > e -> it.c - e
            g.size > 1 && it.x * d >= x * d -> it.c + findBestWay(it.x, it.y, d, g.filterIndexed { j, _ -> i != j }, e)
            g.size > 1 && it.x * d <= x * d && it.c > e -> it.c - e + findBestWay(it.x, it.y, -d, g.filterIndexed { j, _ -> i != j }, e)
            else -> 0
        }
    }.maxOrNull() ?: 0
};0

fun solve(): Int {
    val n = readInt()
    val growsHere = mutableMapOf<Int, Int>()
    val fallsHere = mutableMapOf<Int, MutableList<Int>>()
    repeat(n) {
        val (p, h) = readInts()
        growsHere[p] = h
        fallsHere.computeIfAbsent(p - h) { mutableListOf() }.add(h)
    }
    val best = mutableMapOf<Int, Int>()
    val bestWithoutThis = mutableMapOf<Int, Int>()
    for (x in (growsHere.keys + fallsHere.keys).sorted()) {
        val b = best.getOrDefault(x, 0)
        val bw = bestWithoutThis.getOrDefault(x, 0)
        for (h in fallsHere.getOrElse(x) { mutableListOf() }) {
            best[x + h] = maxOf(best.getOrDefault(x + h, 0), maxOf(b, bw) + h)
        }
        val h = growsHere[x] ?: continue
        bestWithoutThis[x + h] = maxOf(bestWithoutThis.getOrDefault(x + h, 0), bw + h)
    }
    return (best.values + bestWithoutThis.values).maxOrNull()!!
};0

 
import java.util.Stack
 
/* To find out the precedence, we take the index of the
   token in the OPS string and divide by 2 (rounding down).
   This will give us: 0, 0, 1, 1, 2 */
const val OPS = "-+/*^"
 
fun infixToPostfix(infix: String): String {
    val sb = StringBuilder()
    val s = Stack<Int>()
    val rx = Regex("""\s""")
    for (token in infix.split(rx)) {
        if (token.isEmpty()) continue
        val c = token[0]
        val idx = OPS.indexOf(c)
 
        // check for operator
        if (idx != - 1) {
            if (s.isEmpty()) {
                s.push(idx)
            }
            else {
                while (!s.isEmpty()) {
                    val prec2 = s.peek() / 2
                    val prec1 = idx / 2
                    if (prec2 > prec1 || (prec2 == prec1 && c != '^')) {
                        sb.append(OPS[s.pop()]).append(' ')
                    }
                    else break
                }
                s.push(idx)
            }
        }
        else if (c == '(') {
            s.push(-2)  // -2 stands for '('
        }
        else if (c == ')') {
            // until '(' on stack, pop operators.
            while (s.peek() != -2) sb.append(OPS[s.pop()]).append(' ')
            s.pop()
        }
        else {
            sb.append(token).append(' ')
        }
    }
    while (!s.isEmpty()) sb.append(OPS[s.pop()]).append(' ')
    return sb.toString()
}
 
fun main(args: Array<String>) {
    val es = listOf(
        "3 + 4 * 2 / ( 1 - 5 ) ^ 2 ^ 3",
        "( ( 1 + 2 ) ^ ( 3 + 4 ) ) ^ ( 5 + 6 )"
    )
    for (e in es) {
        println("Infix : $e")
        println("Postfix : ${infixToPostfix(e)}\n")
