fun scoreOfParentheses1(s: String): Int {
    var depth = 0
    var result = 0
    val one = 1
    for (i in s.indices) {
        if (s[i] == '(') {
            depth++
        }else if (s[i] == ')') {
            depth--
            if (i > 0 && s[i-1] == '(') {
                result += one.shl(depth)
            }
        }
    }
    return result
};0

