fun decodeSignedInt(byteSequence: ByteArray): Any {
    // The length must be divisible by 4 because each 32-bit integer occupies 4 bytes.
    if (byteSequence.size % 4 != 0) {
        throw IllegalArgumentException("Byte sequence length must be a multiple of 4.")
    }

    val count = byteSequence.size / 4
    if (count == 0) return emptyList<Int>()

    val buffer = ByteBuffer.wrap(byteSequence).order(ByteOrder.LITTLE_ENDIAN)
    val result = mutableListOf<Int>()
    for (i in 0 until count) {
        result.add(buffer.int)
    }
    return if (count == 1) result[0] else result
};1

import java.util.ArrayList
import java.util.Collections
import java.util.Random
 
val N = 5
 
fun generateSquare(): List<List<Int>> {
    val perms = ArrayList<List<Int>>()
    for (i in 1..N) {
        val list = ArrayList<Int>()
        for (j in 1..N) {
            list.add(j)
        }
        Collections.shuffle(list)
        perms.add(list)
    }
    val square = ArrayList<List<Int>>()
    for (i in 0 until N) {
        square.add(perms[i])
        perms.removeAt(i)
        for (j in 0 until perms.size) {
            val perm = perms[j]
            for (k in 0 until N) {
                if (perm[k] == square[i][k]) {
                    perms.removeAt(j)
                    j--
                    break
                }
            }
        }
    }
    return square
}
 
fun printSquare(square: List<List<Int>>) {
    val cellSize = N.toString().length + 1
    val strings = ArrayList<String>()
    for (row in square) {
        val sb = StringBuilder()
        for (el in row) {
            sb.append(el.toString().padStart(cellSize))
        }
        strings.add(sb.toString())
    }
    for (s in strings) {
        println(s)
    }
    println()
}
 
fun main(args: Array<String>) {
