fun validateSuperuserEmail(email: String): String {
    // Rule 1: ensure exactly one '@'
    if (email.count { it == '@' } != 1) {
        return "Invalid email for superuser"
    }

    val parts = email.split("@", limit = 2)
    val localPart = parts[0]
    val domainPart = parts[1]

    // Ensure neither part is empty (e.g., '@domain.com' or 'user@')
    if (localPart.isEmpty() || domainPart.isEmpty()) {
        return "Invalid email for superuser"
    }

    // Rule 2: there must be at least one '.' in the domain part
    if (!domainPart.contains('.')) {
        return "Invalid email for superuser"
    }

    return "Valid email for superuser"
};1

fun calculate_weighted_average_dose(weights: List<Double>, doses: List<Double>): Double {
    if (weights.size != doses.size) {
        throw IllegalArgumentException("Input lists must have the same length.")
    }
    val totalWeight = weights.sum()
    if (totalWeight == 0.0) {
        return 0.0
    }
    var weightedSum = 0.0
    for (i in weights.indices) {
        weightedSum += weights[i] * doses[i]
    }
    return weightedSum / totalWeight
};1

