fun findCommonElements(nums1: List<Int>, nums2: List<Int>): List<Int> {
    val count1 = nums1.groupingBy { it }.eachCount()
    val count2 = nums2.groupingBy { it }.eachCount()
    val commonElements = mutableListOf<Int>()
    for ((num, cnt1) in count1) {
        val cnt2 = count2[num]
        if (cnt2 != null) {
            repeat(minOf(cnt1, cnt2)) {
                commonElements.add(num)
            }
        }
    }
    return commonElements
};1

