fun bankAccountOperations(initialBalance: Int, operations: List<Pair<String, Int>>): Pair<Int, Int> {
    // Validate the initial balance
    if (initialBalance < 0) {
        throw IllegalArgumentException("Initial balance must be a non-negative integer.")
    }
    var balance = initialBalance
    var transactionCount = 0
    for (operation in operations) {
        val op = operation.first
        val amount = operation.second
        if (amount <= 0) {
            throw IllegalArgumentException("Transaction amounts must be positive integers.")
        }
        when (op) {
            "deposit" -> {
                balance += amount
                transactionCount += 1
            }
            "withdraw" -> {
                if (amount > balance) {
                    throw IllegalArgumentException("Withdrawal amount exceeds current balance.")
                }
                balance -= amount
                transactionCount += 1
            }
            else -> {
                throw IllegalArgumentException("Unsupported operation: $op")
            }
        }
    }
    return Pair(balance, transactionCount)
};1

