fun binarySearch(arr: List<Int>, target: Int): Any {
    /*
    Perform binary search on a sorted list of integers.

    Parameters
    ----------
    arr : List<Int>
        A list of integers sorted in ascending order.
    target : Int
        The integer value to search for in `arr`.
    Returns
    -------
    Any (Int or String)
        The index of `target` if found; otherwise the string "Not Found".
    */
    var left = 0
    var right = arr.size - 1

    while (left <= right) {
        val mid = left + (right - left) / 2 // Prevents potential overflow
        val midVal = arr[mid]

        if (midVal == target) {
            return mid
        } else if (midVal < target) {
            left = mid + 1
        } else {
            right = mid - 1
        }
    }
    return "Not Found"
};1

fun generateScientificNames(
    adjectives: List<String>,
    nouns: List<String>,
    numSpecies: Int
): List<String> {
    val scientificNames = mutableSetOf<String>()
    val possibleCombinations = adjectives.flatMap { a -> nouns.map { n -> Pair(a, n) } }
    if (numSpecies > possibleCombinations.size) {
        throw IllegalArgumentException("Not enough unique adjective-noun combinations for the requested number of species.")
    }
    while (scientificNames.size < numSpecies) {
        val (adjective, noun) = possibleCombinations.random()
        val name = "${adjective}us ${noun}icus"
        scientificNames.add(name)
    }
