fun calculateNewTarget(target: Long, operation: String, knownOperand: Long, isLeft: Boolean): Long {
    return when (operation) {
        "+" -> target - knownOperand
        "-" ->
                if (isLeft) {
                    target + knownOperand
                } else {
                    -(target - knownOperand)
                }
        "*" -> target / knownOperand
        "/" ->
                if (isLeft) {
                    target * knownOperand
                } else {
                    knownOperand / target
                }
        else -> throw Exception("Invalid operation")
    }
};0

