class Matrix(val rows: Int, val cols: Int, val data: Array<DoubleArray>) {
    operator fun get(row: Int, col: Int): Double = data[row][col]
    operator fun set(row: Int, col: Int, value: Double) {
        data[row][col] = value
    }
 
    fun elementWise(operator: (Double, Double) -> Double, other: Matrix): Matrix {
        val result = Matrix(rows, cols, Array(rows) { DoubleArray(cols) })
        for (row in 0 until rows) {
            for (col in 0 until cols) {
                result[row, col] = operator(this[row, col], other[row, col])
            }
        }
        return result
    }
 
    fun toString(): String {
        val sb = StringBuilder()
        for (row in 0 until rows) {
            for (col in 0 until cols) {
                sb.append(this[row, col]).append(" ")
            }
            sb.append("\n")
        }
        return sb.toString()
    }
 
    companion object {
        fun build(rows: Int, cols: Int, init: (Int, Int) -> Double): Matrix {
            val data = Array(rows) { DoubleArray(cols) }
            for (row in 0 until rows) {
                for (col in 0 until cols) {
                    data[row][col] = init(row, col)
                }
            }
            return Matrix(rows, cols, data)
        }
    }
}
 
fun main() {
    val m1 = Matrix(2, 3, { row, col -> (row + 1) * 10 + col + 1 })
    val m2 = Matrix(2, 3, { row, col -> (row + 1) * 10 + col + 1 })
    println("m1: $m1\nm2: $m2\n")
 
    val operators = arrayOf("+", "-", "*", "/", "fdiv", "**", "%")
    for (op in operators) {
        println("m1 %-4s m2  =  ${m1.elementWise(getOperator(op), m2)}")
    }
}
 
fun getOperator(op: String): (Double, Double) -> Double {
    return when (op) {
        "+" -> Double::plus
        "-" -> Double::minus
        "*" -> Double::times
        "/" -> Double::div
        "fdiv" -> { a, b -> a / b }
        "**" -> { a, b -> a.pow(b) }
        "%" -> { a, b -> a % b }
        else -> throw IllegalArgumentException("Unknown operator: $op")
    }
};1

