private val operations = mapOf(
    "add" to { a: Double, b: Double -> a + b },
    "sub" to { a: Double, b: Double -> a - b },
    "mul" to { a: Double, b: Double -> a * b },
    "div" to { a: Double, b: Double -> a / b },
    "pow" to { a: Double, b: Double -> a.pow(b) }
)
 
private val nothing: (Double, Double) -> Double = { a, b -> a }
 
fun DoubleArray.doOperation(name: String, other: DoubleArray): DoubleArray {
    if (this == null || other == null) throw IllegalArgumentException()
    if (this.size!= other.size) throw IllegalArgumentException("Arrays have different dimensions.")
 
    val result = DoubleArray(this.size)
    for (i in this.indices) {
        result[i] = operations[name]?.invoke(this[i], other[i])?: this[i]
    }
    return result
}
 
fun DoubleArray.doOperation(operation: (Double, Double) -> Double, other: DoubleArray): DoubleArray {
    if (this == null || other == null) throw IllegalArgumentException()
    if (this.size!= other.size) throw IllegalArgumentException("Arrays have different dimensions.")
 
    val result = DoubleArray(this.size)
    for (i in this.indices) {
        result[i] = operation(this[i], other[i])
    }
    return result
}
 
