fun icbrt(x: Int): Int {
    if (x < 0) throw IllegalArgumentException("icbrt only works for non-negative input")
    var r = x.toDouble().pow(1.0/3.0).roundToInt()
    while ((r + 1).toLong().pow(3) <= x) r += 1
    while (r.toLong().pow(3) > x) r -= 1
    return r
}

fun countWays(n: Int): Int {
    if (n < 1) throw IllegalArgumentException("n must be a positive integer")

    var solutions = 0

    val yMax = icbrt(abs(n) / 29 + 1) + 2
    val xMax = icbrt(abs(n) + 29 * (yMax.toDouble().pow(3).toInt())) + 2

    for (y in -yMax..yMax) {
        val constPart = n - 29 * y * y * y
        for (x in -xMax..xMax) {
            if (x * x * x + x * y == constPart) {
                solutions += 1
            }
        }
    }
    return solutions
}

