        for ((name, content) in node) {
            if (name in ignore) {
                continue
            }
            if (content is Map<*, *>) {
                @Suppress("UNCHECKED_CAST")
                newNode[name] = _copy(content as Map<String, Any>)
            } else {
                newNode[name] = content
            }
        }
        return newNode
    }
    return _copy(src)
