fun ambRun(func: (amb: (values: List<Any>) -> Any, fail: () -> Nothing) -> Any): Any {
    val choices = mutableListOf<Choice>()
    var index = 0
 
    fun amb(values: List<Any>): Any {
        if (values.isEmpty()) {
            fail()
        }
        if (index == choices.size) {
            choices.add(Choice(0, values.size))
        }
        val choice = choices[index++]
        return values[choice.i]
    }
 
    fun fail(): Nothing = throw Fail()
 
    while (true) {
        try {
            index = 0
            return func(amb, fail)
        } catch (e: Fail) {
            if (e!= Fail) {
                throw e
            }
            var choice: Choice?
            while ((choice = choices.lastOrNull())!= null && ++choice.i == choice.count) {
                choices.removeAt(choices.lastIndex)
            }
            if (choice == null) {
                return null
            }
            choices.add(choice)
        }
    }
}
 
ambRun { amb, fail ->
    fun linked(s1: String, s2: String) = s1.last() == s2.first()
 
    val w1 = amb(listOf("the", "that", "a"))
    val w2 = amb(listOf("frog", "elephant", "thing"))
    if (!linked(w1 as String, w2)) fail()
 
    val w3 = amb(listOf("walked", "treaded", "grows"))
    if (!linked(w2, w3)) fail()
 
    val w4 = amb(listOf("slowly", "quickly"))
    if (!linked(w3, w4)) fail()
 
    listOf(w1, w2, w3, w4).joinToString(" ")
}  // "that thing grows slowly";1

