fun findMaximum(nums: List<Int>?): Int? {
    // Validate that input is a list
    if (nums == null) {
        throw TypeCastException("Input must be a list of integers.")
    }
    // Validate that all elements are integers (not needed in Kotlin, List<Int> guarantees it)
    // Empty list case
    if (nums.isEmpty()) {
        return null
    }
    // Initialize the maximum with the first element
    var maximumValue = nums[0]
    // Iterate through the list, updating maximumValue when a larger number is found
    for (num in nums.subList(1, nums.size)) {
        if (num > maximumValue) {
            maximumValue = num
        }
    }
    return maximumValue
};1

 
