fun maxPokemons(n: Int, strengths: List<Int>): Int {
    val maxS = strengths.maxOrNull() ?: 1
    if (maxS == 1) {
        return 1
    }
    val freq = mutableMapOf<Int, Int>()
    for (s in strengths) {
        if (s == 1) {
            continue
        }
        val divisors = mutableSetOf<Int>()
        divisors.add(s)
        val sqrtS = sqrt(s.toDouble()).toInt()
        for (i in 2..sqrtS) {
            if (s % i == 0) {
                divisors.add(i)
                val other = s / i
                if (other != i) {
                    divisors.add(other)
                }
            }
        }
        for (d in divisors) {
            freq[d] = freq.getOrDefault(d, 0) + 1
        }
    }
    return if (freq.isNotEmpty()) freq.values.maxOrNull() ?: 1 else 1
};1

fun IntRange.binarySearch(predicate: (Int) -> Boolean): Int {
    var (low, high) = this.first to this.last // must be false ... must be true
    while (low + 1 < high) (low + (high - low) / 2).also { if (predicate(it)) high = it else low = it }
    return high // first true
