fun calculateMedian(numbers: List<Number>): Double {
    val sortedNumbers = numbers.map { it.toDouble() }.sorted()
    val n = sortedNumbers.size
    val mid = n / 2
    return if (n % 2 == 1) {
        sortedNumbers[mid]
    } else {
        (sortedNumbers[mid - 1] + sortedNumbers[mid]) / 2.0
    }
