fun moveTail(head:Position, tail:Position){
    if (head.X > tail.X + 1){
        tail.X++
        if (head.Y > tail.Y){
            tail.Y++
        }
        else if (head.Y < tail.Y){
            tail.Y--
        }
    }
    else if (head.X < tail.X - 1){
        tail.X--
        if (head.Y > tail.Y){
            tail.Y++
        }
        else if (head.Y < tail.Y){
            tail.Y--
        }
    }
    else if (head.Y > tail.Y + 1){
        tail.Y++
        if (head.X > tail.X){
            tail.X++
        }
        else if (head.X < tail.X){
            tail.X--
        }
    }
    else if (head.Y < tail.Y - 1 ){
        tail.Y--
        if (head.X > tail.X){
            tail.X++
        }
        else if (head.X < tail.X){
            tail.X--
        }
    }
};0

import kotlin.math.cbrt
import kotlin.math.sqrt
 
const val bCoeff = 7.0
 
data class Pt(val x: Double, val y: Double)
 
fun zero() = Pt(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY)
 
fun is_zero(p: Pt) = p.x > 1e20 || p.x < -1e20
 
fun neg(p: Pt) = Pt(p.x, -p.y)
 
fun dbl(p: Pt): Pt {
    if (is_zero(p)) {
        return p
    }
    val L = (3 * p.x * p.x) / (2 * p.y)
    val x = L * L - 2 * p.x
    return Pt(
        x = x,
        y = L * (p.x - x) - p.y
    )
}
 
fun add(p: Pt, q: Pt): Pt {
    if (p.x == q.x && p.y == q.y) {
        return dbl(p)
    }
    if (is_zero(p)) {
        return q
    }
    if (is_zero(q)) {
        return p
    }
    val L = (q.y - p.y) / (q.x - p.x)
    val x = L * L - p.x - q.x
    return Pt(
        x = x,
        y = L * (p.x - x) - p.y
    )
}
 
fun mul(p: Pt, n: Int): Pt {
    var r = zero()
    var i = 1
    while (i <= n) {
        if (i and n!= 0) {
            r = add(r, p)
        }
        p = dbl(p)
        i = i shl 1
    }
    return r
}
 
