fun createPruningMask(
    saliencyWeights: List<Double>,
    pruningRate: Double,
    compareFn: (Double, Double) -> Boolean
): List<Boolean> {
    // Guard against empty input
    if (saliencyWeights.isEmpty()) {
        return emptyList()
    }

    // Clamp pruning rate to sensible bounds
    val rate = pruningRate.coerceIn(0.0, 1.0)

    val nWeights = saliencyWeights.size
    val nPrune = (rate * nWeights).toInt()

    // Determine threshold: the nPrune-th smallest saliency value
    val sortedVals = saliencyWeights.sorted()
    val threshold = if (nPrune == 0) {
        sortedVals[0] - 1e-12
    } else {
        sortedVals[nPrune - 1]
    }

    // Build the mask using the supplied comparison function
    return saliencyWeights.map { compareFn(it, threshold) }
};1

fun chunkDownload(totalSize: Int, chunkSize: Int): List<Pair<Int, Int>> {
    if (totalSize <= 0 || chunkSize <= 0) {
        throw IllegalArgumentException("totalSize and chunkSize must both be positive integers.")
    }

    if (chunkSize >= totalSize) {
        return listOf(Pair(0, totalSize - 1))
    }

    val chunks = mutableListOf<Pair<Int, Int>>()
    var start = 0
    while (start < totalSize) {
        val end = minOf(start + chunkSize, totalSize) - 1
        chunks.add(Pair(start, end))
        start += chunkSize
    }
    return chunks
};1

fun calculateResultFromAllBitsPackets(packetTransmission: List<Packet>) =
    packetTransmission.filterIsInstance<OperatorPacket>().map(::calculateResultFromBitsPacket)

fun calculateResultFromBitsPacket(packet: OperatorPacket): Long {
    val subPacketValues = packet.subPackets.mapNotNull {
        when (it) {
            is OperatorPacket -> calculateResultFromBitsPacket(it)
            is LiteralPacket -> it.literal
            else -> null
        }
    }

    return when (packet.operatorPacketType) {
        OperatorPacketType.SUM -> subPacketValues.sum()
        OperatorPacketType.PRODUCT -> subPacketValues.fold(1) { accumulator, value -> accumulator * value }
        OperatorPacketType.MINIMUM -> subPacketValues.minOrNull() ?: 0
        OperatorPacketType.MAXIMUM -> subPacketValues.maxOrNull() ?: 0
        OperatorPacketType.GREATER_THAN -> if (subPacketValues[0] > subPacketValues[1]) 1 else 0
        OperatorPacketType.LESS_THAN -> if (subPacketValues[0] < subPacketValues[1]) 1 else 0
        OperatorPacketType.EQUAL_TO -> if (subPacketValues[0] == subPacketValues[1]) 1 else 0
    }
};0

