//  See:  https://oeis.org/A094958
fun getPythagoreanQuadruples(max: Long): List<Long> {
    val list = ArrayList<Long>()
    var n = -1
    var m = -1
    while (true) {
        val nTest = Math.pow(2.0, n + 1).toLong()
        val mTest = (5 * Math.pow(2.0, m + 1)).toLong()
        var test = 0L
        if (nTest > mTest) {
            test = mTest
            m++
        } else {
            test = nTest
            n++
        }
        if (test < max) {
            list.add(test)
        } else {
            break
        }
    }
    return list
};1

fun separateAndReverse(sequence: List<Int>): Pair<List<Int>, List<Int>> {
    // Separate the given sequence into primes and composites, each reversed.
    fun isPrime(n: Int): Boolean {
        if (n <= 1) return false
        if (n == 2) return true
        if (n % 2 == 0) return false
        val limit = sqrt(n.toDouble()).toInt()
        var divisor = 3
        while (divisor <= limit) {
            if (n % divisor == 0) return false
            divisor += 2
        }
        return true
    }

    val primes = mutableListOf<Int>()
    val composites = mutableListOf<Int>()

    for (num in sequence) {
        if (num <= 1) {
            // 0, 1, and negative numbers are neither prime nor composite
            continue
        }
        if (isPrime(num)) {
            primes.add(num)
        } else {
            composites.add(num)
        }
    }

    return Pair(primes.asReversed(), composites.asReversed())
};1

