fun main() {
    val cubes = ArrayList<Int>()
 
    val dump = { title: String, items: Map<Int, Int> ->
        println(title)
        for ((key, value) in items) {
            print("\n" + String.format("%4d", key) + " " + String.format("%10d", value))
            for (x in cubes) {
                var y = value - x
                if (y < x) {
                    break
                }
                if (cubes.contains(y)) {
                    print(" = " + String.format("%4d", indexOf(cubes, y)) + "^3 + " + String.format("%3d", indexOf(cubes, x)) + "^3")
                }
            }
        }
    }
 
    val sums = ArrayList<Int>()
 
    // create sorted list of cube sums
    for (i in 0..1189) {
        val cube = i * i * i
        cubes.add(cube)
        for (j in cubes) {
            sums.add(cube + j)
        }
    }
    sums.sort()
 
    // now seek consecutive sums that match
    var nm1 = sums[0]
    var n = sums[1]
    var idx = 0
    val task = HashMap<Int, Int>()
    val trips = HashMap<Int, Int>()
 
    var it = sums.listIterator()
    val end = sums.listIterator(sums.size)
    it.next()
    it.next()
 
    while (it!= end) {
        val np1 = it.next()
 
        if (nm1 == np1) {
            trips[idx] = n
        }
        if (nm1!= n && n == np1) {
            if (idx <= 25 || idx >= 2000 && idx <= 2006) {
                task[idx] = n
            }
        }
        nm1 = n
        n = np1
    }
 
    dump("First 25 Taxicab Numbers, the 2000th, plus the next half-dozen:", task)
 
    val ss = StringBuilder()
    ss.append("\n\nFound ").append(trips.size).append(" triple Taxicabs under 2007:")
    dump(ss.toString(), trips)
};1

