fun isPrime(n: Int): Boolean {
    when {
        n < 2 -> return false
        n % 2 == 0 -> return n == 2
        n % 3 == 0 -> return n == 3
        else -> {
            var d = 5
            while (d * d <= n) {
                if (n % d == 0) {
                    return false
                }
                d += 2
                if (n % d == 0) {
                    return false
                }
                d += 4
            }
            return true
        }
    }
}
 
fun repunit(n: Int): BigInteger {
