val circs = ArrayList<Int>()
 
fun alreadyFound(n: Int): Boolean {
    for (i in circs) {
        if (i == n) {
            return true
        }
    }
    return false
}
 
fun isCircular(n: Int): Boolean {
    var nn = n
    var pow = 1 // will eventually contain 10 ^ d where d is number of digits in n
    while (nn > 0) {
        pow *= 10
        nn /= 10
    }
    nn = n
    while (true) {
        nn *= 10
        val f = nn / pow // first digit
        nn += f * (1 - pow)
        if (alreadyFound(nn)) {
            return false
        }
        if (nn == n) {
            break
        }
        if (!isPrime(nn)) {
            return false
        }
    }
    return true
}
 
