fun maxPixel(grid: List<List<Int>>): Int {
    // Initialize with the first available element.
    // Find the first non-empty row to get a starting value.
    var currentMax: Int? = null
    for (row in grid) {
        if (row.isNotEmpty()) {
            currentMax = row[0]
            break
        }
    }
    if (currentMax == null) {
        throw IllegalArgumentException("Grid contains no pixel values.")
    }
    for (row in grid) {
        for (value in row) {
            if (value > currentMax) {
                currentMax = value
            }
        }
    }
    return currentMax
};1

