fun nextPermutation(arr: List<Int>): List<Int>? {
    val a = arr.toMutableList()
    val n = a.size
    var k = -1
    for (i in n - 2 downTo 0) {
        if (a[i] < a[i + 1]) {
            k = i
            break
        }
    }
    if (k == -1) {
        return null
    }
    var l = n - 1
    while (a[l] <= a[k]) {
        l -= 1
    }
    val temp = a[k]
    a[k] = a[l]
    a[l] = temp
    val suffix = a.subList(k + 1, n).reversed()
    for (i in suffix.indices) {
        a[k + 1 + i] = suffix[i]
    }
    return a
};1

/**
 * An iterative implementation that will check whether the given graph is a tree. The following
 * steps are performed :
 *
 * 1. The root of the tree is found. If it does not exist, return false.
 * 2. A DFS is performed to check that each node has exactly one parent. If not, return false.
 * 3. We check if all the nodes were traversed during the DFS. If not, return false.
 *
 * @return `true` iff this directed graph is a tree.
 */
fun MutableIntGraph.isTree(): Boolean {

  // Step 1.
  val root = findRoot()
  if (root == NoRoot) return false

  // Step 2.
  val visited = BooleanArray(size)
  val valid = treeDfs(root, visited)
  if (!valid) return false

  // Step 3.
  return visited.allTrue()
};0

fun Maze.findPath(portals: Portals): Int {
  val startCoordinate = portals.getValue(day20.first.START).first
  val endCoordinate = portals.getValue(day20.first.END).first
  val seen = mutableSetOf(0 to startCoordinate)
  val portalIndexes = portals.values.filter { it.second != tools.origin }
    .flatMap { listOf(it.first to it.second, it.second to it.first) }
    .toMap()
  val yMax = indexOfLast { it.contains('#') }
  val xMax = get(yMax).indexOfLast { it == '#' }
  val outerPortals = portalIndexes.keys.partition { (x, y) -> x == 2 || x == xMax || y == 2 || y == yMax }.first

  // greedily search the paths with lower levels first
  val queue = tools.priorityQueueOf(
    Comparator { o1, o2 ->
      when (val result = o1.third.compareTo(o2.third)) {
        0 -> o1.second.compareTo(o2.second)
        else -> result
      }
    },
    Triple(startCoordinate, 0, 0)
                                   )
  while (queue.isNotEmpty()) {
    val (coordinate, distance, level) = queue.poll()
    when {
      coordinate == endCoordinate && level == 0 -> return distance
    }
    tools.adjacentCoordinates(coordinate).filter { seen.add(level to it) }
      .filter { (x, y) -> get(y)[x] == '.' }
      .filter { level != 0 || it !in outerPortals }
      .map { target ->
        when (target) {
          in portalIndexes.keys -> Triple(
            portalIndexes.getValue(target),
            distance + 2,
            when (target) {
              in outerPortals -> level - 1
              else -> level + 1
            }
                                         )
          else -> Triple(target, distance + 1, level)
        }
      }.toCollection(queue)
  }
  error("No path found")
};0

fun longestCommonSubsequenceLength(s1: String, s2: String): Int {
    val m = s1.length
    val n = s2.length
    val dp = Array(m + 1) { IntArray(n + 1) }

    for (i in 1..m) {
        for (j in 1..n) {
            if (s1[i - 1] == s2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1
            } else {
                dp[i][j] = maxOf(dp[i - 1][j], dp[i][j - 1])
            }
        }
    }

    return dp[m][n]
};1

