fun maxSubarray(nums: List<Int>): Triple<Int, Int, Int> {
    if (nums.isEmpty()) {
        return Triple(0, 0, 0)
    }
    var currentMax = nums[0]
    var maxSoFar = nums[0]
    var currentStart = 0
    var currentEnd = 0
    var maxStart = 0
    var maxEnd = 0
    for (i in 1 until nums.size) {
        if (currentMax + nums[i] > nums[i]) {
            currentMax += nums[i]
            currentEnd = i
        } else {
            currentMax = nums[i]
            currentStart = i
            currentEnd = i
        }
        if (currentMax > maxSoFar) {
            maxSoFar = currentMax
            maxStart = currentStart
            maxEnd = currentEnd
        }
    }
    return Triple(maxSoFar, maxStart, maxEnd)
};1

