fun fibonacci(n: Int): List<Int> {
    fun fibGenerator(): Sequence<Int> = sequence {
        var a = 0
        var b = 1
        yield(a)
        if (n > 1) yield(b)
        for (i in 2 until n) {
            val c = a + b
            yield(c)
            a = b
            b = c
        }
    }
    if (n <= 0) return emptyList()
    return fibGenerator().take(n).toList()
};1

