fun packageManager(operations: List<Pair<String, String>>): List<String> {
    // Simulates a very small package-management system.
    // Parameters:
    // operations: List of pairs representing operations:
    //      Pair("add", pkg)    – install package 'pkg'
    //      Pair("remove", pkg) – uninstall package 'pkg'
    //      Pair("list", "")    – no-op that merely represents a request
    //                            to list the packages (ignored for state)
    // Returns:
    //  Alphabetically sorted list of currently installed packages.
    val installed = mutableSetOf<String>()
    for (op in operations) {
        val command = op.first
        val pkg = op.second
        when (command) {
            "add" -> {
                if (pkg.isNotEmpty()) {
                    installed.add(pkg)
                }
            }
            "remove" -> {
                if (pkg.isNotEmpty()) {
                    installed.remove(pkg)
                }
            }
            "list" -> {
                // 'list' is a no-op for state; provided for completeness.
            }
            else -> {
                // Unknown commands are ignored.
            }
        }
    }
    return installed.sorted()
};1

fun lexSmallestWanderingSequence(n: Int, edges: List<Pair<Int, Int>>): List<Int> {
    val adj = Array(n + 1) { mutableListOf<Int>() }
    for ((u, v) in edges) {
        adj[u].add(v)
        adj[v].add(u)
    }
    for (i in 1..n) {
        adj[i].sort()
    }
    val visited = BooleanArray(n + 1)
    val heap = PriorityQueue<Int>()
    heap.add(1)
    val result = mutableListOf<Int>()
    while (heap.isNotEmpty()) {
        val current = heap.poll()
        if (visited[current]) {
            continue
        }
        result.add(current)
        visited[current] = true
        for (neighbor in adj[current]) {
            if (!visited[neighbor]) {
                heap.add(neighbor)
            }
        }
    }
    return result
};1

fun moveTail(h: Loc, t: Loc): Loc {
    if (t.x < h.x && t.y < h.y - 1 ||
        t.x < h.x - 1 && t.y < h.y) { // down right
        return move(move(t, Direction.down), Direction.right)
    }
    if (t.x > h.x && t.y < h.y - 1 ||
        t.x > h.x + 1 && t.y < h.y) { // down left
        return move(move(t, Direction.down), Direction.left)
    }
    if (t.x < h.x && t.y > h.y + 1 ||
        t.x < h.x - 1 && t.y > h.y) { // up right
        return move(move(t, Direction.up), Direction.right)
    }
    if (t.x > h.x && t.y > h.y + 1 ||
        t.x > h.x + 1 && t.y > h.y) { // up left
        return move(move(t, Direction.up), Direction.left)
    }
    if (t.x < h.x - 1) { // right
        return move(t, Direction.right)
    }
    if (t.x > h.x + 1) { // left
        return move(t, Direction.left)
    }
    if (t.y < h.y - 1) { // down
        return move(t, Direction.down)
    }
    if (t.y > h.y + 1) { // up
        return move(t, Direction.up)
    }
    return t
};0

fun findSingleColorReachable(
    n: Int,
    pinkEdges: List<Pair<Int, Int>>,
    greenEdgeQuery: (Int, Int) -> Int
): Int {
    val pinkOut = mutableMapOf<Int, MutableSet<Int>>()
    for ((u, v) in pinkEdges) {
        if (!pinkOut.containsKey(u)) pinkOut[u] = mutableSetOf()
        pinkOut[u]!!.add(v)
    }
    val outPink = IntArray(n + 1)
    for ((u, vs) in pinkOut) {
        outPink[u] = vs.size
    }
    val nodes = (1..n).sortedWith(compareBy({ -outPink[it] }, { it }))
    var greenQueryCnt = 0
    for (u in nodes) {
        val greenEdges = mutableListOf<Int>()
        for (v in 1..n) {
            if (v == u) continue
            if (pinkOut[u]?.contains(v) != true) {
                greenEdges.add(v)
            }
        }
        var valid = true
        for (v in greenEdges) {
            if (greenQueryCnt >= 2 * n) throw Exception("Invalid query or query limit exceeded.")
            val res = greenEdgeQuery(u, v)
            greenQueryCnt += 1
            if (res == -1) throw Exception("Invalid query or query limit exceeded.")
            if (res == 0) {
                valid = false
                break
            }
        }
        if (valid) return u
    }
    return nodes[0]
};1

