import java.util.Stack
 
fun main(args: Array<String>) {
    val infix = "3 + 4 * 2 / ( 1 - 5 ) ^ 2 ^ 3"
    println("infix:   $infix")
    println("postfix: ${infixToPostfix(infix)}")
}
 
fun infixToPostfix(infix: String): String {
    /* To find out the precedence, we take the index of the
       token in the ops string and divide by 2 (rounding down).
       This will give us: 0, 0, 1, 1, 2 */
    val ops = "-+/*^"
 
    val sb = StringBuilder()
    val s = Stack<Int>()
 
    for (token in infix.split(" ")) {
        if (token.isEmpty())
            continue
        val c = token[0]
        val idx = ops.indexOf(c)
 
        // check for operator
        if (idx!= -1) {
            if (s.isEmpty())
                s.push(idx)
 
            else {
                while (!s.isEmpty()) {
                    val prec2 = s.peek() / 2
                    val prec1 = idx / 2
                    if (prec2 > prec1 || (prec2 == prec1 && c!= '^'))
                        sb.append(ops[s.pop()]).append(' ')
                    else break
                }
                s.push(idx)
            }
        } else if (c == '(') {
            s.push(-2) // -2 stands for '('
        } else if (c == ')') {
            // until '(' on stack, pop operators.
            while (s.peek()!= -2)
                sb.append(ops[s.pop()]).append(' ')
            s.pop()
        } else {
            sb.append(token).append(' ')
        }
    }
    while (!s.isEmpty())
        sb.append(ops[s.pop()]).append(' ')
    return sb.toString()
};1

fun ipv4ToDecimal(ipv4Address: String): Int {
    val octets = ipv4Address.split(".").map {
        try {
            it.toInt()
        } catch (e: NumberFormatException) {
            throw IllegalArgumentException("Invalid IPv4 address format")
        }
    }
    if (octets.size != 4) {
        throw IllegalArgumentException("Invalid IPv4 address format")
    }
    var decimalIpv4 = 0
    for (octet in octets) {
        if (octet !in 0..255) {
            throw IllegalArgumentException("Invalid IPv4 octet $octet")
        }
        decimalIpv4 = (decimalIpv4 shl 8) + octet
    }
    return decimalIpv4
};1

fun taylorExp(x: Double, n: Int): Double {
    if (n <= 0) {
        return 0.0
    }
    var result = 1.0
    var currentTerm = 1.0
    for (i in 1 until n) {
        currentTerm *= x / i
        result += currentTerm
    }
    return result
};1

