fun checkRoleAccess(username: String, requiredRole: String): Boolean {
    val validRoles = setOf("administrator", "supervisor", "workforce member")

    // If the required role isn't one of the valid roles, deny access
    if (requiredRole !in validRoles) {
        return false
    }

    // Search for the user and verify their role
    for (user in USERS) {
        if (user.username == username) {
            return user.role == requiredRole
        }
    }

    // User not found
    return false
