fun removeDuplicates(lst: List<Any>): List<Any> {
    val seen = mutableSetOf<Any>()
    val result = mutableListOf<Any>()
    for (num in lst) {
        if (!seen.contains(num)) {
            seen.add(num)
            result.add(num)
        }
    }
    return result
