    var (dots, folds) = parseTransparentPaperSheet(transparentPaper)
    val foldsToPerform = folds.take(numberOfFolds ?: folds.size)

    foldsToPerform.forEach { fold ->
        dots = dots.map {
            when (fold.direction) {
                "x" -> foldDotLeft(it, fold.line)
                "y" -> foldDotUp(it, fold.line)
                else -> it
            }
        }.distinct()
    }

    return dots
};0

fun minPaintColors(n: Int, m: Int, vertexTypes: List<List<Int>>, edges: List<Pair<Int, Int>>): Pair<Int, List<Int>> {
    val typeToNodes = mutableMapOf<Int, MutableList<Int>>()
    for ((i, types) in vertexTypes.withIndex()) {
        for (t in types) {
            typeToNodes.getOrPut(t) { mutableListOf() }.add(i)
        }
    }
    var maxSi = 0
    for (types in vertexTypes) {
        if (types.size > maxSi) maxSi = types.size
    }
    val k = if (maxSi > 0) maxSi else 1
    val color = MutableList(m + 1) { 0 } // 1-based, color[0] unused
    var M: List<Int>? = null
    for (types in vertexTypes) {
        if (types.size == maxSi) {
            M = types
            break
        }
    }
    if (M != null) {
        var cur = 1
        for (t in M) {
            color[t] = cur
            cur += 1
        }
    }
    for (u in 1..m) {
        if (color[u] != 0) continue
        val forbidden = mutableSetOf<Int>()
        val nodes = typeToNodes[u]
        if (nodes != null) {
            for (nodeIdx in nodes) {
                for (v in vertexTypes[nodeIdx]) {
                    if (color[v] != 0 && v != u) {
                        forbidden.add(color[v])
                    }
                }
            }
        }
        for (c in 1..k) {
            if (!forbidden.contains(c)) {
                color[u] = c
                break
            }
        }
    }
    return Pair(k, (1..m).map { color[it] })
};1

