fun getPairs(max: Int): List<Pair<Int, Int>> {
    val divsums = IntArray(max + 1)
    for (i in 0..max) {
        divsums[i] = properDivisors(i).sum()
    }
    val pairs = ArrayList<Pair<Int, Int>>()
    for (i in 1..max) {
        val sum = divsums[i]
        if (i < sum && sum <= max && divsums[sum] == i) {
            pairs.add(Pair(i, sum))
        }
    }
    return pairs
}
 
fun properDivisors(number: Int): List<Int> {
    val divisors = ArrayList<Int>()
    for (divisor in 1..number / 2) {
        if (number % divisor == 0) {
            divisors.add(divisor)
        }
    }
    return divisors
};1

import kotlin.math.floor
 
class PCG32 {
    private var state = 0x853c49e6748fea9buL
    private var inc = 0xda3e39cb94b95bdbuL
 
    fun nextInt(): UInt {
        val old = state
        state = old * N + inc
        val shifted = old.shr(18).xor(old).shr(27).toUInt()
        val rot = old.shr(59)
        return (shifted shr rot.toInt()) or shifted.shl((rot.inv() + 1u).and(31u).toInt())
    }
 
    fun nextFloat(): Double {
        return nextInt().toDouble() / (1L shl 32)
    }
 
    fun seed(seedState: ULong, seedSequence: ULong) {
        state = 0u
        inc = (seedSequence shl 1).or(1uL)
        nextInt()
        state += seedState
        nextInt()
    }
 
    companion object {
        private const val N = 6364136223846793005uL
    }
}
 
