fun main(args: Array<String>) {
    var list = ArrayList<Array<Int>>()
    var j = 0
    for (c in 1..200)
        for (b in 1..c)
            for (a in 1..b)
                if (gcd(gcd(a, b), c) == 1 && isHeron(heronArea(a, b, c)))
                    list.add(arrayOf(a, b, c, a + b + c, heronArea(a, b, c)))
    sort(list)
    println("<h2>Primitive Heronian triangles with sides up to 200: " + list.size + "</h2><h3>First ten when ordered by increasing area, then perimeter:</h3><table><tr><th>Sides</th><th>Perimeter</th><th>Area</th><tr>")
    for (i in 0..9)
        println("<tr><td>" + list[i][0] + " x " + list[i][1] + " x " + list[i][2] + "</td><td>" + list[i][3] + "</td><td>" + list[i][4] + "</td></tr>")
    println("</table><h3>Area = 210</h3><table><tr><th>Sides</th><th>Perimeter</th><th>Area</th><tr>")
    for (i in 0..list.size)
        if (list[i][4] == 210)
            println("<tr><td>" + list[i][0] + " x " + list[i][1] + " x " + list[i][2] + "</td><td>" + list[i][3] + "</td><td>" + list[i][4] + "</td></tr>")
    fun heronArea(a: Int, b: Int, c: Int): Int {
        val s = (a + b + c) / 2
        return Math.sqrt(s * (s - a) * (s - b) * (s - c)).toInt()
    }

    fun isHeron(h: Int): Boolean {
        return h % 1 == 0 && h > 0
    }

    fun gcd(a: Int, b: Int): Int {
        var leftover = 1
        var dividend = if (a > b) a else b
        var divisor = if (a > b) b else a
        while (leftover!= 0) {
            leftover = dividend % divisor
            if (leftover > 0) {
                dividend = divisor
                divisor = leftover
            }
        }
        return divisor
    }

    fun sort(list: ArrayList<Array<Int>>) {
        var swapped = true
        var temp = arrayOf<Int>()
        while (swapped) {
            swapped = false
            for (i in 1..list.size) {
                if (list[i][4] < list[i - 1][4] || list[i][4] == list[i - 1][4] && list[i][3] < list[i - 1][3]) {
                    temp = list[i]
                    list[i] = list[i - 1]
                    list[i - 1] = temp
                    swapped = true
                }
            }
        }
    }
};1

