import java.util.Arrays
 
fun toSeq(x: Long, out: ByteArray) {
    var i = 9
    while (i > 0) {
        if (x and (127L shl i * 7)!= 0L) break
        i--
    }
    for (j in 0..i)
        out[j] = ((x shr (i - j) * 7 and 127) or 128).toByte()
 
    out[i] = out[i] xor 128
}
 
fun fromSeq(in_: ByteArray): Long {
    var r = 0L
    var i = 0
    while (in_[i].toInt() and 128!= 0) {
        r = r shl 7 or (in_[i].toInt() and 127).toLong()
        i++
    }
    return r
}
 
