        print("seq from " + java.lang.Long.toHexString(x[j]) + ": [ ")
 
        var i = 0
        while (s[i].toInt() and 128!= 0) {
            print(java.lang.String.format("%02x ", s[i].toInt() and 255))
            i++
        }
        println("] back: " + java.lang.Long.toHexString(fromSeq(s)))
    }
