fun main(args: Array<String>) {
    val array = arrayOf(5, 1, -6, 12, 3, 13, 2, 4, 0, 15)
    println("before: " + Arrays.toString(array))
    cocktailSort(array)
    println("after: " + Arrays.toString(array))
}
 
// Sorts an array of elements that implement the Comparable interface
fun cocktailSort(array: Array<Any>) {
    var begin = 0
    var end = array.size
    if (end == 0)
        return
    for (end-- downTo begin) {
        var new_begin = end
        var new_end = begin
        for (i in begin until end) {
            val c1 = array[i] as Comparable<Any>
            val c2 = array[i + 1] as Comparable<Any>
            if (c1.compareTo(c2) > 0) {
                swap(array, i, i + 1)
                new_end = i
            }
        }
        end = new_end
        for (i in end downTo begin) {
            val c1 = array[i - 1] as Comparable<Any>
            val c2 = array[i] as Comparable<Any>
            if (c1.compareTo(c2) > 0) {
                swap(array, i, i - 1)
                new_begin = i
            }
        }
        begin = new_begin
    }
}
 
fun swap(array: Array<Any>, i: Int, j: Int) {
    val tmp = array[i]
    array[i] = array[j]
    array[j] = tmp
};1

fun mapScore(yTrue: Map<Int, List<Int>>, yPred: Map<Int, List<Int>>, k: Int): Double {
    if (k <= 0) {
        throw IllegalArgumentException("k must be a positive integer")
    }

    var totalAp = 0.0
    var nQueries = 0

    for ((qid, relevantDocs) in yTrue) {
        nQueries += 1
        val relevantSet = relevantDocs.toSet()
        val preds = yPred.getOrDefault(qid, emptyList()).take(k)
        var numHits = 0
        var precisionSum = 0.0

        for ((idx, docId) in preds.withIndex()) {
            val rank = idx + 1
            if (relevantSet.contains(docId)) {
                numHits += 1
                precisionSum += numHits.toDouble() / rank.toDouble()
            }
        }

        val avgPrecision = if (numHits == 0) {
            0.0
        } else {
            precisionSum / minOf(relevantSet.size, k)
        }
        totalAp += avgPrecision
    }

    return if (nQueries > 0) totalAp / nQueries else 0.0
};1

