fun sanitizeInput(userInput: String): String {
    var sanitizedInput = userInput
    // Remove SQL comments (both multi-line /* ... */ and single-line -- ...)
    sanitizedInput = Regex("/\*.*?\*/", RegexOption.DOT_MATCHES_ALL).replace(sanitizedInput, "")
    sanitizedInput = Regex("--.*").replace(sanitizedInput, "")
    // Remove semicolons
    sanitizedInput = sanitizedInput.replace(";", "")
    // Remove single quotes
    sanitizedInput = sanitizedInput.replace("'", "")
    // Trim any leading or trailing whitespace
    return sanitizedInput.trim()
