fun detectPattern(intervals: List<Int>): Boolean {
    val n = intervals.size
    for (patternLen in 1..(n / 2)) {
        val pattern = intervals.subList(0, patternLen)
        var matched = true
        var i = patternLen
        while (i < n) {
            if (i + patternLen > n || intervals.subList(i, i + patternLen) != pattern) {
                matched = false
                break
            }
            i += patternLen
        }
        if (matched) return true
    }
    return false
};1

