fun validateUrl(url: String?): Boolean {
    // Basic type / emptiness check
    if (url == null || url.isEmpty()) {
        return false
    }

    // Whitespace is not allowed inside an unescaped URL
    if (url.any { it.isWhitespace() }) {
        return false
    }

    val parsed: URL
    try {
        parsed = URL(url)
    } catch (e: Exception) {
        return false
    }

    // 1. Scheme must be http or https
    if (parsed.protocol != "http" && parsed.protocol != "https") {
        return false
    }

    // 2. netloc (the part after // and before the first /) must exist
    val host = parsed.host ?: return false
    if (host.isEmpty()) return false

    // 3a. Is the host a valid IPv4 or IPv6 literal?
    try {
        // IPv6 are bracketed in URL, remove brackets if present
        val ipHost = if (host.startsWith("[") && host.endsWith("]")) host.substring(1, host.length - 1) else host
        InetAddress.getByName(ipHost)
        return true
    } catch (e: Exception) {
        // Not an IP literal, continue
    }

    // 3b. Allow “localhost” explicitly
    if (host.equals("localhost", ignoreCase = true)) {
        return true
    }

    // 3c. Otherwise validate it as a domain name
    //     • Each label 1–63 chars
    //     • Letters, digits, hyphens allowed
    //     • Label cannot start/end with a hyphen
    val labelRegex = Pattern.compile("^(?!-)[A-Za-z0-9-]{1,63}(?<!-)")
    val asciiHost = try { IDN.toASCII(host) } catch (e: Exception) { return false }
    val labels = asciiHost.split('.')
    if (labels.size < 2) {
        return false
    }
    for (label in labels) {
        if (!labelRegex.matcher(label).matches()) {
            return false
        }
    }
    return true
};1

fun isBalanced(s: String): Boolean {
    val stack = mutableListOf<Char>()
    for (char in s) {
        if (char == '(') {
            stack.add(char)
        } else if (char == ')') {
            if (stack.isEmpty()) {
                return false
            }
            stack.removeAt(stack.lastIndex)
        }
    }
    return stack.isEmpty()
};1

fun optimizedBubbleSort(arr: List<Int>, order: String): List<Int> {
    // Normalize and validate order string
    val normalizedOrder = order.lowercase()
    if (normalizedOrder != "asc" && normalizedOrder != "desc") {
        throw IllegalArgumentException("order must be either 'asc' or 'desc'")
    }

    // Make a copy so the original array is not modified
    val result = arr.toMutableList()
    val n = result.size

    // Determine comparison based on desired order
    val shouldSwap: (Int, Int) -> Boolean = if (normalizedOrder == "asc") {
        { a, b -> a > b }
    } else {
        { a, b -> a < b }
    }

    // Optimized bubble sort: stop early if no swaps in a full pass
    for (i in 0 until n) {
        var swapped = false
        // Last i elements are already in place
        for (j in 0 until (n - 1 - i)) {
            if (shouldSwap(result[j], result[j + 1])) {
                val temp = result[j]
                result[j] = result[j + 1]
                result[j + 1] = temp
                swapped = true
            }
        }
        if (!swapped) {
            break
        }
    }

    return result.toList()
};1

fun mergeWithSmallerAux(array: IntArray, aux: IntArray = IntArray(array.size / 2), lo: Int, mid: Int, hi: Int) {
    System.arraycopy(array, lo, aux, lo, aux.size)

    var i = lo
    var j = mid + 1

    var k = 0

    while(i <= mid && j <= hi) {
        if (aux[i] > array[j]) {
            array[k++] = array[j++]
        } else {
            array[k++] = aux[i++]
        }
    }

    while(i <= mid)
        array[k++] = aux[i++]

    while(j <= hi)
        array[k++] = array[j++]
};0

 
