import java.util.*
 
abstract class HuffmanTree(var freq: Int) : Comparable<HuffmanTree> {
    fun compareTo(other: HuffmanTree) = freq - other.freq
}
 
class HuffmanLeaf(freq: Int, var value: Char) : HuffmanTree(freq)
 
class HuffmanNode(var left: HuffmanTree, var right: HuffmanTree) : HuffmanTree(left.freq + right.freq)
 
fun buildTree(charFreqs: IntArray) : HuffmanTree {
    val trees = PriorityQueue<HuffmanTree>()
 
    charFreqs.forEachIndexed { index, freq ->
        if(freq > 0) trees.offer(HuffmanLeaf(freq, index.toChar()))
    }
 
    assert(trees.size > 0)
    while (trees.size > 1) {
        val a = trees.poll()
        val b = trees.poll()
        trees.offer(HuffmanNode(a, b))
    }
 
    return trees.poll()
}
 
fun printCodes(tree: HuffmanTree, prefix: StringBuffer) {
    when(tree) {
        is HuffmanLeaf -> println("${tree.value}\t${tree.freq}\t$prefix")
        is HuffmanNode -> {
            //traverse left
            prefix.append('0')
            printCodes(tree.left, prefix)
            prefix.deleteCharAt(prefix.lastIndex)
            //traverse right
            prefix.append('1')
            printCodes(tree.right, prefix)
            prefix.deleteCharAt(prefix.lastIndex)
        }
    }
}
 
fun main(args: Array<String>) {
    val test = "this is an example for huffman encoding"
 
    val maxIndex = test.max()!!.toInt() + 1
    val freqs = IntArray(maxIndex) //256 enough for latin ASCII table, but dynamic size is more fun
    test.forEach { freqs[it.toInt()] += 1 }
 
    val tree = buildTree(freqs)
    println("SYMBOL\tWEIGHT\tHUFFMAN CODE")
    printCodes(tree, StringBuffer())
};0

fun List<String>.calculateBasic(): Long {
    when {
        this.size == 1 -> {
            return this.first().toLong()
        }
        this[0].startsWith("(") -> {
            val closingExpressionIndex = this.indexOfClosingParenthesis()
            val subExpression = this.subList(1, closingExpressionIndex - 1).toMutableList()
            subExpression.add(0, this[0].drop(1))
            subExpression.add(this[closingExpressionIndex - 1].dropLast(1))
            val subExpressionResult = subExpression.calculateBasic().toString()
            return (listOf(subExpressionResult) + this.drop(closingExpressionIndex)).calculateBasic()
        }
        this[2].startsWith("(") -> {
            val closingExpressionIndex = this.drop(2).indexOfClosingParenthesis() + 1
            val subExpression = this.subList(3, closingExpressionIndex).toMutableList()
            subExpression.add(0, this[2].drop(1))
            subExpression.add(this[closingExpressionIndex].dropLast(1))
            val subExpressionResult = subExpression.calculateBasic().toString()
            val expressionResult = calculateNumbers(this[0], this[1], subExpressionResult)
            return (listOf(expressionResult) + this.drop(closingExpressionIndex + 1)).calculateBasic()
        }
        else -> {
            val tmpResult = calculateNumbers(this[0], this[1], this[2])
            return (listOf(tmpResult) + this.drop(3)).calculateBasic()
        }
    }
};0

import kotlin.math.max
 
data class Range(val lower: Double, val upper: Double) {
    fun norm(): Range {
        return if (lower > upper) Range(upper, lower) else this
    }
 
    fun toString(): String {
        return "[${lower}, ${upper}]"
    }
 
    fun union(r2: Range): List<Range> {
        return if (upper < r2.lower) listOf(this, r2) else listOf(Range(lower, max(upper, r2.upper)))
    }
}
 
fun consolidate(rs: List<Range>): List<Range> {
    val rs2 = rs.map { it.norm() }
    val le = rs2.size
    return when {
        le < 2 -> rs2
        le == 2 -> rs2[0].union(rs2[1])
        else -> {
            val rs3 = rs2.sortedBy { it.lower }
            val rs4 = mutableListOf<Range>()
            for (i in 0 until le - 1) {
                for (j in i + 1 until le) {
                    val ru = rs3[i].union(rs3[j])
                    if (ru.size == 1) {
                        rs3[i] = ru[0]
                        rs3.removeAt(j)
                        i--
                        break
                    }
                }
            }
            rs3
        }
    }
}
 
