fun decrementingLoop(n: Int, x: List<Int>) {
    /**
     * Prints the numbers from `n` down to `0`.
     * Any number that appears in `x` is *skipped* and instead the message
     * 'Skipped value: i' is printed—except for the starting value `n`
     * (even if it is in `x`, it is not skipped).
     *
     * @param n Starting integer.
     * @param x List of integers to be skipped (other than the initial `n`).
     */
    val skipSet = x.toSet() // O(1) membership testing
    for (i in n downTo 0) {
        if (i in skipSet && i != n) {
            println("Skipped value: $i")
            continue
        }
        println(i)
    }
};1

fun multiplicativeReplacement(inputArray: List<List<Float>>): List<List<Float>> {
    // Compute sums of each row first (based on original values)
    val rowSums = inputArray.map { row -> row.sum() }

    // Create the modified array
    val result = mutableListOf<List<Float>>()
    for ((i, row) in inputArray.withIndex()) {
        val s = rowSums[i]
        result.add(row.map { x -> x * s })
    }
    return result
};1

fun <T : Comparable<T>> Array<T>.selection_sort() {
    for (i in 0..size - 2) {
        var k = i
        for (j in i + 1..size - 1)
            if (this[j] < this[k])
                k = j
 
        if (k != i) {
            val tmp = this[i]
            this[i] = this[k]
            this[k] = tmp
        }
    }
}
 
