object HammingNumbers {
    // Precompute all Hamming numbers up to 1_000_000
    val hamming: List<Int> by lazy {
        val set = TreeSet<Int>()
        val maxLimit = 1_000_000
        var a = 0
        while (true) {
            val pow2 = 1 shl a
            if (pow2 > maxLimit) break
            var b = 0
            while (true) {
                val pow3 = Math.pow(3.0, b.toDouble()).toInt()
                val productAB = pow2 * pow3
                if (productAB > maxLimit) break
                var c = 0
                while (true) {
                    val pow5 = Math.pow(5.0, c.toDouble()).toInt()
                    val total = productAB * pow5
                    if (total > maxLimit) break
                    set.add(total)
                    c++
                }
                b++
            }
            a++
        }
        return@lazy set.toList()
    }
}

fun countHammingNumbers(m: Int, n: Int): Int {
    val hamming = HammingNumbers.hamming
    val left = hamming.binarySearch(m).let { if (it < 0) -it - 1 else it }
    val right = hamming.binarySearch(n).let { if (it < 0) -it - 1 else it + 1 }
    return right - left
};1

fun getLargestNumber(text: String): Int {
    // Extracts all integer substrings from `text` and returns the largest one.
    // If no integers are present, returns 0.
    val pattern = Pattern.compile("\\d+")
    val matcher = pattern.matcher(text)
    val numbers = mutableListOf<Int>()
    while (matcher.find()) {
        numbers.add(matcher.group().toInt())
    }
    return if (numbers.isNotEmpty()) numbers.maxOrNull()!! else 0
};1

