fun circleArrangement(n: Int, a: List<Int>): Pair<String, List<Int>?> {
    val aSorted = a.sorted()
    if (n >= 3 && aSorted[n - 1] >= aSorted[n - 2] + aSorted[n - 3]) {
        return Pair("NO", null)
    }
    val res = mutableListOf<Int>()
    res.add(aSorted[n - 1])
    for (i in n - 3 downTo 0) {
        res.add(aSorted[i])
    }
    res.add(aSorted[n - 2])
    return Pair("YES", res)
};1

fun countUniqueTriangles(triangles: List<Triple<Long, Long, Long>>): Int {
