    for ((a, b, c) in triangles) {
        val sorted = listOf(a, b, c).sorted()
        val key = Triple(sorted[0], sorted[1], sorted[2])
        counts[key] = counts.getOrDefault(key, 0) + 1
    }
    return counts.values.count { it == 1 }
