fun shortestWordDistance(words: List<String>, word1: String, word2: String): Int {
    if (word1 == word2) {
        var prevIndex = -1
        var minDistance = Int.MAX_VALUE
        for ((i, word) in words.withIndex()) {
            if (word == word1) {
                if (prevIndex != -1) {
                    minDistance = Math.min(minDistance, i - prevIndex)
                }
                prevIndex = i
            }
        }
        return if (minDistance != Int.MAX_VALUE) minDistance else -1
    } else {
        var index1 = -1
        var index2 = -1
        var minDistance = Int.MAX_VALUE
        for ((i, word) in words.withIndex()) {
            if (word == word1) {
                index1 = i
            } else if (word == word2) {
                index2 = i
            }
            if (index1 != -1 && index2 != -1) {
                minDistance = Math.min(minDistance, Math.abs(index1 - index2))
            }
        }
        return if (minDistance != Int.MAX_VALUE) minDistance else -1
    }
};1

fun whoDeviatesMore(maleHeight: Int, femaleHeight: Int): String {
    // Population parameters
    val MALE_MEAN = 70.0
    val MALE_STD = 4.0
    val FEMALE_MEAN = 66.0
    val FEMALE_STD = 3.0

    // Z-score magnitudes (number of standard deviations from the mean)
    val maleZ = kotlin.math.abs(maleHeight - MALE_MEAN) / MALE_STD
    val femaleZ = kotlin.math.abs(femaleHeight - FEMALE_MEAN) / FEMALE_STD

    // Comparison with a tiny tolerance for floating-point rounding
    val eps = 1e-9
    return if (kotlin.math.abs(maleZ - femaleZ) < eps) {
        "equal"
    } else if (maleZ > femaleZ) {
        "male"
    } else {
        "female"
    }
};1

fun charFromId(id: Int): Char {
    return arrayOf(' ', '#', '/', '_', 'L', '|', '\n')[id]
}
 
const val ID_BITS = 3
 
fun decode(code: ByteArray): String {
    var ret = ""
    var carry = 0
    var carryBits = 0
    for (b in code) {
        var bitPos = ID_BITS - carryBits
        var cur = b.toInt() shr bitPos
        val mask = (1 shl bitPos) - 1
        val id = carry or ((b.toInt() and mask) shl carryBits)
        ret += charFromId(id)
        while (bitPos + ID_BITS < 8) {
            ret += charFromId(cur and ((1 shl ID_BITS) - 1))
            cur = cur shr ID_BITS
            bitPos += ID_BITS
        }
        carry = cur
        carryBits = 8 - bitPos
    }
    return ret
}
 
