fun countBeautifulWays(A: List<Int>): Int {
    val freq = mutableMapOf<Int, Int>()
    for (x in A) {
        freq[x] = (freq[x] ?: 0) + 1
    }
    val sortedUnique = freq.keys.sorted()
    val m = sortedUnique.size
    val prefix = IntArray(m + 1)
    for (i in 0 until m) {
        prefix[i + 1] = prefix[i] + (freq[sortedUnique[i]] ?: 0)
    }
    var total = 0
    for (i in 0 until m) {
        val x = sortedUnique[i]
        total += (freq[x] ?: 0) * prefix[i]
    }
    return total
};1

