fun isPrime(k: Int): Boolean {
    if (k <= 1) return false
    if (k == 2) return true
    if (k % 2 == 0) return false
    var i = 3
    val sqrtK = sqrt(k.toDouble()).toInt()
    while (i <= sqrtK) {
        if (k % i == 0) return false
        i += 2
    }
    return true
}

fun findPrevPrime(n: Int): Int {
    for (k in n - 1 downTo 2) {
        if (isPrime(k)) {
            return k
        }
    }
    return -1 // Should not reach for problem constraints
}

fun findNextPrime(n: Int): Int {
    var k = n + 1
    while (true) {
        if (isPrime(k)) {
            return k
        }
        k += 1
    }
}

fun findSurroundingPrimes(n: Int): Pair<Int, Int> {
    return Pair(findPrevPrime(n), findNextPrime(n))
};1

