fun primeFactorization(n: Long): LongArray {
    var m = n
    val tempLong = mutableListOf<Long>()
    run {
        var i: Long = 2
        while (m > 1 && i * i <= m) {
            while (m % i == 0L) {
                tempLong.add(i)
                m /= i
            }
            i++
        }
    }
    if (m > 1) tempLong.add(m)
    val factors = LongArray(tempLong.size)
    for (i in factors.indices) {
        factors[i] = tempLong[i]
    }
    return factors
};0

