fun isRenameAllowed(oldname: String, newname: String, allowedType: List<String>): Boolean {
    // 1. Old file name must be non-empty.
    if (oldname.isEmpty()) {
        return false
    }

    // 2. Extract extension from `newname`.
    val dotPos = newname.lastIndexOf('.')
    if (dotPos == -1 || dotPos == newname.length - 1) {
        return false
    }
    val ext = newname.substring(dotPos + 1).lowercase()

    // 3. Normalize the allowed extensions (strip leading '.' and lowercase).
    val allowedNormalised = allowedType.map { it.trimStart('.').lowercase() }.toSet()

    // 4. Check membership.
    return ext in allowedNormalised
};1

fun String.parseGame(): Game {
