var cache = listOf(listOf(1))
fun cumu(n: Int): List<List<Int>> {
    for (l in cache.size..n) {
        val r = mutableListOf(0)
        for (x in 1..l) {
            r.add(r.last() + cache[l - x][Math.min(x, l - x)])
        }
        cache.add(r)
    }
    return cache
}
 
fun row(n: Int): List<Int> {
    val r = cumu(n)
    return (0..n).map { r[it][it + 1] - r[it][it] }
}
 
