fun countUniqueWords(text1: String, text2: String): Int {
    // Punctuation marks to strip out
    val punctuations = "!,?."
    val regex = Regex("[!,?.]")

    // Normalize both strings: remove punctuation, convert to lowercase, split into words
    val words1 = regex.replace(text1, "").lowercase().split(" ")
    val words2 = regex.replace(text2, "").lowercase().split(" ")

    // Combine the words and count the unique entries
    val uniqueWords = words1.toSet() union words2.toSet()
    // Remove any empty strings which may arise from consecutive spaces
    return uniqueWords.filter { it.isNotEmpty() }.size
};1

