fun OneArray<Char>.sps(): Int {
    // follow the naming convention
    val S = this
    val n = size
    // dp(i, j): len of SPS of S[i..j]
    // memoization structure: 2d array dp[1..n, 1..n] : dp[i, j] = dp(i, j)
    val dp = OneArray(n + 1) { OneArray(n) { 0 } }
    // space complexity: O(n^2)

    // base case:
    // dp(i, j) = 0 if j < i or i, j !in 1..n
    //          = 1 if i = j (single character string is already palindromic)
    for (i in 1..n) {
        dp[i, i] = 1
    }

    // recursive case:
    // dp(i, j) = dp(i + 1, j - 1) +  2 if S[i] == S[j]
    //            since we need to wrap S[i] and S[j] as the first and the last
    //            character in the sps
    //          = util.min{ dp(i + 1, j), dp(i, j - 1) } + 2
    //            find the minimum and either wrap two S[i] around SPS or two S[j]
    // dependency: dp(i, j) depends on dp(i + 1, j - 1), dp(i + 1, j ),
    //             and dp(i, j - 1)
    //             that is entries below, to the left, and to the lower-left
    // evaluation order: outer loop for i from n to 1 (bottom up)
    for (i in n downTo 1) {
        // inner loop for j from i + 1 to n (left to right)
        for (j in i + 1..n) {
            dp[i, j] = if (S[i] == S[j]) {
                dp[i + 1, j - 1] + 2
            } else {
                min(dp[i, j - 1], dp[i + 1, j]) + 2
            }
        }
    }
    // time complexity: O(n^2)

    dp.prettyPrintTable()

    // we want len of SPS of S[1..n], which is dp[1, n]
    return dp[1, n]
};0

fun analyzePlantGrowth(growthData: List<Pair<String, Int>>): Double {
    if (growthData.isEmpty()) {
        return 0.0
    }
    var startDate: LocalDate? = null
    var endDate: LocalDate? = null
    var startHeight: Int? = null
    var endHeight: Int? = null
    val formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")
    for ((dateStr, height) in growthData) {
        val date = LocalDate.parse(dateStr, formatter)
        if (startDate == null || date.isBefore(startDate)) {
            startDate = date
            startHeight = height
        }
        if (endDate == null || date.isAfter(endDate)) {
            endDate = date
            endHeight = height
        }
    }
    if (startDate == null || endDate == null || startHeight == null || endHeight == null) {
        return 0.0
    }
    val totalDays = java.time.temporal.ChronoUnit.DAYS.between(startDate, endDate).toInt()
    val totalGrowth = endHeight - startHeight
    if (totalDays == 0) {
        return 0.0
    }
    val averageGrowthRate = totalGrowth.toDouble() / totalDays
    return averageGrowthRate
};1

