fun first_n_fibonacci(n: Int): List<Int> {
    if (n <= 0) return emptyList()
    val fib = mutableListOf(0, 1)
    if (n == 1) return listOf(0)
    for (i in 2 until n) {
        val nextNum = fib[i - 1] + fib[i - 2]
        fib.add(nextNum)
    }
    return fib.take(n)
