fun formatNumber(number: Double, formatString: String): String {
    val thousandsSep = ","
    val decimalSep = "."
    val precision = "2"

    // 1. Replace the placeholders with their actual values
    var spec = formatString
        .replace("{thousands_sep}", thousandsSep)
        .replace("{decimal_sep}", decimalSep)
        .replace("{precision}", precision)

    // 2. Collapse any duplicate commas if they appear,
    // as might occur if the template is "{thousands_sep},{decimal_sep}{precision}f"
    while (",," in spec) {
        spec = spec.replace(",,", ",")
    }

    // 3. Use Kotlin's format machinery
    // Convert spec such as ",.2f" or ".2f" (Kotlin doesn't fully support custom specifiers like Python)
    // Instead, use NumberFormat for thousands separator and precision
    // We'll parse the spec to determine if thousands separator is needed
    // and always use 2 decimal precision and dot as decimal separator
    val useThousands = spec.contains(",")
    val format = if (useThousands) "%,.2f" else "%.2f"
    val result = String.format(format, number)
    return result
};1

fun parseRedisConnectionString(redisConnectionString: String): Map<String, Any?> {
    val uri = URI(redisConnectionString)

    val userInfo = uri.userInfo
    val password = userInfo?.let {
        if (it.startsWith(":")) it.substring(1) else null
    }

    val hostname = uri.host
    val port = uri.port.takeIf { it != -1 }

    var dbNumber: Int? = null
    val path = uri.path
    if (path != null && path.isNotEmpty()) {
        val pathPart = path.trimStart('/')
        if (pathPart.isNotEmpty()) {
            dbNumber = try {
                pathPart.toInt()
            } catch (e: NumberFormatException) {
                null
            }
        }
    }

    return mapOf(
        "password" to password,
        "hostname" to hostname,
        "port" to port,
        "db_number" to dbNumber
    )
};1

