            val transformed = transformedLine != newTransformedLine

            if ((transformed || batch.contains("\\d".toRegex())) && !reverse) {
                reverse = true
                limit = 0
            } else {
                limit += 1
            }

            transformedLine = newTransformedLine
        }

        transformedLine
