/**
 * Break the list to parts after each matching element. Separator is included in parts.
 *
 */
fun <T> List<T>.breakAfter(predicate: (T) -> Boolean): List<List<T>> {
    if(this.isEmpty()) return listOf()

    val matches = indexesOf(predicate).map { it+1 }
    if(matches.isEmpty()) {
        return listOf(this)
    }

    return listOf(0).plus(matches).plus(size)
        .windowed(2, 1)
        .map {
            subList(it[0], min(it[1],size))
        }
};0

fun processMessages(queue: List<Map<String, Any>>): List<String> {
    val results = mutableListOf<String>()
    for (message in queue) {
        val fType = message["functionType"]
        val method = message["method"]
        if (fType == 1) {
            // Valid processing message; collect its method name.
            results.add(method as String)
        } else if (fType == 0) {
            // Termination signal; stop processing immediately.
            break
        }
        // Any other functionType is ignored per specification.
    }
    return results
};1

