fun maxPalindrome(numbers: List<Int>): Int {
    /*
     * Return the largest palindromic integer in `numbers`.
     * If no palindromic integers exist, return -1.
     * A palindromic integer reads the same forward and backward.
     *
     * Parameters
     * ----------
     * numbers : List<Int>
     *
     * Returns
     * -------
     * Int
     *     The maximum palindromic integer, or -1 if none exist.
     */
    var largest = -1 // Default if no palindrome is found

    for (n in numbers) {
        // Negative numbers are not considered palindromes here
        if (n >= 0 && n.toString() == n.toString().reversed()) {
            if (n > largest) {
                largest = n
            }
        }
    }

    return largest
};1

