 * @param newIndex 后一个index
 */
fun floor(newInt: IntArray, nums: IntArray, index: Int, target: Int, size: Int, newIndex: Int) {
    if (newIndex == size) {
        return
    }
    val i = nums[index] + nums[newIndex]
    if (i == target) {
        newInt[0] = index
        newInt[1] = newIndex
        return
    } else {
        floor(newInt, nums, index, target, size, newIndex + 1)
    }
