fun divideCore(dividend: Int, divisor: Int): Int {
    var result = 0
    var newDividend = dividend
    while (newDividend <= divisor) {
        var value = divisor
        var quotient = 1
        while (value >= 0xc0000000 && newDividend <= value + value) {
            quotient += quotient
            value += value
        }

        result +=  quotient
        newDividend -= value
    }
    return result
};0

fun solve(grid: List<List<Char>>, start: Beam): Int {
    val visited = mutableSetOf<Beam>()
    val queue = mutableListOf(start)
    while (queue.isNotEmpty()) {
        val beam = queue.removeFirst()
        visited.add(beam)
        val next = getNextDirection(beam, grid[beam.y][beam.x])
        for (n in next) {
            if (n.x >= 0 && n.x < grid[0].count() && n.y >= 0 && n.y < grid.count() && n !in visited) {
                queue.add(n)
            }
        }
    }

    return visited.map { Pair(it.x, it.y) }.toSet().count()
};0

