            for (i in 0..2) {
                seq.append(tossCoin(random, false))
            }
        }
        else -> {
            val c0 = seed[0]
            val next = if (c0 == 'H') 'T' else 'H'
            seq.append(next)
            seq.append(c0)
            seq.append(seed[1])
        }
    }
    return seq.toString()
}
 
