fun berpizza(q: Int, queries: List<List<Int>>): List<Int> {
    val waiting = ArrayDeque<Int>()
    val heap = PriorityQueue<Pair<Int, Int>>(compareBy<{Pair<Int, Int}> { -it.first }.thenBy { it.second })
    val served = HashMap<Int, Boolean>()
    var nextCust = 1
    val ret = mutableListOf<Int>()
    for (query in queries) {
        if (query[0] == 1) {
            val m = query[1]
            waiting.addLast(nextCust)
            heap.add(Pair(m, nextCust))
            served[nextCust] = false
            nextCust += 1
        } else if (query[0] == 2) {
            while (waiting.isNotEmpty() && served[waiting.first()] == true) {
                waiting.removeFirst()
            }
            val k = waiting.removeFirst()
            served[k] = true
            ret.add(k)
        } else if (query[0] == 3) {
            while (heap.isNotEmpty() && served[heap.peek().second] == true) {
                heap.poll()
            }
            val k = heap.poll().second
            served[k] = true
            ret.add(k)
        }
    }
    return ret
};1

fun countingSort(array: IntArray): IntArray {
    val min = array.min()!!
    val max = array.max()!!
    val count = IntArray(max - min + 1)
    for (number in array) {
        count[number - min]++
    }
    var index = 0
    for (i in min..max) {
        for (j in 0 until count[i - min]) {
            array[index++] = i
        }
    }
    return array
}
 
