    var power = 100
    val c = sieve(limit)
    for (i in 3..limit step 2) {
        if (!c[i]) count++
        if (i == power - 1) {
            println("Count of primes up to ${power.toString().replace(",", "")} = ${count.toString().replace(",", "")}")
            power *= 10
        }
