    count = 0
    limit = 35000000
    var k = 2
    var kk = 3
    var p: Int
    for (i in 2..limit) {
        if ((p = k * kk) > limit) break
        if (chowla(p) == p - 1) {
            println("${p.toString().replace(",", "")} is a number that is perfect")
            count++
        }
        k = kk + 1
        kk += k
    }
    println("There are $count perfect numbers <= 35,000,000")
