fun calcNumberOfJumps(jumpLength: Int, d: Int, e: Int): Int {
    // If no movement is needed or possible
    if (jumpLength == 0 || (d == 0 && e == 0)) {
        return 0
    }

    // Squared Euclidean distance to the target
    val dist2 = d * d + e * e
    val step2 = jumpLength * jumpLength

    // Exactly one jump is enough if its length exactly matches the distance
    if (dist2 == step2) {
        return 1
    }

    // If a single jump over-shoots the target's distance, we can do it in one jump
    if (dist2 < step2) {
        return 1
    }

    // Otherwise, determine how many full steps are needed
    val distance = sqrt(dist2.toDouble())
    return ceil(distance / jumpLength).toInt()
};1

fun winnerOfStoneGame(n: Int, a: List<Int>): String {
    val aSorted = a.sorted()
    val freq = mutableMapOf<Int, Int>()
    for (num in aSorted) {
        freq[num] = freq.getOrDefault(num, 0) + 1
    }
    if (freq.values.maxOrNull() ?: 0 > 2) {
        return "cslnb"
    }
    val dupNumbers = freq.filter { it.value == 2 }.map { it.key }
    if (dupNumbers.size > 1) {
        return "cslnb"
    }
    if (dupNumbers.size == 1) {
        val x = dupNumbers[0]
        if (x == 0) {
            return "cslnb"
        }
        if (freq.getOrDefault(x - 1, 0) > 0) {
            return "cslnb"
        }
    }
    val S = n * (n - 1) / 2
    if (aSorted.sum() < S) {
        return "cslnb"
    }
    val totalMoves = aSorted.sum() - S
    return if (totalMoves % 2 == 1) "sjfnb" else "cslnb"
};1

