    var sign = 1
    var index = 0
    if (value[0] == '+' || value[0] == '-') {
        if (value.length == 1) {
            throw IllegalArgumentException("Invalid input: $value")
        }
        if (value[0] == '-') {
            sign = -1
        }
        index = 1
    }
    var result = 0
    while (index < value.length) {
        val char = value[index]
        if (char < '0' || char > '9') {
            throw IllegalArgumentException("Invalid input: $value")
        }
        val digit = char.toInt() - '0'.toInt()
        result = result * 10 + digit
        index++
    }
    return sign * result
};1

