//The function which will sort the given array in ascending order using QuickSort Algortihm
fun quicksort(items:List<Int>):List<Int>{
    //If there is only one element in the list, then there is no need to sort
    if (items.count() < 2){
        return items
    }

    //Vaiable pivot stores the index of middle element of the list
    val pivot = items[items.count()/2]

    //Variable equalto stores the elements at the pivot index
    val equalto = items.filter { it == pivot }

    //Variable lesser stores the list of element with indexes less than the pivot index
    val lesser = items.filter { it < pivot }

    //Variable greater stores the list of element with indexes less than the pivot index
    val greater = items.filter { it > pivot }

    //Calling the quicksort function recursively on the splitted arrays
    //This will get recursively called until left with multiple arrays with a single element and arranged in order
    return quicksort(lesser) + equalto + quicksort(greater)
};0

import kotlin.random.Random
 
val target = "METHINKS IT IS LIKE A WEASEL"
val set = "ABCDEFGHIJKLMNOPQRSTUVWXYZ "
var parent = CharArray(target.length)
 
fun init() {
    for (i in parent.indices) {
        parent[i] = set[Random.nextInt(set.length)]
    }
}
 
// fitness:  0 is perfect fit.  greater numbers indicate worse fit.
fun fitness(a: CharArray): Int {
    // (hamming distance)
    var h = 0
    for (i in target.indices) {
        if (a[i]!= target[i]) {
            h++
        }
    }
    return h
}
 
// set m to mutation of p, with each character of p mutated with probability r
fun mutate(p: CharArray, m: CharArray, r: Double) {
    for (i in p.indices) {
        if (Random.nextDouble() < r) {
            m[i] = set[Random.nextInt(set.length)]
        } else {
            m[i] = p[i]
        }
    }
}
 
fun main() {
    val c = 20 // number of times to copy and mutate parent
 
    val copies = Array(c) { CharArray(parent.size) }
 
    println(parent.joinToString(""))
    var best = fitness(parent)
    while (best > 0) {
        for (cp in copies) {
            mutate(parent, cp, 0.05)
        }
        for (cp in copies) {
            val fm = fitness(cp)
            if (fm < best) {
                best = fm
                parent.copyInto(cp)
                println(parent.joinToString(""))
            }
        }
    }
};1

