fun main() {
    readLn()
    val a = readInts()
    val aCount = a.groupBy { it }.mapValues { it.value.size }
    var b = aCount.keys.toList()
    val (primes, factPrimes) = List(2) { MutableList(2) { listOf<Int>() } }
    for (i in 2..b.maxOrNull()!!) {
        val j = (2..i).first { i % it == 0 }
        primes.add(primes[i / j].plus(j))
        factPrimes.add(factPrimes[i - 1].plus(primes[i]).sortedDescending())
    }
    var ans = aCount.map { factPrimes[it.key].size * 1L * it.value }.sum()
    for (x in factPrimes.last().indices) {
        val groups = b.groupBy { factPrimes[it].getOrNull(x) }
        val win = groups.mapValues { entry -> 2 * entry.value.sumOf { aCount.getValue(it) } - a.size }
        val p = win.entries.firstOrNull { it.value > 0 }?.key ?: break
        ans -= win.getValue(p)
        b = groups.getValue(p)
    }
    println(ans)
};0

// O(nlogn),O(n)
fun kClosest1(points: Array<IntArray>, K: Int): Array<IntArray>? {
    fun distance(point: IntArray) = point[0] * point[0] + point[1] * point[1]
    val N = points.size
    val dists = IntArray(N)
    for (i in 0 until N) dists[i] = distance(points[i])
    Arrays.sort(dists)
    val distK = dists[K - 1]
    val ans = Array(K) { IntArray(2) }
    var t = 0
    for (i in 0 until N) if (distance(points[i]) <= distK) ans[t++] = points[i]
    return ans
};0

 
import java.math.BigInteger
 
const val MAX_N = 250
const val BRANCHES = 4
 
val rooted   = Array(MAX_N + 1) { if (it < 2) BigInteger.ONE else BigInteger.ZERO }
val unrooted = Array(MAX_N + 1) { if (it < 2) BigInteger.ONE else BigInteger.ZERO }
val c = Array(BRANCHES) { BigInteger.ZERO }
 
fun tree(br: Int, n: Int, l: Int, s: Int, cnt: BigInteger) {
    var sum = s
    for (b in (br + 1)..BRANCHES) {
        sum += n
        if (sum > MAX_N || (l * 2 >= sum && b >= BRANCHES)) return
 
        var tmp = rooted[n]
        if (b == br + 1) {
            c[br] = tmp * cnt
        }
        else {
            val diff = (b - br).toLong()
            c[br] *= tmp + BigInteger.valueOf(diff - 1L)
            c[br] /= BigInteger.valueOf(diff)
        }
 
        if (l * 2 < sum) unrooted[sum] += c[br]
        if (b < BRANCHES) rooted[sum] += c[br]
        for (m in n - 1 downTo 1) tree(b, m, l, sum, c[br])
    }
}
 
fun bicenter(s: Int) {
    if ((s and 1) == 0) {
        var tmp = rooted[s / 2]
        tmp *= tmp + BigInteger.ONE
        unrooted[s] += tmp.shiftRight(1)
    }
}
 
fun main(args: Array<String>) {
    for (n in 1..MAX_N) {
        tree(0, n, n, 1, BigInteger.ONE)
        bicenter(n)
        println("$n: ${unrooted[n]}")
    }
};0

