fun maxModifiedScore(scores: IntArray, k: Int): Int {
    val n = scores.size
    val baseSum = scores.sum()
    val win = k

    var windowSum = 0
    val maxInWindow = ArrayDeque<Int>() // stores indices
    var bestDelta = 0

    for (i in scores.indices) {
        val value = scores[i]
        windowSum += value

        while (maxInWindow.isNotEmpty() && scores[maxInWindow.last()] <= value) {
            maxInWindow.removeLast()
        }
        maxInWindow.addLast(i)

        if (i >= win) {
            val outIdx = i - win
            windowSum -= scores[outIdx]
            if (maxInWindow.isNotEmpty() && maxInWindow.first() == outIdx) {
                maxInWindow.removeFirst()
            }
        }

        if (i >= win - 1) {
            val windowMax = scores[maxInWindow.first()]
            val delta = windowMax * win - windowSum
            if (delta > bestDelta) {
                bestDelta = delta
            }
        }
    }
    return baseSum + bestDelta
};1

