fun binom(n: Int, k: Int): Int {
    var coeff = 1
    var i: Int
    if (k < 0 || k > n) return 0
    for (i in 0 until k) {
        coeff = coeff * (n - i) / (i + 1)
    }
    return coeff
}
 
