fun modRush(N: Int, M: Int, A: List<Int>, B: List<Int>): Int {
    val arrA = A.toMutableList()
    val sumA = arrA.sumOf { it.toLong() }
    arrA.sort()
    val maxA = if (N > 0) arrA[N - 1] else 0

    // Compute frequency of B elements
    val freqB = mutableMapOf<Int, Int>()
    for (b in B) {
        freqB[b] = (freqB[b] ?: 0) + 1
    }
    // Compute sum_div[m] for m from 1 to maxA
    val sumDiv = LongArray(maxA + 1)
    for ((d, count) in freqB) {
        val contribution = d.toLong() * count.toLong()
        if (d > maxA) continue
        var m = d
        while (m <= maxA) {
            sumDiv[m] += contribution
            m += d
        }
    }
    // Compute sum_second
    var sumSecond = 0L
    for (m in 1..maxA) {
        val cnt = N - arrA.binarySearch(m).let { if (it < 0) -it - 1 else it }
        sumSecond += sumDiv[m] * cnt
    }
    val answer = sumA * M.toLong() - sumSecond
    return answer.toInt()
};1

