fun randomTolerance(value: Double, tolerance: Double): Double {
    // Ensure tolerance is non-negative
    val tol = abs(tolerance)

    // If tolerance is zero (or value is NaN/Inf), just return the input value
    if (tol == 0.0 || value.isNaN() || value.isInfinite()) {
        return value
    }

    val delta = value * tol
    val lower = value - delta
    val upper = value + delta
    return Random.Default.nextDouble(lower, upper)
};1

