fun checkIsin(a: String): Boolean {
    if (a.length!= 12 ||!a.take(2).all { it.isLetter() } ||!a.drop(2).all { it.isLetterOrDigit() })
        return false
    val s = a.map { if (it.isDigit()) it.toInt() - 48 else it.toInt() - 55 }.joinToString("")
    return 0 == (s.dropLast(2).mapIndexed { i, c -> if (i % 2 == 0) c.toString().toInt() * 2 else c.toString().toInt() }.sum() +
            s.takeLast(2).map { it.toString().toInt() }.sum()) % 10
}
 
fun checkIsinAlt(a: String): Boolean {
    if (a.length!= 12)
        return false
    val s = mutableListOf<Int>()
    for ((i, c) in a.withIndex()) {
        if (c.isDigit()) {
            if (i < 2)
                return false
            s.add(c.toInt() - 48)
        } else if (c.isUpperCase()) {
            if (i == 11)
                return false
            s.addAll(divmod(c.toInt() - 55, 10))
        } else {
            return false
        }
    }
    var v = s.reversed().drop(2).sum()
    for (k in s.reversed().take(2)) {
        v += if (k * 2 > 9) k * 2 - 9 else k * 2
    }
    return v % 10 == 0
}
 
