fun canFixToRat(points: List<Pair<Int, Int>>): String {
    fun isRat(a: Pair<Int, Int>, b: Pair<Int, Int>, c: Pair<Int, Int>): Boolean {
        val areaPart = (b.first - a.first) * (c.second - a.second) - (c.first - a.first) * (b.second - a.second)
        if (areaPart == 0) return false
        val d1 = (b.first - c.first) * (b.first - c.first) + (b.second - c.second) * (b.second - c.second)
        val d2 = (a.first - c.first) * (a.first - c.first) + (a.second - c.second) * (a.second - c.second)
        val d3 = (a.first - b.first) * (a.first - b.first) + (a.second - b.second) * (a.second - b.second)
        return (d1 == d2 + d3) || (d2 == d1 + d3) || (d3 == d1 + d2)
    }
    val deltas = listOf(Pair(1, 0), Pair(-1, 0), Pair(0, 1), Pair(0, -1))
    for (i in 0 until 3) {
        val (x, y) = points[i]
        for ((dx, dy) in deltas) {
            val newX = x + dx
            val newY = y + dy
            val newPoints = points.toMutableList()
            newPoints[i] = Pair(newX, newY)
            if (isRat(newPoints[0], newPoints[1], newPoints[2])) {
                return "YES"
            }
        }
    }
    return "NO"
};1

fun generateFibonacciSeries(n: Int, t1: Int = 0, t2: Int = 1): List<Int> {
    // Guard clause for non-positive n
    if (n <= 0) {
        return emptyList()
    }

    // If only the first term is requested
    if (n == 1) {
        return listOf(t1)
    }

    // Initialize the sequence with the first two terms
    val sequence = mutableListOf(t1, t2)

    // Generate the remaining terms until the sequence has n elements
    while (sequence.size < n) {
        val nextValue = sequence[sequence.size - 1] + sequence[sequence.size - 2]
        sequence.add(nextValue)
    }
    return sequence
};1

import java.math.BigInteger
