fun updateEntries(reference: List<String>, current: List<String>): Pair<List<String>, List<String>> {
    // Set for O(1) membership checks
    val currentSet = current.toHashSet()
    val missing = mutableListOf<String>()
    val present = mutableListOf<String>()
    for (dn in reference) {
        if (currentSet.contains(dn)) {
            present.add(dn)
        } else {
            missing.add(dn)
        }
    }
    return Pair(missing, present)
