fun allocateBudgets(percentages: List<Int>, totalBudget: Int): List<Int> {
    val allocations = mutableListOf<Int>()
    var remainingBudget = totalBudget
    for (percentage in percentages) {
        val allocation = (totalBudget * (percentage / 100.0)).toInt()
        allocations.add(allocation)
        remainingBudget -= allocation
    }
    if (allocations.size > 0) {
        allocations[allocations.lastIndex] = allocations.last() + remainingBudget
    }
    return allocations
};1

