fun factorial(n: Int, memo: MutableMap<Int, Int> = mutableMapOf()): Int {
    if (n !is Int || n <= 0) {
        throw IllegalArgumentException("n must be a positive integer")
    }
    if (memo.containsKey(n)) {
        return memo[n]!!
    }
    val result = if (n == 1) 1 else n * factorial(n - 1, memo)
    memo[n] = result
    return result
};1

