fun magicSquareOdd(base: Int): Array<IntArray> {
    if (base % 2 == 0 || base < 3)
        throw IllegalArgumentException("base must be odd and > 2")
 
    val grid = Array(base) { IntArray(base) }
    var r = 0
    var number = 0
    val size = base * base
 
    var c = base / 2
    while (number++ < size) {
        grid[r][c] = number
        if (r == 0) {
            if (c == base - 1) {
                r++
            } else {
                r = base - 1
                c++
            }
        } else {
            if (c == base - 1) {
                r--
                c = 0
            } else {
                if (grid[r - 1][c + 1] == 0) {
                    r--
                    c++
                } else {
                    r++
                }
            }
        }
    }
    return grid
};1

