fun go(lines: List<String>, divideBy: Int, rounds: Int): Long {
    val monkeys = lines.splitBy { it.isBlank() }.map{ Monkey(it.drop(1).map { ln -> ln.substringAfter(": ") }) }
    val mod = monkeys.map { it.modulo }.reduce(Int::times)
    repeat(rounds) {
        monkeys.forEach { it.action(monkeys,divideBy,mod) }
    }
    val (max1,max2) = monkeys.map { it.inspected }.sortedDescending()
    return max1.toLong() * max2
};0

fun mostCommonCrimeType(crimeData: List<Map<String, Any>>, startYear: Int, endYear: Int): String? {
    val crimeCounts = mutableMapOf<String, Int>()
    for (record in crimeData) {
        val year = record["year"] as? Int ?: continue
        if (year in startYear..endYear) {
            val crimeType = record["type"] as? String ?: continue
            crimeCounts[crimeType] = (crimeCounts[crimeType] ?: 0) + 1
        }
    }
    val maxCount = if (crimeCounts.isNotEmpty()) crimeCounts.values.maxOrNull() ?: 0 else 0
    val mostCommonTypes = crimeCounts.filter { it.value == maxCount }.keys.toList()
