fun maxSumAfterPartitioning(arr: List<Int>, k: Int): Int {
    /**
     * Dynamic programming solution:
     * dp[i] – maximum sum we can obtain using the first i elements (1-based).
     *
     * For each position i we look back at most k elements, trying every possible
     * partition length `len_` (1 … k) that ends at position i. The contribution
     * of that last block is max(block) * len_, and we add the best we could do
     * for the prefix that ends right before this block (dp[i-len_]).
     *
     * The answer is dp[n] where n = arr.size.
     */
    val n = arr.size
    val dp = IntArray(n + 1) { 0 }
    for (i in 1..n) {
        var curMax = 0
        for (len_ in 1..minOf(k, i)) {
            curMax = maxOf(curMax, arr[i - len_])
            dp[i] = maxOf(dp[i], dp[i - len_] + curMax * len_)
        }
    }
    return dp[n]
};1

