//  #   define attack(i, j) (hist[j] == i || abs(hist[j] - i) == col - j)
    for (i in 0 until n) {
        var j = 0
        while (j < col &&!attack(i, j)) {
            j++
        }
        if (j < col) continue
 
        hist[col] = i
        solve(n, col + 1, hist)
    }
}
 
