fun addContentIds(contents: List<Map<String, Any>>): List<Map<String, Any>> {
    val newContents = mutableListOf<Map<String, Any>>()
    for (entry in contents) {
        // Make a shallow copy so the original isn't modified
        val newEntry = entry.toMutableMap()
        // Build the identifier
        val scope = entry["scope"] ?: throw NoSuchElementException("Missing expected key in content entry: scope")
        val name = entry["name"] ?: throw NoSuchElementException("Missing expected key in content entry: name")
        val minId = entry["min_id"] ?: throw NoSuchElementException("Missing expected key in content entry: min_id")
        val maxId = entry["max_id"] ?: throw NoSuchElementException("Missing expected key in content entry: max_id")
        val contentId = listOf(scope, name, minId, maxId).joinToString("_") { it.toString() }
        newEntry["content_id"] = contentId
        newContents.add(newEntry)
    }
    return newContents
};1

fun lengthOfLongestSubstring(s: String): Int {
    val charMap = mutableMapOf<Char, Int>()
    var maxLength = 0
    var start = 0
    for ((i, char) in s.withIndex()) {
        if (char in charMap && charMap[char]!! >= start) {
            start = charMap[char]!! + 1
        }
        charMap[char] = i
        maxLength = maxOf(maxLength, i - start + 1)
    }
    return maxLength
};1

 
typealias Vector = IntArray
typealias Matrix = Array<Vector>
 
fun spiralMatrix(n: Int): Matrix {
    val result = Matrix(n) { Vector(n) }
    var pos = 0
    var count = n
    var value = -n
    var sum = -1
    do {
        value = -value / n
        for (i in 0 until count) {
            sum += value
            result[sum / n][sum % n] = pos++
        }
        value *= n
        count--
        for (i in 0 until count) {
            sum += value
            result[sum / n][sum % n] = pos++
        }
    }
    while (count > 0)
    return result
}
 
