fun containsNearbyDuplicate(nums: IntArray, k: Int): Boolean {
    var i = 0; var j = 0
    val set = mutableSetOf<Int>()
    while (j < nums.size){
        if (set.contains(nums[j]))
            return true
        set.add(nums[j])
        if (j - i + 1> k){
            set.remove(nums[i])
            i++
        }
        j++
    }
    return false
