fun ways(
    n: Int,
    ds: List<Int>,
    ways: List<Int> = emptyList()
): List<List<Int>> {
    if (n < 0) return emptyList()
    if (n == 0) return listOf(ways)

    val validDs = ds.filter { it <= n }
    return validDs.foldRight(initial = emptyList()) { d, allWays ->
        ways(n = n - d, ways = ways + d, ds = validDs) + allWays
    }
