import kotlin.math.floor
import kotlin.math.log
import kotlin.math.pow
import kotlin.system.exitProcess
 
val LOG_10 = 2.302585092994
 
fun build_oms(s: Int): Array<Array<Int>> {
    if (s % 2 == 0) {
        s += 1
    }
    val q = Array(s) { Array(s) { 0 } }
    var p = 1
    var i = s / 2
    var j = 0
    while (p <= (s * s)) {
        q[i][j] = p
        val ti = i + 1
        val tj = j - 1
        if (ti >= s) {
            i = 0
        } else {
            i = ti
        }
        if (tj < 0) {
            j = s - 1
        } else {
            j = tj
        }
        if (q[i][j]!= 0) {
            i = ti
            j = tj + 1
        }
        p = p + 1
    }
    return q
}
 
fun build_sems(s: Int): Array<Array<Int>> {
    if (s % 2 == 1) {
        s += 1
    }
    while (s % 4 == 0) {
        s += 2
    }
    val q = Array(s) { Array(s) { 0 } }
    val z = s / 2
    val b = z.toDouble().pow(2.0).toInt()
    val c = 2 * b
    val d = 3 * b
    val o = build_oms(z)
    for (j in 0 until z) {
        for (i in 0 until z) {
            val a = o[i][j]
            q[i][j] = a
            q[i + z][j + z] = a + b
            q[i + z][j] = a + c
            q[i][j + z] = a + d
        }
    }
    val lc = z / 2
    val rc = lc
    for (j in 0 until z) {
        for (i in 0 until s) {
            if (i < lc || i > s - rc || (i == lc && j == lc)) {
                if (!(i == 0 && j == lc)) {
                    val t = q[i][j]
                    q[i][j] = q[i][j + z]
                    q[i][j + z] = t
                }
            }
        }
    }
    return q
}
 
fun format_sqr(s: String, l: Int): String {
    var s = s
    for (i in 0 until l - s.length) {
        s = "0" + s
    }
    return s + " "
}
 
fun display(q: Array<Array<Int>>) {
    val s = q.size
    println(" - $s x $s")
    val k = 1 + floor(log(s * s) / LOG_10).toInt()
    for (j in 0 until s) {
        for (i in 0 until s) {
            print(format_sqr(q[i][j].toString(), k))
        }
        println()
    }
    println("Magic sum: ${s * ((s * s) + 1) / 2}")
}
 
