fun dList(n: Int, start: Int): List<List<Int>> {
    val a = IntArray(n)
    for (i in 0 until n) {
        a[i] = i
    }
    a[start - 1] = a[0]
    a[0] = start - 1
    for (i in 1 until n) {
        a[i] = a[i] + 1
    }
    val first = a[1]
    val r = ArrayList<List<Int>>()
    fun recurse(last: Int) {
        if (last == first) {
            val b = ArrayList<Int>()
            for (i in 1 until n) {
                b.add(a[i] + 1)
            }
            r.add(b)
            return
        }
        for (i in last - 1 downTo 0) {
            val t = a[i]
            a[i] = a[last]
            a[last] = t
            recurse(last - 1)
            a[last] = a[i]
            a[i] = t
        }
    }
    recurse(n - 1)
    return r
}
 
