fun reducedLatinSquares(n: Int, echo: Boolean): Int {
    if (n <= 0) {
        if (echo) {
            println("[]")
        }
        return 0
    } else if (n == 1) {
        if (echo) {
            println("[1]")
        }
        return 1
    }
    val rlatin = Array(n) { IntArray(n) }
    for (i in 0 until n) {
        for (j in 0 until n) {
            rlatin[i][j] = j + 1
        }
    }
    var count = 0
    fun recurse(i: Int) {
        val rows = dList(n, i)
        for (r in 0 until rows.size) {
            for (j in 0 until n) {
                rlatin[i - 1][j] = rows[r][j]
            }
            var justContinue = false
            var k = 0
            while (!justContinue && k < i - 1) {
                for (j in 1 until n) {
                    if (rlatin[k][j] == rlatin[i - 1][j]) {
                        if (r < rows.size - 1) {
                            justContinue = true
                            break
                        }
                        if (i > 2) {
                            return
                        }
                    }
                }
                k++
            }
            if (!justContinue) {
                if (i < n) {
                    recurse(i + 1)
                } else {
                    count++
                    if (echo) {
                        printSquare(rlatin.map { it.toList() }, n)
                    }
                }
            }
        }
    }
    recurse(2)
    return count
}
 
