fun distributeApples(n: Int, arthurLikes: List<Int>, alexanderLikes: List<Int>): List<Int> {
    val arthur = arthurLikes.toSet()
    val alexander = alexanderLikes.toSet()
    val result = mutableListOf<Int>()
    for (i in 1..n) {
        when {
            i in arthur && i !in alexander -> result.add(1)
            i in alexander && i !in arthur -> result.add(2)
            else -> result.add(1) // liked by both, give to Arthur
        }
    }
    return result
