fun isValidIPv4(s: String): Boolean {
    val parts = s.split(".")
    if (parts.size != 4) {
        return false
    }
    for (part in parts) {
        if (part.isEmpty() || part.any { !it.isDigit() }) {
            return false
        }
        if (part.length > 1 && part[0] == '0') {
            return false
        }
        val num = part.toIntOrNull() ?: return false
        if (num < 0 || num > 255) {
            return false
        }
    }
    return true
};1

