fun sameDigits(n: Int, b: Int): Boolean {
    var f = n % b
    n /= b
    while (n > 0) {
        if (n % b!= f) {
            return false
        }
        n /= b
    }
    return true
}
 
fun isBrazilian(n: Int): Boolean {
    if (n < 7) {
        return false
    }
    if (n % 2 == 0 && n >= 8) {
        return true
    }
    for (b in 2 until n - 1) {
        if (sameDigits(n, b)) {
            return true
        }
    }
    return false
}
 
fun isPrime(n: Int): Boolean {
    when {
        n < 2 -> return false
        n % 2 == 0 -> return n == 2
        n % 3 == 0 -> return n == 3
        else -> {
            var d = 5
            while (d * d <= n) {
                if (n % d == 0) {
                    return false
                }
                d += 2
                if (n % d == 0) {
                    return false
                }
                d += 4
            }
            return true
        }
    }
}
 
