fun longestCommonSubstringAtSamePosition(s1: String, s2: String, s3: String): String {
    var maxLength = 0
    var startIndex = 0
    val minLen = minOf(s1.length, s2.length, s3.length)
    for (i in 0 until minLen) {
        val maxPossibleL = listOf(s1.length - i, s2.length - i, s3.length - i).minOrNull() ?: 0
        for (l in maxPossibleL downTo 1) {
            val substr1 = s1.substring(i, i + l)
            val substr2 = s2.substring(i, i + l)
            val substr3 = s3.substring(i, i + l)
            if (substr1 == substr2 && substr2 == substr3) {
                if (l > maxLength) {
                    maxLength = l
                    startIndex = i
                }
                break
            }
        }
    }
    return if (maxLength > 0) s1.substring(startIndex, startIndex + maxLength) else ""
};1

