fun convertDecimal(n: Any?, base: Any?): String {
    if (n !is Int || base !is Int) {
        return "Invalid input"
    }
    if (n < 0 || base < 2 || base > 16) {
        return "Invalid input"
    }
    if (n == 0) {
        return "0"
    }
    var num = n
    val digits = mutableListOf<Char>()
    while (num > 0) {
        val rem = num % base
        if (rem < 10) {
            digits.add('0' + rem)
        } else {
            digits.add('A' + (rem - 10))
        }
        num /= base
    }
    return digits.reversed().joinToString("")
};1

class ListNode(var `val`: Int = 0, var next: ListNode? = null) {
    companion object {
        fun fromList(lst: List<Int>): ListNode? {
            val dummy = ListNode(0)
            var curr = dummy
            for (v in lst) {
                curr.next = ListNode(v)
                curr = curr.next!!
            }
            return dummy.next
        }
    }
    fun toList(): List<Int> {
        val out = mutableListOf<Int>()
        var curr: ListNode? = this
        while (curr != null) {
            out.add(curr.`val`)
            curr = curr.next
        }
        return out
    }
}

fun middleNode(head: ListNode?): ListNode? {
    var slow = head
    var fast = head
    if (head == null) {
        return null
    }
    while (fast?.next != null && fast.next?.next != null) {
        slow = slow?.next
        fast = fast.next?.next
    }
    return slow
};1

