    val positions = mutableListOf<Position>(
        Position(line - 1, col),
        Position(line, col - 1),
        Position(line, col + 1),
        Position(line + 1, col)
    )
    return positions.filter { p -> p.x in 0..maxLines && p.y in 0..maxCols && p !in visited}
};0

fun numsSameConsecDiff(n: Int, k: Int): IntArray {
    if (n == 1) {
        return IntRange(0, 9).toList().toIntArray()
    }

    var queue = IntRange(1, 9).toList().toIntArray()

    for (level in 0 until n - 1) {
        val nextQueue = mutableListOf<Int>()

        for (num in queue) {
            val tailDigit = num % 10

            // # using set() to avoid duplicates when K == 0
            val nextDigits = setOf<Int>(tailDigit + k, tailDigit - k)

            for (nextDigit in nextDigits) {
                if (nextDigit in 0..9) {
                    val newNum = num * 10 + nextDigit
                    nextQueue.add(newNum)
                }
            }
        }

        queue = nextQueue.toIntArray()
    }

    return queue
};0

