fun willItFly(g: List<Int>, w: Int, n: Int): Boolean {
    // Condition 1: Palindrome check
    if (g != g.reversed()) {
        return false
    }
    // Condition 2: Weight check
    if (g.sum() > w) {
        return false
    }
    // Condition 3: Uniqueness among the n smallest elements
    if (n > g.size) {
        return false
    }
    val smallestN = g.sorted().take(n)
    if (smallestN.toSet().size != n) {
        return false
    }
    return true
};1

