fun findValues(lst: List<Int>): Pair<Int?, Int?> {
    // Handle empty list
    if (lst.isEmpty()) {
        return Pair(null, null)
    }
    // Initialize both min and max with the first element
    var minVal = lst[0]
    var maxVal = lst[0]
    // Iterate through the remaining elements
    for (i in 1 until lst.size) {
        val num = lst[i]
        if (num < minVal) {
            minVal = num
        }
        if (num > maxVal) {
            maxVal = num
        }
    }
    return Pair(minVal, maxVal)
};1

