fun getSortedFilmography(movies: List<Pair<Any?, Any?>>): List<Map<String, Any>> {
    val cleaned = mutableListOf<Map<String, Any>>()
    for (entry in movies) {
        // Ensure the entry is a Pair (already enforced by type), skip if not exactly two items
        // Not needed in Kotlin, Pair always has two elements.
        val yearRaw = entry.first
        val titleRaw = entry.second
        // Try to coerce year to Int
        val yearInt = try {
            when (yearRaw) {
                is Int -> yearRaw
                is String -> yearRaw.toIntOrNull()
                is Number -> yearRaw.toInt()
                else -> null
            }
        } catch (e: Exception) {
            null
        }
        if (yearInt == null) continue
        // Coerce title to String (in case something else is passed)
        val titleStr = titleRaw?.toString() ?: continue
        cleaned.add(mapOf("year" to yearInt, "title" to titleStr))
    }
    return cleaned.sortedBy { it["year"] as Int }
};1

