fun removeDuplicatesFromFile(filePath: String) {
    val file = File(filePath)
    val lines = if (file.exists()) file.readLines() else emptyList()
    val seen = mutableSetOf<String>()
    val uniqueLines = mutableListOf<String>()
    for (line in lines) {
        if (!seen.contains(line)) {
            uniqueLines.add(line)
            seen.add(line)
        }
    }
    file.writeText(uniqueLines.joinToString("\n"))
    if (uniqueLines.isNotEmpty()) {
        // restore trailing newline if file originally ended with one
        if (lines.isNotEmpty() && lines.last().isEmpty()) {
            file.appendText("\n")
        } else if (lines.isNotEmpty() && file.readText().lastOrNull() != '\n') {
            file.appendText("\n")
        }
    }
};1

import java.io.BufferedReader
