typealias Timestamp = String
 
fun computeUsage(lines: Iterator<String>): Pair<Int, List<Timestamp>> {
    val timestamps = ArrayList<Timestamp>()
    var current = 0
    var maximum = 0
 
    while (lines.hasNext()) {
        val line = lines.next()
        if (line.startsWith("License IN")) {
            current--
        } else if (line.startsWith("License OUT")) {
            current++
 
            if (maximum <= current) {
                val date = line.split(" ".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()[3]
 
                if (maximum < current) {
                    maximum = current
                    timestamps.clear()
                }
 
                timestamps.add(date)
            }
        }
    }
 
    return Pair(maximum, timestamps)
}
 
