fun filterAcronyms(acronyms: List<String>, tags: List<String> = listOf()): List<String> {
    // If no tags are supplied, return all acronyms unchanged
    if (tags.isEmpty()) {
        return acronyms.toList()
    }

    // Pre-compute upper-cased tags for case-insensitive comparison
    val upperTags = tags.map { it.uppercase() }

    val filtered = mutableListOf<String>()
    for (ac in acronyms) {
        val acUp = ac.uppercase()
        // Keep acronym if any tag is a substring of it
        if (upperTags.any { tag -> tag in acUp }) {
            filtered.add(ac)
        }
    }
    return filtered
};1

