fun mergeLists(list1: List<Any>, list2: List<Any>, order: String = "asc"): List<Any> {
    val merged = (list1 + list2).toMutableList()
    when (order) {
        "asc" -> {
            try {
                merged.sortWith(compareBy { it as Comparable<Any> })
            } catch (e: Exception) {
                throw IllegalArgumentException("List elements are not comparable.")
            }
        }
        "desc" -> {
            try {
                merged.sortWith(compareByDescending { it as Comparable<Any> })
            } catch (e: Exception) {
                throw IllegalArgumentException("List elements are not comparable.")
            }
        }
        else -> throw IllegalArgumentException("Order must be 'asc' or 'desc'")
    }
    return merged
};1

