import kotlin.math.max
import kotlin.math.min
 
fun jaro(str1: String, str2: String): Double {
    // length of the strings
    val str1Len = str1.length
    val str2Len = str2.length
 
    // if both strings are empty return 1
    // if only one of the strings is empty return 0
    if (str1Len == 0) return if (str2Len == 0) 1.0 else 0.0
 
    // max distance between two chars to be considered matching
    // floor() is ommitted due to integer division rules
    val matchDistance = max(str1Len, str2Len) / 2 - 1
 
    // arrays of bools that signify if that char in the matching string has a match
    val str1Matches = BooleanArray(str1Len)
    val str2Matches = BooleanArray(str2Len)
 
    // number of matches and transpositions
    var matches = 0.0
    var transpositions = 0.0
 
    // find the matches
    for (i in 0 until str1Len) {
        // start and end take into account the match distance
        val start = max(0, i - matchDistance)
        val end = min(i + matchDistance + 1, str2Len)
 
        for (k in start until end) {
            // if str2 already has a match continue
            if (str2Matches[k]) continue
            // if str1 and str2 are not
            if (str1[i]!= str2[k]) continue
            // otherwise assume there is a match
            str1Matches[i] = true
            str2Matches[k] = true
            matches++
            break
        }
    }
 
    // if there are no matches return 0
    if (matches == 0.0) return 0.0
 
    // count transpositions
    var k = 0
    for (i in 0 until str1Len) {
        // if there are no matches in str1 continue
        if (!str1Matches[i]) continue
        // while there is no match in str2 increment k
        while (!str2Matches[k]) k++
        // increment transpositions
        if (str1[i]!= str2[k]) transpositions++
        k++
    }
 
    // divide the number of transpositions by two as per the algorithm specs
    // this division is valid because the counted transpositions include both
    // instances of the transposed characters.
    transpositions /= 2.0
 
    // return the Jaro distance
    return ((matches / str1Len) +
            (matches / str2Len) +
            ((matches - transpositions) / matches)) / 3.0
}
 
fun main() {
    println(jaro("MARTHA", "MARHTA"))
    println(jaro("DIXON", "DICKSONX"))
    println(jaro("JELLYFISH", "SMELLYFISH"))
};1

fun maxSubarraySum(arr: List<Int>): Int {
    if (arr.isEmpty()) {
        return 0
    }
    val hasPositive = arr.any { it > 0 }
    if (!hasPositive) {
        return 0
    }
    var maxCurrent = Int.MIN_VALUE
    var maxGlobal = Int.MIN_VALUE
    for (num in arr) {
        maxCurrent = if (maxCurrent < 0) num else maxCurrent + num
        if (maxCurrent > maxGlobal) {
            maxGlobal = maxCurrent
        }
    }
    return maxOf(maxGlobal, 0)
}

fun maxSubarraySumWithLengthLimit(arr: List<Int>, L: Int): Int {
    if (arr.isEmpty()) {
        return 0
    }
    val n = arr.size
    var maxSum = Int.MIN_VALUE
    var foundPositive = false
    for (start in 0 until n) {
        var sum = 0
        var containsPositive = false
        for (len in 1..L) {
            val end = start + len - 1
            if (end >= n) break
            sum += arr[end]
            if (arr[end] > 0) {
                containsPositive = true
            }
            if (containsPositive && sum > maxSum) {
                maxSum = sum
                foundPositive = true
            }
        }
    }
    return if (foundPositive && maxSum > 0) maxSum else 0
};1

// Returns a singleton instance of an in-memory "animation factory".
// The first time this function is invoked, it builds the factory object.
// Subsequent calls return the same object, ensuring the factory is never re-instantiated.

class AnimationFactory private constructor() {
    // Pretend we are doing an expensive initialisation here
    private val tools: Map<String, Any> = mapOf(
        "fade_in" to { duration: Double -> "Fading in over ${duration}s" },
        "fade_out" to { duration: Double -> "Fading out over ${duration}s" },
        "tween" to { start: Double, end: Double, t: Double -> start + (end - start) * t }
    )

    // Retrieve a tool by name, or null if it does not exist
    fun getTool(name: String): Any? = tools[name]

    // Return a list of all available tool names
    fun listTools(): List<String> = tools.keys.toList()

    // Allow attribute-like access to tools
    operator fun get(name: String): Any =
        getTool(name) ?: throw NoSuchElementException("No animation tool named '$name'")

    fun toString(): String = "<AnimationFactory tools=${listTools()}>"

    companion object {
        @Volatile
        private var instance: AnimationFactory? = null

        fun getInstance(): AnimationFactory {
            return instance ?: synchronized(this) {
                instance ?: AnimationFactory().also { instance = it }
            }
        }
    }
}

fun create_animation_factory(): AnimationFactory = AnimationFactory.getInstance();1

