import java.util.ArrayList
import java.util.Collections
import java.util.Comparator
import java.util.List
 
fun main(args: Array<String>) {
    val points = listOf(
        Point(16, 3), Point(12, 17), Point(0, 6), Point(-4, -6), Point(16, 6),
        Point(16, -7), Point(16, -3), Point(17, -4), Point(5, 19), Point(19, -8),
        Point(3, 16), Point(12, 13), Point(3, -4), Point(17, 5), Point(-3, 15),
        Point(-3, -9), Point(0, 11), Point(-9, -3), Point(-4, -2), Point(12, 10)
    )
 
    val hull = convexHull(points)
    println("Convex Hull: $hull")
}
 
fun convexHull(points: List<Point>): List<Point> {
    if (points.isEmpty()) return emptyList()
 
    val sortedPoints = points.sortedWith(Comparator { a, b ->
        if (a.x < b.x) -1 else 0
    })
 
    val hull = ArrayList<Point>()
 
    // lower hull
    for (pt in sortedPoints) {
        while (hull.size >= 2 &&!ccw(hull[hull.size - 2], hull[hull.size - 1], pt)) {
            hull.removeAt(hull.size - 1)
        }
        hull.add(pt)
    }
 
    // upper hull
    val t = hull.size + 1
    for (i in sortedPoints.size - 1 downTo 0) {
        val pt = sortedPoints[i]
        while (hull.size >= t &&!ccw(hull[hull.size - 2], hull[hull.size - 1], pt)) {
            hull.removeAt(hull.size - 1)
        }
        hull.add(pt)
    }
 
    hull.removeAt(hull.size - 1)
    return hull
}
 
fun ccw(a: Point, b: Point, c: Point): Boolean {
    return ((b.x - a.x) * (c.y - a.y)) > ((b.y - a.y) * (c.x - a.x))
}
 
data class Point(val x: Int, val y: Int)
 
