class Polynomial(vararg val coefs: Int) {
    operator fun plus(other: Polynomial): Polynomial {
        val coefs = ArrayList<Int>()
        for (i in 0..Math.max(this.coefs.size, other.coefs.size) - 1) {
            coefs.add(this.coefs.getOrNull(i)?: 0 + other.coefs.getOrNull(i)?: 0)
        }
        return Polynomial(*coefs.toIntArray())
    }

    operator fun minus(other: Polynomial): Polynomial {
        val coefs = ArrayList<Int>()
        for (i in 0..Math.max(this.coefs.size, other.coefs.size) - 1) {
            coefs.add(this.coefs.getOrNull(i)?: 0 - other.coefs.getOrNull(i)?: 0)
        }
        return Polynomial(*coefs.toIntArray())
    }

    operator fun times(other: Polynomial): Polynomial {
        val coefs = IntArray(this.coefs.size + other.coefs.size - 1)
        for (i in 0..this.coefs.size - 1) {
            for (j in 0..other.coefs.size - 1) {
                coefs[i + j] += this.coefs[i] * other.coefs[j]
            }
        }
        return Polynomial(*coefs)
    }

    operator fun times(other: Int): Polynomial {
        val coefs = IntArray(this.coefs.size)
        for (i in 0..this.coefs.size - 1) {
            coefs[i] = this.coefs[i] * other
        }
        return Polynomial(*coefs)
    }

    operator fun div(other: Polynomial): Polynomial {
        val coefs = IntArray(this.coefs.size - other.coefs.size + 1)
        val dividend = this.coefs.copyOf()
        for (i in 0..this.coefs.size - other.coefs.size) {
            coefs[i] = dividend[i] / other.coefs[0]
            for (j in 0..other.coefs.size - 1) {
                dividend[i + j] -= coefs[i] * other.coefs[j]
            }
        }
        return Polynomial(*coefs)
    }

    operator fun div(other: Int): Polynomial {
        val coefs = IntArray(this.coefs.size)
        for (i in 0..this.coefs.size - 1) {
            coefs[i] = this.coefs[i] / other
        }
        return Polynomial(*coefs);1

fun maxProfit(prices: List<Int>): Int {
    // Calculate the maximum profit from a single buy-and-sell operation.
    if (prices.isEmpty()) {
        // The prompt guarantees at least one element, but guard anyway.
        return 0
    }

    var minPriceSoFar = prices[0]
    var bestProfit = 0

    for (i in 1 until prices.size) {
        val price = prices[i]
        // If we sold today, profit would be price - minPriceSoFar
        val potentialProfit = price - minPriceSoFar
        // Update the best profit seen so far
        if (potentialProfit > bestProfit) {
            bestProfit = potentialProfit
        }
        // Update the minimum purchase price seen so far
        if (price < minPriceSoFar) {
            minPriceSoFar = price
        }
    }

    return bestProfit
};1

