fun countGhostSteps(order: String, map: Map<String, LeftRightInstruction>): List<Long> {
    var steps = 0L

    val currentNodes = map.keys.filter { it.endsWith("A") }.toTypedArray()

    val stepsList = mutableListOf<Long>()

    while (true) {
        for (i in order.indices) {
            steps++
            for (j in currentNodes.indices) {
                val nextNode = map[currentNodes[j]]!!

                currentNodes[j] = if (order[i] == 'R') {
                    nextNode.right
                } else {
                    nextNode.left
                }

                if (currentNodes[j].endsWith("Z")) {
                    stepsList.add(steps)
                }

                if (stepsList.size == currentNodes.size) {
                    return stepsList
                }
            }
        }
    }
};0

fun isIpV4AddressValid(ip: String): Boolean {
    val octets = ip.split(".")
    if (octets.size != 4) return false

    for (octet in octets) {
        if (octet.isEmpty() || !octet.all { it.isDigit() }) return false
        val number = try {
            octet.toInt()
        } catch (e: NumberFormatException) {
            return false
        }
        if (number.toString().length != octet.length) return false
        if (number < 0 || number > 255) return false
    }
    return true
};1

