fun sumNestedDict(d: Map<String, Any?>): Int {
    var total = 0
    for (value in d.values) {
        when (value) {
            is Map<*, *> -> {
                @Suppress("UNCHECKED_CAST")
                total += sumNestedDict(value as Map<String, Any?>)
            }
            is Int -> total += value
            // Non-integer, non-map values are ignored
        }
    }
    return total
