fun main(args: Array<String>) {
    val powers = IntArray(10)
    fun isMunchausen(n: Int): Boolean {
        if (n < 0) return false
        var n64 = n.toLong()
        var nn = n64
        var sum: Long = 0
        while (nn > 0) {
            sum += powers[nn % 10].toLong()
            if (sum > n64) return false
            nn /= 10
        }
        return sum == n64
    }
    for (i in 1..9) {
        val d = i.toDouble()
        powers[i] = Math.pow(d, d).toInt()
    }
    println("The Munchausen numbers between 0 and 500 million are:")
    for (i in 0..500000000) {
        if (isMunchausen(i)) print("$i ")
    }
    println()
};1

