fun <T> sc_rank(iterable: List<T>, start: Int = 1): List<Pair<Int, T>> {
    var lastresult: T? = null
    var lastrank: Int? = null
    return iterable.mapIndexed { n, item ->
        if (item == lastresult) {
            Pair(lastrank!!, item)
        } else {
            lastresult = item
            lastrank = n + start
            Pair(lastrank!!, item)
        }
    }
}
 
fun <T> mc_rank(iterable: List<T>, start: Int = 1): List<Pair<Int, T>> {
    var lastresult: T? = null
    val fifo = LinkedList<T>()
    return iterable.mapIndexed { n, item ->
        if (item == lastresult) {
            fifo.add(item)
        } else {
            while (fifo.isNotEmpty()) {
                Pair(n + start, fifo.removeFirst())
            }
            lastresult = item
            fifo.add(item)
        }
    }.plus(IntStream.range(0, fifo.size).mapToObj { Pair(n + start, fifo.removeFirst()) }.collect(Collectors.toList()))
}
 
fun <T> d_rank(iterable: List<T>, start: Int = 1): List<Pair<Int, T>> {
    var lastresult: T? = null
    var lastrank: Int? = start - 1
    return iterable.map {
        if (it == lastresult) {
            Pair(lastrank!!, it)
        } else {
            lastresult = it
            lastrank = lastrank!! + 1
            Pair(lastrank!!, it)
        }
    }
};1

