fun chooseItem(weight: Int, id: Int, cache: MutableMap<Pair<Int, Int>, Pair<Int, List<Int>>>): Pair<Int, List<Int>> {
  if (id < 0) {
    return Pair(0, listOf())
  }
 
  val k = Pair(weight, id)
  if (cache.containsKey(k)) {
    return cache[k]!!
  }
  val value = items[id].value
  var bestV = 0
  var bestList = listOf<Int>()
  for (i in 0..items[id].count) {
    val wlim = weight - i * items[id].weight
    if (wlim < 0) {
      break
    }
    val (val, taken) = chooseItem(wlim, id - 1, cache)
    if (val + i * value > bestV) {
      bestV = val + i * value
      bestList = taken + listOf(i)
    }
  }
  cache[k] = Pair(bestV, bestList)
  return Pair(bestV, bestList)
}
 
