fun bucketSort(arr: List<Int>, numBuckets: Int): List<Int> {
    if (numBuckets <= 0) {
        throw IllegalArgumentException("numBuckets must be a positive integer")
    }

    val minVal = arr.minOrNull()!!
    val maxVal = arr.maxOrNull()!!

    if (minVal == maxVal) {
        return arr.toList()
    }

    val rangeSize = maxVal - minVal + 1
    val bucketSize = maxOf(1, (rangeSize + numBuckets - 1) / numBuckets)

    val buckets = MutableList(numBuckets) { mutableListOf<Int>() }

    for (value in arr) {
        var idx = (value - minVal) / bucketSize
        if (idx >= numBuckets) idx = numBuckets - 1
        buckets[idx].add(value)
    }

    val sortedArr = mutableListOf<Int>()
    for (bucket in buckets) {
        if (bucket.isNotEmpty()) {
            bucket.sort()
            sortedArr.addAll(bucket)
        }
    }

    return sortedArr
};1

fun findMedian(numbers: List<Double>): Double {
    val sortedNumbers = numbers.sorted()
    val n = sortedNumbers.size
    if (n == 0) {
        throw IllegalArgumentException("Cannot compute median of empty list")
    }
    return if (n % 2 == 1) {
        sortedNumbers[n / 2]
    } else {
        (sortedNumbers[(n / 2) - 1] + sortedNumbers[n / 2]) / 2
    }
};1

fun getPrimeFactors(numbers: List<Int>): List<Int> {
    fun isPrime(n: Int): Boolean {
        if (n <= 1) return false
        if (n == 2) return true
        if (n % 2 == 0) return false
        var i = 3
        while (i * i <= n) {
            if (n % i == 0) return false
            i += 2
        }
        return true
    }

    fun getPrimesOf(n: Int): Set<Int> {
        var num = n
        val factors = mutableSetOf<Int>()
        if (num < 2) return factors
        if (num % 2 == 0) {
            factors.add(2)
            while (num % 2 == 0) {
                num /= 2
            }
        }
        var i = 3
        while (i * i <= num) {
            if (num % i == 0) {
                factors.add(i)
                while (num % i == 0) {
                    num /= i
                }
            }
            i += 2
        }
        if (num > 2) {
            factors.add(num)
        }
        return factors
    }

    val primesInInput = mutableSetOf<Int>()
    for (num in numbers) {
        if (isPrime(num)) {
            primesInInput.add(num)
        }
    }
    val allFactors = mutableSetOf<Int>()
    for (num in numbers) {
        val factors = getPrimesOf(num)
        allFactors.addAll(factors)
    }
    val result = allFactors - primesInInput
    return result.sorted()
};1

fun solve(): Int {
    readLn()
    val a = readInts().sorted()
    if (a.size == 2) return 0
    var ans = minOf(makeEqual(a.drop(1)), makeEqual(a.dropLast(1))).coerceInInt()
    var i = 1
    var j = a.lastIndex - 1
    val borders = a[0] + a.last()
    while (i < j) {
        ans = minOf(ans, abs(a[i] + a[j] - borders))
        if (a[i] + a[j] < borders) i++ else j--
    }
    return ans
};0

fun validateLatinScript(inputData: Any?): List<String> {
    // 1. Directly handle list/array
    when (inputData) {
        is List<*> -> {
            return inputData.mapNotNull { it?.toString() }
        }
        is Array<*> -> {
            return inputData.mapNotNull { it?.toString() }
        }
        is String -> {
            // 2. Validate string input
            if (inputData.isEmpty() || inputData.length > 33) {
                return emptyList()
            }
            // Only letters, commas, and (optional) spaces are allowed
            val regex = Pattern.compile("[A-Za-z,\\s]*")
            if (!regex.matcher(inputData).matches()) {
                return emptyList()
            }
            if (inputData.contains(",")) {
                // Split on commas, strip spaces, drop empties
                val tokens = inputData.split(",")
                    .map { it.trim() }
                    .filter { it.isNotEmpty() }
                if (!tokens.all { it.length == 1 && it.all { ch -> ch.isLetter() } }) {
                    return emptyList()
                }
                return tokens
            } else {
                // No commas → treat every character as individual letter
                if (!inputData.all { it.isLetter() }) {
                    return emptyList()
                }
                return inputData.map { it.toString() }
            }
        }
        else -> {
            // 3. Unsupported type → invalid
            return emptyList()
        }
    }
};1

 
