// We will represent tuples in Kotlin as List<Any> for generality
// since Python tuples can have arbitrary lengths and can be nested arbitrarily.
// The problem requires working on nested tuples (possibly deeply nested) where tuples are expressed as List<Any> in Kotlin.

fun removeTuples(t: Any, condition: (Any) -> Boolean): Any {
    val REMOVE = Any() // Sentinel object

    fun _process(obj: Any): Any {
        // Only List<*> (as tuple-like) may be traversed or removed
        if (obj !is List<*>) {
            return obj
        }
        val shouldRemove = try {
            condition(obj)
        } catch (e: Exception) {
            false // If the condition throws, keep the tuple
        }
        if (shouldRemove) {
            return REMOVE
        }
        val processedItems = mutableListOf<Any>()
        for (item in obj) {
            val res = _process(item!!)
            if (res !== REMOVE) {
                processedItems.add(res)
            }
        }
        return processedItems
    }
    val result = _process(t)
    return if (result === REMOVE) emptyList<Any>() else result
};1

