import java.io.BufferedReader
import java.io.IOException
import java.io.InputStreamReader
import java.io.PrintStream
import java.net.ServerSocket
import java.net.Socket
import java.util.ArrayList
import java.util.concurrent.locks.Lock
import java.util.concurrent.locks.ReentrantLock
import kotlin.concurrent.thread
 
class ChatServer(port: Int, address: String, maxConnections: Int, errorStream: PrintStream, info: Boolean) {
    private val serverSocket: ServerSocket = ServerSocket(port, maxConnections, java.net.InetAddress.getByName(address))
    private val chatters: MutableList<Socket> = ArrayList()
    private val mutex: Lock = ReentrantLock()
    private val errorStream: PrintStream = errorStream
    private val info: Boolean = info
 
    fun start() {
        thread(start = true) {
            while (true) {
                val socket = serverSocket.accept()
                thread(start = true) {
                    serve(socket)
                }
            }
        }
    }
 
    fun serve(socket: Socket) {
        val input = BufferedReader(InputStreamReader(socket.getInputStream()))
        val output = PrintStream(socket.getOutputStream())
        output.print("Name: ")
        val name = input.readLine()?: return
        output.println()
        broadcast("--+ $name has joined +--")
        mutex.lock()
        chatters.add(socket)
        mutex.unlock()
        while (true) {
            val message = input.readLine()?: break
            broadcast("$name> $message")
        }
        broadcast("--+ $name has left +--")
    }
 
    fun broadcast(message: String) {
        if (info) {
            errorStream.println(message)
        }
        mutex.lock()
        for (chatter in chatters) {
            try {
                chatter.getOutputStream().write((message + "\r\n").toByteArray())
            } catch (e: IOException) {
                chatters.remove(chatter)
            }
        }
        mutex.unlock()
    }
}
 
fun main(args: Array<String>) {
    ChatServer(7000, "0.0.0.0", 100, System.err, true).start()
};1

fun buildRules(rules: List<String>): Rule {
    val rulePattern = Regex("""(\d+): (.+)""")
    val ruleMap = mutableMapOf<Int, Lazy<Rule>>()

    ruleMap += rules.associate { s ->
        val (_, id, text) = rulePattern.matchEntire(s)?.groupValues ?: error("invalid rule '$s'")

        id.toInt() to lazy {
            Rule.parse(text, ruleMap)
        }
    }

    return ruleMap[0]!!.value
};0

fun minRemovals(nums: List<Int>, k: Int): Int {
    if (nums.isEmpty()) return 0
    val sortedNums = nums.sorted()
    val n = sortedNums.size
    var maxSize = 0
    for (right in 0 until n) {
        val target = sortedNums[right] - k
        // Binary search for the leftmost index >= target
        val left = lowerBound(sortedNums, 0, right + 1, target)
        val currentSize = right - left + 1
        if (currentSize > maxSize) {
            maxSize = currentSize
        }
    }
    return n - maxSize
}

// Helper to find the lower bound, similar to bisect_left
fun lowerBound(arr: List<Int>, start: Int, end: Int, target: Int): Int {
    var low = start
    var high = end
    while (low < high) {
        val mid = (low + high) ushr 1
        if (arr[mid] < target) {
            low = mid + 1
        } else {
            high = mid
        }
    }
    return low
};1

