fun processImage(binaryImage: List<List<Int>>, iterations: Int, operation: String): List<List<Int>> {
    if (operation != "erode" && operation != "dilate") {
        throw IllegalArgumentException("operation must be either 'erode' or 'dilate'")
    }
    if (iterations <= 0) {
        return binaryImage.map { it.toList() } // shallow copy for each row
    }
    val rows = binaryImage.size
    val cols = binaryImage[0].size
    val neighOffsets = listOf(
        Pair(-1, -1), Pair(-1, 0), Pair(-1, 1),
        Pair(0, -1),  Pair(0, 0),  Pair(0, 1),
        Pair(1, -1),  Pair(1, 0),  Pair(1, 1)
    )
    var current = binaryImage.map { it.toMutableList() }
    repeat(iterations) {
        val nextImg = MutableList(rows) { MutableList(cols) { 0 } }
        for (r in 0 until rows) {
            for (c in 0 until cols) {
                if (operation == "erode") {
                    var value = 1
                    for ((dr, dc) in neighOffsets) {
                        val nr = r + dr
                        val nc = c + dc
                        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || current[nr][nc] == 0) {
                            value = 0
                            break
                        }
                    }
                    nextImg[r][c] = value
                } else { // dilate
                    var value = 0
                    for ((dr, dc) in neighOffsets) {
                        val nr = r + dr
                        val nc = c + dc
                        if (nr in 0 until rows && nc in 0 until cols && current[nr][nc] == 1) {
                            value = 1
                            break
                        }
                    }
                    nextImg[r][c] = value
                }
            }
        }
        current = nextImg
    }
    return current
};1

