    for (num in nums.reversed()) {
        // O(logN)
        update(1, 0, SIZE, num + OFFSET, 1)
        // O(logN)
        ret.add(query(1, 0, SIZE, 0, num + OFFSET - 1))
    }
    return ret.reversed()
