fun jacobi(A: Int, N: Int): Int {
    assert(N > 0 && N and 1 == 1)
    var a = A % N
    var n = N
    var result = 1
    while (a != 0) {
        var aMod4 = a and 3
        while (aMod4 == 0) {    // remove factors of four
            a = a shr 2
            aMod4 = a and 3
        }
        if (aMod4 == 2) {       // if even
            a = a shr 1         // remove factor 2 and possibly change sign
            if ((n and 7).let { it == 3 || it == 5 })
                result = -result
            aMod4 = a and 3
        }
        if (aMod4 == 3 && n and 3 == 3)
            result = -result
        a = (n % a).also { n = a }
    }
    return if (n == 1) result else 0
};0

fun maxNonAdjacentSum(arr: List<Int>): Int {
    // Disse to variablene holder henholdsvis:
    //  - incl: beste sum som INKLUDERER det nåværende elementet.
    //  - excl: beste sum som EKSKLUDERER det nåværende elementet.
    var incl = 0
    var excl = 0
    for (num in arr) {
        // Ignorer ikke-positive tall for summen.
        val value = if (num > 0) num else 0
        // Hvis vi ekskluderer nåværende element, er det beste vi kan ha max(incl, excl)
        val newExcl = maxOf(incl, excl)
        // Hvis vi inkluderer nåværende element, må vi ta forrige excl
        incl = excl + value
        // Oppdater excl for neste iterasjon
        excl = newExcl
    }
    return maxOf(incl, excl)
};1

