var c: BooleanArray = BooleanArray(0)
 
fun sieve(ss: Int) {
    c = BooleanArray(ss)
    c[1] = true
    var p = 2
    while (true) {
        val p2 = p * p
        if (p2 >= ss) {
            break
        }
        for (i in p2 until ss step p) {
            c[i] = true
        }
        while (true) {
            p++
            if (!c[p]) {
                break
            }
        }
    }
}
 
fun search(digits: Int, pot: Int, s: String, truncFunc: (Int, Int) -> Int): Boolean {
    var n = pot - 1
    var pot = pot / 10
smaller@ while (n >= pot) {
        var tn = n
        var tp = pot
        while (tp > 0) {
            if (tn < tp || c[tn]) {
                continue@smaller
            }
            tn = truncFunc(tn, tp)
            tp /= 10
        }
        println("max $s truncatable: $n")
        return true
    }
    if (digits > 1) {
        return search(digits - 1, pot, s, truncFunc)
    }
    return false
};1

class TreeNode(
    var `val`: Int = 0,
    var left: TreeNode? = null,
    var right: TreeNode? = null
)

fun isBalanced(root: TreeNode?): Boolean {
    // Helper that returns Pair(balanced, height)
    fun check(node: TreeNode?): Pair<Boolean, Int> {
        if (node == null) {
            return Pair(true, -1)
        }

        val (leftBalanced, leftHeight) = check(node.left)
        if (!leftBalanced) return Pair(false, 0)

        val (rightBalanced, rightHeight) = check(node.right)
        if (!rightBalanced) return Pair(false, 0)

        val balanced = kotlin.math.abs(leftHeight - rightHeight) <= 1
        val height = maxOf(leftHeight, rightHeight) + 1
        return Pair(balanced, height)
    }
    return check(root).first
};1

fun calculateDiceCoefficient(counts: Map<String, Int>): Double {
    // Retrieve counts, defaulting to 0 if a key is absent.
    val tp = counts.getOrDefault("TP", 0)
    val fp = counts.getOrDefault("FP", 0)
    val fn = counts.getOrDefault("FN", 0)

    val denominator = 2 * tp + fp + fn
    if (denominator == 0) {
        return 0.0
    }
    return 2.0 * tp / denominator
};1

import java.lang.Math.*
 
data class Equation(val a: Double, val b: Double, val c: Double) {
    data class Complex(val r: Double, val i: Double) {
        fun toString() = when {
            i == 0.0 -> r.toString()
            r == 0.0 -> "${i}i"
            else -> "$r + ${i}i"
        }
    }
 
    data class Solution(val x1: Any, val x2: Any) {
        fun toString() = when(x1) {
            x2 -> "X1,2 = $x1"
            else -> "X1 = $x1, X2 = $x2"
        }
    }
 
    val quadraticRoots by lazy {
        val _2a = a + a
        val d = b * b - 4.0 * a * c  // discriminant
         if (d < 0.0) {
            val r = -b / _2a
            val i = sqrt(-d) / _2a
            Solution(Complex(r, i), Complex(r, -i))
        } else {
            // avoid calculating -b +/- sqrt(d), to avoid any
            // subtractive cancellation when it is near zero.
            val r = if (b < 0.0) (-b + sqrt(d)) / _2a else (-b - sqrt(d)) / _2a
            Solution(r, c / (a * r))
        }
    }
}
 
fun main(args: Array<String>) {
    val equations = listOf(Equation(1.0, 22.0, -1323.0),   // two distinct real roots
                           Equation(6.0, -23.0, 20.0),     //  with a != 1.0
                           Equation(1.0, -1.0e9, 1.0),     //  with one root near zero
                           Equation(1.0, 2.0, 1.0),        // one real root (double root)
                           Equation(1.0, 0.0, 1.0),        // two imaginary roots
                           Equation(1.0, 1.0, 1.0))        // two complex roots
 
    equations.forEach { println("$it\n" + it.quadraticRoots) }
};0

data class Node(val val: Int, val back: Node?)
 
fun lis(n: List<Int>): List<Int> {
    val pileTops = mutableListOf<Node>()
    // sort into piles
    for (x in n) {
        // binary search
        var low = 0
        var high = pileTops.size - 1
        while (low <= high) {
            val mid = low + (high - low) / 2
            if (pileTops[mid].val >= x) {
                high = mid - 1
            } else {
                low = mid + 1
            }
        }
        val i = low
        val node = Node(x, if (i > 0) pileTops[i - 1] else null)
        pileTops[i] = node
    }
 
    val result = mutableListOf<Int>()
    var node = pileTops.last()
    while (node!= null) {
        result.add(0, node.val)
        node = node.back
    }
    return result
}
 
