fun minCoinsToAllOnes(n: Int, x: Int, y: Int, a: String): Int {
    var count = 0
    var prev = '1'
    for (c in a) {
        if (c == '0' && prev == '1') {
            count += 1
        }
        prev = c
    }
    return if (count == 0) {
        0
    } else {
        (count - 1) * minOf(x, y) + y
    }
};1

import kotlin.text.*
 
/* c = a * b.  Caller is responsible for memory.
   c must not be the same as either a or b. */
fun longmulti(a: String, b: String, c: CharArray) {
    var i = 0
    var j = 0
    var k = 0
    var n: Int
    var carry: Int
    var la: Int
    var lb: Int
 
    /* either is zero, return "0" */
    if (a == "0" || b == "0") {
        c[0] = '0'
        c[1] = '\u0000'
        return
    }
 
    /* see if either a or b is negative */
    if (a[0] == '-') {
        i = 1
        k =!k
    }
    if (b[0] == '-') {
        j = 1
        k =!k
    }
 
    /* if yes, prepend minus sign if needed and skip the sign */
    if (i || j) {
        if (k) c[0] = '-'
        longmulti(a.substring(i), b.substring(j), c.sliceArray(k..c.size - 1))
        return
    }
 
    la = a.length
    lb = b.length
    c.fill('0', 0, la + lb)
    c[la + lb] = '\u0000'
 
#   define I(a) (a - '0')
    for (i = la - 1; i >= 0; i--) {
        for (j = lb - 1, k = i + j + 1, carry = 0; j >= 0; j--, k--) {
            n = I(a[i]) * I(b[j]) + I(c[k]) + carry
            carry = n / 10
            c[k] = (n % 10) + '0'
        }
        c[k] += carry
    }
#   undef I
    if (c[0] == '0') c.copyInto(c, 1, 0, la + lb)
 
    return
}
 
fun main(args: Array<String>) {
    val c = CharArray(1024)
    longmulti("-18446744073709551616", "-18446744073709551616", c)
    println(c)
};1

