fun longestIncreasingSubsequence(X: List<Int>): List<Int> {
    val N = X.size
    val P = IntArray(N)
    val M = IntArray(N + 1)
    var L = 0
    for (i in 0 until N) {
        var lo = 1
        var hi = L
        while (lo <= hi) {
            val mid = (lo + hi) / 2
            if (X[M[mid]] < X[i]) {
                lo = mid + 1
            } else {
                hi = mid - 1
            }
        }
        val newL = lo
        P[i] = M[newL - 1]
        M[newL] = i
        if (newL > L) {
            L = newL
        }
    }
    val S = mutableListOf<Int>()
    var k = M[L]
    for (i in L - 1 downTo 0) {
        S.add(X[k])
        k = P[k]
    }
    return S.reversed()
}
 
