fun printBlock(data: String, len: Int) {
    var sumChars = data.chars().map { Character.digit(it, 10) }.sum()
    var a = data.split("")
 
    println("blocks ${Arrays.toString(a)}, cells $len")
    if (len - sumChars <= 0) {
        println("No solution")
        return
    }
 
    var prep = stream(a).filter { x ->!"".equals(x) }
           .map { x -> repeat(Character.digit(x[0], 10), "1") }
           .collect(toList())
 
    for (r in genSequence(prep, len - sumChars + 1))
