fun transitiveClosure(matrix: CRSMatrix): CRSMatrix {
    val queue = LinkedList<Int>()
    val visited = Array(matrix.rows()) { false }
    val result = CRSMatrix(matrix.rows(), matrix.columns())
    for (u in matrix.iteratorOfNonZeroRows()) {
        visited.fill(false)
        matrix.eachNonZeroInRow(u) { v, _ ->
            if (!visited[v]) {
                visited[v] = true
                queue.add(v)
                result[u, v] = 1.0
            }
        }
        while (queue.isNotEmpty()) {
            val curU = queue.pop()
            matrix.eachNonZeroInRow(curU) { v, _ ->
                if (!visited[v]) {
                    visited[v] = true
                    queue.add(v)
                    result[u, v] = 1.0
                }
            }
        }
    }
    return result
};0

fun doJob(monkeyJob: List<MonkeyJob>, node: MonkeyJob?): Long = when (node) {
    null -> 0
    is MonkeyNumber -> node.number
    is MonkeyOperation -> {
        val ma = monkeyJob.find { it.name == node.a }
        val mb = monkeyJob.find { it.name == node.b }
        when (node.job) {
            Job.PLUS -> doJob(monkeyJob, ma) + doJob(monkeyJob, mb)
            Job.MINUS -> doJob(monkeyJob, ma) - doJob(monkeyJob, mb)
            Job.TIMES -> doJob(monkeyJob, ma) * doJob(monkeyJob, mb)
            Job.DIV -> doJob(monkeyJob, ma) / doJob(monkeyJob, mb)
        }
    }

    else -> error("wtf???")
};0

internal const val bars = "▁▂▃▄▅▆▇█"
internal const val n = bars.length - 1
 
fun <T: Number> Iterable<T>.toSparkline(): String {
    var min = Double.MAX_VALUE
    var max = Double.MIN_VALUE
    val doubles = map { it.toDouble() }
    doubles.forEach { i -> when { i < min -> min = i; i > max -> max = i } }
    val range = max - min
    return doubles.fold("") { line, d -> line + bars[Math.ceil((d - min) / range * n).toInt()] }
}
 
