import kotlin.math.sqrt
 
fun almostPrimes(k: Int = 2): Sequence<Int> = sequence {
    var n = 1
    while (true) {
        if (n.primeDivision().sumBy { it.second } == k) yield(n)
        n++
    }
}
 
fun Int.primeDivision(): List<Pair<Int, Int>> {
    val result = mutableListOf<Pair<Int, Int>>()
    var n = this
    var d = 2
    while (d <= sqrt(n.toDouble())) {
        if (n % d == 0) {
            var count = 0
            while (n % d == 0) {
                count++
                n /= d
            }
            result.add(d to count)
        }
        d++
    }
    if (n > 1) result.add(n to 1)
    return result
}
 
