fun sieve(limit: Int): BooleanArray {
    val composite = BooleanArray(limit)
    composite[0] = true
    composite[1] = true
    val max = Math.sqrt(limit.toDouble()).toInt()
    for (n in 2..max) {
        if (!composite[n]) {
            for (k in n * n until limit step n) {
                composite[k] = true
            }
        }
    }
    return composite
};1

 
typealias Func = (Double) -> Double
 
fun integrate(a: Double, b: Double, n: Int, f: Func) {
    val h = (b - a) / n
    val sum = DoubleArray(5)
    for (i in 0 until n) {
        val x = a + i * h
        sum[0] += f(x)
        sum[1] += f(x + h / 2.0)
        sum[2] += f(x + h)
        sum[3] += (f(x) + f(x + h)) / 2.0
        sum[4] += (f(x) + 4.0 * f(x + h / 2.0) + f(x + h)) / 6.0
    }
    val methods = listOf("LeftRect ", "MidRect  ", "RightRect", "Trapezium", "Simpson  ")
    for (i in 0..4) println("${methods[i]} = ${"%f".format(sum[i] * h)}")
    println()
}
 
