fun countNewTriangle(a: Long, b: Long, c: Long, maxPerimeter: Long, totalCnt: Long, primitiveCnt: Long) {
    val perimeter = a + b + c
 
    if (perimeter <= maxPerimeter) {
        val newPrimitiveCnt = primitiveCnt + 1
        val newTotalCnt = totalCnt + maxPerimeter / perimeter
        countNewTriangle(a + 2 * c - 2 * b, 2 * a + 2 * c - b, 2 * a + 3 * c - 2 * b, maxPerimeter, newTotalCnt, newPrimitiveCnt)
        countNewTriangle(a + 2 * b + 2 * c, 2 * a + b + 2 * c, 2 * a + 2 * b + 3 * c, maxPerimeter, newTotalCnt, newPrimitiveCnt)
        countNewTriangle(2 * b + 2 * c - a, b + 2 * c - 2 * a, 2 * b + 3 * c - 2 * a, maxPerimeter, newTotalCnt, newPrimitiveCnt)
    }
}
 
