fun power(x: Int, n: Int): Double =
    when {
        n == 0 -> 1.0
        n < 0 -> 1.0 / power(x, -n)
        n.isOdd() -> x * power(x, n - 1)
        else -> power(x, n / 2) * power(x, n / 2)
