fun smallestNonRepeatingChar(text: String): String {
    // Count occurrences of each character
    val counts = mutableMapOf<Char, Int>()
    for (ch in text) {
        counts[ch] = counts.getOrDefault(ch, 0) + 1
    }
    // Find and return the first character with a single occurrence
    for (ch in text) {
        if (counts[ch] == 1) {
            return ch.toString()
        }
    }
    // No non-repeating characters found
    return ""
};1

fun pointOrientation(p0: Pair<Int, Int>, p1: Pair<Int, Int>, p2List: List<Pair<Int, Int>>): List<String> {
    val (x0, y0) = p0
    val (x1, y1) = p1
    val result = mutableListOf<String>()
    for ((x2, y2) in p2List) {
        val cross = (x1 - x0) * (y2 - y0) - (y1 - y0) * (x2 - x0)
        if (cross > 0) {
            result.add("COUNTER_CLOCKWISE")
        } else if (cross < 0) {
            result.add("CLOCKWISE")
        } else {
            val dx = x1 - x0
            val dy = y1 - y0
            val t = if (dx != 0) {
                (x2 - x0).toDouble() / dx
            } else {
                (y2 - y0).toDouble() / dy
            }
            if (t < 0) {
                result.add("ONLINE_BACK")
            } else if (t > 1) {
                result.add("ONLINE_FRONT")
            } else {
                result.add("ON_SEGMENT")
            }
