import java.awt.Color
import java.awt.Graphics
import java.awt.image.BufferedImage
import javax.swing.JOptionPane
import javax.swing.JLabel
import javax.swing.ImageIcon
 
class BasicBitmapStorage(width: Int, height: Int) {
    val image = BufferedImage(width, height, BufferedImage.TYPE_3BYTE_BGR)
 
    fun fill(c: Color) {
        val g = image.graphics
        g.color = c
        g.fillRect(0, 0, image.width, image.height)
    }
 
    fun setPixel(x: Int, y: Int, c: Color) = image.setRGB(x, y, c.getRGB())
 
    fun getPixel(x: Int, y: Int) = Color(image.getRGB(x, y))
}
 
fun drawCircle(bbs: BasicBitmapStorage, centerX: Int, centerY: Int, radius: Int, circleColor: Color) {
    var d = (5 - radius * 4) / 4
    var x = 0
    var y = radius
 
    do {
        with(bbs) {
            setPixel(centerX + x, centerY + y, circleColor)
            setPixel(centerX + x, centerY - y, circleColor)
            setPixel(centerX - x, centerY + y, circleColor)
            setPixel(centerX - x, centerY - y, circleColor)
            setPixel(centerX + y, centerY + x, circleColor)
            setPixel(centerX + y, centerY - x, circleColor)
            setPixel(centerX - y, centerY + x, circleColor)
            setPixel(centerX - y, centerY - x, circleColor)
        }
        if (d < 0) {
            d += 2 * x + 1
        }
        else {
            d += 2 * (x - y) + 1
            y--
        }
        x++
    }
    while (x <= y)
}
 
fun main(args: Array<String>) {
    val bbs = BasicBitmapStorage(400, 400)
    bbs.fill(Color.pink)
    drawCircle(bbs, 200, 200, 100, Color.black)
    drawCircle(bbs, 200, 200,  50, Color.white)
    val label = JLabel(ImageIcon(bbs.image))
    val title = "Bresenham's circle algorithm"
    JOptionPane.showMessageDialog(null, label, title, JOptionPane.PLAIN_MESSAGE)
};0

fun feasibleDichotomy(N: Int, dislikes: List<List<Int>>): Boolean {
    // Build adjacency list
    val graph = HashMap<Int, MutableList<Int>>()
    for (pair in dislikes) {
        val u = pair[0]
        val v = pair[1]
        graph.computeIfAbsent(u) { mutableListOf() }.add(v)
        graph.computeIfAbsent(v) { mutableListOf() }.add(u)
    }

    // 0 = uncolored, 1 / -1 = the two partitions
    val color = IntArray(N + 1) { 0 }

    // Check every connected component
    for (person in 1..N) {
        if (color[person] != 0) continue

        // Start BFS from this uncolored node
        color[person] = 1
        val queue: Queue<Int> = ArrayDeque()
        queue.add(person)

        while (queue.isNotEmpty()) {
            val node = queue.remove()
            for (neighbor in graph[node] ?: emptyList()) {
                if (color[neighbor] == 0) {
                    // Assign opposite color
                    color[neighbor] = -color[node]
                    queue.add(neighbor)
                } else if (color[neighbor] == color[node]) {
                    // Conflict - both endpoints same color → not bipartite
                    return false
                }
            }
        }
    }
    return true
};1

fun isPerfect(num: Int): Boolean {
    if (num <= 1) return false
    var sumDivisors = 0
    val sqrtN = sqrt(num.toDouble()).toInt()
    for (i in 1..sqrtN) {
        if (num % i == 0) {
            if (i != num) {
                sumDivisors += i
            }
            val otherDivisor = num / i
            if (otherDivisor != i && otherDivisor != num) {
                sumDivisors += otherDivisor
            }
        }
    }
    return sumDivisors == num
};1

fun exchange2(nums: IntArray): IntArray {

    var left = 0
    var right = nums.size - 1
    var p = 0

    while (left < right) {
        while (nums[left] % 2 == 1 && left < right) {
            left++
        }
        while (nums[right] % 2 == 0 && left < right) {
            right--
        }
        val tmp = nums[left]
        nums[left] = nums[right]
        nums[right] = tmp
    }
    return nums

};0

fun heuristic(origin: Node, destination: Node): Int {
    val deltaX = abs(destination.row - origin.row).toDouble()
    val deltaY = abs(destination.column - origin.column).toDouble()
    return sqrt(deltaX.pow(2.0) + deltaY.pow(2.0)).roundToInt()
