fun handleException(excType: Any, excValue: Any, excTraceback: Any?): String {
    // excType: Typically a KClass or Class<*> in Kotlin; we expect excType to have a 'simpleName' property or fallback to 'toString()'
    val typeName = when (excType) {
        is kotlin.reflect.KClass<*> -> excType.simpleName ?: excType.toString()
        is Class<*> -> excType.simpleName ?: excType.toString()
        is String -> excType
        else -> excType::class.simpleName ?: excType.toString()
    }
    return "Error: $typeName: $excValue. Please check your settings and input files for consistency."
