import kotlin.random.Random
 
fun isPrime(n: Int): Boolean {
    if (n == 0 || n == 1 || n == 4 || n == 6 || n == 8 || n == 9) {
        return false
    }
    if (n == 2 || n == 3 || n == 5 || n == 7) {
        return true
    }
    var s = 0
    var d = n - 1
    while (d % 2 == 0) {
        d /= 2
        s++
    }
    assert(2.0.pow(s) * d == n - 1)
 
    fun trialComposite(a: Int): Boolean {
        if (a.toDouble().pow(d) % n == 1) {
            return false
        }
        for (i in 0 until s) {
            if (a.toDouble().pow(2.0.pow(i) * d) % n == n - 1) {
                return false
            }
        }
        return true
    }
 
    for (i in 0 until 8) {
        val a = Random.nextInt(2, n)
        if (trialComposite(a)) {
            return false
        }
    }
 
    return true
}
 
fun isPrime(n: Long): Boolean {
    if (n <= 1) {
        return false
    }
    if (n <= 3) {
        return true
    }
    if (n % 2 == 0L || n % 3 == 0L) {
        return false
    }
    var i = 5L
    while (i * i <= n) {
        if (n % i == 0L || n % (i + 2) == 0L) {
            return false
        }
        i += 6
    }
    return true
}
 
