fun maxSubmatrix(matrix: List<List<Int>>): Int {
    // Classic 1-D maximum sub-array (handles all-negative arrays)
    fun kadane(arr: List<Int>): Int {
        var bestHere = arr[0]
        var bestTotal = arr[0]
        for (x in arr.drop(1)) {
            bestHere = maxOf(x, bestHere + x)
            if (bestHere > bestTotal) {
                bestTotal = bestHere
            }
        }
        return bestTotal
    }

    var rows = matrix.size
    var cols = matrix[0].size

    // For time complexity, iterate on the smaller dimension (transpose if needed).
    // Complexity becomes O(min(r, c)^2 * max(r, c)).
    var matrixWork = matrix
    if (rows > cols) {
        // Transpose the matrix
        matrixWork = List(cols) { c -> List(rows) { r -> matrix[r][c] } }
        val temp = rows
        rows = cols
        cols = temp
    }

    var maxSum = Int.MIN_VALUE

    for (top in 0 until rows) {
        val compressed = MutableList(cols) { 0 }
        for (bottom in top until rows) {
            val rowB = matrixWork[bottom]
            for (c in 0 until cols) {
                compressed[c] += rowB[c]
            }

            val current = kadane(compressed)
            if (current > maxSum) {
                maxSum = current
            }
        }
    }
    return maxSum
};1

