fun <T> mergesort(list: MutableList<T>, order: Comparator<T>) {
    if (list.size > 1) {
        val middle = floor(list.size / 2.0).toInt()
        mergesort(list.subList(0, middle), order)
        mergesort(list.subList(middle, list.size), order)
        inplaceMerge(list, order)
    }
}
 
fun <T> mergesort(list: MutableList<T>) {
    mergesort(list, Comparator<T> { a, b -> a.compareTo(b) })
}
 
fun <T> inplaceMerge(list: MutableList<T>, order: Comparator<T>) {
    val middle = floor(list.size / 2.0).toInt()
    val left = list.subList(0, middle)
    val right = list.subList(middle, list.size)
    var leftIndex = 0
    var rightIndex = 0
    var listIndex = 0
    while (leftIndex < left.size && rightIndex < right.size) {
        if (order.compare(left[leftIndex], right[rightIndex]) <= 0) {
            list[listIndex] = left[leftIndex]
            leftIndex++
        } else {
            list[listIndex] = right[rightIndex]
            rightIndex++
        }
        listIndex++
    }
    while (leftIndex < left.size) {
        list[listIndex] = left[leftIndex]
        leftIndex++
        listIndex++
    }
    while (rightIndex < right.size) {
        list[listIndex] = right[rightIndex]
        rightIndex++
        listIndex++
    }
};1

fun createBook(title: String, author: String, publicationDate: String, genre: String): Map<String, String> {
    // List of accepted date formats
    val acceptedFormats = listOf(
        "yyyy-MM-dd",      // 2023-07-15
        "dd-MM-yyyy",      // 15-07-2023
        "MM/dd/yyyy",      // 07/15/2023
        "MMMM dd, yyyy",   // July 15, 2023
        "MMM dd, yyyy"     // Jul 15, 2023
    )
    var parsedDate: LocalDate? = null
    for (fmt in acceptedFormats) {
        val formatter = DateTimeFormatter.ofPattern(fmt, Locale.ENGLISH)
        try {
            parsedDate = LocalDate.parse(publicationDate, formatter)
            break
        } catch (e: DateTimeParseException) {
            // keep trying
        }
    }
    if (parsedDate == null) {
        try {
            // Try ISO format (e.g., 2023-07-15T00:00:00)
            parsedDate = LocalDate.parse(publicationDate)
        } catch (e: DateTimeParseException) {
            try {
                parsedDate = LocalDate.parse(publicationDate, DateTimeFormatter.ISO_DATE_TIME)
            } catch (e2: DateTimeParseException) {
                throw IllegalArgumentException("publicationDate must be a valid date string.")
            }
        }
    }
    val normalizedDate = parsedDate.format(DateTimeFormatter.ofPattern("yyyy-MM-dd"))
    return mapOf(
        "title" to title,
        "author" to author,
        "publication_date" to normalizedDate,
        "genre" to genre
    )
};1

