fun replaceString(content: String, rules: List<Map<String, String>>): String {
    var result = content
    for (rule in rules) {
        val findSub = rule["find"] ?: ""
        val replSub = rule["replace"] ?: ""
        val mode = rule["param"]?.lowercase() ?: "every"

        if (findSub.isEmpty()) {
            continue
        }

        result = when (mode) {
            "first" -> {
                result.replaceFirst(findSub, replSub)
            }
            "last" -> {
                val idx = result.lastIndexOf(findSub)
                if (idx != -1) {
                    result.substring(0, idx) + replSub + result.substring(idx + findSub.length)
                } else {
                    result
                }
            }
            else -> {
                result.replace(findSub, replSub)
            }
        }
    }
    return result
};1

