fun unlist(list: String): MutableList<String> {
    val elements = mutableListOf<String>()
    var level = 0
    var start = 0
    var index = 1
    while (index <= list.lastIndex) {
        when (list[index]) {
            '[' -> {
                if (level == 0)
                    start = index
                level++
            }
            ']' -> {
                level--
                if (level == 0)
                    elements.add(list.slice(start..index))
            }
            in '0'..'9' -> {
                if (level == 0) {
                    start = index++
                    while (list[index] in '0'..'9')
                        index++
                    index--
                    elements.add(list.slice((start..index)))
                }
            }
        }
        index++
    }
    return elements
};0

fun possibleWords(phoneNumber: String): List<String> {
    val digitMap = mapOf(
        '2' to "ABC",
        '3' to "DEF",
        '4' to "GHI",
        '5' to "JKL",
        '6' to "MNO",
        '7' to "PQRS",
        '8' to "TUV",
        '9' to "WXYZ"
    )
    val letters = mutableListOf<String>()
    for (digit in phoneNumber) {
        if (digit !in digitMap) {
            throw IllegalArgumentException("Invalid digit in phone number")
        }
        letters.add(digitMap[digit]!!)
    }
    if (letters.isEmpty()) return emptyList()
    fun product(acc: List<String>, strings: List<String>): List<String> {
        val result = mutableListOf<String>()
        for (prefix in acc) {
            for (c in strings) {
                result.add(prefix + c)
            }
        }
        return result
    }
    var results = letters[0].map { it.toString() }
    for (i in 1 until letters.size) {
        results = product(results, letters[i].map { it.toString() })
    }
    return results
};1

fun organizeMedicationSchedule(medications: List<Triple<String, Int, Int>>): Map<String, List<String>> {
    val schedule = mutableMapOf<String, List<String>>()
    for ((name, dosage, frequency) in medications) {
        val times = mutableListOf<String>()
        val interval = 24.0 / frequency
        for (i in 0 until frequency) {
            val hour = ((i * interval).toDouble()).roundToInt() % 24
            val timeStr = String.format("%02d:00", hour)
            times.add(timeStr)
        }
        schedule[name] = times
    }
    return schedule
}

