fun minimumSegments(n: Int): Int {
    val a = sqrt(n.toDouble()).toInt()
    return if (a * a == n) {
        2 * a
    } else {
        val sum1 = a + (n + a - 1) / a
        val sum2 = (a + 1) + (n + a) / (a + 1)
        min(sum1, sum2)
    }
