import java.util.ArrayList
import java.util.Arrays
import java.util.List
import java.util.concurrent.atomic.AtomicInteger
import java.util.function.BiConsumer
import java.util.function.IntConsumer
import java.util.stream.Collectors

fun kosaraju(g: List<List<Int>>): List<Int> {
    // 1. For each vertex u of the graph, mark u as unvisited. Let l be empty.
    val size = g.size
    val vis = BooleanArray(size)
    val l = IntArray(size)
    val x = AtomicInteger(size)

    val t = ArrayList<List<Int>>()
    for (i in 0 until size) {
        t.add(ArrayList())
    }

    val visit = Recursive<IntConsumer>()
    visit.func = IntConsumer { u ->
        if (!vis[u]) {
            vis[u] = true
            for (v in g[u]) {
                visit.func.accept(v)
                t[v].add(u)
            }
            val xval = x.decrementAndGet()
            l[xval] = u
        }
    }

    // 2. For each vertex u of the graph do visit(u)
    for (i in 0 until size) {
        visit.func.accept(i)
    }
    val c = IntArray(size)

    val assign = Recursive<BiConsumer<Int, Int>>()
    assign.func = BiConsumer { u, root ->
        if (vis[u]) { // repurpose vis to mean 'unassigned'
            vis[u] = false
            c[u] = root
            for (v in t[u]) {
                assign.func.accept(v, root)
            }
        }
    }

    // 3: For each element u of l in order, do assign(u, u)
    for (u in l) {
        assign.func.accept(u, u)
    }

    return Arrays.stream(c).boxed().collect(Collectors.toList())
}

