fun tryParseJson(jsonString: String): Any {
    // Reject empty or purely whitespace strings immediately
    if (jsonString.isBlank()) {
        return false
    }
    return try {
        val obj = JSONObject(jsonString)
        // Convert JSONObject to a Map<String, Any?>
        obj.toMap()
    } catch (e: JSONException) {
        false
    } catch (e: Exception) {
        false
    }
}

fun JSONObject.toMap(): Map<String, Any?> {
    val map = mutableMapOf<String, Any?>()
    for (key in this.keys()) {
        val value = this.get(key)
        map[key] = when (value) {
            is JSONObject -> value.toMap()
            is org.json.JSONArray -> value.toList()
            org.json.JSONObject.NULL -> null
            else -> value
        }
    }
    return map
}

fun org.json.JSONArray.toList(): List<Any?> {
    val list = mutableListOf<Any?>()
    for (i in 0 until this.length()) {
        val value = this.get(i)
        val processed = when (value) {
            is JSONObject -> value.toMap()
            is org.json.JSONArray -> value.toList()
            org.json.JSONObject.NULL -> null
            else -> value
        }
        list.add(processed)
    }
    return list
};1

