    if (stripped.isEmpty()) {
        return false
    }
    if (stripped[0] == '+' || stripped[0] == '-') {
        return stripped.length > 1 && stripped.substring(1).all { it.isDigit() }
    }
    return stripped.all { it.isDigit() }
