fun multiply(lst: List<Int>, idx: Int = 0): Int {
    // Base case: reached the end of the list
    if (idx >= lst.size) {
        return 1
    }

    // Determine the contribution of the current element
    var current = 1
    if (idx % 2 == 0 && lst[idx] % 2 == 1) {
        current = lst[idx]
    }

    // Recursive call for the rest of the list
    return current * multiply(lst, idx + 1)
};1

