class Vector(init: DoubleArray) {
    val store: DoubleArray = init
    constructor(x: Double, y: Double) : this(doubleArrayOf(x, y))
    operator fun plus(v2: Vector): Vector {
        return Vector(this.store.zip(v2.store).map { (a, b) -> a + b }.toDoubleArray())
    }
    operator fun minus(v2: Vector): Vector {
        return Vector(this.store.zip(v2.store).map { (a, b) -> a - b }.toDoubleArray())
    }
    operator fun times(scalar: Double): Vector {
        return Vector(this.store.map { x -> x * scalar }.toDoubleArray())
    }
    operator fun div(scalar: Double): Vector {
        return Vector(this.store.map { x -> x / scalar }.toDoubleArray())
    }
    fun toString(): String {
        return "[" + this.store.joinToString(",") + "]"
    }
}
 
