fun reconstructMatrix(m: Int, n: Int, B: List<List<Int>>): Pair<String, List<List<Int>>?> {
    val rowHasZero = MutableList(m) { i -> B[i].any { x -> x == 0 } }
    val colHasZero = MutableList(n) { j -> (0 until m).any { i -> B[i][j] == 0 } }
    val A = MutableList(m) { MutableList(n) { 0 } }
    for (i in 0 until m) {
        for (j in 0 until n) {
            if (!rowHasZero[i] && !colHasZero[j]) {
                A[i][j] = 1
            } else {
                A[i][j] = 0
            }
        }
    }
    val rowOr = MutableList(m) { 0 }
    for (i in 0 until m) {
        var v = 0
        for (num in A[i]) {
            v = v or num
        }
        rowOr[i] = v
    }
    val colOr = MutableList(n) { 0 }
    for (j in 0 until n) {
        var v = 0
        for (i in 0 until m) {
            v = v or A[i][j]
        }
        colOr[j] = v
    }
    var valid = true
    outer@ for (i in 0 until m) {
        for (j in 0 until n) {
            if ((rowOr[i] or colOr[j]) != B[i][j]) {
                valid = false
                break@outer
            }
        }
    }
    return if (valid) {
        Pair("YES", A)
    } else {
        Pair("NO", null)
    }
};1

fun parseModules(lines: List<String>): Map<String, Module> {
    val inputToOutputMap = lines.associate { line ->
        val (namePart, destPart) = line.split("->")
        val nameAndType = namePart.trim()
        val destinations = destPart.split(',').map { it.trim() }
        nameAndType to destinations
    }

    return inputToOutputMap.map { (nameAndType, destinations) ->
        when {
            nameAndType == "broadcaster" ->
                BroadcasterModule(destinations)

            nameAndType.startsWith('%') ->
                FlipFlopModule(
                    name = getName(nameAndType),
                    destinations = destinations
                )

            nameAndType.startsWith('&') ->
                ConjunctionModule(
                    name = getName(nameAndType),
                    inputs = inputToOutputMap
                        .filterValues { it.contains(getName(nameAndType)) }
                        .keys
                        .map { getName(it) }
                        .toSet(),
                    destinations = destinations
                )

            else ->
                UntypedModule(nameAndType, destinations)
        }
    }.associateBy { it.name }
};0

/**
 * Return a list containing the squares of all integers from 0 to `num`, inclusive.
 *
 * @param num A non-negative integer that defines the upper bound of the range whose
 * squares are to be returned.
