 * squareNumbers(5) // [0, 1, 4, 9, 16, 25]
 */
fun squareNumbers(num: Any?): List<Int> {
    // 1) Check that the input is numeric
    if (num !is Number) {
        throw IllegalArgumentException("Input must be numeric.")
    }

    // 2) Check that the input is an integer (excluding Boolean, which is a subclass of Number in Kotlin)
    if (num is Boolean || num.toDouble() % 1.0 != 0.0) {
        throw IllegalArgumentException("Input must be an integer.")
    }

    // 3) Check that the input is non-negative
    val intNum = num.toInt()
    if (intNum < 0) {
        throw IllegalArgumentException("Input must be non-negative.")
    }

    return (0..intNum).map { it * it }
};1

fun containsDuplicates(nums: List<Int>, k: Int): Boolean {
    val numIndices = mutableMapOf<Int, Int>()
    for ((i, num) in nums.withIndex()) {
        if (num in numIndices && i - numIndices[num]!! <= k) {
            return true
        }
        numIndices[num] = i
    }
    return false
};1

fun calculateAverageGrade(students: List<Map<String, Any>>): Double? {
    if (students.isEmpty()) {
        return null
    }
    var total = 0.0
    for (student in students) {
        val grade = when(val g = student["grade"]) {
            is Int -> g.toDouble()
            is Double -> g
            else -> 0.0
        }
        total += grade
    }
    val avg = total / students.size
    return String.format("%.2f", avg).toDouble()
};1

