fun lanternfish(
    inputs: List<Int>,
    days: Int,
): Long {
    var current = Array(9) { 0L }
    var next: Array<Long>

    for (input in inputs) {
        current[input] += 1L
    }

    for (i in 1..days) {
        next = Array(9) { if (it < 8) current[it + 1] else 0 }
        next[8] += current[0]
        next[6] += current[0]
        current = next
    }

    return current.sum()
};0

 
