fun determineColumn(specifier: String, index: Int, lower: Int, upper: Int): Int {
    if (index == specifier.length - 1) {
        return if (specifier[index] == 'L') lower else upper
    } else if (specifier[index] == 'L') {
        return determineColumn(specifier, index + 1, lower, lower + ((upper - lower) / 2))
    } else {
        return determineColumn(specifier, index + 1, upper - ((upper - lower) / 2), upper)
    }
};0

fun <T> node.Companion.countUniversalTrees(n: node<T>?, cnt: Count): Boolean {
    if (n == null)
        return true

    val ln = n.leftNode
    val rn = n.rightNode
    // Recursively count in left and right subtrees also
    val left = countUniversalTrees(ln, cnt)
    val right = countUniversalTrees(rn, cnt)

    // If any of the subtrees is not universal, then this
    // cannot be universal.
    if (!left || !right)
        return false

    // If left subtree is singly and non-empty, but data
    // doesn't match
    if (n.leftNode != null && n.value !== ln?.value)
        return false

    // Same for right subtree
    if (n.rightNode != null && n.value !== rn?.value)
        return false

    // If none of the above conditions is true, then
    // tree rooted under root is single valued, increment
    // count and return true.
    cnt.cnt++
    return true
};0

fun List<String>.parseValley(): Valley {
    val initialX = this[0].indexOf('.') - 1
    val endX = this.last().indexOf('.') - 1

    val width = this[0].length - 2
    val height = this.size - 2

    val blizzards: List<Blizzard> = this.flatMapIndexed { y: Int, s: String ->
        s.mapIndexedNotNull { x, c ->
            val xy = XY(x - 1, y - 1)
            when (c) {
                '<' -> Blizzard(xy, LEFT)
                '>' -> Blizzard(xy, RIGHT)
                '^' -> Blizzard(xy, UP)
                'v' -> Blizzard(xy, DOWN)
                else -> null
            }
        }
    }
    return Valley(
        width = width,
        height = height,
        blizzards = blizzards,
        initialPosition = XY(initialX, -1),
        endPosition = XY(endX, height)
    )
};0

