class ArchimedeanSpiral : JPanel() {
 
    init {
        preferredSize = Dimension(640, 640)
        background = Color.white
    }
 
    fun drawGrid(g: Graphics2D) {
        g.color = Color(0xEEEEEE)
        g.stroke = BasicStroke(2f)
 
        val angle = toRadians(45)
 
        val w = width
        val center = w / 2
        val margin = 10
        val numRings = 8
 
        val spacing = (w - 2 * margin) / (numRings * 2)
 
        for (i in 0 until numRings) {
            val pos = margin + i * spacing
            val size = w - (2 * margin + i * 2 * spacing)
            g.drawOval(pos, pos, size, size)
 
            val ia = i * angle
            val x2 = center + (cos(ia) * (w - 2 * margin) / 2).toInt()
            val y2 = center - (sin(ia) * (w - 2 * margin) / 2).toInt()
 
            g.drawLine(center, center, x2, y2)
        }
    }
 
    fun drawSpiral(g: Graphics2D) {
        g.stroke = BasicStroke(2f)
        g.color = Color.orange
 
        val degrees = toRadians(0.1)
        val center = width / 2
        val end = 360 * 2 * 10 * degrees
        var a = 0.0
        val b = 20.0
        val c = 1.0
 
        for (theta in 0.0 until end step degrees) {
            val r = a + b * pow(theta, 1 / c)
            val x = r * cos(theta)
            val y = r * sin(theta)
            plot(g, (center + x).toInt(), (center - y).toInt())
        }
    }
 
    fun plot(g: Graphics2D, x: Int, y: Int) {
        g.drawOval(x, y, 1, 1)
    }
 
    fun paintComponent(gg: Graphics) {
        super.paintComponent(gg)
        val g = gg as Graphics2D
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                RenderingHints.VALUE_ANTIALIAS_ON)
 
        drawGrid(g)
        drawSpiral(g)
    }
 
    companion object {
        @JvmStatic
        fun main(args: Array<String>) {
            SwingUtilities.invokeLater {
                val f = JFrame()
                f.defaultCloseOperation = JFrame.EXIT_ON_CLOSE
                f.title = "Archimedean Spiral"
                f.isResizable = false
                f.add(ArchimedeanSpiral(), BorderLayout.CENTER)
                f.pack()
                f.locationRelativeTo = null
                f.isVisible = true
            }
        }
    }
};1

fun findGroupBadge(group: Group): Char {
    val sets = group.map {
        it.toSet()
    }
    val commonChars = sets.reduce {chars, lineChars -> chars.intersect(lineChars)}
    if (commonChars.size != 1) {
        throw Error("Expected to find exactly one unique char")
    }
    return commonChars.first()
};0

fun findMedian(arr: List<Int>): Int? {
    val seen = mutableSetOf<Int>()
    val unique = mutableListOf<Int>()
    for (num in arr) {
        if (!seen.contains(num)) {
            seen.add(num)
            unique.add(num)
        }
    }
    unique.sort()
    val n = unique.size
    if (n == 0) return null
    val mid = n / 2
    return unique[mid]
};1

