    val y = moons.map { Axis(it.y) }
    val z = moons.map { Axis(it.z) }

    var repeat = -1L
    runBlocking {

        val xRepeat = async { repeats(x) }
        val yRepeat = async { repeats(y) }
        val zRepeat = async { repeats(z) }

        repeat = lcm(lcm(xRepeat.await(), yRepeat.await()), zRepeat.await())
    }
    return repeat
