import java.util.Arrays
 
    fun oddMagicSquare(n: Int): Array<IntArray>? {
        if (n < 3 || n % 2 == 0)
            return null
 
        var value = 0
        val squareSize = n * n
        var c = n / 2
        var r = 0
 
        val result = Array(n, { IntArray(n) })
 
        while (++value <= squareSize) {
            result[r][c] = value
            if (r == 0) {
                if (c == n - 1) {
                    r++
                } else {
                    r = n - 1
                    c++
                }
            } else if (c == n - 1) {
                r--
                c = 0
            } else if (result[r - 1][c + 1] == 0) {
                r--
                c++
            } else {
                r++
            }
        }
        return result
    }
 
    fun singlyEvenMagicSquare(n: Int): Array<IntArray>? {
        if (n < 6 || (n - 2) % 4!= 0)
            return null
 
        val size = n * n
        val halfN = n / 2
        val subGridSize = size / 4
 
        val subGrid = oddMagicSquare(halfN)
        val gridFactors = intArrayOf(0, 2, 3, 1)
        val result = Array(n, { IntArray(n) })
 
        for (r in 0..n - 1) {
            for (c in 0..n - 1) {
                val grid = (r / halfN) * 2 + (c / halfN)
                result[r][c] = subGrid[r % halfN][c % halfN]
                result[r][c] += gridFactors[grid] * subGridSize
            }
        }
 
        val nColsLeft = halfN / 2
        val nColsRight = nColsLeft - 1
 
        for (r in 0..halfN - 1)
            for (c in 0..n - 1) {
                if (c < nColsLeft || c >= n - nColsRight
                        || (c == nColsLeft && r == nColsLeft)) {
 
                    if (c == 0 && r == nColsLeft)
                        continue
 
                    val tmp = result[r][c]
                    result[r][c] = result[r + halfN][c]
                    result[r + halfN][c] = tmp
                }
            }
 
        return result
    }
 
    fun numDigits(n: Int): Int {
        var count = 1
 
        while (n >= 10) {
            n /= 10
            count++
        }
 
        return count
    }
 
    fun printMagicSquare(square: Array<IntArray>, rows: Int) {
        for (i in 0..rows - 1) {
            for (j in 0..rows - 1) {
                print(String.format("%" + (rows - numDigits(square[i][j])) + "s%d", "", square[i][j]))
            }
            println()
        }
        println("\nMagic constant: " + (rows * rows + 1) * rows / 2)
    }
 
