fun threshIou(gtDists: List<Double>, predDists: List<Double>, thresh: Double): List<Double> {
    if (gtDists.size != predDists.size) {
        throw IllegalArgumentException("Input lists must be of the same length.")
    }
    val ious = mutableListOf<Double>()
    for ((gt, pred) in gtDists.zip(predDists)) {
        val inGt = gt <= thresh
        val inPred = pred <= thresh

        val intersection = if (inGt && inPred) 1 else 0
        val union = if (inGt || inPred) 1 else 0

        val iou = if (union != 0) intersection.toDouble() / union else 0.0
        ious.add(iou)
    }
    return ious
};1

//This function takes an integer array as input and returns the maximum sum of any contiguous subarray in the array.
// We initialize two variables, maxSum and currentSum, to the first element of the array. We then loop through the
// array, updating currentSum to be the maximum of the current element and the sum of the current element and the
// previous subarray, and updating maxSum to be the maximum of the current value of maxSum and the current value
// of currentSum.
fun maxSubarraySum(arr: IntArray): Int {
    var maxSum = arr[0]
    var currentSum = arr[0]

    for (i in 1 until arr.size) {
        currentSum = maxOf(arr[i], currentSum + arr[i])
        maxSum = maxOf(maxSum, currentSum)
    }

    return maxSum
};0

fun organizePetFeedingSchedule(events: List<Map<String, String>>): Map<String, List<Pair<String, String>>> {
    val feedingSchedule = mutableMapOf<String, MutableList<Pair<String, String>>>()
    for (event in events) {
        val petName = event["pet_name"] ?: continue
        val time = event["time"] ?: continue
        val foodType = event["food_type"] ?: continue
        if (petName !in feedingSchedule) {
            feedingSchedule[petName] = mutableListOf()
        }
        feedingSchedule[petName]?.add(Pair(time, foodType))
    }
    for ((petName, schedule) in feedingSchedule) {
        feedingSchedule[petName] = schedule.sortedBy { it.first }.toMutableList()
    }
    return feedingSchedule
};1

// Parses the input string for the numerators and denominators
fun compile(prog: String, numArr: MutableList<String>, denArr: MutableList<String>): List<MutableList<String>> {
    val regex = Regex("\\s*(\\d*)\\s*/\\s*(\\d*)\\s*(.*)", RegexOption.MULTILINE)
    var result: MatchResult?
    while (result = regex.find(prog)) {
        numArr.add(result.groupValues[1])
        denArr.add(result.groupValues[2])
        prog = result.groupValues[3]
    }
    return listOf(numArr, denArr)
}
 
// Outputs the result of the compile stage
fun dump(numArr: MutableList<String>, denArr: MutableList<String>): String {
    var output = ""
    for (i in numArr.indices) {
        output += "${numArr[i]}/${denArr[i]} "
    }
    return "$output<br>"
}
 
// Step
fun step(val: Int, numArr: MutableList<String>, denArr: MutableList<String>): Int {
    var i = 0
    while (i < denArr.size && val % denArr[i].toInt()!= 0) i++
    return numArr[i].toInt() * val / denArr[i].toInt()
}
 
// Executes Fractran
fun exec(val: Int, i: Int, limit: Int, numArr: MutableList<String>, denArr: MutableList<String>): String {
    var output = ""
    while (val!= 0 && i < limit) {
        output += "$i: $val<br>"
        val = step(val, numArr, denArr)
        i++
    }
    return output
}
 
