fun getSpiralArray(dimension: Int): Array<IntArray> {
    val spiralArray = Array(dimension) { IntArray(dimension) }
    val numConcentricSquares = ceil(dimension / 2.0).toInt()
    var j: Int
    var sideLen = dimension
    var currNum = 0
    for (i in 0 until numConcentricSquares) {
        // do top side
        for (j in 0 until sideLen) {
            spiralArray[i][i + j] = currNum++
        }
        // do right side
        for (j in 1 until sideLen) {
            spiralArray[i + j][dimension - 1 - i] = currNum++
        }
        // do bottom side
        for (j in sideLen - 2 downTo 0) {
            spiralArray[dimension - 1 - i][i + j] = currNum++
        }
        // do left side
        for (j in sideLen - 2 downTo 1) {
            spiralArray[i + j][i] = currNum++
        }
        sideLen -= 2
    }
    return spiralArray
}
 
fun printSpiralArray(spiralArray: Array<IntArray>) {
    val dimension = spiralArray.size
    val fieldWidth = floor(log10(dimension * dimension - 1.0)).toInt() + 2
    for (row in 0 until dimension) {
        for (col in 0 until dimension) {
            print("%${fieldWidth}d".format(spiralArray[row][col]))
        }
        println()
    }
}
 
