fun findTripletRows(matrix: List<List<Int>>, target: Int): List<List<Int>>? {
    val n = matrix.size
    if (n < 3) {
        return null
    }

    // Step 1: row sums
    val rowSums = matrix.map { row -> row.sum() }

    // Step 2: mapping from sum -> list of indices that have that sum
    val sumToIndices = mutableMapOf<Int, MutableList<Int>>()
    for ((idx, s) in rowSums.withIndex()) {
        sumToIndices.computeIfAbsent(s) { mutableListOf() }.add(idx)
    }

    // Step 3: search for a triplet
    for (i in 0 until n-2) {
        for (j in i+1 until n-1) {
            val needed = target - (rowSums[i] + rowSums[j])
            val indices = sumToIndices[needed]
            if (indices != null) {
                for (k in indices) {
                    if (k != i && k != j) {
                        return listOf(matrix[i], matrix[j], matrix[k])
                    }
                }
            }
        }
    }
    // Step 4: no triplet found
    return null
};1

