fun unPrimable(test: Int): Boolean {
    if (primes[test]) {
        return false
    }
    val s = test.toString() + ""
    for (i in s.indices) {
        for (j in 0..9) {
            if (primes[replace(s, i, j).toInt()]) {
                return false
            }
        }
    }
    return true
}
 
fun replace(str: String, position: Int, value: Int): String {
    val sChar = str.toCharArray()
    sChar[position] = value.toChar()
    return str.substring(0, position) + value + str.substring(position + 1)
}
 
fun sieve() {
    //  primes
    for (i in 2 until MAX) {
        primes[i] = true
    }
    for (i in 2 until MAX) {
        if (primes[i]) {
            var j = 2 * i
            while (j < MAX) {
                primes[j] = false
                j += i
            }
        }
    }
};0

fun <T> median(l: List<T>, cmpFunc: ((T, T) -> Int)? = null): Double {
    if (l.isEmpty()) {
        throw IllegalArgumentException("median() arg is an empty sequence")
    }

    val cmp: (T, T) -> Int = cmpFunc ?: { a, b ->
        @Suppress("UNCHECKED_CAST")
        when {
            a is Number && b is Number -> {
                val ad = a.toDouble(); val bd = b.toDouble()
                when {
                    ad < bd -> -1
                    ad > bd -> 1
                    else -> 0
                }
            }
            a is Comparable<*> && b is Comparable<*> ->
                (a as Comparable<Any>).compareTo(b as Any)
            else -> throw IllegalArgumentException("Cannot compare elements of type " + a?.javaClass?.name)
        }
    }

    fun quickSelect(seq: MutableList<T>, k: Int): T {
        var sequence = seq
        var idx = k
        while (true) {
            if (sequence.size == 1) {
                return sequence[0]
            }
            val pivot = sequence[0]
            val lows = mutableListOf<T>()
            val highs = mutableListOf<T>()
            val pivots = mutableListOf<T>()
            for (item in sequence) {
                val cmpResult = cmp(item, pivot)
                when {
                    cmpResult < 0 -> lows.add(item)
                    cmpResult > 0 -> highs.add(item)
                    else -> pivots.add(item)
                }
            }
            when {
                idx < lows.size -> {
                    sequence = lows
                }
                idx < lows.size + pivots.size -> {
                    return pivots[0]
                }
                else -> {
                    idx -= (lows.size + pivots.size)
                    sequence = highs
                }
            }
        }
    }

    val n = l.size
    val copy1 = l.toMutableList()
    val mid1 = quickSelect(copy1, (n - 1) / 2)

    if (n and 1 == 1) {
        return when (mid1) {
            is Number -> mid1.toDouble()
            else -> throw IllegalArgumentException("Median value is not numeric.")
        }
    }
    val copy2 = l.toMutableList()
    val mid2 = quickSelect(copy2, n / 2)
    if (mid1 is Number && mid2 is Number) {
        return (mid1.toDouble() + mid2.toDouble()) / 2.0
    } else {
        throw IllegalArgumentException("Median values are not numeric.")
    }
};1

