fun longestIncreasingSubsequence(nums: List<Int>): Int {
    if (nums.isEmpty()) return 0

    val tails = mutableListOf<Int>()
    for (num in nums) {
        val idx = tails.binarySearch(num)
        val insertIdx = if (idx < 0) -idx - 1 else idx
        if (insertIdx == tails.size) {
            tails.add(num)
        } else {
            tails[insertIdx] = num
        }
    }
    return tails.size
};1

fun matchCatWords(word: String): Boolean {
    // Quick fail if the basic length cannot satisfy the middle-character requirement.
    if (word.length < 5) { // minimum: 'cat' + 1 middle char + 's' ==> 3+1+1 = 5
        return false
    }

    // Validate prefix
    if (!word.startsWith("cat")) {
        return false
    }

    // Validate suffix and compute how many characters remain in the middle
    val suffixLen = when {
        word.endsWith("ing") -> 3
        word.endsWith("s") -> 1
        else -> return false
    }

    // Ensure at least one character between prefix ('cat') and the suffix
    val middleLength = word.length - 3 - suffixLen
    return middleLength >= 1
};1

fun bankOperations(operations: List<Pair<String, Int>>): Int {
    var balance = 0
    for (op in operations) {
        val action = op.first
        val amount = op.second
        when (action) {
            "deposit" -> {
                if (amount > 0) {
                    balance += amount
                }
            }
            "withdraw" -> {
                if (amount > 0 && balance >= amount) {
                    balance -= amount
                }
            }
            "get_balance" -> {
                // Do nothing
            }
            // Ignore other actions
        }
    }
    return balance
};1

