    }

    node.getFiles().forEach { node ->
        println("$indentation | ${node.filename} ${node.filesize}")
    }

    node.getDirectories().forEach { node ->
        println("$indentation | ${node.filename} (${node.filesize})")
        printTree(node, depth + 1)
    }
