fun searchItemByCode(itemCode: String, inventory: List<String>): String {
    // Normalize the code being searched
    val trimmedCode = itemCode.trim()

    for (record in inventory) {
        // Split the record and trim spaces from each part
        val parts = record.split(",").map { it.trim() }
        if (parts.size != 4) {
            // Skip malformed lines
            continue
        }
        val (code, name, qty, price) = parts
        if (code == trimmedCode) {
            return """Item Code: $code\nItem Name: $name\nQuantity: $qty\nPrice: $$price"""
        }
    }
    return "Item with code $trimmedCode not found in the inventory."
};1

