import java.util.Random
 
class Cupboard {
    private val drawers = IntArray(100)
    private val random = Random()
 
    init {
        for (i in 0..99)
            drawers[i] = i
        for (i in 0..99) {
            val j = random.nextInt(100)
            val temp = drawers[i]
            drawers[i] = drawers[j]
            drawers[j] = temp
        }
    }
 
    fun playRandom(): Boolean {
        val openedDrawers = BooleanArray(100)
        for (prisonerNum in 0..99) {
            var prisonerSuccess = false
            for (i in 0..49) {
                val drawerNum = random.nextInt(100)
                if (!openedDrawers[drawerNum]) {
                    openedDrawers[drawerNum] = true
                    break
                }
                if (drawers[drawerNum] == prisonerNum) {
                    prisonerSuccess = true
                    break
                }
            }
            if (!prisonerSuccess)
                return false
        }
        return true
    }
 
    fun playOptimal(): Boolean {
        for (prisonerNum in 0..99) {
            var prisonerSuccess = false
            var checkDrawerNum = prisonerNum
            for (i in 0..49) {
                if (drawers[checkDrawerNum] == prisonerNum) {
                    prisonerSuccess = true
                    break
                } else
                    checkDrawerNum = drawers[checkDrawerNum]
            }
            if (!prisonerSuccess)
                return false
        }
        return true
    }
}
 
fun simulate(strategy: Char): Double {
    var numberOfSuccesses = 0
    for (i in 0..9999) {
        val d = Cupboard()
        if ((strategy == 'R' && d.playRandom()) || (strategy == 'O' && d.playOptimal()))
            numberOfSuccesses++
    }
 
    return numberOfSuccesses * 100.0 / 10000
}
 
fun main(args: Array<String>) {
    println("Random strategy:  " + simulate('R') + " %")
    println("Optimal strategy: " + simulate('O') + " %")
};1

fun cleanText(text: String): String {
    // Step-1: collapse long runs of '_', '—', or '.' to '__'
    val longRunPattern = Pattern.compile("(_{4,}|—{4,}|\\.{4,})")
    var result = longRunPattern.matcher(text).replaceAll("__")

    // Step-2: remove unwanted characters
    val cleaned = StringBuilder()
    for (ch in result) {
        val code = ch.code
        // Explicitly exclude NUL and the replacement character
        if (code == 0 || code == 0xFFFD) {
            continue
        }
        // Remove control characters, but keep common whitespace controls
        val isControl = Character.getType(ch) == Character.CONTROL.toInt()
        if (isControl && ch != '\n' && ch != '\r' && ch != '\t') {
            continue
        }
        cleaned.append(ch)
    }
    return cleaned.toString()
};1

 
