import java.math.BigInteger

fun factorial(n: BigInteger): BigInteger {
    var ans = BigInteger.ONE
    for (x in BigInteger.ONE..n) {
        ans = ans.multiply(x)
    }
    return ans
}

fun leftFact(n: BigInteger): BigInteger {
    var ans = BigInteger.ZERO
    for (k in BigInteger.ZERO..n.subtract(BigInteger.ONE)) {
        ans = ans.add(factorial(k))
    }
    return ans
}

fun main(args: Array<String>) {
    for (i in 0..10) {
        println("!$i = " + leftFact(BigInteger.valueOf(i.toLong())))
    }

    for (i in 20..110 step 10) {
        println("!$i = " + leftFact(BigInteger.valueOf(i.toLong())))
    }

    for (i in 1000..10000 step 1000) {
        println("!$i has " + leftFact(BigInteger.valueOf(i.toLong())).toString().length + " digits")
    }
};1

