import java.util.Arrays
 
class Node(var v: Int, var next: Node?)
 
class Slist(var head: Node?, var tail: Node?)
 
fun push(l: Slist, e: Node) {
    if (l.head == null) l.head = e
    if (l.tail!= null) l.tail.next = e
    l.tail = e
}
 
fun removehead(l: Slist): Node? {
    val e = l.head
    if (e!= null) {
        l.head = e.next
        e.next = null
    }
    return e
}
 
fun join(a: Slist, b: Slist) {
    push(a, b.head!!)
    a.tail = b.tail
}
 
fun merge(a: Slist, b: Slist) {
    val r = Slist(null, null)
    while (a.head!= null && b.head!= null)
        push(r, removehead(if (a.head!!.v <= b.head!!.v) a else b)!!)
 
    join(r, if (a.head!= null) a else b)
    a.head = r.head
    a.tail = r.tail
    b.head = null
    b.tail = null
}
 
fun sort(ar: IntArray) {
    val all = Array(ar.size) { Node(ar[it], if (it < ar.size - 1) all[it + 1] else null) }
 
    val list = Slist(all[0], all[ar.size - 1])
    var rem = Slist(null, null)
    var strand = Slist(null, null)
    var res = Slist(null, null)
 
    while (list.head!= null) {
        rem.head = null
        rem.tail = null
        while (list.head!= null) {
            val e = removehead(list)
            push(if (strand.head == null || e!!.v >= strand.tail!!.v) strand else rem, e)
        }
        merge(res, strand)
        list.head = rem.head
        list.tail = rem.tail
    }
 
    for (i in 0 until ar.size) {
        ar[i] = res.head!!.v
        res.head = res.head!!.next
    }
}
 
