fun maxFriendlyPairs(redPoints: List<Pair<Int, Int>>, bluePoints: List<Pair<Int, Int>>): Int {
    val N = redPoints.size
    val adj = Array(N) { mutableListOf<Int>() }
    for ((i, red) in redPoints.withIndex()) {
        for ((j, blue) in bluePoints.withIndex()) {
            if (blue.first > red.first && blue.second > red.second) {
                adj[i].add(j)
            }
        }
    }
    val matchTo = IntArray(N) { -1 }
    fun dfs(u: Int, visited: BooleanArray): Boolean {
        for (v in adj[u]) {
            if (!visited[v]) {
                visited[v] = true
                if (matchTo[v] == -1 || dfs(matchTo[v], visited)) {
                    matchTo[v] = u
                    return true
                }
            }
        }
        return false
    }
    var result = 0
    for (u in 0 until N) {
        val visited = BooleanArray(N) { false }
        if (dfs(u, visited)) {
            result++
        }
    }
    return result
};1

