fun minimalCheapestSuccessfulJourney(n: Int, k: Int, cost: Array<IntArray>): Int {
    val INF = Int.MAX_VALUE / 2 // avoid overflow
    var prev = Array(n) { IntArray(2) { INF } }
    prev[0][0] = 0
    for (step in 1..k) {
        val curr = Array(n) { IntArray(2) { INF } }
        for (u in 0 until n) {
            for (p in 0..1) {
                if (prev[u][p] == INF) continue
                for (v in 0 until n) {
                    if (u == v) continue
                    val newCost = prev[u][p] + cost[u][v]
                    val newP = 1 - p
                    if (newCost < curr[v][newP]) {
                        curr[v][newP] = newCost
                    }
                }
            }
        }
        prev = curr
    }
    return prev[0][0]
};1

fun assignNum(value: Any?): Double? {
    // If the value is already numeric (Int or Double), return it directly as Double
    when (value) {
        is Int -> return value.toDouble()
        is Double -> return value
        else -> {
            // First, try converting to Int (for whole-number strings like "42")
            try {
                val num = value?.toString()?.toInt()
                return num?.toDouble()
            } catch (_: Exception) {
                // Not an Int, try Double next
            }
            // Next, try converting to Double (handles decimals, scientific notation, etc.)
            try {
                val num = value?.toString()?.toDouble()
                return num
            } catch (_: Exception) {
                // Conversion failed; return null
                return null
            }
        }
    }
};1

fun solve(rules: Map<Pair<Char, Char>, Char>, initialPairCounts: Map<Pair<Char, Char>, Long>, steps: Int): Long {

    var pairCounts = initialPairCounts
    for (step in 1..steps) {
        pairCounts = pairCounts.entries.fold(emptyMap()) { acc, pairCount ->
            val ch = rules[pairCount.key]
            if (ch != null) {
                acc + Pair(pairCount.key.first, ch).let { it to (acc[it] ?: 0L) + pairCount.value } +
                        Pair(ch, pairCount.key.second).let { it to (acc[it] ?: 0L) + pairCount.value }
            } else {
                acc + (pairCount.key to pairCount.value)
            }
        }
    }

    val counts = pairCounts.entries
        .fold(emptyMap<Char, Long>()) { acc, pairCount ->
            acc + (pairCount.key.first to (acc[pairCount.key.first] ?: 0L) + pairCount.value)
        }
    return counts.values.let { it.maxOrNull()!! - it.minOrNull()!! }
};0

fun sieve(n: Int): List<Int> {
    val primes = mutableListOf<Int>()
    val isPrime = BooleanArray(n + 1) { true }
    for (i in 2..n) {
        if (isPrime[i]) {
            primes.add(i)
            for (j in i * i..n step i) {
                isPrime[j] = false
            }
        }
    }
    return primes
}
 
