fun treeTagWinner(n: Int, a: Int, b: Int, da: Int, db: Int, edges: List<List<Int>>): String {
    val adj = MutableList(n + 1) { mutableListOf<Int>() }
    for (edge in edges) {
        val u = edge[0]
        val v = edge[1]
        adj[u].add(v)
        adj[v].add(u)
    }

    fun getDist(start: Int, goal: Int): Int {
        val visited = BooleanArray(n + 1)
        val q: Deque<Pair<Int, Int>> = ArrayDeque()
        q.add(Pair(start, 0))
        visited[start] = true
        while (q.isNotEmpty()) {
            val (node, d) = q.removeFirst()
            if (node == goal) return d
            for (neighbor in adj[node]) {
                if (!visited[neighbor]) {
                    visited[neighbor] = true
                    q.add(Pair(neighbor, d + 1))
                }
            }
        }
        return -1
    }

    val distAb = getDist(a, b)
    if (distAb <= da) return "Alice"
    if (2 * da >= db) return "Alice"

    fun bfsFarthest(start: Int): Pair<Int, Int> {
        val visited = BooleanArray(n + 1)
        val q: Deque<Pair<Int, Int>> = ArrayDeque()
        q.add(Pair(start, 0))
        visited[start] = true
        var maxD = 0
        var farNode = start
        while (q.isNotEmpty()) {
            val (node, d) = q.removeFirst()
            if (d > maxD) {
                maxD = d
                farNode = node
            }
            for (neighbor in adj[node]) {
                if (!visited[neighbor]) {
                    visited[neighbor] = true
                    q.add(Pair(neighbor, d + 1))
                }
            }
        }
        return Pair(farNode, maxD)
    }

    val (u, _) = bfsFarthest(1)
    val (_, diameter) = bfsFarthest(u)
    if (diameter <= 2 * da) return "Alice"
    return "Bob"
};1

