fun insert(r: Node?, value: Int): Node {
    var root = r
    when {
        root == null -> {
            root = Node(value)
        }

        value == root.value -> {
            root.cnt++
        }

        value < root.value -> {
            root.left = insert(root.left, value)
        }

        else -> {
            root.cnt++
            root.right = insert(root.right, value)
        }
    }

    return root
};0

