fun countUniqueChars(s: String): Int {
    if (s.isEmpty()) {
        return 0
    }
    var bitmask = 0L
    var count = 0
    for (c in s) {
        val code = c.code
        // Kotlin Int is 32 bits; to support more chars, use a Long (64 bits)
        if ((bitmask and (1L shl code)) == 0L) {
            count += 1
            bitmask = bitmask or (1L shl code)
        }
    }
    return count
};1

fun removeDuplicates(lst: List<Any>): List<Any> {
    val seen = mutableSetOf<Any>()
    val result = mutableListOf<Any>()
    for (item in lst) {
        if (item !in seen) {
            seen.add(item)
            result.add(item)
        }
    }
    return result
};1

