fun compareVersions(version1: String, version2: String): Int {
    // Split versions into integer lists
    val nums1 = version1.split('.').map { it.toInt() }.toMutableList()
    val nums2 = version2.split('.').map { it.toInt() }.toMutableList()

    // Determine the longest length to compare
    val maxLen = maxOf(nums1.size, nums2.size)

    // Extend the shorter list with zeros (implicit missing parts)
    while (nums1.size < maxLen) nums1.add(0)
    while (nums2.size < maxLen) nums2.add(0)

    // Compare component by component
    for (i in 0 until maxLen) {
        val a = nums1[i]
        val b = nums2[i]
        if (a > b) return 1
        if (a < b) return -1
    }
    return 0
};1

