        ""
    } else {
        "${justifyRight(4)(" ")(n.toString())} : ${k}"
    }
}

fun asciiName(n: Int): String {
    return if (32 > n || 127 < n) {
        ""
    } else if (32 == n) {
        "Spc"
    } else if (127 == n) {
        "Del"
    } else {
        chr(n)
    }
}

fun chr(x: Int): String {
    return x.toChar().toString()
}

fun chunksOf(n: Int): (List<Any>) -> List<List<Any>> {
    return { xs ->
        fun go(xs: List<Any>): List<List<Any>> {
            val chunk = xs.slice(0 until n)
            return if (0 < chunk.size) {
                listOf(chunk) + go(xs.slice(n until xs.size))
            } else {
                listOf()
            }
        }
        go(xs)
    }
}

fun enumFromTo(m: Int): (Int) -> List<Int> {
    return { n ->
        List(1 + n - m) { i -> m + i }
    }
}

fun justifyLeft(n: Int): (Char) -> (String) -> String {
    return { c ->
        { s ->
            if (n > s.length) {
                s.padEnd(n, c)
            } else {
                s
            }
        }
    }
}

fun justifyRight(n: Int): (Char) -> (String) -> String {
    return { c ->
        { s ->
            if (Boolean(s)) {
                s.padStart(n, c)
            } else {
                ""
            }
        }
    }
}

fun transpose(rows: List<List<Any>>): List<List<Any>> {
    return if (0 < rows.size) {
        rows[0].mapIndexed { i, _ ->
            rows.flatMap { v -> v[i] }
        }
    } else {
        listOf()
    }
};1

