fun organizeIngredients(ingredientsList: List<String>): Map<String, String> {
    val ingredientsDict = mutableMapOf<String, String>()
    for (ingredient in ingredientsList) {
        val parts = ingredient.split(" ")
        val quantity: String
        val name: String
        if (parts.size == 2) {
            quantity = parts[0]
            name = parts[1]
        } else {
            quantity = parts.subList(0, parts.size - 1).joinToString(" ")
            name = parts.last()
        }
        ingredientsDict[name] = quantity
    }
    return ingredientsDict
