fun miller_rabin_prime(n: Int, g: Int): Boolean {
    var d = n - 1
    var s = 0
    while (d % 2 == 0) {
        d /= 2
        s += 1
    }
    for (i in 0 until g) {
        val a = 2 + (Math.random() * (n - 4)).toInt()
        var x = a.pow(d, n) // x = (a**d) % n
        if (x == 1 || x == n - 1) continue
        for (r in 1 until s) {
            x = x.pow(2, n) // x = (x**2) % n
            if (x == 1) return false
            if (x == n - 1) break
        }
        if (x!= n - 1) return false
    }
    return true // probably
}
 
fun main(args: Array<String>) {
    val primes = (3..1000).step(2).filter { miller_rabin_prime(it, 10) }
    println(primes)
};1

