class oo {
    fun evolve(l: Int, rule: Int) {
        var cells: String = "O"
        println(" Rule #" + rule + ":")
        for (x in 0..l - 1) {
            addNoCells(cells)
            println(cells.padStart(40 + (cells.length shr 1)))
            step(cells, rule)
        }
    }
 
    fun step(cells: String, rule: Int) {
        var bin: Int
        var newCells: String
        for (i in 0..cells.length - 3) {
            bin = 0
            for (n in i..i + 2) {
                bin += if (cells[n] == 'O') 1 else 0 shl 2 - (n - i)
            }
            newCells += if (rule and (1 shl bin)!= 0) 'O' else '.'
        }
        cells = newCells
    }
 
    fun addNoCells(s: String) {
        var l: Char = if (s[0] == 'O') '.' else 'O'
        var r: Char = if (s[s.length - 1] == 'O') '.' else 'O'
        s = l + s + r
        s = l + s + r
    }
}
 
fun main(args: Array<String>) {
    var o: oo = oo()
    o.evolve(35, 90)
    println()
};1

fun calculatePoints(matches: List<Pair<Int, Int>>): Int {
    var totalPoints = 0
    for ((ludogoretsGoals, opponentGoals) in matches) {
        if (ludogoretsGoals > opponentGoals) {
            totalPoints += 3
        } else if (ludogoretsGoals == opponentGoals) {
            totalPoints += 1
        }
        // else: 0 points for a loss
    }
    return totalPoints
