    }
}
 
fun zeckendorf(n: Int): Int {
    // initial arguments of fib0 = 1 and fib1 = 1 will produce
    // the Fibonacci sequence {1, 2, 3,..} on the stack as successive
    // values of fib1.
    val (remaining, set) = zr(1, 1, n, 0)
    return set
}
 
fun zr(fib0: Int, fib1: Int, n: Int, bit: Int): Pair<Int, Int> {
    if (fib1 > n) {
        return Pair(n, 0)
    }
    // recurse.
    // construct sequence on the way in, construct ZR on the way out.
    val (remaining, set) = zr(fib1, fib0 + fib1, n, bit + 1)
    if (fib1 <= remaining) {
        return Pair(remaining - fib1, set or (1 shl bit))
    }
    return Pair(remaining, set)
};1

