class Maybe<T>(val value: T?) {
    fun map(f: (T) -> T): Maybe<T> {
        return if (value == null) {
            this
        } else {
            Maybe(f(value))
        }
    }
}
 
fun <T> Maybe<T>.bind(f: (T) -> Maybe<T>): Maybe<T> {
    return if (value == null) {
        this
    } else {
        f(value)
    }
}
 
fun <T> Maybe.Companion.unit(value: T): Maybe<T> {
    return Maybe(value)
}
 
