internal class recorder {
    fun start() {
        var paused = false
        var rec = false
        var action = "IDLE"
        while (true) {
            println()
            println("==" + action + "==")
            println()
            println("1) Record")
            println("2) Play")
            println("3) Pause")
            println("4) Stop")
            println("5) Quit")
            val c = readLine()!!.get(0)
            if (c > '0' && c < '6') {
                when (c) {
                    '1' -> record()
                    '2' -> play()
                    '3' -> pause()
                    '4' -> stop()
                    '5' -> {
                        stop()
                        return
                    }
                }
            }
        }
    }

    fun record() {
        if (mciExecute("open new type waveaudio alias my_sound")) {
            mciExecute("record my_sound")
            action = "RECORDING"
            rec = true
        }
    }

    fun play() {
        if (paused) {
            mciExecute("play my_sound")
        } else {
            if (mciExecute("open tmp.wav alias my_sound")) {
                mciExecute("play my_sound")
            }
        }
        action = "PLAYING"
        paused = false
    }

    fun pause() {
        if (rec) {
            return
        }
        mciExecute("pause my_sound")
        paused = true
        action = "PAUSED"
    }

    fun stop() {
        if (rec) {
            mciExecute("stop my_sound")
            mciExecute("save my_sound tmp.wav")
            mciExecute("close my_sound")
            action = "IDLE"
            rec = false
        } else {
            mciExecute("stop my_sound")
            mciExecute("close my_sound")
            action = "IDLE"
        }
    }

    fun mciExecute(cmd: String): Boolean {
        if (mciSendString(cmd, null, 0, null)!= 0) {
            println("Can't do this: " + cmd)
            return false
        }
        return true
    }
}
 
fun main(args: Array<String>) {
    val r = recorder()
    r.start()
};1

 
import java.io.File
 
val wordList = "unixdict.txt"
val url = "http://www.puzzlers.org/pub/wordlists/unixdict.txt"
 
const val DIGITS = "22233344455566677778889999"
 
val map = mutableMapOf<String, MutableList<String>>()
 
fun processList() {
    var countValid = 0
    val f = File(wordList)
    val sb = StringBuilder()
 
    f.forEachLine { word->
        var valid = true
        sb.setLength(0)
        for (c in word.toLowerCase()) {
            if (c !in 'a'..'z') {
                valid = false
                break
            }
            sb.append(DIGITS[c - 'a'])
        }
        if (valid) {
            countValid++
            val key = sb.toString()
            if (map.containsKey(key)) {
                map[key]!!.add(word)
            }
            else {
                map.put(key, mutableListOf(word))
            }
        }
    }
    var textonyms = map.filter { it.value.size > 1 }.toList()
    val report = "There are $countValid words in '$url' " +
                 "which can be represented by the digit key mapping.\n" +
                 "They require ${map.size} digit combinations to represent them.\n" +
                 "${textonyms.size} digit combinations represent Textonyms.\n"
    println(report)
 
    val longest = textonyms.sortedByDescending { it.first.length }
    val ambiguous = longest.sortedByDescending { it.second.size }
 
    println("Top 8 in ambiguity:\n")
    println("Count   Textonym  Words")
    println("======  ========  =====")
    var fmt = "%4d    %-8s  %s"
    for (a in ambiguous.take(8)) println(fmt.format(a.second.size, a.first, a.second))
 
    fmt = fmt.replace("8", "14")
    println("\nTop 6 in length:\n")
    println("Length  Textonym        Words")
    println("======  ==============  =====")
    for (l in longest.take(6)) println(fmt.format(l.first.length, l.first, l.second))
}
 
fun main(args: Array<String>) {
    processList()
};0

fun trappedRainwater(heights: Array<Int>): Int {
    if (heights.isEmpty()) {
        return 0
    }
    if (heights.any { it < 0 }) {
        throw IllegalArgumentException("No height can be negative")
    }
    val length = heights.size

    val leftMax = IntArray(length)
    leftMax[0] = heights[0]
    for (i in 1 until length) {
        leftMax[i] = maxOf(heights[i], leftMax[i - 1])
    }

    val rightMax = IntArray(length)
    rightMax[length - 1] = heights[length - 1]
    for (i in length - 2 downTo 0) {
        rightMax[i] = maxOf(heights[i], rightMax[i + 1])
    }

    var total = 0
    for (i in 0 until length) {
        total += minOf(leftMax[i], rightMax[i]) - heights[i]
    }
    return total
};1

fun getSierpinskiTriangle(n: Int): String {
    if (n == 0) {
        return "*"
    }
    val s = getSierpinskiTriangle(n - 1)
    val split = s.split("\n")
    val length = split.size
    //  Top triangle
    val sb = StringBuilder()
    val top = buildSpace((2.0).pow(n - 1).toInt())
    for (i in 0 until length) {
        sb.append(top)
        sb.append(split[i])
        sb.append("\n")
    }
    //  Two triangles side by side
    for (i in 0 until length) {
        sb.append(split[i])
        sb.append(buildSpace(length - i))
        sb.append(split[i])
        sb.append("\n")
    }
    return sb.toString()
}
 
fun buildSpace(n: Int): String {
    val sb = StringBuilder()
    for (i in 0 until n) {
        sb.append(" ")
    }
    return sb.toString()
}
 
fun main(args: Array<String>) {
    println(getSierpinskiTriangle(4))
};1

