fun parseConfig(config: String): Map<String, List<String>> {
    val regex = """^([A-Z]+)(.*)$""".toRegex()
    val configObject = mutableMapOf<String, List<String>>()

    var match: MatchResult?
    while (match = regex.find(config)) {
        val key = match.groups[1]!!.value
        val values = match.groups[2]!!.value.split(",")
        if (values.size == 1) {
            configObject[key] = listOf(values[0])
        } else {
            configObject[key] = values.map { it.trim() }
        }
    }

    return configObject
};1

