import kotlin.math.pow
import kotlin.math.sqrt
 
data class Imprecise(val value: Double, val delta: Double)
 
fun impreciseAdd(a: Imprecise, b: Imprecise): Imprecise {
    return Imprecise(a.value + b.value, sqrt(a.delta.pow(2) + b.delta.pow(2)))
}
 
fun impreciseMul(a: Imprecise, b: Imprecise): Imprecise {
    return Imprecise(a.value * b.value, sqrt((a.value * b.delta).pow(2) + (b.value * a.delta).pow(2)))
}
 
fun impreciseDiv(a: Imprecise, b: Imprecise): Imprecise {
    return Imprecise(a.value / b.value, sqrt((a.value * b.delta).pow(2) + (b.value * a.delta).pow(2)) / b.value.pow(2))
}
 
fun imprecisePow(a: Imprecise, c: Double): Imprecise {
    return Imprecise(a.value.pow(c), (a.value.pow(c) * c * a.delta / a.value).absoluteValue)
}
 
fun printImprecise(val: Imprecise): String {
    return "${val.value}±${val.delta}"
}
 
fun main() {
    val x1 = Imprecise(100.0, 1.1)
    val y1 = Imprecise(50.0, 1.2)
    val x2 = Imprecise(-200.0, 2.2)
    val y2 = Imprecise(-100.0, 2.3)
    val d = imprecisePow(impreciseAdd(imprecisePow(impreciseAdd(x1, x2), 2.0), imprecisePow(impreciseAdd(y1, y2), 2.0)), 0.5)
    println("Distance, d, between the following points :")
    println("( x1, y1) = ( ${printImprecise(x1)}, ${printImprecise(y1)})")
    println("( x2, y2) = ( ${printImprecise(x2)}, ${printImprecise(y2)})")
    println("is d = ${printImprecise(d)}")
};1

fun solveCubicNormed(x: FloatArray, aIn: Float, b: Float, c: Float): Int {
    var a = aIn

    val a2 = a * a
    var q = 1 / 9.0f * (a2 - 3.0f * b)
    val r = 1 / 54.0f * (a * (2.0f * a2 - 9.0f * b) + 27.0f * c)
    val r2 = r * r
    val q3 = q * q * q
    a *= 1.0f / 3.0f

    if (r2 < q3) {
        var t = r * (1.0f / sqrt(q3))
        if (t < -1) t = -1.0f
        if (t > 1) t = 1.0f
        t = fastACos(t)
        q = -2.0f * sqrt(q)
        x[0] = q * cos(1.0f / 3.0f * t) - a
        x[1] = (q * cos(1.0f / 3.0f * (t + 2.0f * PI_F)) - a)
        x[2] = q * cos(1.0f / 3.0f * (t - 2.0f * PI_F)) - a
        return 3
    } else {
        val u = (if (r < 0.0f) 1.0f else -1.0f) * (abs(r) + sqrt(r2 - q3)).pow(1 / 3.0f)
        val v = if (u == 0.0f) 0.0f else q / u
        x[0] = (u + v) - a
        if (u == v || abs(u - v) < 1e-12 * abs(u + v)) {
            x[1] = -0.5f * (u + v) - a
            return 2
        }
        return 1
    }
};0

