fun analyzeSurveyData(surveyData: List<Map<String, Int>>): Map<String, Double> {
    val factorScores = mutableMapOf<String, MutableList<Int>>()
    for (response in surveyData) {
        for ((factor, score) in response) {
            if (factor !in factorScores) {
                factorScores[factor] = mutableListOf(score)
            } else {
                factorScores[factor]!!.add(score)
            }
        }
    }
    val averageScores = mutableMapOf<String, Double>()
    for ((factor, scores) in factorScores) {
        averageScores[factor] = scores.sum().toDouble() / scores.size
    }
    return averageScores
};1

fun checkShiritori(n: Int, words: List<String>): String {
    val seen = mutableSetOf<String>()
    for (i in 0 until n) {
        if (words[i] in seen) {
            return "No"
        }
        seen.add(words[i])
        if (i > 0) {
            if (words[i][0] != words[i - 1].last()) {
                return "No"
            }
        }
    }
    return "Yes"
