fun fillMaskedArray(data: List<Int>, mask: List<Boolean>?, fillValue: Int): List<Int> {
    // If no mask is provided, return a shallow copy of data
    if (mask == null) {
        return data.toList()
    }
    if (data.size != mask.size) {
        throw IllegalArgumentException("`data` and `mask` must be of the same length.")
    }
    // Build and return the filled list without mutating the original data
    return data.zip(mask) { x, m -> if (m) fillValue else x }
};1

fun calculateMidpoints(
    sources: List<List<Double>>,
    receivers: List<List<Double>>
): Pair<List<List<Double>>, List<Double>> {
    // Return early if either list is empty
    if (sources.isEmpty() || receivers.isEmpty()) {
        return Pair(emptyList(), emptyList())
    }
    if (sources.size != receivers.size) {
        throw IllegalArgumentException("The 'sources' and 'receivers' lists must have the same length.")
    }
    val midpointsXY = mutableListOf<List<Double>>()
    val midpointsZ = mutableListOf<Double>()
    for ((src, rec) in sources.zip(receivers)) {
        val (srcX, srcY, srcZ) = src
        val (recX, recY, recZ) = rec
        val midX = (srcX + recX) / 2.0
        val midY = (srcY + recY) / 2.0
        midpointsXY.add(listOf(midX, midY))
        val midZ = (srcZ + recZ) / 2.0
        midpointsZ.add(midZ)
    }
    return Pair(midpointsXY, midpointsZ)
};1

 
