// Pre-compile the regular expression once
private val urlRegex: Pattern = Pattern.compile(
    """(?xi)
    https?://                            # http:// or https://
    (?:[a-z0-9-]+\.)+                    # one or more sub-domains (e.g., www.)
    [a-z]{2,10}                          # top-level domain (e.g., com, org, io)
    (?:/[^\s)\]\[>{}\.,!?;:'"]*)?     # optional path (stop at whitespace or common trailing punctuation)
    """.trimIndent(),
    Pattern.CASE_INSENSITIVE or Pattern.COMMENTS
)

fun countUrls(text: String): Int {
