fun parseMap(lines: List<String>): Pair<Numbers, Symbols> {
    val numbers: Numbers = hashMapOf()
    val symbols: Symbols = hashMapOf()

    val regex = """\d+""".toRegex()

    lines.forEachIndexed { y, s ->
        var x = 0
        var currentLine = s

        while (currentLine.isNotEmpty()) {
            val currentChar = currentLine.first()
            if (currentChar.isDigit()) {
                val match = regex.find(currentLine)!!
                val num = match.value.toInt()
                numbers[Pair(x, y)] = num
                x += match.value.length
                currentLine = currentLine.substring(match.value.length)
            } else {
                if (currentChar != '.') {
                    symbols[Pair(x, y)] = currentChar
                }
                x += 1
                currentLine = currentLine.substring(1)
            }
        }
    }

    return Pair(numbers, symbols)
};0

import kotlin.math.pow
import kotlin.math.sqrt
 
const val LIMIT = 15
var smallPrimes = IntArray(LIMIT)
 
fun sieve() {
    var i = 2
    var j: Int
    var p = 5
 
    smallPrimes[0] = 2
    smallPrimes[1] = 3
 
    while (i < LIMIT) {
        for (j in 0 until i) {
            if (smallPrimes[j] * smallPrimes[j] <= p) {
                if (p % smallPrimes[j] == 0) {
                    p += 2
                    break
                }
            } else {
                smallPrimes[i++] = p
                p += 2
                break
            }
        }
    }
}
 
fun is_prime(n: Long): Boolean {
    var i: Long
 
    for (i in 0 until LIMIT) {
        if (n % smallPrimes[i.toInt()] == 0L) {
            return n == smallPrimes[i.toInt()].toLong()
        }
    }
 
    i = smallPrimes[LIMIT - 1] + 2
    while (i * i <= n) {
        if (n % i == 0L) {
            return false
        }
        i += 2
    }
 
    return true
}
 
fun divisor_count(n: Long): Long {
    var count = 1L
    var d: Long
 
    while (n % 2 == 0L) {
        n /= 2
        count++
    }
 
    for (d in 3..n step 2) {
        var q = n / d
        var r = n % d
        var dc = 0L
        while (r == 0L) {
            dc += count
            n = q
            q = n / d
            r = n % d
        }
        count += dc
    }
 
    if (n!= 1L) {
        return count * 2
    }
    return count
}
 
fun OEISA073916(n: Long): Long {
    var count = 0L
    var result = 0L
    var i: Long
 
    if (is_prime(n)) {
        return (smallPrimes[n.toInt() - 1].toLong().toDouble().pow(n.toInt() - 1)).toLong()
    }
 
    for (i in 1..n) {
        if (n % 2 == 1L) {
            //  The solution for an odd (non-prime) term is always a square number
            val root = sqrt(i.toDouble()).toLong()
            if (root * root!= i) {
                continue
            }
        }
        if (divisor_count(i) == n) {
            count++
            result = i
        }
    }
 
    return result
}
 
fun main() {
    var n: Long
 
    sieve()
 
    for (n in 1..LIMIT) {
        if (n == 13L) {
            println("A073916($n) = One more bit needed to represent result.")
        } else {
            println("A073916($n) = ${OEISA073916(n)}")
        }
    }
};1

