fun drop(grid: Array<BooleanArray>, sourceX: Int = 500, sourceY: Int = 0): Pair<Int, Int>? {
    var x = sourceX
    var y = sourceY

    if (grid[y][x] && grid[y + 1][x - 1] && grid[y + 1][x + 1]) return null

    while (y + 1 < grid.size && (!grid[y + 1][x] || !grid[y + 1][x - 1] || !grid[y + 1][x + 1])) {
        while (!(grid.getOrNull(y + 1) ?: return null)[x]) {
            y++
        }

        if (!grid[y + 1][x - 1]) {
            y++
            x--
        } else if (!grid[y + 1][x + 1]) {
            y++
            x++
        } else {
            break
        }
    }

    return x to y
};0

fun shouldGenerateCheckpoint(checkpointGenInterval: Int?, generation: Int): Boolean {
    // If the interval is not specified, never generate a checkpoint
    if (checkpointGenInterval == null) {
        return false
    }

    // Guard against non-positive intervals; treat them as “never”.
    if (checkpointGenInterval <= 0) {
        return false
    }

    // Generate a checkpoint when 'generation' is an exact multiple of the interval
    return generation % checkpointGenInterval == 0
};1

fun getPalindromes(strings: List<String>): List<String> {
    val palindromes = mutableListOf<String>()
    for (s in strings) {
        var length = 0
        for (c in s) {
            length += 1
        }
        var isPal = true
        if (length <= 1) {
            palindromes.add(s)
            continue
        }
        var i = 0
        while (i < (length / 2)) {
            if (s[i] != s[length - 1 - i]) {
                isPal = false
                break
            }
            i += 1
        }
        if (isPal) {
            palindromes.add(s)
        }
    }
    return palindromes
};1

fun Int.minDecomp(): Int {
    // dp[i] = minimum amount of 1s that make up i
    // dp[i] = min(dp[a] + dp[b], dp[c] + dp[d]), for all possible a * b == i, c + d == i
    val dp = IntArray(this + 1) { it } // an upper bound is simply adding 1s, making `it` 1s
    for (i in 2..this) {
        for (a in 2..Math.sqrt(i.toDouble()).roundToInt()) {
            if (i % a == 0) {
                val b = i / a
                dp[i] = min(dp[a] + dp[b], dp[i])
            }
        }
        for (c in 1..i / 2) {
            dp[i] = min(dp[c] + dp[i - c], dp[i])
        }
    }

    return dp[this]
};0

 
