fun getRanges(testString: String): List<List<Int>> {
    val numbers = testString.split(",").map { it.trim().toInt() }
    val current = ArrayList<Int>()
    val ranges = ArrayList<List<Int>>()
    for (n in numbers) {
        if (current.isEmpty()) {
            current.add(n)
        } else {
            if (current.max()!! + 1 == n) {
                current.add(n)
            } else {
                ranges.add(current)
                current.clear()
                current.add(n)
            }
        }
    }
    ranges.add(current)
    return ranges
}
 
fun rangesToStrings(ranges: List<List<Int>>): String {
    val result = ArrayList<String>()
    for (range in ranges) {
        if (range.size == 1) {
            result.add(range[0].toString())
        } else if (range.size == 2) {
            result.add(range.min()!!.toString() + "," + range.max())
        } else {
            result.add(range.min()!!.toString() + "-" + range.max())
        }
    }
    return result.joinToString(",")
};1

 
class Stack<E> {
    private val data = mutableListOf<E>()
 
    val size get() = data.size
 
    val empty get() = size == 0
 
    fun push(element: E) = data.add(element)
 
    fun pop(): E {
        if (empty) throw RuntimeException("Can't pop elements from an empty stack")
        return data.removeAt(data.lastIndex)
    }
 
    val top: E
        get() {
            if (empty) throw RuntimeException("Empty stack can't have a top element")
            return data.last()
        }
 
    fun clear() = data.clear()
 
    fun toString() = data.toString()
}
 
fun main(args: Array<String>) {
    val s = Stack<Int>()
    (1..5).forEach { s.push(it) }
    println(s)
    println("Size of stack = ${s.size}")
    print("Popping: ")
    (1..3).forEach { print("${s.pop()} ") }
    println("\nRemaining on stack: $s")
    println("Top element is now ${s.top}")
    s.clear()
    println("After clearing, stack is ${if(s.empty) "empty" else "not empty"}")
    try {
        s.pop()
    }
    catch (e: Exception) {
        println(e.message)
    }
};0

import kotlin.math.gcd
 
fun pt1(maxperimeter: Int = 100): Set<Triple<Int, Int, Int>> {
    val trips = mutableSetOf<Triple<Int, Int, Int>>()
    for (a in 1..maxperimeter) {
        val aa = a * a
        for (b in a..maxperimeter - a + 1) {
            val bb = b * b
            for (c in b..maxperimeter - b - a + 1) {
                val cc = c * c
                if (a + b + c > maxperimeter || cc > aa + bb) break
                if (aa + bb == cc) {
                    trips.add(Triple(a, b, c))
                }
            }
        }
    }
    return trips
}
 
fun pytrip(trip: Triple<Int, Int, Int> = Triple(3, 4, 5), perim: Int = 100, prim: Int = 1): Set<Triple<Int, Int, Int>> {
    val a0 = trip.first
    val b0 = trip.second
    val c0 = trip.third
    val t = mutableSetOf<Triple<Int, Int, Int>>()
    var firstprim = prim > 0
    while (a0 + b0 + c0 <= perim) {
        t.add(Triple(a0, b0, c0, firstprim))
        a0 += a0
        b0 += b0
        c0 += c0
        firstprim = false
    }
    val t2 = mutableSetOf<Triple<Int, Int, Int>>()
    for (a in t) {
        val a2 = a.first * 2
        val a5 = a.first * 5
        val b2 = a.second * 2
        val b5 = a.second * 5
        val c2 = a.third * 2
        val c3 = a.third * 3
        val c7 = a.third * 7
        if (a5 - b5 + c7 <= perim) {
            t2 += pytrip(Triple(a.first - b2 + c2, a2 - a.second + c2, a2 - b2 + c3), perim, a.fourth)
        }
        if (a5 + b5 + c7 <= perim) {
            t2 += pytrip(Triple(a.first + b2 + c2, a2 + a.second + c2, a2 + b2 + c3), perim, a.fourth)
        }
        if (-a5 + b5 + c7 <= perim) {
            t2 += pytrip(Triple(-a.first + b2 + c2, -a2 + a.second + c2, -a2 + b2 + c3), perim, a.fourth)
        }
    }
    return t + t2
}
 
fun pt2(maxperimeter: Int = 100): Set<Triple<Int, Int, Int>> {
    val trips = pytrip(Triple(3, 4, 5), maxperimeter, 1)
    return trips
}
 
fun printit(maxperimeter: Int = 100, pt: (Int) -> Set<Triple<Int, Int, Int>> = ::pt1) {
    val trips = pt(maxperimeter)
    println("  Up to a perimeter of %i there are %i triples, of which %i are primitive".format(maxperimeter, trips.size, trips.filter { it.fourth }.size))
}
 
