class TreeNode(var `val`: Int, var left: TreeNode? = null, var right: TreeNode? = null)

fun insert(root: TreeNode?, value: Int): TreeNode? {
    fun exists(node: TreeNode?, v: Int): Boolean {
        if (node == null) return false
        if (node.`val` == v) return true
        return exists(node.left, v) || exists(node.right, v)
    }
    if (exists(root, value)) return root
    if (root == null) return TreeNode(value)
    val queue = java.util.ArrayDeque<TreeNode>()
    queue.add(root)
    while (queue.isNotEmpty()) {
        val current = queue.removeFirst()
        if (current.left == null) {
            current.left = TreeNode(value)
            break
        } else {
            queue.add(current.left)
        }
        if (current.right == null) {
            current.right = TreeNode(value)
            break
        } else {
            queue.add(current.right)
        }
    }
    return root
};1

