fun String.toRound(): Round {
    var red = 0
    var green = 0
    var blue = 0

    this.split(",").map { it.trim() }.forEach {
        val amount = it.substringBefore(" ").toInt()
        when (it.substringAfter(" ")) {
            "red" -> red = amount
            "blue" -> blue = amount
            "green" -> green = amount
        }
    }

    return Round(red, green, blue)
};0

 
fun sumDigits(n: Long): Int = when {
        n < 0L -> throw IllegalArgumentException("Negative numbers not allowed")
        else   -> {
            var sum = 0
            var nn  = n
            while (nn > 0L) {
                sum += (nn % 10).toInt()
                nn /= 10
            }
            sum
        }
    }
 
fun digitalRoot(n: Long): Pair<Int, Int> = when {
        n < 0L  -> throw IllegalArgumentException("Negative numbers not allowed")
        n < 10L -> Pair(n.toInt(), 0)
        else    -> {
            var dr = n
            var ap = 0
            while (dr > 9L) {
                dr = sumDigits(dr).toLong()
                ap++
            }
            Pair(dr.toInt(), ap)
        }
    }
 
