import java.util.*
 
fun main(args: Array<String>) {
    val board = arrayOf(
        ".00.00.",
        "0000000",
        "0000000",
        ".00000.",
        "..000..",
        "...0..."
    )
 
    val moves = arrayOf(
        intArrayOf(-3, 0),
        intArrayOf(0, 3),
        intArrayOf(3, 0),
        intArrayOf(0, -3),
        intArrayOf(2, 2),
        intArrayOf(2, -2),
        intArrayOf(-2, 2),
        intArrayOf(-2, -2)
    )
    val nRows = board.size + 6
    val nCols = board[0].length + 6
 
    val grid = Array(nRows) { IntArray(nCols) }
    var totalToFill = 0
 
    for (r in 0 until nRows) {
        Arrays.fill(grid[r], -1)
        for (c in 3 until nCols - 3)
            if (r >= 3 && r < nRows - 3) {
                if (board[r - 3][c - 3] == '0') {
                    grid[r][c] = 0
                    totalToFill++
                }
            }
    }
 
    var pos = -1
    var r = 0
    var c = 0
    do {
        do {
            pos++
            r = pos / nCols
            c = pos % nCols
        } while (grid[r][c] == -1)
 
        grid[r][c] = 1
        if (solve(r, c, 2, grid, moves, totalToFill))
            break
        grid[r][c] = 0
 
    } while (pos < nRows * nCols)
 
    printResult(grid)
}
 
fun solve(r: Int, c: Int, count: Int, grid: Array<IntArray>, moves: Array<IntArray>, totalToFill: Int): Boolean {
    if (count > totalToFill)
        return true
 
    val nbrs = neighbors(r, c, grid, moves)
 
    if (nbrs.isEmpty() && count!= totalToFill)
        return false
 
    nbrs.sortBy { it[2] }
 
    for (nb in nbrs) {
        r = nb[0]
        c = nb[1]
        grid[r][c] = count
        if (solve(r, c, count + 1, grid, moves, totalToFill))
            return true
        grid[r][c] = 0
    }
 
    return false
}
 
fun neighbors(r: Int, c: Int, grid: Array<IntArray>, moves: Array<IntArray>): List<IntArray> {
    val nbrs = mutableListOf<IntArray>()
 
    for (m in moves) {
        val x = m[0]
        val y = m[1]
        if (grid[r + y][c + x] == 0) {
            val num = countNeighbors(r + y, c + x, grid, moves) - 1
            nbrs.add(intArrayOf(r + y, c + x, num))
        }
    }
    return nbrs
}
 
fun countNeighbors(r: Int, c: Int, grid: Array<IntArray>, moves: Array<IntArray>): Int {
    var num = 0
    for (m in moves)
        if (grid[r + m[1]][c + m[0]] == 0)
            num++
    return num
}
 
