            if (i == -1)
                print("%2s ".format(' '))
            else
                print("%2d ".format(i));1

fun List<IntOffset>.getNextSteps(
    heightMap: Map<IntOffset, Char>,
    wayUp: Boolean
): List<List<IntOffset>> {
    val route = this
    val currentPosition = route.last()
    val currentHeight = heightMap[currentPosition]!!
    val possibleDirections = Direction.values()
        .map { currentPosition + it }
        .filterNot(route::contains)
        .filter(heightMap.keys::contains)

    val nextSteps = buildList {
        for (point in possibleDirections) {
            val pointHeight = heightMap[point]!!
            if (wayUp && pointHeight - 1 > currentHeight) continue
            if (!wayUp && pointHeight < currentHeight - 1) continue

            add(route + point)
        }
    }

    return nextSteps
};0

// Kotlin implementation of Chaocipher
// left wheel = ciphertext wheel
// right wheel = plaintext wheel
 
fun main() {
    // letters only! makealpha(key) helps generate lalpha/ralpha.
    val lalpha = "HXUCZVAMDSLKPEFJRIGTWOBNYQ"
    val ralpha = "PTLNBQDEOYSFAVZKGJRIHWXUMC"
    val msg = "WELLDONEISBETTERTHANWELLSAID"
 
    println("L: $lalpha")
    println("R: $ralpha")
    println("I: $msg")
    println("O: ${do_chao(msg, lalpha, ralpha, 1, 0)} \n")
 
    do_chao(msg, lalpha, ralpha, 1, 1)
}
 
fun do_chao(msg: String, lalpha: String, ralpha: String, en: Int, show: Int): String {
    val msg = correct_case(msg)
    var out = ""
    if (show == 1) {
        println("="*54)
        println(10*" " + "left:" + 21*" " + "right: ")
        println("="*54)
        println("$lalpha $ralpha \n")
    }
    for (L in msg) {
        if (en == 1) {
            val (lalpha, ralpha) = rotate_wheels(lalpha, ralpha, L)
            out += lalpha[0]
        } else {
            val (ralpha, lalpha) = rotate_wheels(ralpha, lalpha, L)
            out += ralpha[0]
        }
        val (lalpha, ralpha) = scramble_wheels(lalpha, ralpha)
        if (show == 1) {
            println("$lalpha $ralpha")
        }
    }
    return out
}
 
fun makealpha(key: String = ""): String {
    val alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    val z = mutableSetOf<String>()
    val key = (key + alpha.reversed()).map { it.toUpperCase() }
       .filter {!z.contains(it) && z.add(it) }
    return key.joinToString("")
}
 
fun correct_case(string: String): String {
    return string.filter { it.isLetter() }.toUpperCase()
}
 
fun permu(alp: String, num: Int): String {
    val alp = alp.split("").toMutableList()
    val (first, second) = alp.subList(0, num) to alp.subList(num, alp.size)
    return first.joinToString("") + second.joinToString("")
}
 
fun rotate_wheels(lalph: String, ralph: String, key: Char): Pair<String, String> {
    val newin = ralph.indexOf(key)
    return permu(lalph, newin), permu(ralph, newin)
}
 
fun scramble_wheels(lalph: String, ralph: String): Pair<String, String> {
    // LEFT = cipher wheel
    // Cycle second[1] through nadir[14] forward
    val lalph = lalph.split("").toMutableList()
    lalph.add(1, lalph.removeAt(0))
    lalph.add(14, lalph.removeAt(13))
 
    // RIGHT = plain wheel
    // Send the zenith[0] character to the end[25],
    // cycle third[2] through nadir[14] characters forward
    val ralph = ralph.split("").toMutableList()
    ralph.add(ralph.removeAt(0))
    ralph.add(14, ralph.removeAt(13))
    ralph.add(25, ralph.removeAt(24));1

