fun IntArray.countingSort(exp: Int) {
    val counts = IntArray(10)
    val output = IntArray(this.size)

    this.forEach { counts[(it / exp) % 10]++ }

    (1 until counts.size).forEach {
        counts[it] += counts[it - 1]
    }

    this.indices.reversed().forEach {
        val index = this[it] / exp
        output[counts[index % 10] - 1] = this[it]
        counts[index % 10]--
    }

    output.forEachIndexed { index, i ->
        this[index] = i
    }
};0

fun serveGuests(n: Int, pairs: List<Pair<Int, Int>>): Any {
    var valid = true
    for ((a, b) in pairs) {
        if ((a % 2) == (b % 2)) {
            valid = false
            break
        }
    }
    return if (!valid) {
        -1
    } else {
        val res = mutableListOf<Pair<Int, Int>>()
        for ((a, b) in pairs) {
            val aColor = if (a % 2 == 1) 1 else 2
            val bColor = if (b % 2 == 1) 1 else 2
            res.add(Pair(aColor, bColor))
        }
        res
    }
};1

/**
 * Get the left most index using binary search
 */
fun getLeftMostMatch(str: String, array: Array<String>, low: Int, high: Int): Int {
    if (low <= high) {
        val mid = (low + high) / 2
        if ((mid == 0 || array[mid - 1] != str) && array[mid] == str) {
            // if the left of mid is different than str, then this is the left most index
            return mid
        } else if (str > array[mid]) {
            return getLeftMostMatch(str, array, mid + 1, high)
        } else {
            return getLeftMostMatch(str, array, low, mid - 1)
        }
    }
    return -1
};0

fun sumAndProduct(a: Any?, b: Any?): String {
    fun isNumber(x: Any?): Boolean {
        return (x is Int || x is Double || x is Float || x is Long || x is Short) && x !is Boolean
    }
    if (!isNumber(a) || !isNumber(b)) {
        return "Both inputs must be a number!"
    }
    val numA = when (a) {
        is Int -> a.toDouble()
        is Double -> a
        is Float -> a.toDouble()
        is Long -> a.toDouble()
        is Short -> a.toDouble()
        else -> 0.0
    }
    val numB = when (b) {
        is Int -> b.toDouble()
        is Double -> b
        is Float -> b.toDouble()
        is Long -> b.toDouble()
        is Short -> b.toDouble()
        else -> 0.0
    }
    val summation = numA + numB
    val product = numA * numB
    val strA = if (a is Number) a.toString() else a.toString()
    val strB = if (b is Number) b.toString() else b.toString()
    return "The sum of $strA and $strB is $summation and their product is $product"
};1

