const val MOD = 1000000007

fun fastDoubling(n: Int, mod: Int): Pair<Long, Long> {
    if (n == 0) return Pair(0L, 1L)
    val (a, b) = fastDoubling(n shr 1, mod)
    val c = (a * ((2 * b - a + mod) % mod)) % mod
    val d = (a * a + b * b) % mod
    return if ((n and 1) != 0) Pair(d % mod, (c + d) % mod) else Pair(c % mod, d % mod)
}

fun nthShikharsFibonacci(a: Int, b: Int, n: Int): Int {
    if (n == 1) return ((a % MOD) + MOD) % MOD
    if (n == 2) return ((b % MOD) + MOD) % MOD
    val (x, _) = fastDoubling(n - 2, MOD)
    val (y, _) = fastDoubling(n - 1, MOD)
    // Use Long to avoid overflow
    val res = ((a.toLong() * x % MOD) + (b.toLong() * y % MOD)) % MOD
    return res.toInt()
};1

object Levenshtein {
    fun distance(a: String, b: String): Int {
        val a = a.toLowerCase()
        val b = b.toLowerCase()
        val costs = IntArray(b.length + 1) // i == 0
        for (i in 1..a.length) {
            costs[0] = i
            var nw = i - 1 // j == 0; nw is lev(i-1, j)
            for (j in 1..b.length) {
                val cost = if (a[i - 1] == b[j - 1]) 0 else 1
                costs[j] = Math.min(Math.min(costs[j] + 1, costs[j - 1] + 1), nw + cost)
                nw = costs[j]
            }
        }
        return costs[b.length]
    }
 
    fun test() {
        arrayOf("kitten", "sitting", "saturday", "sunday", "rosettacode", "raisethysword").chunked(2).forEach { (a, b) ->
            println("distance($a, $b) = ${distance(a, b)}")
        }
    }
}
 
