fun doublyLinkedList(operations: List<String>): String {
    class Node(val key: Int) {
        var prev: Node? = null
        var next: Node? = null
    }

    class DoublyLinkedList {
        var head: Node? = null
        var tail: Node? = null

        fun insert(x: Int) {
            val node = Node(x)
            if (head == null) {
                head = node
                tail = node
            } else {
                node.next = head
                head!!.prev = node
                head = node
            }
        }

        fun deleteFirst() {
            if (head == null) return
            if (head === tail) {
                head = null
                tail = null
            } else {
                head = head!!.next
                head!!.prev = null
            }
        }

        fun deleteLast() {
            if (tail == null) return
            if (head === tail) {
                head = null
                tail = null
            } else {
                tail = tail!!.prev
                tail!!.next = null
            }
        }

        fun delete(x: Int) {
            var cur = head
            while (cur != null) {
                if (cur.key == x) {
                    if (cur === head) {
                        deleteFirst()
                    } else if (cur === tail) {
                        deleteLast()
                    } else {
                        cur.prev!!.next = cur.next
                        cur.next!!.prev = cur.prev
                    }
                    break
                }
                cur = cur.next
            }
        }

        fun toList(): List<String> {
            val res = mutableListOf<String>()
            var cur = head
            while (cur != null) {
                res.add(cur.key.toString())
                cur = cur.next
            }
            return res
        }
    }

    val dll = DoublyLinkedList()
    for (op in operations) {
        when {
            op.startsWith("insert ") -> {
                val x = op.substringAfter(" ").toInt()
                dll.insert(x)
            }
            op.startsWith("delete ") -> {
                val x = op.substringAfter(" ").toInt()
                dll.delete(x)
            }
            op == "deleteFirst" -> {
                dll.deleteFirst()
            }
            op == "deleteLast" -> {
                dll.deleteLast()
            }
        }
    }
    return dll.toList().joinToString(separator = " ")
};1

