fun minimumSocksToRepaint(n: Int, m: Int, k: Int, colors: List<Int>, instructions: List<Pair<Int, Int>>): Int {
    class DSU(size: Int) {
        val parent = IntArray(size) { it }
        val rank = IntArray(size) { 1 }
        fun find(x: Int): Int {
            if (parent[x] != x) {
                parent[x] = find(parent[x])
            }
            return parent[x]
        }
        fun union(x: Int, y: Int) {
            val xRoot = find(x)
            val yRoot = find(y)
            if (xRoot == yRoot) return
            if (rank[xRoot] < rank[yRoot]) {
                parent[xRoot] = yRoot
            } else {
                parent[yRoot] = xRoot
                if (rank[xRoot] == rank[yRoot]) {
                    rank[xRoot] += 1
                }
            }
        }
    }
    val dsu = DSU(n)
    for ((l, r) in instructions) {
        dsu.union(l - 1, r - 1) // convert to 0-based
    }
    val groups = mutableMapOf<Int, MutableList<Int>>()
    for (i in 0 until n) {
        val root = dsu.find(i)
        groups.computeIfAbsent(root) { mutableListOf() }.add(colors[i])
    }
    var total = 0
    for (group in groups.values) {
        if (group.size < 2) continue
        val counts = group.groupingBy { it }.eachCount()
        val maxFreq = counts.values.maxOrNull() ?: 0
        total += group.size - maxFreq
    }
    return total
};1

fun count2_3Integers(l: Int, r: Int): Int {
    var count = 0
    var a = 1L
    while (a <= r.toLong()) {
        var current = a
        while (true) {
            if (current > r) {
                break
            }
            if (current >= l) {
                count += 1
            }
            if (current > r.toLong() / 3) {
                break
            }
            current *= 3
        }
        if (a > r.toLong() / 2) {
            break
        }
        a *= 2
    }
    return count
};1

fun determineTicketFields(ranges: Map<String, List<IntRange>>, myTicket: List<Int>, otherTickets: List<List<Int>>): Long {
    val r = ranges.values.flatten()
    val t = otherTickets.filter { it.validateTicket(r) }
    val fieldValues = Array<MutableList<Int>>(myTicket.size) { mutableListOf() }

    for (ticket in t) {
        for (i in 0..myTicket.lastIndex) {
            fieldValues[i].add(ticket[i])
        }
    }

    val possibleRanges = Array<MutableList<String>>(myTicket.size) { mutableListOf() }
    for (i in 0..fieldValues.lastIndex) {
        for (range in ranges) {
            if (fieldValues[i].validateTicket(range.value)) possibleRanges[i].add(range.key)
        }
    }

    while (possibleRanges.any { it.size != 1 }) {
        val unique = possibleRanges.filter { it.size == 1 }.flatten()
        possibleRanges.filter { it.size > 1 && it.any { name -> unique.contains(name) } }.forEach { it.removeAll(unique) }
    }

    var sum = 1L
    for (i in 0..possibleRanges.lastIndex) {
        if (possibleRanges[i].first().startsWith("departure")) sum *= myTicket[i]
    }

    return sum
};0

import java.util.ArrayList
import java.util.List
 
fun getDivisors(n: Int): List<Int> {
    val divs = ArrayList<Int>()
    divs.add(1)
    divs.add(n)
    for (i in 2..Math.sqrt(n.toDouble()).toInt()) {
        if (n % i == 0) {
            divs.add(i)
            if (i!= n / i) {
                divs.add(n / i)
            }
        }
    }
    return divs
}
 
fun isPartSum(divs: List<Int>, sum: Int): Boolean {
    if (sum == 0) {
        return true
    }
    val le = divs.size
    if (le == 0) {
        return false
    }
    val last = divs[le - 1]
    val newDivs = ArrayList<Int>()
    for (i in 0..le - 2) {
        newDivs.add(divs[i])
    }
    if (last > sum) {
        return isPartSum(newDivs, sum)
    }
    return isPartSum(newDivs, sum) || isPartSum(newDivs, sum - last)
}
 
fun isZumkeller(n: Int): Boolean {
    val divs = getDivisors(n)
    val sum = divs.sum()
    // if sum is odd can't be split into two partitions with equal sums
    if (sum % 2 == 1) {
        return false
    }
    // if n is odd use 'abundant odd number' optimization
    if (n % 2 == 1) {
        val abundance = sum - 2 * n
        return abundance > 0 && abundance % 2 == 0
    }
    // if n and sum are both even check if there's a partition which totals sum / 2
    return isPartSum(divs, sum / 2)
}
 
fun main(args: Array<String>) {
    println("The first 220 Zumkeller numbers are:")
    var i = 2
    var count = 0
    while (count < 220) {
        if (isZumkeller(i)) {
            print(String.format("%3d ", i))
            count++
            if (count % 20 == 0) {
                println()
            }
        }
        i++
    }
 
    println("\nThe first 40 odd Zumkeller numbers are:")
    i = 3
    count = 0
    while (count < 40) {
        if (isZumkeller(i)) {
            print(String.format("%5d ", i))
            count++
            if (count % 10 == 0) {
                println()
            }
        }
        i += 2
    }
 
    println("\nThe first 40 odd Zumkeller numbers which don't end in 5 are:")
    i = 3
    count = 0
    while (count < 40) {
        if (i % 10!= 5 && isZumkeller(i)) {
            print(String.format("%7d ", i))
            count++
            if (count % 8 == 0) {
                println()
            }
        }
        i += 2
    }
};1

