class User(val username: String, val passSalt: ByteArray, val passMd5: ByteArray)
 
fun connectDB(): Connection {
    Class.forName("com.mysql.jdbc.Driver")
    return DriverManager.getConnection("jdbc:mysql://localhost/rc", "rosetta", "code")
}
 
fun createUser(db: Connection, user: String, pwd: String): Boolean {
    val salt = ByteArray(16)
    SecureRandom().nextBytes(salt)
    val stmt = db.prepareStatement("insert into users (username, pass_salt, pass_md5) values (?, ?, ?)")
    stmt.setString(1, user)
    stmt.setBytes(2, salt)
    stmt.setBytes(3, saltHash(salt, pwd))
    return stmt.executeUpdate() == 1
}
 
fun authenticateUser(db: Connection, user: String, pwd: String): Boolean {
    val stmt = db.prepareStatement("select pass_salt, pass_md5 from users where username=?")
    stmt.setString(1, user)
    val rs = stmt.executeQuery()
    if (!rs.next()) {
        return false
    }
    val salt = rs.getBytes(1)
    val hash = rs.getBytes(2)
    return Arrays.equals(saltHash(salt, pwd), hash)
}
 
fun saltHash(salt: ByteArray, pwd: String): ByteArray {
    val md = MessageDigest.getInstance("MD5")
    md.update(salt)
    md.update(pwd.toByteArray())
    return md.digest()
}
 
