fun List<String>.toSnackSumSequence(): Sequence<Int> = sequence {
    var sum = 0

    for (item in this@toSnackSumSequence) {
        if (item.isBlank()) {
            this.yield(sum)
            sum = 0
        } else {
            sum += item.toInt()
        }
    }
    this.yield(sum)
};0

