fun sierpinski(intOrder: Int): String {
    return (1..Math.pow(2.0, intOrder.toDouble()).toInt() - 1)
       .fold(listOf("▲")) { lstRows, _ ->
            val lstPrevRow = lstRows.last()
            lstRows + zipWith({ left, right ->
                if (left == right) " " else "▲"
            }, listOf(' ') + lstPrevRow, lstPrevRow +'')
        }
       .foldRight(Pair("", "")) { lstLine, sofar ->
            Pair(sofar.first + lstLine.joinToString(" ") + "\n",
                sofar.second + " ")
        }.first
}
 
fun <T, U, V> zipWith(f: (T, U) -> V, xs: List<T>, ys: List<U>): List<V> {
    return if (xs.size == ys.size) xs.mapIndexed { i, x -> f(x, ys[i]) } else null
}
 
