/**
 * Generate the first `n` Fibonacci numbers.
 *
 * @param n The number of Fibonacci numbers to generate. Must be non-negative.
 * @return A list containing the first `n` numbers of the Fibonacci sequence, starting with 0.
 *         If `n` is 0 or negative, an empty list is returned.
 *
 * Examples:
 *   fibonacci(0) == listOf()
 *   fibonacci(1) == listOf(0)
 *   fibonacci(5) == listOf(0, 1, 1, 2, 3)
 */
fun fibonacci(n: Int): List<Int> {
    if (n <= 0) {
        return emptyList()
    }
    if (n == 1) {
        return listOf(0)
    }

    val fibs = mutableListOf(0, 1) // Seed the sequence with the first two Fibonacci numbers.
    for (i in 2 until n) {
        fibs.add(fibs[fibs.size - 1] + fibs[fibs.size - 2])
    }
    return fibs
};1

