fun sieve(limit: Int): BooleanArray {
    val composite = BooleanArray(limit)
    composite[0] = true
    composite[1] = true
 
    val max = sqrt(limit.toDouble()).toInt()
    for (n in 2..max) {
        if (!composite[n]) {
            for (k in n * n until limit step n) {
                composite[k] = true
            }
        }
    }
 
    return composite
};1

