// succinct LIS implementation for OneArray
// the algorithm is the same, but i just want to show how expressive Kotlin is!
fun OneArray<Int>.lis(): Int {
    val dp = OneArray(size) { 0 }
    for (i in size downTo 1)
        dp[i] = 1 + ((i + 1..size)
                .filter { this[it] > this[i] }
                .map { dp[it] }
                .max() ?: 0)
    return dp.max() ?: 0
};0

fun filterSubtreesBySize(tree: MutableMap<String, Any>, sizeLimit: Long, filterSmaller: Boolean = true): List<MutableMap<String, Any>> {
    var subtrees = emptyList<MutableMap<String, Any>>().toMutableList()
    tree.forEach { (_, value) ->
        if (value is MutableMap<*, *>) {
            subtrees = subtrees.plus(filterSubtreesBySize(value as MutableMap<String, Any>, sizeLimit, filterSmaller)).toMutableList()
        }
    }
    if (filterSmaller && tree["_sum"] as Long <= sizeLimit) subtrees.add(tree)
    if (!filterSmaller && tree["_sum"] as Long >= sizeLimit) subtrees.add(tree)
    return subtrees
};0

