fun solve() {
    val s = readLn()
    val inf = (s.maxOrNull()!! + 1).toString()
    val init = listOf(listOf(inf to listOf<Boolean>()), listOf("" to listOf()))
    val ans = s.foldIndexed(init) { i, (sure, unsure), c ->
        val next = List(2) { MutableList(i + 1) { inf to listOf<Boolean>()} }
        fun update(isSure: Boolean, index: Int, new: Pair<String, List<Boolean>>) {
            val a = next[if (isSure) 0 else 1]
            if (!new.first.startsWith(inf) && new.first < a[index].first) a[index] = new
        }
        sure.forEachIndexed { j, (t, how) ->
            val storeShort = if (t.length == j) 1 else 0
            update(true, j + 1 - storeShort, t to how + false)
            update(true, minOf(j + storeShort, i - j), t + c to how + true)
        }
        unsure.forEachIndexed { j, (t, how) ->
            update(false, j, t + c to how + true)
            if (j != i - j && t != inf) when {
                c > t[j] -> update(true, j + 1, t.substring(0, j) + c to how + true)
                else -> update(c < t[j], j + 1, t to how + false)
            }
        }
        next
    }
    println(ans.flatten().minByOrNull { it.first }!!.second.joinToString("") { if (it) "R" else "B" })
};0

 
const val STX = "\u0002"
const val ETX = "\u0003"
 
fun bwt(s: String): String {
    if (s.contains(STX) || s.contains(ETX)) {
        throw RuntimeException("String can't contain STX or ETX")
    }
    val ss = STX + s + ETX
    val table = Array<String>(ss.length) { ss.substring(it) + ss.substring(0, it) }
    table.sort()
    return String(table.map { it[it.lastIndex] }.toCharArray())
}
 
fun ibwt(r: String): String {
    val len = r.length
    val table = Array<String>(len) { "" }
    repeat(len) {
        for (i in 0 until len) {
            table[i] = r[i].toString() + table[i]
        }
        table.sort()
    }
    for (row in table) {
        if (row.endsWith(ETX)) {
            return row.substring(1, len - 1)
        }
    }
    return ""
}
 
fun makePrintable(s: String): String {
    // substitute ^ for STX and | for ETX to print results
    return s.replace(STX, "^").replace(ETX, "|")
}
 
fun main(args: Array<String>) {
    val tests = listOf(
        "banana",
        "appellee",
        "dogwood",
        "TO BE OR NOT TO BE OR WANT TO BE OR NOT?",
        "SIX.MIXED.PIXIES.SIFT.SIXTY.PIXIE.DUST.BOXES",
        "\u0002ABC\u0003"
    )
    for (test in tests) {
        println(makePrintable(test))
        print(" --> ")
        var t = ""
        try {
            t = bwt(test)
            println(makePrintable(t))
        }
        catch (ex: RuntimeException) {
            println("ERROR: " + ex.message)
        }
        val r = ibwt(t)
        println(" --> $r\n")
    }
};0

import java.util.stream.IntStream
import java.util.stream.Stream
import java.util.stream.Collectors
 
fun allEqual(a: Int, b: Int, c: Int, d: Int, e: Int, f: Int, g: Int): Boolean {
    return a + b == b + c + d && d + e + f == f + g
}
 
fun foursquares(lo: Int, hi: Int, unique: Boolean, show: Boolean) {
    var solutions = 0
    val uorn = if (unique) "unique" else "non-unique"
    val citer = if (unique) IntStream.range(lo, hi + 1).combinations(7) else IntStream.range(lo, hi + 1).combinationsWithReplacement(7)
    citer.forEach {
        val perms = it.permutations()
        perms.forEach {
            if (allEqual(it[0], it[1], it[2], it[3], it[4], it[5], it[6])) {
                solutions++
                if (show) {
                    println(it.joinToString(prefix = "[", postfix = "]"))
                }
            }
        }
    }
    println("$solutions $uorn solutions in $lo to $hi")
}
 
fun IntStream.combinations(k: Int): Stream<IntArray> {
    return this.sorted().combinationsWithReplacement(k).distinct()
}
 
fun IntStream.combinationsWithReplacement(k: Int): Stream<IntArray> {
    return this.mapToObj { IntArray(k) { it } }.flatMap {
        IntStream.range(0, k).mapToObj {
            val a = it
            val b = IntStream.range(0, k).map { a }.toArray()
            b[a] = it
            b
        }
    }
}
 
fun IntArray.permutations(): Stream<IntArray> {
    return IntStream.range(0, this.size).mapToObj {
        val a = it
        val b = IntStream.range(0, this.size).map { a }.toArray()
        b[a] = this[a]
        b
    }
};1

fun scs(u: String, v: String): String {
    val lcs = lcs(u, v)
    var u = u
    var v = v
    var scs = ""
    // Iterate over the characters until LCS processed
    while (lcs.isNotEmpty()) {
        if (u[0] == lcs[0] && v[0] == lcs[0]) {
            // Part of the LCS, so consume from all strings
            scs += lcs[0]
            u = u.substring(1)
            v = v.substring(1)
            lcs = lcs.substring(1)
        } else if (u[0] == lcs[0]) {
            // char of u = char of LCS, but char of LCS v doesn't so consume just that
            scs += v[0]
            v = v.substring(1)
        } else {
            // char of u != char of LCS, so consume just that
            scs += u[0]
            u = u.substring(1)
        }
    }
    // append remaining characters, which are not in common
    return scs + u + v
}
 
