    world.cellMap.forEach { (_, cell) ->
        val directions = Direction.ALL.mapNotNull {
            val next = world.cellMap[cell.pos + it]
            if (next == null || next.elevation > (cell.elevation + 1)) {
                null
            } else {
                it to next
