fun areListsInRightOrder(list1: List<Int>, list2: List<Int>): Int {

    val minSize = min(list1.size, list2.size)
    for (i in 0 until minSize) {
        if (list1[i] < list2[i]) {
            return 1
        } else if (list1[i] > list2[i]) {
            return -1
        }
    }
    return if (list1.size > list2.size) -1 else 1
