fun calculate_loss(original: List<Double>, reconstructed: List<Double>): Double {
    require(original.size == reconstructed.size) { "The two input lists must have the same length." }
    val n = original.size
    if (n == 0) {
        return 0.0 // Avoid division by zero
    }
    var squaredErrorSum = 0.0
    for (i in 0 until n) {
        val diff = original[i] - reconstructed[i]
        squaredErrorSum += diff * diff
    }
    return squaredErrorSum / n
