        resultList.add("many")
        done = true
        return
    }

    if(currentVertex == adjMatrix.size-1){
        resultList.add((numberOfColors+1).toString())
        done = true
        return
    }

    for(i in 1..numberOfColors+1) {
        vertColored[currentVertex+1] = i
        solve(numberOfColors,adjMatrix,currentVertex+1,vertColored)
    }
    return
