fun move(list: ArrayList<Num>, idx: Int, dist: Long) {
    var d = (dist % (list.size-1)).toInt()
    if (d < 0) {
        d = -d
        val n = list[idx]
        if (d <= idx) {
            for (i in idx downTo idx - d + 1)
                list[i] = list[i - 1]
            list[idx - d] = n
        } else {
            for (i in idx until list.size - d + idx - 1)
                list[i] = list[i + 1]
            list[list.size - d + idx - 1] = n
        }
    } else if (d > 0) {
        val n = list[idx]
        if (idx + d < list.size) {
            for (i in idx until idx + d)
                list[i] = list[i + 1]
            list[idx + d] = n
        } else {
            for (i in idx downTo idx + d - list.size + 2)
                list[i] = list[i - 1]
            list[idx + d - list.size + 1] = n
        }
    }
};0

fun eratosthenes2(n: Int): List<Int> {
    val multiples = mutableSetOf<Int>()
    val result = mutableListOf<Int>()
    for (i in 2..n) {
        if (i!in multiples) {
            result.add(i)
            multiples.addAll(i * i..n step i)
        }
    }
    return result
}
 
