fun computeStatistics(numbers: List<Int>, thresholds: List<Int>): Any {
    if (numbers.size < 3) {
        return "Insufficient data"
    }
    if (numbers.size > 50) {
        return "Limit exceeded"
    }
    if (thresholds.size < 3) {
        return "Insufficient thresholds provided"
    }
    val sumThreshold = thresholds[0]
    val avgThreshold = thresholds[1]
    val productThreshold = thresholds[2]
    val included = numbers.subList(1, numbers.size - 1)
    val sumIncluded = included.sum()
    val n = included.size
    val averageIncluded = if (n != 0) sumIncluded.toDouble() / n else 0.0
    val productExcluded = numbers.first() * numbers.last()
    if (sumIncluded > sumThreshold || averageIncluded > avgThreshold || productExcluded > productThreshold) {
        return "Computation cannot be completed"
    }
    return Triple(sumIncluded, averageIncluded, productExcluded)
};1

fun equal_distribution(resources: List<Int>): Any {
    val totalResources = resources.sum()
    val numRegions = resources.size
    if (numRegions == 0) {
        return emptyList<Int>()
    }
    if (totalResources % numRegions != 0) {
        return false
    }
    val equalShare = totalResources / numRegions
    return List(numRegions) { equalShare }
};1

