fun longestCommonPrefix(strs: Array<String>): String {
    var menorPalavra = strs[0]
    var resposta = ""
    var index = 0
    var contador = menorPalavra.length

    if(strs.isEmpty()) return ""
    if(strs.size == 1) return strs[0]

    strs.forEach {
        if(it == "") return ""
        if(it.length < menorPalavra.length){
            menorPalavra = it
        }
    }
    val strsFiltrado = strs.filter { it != menorPalavra }

    strsFiltrado.forEach{
        var i = 0
        while (i < it.length && contador > 0)
        if (index < menorPalavra.length && it[index] == menorPalavra[index]){
            index++
            i++
        } else if (index < contador) {
            contador = index
            i = it.length
            index = 0
        } else {
            i = it.length
            index = 0
        }
    }

    resposta = menorPalavra.substring(0, contador)

    return resposta

};0

fun triangleArea(a: Double, b: Double, c: Double): Any? {
    // Validación básica: todos los lados deben ser positivos
    for (side in listOf(a, b, c)) {
        if (side <= 0.0 || side.isNaN() || side.isInfinite()) {
            return null
        }
    }
    // Desigualdad triangular
    if ((a + b <= c) || (a + c <= b) || (b + c <= a)) {
        return null
    }
    // Fórmula de Herón
    val s = (a + b + c) / 2.0
    var areaSquared = s * (s - a) * (s - b) * (s - c)
    // Control de estabilidad numérica
    if (areaSquared < 0) {
        areaSquared = 0.0
    }
    val area = sqrt(areaSquared)
    // Advertencia si el área es muy pequeña
    if (area < 0.0001) {
        return "Warning: area is very small"
    }
    // Retorna el área con 4 decimales
    return String.format("%.4f", area).toDouble()
};1

fun List<IntRange>.merge(): List<IntRange> {
    var prev = this
    var next = fold(emptyList<IntRange>()) { ranges, next ->
        var found = false
        ranges
            .map { range ->
                if (range.overlaps(next)) {
                    found = true
                    min(next.first, range.first)..max(next.last, range.last)
                } else {
                    range
                }
            }
            .let { ranges ->
                if (found) {
                    ranges
                } else {
                    ranges.plusElement(next)
                }
            }
    }
    while (next != prev) {
        prev = next
        next = next.fold(emptyList()) { ranges, next ->
            var found = false
            ranges
                .map {  range ->
                    if (range.overlaps(next) || next.overlaps(range)) {
                        found = true
                        min(next.first, range.first)..max(next.last, range.last)
                    } else {
                        range
                    }
                }
                .let { ranges ->
                    if (found) {
                        ranges
                    } else {
                        ranges.plusElement(next)
                    }
                }
        }
    }
    return next
};0

