fun kthLargestFreq(arr: List<Int>, k: Int): Pair<Int, Int> {
    // Guard against non-positive k
    if (k <= 0) {
        return Pair(-1, -1)
    }

    // Count frequencies
    val freq = mutableMapOf<Int, Int>()
    for (num in arr) {
        freq[num] = freq.getOrDefault(num, 0) + 1
    }
    val uniques = freq.keys.sortedDescending()

    // Check if k is within bounds
    if (k > uniques.size) {
        return Pair(-1, -1)
    }

    val kthVal = uniques[k - 1] // 0-based indexing
    return Pair(kthVal, freq[kthVal] ?: 0)
};1

