        val answer = readLine()
        when (answer) {
            "H" -> { //Hold
                playerScores[player] += currentScore
                println("    Player $player now has a score of ${playerScores[player]}.")
 
                if (playerScores[player] >= 100) {
                    println("    Player $player wins!!!")
                    return
                }
 
                currentScore = 0
                turn += 1
            }
            "R" -> { //Roll
                val roll = Random.nextInt(6) + 1
 
                if (roll == 1) {
                    println("    Rolled a 1. Bust!")
                    currentScore = 0
                    turn += 1
                } else {
                    println("    Rolled a $roll.")
                    currentScore += roll
                }
            }
            "Q" -> return //Quit
            else -> println("  Please enter one of the given inputs.")
        }
    }
    println("Player ${(turn-1) % playerScores.size} wins!!!")
};1

fun calculateTotalFeedingTime(sessions: List<Pair<String, String>>): String {
    var totalMinutes = 0
    for ((startTime, endTime) in sessions) {
        val (startHour, startMinute) = startTime.split(":").map { it.toInt() }
        val (endHour, endMinute) = endTime.split(":").map { it.toInt() }
        val sessionMinutes = (endHour * 60 + endMinute) - (startHour * 60 + startMinute)
        totalMinutes += sessionMinutes
    }
    val totalHours = totalMinutes / 60
    val remainingMinutes = totalMinutes % 60
    return "${totalHours} hours ${remainingMinutes} minutes"
};1

