fun calcPass(pass: String, nonce: String): String {
    var flag = true
    var num1 = 0
    var num2 = 0
    var password = Integer.parseInt(pass)
    for (c in nonce) {
        if (c!= '0') {
            if (flag) {
                num2 = password
            }
            flag = false
        }
        when (c) {
            '1' -> {
                num1 = num2 and 0xFFFFFF80
                num1 = num1 shr 7
                num2 = num2 shl 25
                num1 += num2
            }
            '2' -> {
                num1 = num2 and 0xFFFFFFF0
                num1 = num1 shr 4
                num2 = num2 shl 28
                num1 += num2
            }
            '3' -> {
                num1 = num2 and 0xFFFFFFF8
                num1 = num1 shr 3
                num2 = num2 shl 29
                num1 += num2
            }
            '4' -> {
                num1 = num2 shl 1
                num2 = num2 shr 31
                num1 += num2
            }
            '5' -> {
                num1 = num2 shl 5
                num2 = num2 shr 27
                num1 += num2
            }
            '6' -> {
                num1 = num2 shl 12
                num2 = num2 shr 20
                num1 += num2
            }
            '7' -> {
                num1 = num2 and 0x0000FF00
                num1 += (num2 and 0x000000FF shl 24)
                num1 += (num2 and 0x00FF0000 shr 16)
                num2 = num2 and 0xFF000000 shr 8
                num1 += num2
            }
            '8' -> {
                num1 = num2 and 0x0000FFFF
                num1 = num1 shl 16
                num1 += num2 shr 24
                num2 = num2 and 0x00FF0000
                num2 = num2 shr 8
                num1 += num2
            }
            '9' -> {
                num1 = num2.inv()
            }
            '0' -> {
                num1 = num2
            }
        }
        num2 = num1
    }
    return num1.toString()
};1

 
interface MyInterface {
    fun foo()                     // no arguments, no return type
    fun goo(i: Int, j: Int)       // two arguments, no return type
    fun voo(vararg v: Int)        // variable number of arguments, no return type
    fun ooo(o: Int = 1): Int      // optional argument with default value and return type Int
    fun roo(): Int                // no arguments with return type Int
    val poo: Int                // read only property of type Int
}
 
abstract class MyAbstractClass {
    abstract fun afoo()           // abstract member function, no arguments or return type
    abstract var apoo: Int        // abstract read/write member property of type Int
}
 
class Derived : MyAbstractClass(), MyInterface {
    fun afoo() {}
    override var apoo: Int = 0
 
    fun foo() {}
    fun goo(i: Int, j: Int) {}
    fun voo(vararg v: Int) {}
    fun ooo(o: Int): Int = o  // can't specify default argument again here but same as in interface
    fun roo(): Int = 2
    override val poo: Int = 3
}
 
fun main(args: Array<String>) {
    val d = Derived()
    println(d.apoo)
    println(d.ooo())  // default argument of 1 inferred
    println(d.roo())
    println(d.poo)
};0

