var grid: ByteArray = byteArrayOf()
var w: Int = 0
var h: Int = 0
var last: Int = 0
var cnt: Int = 0
var next: IntArray = intArrayOf()
val dir = arrayOf(intArrayOf(0, -1), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(1, 0))
 
fun walk(y: Int, x: Int) {
    if (y == 0 || y == h || x == 0 || x == w) {
        cnt += 2
        return
    }
    val t = y * (w + 1) + x
    grid[t]++
    grid[last - t]++
    for (i in dir.indices) {
        if (grid[t + next[i]] == 0.toByte()) {
            walk(y + dir[i][0], x + dir[i][1])
        }
    }
    grid[t]--
    grid[last - t]--
}
 
fun solve(hh: Int, ww: Int, recur: Int): Int {
    h = hh
    w = ww
 
    if (h and 1!= 0) {
        h = w
        w = h
    }
    when {
        h and 1 == 1 -> return 0
        w == 1 -> return h
        w == 2 -> return h
        h == 2 -> return w
    }
    val cy = h / 2
    val cx = w / 2
 
    grid = ByteArray((h + 1) * (w + 1))
    last = grid.size - 1
    next = intArrayOf(-1, -w - 1, 1, w + 1)
 
    if (recur!= 0) {
        cnt = 0
    }
    for (x in cx + 1 until w) {
        val t = cy * (w + 1) + x
        grid[t] = 1
        grid[last - t] = 1
        walk(cy - 1, x)
    }
    cnt++
 
    if (h == w) {
        cnt *= 2
    } else if (w and 1 == 0 && recur!= 0) {
        solve(w, h, 0)
    }
    return cnt
};1

fun mergeSort(arr: List<Int>): List<Int> {
    if (arr.size <= 1) {
        return arr
    }
    val mid = arr.size / 2
    val left = mergeSort(arr.subList(0, mid))
    val right = mergeSort(arr.subList(mid, arr.size))
    return merge(left, right)
}

fun merge(left: List<Int>, right: List<Int>): List<Int> {
    val result = mutableListOf<Int>()
    var i = 0
    var j = 0
    while (i < left.size && j < right.size) {
        if (left[i] < right[j]) {
            result.add(left[i])
            i++
        } else {
            result.add(right[j])
            j++
        }
    }
    while (i < left.size) {
        result.add(left[i])
        i++
    }
    while (j < right.size) {
        result.add(right[j])
        j++
    }
    return result
};1

