// --------------------- CRC-32 ----------------------

// crc32 :: String -> Int
fun crc32(str: String): Int {
    // table :: [Int]
    val table = enumFromTo(0)(255).map { n ->
        take(9)(
            iterate { x: Int ->
                if (x and 1 == 1) {
                    { z: Int -> 0xEDB88320 xor z }
                } else {
                    ::identity
                }
            }(n)
        )[8]
    }
    return chars(str).reduce { a: Int, c: Char ->
        (a ushr 8) xor table[(a xor c.toInt()) and 255]
    } xor -1
}

