// enumFromTo :: Int -> Int -> [Int]
fun enumFromTo(m: Int): (Int) -> List<Int> = { n: Int ->
    if (!m.isNaN()) {
        (m..n).toList()
    } else {
        enumFromTo_(m)(n)
    }
}

