fun lca(a: Int, b: Int): Int {
    var (u, v) = listOf(a, b)
    if (depth[u] < depth[v]) {
        val temp = u
        u = v
        v = temp
    }
    val (k, one) = listOf(depth[u] - depth[v], 1)
    for (i in LOG - 1 downTo 0) {
        if (k.and(one.shl(i)) != 0) u = up[u][i]
    }
    if (u == v) return u
    for (i in LOG - 1 downTo 0) {
        if (up[u][i] != up[v][i]) {
            u = up[u][i]
            v = up[v][i]
        }
    }
    return up[u][0]
};0

fun longestPeacePeriod(ceasefires: List<Pair<String, String>>): Int {
    if (ceasefires.isEmpty() || ceasefires.size < 2) {
        return 0
    }
    val formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")
    val cfSorted = ceasefires.sortedBy { LocalDate.parse(it.first, formatter) }
    var maxPeace = 0
    var prevEnd = LocalDate.parse(cfSorted[0].second, formatter)
    for (i in 1 until cfSorted.size) {
        val currStart = LocalDate.parse(cfSorted[i].first, formatter)
        val peaceDays = currStart.toEpochDay() - prevEnd.toEpochDay()
        if (peaceDays > maxPeace) {
            maxPeace = peaceDays.toInt()
        }
        prevEnd = LocalDate.parse(cfSorted[i].second, formatter)
    }
    return maxPeace
};1

fun parseOperation(line: String): Operation {
