    val op = when (match!!.groupValues[2]) {
        "*" -> Op.Mul
        "+" -> Op.Plus
        else -> throw Error("Unexpected op")
    }
    val a = parseOpInput(match.groupValues[1])
    val b = parseOpInput(match.groupValues[3])
    return Operation(a, b, op)
