fun filterProducts(products: List<Map<String, Any>>, criteria: Map<String, Any>): List<Map<String, Any>> {
    // Pre-extract every filter, defaulting to null if not supplied.
    var nameFilter = criteria["name_filter"] as? String
    var typeFilter = criteria["type_filter"] as? String
    var companyFilter = criteria["company_filter"] as? String
    val minPrice = criteria["min_price"] as? Number
    val maxPrice = criteria["max_price"] as? Number

    // Lower-case string filters once to avoid doing so repeatedly.
    if (nameFilter != null) {
        nameFilter = nameFilter.lowercase()
    }
    if (typeFilter != null) {
        typeFilter = typeFilter.lowercase()
    }
    if (companyFilter != null) {
        companyFilter = companyFilter.lowercase()
    }

    val filtered = mutableListOf<Map<String, Any>>()

    for (product in products) {
        val name = product["name"] as? String ?: ""
        val type = product["type"] as? String ?: ""
        val company = product["company"] as? String ?: ""
        val price = product["price"] as? Number ?: continue

        if (nameFilter != null && !name.lowercase().contains(nameFilter)) {
            continue
        }
        if (typeFilter != null && type.lowercase() != typeFilter) {
            continue
        }
        if (companyFilter != null && company.lowercase() != companyFilter) {
            continue
        }
        if (minPrice != null && price.toDouble() < minPrice.toDouble()) {
            continue
        }
        if (maxPrice != null && price.toDouble() > maxPrice.toDouble()) {
            continue
        }

        filtered.add(product)
    }

    return filtered
};1

