fun F_k(n: Int, k: Int): Int {
    val mod = 1_000_000_007

    fun euler_phi(x0: Int): Int {
        if (x0 == 1) return 1
        var x = x0
        var res = x
        var i = 2
        while (i * i <= x) {
            if (x % i == 0) {
                while (x % i == 0) {
                    x /= i
                }
                res -= res / i
            }
            i++
        }
        if (x > 1) {
            res -= res / x
        }
        return res
    }

    fun f(n: Int): Int {
        return if (n == 1) 1 else euler_phi(n)
    }

    fun g(n: Int): Int {
        var res = 0
        var d = 1
        while (d * d <= n) {
            if (n % d == 0) {
                val nd = n / d
                res += f(nd)
                if (d != nd) {
                    res += f(d)
                }
            }
            d++
        }
        return res
    }

    var m = (k + 1) / 2
    var current = n
    for (i in 0 until m) {
        if (current == 1) break
        current = euler_phi(current)
    }
    return ((current % mod) + mod) % mod
};1

