fun findKthSmallest(nums: List<Int>, k: Int): Int {
    val numbers = nums.toMutableList()
    fun partition(left: Int, right: Int): Int {
        val pivot = numbers[right]
        var i = left
        for (j in left until right) {
            if (numbers[j] <= pivot) {
                val tmp = numbers[i]
                numbers[i] = numbers[j]
                numbers[j] = tmp
                i += 1
            }
        }
        val tmp = numbers[i]
        numbers[i] = numbers[right]
        numbers[right] = tmp
        return i
    }

    fun select(left: Int, right: Int, kSmallest: Int): Int {
        if (left == right) {
            return numbers[left]
        }
        val pivotIndex = partition(left, right)
        return when {
            kSmallest == pivotIndex -> numbers[kSmallest]
            kSmallest < pivotIndex -> select(left, pivotIndex - 1, kSmallest)
            else -> select(pivotIndex + 1, right, kSmallest)
        }
    }

    if (k !in 1..numbers.size) {
        throw IllegalArgumentException("k is out of the bounds of the list length")
    }
    return select(0, numbers.size - 1, k - 1)
};1

