fun minEdits(original: String, received: String): Int {
    val orig = original.lowercase()
    val recv = received.lowercase()
    val m = orig.length
    val n = recv.length
    val dp = Array(m + 1) { IntArray(n + 1) { Int.MAX_VALUE } }
    dp[0][0] = 0
    for (j in 1..n) {
        dp[0][j] = j // Delete all j characters
    }
    for (i in 1..m) {
        for (j in 1..n) {
            if (j < i) continue
            val cost = if (orig[i - 1] == recv[j - 1]) dp[i - 1][j - 1] else 1 + dp[i - 1][j - 1]
            val deletion = 1 + dp[i][j - 1]
            dp[i][j] = minOf(cost, deletion)
        }
    }
    return dp[m][n]
};1

