fun findTree(N: Int, subsets: List<List<Int>>): Any {
    val parent = IntArray(N + 1) { it }
    val rank = IntArray(N + 1) { 1 }

    fun find(u: Int): Int {
        var v = u
        while (parent[v] != v) {
            parent[v] = parent[parent[v]]
            v = parent[v]
        }
        return v
    }

    fun union(u: Int, v: Int): Boolean {
        val uRoot = find(u)
        val vRoot = find(v)
        if (uRoot == vRoot) return false
        if (rank[uRoot] < rank[vRoot]) {
            parent[uRoot] = vRoot
            rank[vRoot] += rank[uRoot]
        } else {
            parent[vRoot] = uRoot
            rank[uRoot] += rank[vRoot]
        }
        return true
    }

    val edges = mutableListOf<List<Int>>()
    for (s in subsets) {
        val roots = s.map { find(it) }
        if (roots.toSet().size == 1) {
            return -1
        }
        val u = s[0]
        var found = false
        for (v in s.drop(1)) {
            if (find(u) != find(v)) {
                edges.add(listOf(u, v))
                union(u, v)
                found = true
                break
            }
        }
        if (!found) {
            for (v in s) {
                if (find(u) != find(v)) {
                    edges.add(listOf(u, v))
                    union(u, v)
                    found = true
                    break
                }
            }
            if (!found) {
                return -1
            }
        }
    }
    val root = find(1)
    for (i in 2..N) {
        if (find(i) != root) {
            return -1
        }
    }
    return edges
};1

