fun commonChars(wordList: MutableList<String>): List<String> {
    val res = mutableListOf<String>()
    if(wordList.isEmpty()) {
        return res
    }

    val lettersMap = Array(wordList.size) { mutableMapOf<Char, Int>() }

    for(i in wordList.indices) {
        for(letter in wordList[i]) {
            val letterCount = lettersMap[i].get(letter) ?: 0
            lettersMap[i].put(letter, letterCount + 1)
        }
    }
    //iterate over the first word
    for(letterEntry in lettersMap[0]){
        var count = letterEntry.value
        //check if the letter appears in each word i (!= 0)
        loop@for(i in 1 until wordList.size) {
            var letterCount = lettersMap[i].get(letterEntry.key)
            if(letterCount == null) {
                //it means that the letter doesn't appear any word
                count = 0
                break@loop //break inner loop and move to next iteration
            } else {
                //update to minimum appearances (in case of duplicates letters in word)
                count = count.coerceAtMost(letterCount)
            }
        }

        for(i in 1..count) {
            res.add(letterEntry.key.toString())
        }
    }

    return res
};0

fun parseEngineSchematic(lines: Iterable<String>): EngineSchematic {
    val map = lines.parse2DMap().toMap()
    val width = map.getWidth()
    val height = map.getHeight()

    val numbers = buildList {
        var y = 0
        while (y < height) {
            var x = 0
            while (x < width) {
                var number = 0
                val startCoord = Coord(x, y)
                var coord = startCoord

                while (coord.x < width
                    && map[coord]?.isDigit() == true) {
                    number = number * 10 + map[coord]!!.digitToInt()
                    coord += Coord(1, 0)
                }

                if (number > 0) {
                    val numDigits = log10(number.toDouble()).toInt() + 1
                    val symbols = (startCoord.x until (startCoord.x + numDigits))
                        .flatMap { xx -> map.getAdjacentCoords(Coord(x = xx, y = startCoord.y), includeDiagonal = true) }
                        .toSet()
                        .mapNotNull { adjCoord ->
                            map[adjCoord]
                                ?.takeIf { it.isSymbol() }
                                ?.let { symbol -> EngineSymbol(symbol, adjCoord) }
                        }

                    add(EngineNumber(number, startCoord, symbols))
                    x += numDigits
                } else {
                    x++
                }
            }

            y++
        }
    }

    return EngineSchematic(numbers)
};0

