fun matrixMultiply(A: List<List<Int>>, B: List<List<Int>>): List<List<Int>> {
    // Both matrices must be non-empty and rectangular.
    if (A.isEmpty() || B.isEmpty()) return emptyList()

    val nColsA = A[0].size
    val nRowsB = B.size

    // Verify A is rectangular
    for (row in A) {
        if (row.size != nColsA) return emptyList()
    }

    // Verify B is rectangular
    val nColsB = B[0].size
    for (row in B) {
        if (row.size != nColsB) return emptyList()
    }

    // Check dimension compatibility for multiplication
    if (nColsA != nRowsB) return emptyList()
    val m = A.size
    val n = nColsA
    val p = nColsB
    val result = mutableListOf<MutableList<Int>>()
    for (i in 0 until m) {
        val resultRow = mutableListOf<Int>()
        for (j in 0 until p) {
            var elementSum = 0
            for (k in 0 until n) {
                elementSum += A[i][k] * B[k][j]
            }
            resultRow.add(elementSum)
        }
        result.add(resultRow)
    }
    return result
};1

