fun sieve(limit: Int): BooleanArray {
    val c = BooleanArray(limit + 1)
    c[0] = true
    c[1] = true
    var p = 3
    while (true) {
        val p2 = p * p
        if (p2 >= limit) {
            break
        }
        for (i in p2..limit step 2 * p) {
            c[i] = true
        }
        while (true) {
            p += 2
            if (!c[p]) {
                break
            }
        }
    }
    return c
}
 
fun commatize(n: Int): String {
    val s = n.toString()
    var le = s.length
    for (i in le - 3 downTo 1 step 3) {
        s.substring(0, i) + "," + s.substring(i)
    }
    return s
}
 
fun main(args: Array<String>) {
    // sieve up to 10,000,019 - the first prime after 10 million
    val limit = 1e7 + 19
    val sieved = sieve(limit)
    // extract primes
    val primes = mutableListOf(2)
    for (i in 3..limit step 2) {
        if (!sieved[i]) {
            primes.add(i)
        }
    }
    // extract strong and weak primes
    val strong = mutableListOf<Int>()
    val weak = mutableListOf(3) // so can use integer division for rest
    for (i in 2 until primes.size - 1) { // start from 5
        if (primes[i] > (primes[i - 1] + primes[i + 1]) / 2) {
            strong.add(primes[i])
        } else if (primes[i] < (primes[i - 1] + primes[i + 1]) / 2) {
            weak.add(primes[i])
        }
    }
 
    println("The first 36 strong primes are:")
    println(strong.subList(0, 36))
    var count = 0
    for (p in strong) {
        if (p >= 1e6) {
            break
        }
        count++
    }
    println("\nThe number of strong primes below 1,000,000 is", commatize(count))
    println("\nThe number of strong primes below 10,000,000 is", commatize(strong.size))
 
    println("\nThe first 37 weak primes are:")
    println(weak.subList(0, 37))
    count = 0
    for (p in weak) {
        if (p >= 1e6) {
            break
        }
        count++
    }
    println("\nThe number of weak primes below 1,000,000 is", commatize(count))
    println("\nThe number of weak primes below 10,000,000 is", commatize(weak.size))
};1

