fun <E> List<List<E>>.adjacentToCoords(position: Pair<Int, Int>): Set<Pair<Int, Int>> {
    val (x, y) = position
    val validPositions = mutableListOf<Pair<Int, Int>>()
    for (dy in -1..1) {
        for (dx in -1..1) {
            if (dx == 0 && dy == 0) continue
            val newX = x + dx
            val newY = y + dy
            if (newX < 0 || newY < 0) continue
            if (newY >= size || newX >= this[newY].size) continue
            validPositions.add(Pair(newX, newY))
        }
    }
    return validPositions.toSet()
};0

/**
 * Questions32-2: Print a binary tree from top to bottom by line
 */
fun <T> BinaryTreeNode<T>.printlnBinaryTreeFromTop2BottomByLine() {
    val line = Queue<BinaryTreeNode<T>>()
    line.enqueue(this)
    var thisLineNodesCount = 1
    var nextLineNodesCount = 0
    while (!line.isEmpty) {
        if (thisLineNodesCount == 0) {
            thisLineNodesCount = nextLineNodesCount
            nextLineNodesCount = 0
        }
        val node = line.dequeue()
        print("${node.value}, ")
        if (--thisLineNodesCount == 0)
            println()
        node.left?.let {
            line.enqueue(it)
            nextLineNodesCount++
        }
        node.right?.let {
            line.enqueue(it)
            nextLineNodesCount++
        }
    }
};0

