val EMAIL_PATTERN: Pattern = Pattern.compile(
    "^" +                              // start of string
    "[A-Za-z0-9]+" +                   // first alphanumeric in local part
    "(?:[._%+-][A-Za-z0-9]+)*" +       // further parts of local part
    "@" +                              // mandatory @
    "(?:[A-Za-z0-9-]+\\.)+" +         // one or more domain labels + dot
    "[A-Za-z]{2,}" +                   // final extension (≥ 2 letters)
    "$"                                // end of string
)

fun validateEmail(email: String): Boolean {
    // Fast failures for trivial edge cases
    if (email.isEmpty() || email.count { it == '@' } != 1 || email.contains(' ') || email.contains('\t')) {
        return false
    }
    // Double-dot anywhere is invalid (e.g. "a..b@c.com", "a@b..com")
    if (email.contains("..")) {
        return false
    }
    // Full regular-expression match decides the rest
    return EMAIL_PATTERN.matcher(email).matches()
};1

