fun calculate_average_kinetic_energy(masses: List<Double>, velocities: List<Double>): Double {
    val kineticEnergies = mutableListOf<Double>()
    for ((mass, velocity) in masses.zip(velocities)) {
        val kineticEnergy = 0.5 * mass * velocity * velocity
        kineticEnergies.add(kineticEnergy)
    }
    val totalKineticEnergy = kineticEnergies.sum()
    val averageKineticEnergy = totalKineticEnergy / kineticEnergies.size
    return averageKineticEnergy
