        return emptyMap()
    }
    val soilHorizons = mutableMapOf(
        'O' to mutableListOf<Int>(),
        'A' to mutableListOf<Int>(),
        'E' to mutableListOf<Int>(),
        'B' to mutableListOf<Int>(),
        'C' to mutableListOf<Int>()
    )
    for (size in particleSizes) {
        when {
            size < 10 -> soilHorizons['O']!!.add(size)
            size in 10 until 50 -> soilHorizons['A']!!.add(size)
            size in 50 until 200 -> soilHorizons['E']!!.add(size)
            size in 200 until 500 -> soilHorizons['B']!!.add(size)
            else -> soilHorizons['C']!!.add(size)
        }
    }
    return soilHorizons
};1

fun isOverlapped(it:List<String>):Boolean {
    val leftRanges  = it[0].split("-").map { Integer.valueOf(it)}
    val rightRanges = it[1].split("-").map { Integer.valueOf(it)}
    val leftContainsRight = leftRanges[0] <= rightRanges[0] && leftRanges[1] >= rightRanges[1]
    val rightContainsLeft = rightRanges[0] <= leftRanges[0] && rightRanges[1] >= leftRanges[1]
    return leftContainsRight || rightContainsLeft
};0

