fun insertionSort(arr: List<Int>): List<Int> {
    // Make a shallow copy so the original list is not modified
    val sortedArr = arr.toMutableList()
    for (i in 1 until sortedArr.size) {
        val key = sortedArr[i]
        var j = i - 1
        while (j >= 0 && sortedArr[j] > key) {
            sortedArr[j + 1] = sortedArr[j]
            j -= 1
        }
        sortedArr[j + 1] = key
    }
    return sortedArr
};1

fun List<List<Long>>.maxMultiple(): Long {
    val visited = mutableListOf<List<Long>>()
    val directions = listOf(EAST, SOUTH_EAST, SOUTH, SOUTH_WEST)

    return this.flatMapIndexed { y, line ->
        line.indices.mapNotNull { x ->
            val current = x to y
            directions.maxOfOrNull { dir ->
                current
                    .lineTo(dir, 3)
                    .takeIf { list -> list.all { it.withinMap(this) } }
                    ?.map { this[it.second][it.first] }
                    ?.also { visited.add(it) }
                    ?.multiply() ?: 0
            }
        }
    }.max()
};0

 
import java.math.BigDecimal
 
var p = mutableMapOf(1 to 0)
var lvl = mutableListOf(listOf(1))
 
fun path(n: Int): List<Int> {
    if (n == 0) return emptyList<Int>()
    while (n !in p) {
        val q = mutableListOf<Int>()
        for (x in lvl[0]) {
            for (y in path(x)) {
                if ((x + y) in p) break
                p[x + y] = x
                q.add(x + y)
            }
        }
        lvl[0] = q
    }
    return path(p[n]!!) + n
}
 
fun treePow(x: Double, n: Int): BigDecimal {
    val r = mutableMapOf(0 to BigDecimal.ONE, 1 to BigDecimal(x.toString()))
    var p = 0
    for (i in path(n)) {
        r[i] = r[i - p]!! * r[p]!!
        p = i
    }
    return r[n]!!
}
 
fun showPow(x: Double, n: Int, isIntegral: Boolean = true) {
    println("$n: ${path(n)}")
    val f = if (isIntegral) "%.0f" else "%f"
    println("${f.format(x)} ^ $n = ${f.format(treePow(x, n))}\n")
}
 
