fun convexHull(p: Array<Point>): Array<Point> {
    // From https://en.wikibooks.org/wiki/Algorithm_Implementation/Geometry/Convex_hull/Monotone_chain
    // with only minor deviations.
    val h = ArrayList<Point>()
    val sorted = p.sortedWith(compareBy({ it.x }, { it.y }))
 
    // Lower hull
    for (pt in sorted) {
        while (h.size >= 2 &&!ccw(h[h.size - 2], h[h.size - 1], pt)) {
            h.removeAt(h.size - 1)
        }
        h.add(pt)
    }
 
    // Upper hull
    for (i in sorted.size - 2 downTo 0) {
        val pt = sorted[i]
        while (h.size >= 2 &&!ccw(h[h.size - 2], h[h.size - 1], pt)) {
            h.removeAt(h.size - 1)
        }
        h.add(pt)
    }
 
    return h.dropLast(1).toTypedArray()
}
 
// ccw returns true if the three points make a counter-clockwise turn
fun ccw(a: Point, b: Point, c: Point): Boolean {
    return ((b.x - a.x) * (c.y - a.y)) > ((b.y - a.y) * (c.x - a.x))
};1

