fun recur(x: Int, v: Int) {
    if (x >= 0 && x < ww && map!![x] == -1) {
        map!![x] = v
        recur(x - w, v)
        recur(x - 1, v)
        recur(x + 1, v)
        recur(x + w, v)
    }
}
 
fun count_clusters(): Int {
    var i = 0
    var cls = 0
    for (i in 0 until ww) {
        if (-1!= map!![i]) {
            continue
        }
        recur(i, ++cls)
    }
    return cls
}
 
fun tests(n: Int, p: Double): Double {
    var i = 0
    var k = 0.0
    for (i in 0 until n) {
        make_map(p)
        k += count_clusters() / ww.toDouble()
    }
    return k / n
}
 
