object DRAGON {
    // MATRIX MATH
    // -----------
    private val matrix = object {
        fun mult(m: Array<Array<Double>>, v: Array<Double>): Array<Double> {
            return arrayOf(m[0][0] * v[0] + m[0][1] * v[1], m[1][0] * v[0] + m[1][1] * v[1])
        }

        fun minus(a: Array<Double>, b: Array<Double>): Array<Double> {
            return arrayOf(a[0] - b[0], a[1] - b[1])
        }

        fun plus(a: Array<Double>, b: Array<Double>): Array<Double> {
            return arrayOf(a[0] + b[0], a[1] + b[1])
        }
    }

    // SVG STUFF
    // ---------
    // Turn a pair of points into an SVG path like "M1 1L2 2".
    fun toSVGpath(a: Array<Double>, b: Array<Double>): String {
        return "M" + a[0] + " " + a[1] + "L" + b[0] + " " + b[1]
    }

    // DRAGON MAKING
    // -------------
    // Make a dragon with a better fractal algorithm
    fun fractalMakeDragon(svgid: String, ptA: Array<Double>, ptC: Array<Double>, state: Int, lr: Boolean, interval: Int) {
        // make a new <path>
        val path = document.createElementNS("http://www.w3.org/2000/svg", "path")
        path.setAttribute("class", "dragon")
        path.setAttribute("d", toSVGpath(ptA, ptC))

        // append the new path to the existing <svg>
        val svg = document.getElementById(svgid) // call could be eliminated
        svg.appendChild(path)

        // if we have more iterations to go...
        if (state > 1) {
            // make a new point, either to the left or right
            val growNewPoint = fun(ptA: Array<Double>, ptC: Array<Double>, lr: Boolean): Array<Double> {
                val left = arrayOf(arrayOf(1 / 2.0, -1 / 2.0), arrayOf(1 / 2.0, 1 / 2.0))

                val right = arrayOf(arrayOf(1 / 2.0, 1 / 2.0), arrayOf(-1 / 2.0, 1 / 2.0))

                return matrix.plus(ptA, matrix.mult(if (lr) left else right, matrix.minus(ptC, ptA)))
            }

            val ptB = growNewPoint(ptA, ptC, lr)

            // then recurse using each new line, one left, one right
            val recurse = fun() {
                // when recursing deeper, delete this svg path
                svg.removeChild(path)

                // then invoke again for new pair, decrementing the state
                fractalMakeDragon(svgid, ptB, ptA, state - 1, lr, interval)
                fractalMakeDragon(svgid, ptB, ptC, state - 1, lr, interval)
            }

            window.setTimeout(recurse, interval)
        }
    }
};1

