fun calculate_average_distance(data: List<Triple<Int, Double, Double>>): Double {
    val R = 6371.0
    var totalDistance = 0.0
    val numDays = data.size - 1
    for (i in 0 until numDays) {
        val day1 = data[i]
        val day2 = data[i + 1]
        val lat1 = Math.toRadians(day1.second)
        val lon1 = Math.toRadians(day1.third)
        val lat2 = Math.toRadians(day2.second)
        val lon2 = Math.toRadians(day2.third)
        val dlat = lat2 - lat1
        val dlon = lon2 - lon1
        val a = Math.sin(dlat / 2).pow(2.0) + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dlon / 2).pow(2.0)
        val c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))
        val distance = R * c
        totalDistance += distance
    }
    return if (numDays > 0) {
        totalDistance / numDays
    } else {
        0.0
    }
}

