fun countOccurrencesInRanges(s: String, t: String, queries: List<Pair<Int, Int>>): List<Int> {
    val n = s.length
    val m = t.length
    val positions = mutableListOf<Int>()
    if (m <= n) {
        for (i in 1..(n - m + 1)) {
            if (s.substring(i - 1, i - 1 + m) == t) {
                positions.add(i)
            }
        }
    }
    val res = mutableListOf<Int>()
    for ((l, r) in queries) {
        if (m > (r - l + 1)) {
            res.add(0)
            continue
        }
        val right = r - m + 1
        if (right < l) {
            res.add(0)
        } else {
            val leftPos = positions.binarySearch(l).let { if (it < 0) -it - 1 else it }
            val rightPos = positions.binarySearch(right + 1).let { if (it < 0) -it - 1 else it }
            res.add(rightPos - leftPos)
        }
    }
    return res
};1

 
import java.math.BigInteger
 
val bigTwo   = BigInteger.valueOf(2L)
val bigThree = BigInteger.valueOf(3L)
 
fun getPrimeFactors(n: BigInteger): MutableList<BigInteger> {
    val factors = mutableListOf<BigInteger>()
    if (n < bigTwo) return factors
    if (n.isProbablePrime(20)) {
        factors.add(n)
        return factors
    }
    var factor = bigTwo
    var nn = n
    while (true) {
        if (nn % factor == BigInteger.ZERO) {
            factors.add(factor)
            nn /= factor
            if (nn == BigInteger.ONE) return factors
            if (nn.isProbablePrime(20)) factor = nn
        }
        else if (factor >= bigThree) factor += bigTwo
        else factor = bigThree
    }
}
 
