fun gen(N: Int): String {
    val txt = CharArray(N * 2)
    for (i in 0 until N) {
        txt[i] = '['
        txt[N * 2 - i - 1] = ']'
    }
    txt.shuffle()
    return String(txt)
}

fun balanced(txt: String): Boolean {
    var braced = 0
    for (ch in txt) {
        if (ch == '[') braced++
        if (ch == ']') {
            braced--
            if (braced < 0) return false
        }
    }
    return braced == 0
}

