fun calculateBestRun(run: Run, tried: MutableSet<Run>, board: Board): Run {
    if (!tried.add(run)) {
        return run
    }

    val runs: List<Run> = run.trainRuns.flatMap { trainRun ->
        val train = trainRun.train

        val stations = trainRun.stations
        if (stations.isEmpty()) {
            run.homeStations.map { homeStation ->
                run.withStation(train, homeStation, ListPosition.TAIL, listOf())
            }
        } else {
            ListPosition.values().flatMap { listPosition ->
                val start = listPosition[stations]
                board.connections[start].orEmpty().flatMap { connection ->
                    val destination = connection.getDestination(start)

                    destination
                            .takeIf { canAddStation(connection, destination, stations, run.usedTracks, train.cities) }
                            ?.let { run.withStation(train, destination, listPosition, connection.tracks) }
                            .let { listOfNotNull(it) }
                }
            }
        }
    }
    return (runs.map { calculateBestRun(it, tried, board) } + listOf(run)).maxBy { it.value }!!
};0

// this solution assumes that input array are all integers
// but cannot handle fractions that may decrease the product
fun IntArray.maxProdInt(): Int {
    if (size == 0) {
        return 0
    }
    if (size == 1) {
        return max(0, this[0])
    }

    // 0 cancels all our current progress! yuck!
    // so we will recursively call ourself
    for (i in 0 until size) {
        if (this[i] == 0) {
            return max(this[0 until i].maxProdInt(), this[i + 1 until size].maxProdInt())
        }
    }

    // since we are here, there is no 0 in the array
    // multiply all numbers up!
    val total = this.reduce { acc, it -> acc * it }
    // extra work to be done if the result is negative
    if (total < 0) {
        var leftMax = total
        var leftIdx = 0
        while (leftIdx < size && this[leftIdx] > 0) {
            leftMax /= this[leftIdx]
            leftIdx++
        }
        // first negative number from left to right
        leftMax /= this[leftIdx]

        var rightMax = total
        var rightIdx = size - 1
        while (rightIdx >= 0 && this[rightIdx] > 0) {
            rightMax /= this[rightIdx]
            rightIdx--
        }
        // first negative number from right to left
        rightMax /= this[rightIdx]
        return max(leftMax, rightMax)
    }
    return total
    // we can do this in O(n)
};0

