fun main(args: Array<String>) {
    val base = 12
    val moves = arrayOf(intArrayOf(1, -2), intArrayOf(2, -1), intArrayOf(2, 1), intArrayOf(1, 2), intArrayOf(-1, 2), intArrayOf(-2, 1), intArrayOf(-2, -1), intArrayOf(-1, -2))
    val grid = Array(base) { IntArray(base) }
    val total = (base - 4) * (base - 4)
 
    for (r in 0 until base) {
        for (c in 0 until base) {
            if (r < 2 || r > base - 3 || c < 2 || c > base - 3) {
                grid[r][c] = -1
            }
        }
    }
 
    val row = 2 + (Math.random() * (base - 4)).toInt()
    val col = 2 + (Math.random() * (base - 4)).toInt()
 
    grid[row][col] = 1
 
    if (solve(row, col, 2, grid, total, moves)) {
        printResult(grid)
    } else {
        println("no result")
    }
}
 
fun solve(r: Int, c: Int, count: Int, grid: Array<IntArray>, total: Int, moves: Array<IntArray>): Boolean {
    if (count > total) {
        return true
    }
 
    val nbrs = neighbors(r, c, grid, moves)
 
    if (nbrs.isEmpty() && count!= total) {
        return false
    }
 
    nbrs.sortWith(Comparator { a, b -> a[2] - b[2] })
 
    for (nb in nbrs) {
        val x = nb[0]
        val y = nb[1]
        grid[x][y] = count
        if (!orphanDetected(count, x, y, grid, total, moves) && solve(x, y, count + 1, grid, total, moves)) {
            return true
        }
        grid[x][y] = 0
    }
 
    return false
}
 
fun neighbors(r: Int, c: Int, grid: Array<IntArray>, moves: Array<IntArray>): List<IntArray> {
    val nbrs = ArrayList<IntArray>()
 
    for (m in moves) {
        val x = m[0]
        val y = m[1]
        if (grid[r + y][c + x] == 0) {
            val num = countNeighbors(r + y, c + x, grid, moves)
            nbrs.add(intArrayOf(r + y, c + x, num))
        }
    }
    return nbrs
}
 
fun countNeighbors(r: Int, c: Int, grid: Array<IntArray>, moves: Array<IntArray>): Int {
    var num = 0
    for (m in moves) {
        if (grid[r + m[1]][c + m[0]] == 0) {
            num++
        }
    }
    return num
}
 
fun orphanDetected(cnt: Int, r: Int, c: Int, grid: Array<IntArray>, total: Int, moves: Array<IntArray>): Boolean {
    if (cnt < total - 1) {
        val nbrs = neighbors(r, c, grid, moves)
        for (nb in nbrs) {
            if (countNeighbors(nb[0], nb[1], grid, moves) == 0) {
                return true
            }
        }
    }
    return false
}
 
