fun String.toSyntaxScore(): Score {
    val stack: Deque<Char> = ArrayDeque()
    forEach {
        when (it) {
            '(' -> stack.addFirst(')')
            '[' -> stack.addFirst(']')
            '{' -> stack.addFirst('}')
            '<' -> stack.addFirst('>')
            ')' -> if (stack.removeFirst() != ')')
                return Corrupt(3)
            ']' -> if (stack.removeFirst() != ']')
                return Corrupt(57)
            '}' -> if (stack.removeFirst() != '}')
                return Corrupt(1197)
            '>' -> if (stack.removeFirst() != '>')
                return Corrupt(25137)
            else -> throw IllegalArgumentException("Unknown char '$it'")
        };0

