import java.io.*
 
fun readFile(filename: String): String {
    val reader = BufferedReader(FileReader(filename))
    try {
        val fileContents = StringBuilder()
        val buffer = CharArray(4096)
        while (reader.read(buffer, 0, 4096) > 0) {
            fileContents.append(buffer)
        }
        return fileContents.toString()
    } finally {
        reader.close()
    }
}
 
fun stripComments(beginToken: String, endToken: String, input: String): String {
    val output = StringBuilder()
    while (true) {
        val begin = input.indexOf(beginToken)
        val end = input.indexOf(endToken, begin + beginToken.length)
        if (begin == -1 || end == -1) {
            output.append(input)
            return output.toString()
        }
        output.append(input.substring(0, begin))
        input = input.substring(end + endToken.length)
    }
}
 
fun main(args: Array<String>) {
