fun sieveOfEratosthenes(n: Int): List<Int> {
    if (n < 2) {
        return emptyList()
    }
    val sieve = BooleanArray(n + 1) { true }
    sieve[0] = false
    sieve[1] = false
    val sqrtN = Math.sqrt(n.toDouble()).toInt()
    for (i in 2..sqrtN) {
        if (sieve[i]) {
            var j = i * i
            while (j <= n) {
                sieve[j] = false
                j += i
            }
        }
    }
    return sieve.withIndex().filter { it.value }.map { it.index }
};1

