fun mergeDictionaries(dict1: Map<String, Any?>?, dict2: Map<String, Any?>?): Map<String, Double> {
    val merged = mutableMapOf<String, Double>()

    fun safeAdd(k: Any?, v: Any?) {
        if (k !is String || k.length != 1 || !k[0].isLetter()) return
        val numVal: Double = when (v) {
            is Number -> v.toDouble()
            is String -> v.toDoubleOrNull() ?: return
            else -> return
        }
        val kLower = k.lowercase()
        merged[kLower] = merged.getOrDefault(kLower, 0.0) + numVal
    }

    if (dict1 is Map<*, *>) {
        for ((key, value) in dict1) {
            safeAdd(key, value)
        }
    }
    if (dict2 is Map<*, *>) {
        for ((key, value) in dict2) {
            safeAdd(key, value)
        }
    }
    return merged
};1

