fun maxPopularity(testCases: List<List<Pair<Int, Int>>>): List<Int> {
    val results = mutableListOf<Int>()
    for (case in testCases) {
        val events = mutableListOf<Pair<Int, Int>>()
        for ((T1, T2) in case) {
            events.add(Pair(T1, 1))
            events.add(Pair(T2, -1))
        }
        events.sortWith(compareBy({ it.first }, { it.second }))
        var current = 0
        var maxCurrent = 0
        for ((_, delta) in events) {
            current += delta
            if (current > maxCurrent) {
                maxCurrent = current
            }
        }
        results.add(maxCurrent)
    }
    return results
};1

