fun isPrime(n: Int): Boolean {
    if (n == 2 || n == 3)
        return true
    else if (n < 2 || n % 2 == 0 || n % 3 == 0)
        return false
    for (div in 5..Math.sqrt(n.toDouble()).toInt() step 6) {
        if (n % div == 0)
            return false
    }
    return true
}

fun main(args: Array<String>) {
    for (p in 2..62) {
        if (!isPrime(p))
            continue
        for (h3 in 2..p) {
            val g = h3 + p
            for (d in 1..g) {
                if ((g * (p - 1)) % d!= 0 || mod(-p * p, h3)!= d % h3)
                    continue
                val q = 1 + (p - 1) * g / d
                if (!isPrime(q))
                    continue
                val r = 1 + (p * q / h3)
                if (!isPrime(r) || (q * r) % (p - 1)!= 1)
                    continue
                println("$p x $q x $r")
            }
        }
    }
};1

