class OptimizedRandomizedSet {
    private val nums = mutableListOf<Int>()
    private val valToIndex = mutableMapOf<Int, Int>()

    fun insert(`val`: Int): Boolean {
        if (`val` in valToIndex) {
            return false
        }
        valToIndex[`val`] = nums.size
        nums.add(`val`)
        return true
    }

    fun remove(`val`: Int): Boolean {
        val idx = valToIndex[`val`] ?: return false
        val lastVal = nums.last()
        nums[idx] = lastVal
        valToIndex[lastVal] = idx
        nums.removeAt(nums.size - 1)
        valToIndex.remove(`val`)
        return true
    }

    fun getRandom(): Int {
        if (nums.isEmpty()) throw IndexOutOfBoundsException("Set is empty.")
        return nums[Random.nextInt(nums.size)]
    }
};1

fun firstTwoElements(data: Any?): Any {
    return when (data) {
        is String -> {
            if (data.length < 2) {
                "Input is too short"
            } else {
                data.substring(0, 2)
            }
        }
        is List<*> -> {
            if (data.size < 2) {
                "Input is too short"
            } else {
                data.subList(0, 2)
            }
        }
        is Array<*> -> {
            if (data.size < 2) {
                "Input is too short"
            } else {
                data.copyOfRange(0, 2)
            }
        }
        else -> "Invalid input type, expected string, list, or array"
    }
};1

