data class Card(var suit: Int, var number: Int, var _s: Int)
data class Deck(var n: Int, var cards: Array<Card>)
 
fun showCard(c: Card) {
    if (localeOk)
        print(" ${sSuits[c.suit]}${sNums[c.number]}")
    else
        print(" ${sSuitsAscii[c.suit]}${sNums[c.number]}")
