fun newDeck(): Deck {
    val d = Deck(52, Array(52) { Card(0, 0, 0) })
    d.n = 52
    for (i in 0..3)
        for (j in 1..13) {
            d.cards[i * 13 + j - 1].suit = i
            d.cards[i * 13 + j - 1].number = j
        }
    return d
}
 
fun showDeck(d: Deck) {
    print("${d.n} cards:")
    for (i in 0 until d.n)
        showCard(d.cards[i])
    println()
}
 
fun cmpCard(a: Card, b: Card): Int {
    val x = a._s
    val y = b._s
    return if (x < y) -1 else if (x > y) 1 else 0
}
 
fun dealCard(d: Deck): Card? {
    if (d.n == 0) return null
    return d.cards[--d.n]
}
 
fun shuffleDeck(d: Deck) {
    for (i in 0 until d.n)
        d.cards[i]._s = Math.random().toInt()
    d.cards.sortWith(Comparator { a, b -> cmpCard(a, b) })
}
 
