fun calculateFuelWithMaxPayload(outPayloads: List<Number>): Map<Int, Double> {
    if (outPayloads.isEmpty()) return emptyMap()
    val maxPayload = outPayloads.maxOf { it.toDouble() }
    val fuelRequired = maxPayload * 0.5
    return outPayloads.indices.associateWith { fuelRequired }
