        fifth[i - 1] = i2 * i2 * i
    }
    for (a in 0 until MAX_NUMBER) {
        if (found) {
            break
        }
        for (b in a until MAX_NUMBER) {
            if (found) {
                break
            }
            for (c in b until MAX_NUMBER) {
                if (found) {
                    break
