                for (d in c until MAX_NUMBER) {
                    val sum = fifth[a] + fifth[b] + fifth[c] + fifth[d]
                    val e = fifth.binarySearch(sum)
                    found = e >= 0
                    if (found) {
                        println(String.format("%d^5 + %d^5 + %d^5 + %d^5 = %d^5", a + 1, b + 1, c + 1, d + 1, e + 1))
