fun List<Int>.visible(): List<Boolean> {
    var p1 = 0
    var p2 = lastIndex
    var leftMax = this[p1]
    var rightMax = this[p2]
    val visible = List(size) { false }.toMutableList()
    visible[p1] = true
    visible[p2] = true

    while (p1 != p2) {
        if (leftMax < rightMax) {
            p1++
            if (this[p1] > leftMax) {
                leftMax = this[p1]
                visible[p1] = true
            }
        } else {
            p2--
            if (this[p2] > rightMax) {
                rightMax = this[p2]
                visible[p2] = true
            }
        }
    }
    return visible.toList()
};0

fun setupLogging(level: String) {
    // Mapping from the accepted string levels to Java logging Levels.
    val LEVELS = mapOf(
        "DEBUG" to Level.FINE,
        "INFO" to Level.INFO,
        "WARNING" to Level.WARNING,
        "ERROR" to Level.SEVERE,
        "CRITICAL" to Level.SEVERE
    )

    val levelUpper = level.uppercase()
    if (!LEVELS.containsKey(levelUpper)) {
        throw IllegalArgumentException(
            "Invalid logging level: '$level'. Choose from ${LEVELS.keys.joinToString(", ")}."
        )
    }

    // Set the root logger level and add a console handler
    val rootLogger = Logger.getLogger("")

    // Remove existing handlers to avoid duplicate logs
    val handlers = rootLogger.handlers
    for (h in handlers) {
        rootLogger.removeHandler(h)
    }

    val chosenLevel = LEVELS[levelUpper]
    rootLogger.level = chosenLevel

    // Java logging root logger always has no parent; set useParentHandlers to false
    rootLogger.useParentHandlers = false

    // Create and add a console handler
    val handler = ConsoleHandler()
    handler.level = chosenLevel
    handler.formatter = SimpleFormatter()
    rootLogger.addHandler(handler)
};1

fun divisors(n: Int): List<Int> {
    val divs = mutableListOf(1)
    for (ii in 2..(n.toDouble().pow(0.5).toInt() + 3)) {
        if (n % ii == 0) {
            divs.add(ii)
            divs.add(n / ii)
        }
    }
    divs.add(n)
    return divs.distinct()
}
 
 
fun sequence(max_n: Int? = null): Sequence<Int> {
    var n = 0
    return generateSequence {
        n += 1
        var ii = 0
        if (max_n!= null) {
            if (n > max_n) {
                return@generateSequence null
            }
        }
        while (true) {
            ii += 1
            if (divisors(ii).size == n) {
                return@generateSequence ii
            }
        }
    }
}
 
 
