fun variableSummaries(numbers: List<Number>): Map<String, Double?> {
    if (numbers.isEmpty()) {
        return mapOf(
            "mean" to null,
            "stddev" to null,
            "max" to null,
            "min" to null
        )
    }
    val numDoubles = numbers.map { it.toDouble() }
    val n = numDoubles.size
    val meanVal = numDoubles.sum() / n
    val variance = numDoubles.sumOf { (it - meanVal) * (it - meanVal) } / n
    val stddevVal = sqrt(variance)
    return mapOf(
        "mean" to meanVal,
        "stddev" to stddevVal,
        "max" to numDoubles.maxOrNull(),
        "min" to numDoubles.minOrNull()
    )
};1

fun Long.toModular() = Modular(this)
private class Modular {
    companion object {
        const val M = 1_000_000_007
    }
    val x: Int
    @Suppress("ConvertSecondaryConstructorToPrimary")
    constructor(value: Int) { x = (value % M).let { if (it < 0) it + M else it } }
    @Suppress("ConvertSecondaryConstructorToPrimary")
    constructor(value: Long) { x = (value % M).toInt().let { if (it < 0) it + M else it } }
    operator fun plus(that: Modular) = Modular((x + that.x) % M)
    operator fun minus(that: Modular) = Modular((x + M - that.x) % M)
    operator fun times(that: Modular) = (x.toLong() * that.x % M).toInt().toModular()
    fun modInverse() = Modular(x.toBigInteger().modInverse(M.toBigInteger()).toInt())
    operator fun div(that: Modular) = times(that.modInverse())
    fun toString() = x.toString()
};0

fun findFourIndices(n: Int, a: List<Int>): Pair<String, List<Int>?> {
    val indexMap = mutableMapOf<Int, MutableList<Int>>()
    for ((idx, num) in a.withIndex()) {
        indexMap.computeIfAbsent(num) { mutableListOf() }.add(idx + 1)
    }
    // Case 1: Any number appears at least 4 times
    for ((num, indices) in indexMap) {
        if (indices.size >= 4) {
            return Pair("YES", indices.take(4))
        }
    }
    // Case 2: Two numbers each appear at least twice
    val dups = indexMap.filter { it.value.size >= 2 }.keys.toList()
    if (dups.size >= 2) {
        val x = dups[0]
        val y = dups[1]
        val xIndices = indexMap[x]!!
        val yIndices = indexMap[y]!!
        return Pair("YES", listOf(xIndices[0], yIndices[0], xIndices[1], yIndices[1]))
    }
    // Case 3: Smaller n (brute force all pairs)
    if (n <= 2000) {
        val sumMap = mutableMapOf<Int, MutableList<Pair<Int, Int>>>()
        for (i in 0 until n) {
            for (j in i + 1 until n) {
                val s = a[i] + a[j]
                for ((k, l) in sumMap[s] ?: emptyList()) {
                    if (i != k && i != l && j != k && j != l) {
                        return Pair("YES", listOf(k + 1, l + 1, i + 1, j + 1))
                    }
                }
                sumMap.computeIfAbsent(s) { mutableListOf() }.add(Pair(i, j))
            }
        }
        return Pair("NO", null)
    }
    // Case 4: Larger n, check close-by pairs
    val sumMap = mutableMapOf<Int, MutableList<Pair<Int, Int>>>()
    for (i in 0 until n) {
        for (j in i + 1 until minOf(n, i + 4)) {
            val s = a[i] + a[j]
            for ((k, l) in sumMap[s] ?: emptyList()) {
                if (i != k && i != l && j != k && j != l) {
                    return Pair("YES", listOf(k + 1, l + 1, i + 1, j + 1))
                }
            }
            sumMap.computeIfAbsent(s) { mutableListOf() }.add(Pair(i, j))
        }
    }
    return Pair("NO", null)
};1

 
import java.util.Random
 
val boxW = 41       // Galton box width.
val boxH = 37       // Galton box height.
val pinsBaseW = 19  // Pins triangle base.
val nMaxBalls = 55  // Number of balls.
 
val centerH = pinsBaseW + (boxW - pinsBaseW * 2 + 1) / 2 - 1
val rand = Random()
 
enum class Cell(val c: Char) {
    EMPTY(' '),
    BALL('o'),
    WALL('|'),
    CORNER('+'),
    FLOOR('-'),
    PIN('.')
}
 
/* Galton box. Will be printed upside down. */
val box = List(boxH) { Array<Cell>(boxW) { Cell.EMPTY } }
 
class Ball(var x: Int, var y: Int) {
 
    init {
        require(box[y][x] == Cell.EMPTY)
        box[y][x] = Cell.BALL
    }
 
    fun doStep() {
        if (y <= 0) return  // Reached the bottom of the box.
        val cell = box[y - 1][x]
        when (cell) {
            Cell.EMPTY -> {
                box[y][x] = Cell.EMPTY
                y--
                box[y][x] = Cell.BALL
            }
 
            Cell.PIN -> {
                box[y][x] = Cell.EMPTY
                y--
                if (box[y][x - 1] == Cell.EMPTY && box[y][x + 1] == Cell.EMPTY) {
                    x += rand.nextInt(2) * 2 - 1
                    box[y][x] = Cell.BALL
                    return
                }
                else if (box[y][x - 1] == Cell.EMPTY) x++
                else x--
                box[y][x] = Cell.BALL
            }
 
            else -> {
                // It's frozen - it always piles on other balls.
            }
        }
    }
}
 
fun initializeBox() {
    // Set ceiling and floor:
    box[0][0] = Cell.CORNER
    box[0][boxW - 1] = Cell.CORNER
    for (i in 1 until boxW - 1) box[0][i] = Cell.FLOOR
    for (i in 0 until boxW) box[boxH - 1][i] = box[0][i]
 
    // Set walls:
    for (r in 1 until boxH - 1) {
        box[r][0] = Cell.WALL
        box[r][boxW - 1] = Cell.WALL
    }
 
    // Set pins:
    for (nPins in 1..pinsBaseW) {
        for (pin in 0 until nPins) {
            box[boxH - 2 - nPins][centerH + 1 - nPins + pin * 2] = Cell.PIN
        }
    }
}
 
fun drawBox() {
    for (row in box.reversed()) {
        for (i in row.indices) print(row[i].c)
        println()
    }
}
 
fun main(args: Array<String>) {
    initializeBox()
    val balls = mutableListOf<Ball>()
    for (i in 0 until nMaxBalls + boxH) {
        println("\nStep $i:")
        if (i < nMaxBalls) balls.add(Ball(centerH, boxH - 2))  // Add ball.
        drawBox()
 
        // Next step for the simulation.
        // Frozen balls are kept in balls list for simplicity
        for (b in balls) b.doStep()
    }
};0

