fun calculateNextExecution(frequency: String, time: String, day: String, currentTime: String): String {
    if (frequency.lowercase() != "weekly") {
        throw NotImplementedError("This function currently supports only weekly schedules.")
    }

    val now = try {
        LocalDateTime.parse(currentTime, DateTimeFormatter.ISO_LOCAL_DATE_TIME)
    } catch (e: Exception) {
        throw IllegalArgumentException("Invalid currentTime '$currentTime': ${'$'}{e.message}")
    }

    val weekdayMap = mapOf(
        "Mon" to DayOfWeek.MONDAY,
        "Tue" to DayOfWeek.TUESDAY,
        "Wed" to DayOfWeek.WEDNESDAY,
        "Thu" to DayOfWeek.THURSDAY,
        "Fri" to DayOfWeek.FRIDAY,
        "Sat" to DayOfWeek.SATURDAY,
        "Sun" to DayOfWeek.SUNDAY
    )

    val targetDayOfWeek = weekdayMap[day] ?: throw IllegalArgumentException("Invalid day '$day'. Expected one of ${weekdayMap.keys}.")

    val (hour, minute) = try {
        time.split(":").let {
            Pair(it[0].toInt(), it[1].toInt())
        }
    } catch (e: Exception) {
        throw IllegalArgumentException("Invalid time '$time': ${'$'}{e.message}")
    }

    val targetTime = LocalTime.of(hour, minute)

    val daysAhead = ((targetDayOfWeek.value - now.dayOfWeek.value + 7) % 7)
    val candidateDate = now.toLocalDate().plusDays(daysAhead.toLong())
    var candidateDT = LocalDateTime.of(candidateDate, targetTime)

    if (candidateDT < now) {
        candidateDT = candidateDT.plusDays(7)
    }

    return candidateDT.format(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss"))
};1

fun solve(lines: List<String>) {
    @Suppress("NAME_SHADOWING")
    val lines = ArrayDeque(lines)
    val lastVisited = ArrayDeque<Directory>()
    val root = Directory("root")
    val allFiles = mutableListOf<SystemObject>()
    while (lines.isNotEmpty()) {
        when (val line = lines.removeFirst()) {
            "\$ ls" -> {
                lines
                    .takeWhile { !it.startsWith('$') }
                    .also { lines.subList(0, it.size).clear() }
                    .let { lastVisited.last().updateWithLsOutput(it) }
                    .let { allFiles.addAll(it) }
            }

            "\$ cd .." -> {
                lastVisited.removeLast()
                lastVisited.lastOrNull()?.recalculateSize()
            }

            "\$ cd /" -> { //only happens once in my input so not bothering to back up one level at a time
                lastVisited.add(root)
            }

            else -> lastVisited.add(lastVisited.last().cd(line.substringAfter("\$ cd ")))
        }
    }
    while (lastVisited.isNotEmpty()) lastVisited.removeLast().apply { recalculateSize() }
    val part1 =
        allFiles
            .filterIsInstance<Directory>()
            .map { it.size!! }
            .filter { it < BigInteger("100000") }
            .sumOf { it }
    println("part 1 $part1")
    val freeSpaceStillNeeded = BigInteger("30000000").minus(BigInteger("70000000").minus(root.size!!))
    val part2 = allFiles
        .filterIsInstance<Directory>()
        .map { it.size!! }
        .filter { it >= freeSpaceStillNeeded }
        .min()
    println("part 2 $part2")

};0

fun swapWithoutTemp(a: Int, b: Int): Pair<Int, Int> {
    var aVar = a
    var bVar = b
    aVar = aVar xor bVar // Step 1: aVar holds (a XOR b)
    bVar = bVar xor aVar // Step 2: bVar becomes original a
    aVar = aVar xor bVar // Step 3: aVar becomes original b
    return Pair(aVar, bVar)
};1

fun day8ProblemReader(string: String): List<Instruction> {
    val instructionRegex = """(\w+)\s(\+|\-)(\d+)""".toRegex()
    return string
        .split("\n")
        .map { line ->
            val (instruction, signStr, amount) = instructionRegex.matchEntire(line)!!.destructured
            if (signStr == "+") {
                Instruction(instruction, true, amount.toInt())
            } else {
                Instruction(instruction, false, amount.toInt())
