fun main(args: Array<String>) {
    val r = java.util.Random()
    var count = 0
    val numbers = IntArray(9)
    numbers[0] = 2 + r.nextInt(8) // this will ensure list isn't ascending
    for (i in 1..8) {
        var rn: Int
        do {
            rn = 1 + r.nextInt(9)
        } while (rn in numbers)
        numbers[i] = rn
    }
