            numbers[i++] = numbers[j]
            numbers[j--] = temp
        }
        if (isAscending(numbers)) {
            println("Here's your final list : ${numbers.joinToString()}")
            break
        }
        println("Here's your list now   : ${numbers.joinToString()}")
    }
    println("So you've completed the game with a score of $count")
