fun countSubstringsWithSbeginAndSend(t: String, sbegin: String, send: String): Int {
    val lenT = t.length
    val lenSb = sbegin.length
    val lenSd = send.length

    val sbeginStarts = mutableListOf<Int>()
    for (i in 0..(lenT - lenSb)) {
        if (t.substring(i, i + lenSb) == sbegin) {
            sbeginStarts.add(i)
        }
    }

    val sendEnds = mutableListOf<Int>()
    for (j in (lenSd - 1) until lenT) {
        val start = j - lenSd + 1
        if (start >= 0 && t.substring(start, j + 1) == send) {
            sendEnds.add(j)
        }
    }

    if (sbeginStarts.isEmpty() || sendEnds.isEmpty()) {
        return 0
    }

    val mod = 1000000000000000003L
    val base = 911382629L
    val maxLen = lenT

    val prefixHash = LongArray(lenT + 1)
    val power = LongArray(lenT + 1) { 1L }
    for (i in 0 until lenT) {
        prefixHash[i + 1] = (prefixHash[i] * base + t[i].code.toLong()) % mod
        power[i + 1] = (power[i] * base) % mod
    }

    fun getHash(l: Int, r: Int): Long {
        var res = (prefixHash[r + 1] - prefixHash[l] * power[r - l + 1]) % mod
        if (res < 0) res += mod
        return res
    }

    val sendEndsSorted = sendEnds.sorted()
    val maxLenRequired = max(lenSb, lenSd)
    val seen = mutableSetOf<Long>()
    for (i in sbeginStarts) {
        val minJ = i + maxLenRequired - 1
        val idx = sendEndsSorted.indexOfFirst { it >= minJ }.let { if (it == -1) sendEndsSorted.size else it }
        for (k in idx until sendEndsSorted.size) {
            val j = sendEndsSorted[k]
            if (j < i + lenSb - 1 || j < i + lenSd - 1) continue
            val h = getHash(i, j)
            seen.add(h)
        }
    }
    return seen.size
};1

 
import java.math.BigInteger
 
fun leftFactorial(n: Int): BigInteger {
    if (n == 0) return BigInteger.ZERO
    var fact = BigInteger.ONE
    var sum = fact
    for (i in 1 until n) {
        fact *= BigInteger.valueOf(i.toLong())
        sum += fact
    }
    return sum
}
 
