fun findFibonacciTuples(startList: List<Map<String, Int>>, limit: Int): List<Triple<Int, String, Int>> {
    if (limit <= 0) return emptyList()

    // Precompute all Fibonacci numbers below limit
    val fibSet = mutableSetOf<Int>()
    var a = 0
    var b = 1
    while (a < limit) {
        fibSet.add(a)
        val tmp = a + b
        a = b
        b = tmp
    }

    val result = mutableListOf<Triple<Int, String, Int>>()
    for ((idx, map) in startList.withIndex()) {
        for ((key, value) in map) {
            if (value in fibSet) {
                result.add(Triple(idx, key, value))
            }
        }
    }
    return result
};1

