class AtomicUpdates {
    companion object {
        private const val NUM_BUCKETS = 10

        class Buckets(data: IntArray) {
            private val data: IntArray = data.clone()

            fun getBucket(index: Int): Int {
                synchronized(data) {
                    return data[index]
                }
            }

            fun transfer(srcIndex: Int, dstIndex: Int, amount: Int): Int {
                if (amount < 0) throw IllegalArgumentException("negative amount: $amount")
                if (amount == 0) return 0

                synchronized(data) {
                    if (data[srcIndex] - amount < 0) amount = data[srcIndex]
                    if (data[dstIndex] + amount < 0) amount = Integer.MAX_VALUE - data[dstIndex]
                    if (amount < 0) throw IllegalStateException()
                    data[srcIndex] -= amount
                    data[dstIndex] += amount
                    return amount
                }
            }

            fun getBuckets(): IntArray {
                synchronized(data) {
                    return data.clone()
                }
            }
        }

        fun getTotal(values: IntArray): Long {
            var total = 0L
            for (value in values) {
                total += value
            }
            return total
