data class Quadruple<A, B, C, D>(val first: A, val second: B, val third: C, val fourth: D)

fun rectanglesInQuery(n: Int, rect1: Quadruple<Int, Int, Int, Int>, rect2: Quadruple<Int, Int, Int, Int>, query: Quadruple<Int, Int, Int, Int>): Int {
    fun inside(r1: Quadruple<Int, Int, Int, Int>, r2: Quadruple<Int, Int, Int, Int>): Boolean {
        val (x1, y1, x2, y2) = r1
        val (qx1, qy1, qx2, qy2) = r2
        return (qx1 <= x1 && x2 <= qx2) && (qy1 <= y1 && y2 <= qy2)
    }
    var count = 0
    if (inside(rect1, query)) {
        count += 1
    }
    if (inside(rect2, query)) {
        count += 1
    }
    return count
};1

import java.lang.StringBuilder
 
fun bin2str(value: Int, buffer: StringBuilder): String {
    // This algorithm is not the fastest one, but is relativelly simple.
    //
    // A faster algorithm would be conversion octets to strings by a lookup table.
    // There is only 2**8 == 256 octets, therefore we would need only 2048 bytes
    // for the lookup table. Conversion of a 64-bit integers would need 8 lookups
    // instead 64 and/or/shifts of bits etc. Even more... lookups may be implemented
    // with XLAT or similar CPU instruction... and AVX/SSE gives chance for SIMD.
 
    val N_DIGITS = 32
    var mask = 1 shl (N_DIGITS - 1)
    var ptr = 0
 
    for (i in 0 until N_DIGITS) {
        buffer[ptr++] = '0' + (value and mask!= 0)
        mask = mask shr 1
    }
    buffer[ptr] = '\u0000'
 
    // Remove leading zeros.
    //
    for (ptr in 0 until buffer.length) {
        if (buffer[ptr]!= '0') {
            break
        }
    }
 
    return buffer.substring(ptr)
}
 
fun bin2strNaive(value: Int, buffer: StringBuilder): String {
    // This variation of the solution doesn't use bits shifting etc.
 
    var n = 0
    var p = 1  // p = 2 ** n
    while (p <= value / 2) {
        n = n + 1
        p = p * 2
    }
 
    var m = 0
    while (n > 0) {
        buffer[m] = '0' + value / p
        value = value % p
        m = m + 1
        n = n - 1
        p = p / 2
    }
 
    buffer[m + 1] = '\u0000'
    return buffer.toString()
}
 
fun main(args: Array<String>) {
    val NUMBERS = intArrayOf(5, 50, 9000)
 
    val RADIX = 2
    val buffer = StringBuilder(32 + 1)
 
    // Function itoa is an POSIX function, but it is not in C standard library.
    // There is no big surprise that Microsoft deprecate itoa because POSIX is
    // "Portable Operating System Interface for UNIX". Thus it is not a good
    // idea to use _itoa instead itoa: we lost compatibility with POSIX;
    // we gain nothing in MS Windows (itoa-without-underscore is not better
    // than _itoa-with-underscore). The same holds for kbhit() and _kbhit() etc.
    //
    for (i in NUMBERS.indices) {
        val value = NUMBERS[i]
        itoa(value, buffer, RADIX)
        println("itoa:          $value decimal = ${buffer.toString()} binary")
    }
 
    // Yeep, we can use a homemade bin2str function. Notice that C is very very
    // efficient (as "hi level assembler") when bit manipulation is needed.
    //
    for (i in NUMBERS.indices) {
        val value = NUMBERS[i]
        println("bin2str:       $value decimal = ${bin2str(value, buffer)} binary")
    };1

class TreeNode(var `val`: Int = 0, var left: TreeNode? = null, var right: TreeNode? = null)

fun kthSmallest(root: TreeNode?, k: Int): Int {
    val stack = ArrayDeque<TreeNode>()
    var current = root
    var count = 0
    while (stack.isNotEmpty() || current != null) {
        while (current != null) {
            stack.addLast(current)
            current = current.left
        }
        current = stack.removeLast()
        count += 1
        if (count == k) return current.`val`
        current = current.right
    }
    return -1 // This line is theoretically unreachable if k is valid
};1

