fun calculateL1Loss(l1: Int, regParams: List<Double>): Double {
    // Quick exits for the trivial cases
    if (l1 == 0 || regParams.isEmpty()) {
        return 0.0
    }
    // Compute sum of absolute values of parameters
    val absSum = regParams.sumOf { kotlin.math.abs(it) }
    // Return L1 regularization loss
    return l1 * absSum
};1

