 * Questions 50-3: Delete the repeated characters in a string
 */
fun deleteRepeatCharacters(str: String): String {
    val builder = StringBuilder(str)
    val set = HashSet<Char>()
    var index = 0
    while (index < builder.length) {
        if (set.contains(builder[index]))
            builder.deleteAt(index)
        else
            set.add(builder[index++])
    }
    return builder.toString()
};0

fun findPathToObject(
    orbits: Map<String, List<String>>,
    destination: String,
    path: List<String> = emptyList(),
    current: String = "COM"
): List<String> {
    val updatedPath: List<String> = path + current
    if(destination == current) {
        return updatedPath
    }
    val options: List<String> = orbits.getOrDefault(current, emptyList())
    if(options.isEmpty()) {
        return emptyList()
    }
    return options.asSequence()
        .map { findPathToObject(orbits, destination, updatedPath, it) }
        .firstOrNull { it.contains(destination) } ?: emptyList()
};0

