        for (k in 0..n) {
            print("%10s".format(sterling2(n, k)))
        }
        println()
    }
    println("The maximum value of S2(100, k) = ")
    var previous = BigInteger.ZERO
    for (k in 1..100) {
        val current = sterling2(100, k)
        previous = if (current > previous) {
            current
        } else {
            println("%s%n(%d digits, k = %d)".format(previous, previous.toString().length, k - 1))
            break
        }
    }
}
 
private val COMPUTED: MutableMap<String, BigInteger> = HashMap()
fun sterling2(n: Int, k: Int): BigInteger {
    val key = "$n,$k"
    if (COMPUTED.containsKey(key)) {
        return COMPUTED[key]!!
    }
    if (n == 0 && k == 0) {
        return BigInteger.valueOf(1)
    }
    if (n > 0 && k == 0 || n == 0 && k > 0) {
        return BigInteger.ZERO
    }
    if (n == k) {
        return BigInteger.valueOf(1)
    }
    if (k > n) {
        return BigInteger.ZERO
    }
 
    val result = BigInteger.valueOf(k.toLong()) * sterling2(n - 1, k) + sterling2(n - 1, k - 1)
    COMPUTED[key] = result
    return result
};0

fun doubleEvenMagicSquare(n: Int): Array<IntArray> {
    if (n % 4 > 0) throw IllegalArgumentException("Need multiple of four")
    val block_size = n / 4
    val max = n * n
    val pre_pat = booleanArrayOf(true, false, false, true, false, true, true, false)
    val pattern = pre_pat.flatMap { b -> List(block_size) { b } } * block_size
    val flat_ar = pattern.mapIndexed { num, yes -> if (yes) num + 1 else max - num }
    return flat_ar.chunked(n).toTypedArray()
}
 
fun toString(square: Array<IntArray>): String {
    val n = square.size
    val fmt = "%${(n * n).toString().length + 1}d".repeat(n)
    return square.joinToString("\n") { row -> fmt.format(*row.toTypedArray()) }
}
 
