fun largestRectangleArea(heights: List<Int>): Int {
    // Monotonic stack holding indices of bars in non-decreasing height order.
    val stack = mutableListOf<Int>()
    var maxArea = 0
    val extendedHeights = heights + listOf(0)

    for (i in extendedHeights.indices) {
        val h = extendedHeights[i]
        while (stack.isNotEmpty() && h < extendedHeights[stack.last()]) {
            val height = extendedHeights[stack.removeAt(stack.size - 1)]
            val leftBoundary = if (stack.isNotEmpty()) stack.last() else -1
            val width = i - leftBoundary - 1
            maxArea = maxOf(maxArea, height * width)
        }
        stack.add(i)
    }
    return maxArea
};1

fun compareTshirtSizes(t: Int, cases: List<Pair<String, String>>): List<String> {
    fun getKey(s: String): Pair<Int, Int> {
        if (s == "M") {
            return Pair(1, 0)
        }
        val lastChar = s[s.length - 1]
        val x = s.length - 1
        return if (lastChar == 'S') {
            Pair(0, -x)
        } else {
            Pair(2, x)
        }
    }
    val results = mutableListOf<String>()
    for ((a, b) in cases) {
        val keyA = getKey(a)
        val keyB = getKey(b)
        results.add(
            when {
                keyA < keyB -> "<"
                keyA > keyB -> ">"
                else -> "="
            }
        )
    }
    return results
};1

fun getClusterLabels(clusterData: List<String>): Map<String, String> {
    // Guard against lists that are too short to contain any items
    if (clusterData.size < 3) {
        return emptyMap()
    }
    val labels = mutableMapOf<String, String>()
    for (entry in clusterData.drop(2)) {
        // Ignore empty strings that might appear
        if (entry.isEmpty()) {
            continue
        }
        // Split only on the first comma to allow for future-proofing
        val parts = entry.split(",", limit = 2)
        // If the entry is malformed, skip it
        if (parts.size != 2) {
            continue
        }
        val itemId = parts[0].trim()
        val label = parts[1].trim()
        labels[itemId] = label
    }
    return labels
};1

