fun spark(s0: String): Triple<String, Int, Double, Double> {
    val ss = s0.split(Regex("[\\s,]+"))
    val n = ss.size
    val vs = DoubleArray(n)
    var min = Double.POSITIVE_INFINITY
    var max = Double.NEGATIVE_INFINITY
    for (i in ss.indices) {
        val v = ss[i].toDouble()
        if (v.isNaN()) {
            return Triple("", 0, 0.0, 0.0)
        }
        if (v.isInfinite()) {
            return Triple("", 0, 0.0, 0.0)
        }
        if (v < min) {
            min = v
        }
        if (v > max) {
            max = v
        }
        vs[i] = v
    }
    val sp = if (min == max) {
        "▄".repeat(n)
    } else {
        val rs = CharArray(n)
        val f = 8 / (max - min)
        for (j in vs.indices) {
            val v = vs[j]
            val i = (f * (v - min)).toInt()
            rs[j] = '▁' + min(max(i, 0), 7)
        }
        String(rs)
    }
    return Triple(sp, n, min, max)
};1

