fun troubleshootJob(
    server: String,
    jobName: String,
    jobId: Any,
    jobServerStatus: String,
    remotePath: String,
    serverNodes: List<String>? = null
): Pair<String?, Boolean> {
    // Early exit if the job is finished
    if (jobServerStatus == "done") {
        return Pair(null, false)
    }

    // Nothing to do while it is still running
    if (jobServerStatus == "running") {
        return Pair(null, false)
    }

    // Decide which node to try next
    val triedNodes = (serverNodes ?: emptyList()).toSet()

    // Pre-defined node pools for the most common servers
    val nodePools = mapOf(
        "serverA" to (1..8).map { "node%02d".format(it) },
        "serverB" to (1..4).map { "cpu$it" },
        "serverC" to (0..3).map { "gpu$it" }
    )

    // Fallback: generic pool node0 … node9
    val pool = nodePools[server] ?: (0..9).map { "node$it" }

    val newNode = pool.firstOrNull { it !in triedNodes }

    // Re-run only if we have a fresh node to use
    var shouldRerun = newNode != null

    // For any status other than 'errored' or 'initializing' we never re-run
    if (jobServerStatus != "errored" && jobServerStatus != "initializing") {
        shouldRerun = false
        return Pair(null, false)
    }

    return Pair(newNode, shouldRerun)
};1

fun getKeyName(key: String): String {
