        if (key == "[") {
            key = getKey()
            if (key == "A") {
                key = "up"
            } else if (key == "B") {
                key = "down"
            } else if (key == "C") {
                key = "right"
            } else if (key == "D") {
                key = "left"
            } else {
                key = ""
            }
        } else if (key == "O") {
            key = getKey()
            if (key == "H") {
                key = "home"
            } else if (key == "F") {
                key = "end"
            } else {
                key = ""
            }
        } else {
            key = ""
        }
    } else if (key == "\u0003") {
        key = "break"
    } else if (key == "\b") {
        key = "backspace"
    } else if (key == "\t") {
        key = "tab"
    } else if (key == "\r") {
        key = "enter"
    } else if (key == " ") {
        key = "space"
    } else if (key == "\u007f") {
        key = "delete"
    }
    return key
};1

