fun countCoins(c: IntArray, m: Int, n: Int): Long {
    val table = LongArray(n + 1)
    table[0] = 1
    for (i in 0 until m)
        for (j in c[i]..n) table[j] += table[j - c[i]]
    return table[n]
}
 
