fun convexHull(points: List<Point>): List<Point> {
    points.sortWith(Comparator { a, b ->
        if (a.x == b.x) {
            a.y - b.y
        } else {
            a.x - b.x
        }
    })
    val L = ArrayList<Point>()
    for (i in 0 until points.size) {
        while (L.size >= 2 && cross(L[L.size - 2], L[L.size - 1], points[i]) <= 0) {
            L.removeAt(L.size - 1)
        }
        L.add(points[i])
    }
    val U = ArrayList<Point>()
    for (i in points.size - 1 downTo 0) {
        while (U.size >= 2 && cross(U[U.size - 2], U[U.size - 1], points[i]) <= 0) {
            U.removeAt(U.size - 1)
        }
        U.add(points[i])
    }
    L.removeAt(L.size - 1)
    U.removeAt(U.size - 1)
    return L + U
}
 
fun cross(a: Point, b: Point, o: Point): Int {
    return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x)
}
 
