val small = arrayOf("zero", "one", "two", "three", "four", "five", "six",
        "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen",
        "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen")
val tens = arrayOf("", "", "twenty", "thirty", "forty",
        "fifty", "sixty", "seventy", "eighty", "ninety")
val illions = arrayOf("", " thousand", " million", " billion",
        " trillion", " quadrillion", " quintillion")
 
fun say(n: Long): String {
    var t = ""
    if (n < 0) {
        t += "negative "
        // Note, for math.MinInt64 this leaves n negative.
        n = -n
    }
    when {
        n < 20 -> t += small[n.toInt()]
        n < 100 -> {
            t += tens[n.toInt() / 10]
            val s = n % 10
            if (s > 0) {
                t += "-" + small[s.toInt()]
            }
        }
        n < 1000 -> {
            t += small[n.toInt() / 100] + " hundred"
            val s = n % 100
            if (s > 0) {
                t += " " + say(s)
            }
        }
        else -> {
            // work right-to-left
            var sx = ""
            var i = 0
            while (n > 0) {
                val p = n % 1000
                n /= 1000
                if (p > 0) {
                    val ix = say(p) + illions[i]
                    if (sx!= "") {
                        ix += " " + sx
                    }
                    sx = ix
                }
                i++
            }
            t += sx
        }
    }
    return t
};1

fun findDirectoriesWithSizeFrom(
    itemsToProcess: List<FileSystemItem>,
    foundItems: MutableList<FileSystemItem>,
    minSize: Int
): List<FileSystemItem> {
    val directories = itemsToProcess.filterIsInstance<Directory>()
    if (directories.isEmpty()) {
        return foundItems
    }
    val firstDirectory = directories.first()
    val remainingDirectories =
        mutableListOf<FileSystemItem>(*directories.drop(1).toTypedArray()).apply {
            this.addAll(firstDirectory.content)
        }
    if (firstDirectory.size >= minSize) {
        foundItems.add(firstDirectory)
    }
    return findDirectoriesWithSizeFrom(remainingDirectories, foundItems, minSize)
};0

