import java.util.*
import java.util.concurrent.ConcurrentHashMap
import java.util.stream.IntStream

class SelfReferentialSequence {
    companion object {
        val cache = ConcurrentHashMap<String, Int>(10_000)
    }

    fun main(args: Array<String>) {
        val res = IntStream.range(0, 1000_000)
               .parallel()
               .mapToObj { n -> summarize(n, false) }
               .collect(Seeds(), { acc, s -> acc.accept(s) }, { acc, acc2 -> acc.combine(acc2) })

        println("Seeds:")
        res.seeds.forEach { e -> println(Arrays.toString(e)) }

        println("\nSequence:")
        summarize(res.seeds[0][0], true)
    }

    fun summarize(seed: Int, display: Boolean): IntArray {
        val n = seed.toString()

        val k = Arrays.toString(n.chars().sorted().toArray())
        if (!display && cache[k]!= null)
            return intArrayOf(seed, cache[k]!!)

        val seen = HashSet<String>()
        val sb = StringBuilder()

        val freq = IntArray(10)

        while (!seen.contains(n)) {
            seen.add(n)

            val len = n.length
            for (i in 0 until len)
                freq[n[i] - '0']++

            sb.setLength(0)
            for (i in 9 downTo 0) {
                if (freq[i]!= 0) {
                    sb.append(freq[i]).append(i)
                    freq[i] = 0
                }
            }
            if (display)
                println(n)
            n = sb.toString()
        }

        cache[k] = seen.size

        return intArrayOf(seed, seen.size)
    }

    class Seeds {
        var largest = Int.MIN_VALUE
        val seeds = ArrayList<IntArray>()

        fun accept(s: IntArray) {
            val size = s[1]
            if (size >= largest) {
                if (size > largest) {
                    largest = size
                    seeds.clear()
                }
                seeds.add(s)
            }
        }

        fun combine(acc: Seeds) {
            acc.seeds.forEach { this.accept(it) }
        }
    }
};1

