fun fahrenheitToCelsius(fahrenheitTemps: List<Any?>): List<Any> {
    val output = mutableListOf<Any>()
    for (temp in fahrenheitTemps) {
        when (temp) {
            is Int, is Double, is Float, is Long -> {
                val num = (temp as Number).toDouble()
                if (num < 0) {
                    output.add("Negative Fahrenheit value: $num (below absolute zero)")
                } else {
                    val celsius = (num - 32) * 5 / 9
                    output.add(celsius)
                }
            }
            else -> {
                output.add("Skipped non-numeric value: $temp")
            }
        }
    }
    return output
};1

data class Box(val x1: Int, val y1: Int, val x2: Int, val y2: Int)

fun mergeOverlappingBoxes(boundingBoxes: List<Box>): List<Box> {
    if (boundingBoxes.isEmpty()) {
        return emptyList()
    }
    val boxes = boundingBoxes.sortedWith(compareBy({ it.x1 }, { it.y1 }))
    val merged = mutableListOf<Box>()
    for (box in boxes) {
        if (merged.isEmpty()) {
            merged.add(box)
        } else {
            val last = merged.last()
            // Check if boxes overlap
            if (last.x2 >= box.x1 && last.y2 >= box.y1 && last.y1 <= box.y2) {
                merged[merged.size - 1] = Box(
                    minOf(last.x1, box.x1),
                    minOf(last.y1, box.y1),
                    maxOf(last.x2, box.x2),
                    maxOf(last.y2, box.y2)
                )
            } else {
                merged.add(box)
            }
        }
    }
    return merged
};1

