fun buildRegulationTree(text: String): List<Pair<String, List<String>>> {
    // Guard for completely empty input
    if (text.isEmpty()) {
        return emptyList()
    }

    // Split once: first line is the title, everything else is body
    val split = text.split('\n', limit = 2)
    val title = split[0]
    val body = if (split.size > 1) split[1] else ""

    // Regular expression for lines like "1.", "1.1.", "12.3.4." etc.
    // ^\s*        -> optional leading whitespace
    // \d+         -> one or more digits
    // (?:\.\d+)*  -> zero or more ".<digits>" groups
    // \.\s+       -> final dot followed by at least one whitespace
    val subsectionRe = Pattern.compile("^\\s*\\d+(?:\\.\\d+)*\\.\\s+")

    val subsections = mutableListOf<String>()
    for (line in body.lines()) {
        if (subsectionRe.matcher(line).find()) {
            subsections.add(line.trim())
        }
    }
    return listOf(Pair(title.trim(), subsections))
};1

fun manageDataset(uniqueName: Any?, datasetFormat: Any?, content: Any?, tags: Any?): Map<String, Any> {
    // Basic validation / normalisation
    if (uniqueName !is String || uniqueName.trim().isEmpty()) {
        throw IllegalArgumentException("unique_name must be a non-empty string")
    }
    if (datasetFormat !is String || datasetFormat.trim().isEmpty()) {
        throw IllegalArgumentException("dataset_format must be a non-empty string")
    }
    if (content !is String) {
        throw IllegalArgumentException("content must be a base64-encoded string")
    }

    // Ensure tags is a list (convert single tag to list if needed)
    val tagsList: List<String> = when (tags) {
        null -> emptyList()
        is String -> listOf(tags)
        is Iterable<*> -> tags.map {
            if (it is String) it else throw IllegalArgumentException("all tags must be strings")
        }
        else -> throw IllegalArgumentException("tags must be a list (or similar iterable) of strings")
    }

    val dataset = mapOf(
        "unique_name" to uniqueName,
        "format" to datasetFormat,
        "content" to content,
        "tags" to tagsList
    )
    val deletionMessage = "Dataset deleted successfully"
    return mapOf(
        "dataset" to dataset,
        "message" to deletionMessage
    )
};1

