            "one small step for man" in lowerSummary -> "'One small step for man, one giant leap for mankind.' Join Neil Armstrong on the moon in this defining moment of space exploration."
            "berlin wall" in lowerSummary && ("east" in lowerSummary || "west" in lowerSummary) -> "In 1989, the world watched as the Berlin Wall crumbled, uniting East and West Berlin in a historic moment that reshaped Europe."
            else -> summary.split(".").firstOrNull()?.trim().let { if (it.isNullOrEmpty()) "" else "$it." } ?: ""
        }
        val script = "Title: $title\nDate: $date\nLocation: $location\nScript: $scriptBody"
        scripts.add(script)
    }
    return scripts
