import java.util.Arrays
import java.util.concurrent.ExecutorService
import java.util.concurrent.Executors
import java.util.concurrent.Future
import java.util.stream.IntStream
import java.util.stream.Stream
import kotlin.math.min

object VogelsApproximationMethod {
    val demand = intArrayOf(30, 20, 70, 30, 60)
    val supply = intArrayOf(50, 60, 50, 50)
    val costs = arrayOf(
        intArrayOf(16, 16, 13, 22, 17),
        intArrayOf(14, 14, 13, 19, 15),
        intArrayOf(19, 19, 20, 23, 50),
        intArrayOf(50, 12, 50, 15, 11)
    )

    val nRows = supply.size
    val nCols = demand.size

    var rowDone = BooleanArray(nRows)
    var colDone = BooleanArray(nCols)
    var result = Array(nRows) { IntArray(nCols) }

    val es: ExecutorService = Executors.newFixedThreadPool(2)

    @JvmStatic
    fun main(args: Array<String>) {
        var supplyLeft = IntStream.of(*supply).sum()
        var totalCost = 0

        while (supplyLeft > 0) {
            val cell = nextCell()
            val r = cell[0]
            val c = cell[1]

            val quantity = min(demand[c], supply[r])
            demand[c] -= quantity
            if (demand[c] == 0)
                colDone[c] = true

            supply[r] -= quantity
            if (supply[r] == 0)
                rowDone[r] = true

            result[r][c] = quantity
            supplyLeft -= quantity

            totalCost += quantity * costs[r][c]
        }

        Stream.of(*result).forEach { a -> println(Arrays.toString(a)) }
        println("Total cost: $totalCost")

        es.shutdown()
    }

    fun nextCell(): IntArray {
        val f1: Future<IntArray> = es.submit { maxPenalty(nRows, nCols, true) }
        val f2: Future<IntArray> = es.submit { maxPenalty(nCols, nRows, false) }

        val res1 = f1.get()
        val res2 = f2.get()

        return if (res1[3] == res2[3])
            if (res1[2] < res2[2]) res1 else res2
        else if (res1[3] > res2[3]) res2 else res1
    }

    fun diff(j: Int, len: Int, isRow: Boolean): IntArray {
        var min1 = Int.MAX_VALUE
        var min2 = Int.MAX_VALUE
        var minP = -1
        for (i in 0 until len) {
            if (isRow && colDone[i] ||!isRow && rowDone[i])
                continue
            val c = if (isRow) costs[j][i] else costs[i][j]
            if (c < min1) {
                min2 = min1
                min1 = c
                minP = i
            } else if (c < min2)
                min2 = c
        }
        return intArrayOf(min2 - min1, min1, minP)
    };1

