fun containsDuplicatePairs(nums: List<Int>, k: Int): Boolean {
    val lastOccurrence = mutableMapOf<Int, Int>()
    val found = mutableSetOf<Int>()
    for ((i, num) in nums.withIndex()) {
        if (lastOccurrence.containsKey(num)) {
            if (i - lastOccurrence[num]!! <= k) {
                found.add(num)
                if (found.size >= 2) {
                    return true
                }
            }
        }
        lastOccurrence[num] = i
    }
    return false
};1

 
