    val zero = 0.0
    val one = 1.0
    val l = ludecomp(a, n, zero, one)
    lusolve(a, b, l, zero).forEach { println(it) }
}
 
fun ludecomp(a: Array<DoubleArray>, n: Int, zero: Double, one: Double): Array<DoubleArray> {
    val l = Array(n) { DoubleArray(n) }
    for (i in 0 until n) {
        for (j in 0 until n) {
            l[i][j] = zero
        }
    }
    for (i in 0 until n) {
        l[i][i] = one
    }
    for (j in 0 until n) {
        for (i in 0 until j) {
            var sum = zero
            for (k in 0 until i) {
                sum += l[i][k] * l[k][j]
            }
            l[i][j] = (a[i][j] - sum) / l[i][i]
        }
        for (i in j until n) {
            var sum = zero
            for (k in 0 until j) {
                sum += l[i][k] * l[k][j]
            }
            l[i][j] = a[i][j] - sum
        }
    }
    return l
}
 
fun lusolve(a: Array<DoubleArray>, b: DoubleArray, l: Array<DoubleArray>, zero: Double): DoubleArray {
    val n = b.size
    val x = DoubleArray(n)
    val y = DoubleArray(n)
    for (i in 0 until n) {
        var sum = zero
        for (k in 0 until i) {
            sum += l[i][k] * y[k]
        }
        y[i] = b[i] - sum
    }
    for (i in n - 1 downTo 0) {
        var sum = zero
        for (k in i + 1 until n) {
            sum += l[i][k] * x[k]
        }
        x[i] = (y[i] - sum) / l[i][i]
    }
    return x
};1

//defining a boolean function to check whether the number is happy number or not
fun Happynumber(number: Int): Boolean {
    var slow: Int
    var fast: Int

    fast = number
    slow = fast
    do {

        slow = squaredSum(slow)

        fast = squaredSum(squaredSum(fast))
    } while (slow != fast)

    return slow == 1
