fun main4B() {
  var lastGuard: String = "";
  var guards: MutableMap<String, MutableMap<Int, Int>> = mutableMapOf();
  File("input.txt")
    .readText(Charsets.UTF_8)
    .split("\n")
    .sorted()
    .map({ line: String -> run {
      var matchResult = Regex("\\s([0-9]+):([0-9]+)").find(line);
      var match = matchResult?.groupValues;
      var time: Int = 0;
      if ((match?.getOrNull(1)?.toIntOrNull() ?: 0) == 0) {
        time = match?.getOrNull(2)?.toIntOrNull() ?: 0;
      }
      var action: Int = 0;
      if (line.indexOf("begins shift") != -1) {
        lastGuard = Regex("Guard #([0-9]+)").find(line)?.groupValues?.getOrNull(1) ?: "";
      } else if (line.indexOf("falls asleep") != -1) {
        action = 1;
      } else if (line.indexOf("wakes up") != -1) {
        action = -1;
      }

      var guard = guards.getOrPut(lastGuard) { mutableMapOf() }
      for (i in time until 60) {
        guard.set(i, guard.getOrDefault(i, 0) + action);
      }
    }});

    var mostAsleep = MostAsleep(0, 0, "");
    guards.keys.forEach({ id -> run {
      var timetable = guards.getOrDefault(id, mutableMapOf()).toList().map { it.component2() };
      var time = timetable.max() ?: 0;
      if (time > mostAsleep.time) {
        val min = timetable.indexOf(time);
        mostAsleep = MostAsleep(time, min, id);
      }
    }});

    println(mostAsleep.id.toInt() * mostAsleep.min);
};0

 
import java.math.BigInteger
 
/* Separates each integer in the list with an 'a' then encodes in base 11. Empty list mapped to '-1' */
fun rank(li: List<Int>) = when (li.size) {
    0    -> -BigInteger.ONE
    else ->  BigInteger(li.joinToString("a"), 11)
}
 
fun unrank(r: BigInteger) = when (r) {
    -BigInteger.ONE -> emptyList<Int>()
    else            -> r.toString(11).split('a').map { if (it != "") it.toInt() else 0 }
}
 
 
/* Each integer n in the list mapped to '1' plus n '0's. Empty list mapped to '0' */
fun rank2(li:List<Int>): BigInteger {
    if (li.isEmpty()) return BigInteger.ZERO
    val sb = StringBuilder()
    for (i in li) sb.append("1" + "0".repeat(i))
    return BigInteger(sb.toString(), 2)
}
 
fun unrank2(r: BigInteger) = when (r) {
    BigInteger.ZERO -> emptyList<Int>()
    else            -> r.toString(2).drop(1).split('1').map { it.length }
}
 
fun main(args: Array<String>) {
    var li: List<Int>
    var r: BigInteger
    li = listOf(0, 1, 2, 3, 10, 100, 987654321)
    println("Before ranking   : $li")
    r = rank(li)
    println("Rank = $r")
    li = unrank(r)
    println("After unranking  : $li")
 
    println("\nAlternative approach (not suitable for large numbers)...\n")
    li = li.dropLast(1)
    println("Before ranking   : $li")
    r = rank2(li)
    println("Rank = $r")
    li = unrank2(r)
    println("After unranking  : $li")
 
    println()
    for (i in 0..10) {
        val bi = BigInteger.valueOf(i.toLong())
        li = unrank2(bi)
        println("${"%2d".format(i)} -> ${li.toString().padEnd(9)} -> ${rank2(li)}")
    }
};0

