const val LIMIT = 46  // to stay within range of signed 32 bit integer
val fibs = fibonacci(LIMIT)
 
fun fibonacci(n: Int): IntArray {
    if (n !in 2..LIMIT) throw IllegalArgumentException("n must be between 2 and $LIMIT")
    val fibs = IntArray(n)
    fibs[0] = 1
    fibs[1] = 1
    for (i in 2 until n) fibs[i] = fibs[i - 1] + fibs[i - 2]
    return fibs
}
 
fun zeckendorf(n: Int): String {
    if (n < 0) throw IllegalArgumentException("n must be non-negative")
    if (n < 2) return n.toString()
    var lastFibIndex = 1
    for (i in 2..LIMIT)
        if (fibs[i] > n) {
            lastFibIndex = i - 1
            break
        }
    var nn = n - fibs[lastFibIndex--]
    val zr = StringBuilder("1")
    for (i in lastFibIndex downTo 1)
        if (fibs[i] <= nn) {
            zr.append('1')
            nn -= fibs[i]
        } else {
            zr.append('0')
        }
    return zr.toString()
}
 
fun main(args: Array<String>) {
    println(" n   z")
    for (i in 0..20) println("${"%2d".format(i)} : ${zeckendorf(i)}")
};0

fun cleanContent(paragraphs: List<Any?>): String {
    val cleanedParts = mutableListOf<String>()
    for (part in paragraphs) {
        var text = part?.toString() ?: ""
        text = text.trim()
        // Collapse internal whitespace to single space
        text = text.replace(Regex("\\s+"), " ")
        if (text.isNotEmpty()) {
            cleanedParts.add(text)
        }
    }
    return cleanedParts.joinToString(" ")
}

fun standardizeDate(rawIn: Any?): String? {
    val raw = rawIn?.toString()?.trim() ?: return null
    if (raw == "Unknown") return null
    val prefix = "Published on "
    val dateStr = if (raw.startsWith(prefix)) raw.removePrefix(prefix).trim() else raw
    val pattern = Pattern.compile("\\d{4}-\\d{2}-\\d{2}")
    return if (pattern.matcher(dateStr).matches()) dateStr else null
}

fun processArticles(articles: List<Map<String, Any?>>): List<Map<String, Any?>> {
    val result = mutableListOf<Map<String, Any?>>()
    for (article in articles) {
        val title = article["title"]?.toString() ?: ""
        val stdDate = standardizeDate(article["publication_date"])
        val rawContent = article["content"]
        val contentList = when (rawContent) {
            is List<*> -> rawContent
            null -> emptyList<Any?>()
            else -> listOf(rawContent)
        }
        val cleanedContent = cleanContent(contentList)
        result.add(mapOf(
            "title" to title,
            "publication_date" to stdDate,
            "content" to cleanedContent
        ))
    }
    return result
};1

/**
 * Uses a 2 pointer approach to merge to sorted arrays.
 * The first pointer i points to the last element of the subarray of size m in the nums1 array,
 * the second pointer j points to the last element of the nums2 array of size n.
 * The pointer k points to the end of the array nums1 of size m + n.
 *
 * Until the pointer j reaches 0 (that is, until we reach the beginning of the nums2 array), we check the following
 * conditions:
 *
 * - If the pointer i < 0 (i.e. we have reached the beginning of the nums1 array) OR nums1[i] < nums2[j] =>
 *     write nums2[j] to nums1[k] and then decrease the value of j and k by 1
 * - In all other cases, write nums1[i] to nums1[k] and then decrease the value of i and k by 1
 *
 * Complexity
 * Time complexity: O(n+m)
 * Space complexity: O(1)
 */
fun merge(nums1: IntArray, m: Int, nums2: IntArray, n: Int) {
    var i = m - 1
    var j = n - 1
    var k = m + n - 1

    while (j >= 0) {
        nums1[k--] = if (i < 0 || nums1[i] < nums2[j]) {
            nums2[j--]
        } else {
            nums1[i--]
        }
    }
};0

