fun rotateList(l: List<Int>, n: Int): List<Int> {
    if (l.isEmpty()) {
        return emptyList()
    }
    val m = if (l.isNotEmpty()) (n % l.size + l.size) % l.size else 0
    if (m == 0) {
        return l.toList()
    }
    return l.takeLast(m) + l.dropLast(m)
};1

fun insertWords(words: List<String>): Set<String> {
    /**
     * Inserts each word from the given list into a catalogue-like
     * collection while ensuring only unique words are stored.
     *
     * @param words A non-empty list of strings to add to the catalogue.
     * @return A set containing all distinct words that were inserted.
     */
    // Using a set automatically removes duplicates.
    val catalogue = mutableSetOf<String>()
    for (word in words) {
        catalogue.add(word)
    }
    return catalogue
};1

 
