import kotlin.random.Random
 
/**
 * 1. Cards
 */
val n = 52
val Black = "Black"
val Red = "Red"
val blacks = List(n / 2) { Black }
val reds = List(n / 2) { Red }
val pack = blacks + reds
// Give the pack a good shuffle.
pack.shuffle()
 
/**
 * 2. Deal from the randomised pack into three stacks
 */
val blackStack = mutableListOf<String>()
val redStack = mutableListOf<String>()
val discard = mutableListOf<String>()
while (pack.isNotEmpty()) {
    val top = pack.removeLast()
    if (top == Black) {
        blackStack.add(pack.removeLast())
    } else {
        redStack.add(pack.removeLast())
    }
    discard.add(top)
}
println("(Discards: ${discard.joinToString(" ") { it[0].toString() }})")
 
/**
 * 3. Swap the same, random, number of cards between the two stacks.
 */
// We can't swap more than the number of cards in a stack.
val maxSwaps = minOf(blackStack.size, redStack.size)
// Randomly choose the number of cards to swap.
val swapCount = Random.nextInt(0, maxSwaps)
println("Swapping $swapCount")
// Randomly choose that number of cards out of each stack to swap.
fun <T> randomPartition(stack: MutableList<T>, count: Int): Pair<MutableList<T>, MutableList<T>> {
    val sample = stack.shuffled().take(count)
    val rest = stack.toMutableList()
    for (card in sample) {
        rest.remove(card)
    }
    return rest to sample
}
 
val (blackStack, blackSwap) = randomPartition(blackStack, swapCount)
val (redStack, redSwap) = randomPartition(redStack, swapCount)
 
// Perform the swap.
blackStack += redSwap
redStack += blackSwap
 
/**
 * 4. Order from randomness?
 */
if (blackStack.count { it == Black } == redStack.count { it == Red }) {
    println("Yeha! The mathematicians assertion is correct.")
} else {
    println("Whoops - The mathematicians (or my card manipulations) are flakey")
};1

