fun canPartition(numbers: List<Int>): Boolean {
    val totalSum = numbers.sum()
    if (totalSum % 2 != 0) {
        return false
    }
    val targetSum = totalSum / 2
    var dp = mutableSetOf(0)
    for (num in numbers) {
        val nextDp = mutableSetOf<Int>()
        nextDp.addAll(dp)
        for (currSum in dp) {
            nextDp.add(currSum + num)
        }
        dp = nextDp
    }
    return dp.contains(targetSum)
};1

