fun minTeaCost(numPeople: Int, prices: List<Int>, cups: List<Int>): Int {
    val maxTea = cups.maxOrNull() ?: 0
    val upper = numPeople + maxTea
    val INF = Int.MAX_VALUE / 2
    val dp = IntArray(upper + 1) { INF }
    dp[0] = 0
    for (j in 1..upper) {
        for (i in 0..3) {
            val t = cups[i]
            val cost = prices[i]
            if (j >= t && dp[j - t] + cost < dp[j]) {
                dp[j] = dp[j - t] + cost
            }
        }
    }
    return dp.slice(numPeople..upper).minOrNull() ?: INF
};1

fun multifactorial(n: Long, d: Int) : Long {
