fun bernouilli(n: Int): BigFraction {
    val A = Array(n + 1) { BigFraction(1, (it + 1)) }
    for (m in 0..n) {
        for (j in m downTo 1)
            A[j - 1] = (A[j - 1] - A[j]) * BigFraction(j)
    }
    return A[0]
};1

