fun prime(n: Int): Boolean {
    if (n < 5) return n == 3 || n == 2
    if (n.gcd(6)!= 1) return false
    val sqrtN = kotlin.math.sqrt(n.toDouble()).toInt()
    var pc = -1
    while (pc += 6 <= sqrtN) {
        if (n % pc == 0 || n % (pc + 2) == 0) return false
    }
    return true
}
 
fun genPrimes(a: Int, b: Int): List<Int> {
    return (a..b).filter { prime(it) }
}
 
fun nsmooth(n: Int, limit: Int): List<Int> {
    if (n < 2 || n > 521 || limit < 1) throw Exception("Exception(n or limit)")
    if (!prime(n)) throw Exception("Exception(must be a prime number: n)")
 
    val primes = genPrimes(2, n)
    val ns = MutableList(limit) { 0 }
    ns[0] = 1
    val nextp = primes.subList(0, primes.indexOf(n) + 1)
 
    val indices = MutableList(nextp.size) { 0 }
    for (m in 1 until limit) {
        ns[m] = nextp.min()!!
        for (i in 0 until indices.size) {
            if (ns[m] == nextp[i]) {
                indices[i] += 1
                nextp[i] = primes[i] * ns[indices[i]]
            }
        }
    }
    return ns
}
 
