    println("c = a + b = $c")
    println("d = -c    = $d")
    println("c + d     = ${c + d}")
    println("a + b + d = ${a + b + d}")
    println("a * 12345 = ${a * 12345}")
};0

class Complex(val real: Double, val imag: Double) {
    constructor() : this(0.0, 0.0)

    fun add(b: Complex) = Complex(real + b.real, imag + b.imag)

    fun mult(b: Complex) = Complex(real * b.real - imag * b.imag, real * b.imag + imag * b.real)

    fun inv() = Complex(real / (real * real + imag * imag), -imag / (real * real + imag * imag))

    fun neg() = Complex(-real, -imag)

    fun conj() = Complex(real, -imag)

    fun toString() = "$real + $imag * i"

    companion object {
        @JvmStatic
        fun main(args: Array<String>) {
            val a = Complex(Math.PI, -5.0)
            val b = Complex(-1.0, 2.5)
            println(a.neg())
            println(a.add(b))
            println(a.inv())
            println(a.mult(b))
            println(a.conj())
        }
    }
};1

