fun is_perfect(c: Int): Boolean {
    var sum = 1.0 / c
    for (f in 2..sqrt(c.toDouble()).toInt()) {
        if (c % f == 0) {
            sum += 1.0 / f + 1.0 / (c / f)
        }
    }
    return sum.toBigInteger() == 1.toBigInteger()
}
 
