fun isHarshad(n: Int): Boolean {
    val inputChars = n.toString().toCharArray()
    val digits = ArrayList<Byte>()
 
    for (digit in inputChars) {
        digits.add(digit.toByte())
    }
 
    if (n < 1) {
        return false
    }
 
    var sum = 0
 
    for (digit in digits) {
        sum += digit.toInt()
    }
 
    return n % sum == 0
}
 
