fun insertionSort(arr: List<Int>): List<Int> {
    /**
     * Sorts a list of integers in ascending order using the insertion sort algorithm.
     *
     * Parameters:
     * arr (List<Int>): The list of integers to sort.
     *
     * Returns:
     * List<Int>: A new list containing the sorted integers.
     */
    val sortedArr = arr.toMutableList() // Make a copy so the original list remains unmodified

    // Perform insertion sort
    for (i in 1 until sortedArr.size) {
        val key = sortedArr[i] // The current element to insert
        var j = i - 1

        // Shift elements of the sorted part that are greater than `key` one position to the right
        while (j >= 0 && sortedArr[j] > key) {
            sortedArr[j + 1] = sortedArr[j]
            j--
        }

        // Place the key in its correct location
        sortedArr[j + 1] = key
    }
    return sortedArr
};1

