fun maximalRectangle(matrix: List<List<String>>): Int {
    fun maxValidArea(heights: List<Int>): Int {
        val stack = mutableListOf<Int>()
        var maxArea = 0
        val newHeights = mutableListOf(0)
        newHeights.addAll(heights)
        newHeights.add(0)
        for (i in newHeights.indices) {
            while (stack.isNotEmpty() && newHeights[i] < newHeights[stack.last()]) {
                val h = newHeights[stack.removeAt(stack.size - 1)]
                val left = stack.last()
                val w = i - left - 1
                if (h >= 2 && w >= 2) {
                    val currentArea = h * w
                    if (currentArea > maxArea) {
                        maxArea = currentArea
                    }
                }
            }
            stack.add(i)
        }
        return maxArea
    }
    if (matrix.isEmpty() || matrix[0].isEmpty()) return 0
    val rows = matrix.size
    val cols = matrix[0].size
    var maxSum = 0
    val heights = MutableList(cols) { 0 }
    for (row in matrix) {
        for (j in 0 until cols) {
            if (row[j] == "1") {
                heights[j] += 1
            } else {
                heights[j] = 0
            }
        }
        val currentMax = maxValidArea(heights.toList())
        if (currentMax > maxSum) {
            maxSum = currentMax
        }
    }
    return maxSum
};1

fun getStorageObjectIdsEbs(domain: String, username: String, password: String, tag: String): List<String> {
