        mapOf("id" to "vol-1a2b3c4d5e6f7g8h9", "tags" to listOf("staging", "web")),
        mapOf("id" to "vol-2a3b4c5d6e7f8g9h0", "tags" to listOf("development", "test")),
        mapOf("id" to "vol-3a4b5c6d7e8f9g0h1", "tags" to listOf("backup", "production")),
        mapOf("id" to "vol-4a5b6c7d8e9f0g1h2", "tags" to listOf("archive", "compliance")),
        mapOf("id" to "vol-5a6b7c8d9e0f1g2h3", "tags" to emptyList<String>())
