fun MutableList<Monkey>.solution(rep: Int, worryDivider: Int): Long {
    val mod = map { it.div }.reduce(Int::times)
    repeat(rep) {
        forEach { monkey: Monkey ->
            repeat(monkey.worryLevel.size) {
                monkey.inspectCount++
                val worry = monkey.worryLevel.removeFirst()
                val oppNumber = monkey.oppNumber?.toLong() ?: worry
                val result = when (monkey.oppSign) {
                    '+' -> worry + oppNumber
                    '-' -> worry - oppNumber
                    '*' -> worry * oppNumber
                    '/' -> worry / oppNumber
                    else -> throw IllegalArgumentException()
                } / worryDivider % mod
                if (result.rem(monkey.div) == 0L) {
                    get(monkey.ifTrueMonkeyNum).apply { worryLevel += result }
                } else {
                    get(monkey.ifFalseMonkeyNum).apply { worryLevel += result }
                }
            }
        }
    }
    return sortedByDescending { it.inspectCount }.take(2).let { (a, b) -> a.inspectCount * b.inspectCount }
};0

fun String.toDigits() = mapIndexed { i, c ->
    if (!c.isDigit())
        throw IllegalArgumentException("Invalid digit $c found at position $i")
    c - '0'
}.reversed()
 
operator fun String.times(n: String): String {
    val left = toDigits()
    val right = n.toDigits()
    val result = IntArray(left.size + right.size)
 
    right.mapIndexed { rightPos, rightDigit ->
        var tmp = 0
        left.indices.forEach { leftPos ->
            tmp += result[leftPos + rightPos] + rightDigit * left[leftPos]
            result[leftPos + rightPos] = tmp % 10
            tmp /= 10
        }
        var destPos = rightPos + left.size
        while (tmp != 0) {
            tmp += (result[destPos].toLong() and 0xFFFFFFFFL).toInt()
            result[destPos] = tmp % 10
            tmp /= 10
            destPos++
        }
    }
 
    return result.foldRight(StringBuilder(result.size), { digit, sb ->
        if (digit != 0 || sb.length > 0) sb.append('0' + digit)
        sb
    }).toString()
}
 
