fun Rope(length: Int, x: Int = 0, y: Int = 0): Rope {
  val rope: MutableList<Knot> = mutableListOf()
  for (i in length - 1 downTo 0) {
    rope += Knot(i, x, y, next = rope.lastOrNull())
  }
  return rope.reversed()
