fun powers(m: Int): Stream<Long> {
    return Stream.iterate(0L) { x -> x + 1 }.map { x -> x.toDouble().pow(m).toLong() }
}
 
fun noncubicSquares(): Iterator<Long> {
    return NoncubicSquares(powers(2).iterator(), powers(3).iterator())
}
 
class NoncubicSquares(private val squares: Iterator<Long>, private val cubes: Iterator<Long>) : Iterator<Long> {
    fun hasNext(): Boolean {
        return true
    }
 
    fun next(): Long {
        while (true) {
            when {
                squares.peek() == cubes.peek() -> return squares.next()
                squares.peek() < cubes.peek() -> return squares.next()
                else -> cubes.next()
            }
        }
    }
 
    fun <T> Iterator<T>.peek(): T? {
        return if (hasNext()) next() else null
    }
}
 
