fun solve() {
    val n = readInt()
    val nei = List(n) { mutableListOf<Edge>() }
    repeat(n - 1) {
        val (aInput, bInput, value) = readInts()
        val a = aInput - 1
        val b = bInput - 1
        nei[a].add(Edge(a, b, value))
        nei[b].add(Edge(b, a, value))
    }
    if (nei.any { it.size == 2 }) {
        println("NO")
        return
    }
    println("YES")
    val ans = nei.flatten().filter { it.from < it.to }.flatMap { edge ->
        val a = dfs(edge.from, edge.to, false, nei)
        val b = dfs(edge.from, edge.to, true, nei)
        val c = dfs(edge.to, edge.from, false, nei)
        val d = dfs(edge.to, edge.from, true, nei)
        val halfValue = edge.value / 2
        listOf(
                Edge(a, c, halfValue),
                Edge(b, d, halfValue),
                Edge(a, b, -halfValue),
                Edge(c, d, -halfValue)
        ).filter { it.from != it.to }
    }
    println(ans.size)
    for (edge in ans) {
        println("${edge.from + 1} ${edge.to + 1} ${edge.value}")
    }
};0

fun maxValue(events: List<List<Int>>): Int {
    if (events.isEmpty()) return 0

    // Sort events by their ending day to facilitate binary search
    val sortedEvents = events.sortedBy { it[1] }
    val ends = sortedEvents.map { it[1] }
    val n = sortedEvents.size
    val dp = IntArray(n)
    for (i in sortedEvents.indices) {
        val (s, e, v) = sortedEvents[i]
        // Find rightmost event that ends strictly before current event starts
        val j = ends.binarySearch(s).let { if (it < 0) -(it + 1) - 1 else it - 1 }
        val bestWithCurrent = v + if (j >= 0) dp[j] else 0
        val bestWithoutCurrent = if (i > 0) dp[i-1] else 0
        dp[i] = maxOf(bestWithCurrent, bestWithoutCurrent)
    }
    return dp.last()
};1

fun perfectPlay(n: Int, heap: List<Int>): String {
    // Compute the nim-sum (xor of all heap sizes)
    var nimSum = 0
    for (stones in heap) {
        nimSum = nimSum xor stones
    }
    // If nim-sum is zero, the current player is in a losing position
    if (nimSum == 0) {
        return "Player who plays first will lose in a perfect gameplay."
    }
    // Otherwise, find a heap to reduce so that nim-sum becomes zero
    for ((i, stones) in heap.withIndex()) {
        val targetSize = stones xor nimSum
        if (targetSize < stones) {
            val stonesToRemove = stones - targetSize
            val heapIndex = i + 1
            return "Player who plays first should remove $stonesToRemove from heap $heapIndex to win."
        }
    }
    // This line should theoretically never be reached
    return "Player who plays first will lose in a perfect gameplay."
};1

