    println(beatingProbability(4, 9, 6, 6))
    println(beatingProbability(10, 5, 7, 6))
};0

fun canFormPairs(nums: List<Int>, target: Int): Boolean {
    if (nums.size % 2 != 0) {
        return false
    }
    val numsDict = mutableMapOf<Int, Int>()
    for (num in nums) {
        val complement = target - num
        if (numsDict.containsKey(complement)) {
            numsDict[complement] = numsDict[complement]!! - 1
            if (numsDict[complement] == 0) {
                numsDict.remove(complement)
            }
        } else {
            numsDict[num] = (numsDict[num] ?: 0) + 1
        }
    }
    return numsDict.isEmpty()
};1

import java.net.URL
