class YahooSearch(query: String, page: Int) {
    private val query: String
    private val content: String
    private val page: Int
 
    private val yahoo = "http://search.yahoo.com/search?"
 
    init {
        this.query = query
        this.page = page
        this.content = URL(String.format(yahoo + "p=%s&b=%s", query, this.page * 10 + 1)).readText()
    }
 
    val results: Array<YahooResult>
        get() {
            val results = ArrayList<YahooResult>()
 
            fun substringBefore(str: String, before: String): String {
                val iHref = str.indexOf(before)
                return if (iHref < 0) "" else str.substring(0, iHref)
            }
 
            fun substringAfter(str: String, after: String): String {
                val iHref = str.indexOf(after)
                return if (iHref < 0) "" else str.substring(iHref + after.length)
            }
 
            fun getText(p: String): String {
                return p.replace("<[^>]*>".toRegex(), "")
            }
 
            val rx = Pattern.compile(
                    """<li>
                        <div \s class="res">
                            <div>
                                <h3>
                                    <a \s (?'LinkAttributes'[^>]+)>
                                        (?'LinkText'.*?)
                                    (?></a>)
                                </h3>
                            </div>
                            <div \s class="abstr">
                                (?'Abstract'.*?)
                            (?></div>)
                           .*?
                        (?></div>)
                    </li>""",
                    Pattern.MULTILINE or Pattern.DOTALL or Pattern.COMMENTS)
            val matcher = rx.matcher(this.content)
            while (matcher.find()) {
                val rurl = getText(substringBefore(substringAfter(matcher.group("LinkAttributes"), "href=\""), "\""))
                val rtitle = getText(matcher.group("LinkText"))
                val rcontent = getText(matcher.group("Abstract"))
 
                results.add(YahooResult(rurl, rtitle, rcontent))
            }
            return results.toTypedArray()
        }
 
    fun nextPage(): YahooSearch {
        return YahooSearch(this.query, this.page + 1)
    }
 
    fun getPage(page: Int): YahooSearch {
        return YahooSearch(this.query, page)
    }
};1

 
