fun bestShuffle(s: String): Pair<String, Int> {
    // Fill _pos_ with positions in the order
    // that we want to fill them.
    val pos = mutableListOf<Int>()
    // g["a"] = [2, 4] implies that s[2] == s[4] == "a"
    val g = s.indices.groupBy { s[it] }

    // k sorts letters from low to high count
    val k = g.toList().sortedBy { it.second.size }.map { it.first }

    while (g.isNotEmpty()) {
        k.forEach { letter ->
            g[letter]?: return@forEach
            pos.add(g[letter]!!.removeAt(g[letter]!!.lastIndex))
            if (g[letter]!!.isEmpty()) g.remove(letter)
        }
    }

    // Now fill in _new_ with _letters_ according to each position
    // in _pos_, but skip ahead in _letters_ if we can avoid
    // matching characters that way.
    val letters = s.toMutableList()
    val new = MutableList(s.length) { '?' }
    while (letters.isNotEmpty()) {
        var i = 0
        val p = pos.removeAt(pos.lastIndex)
        while (letters[i] == s[p] && i < letters.lastIndex) i++
        new[p] = letters.removeAt(i)
    }

    val score = new.zip(s.toList()).count { it.first == it.second }
    return Pair(new.joinToString(""), score)
}

fun main(args: Array<String>) {
    listOf("abracadabra", "seesaw", "elk", "grrrrrr", "up", "a").forEach { word ->
        val (new, score) = bestShuffle(word)
        println("$word, $new, ($score)")
    }
};1

