// written for clarity not efficiency.
 
import java.util.ArrayDeque
 
class Subtractive_generator(seed: Int) {
    private val param_i = 55
    private val param_j = 24
    private val initial_load = 219
    private val mod = 1e9.toInt()
    private val r = ArrayDeque<Int>()
 
    init {
        val s = IntArray(param_i)
        s[0] = seed
        s[1] = 1
        for (n in 2 until param_i) {
            var t = s[n - 2] - s[n - 1]
            if (t < 0) t += mod
            s[n] = t
        }
 
        for (n in 0 until param_i) {
            val i = (34 * (n + 1)) % param_i
            r.add(s[i])
        }
        for (n in param_i..initial_load) next()
    }
 
    fun next(): Int {
        var t = r[0] - r[31]
        if (t < 0) t += mod
        r.add(t)
        return r[param_i - 1]
    }
 
    operator fun invoke(): Int = next()
}
 
