import kotlin.math.abs
import kotlin.math.sqrt
 
fun main(args: Array<String>) {
    println(arithmeticGeometricMean(1.0, 0.5 * sqrt(2.0), RelativeDifferenceComparer(1e-5)).toString())
}
 
fun arithmeticGeometricMean(number: Double, otherNumber: Double, comparer: Comparator<Double>): Double {
    return if (comparer.compare(number, otherNumber) == 0) {
        number
    } else {
        arithmeticGeometricMean(arithmeticMean(number, otherNumber), geometricMean(number, otherNumber), comparer)
    }
}
 
fun arithmeticMean(number: Double, otherNumber: Double): Double {
    return 0.5 * (number + otherNumber)
}
 
fun geometricMean(number: Double, otherNumber: Double): Double {
    return sqrt(number * otherNumber)
}
 
class RelativeDifferenceComparer(private val maximumRelativeDifference: Double) : Comparator<Double> {
    fun compare(number: Double, otherNumber: Double): Int {
        return if (relativeDifference(number, otherNumber) <= maximumRelativeDifference) {
            0
        } else {
            1
        }
    }
 
    fun relativeDifference(number: Double, otherNumber: Double): Double {
        return absoluteDifference(number, otherNumber) / norm(number, otherNumber)
    }
 
    fun absoluteDifference(number: Double, otherNumber: Double): Double {
        return abs(number - otherNumber)
    }
 
    fun norm(number: Double, otherNumber: Double): Double {
        return 0.5 * (abs(number) + abs(otherNumber))
    }
};1

