fun validateSegments(segments: List<List<String>>): Boolean {
    // Grunnleggende sjekk: må ha minst 3 segmenter
    if (segments.size < 3) {
        return false
    }
    // Hjelpemetode for å hente taggen til et segment (kan være tomt)
    fun tag(segment: List<String>): String = if (segment.isNotEmpty()) segment[0] else ""

    // Sjekk obligatoriske posisjoner
    if (tag(segments[0]) != "UNH") {
        return false
    }
    if (tag(segments[1]) != "BGM") {
        return false
    }
    if (tag(segments[segments.lastIndex]) != "UNT") {
        return false
    }
    return true
};1

fun parseMove(s: String): List<Direction> {
    val (directionChar, numberOfMoves) = s.split(' ')
    val direction = when (directionChar) {
        "U" -> Direction.UP
        "L" -> Direction.LEFT
        "D" -> Direction.DOWN
        "R" -> Direction.RIGHT
        else -> throw IllegalArgumentException("Invalid move code, cannot parse direction: $s.")
    }

    return List(numberOfMoves.toInt()) { direction }
