    var coldestIndex = 0
    var warmestIndex = 0
    for (i in temperatures.indices) {
        if (temperatures[i] < temperatures[coldestIndex]) {
            coldestIndex = i
        } else if (temperatures[i] > temperatures[warmestIndex]) {
