import java.io.File
import java.io.IOException
import java.io.RandomAccessFile
import java.nio.channels.FileChannel
import java.nio.channels.FileLock
import java.nio.channels.OverlappingFileLockException
import java.nio.file.Files
import java.nio.file.Paths
import java.nio.file.StandardOpenOption
import java.util.Scanner
 
fun main(args: Array<String>) {
    if (args.size!= 3) {
        System.err.println("Usage: ${args[0]} <file> <start> <count>")
        System.exit(1)
    }
 
    val count = args[2].toInt()
    if (count < 1) {
        // We're a no-op.
        return
    }
 
    val start = args[1].toInt()
    if (start < 1) {
        System.err.println("Error: <start> ($start) must be positive")
        System.exit(1)
    }
 
    val file = File(args[0])
    if (!file.exists()) {
        System.err.println("No such file: ${args[0]}")
        System.exit(1)
    }
 
    val lines = countLines(file)
    if (start + count > lines) {
        System.err.println("Error: invalid parameters for file with $lines lines")
        System.exit(1)
    }
 
    val dest = getLineOffset(file, start)
    val src = getLineOffset(file, start + count)
 
    val buf = ByteArray(src - dest)
    val raf = RandomAccessFile(file, "rw")
    val fc = raf.channel
    val lock: FileLock
    try {
        lock = fc.lock()
    } catch (e: OverlappingFileLockException) {
        System.err.println("Error: file is locked")
        System.exit(1)
    }
 
    fc.position(dest)
    fc.read(buf)
    fc.position(dest)
    fc.write(fc.map(FileChannel.MapMode.READ_WRITE, src, fc.size() - src))
    fc.position(dest)
    fc.write(buf)
    lock.release()
    raf.close()
}
 
fun countLines(file: File): Int {
    var lines = 0
    val scanner = Scanner(file)
    while (scanner.hasNextLine()) {
        scanner.nextLine()
        lines++
    }
    scanner.close()
    return lines
}
 
fun getLineOffset(file: File, line: Int): Long {
    var offset = 0L
    val scanner = Scanner(file)
    for (i in 1..line) {
        offset = scanner.nextLine().length + 1
    }
    scanner.close()
    return offset
};1

