fun maxProfit(prices: IntArray): Int {
    var left = 0
    var right = 1
    var max = Int.MIN_VALUE
    while (left < prices.size - 1){
        if (prices[right] - prices[right] <= 0){
            left = right
            right++
        }
        else {
            val sp = prices[right] - prices[left]
            max = maxOf(max, sp)
            right++
        }
    }
    return max
};0

