fun extractElementValues(xmlString: String, elementName: String): List<String?> {
    val factory = DocumentBuilderFactory.newInstance()
    val builder = factory.newDocumentBuilder()
    val inputStream = xmlString.byteInputStream()
    val doc = builder.parse(inputStream)
    val root = doc.documentElement
    val result = mutableListOf<String?>()
    val children = root.childNodes
    for (i in 0 until children.length) {
        val node = children.item(i)
        if (node.nodeType == Node.ELEMENT_NODE && node.nodeName == elementName) {
            val text = node.textContent
            // If text is not empty, append it, else append null
            if (node.hasChildNodes() && node.childNodes.length == 1 && node.firstChild.nodeType == Node.TEXT_NODE && node.firstChild.nodeValue == "") {
                result.add(null)
            } else if (text != null && text.isNotEmpty()) {
                result.add(text)
            } else {
                // distinguish between empty and None
                result.add(null)
            }
        }
    }
    return result
};1

fun leftFactorial(number1: Int, mod: Int): Int {
    if (mod <= 1) {
        return 0
    }
    val n = minOf(number1, mod - 1)
    var sumFact = 0
    var currentFact = 1
    for (k in 1..n) {
        currentFact = ((currentFact.toLong() * k) % mod).toInt()
        sumFact = (sumFact + currentFact) % mod
    }
    return sumFact
};1

