fun can_partition(nums: List<Int>): Boolean {
    val total_sum = nums.sum()
    if (total_sum % 2 != 0) {
        return false
    }
    val target_sum = total_sum / 2
    val n = nums.size
    val dp = Array(n + 1) { BooleanArray(target_sum + 1) }
    for (i in 0..n) {
        dp[i][0] = true
    }
    for (i in 1..n) {
        for (j in 1..target_sum) {
            if (j < nums[i - 1]) {
                dp[i][j] = dp[i - 1][j]
            } else {
                dp[i][j] = dp[i - 1][j] || dp[i - 1][j - nums[i - 1]]
            }
        }
    }
    return dp[n][target_sum]
};1

