fun buildHttpsLink(
    subDomain: String,
    domain: String,
    path: String,
    queryParams: Map<String, String?>,
    hashVal: String = ""
): String {
    if (domain.isEmpty()) {
        throw IllegalArgumentException("The main domain must be provided.")
    }

    // ----- Authority / host -----
    // Clean up any stray dots provided by the caller.
    val authorityParts = mutableListOf<String>()
    if (subDomain.isNotEmpty()) {
        authorityParts.add(subDomain.trim('.'))
    }
    authorityParts.add(domain.trimStart('.'))
    val authority = authorityParts.joinToString(".")

    // ----- Path -----
    val encodedPath = if (path.isNotEmpty()) {
        val normalizedPath = if (path.startsWith("/")) path else "/$path"
        // URL encode the path, but leave slashes unencoded
        normalizedPath.split("/")
            .joinToString("/") { part ->
                if (part.isNotEmpty()) URLEncoder.encode(part, StandardCharsets.UTF_8.toString()) else ""
            }.let { "/${it.trimStart('/')}" }
    } else {
        ""
    }

    // ----- Query string -----
    val queryString = if (queryParams.isNotEmpty()) {
        val safeQs = queryParams.map { (k, v) ->
            URLEncoder.encode(k, StandardCharsets.UTF_8.toString()) +
                    "=" +
                    URLEncoder.encode(v ?: "", StandardCharsets.UTF_8.toString())
        }.joinToString("&")
        "?$safeQs"
    } else {
        ""
    }

    // ----- Fragment / hash -----
    val fragment = if (hashVal.isNotEmpty()) {
        "#" + URLEncoder.encode(hashVal.trimStart('#'), StandardCharsets.UTF_8.toString())
    } else {
        ""
    }

    // ----- Assemble the URL -----
    return "https://$authority$encodedPath$queryString$fragment"
};1

