import kotlin.math.min
 
class Vigenere(private val key: String) {
 
    fun encrypt(text: String): String {
        val out = StringBuilder()
 
        for (i in text.indices) {
            val c = text[i]
 
            if (c in 'a'..'z') {
                out.append((c + key[i % key.length] - 2 * 'A') % 26 + 'A')
            } else if (c in 'A'..'Z') {
                out.append(c)
            }
        }
 
        return out.toString()
    }
 
    fun decrypt(text: String): String {
        val out = StringBuilder()
 
        for (i in text.indices) {
            val c = text[i]
 
            if (c in 'a'..'z') {
                out.append((c - key[i % key.length] + 26) % 26 + 'A')
            } else if (c in 'A'..'Z') {
                out.append(c)
            }
        }
 
        return out.toString()
    }
}
 
fun main() {
    val cipher = Vigenere("VIGENERECIPHER")
 
    val original = "Beware the Jabberwock, my son! The jaws that bite, the claws that catch!"
    val encrypted = cipher.encrypt(original)
    val decrypted = cipher.decrypt(encrypted)
 
    println(original)
    println("Encrypted: $encrypted")
    println("Decrypted: $decrypted")
};1

