fun List<Double>.smooth7(iterations: Int = 1): List<Double> {
    require(iterations >= 1)

    val kernel = mapOf(
        -3 to .006,
        -2 to .061,
        -1 to .242,
        0 to .382,
        1 to .242,
        2 to .061,
        3 to .006
    )

    val source = if (iterations > 1) {
        this.smooth7(iterations - 1)
    } else {
        this
    }

    return source.indices.map { idx ->
        kernel.map { (k, v) ->
            val offset = if (idx + k in source.indices) {
                idx + k
            } else {
                idx + -k
            }
            source[offset] * v
        }.sum()
    }
};0

