fun reverseString(s: String): String {
    val chars = s.toCharArray()
    var left = 0
    var right = chars.size - 1
    while (left < right) {
        val temp = chars[left]
        chars[left] = chars[right]
        chars[right] = temp
        left++
        right--
    }
    var result = ""
    for (char in chars) {
        result += char
    }
    return result
};1

fun findPatterns(pattern: String, s: String, sId: Int): List<Map<String, Any>> {
    val matches = mutableListOf<Map<String, Any>>()
    val regex: Pattern
    try {
        regex = Pattern.compile(pattern)
    } catch (e: PatternSyntaxException) {
        return listOf(mapOf("error" to "Invalid pattern: ${e.description}"))
    }
    val matcher = regex.matcher(s)
    while (matcher.find()) {
        matches.add(
            mapOf(
                "string_id" to sId,
                "match" to matcher.group(),
                "start" to matcher.start(),
                "end" to matcher.end()
            )
        )
    }
    return matches
};1

