class TreeNode(
    var `val`: Int = 0,
    var left: TreeNode? = null,
    var right: TreeNode? = null
)

fun largestBstSubtree(root: TreeNode?): Int {
    // Returns best (size of largest BST) in the subtree
    fun postorder(node: TreeNode?): Triple<Boolean, Int, IntArray> {
        // Returns Triple<isBST, size, intArrayOf(min, max, best)>
        if (node == null) {
            // Empty subtree is BST of size 0
            return Triple(true, 0, intArrayOf(Int.MAX_VALUE, Int.MIN_VALUE, 0))
        }
        val (lIsBst, lSize, lArr) = postorder(node.left)
        val (rIsBst, rSize, rArr) = postorder(node.right)
        val lMin = lArr[0]
        val lMax = lArr[1]
        val lBest = lArr[2]
        val rMin = rArr[0]
        val rMax = rArr[1]
        val rBest = rArr[2]

        return if (lIsBst && rIsBst && node.`val` > lMax && node.`val` < rMin) {
            val size = lSize + rSize + 1
            val mn = min(lMin, node.`val`)
            val mx = max(rMax, node.`val`)
            Triple(true, size, intArrayOf(mn, mx, size))
        } else {
            Triple(false, 0, intArrayOf(0, 0, max(lBest, rBest)))
        }
    }
    return postorder(root).third[2]
};1

