fun merge(array: Array<Int>, aux: Array<Int>, lo: Int, mid: Int, hi: Int): Long {
    var i = lo
    var j = mid + 1
    val nextToMid = j
    var k = lo

    var inversions = 0L

    while(i <= mid && j <= hi) {
        if (array[i] <= array[j]) {
            aux[k++] = array[i++]
        } else {
            aux[k++] = array[j++]
            inversions += nextToMid - i
        }
    }

    while(i <= mid)
        aux[k++] = array[i++]

    while(j <= hi)
        aux[k++] = array[j++]

    System.arraycopy(aux, lo, array, lo, (hi - lo) + 1)

    return inversions
};0

fun A(m: Long, n: Long): Long {
    require(m >= 0L) { "m must not be negative" }
    require(n >= 0L) { "n must not be negative" }
    if (m == 0L) {
        return n + 1L
    }
    if (n == 0L) {
        return A(m - 1L, 1L)
    }
    return A(m - 1L, A(m, n - 1L))
}
 
