fun heapSort(arr: MutableList<Int>) {
    heapify(arr)
    var end = arr.size - 1
    while (end > 0) {
        val temp = arr[end]
        arr[end] = arr[0]
        arr[0] = temp
        end--
        siftDown(arr, 0, end)
    }
}
 
fun heapify(arr: MutableList<Int>) {
    var start = arr.size / 2 - 1
    while (start >= 0) {
        siftDown(arr, start, arr.size - 1)
        start--
    }
}
 
fun siftDown(arr: MutableList<Int>, startPos: Int, endPos: Int) {
    var rootPos = startPos
    while (rootPos * 2 + 1 <= endPos) {
        var childPos = rootPos * 2 + 1
        if (childPos + 1 <= endPos && arr[childPos] < arr[childPos + 1]) {
            childPos++
        }
        if (arr[rootPos] < arr[childPos]) {
            val temp = arr[rootPos]
            arr[rootPos] = arr[childPos]
            arr[childPos] = temp
            rootPos = childPos
        } else {
            return
        }
    }
}
 
