import kotlin.math.abs
import kotlin.math.ceil
import kotlin.math.floor
import kotlin.math.max
import kotlin.math.min
import kotlin.math.sign
import kotlin.random.Random
 
fun decimalToRational(n: Double): Pair<Long, Long> {
    //Based on Farey sequences
    assert(n.isFinite())
    val flagNeg = n < 0.0
    val n = if (flagNeg) -n else n
    if (n < Double.MIN_VALUE) return 0L to 1L
    if (abs(n - n.roundToInt()) < Double.MIN_VALUE) return n.roundToInt() to 1L
    var a: Long = 0
    var b: Long = 1
    var c: Long = ceil(n).toLong()
    var d: Long = 1
    val aux1 = Long.MAX_VALUE / 2
    while (c < aux1 && d < aux1) {
        val aux2 = (a + c).toDouble() / (b + d)
        if (abs(n - aux2) < Double.MIN_VALUE) break
        if (n > aux2) {
            a += c
            b += d
        } else {
            c += a
            d += b
        }
    }
    // Make sure that the fraction is irreducible
    val gcd = gcd(a + c, b + d)
    return if (flagNeg) (-(a + c) / gcd) to (b + d) / gcd else (a + c) / gcd to (b + d) / gcd
}
 
fun gcd(a: Long, b: Long): Long {
    var a = a
    var b = b
    while (b!= 0L) {
        val t = b
        b = a % b
        a = t
    }
    return a
}
 
