fun minimalFenceSection(n: Int, k: Int, h: List<Int>): Int {
    var currentSum = h.subList(0, k).sum()
    var minSum = currentSum
    var minIndex = 0
    for (i in 1..(n - k)) {
        currentSum = currentSum - h[i - 1] + h[i + k - 1]
        if (currentSum < minSum) {
            minSum = currentSum
            minIndex = i
        }
    }
    return minIndex + 1
};1

