fun B10(n: Int): String {
    val pow = IntArray(n + 1)
    val val_ = IntArray(29)
    for (count in 0..n - 1) {
        val_[count + 1] = BigInteger.TEN.pow(count).mod(BigInteger.valueOf(n.toLong())).toInt()
        for (j in 0..n - 1) {
            if (pow[j]!= 0 && pow[j]!= count + 1 && pow[(j + val_[count + 1]) % n] == 0) {
                pow[(j + val_[count + 1]) % n] = count + 1
            }
        }
        if (pow[val_[count + 1]] == 0) {
            pow[val_[count + 1]] = count + 1
        }
    }
    if (pow[0]!= 0) {
        var x = n
        var s = ""
        while (x!= 0) {
            val p = pow[x % n]
            if (count > p) {
                s += "0".repeat(count - p)
            }
            count = p - 1
            s += "1"
            x = (n + x - val_[p]) % n
        }
        if (count > 0) {
            s += "0".repeat(count)
        }
        return s
    }
    return "1"
};1

