fun longestPath(edges: MutableSet<Edge>, from: Vertex, to: Vertex): Int {
    data class Candidate(val vertex: Vertex, val cost: Int, val prev: Candidate? = null) {
        fun vertices() = generateSequence(this) { it.prev }
            .map { it.vertex }
            .toSet()
    }

    var optimum = 0
    var bound = 0
    val queue = PriorityQueue<Candidate> { a, b -> b.cost.compareTo(a.cost) }
    queue.add(Candidate(from, 0))

    while (queue.isNotEmpty()) {
        val candidate = queue.poll()
        if (candidate.vertex == to && candidate.cost > bound) {
            optimum = candidate.cost
            bound = candidate.cost
        } else {
            val vertices = candidate.vertices()
            edges.filter { it.v1 == candidate.vertex && !vertices.contains(it.v2) }
                .forEach { edge ->
                    val totalEdgeCost = candidate.cost + edge.cost
                    val upperBound = totalEdgeCost + edges
                        .filterNot { vertices.contains(it.v1) || vertices.contains(it.v2) }
                        .sumOf { it.cost }
                    if (upperBound >= bound) {
                        queue.add(Candidate(edge.v2, totalEdgeCost, candidate))
                    }
                }
        }
    }

    return optimum
};0

fun findStrictlyIncreasingXorSequence(b: List<Int>): Pair<String, List<Int>?> {
    fun highestBit(x: Int): Int {
        return if (x == 0) 0 else (31 - Integer.numberOfLeadingZeros(x))
    }
    val n = b.size
    var totalXor = 0
    for (num in b) {
        totalXor = totalXor xor num
    }
    val bIndices = Array(61) { mutableListOf<Int>() }
    for ((idx, num) in b.withIndex()) {
        bIndices[highestBit(num)].add(idx)
    }
    val taken = BooleanArray(n) { false }
    val perm = mutableListOf<Int>()
    var xNow = 0
    for (rep in 0 until n) {
        var found = false
        for (hi in 0 until 61) {
            for (idx in bIndices[hi]) {
                if (taken[idx]) continue
                val maybe = b[idx]
                if ((xNow xor maybe) > xNow) {
                    taken[idx] = true
                    perm.add(maybe)
                    xNow = xNow xor maybe
                    found = true
                    break
                }
            }
            if (found) break
        }
        if (!found) {
            return Pair("No", null)
        }
    }
    // Verify result
    val a = mutableListOf<Int>()
    var current = 0
    for (el in perm) {
        current = current xor el
        a.add(current)
    }
    for (i in 0 until n - 1) {
        if (a[i] >= a[i + 1]) {
            return Pair("No", null)
        }
    }
    val usedCount = mutableMapOf<Int, Int>()
    val origCount = mutableMapOf<Int, Int>()
    for (v in b) origCount[v] = origCount.getOrDefault(v, 0) + 1
    for (v in perm) usedCount[v] = usedCount.getOrDefault(v, 0) + 1
    if (usedCount != origCount) return Pair("No", null)
    return Pair("Yes", perm)
};1

fun sumOfEvens(numbers: List<Int>): Int {
    // Compute and return the sum of all even integers in the input list.
    // Parameters:
    //    numbers: List<Int> - A list containing integer values.
    // Returns:
    //    Int - Sum of the even numbers in `numbers`. Returns 0 if there are no even numbers.
    var total = 0
    for (n in numbers) {
        if (n % 2 == 0) {
            total += n
        }
    }
    return total
};1

fun time_to_seconds(hms: String): Int {
    val parts = hms.split(":")
    val h = parts[0].toInt()
    val m = parts[1].toInt()
    val s = parts[2].toInt()
    if (h < 12) {
        return h * 60 * 60 + m * 60 + s
    }
    return (h + 24) * 60 * 60 + m * 60 + s
}

fun seconds_to_time(s: Int): String {
    var h = s / (60 * 60)
    if (h < 10) {
        h = "0$h"
    }
    s %= 60 * 60
    var m = s / 60
    if (m < 10) {
        m = "0$m"
    }
    s %= 60
    if (s < 10) {
        s = "0$s"
    }
    return "$h:$m:$s"
}

