fun findNthLargestEvenDivisible(x: Int, y: Int, z: Int, n: Int): Int {
    // Normalize the range so that low <= high
    val (low, high) = if (x <= y) Pair(x, y) else Pair(y, x)

    // A number must be divisible by both 2 and z, so it must be
    // a multiple of their least common multiple.
    fun gcd(a: Int, b: Int): Int {
        var a1 = abs(a)
        var b1 = abs(b)
        while (b1 != 0) {
            val t = b1
            b1 = a1 % b1
            a1 = t
        }
        return a1
    }
    val lcm2z = 2 * z / gcd(2, z)

    // Largest multiple of lcm_2_z that does not exceed 'high'
    val largest = high - (high % lcm2z)

    // nth largest candidate
    val candidate = largest - (n - 1) * lcm2z

    // Validate that the candidate lies inside the range
    return if (candidate >= low) candidate else -1
};1

