import kotlin.math.pow
 
// Radix sort comparator for 32-bit two's complement integers
class RadixTest(val bit: Int) { // constructor
 
    fun invoke(value: Int): Boolean { // function call operator
        if (bit == 31) { // sign bit
            return value < 0 // negative int to left partition
        } else {
            return (value and (1 shl bit)) == 0 // 0 bit to left partition
        }
    }
}
 
// Least significant digit radix sort
fun lsdRadixSort(first: IntArray, last: IntArray) {
    for (lsb in 0..31) { // least-significant-bit
        first.stablePartition(last, RadixTest(lsb))
    }
}
 
// Most significant digit radix sort (recursive)
fun msdRadixSort(first: IntArray, last: IntArray, msb: Int = 31) {
    if (first!= last && msb >= 0) {
        val mid = first.partition(last, RadixTest(msb))
        msb-- // decrement most-significant-bit
        msdRadixSort(first, mid, msb) // sort left partition
        msdRadixSort(mid, last, msb) // sort right partition
    }
}
 
// test radix_sort
fun main() {
    val data = intArrayOf(170, 45, 75, -90, -802, 24, 2, 66)
 
