fun getMonkeys(monkeysInfo: MutableList<MutableList<String>>): MutableList<Monkey> {
    val listOfMonkeys = mutableListOf<Monkey>()

    monkeysInfo.map {line ->
        val currentMonkey = Monkey()

        line.map{subLine ->
            if(subLine.startsWith("Starting")) {
                currentMonkey.itemsList = subLine.split(":")[1].trim().split(",").map {it.trim().toInt()}.toMutableList()
            } else if (subLine.startsWith("Operation")) {
                currentMonkey.operation = subLine.split("=")[1].trim()
            } else if (subLine.startsWith("Test")) {
                val testLine = subLine.split(" ")
                currentMonkey.test = testLine[testLine.lastIndex].toInt()
            } else {
                val nextMonkeyLine = subLine.split(" ")
                val nextMonkeyNumber = nextMonkeyLine[nextMonkeyLine.lastIndex].toInt()
                currentMonkey.nextMonkey.add(nextMonkeyNumber)
            }
        }

        listOfMonkeys.add(currentMonkey)
    }

    return listOfMonkeys
};0

/**
 * Given a variable number of [List]s, concatenates the [toString] value of each element with the corresponding element
 * of the next [List]s, values of each [List] left padded (right aligned) with respect to that [List]s values
 * @param lists [Array]`<out [List]<*>>` A variable number of [List]s to have their elements concatenated.
 *        All [lists] must be equal in size.
 * @return A new [List]`<String>` with the concatenated and aligned values.
 */
fun concatAlignRight(vararg lists: List<*>): List<String> {
    if (lists.isEmpty()) {
        return emptyList()
    }
    val result = lists[0].map { "" }
    return lists.fold(result, {current, next -> current concatEach next.alignRight()})
};0

 
fun longestIncreasingSubsequence(x: IntArray): IntArray =
    when (x.size) {
        0    -> IntArray(0)
        1    -> x
        else -> {
            val n = x.size
            val p = IntArray(n)
            val m = IntArray(n + 1)
            var len = 0
            for (i in 0 until n) {
                var lo = 1
                var hi = len
                while (lo <= hi) {
                    val mid = Math.ceil((lo + hi) / 2.0).toInt()
                    if (x[m[mid]] < x[i]) lo = mid + 1
                    else hi = mid - 1
                }
                val newLen = lo
                p[i] = m[newLen - 1]
                m[newLen] = i
                if (newLen > len) len = newLen
            }
            val s = IntArray(len)
            var k = m[len]
            for (i in len - 1 downTo 0) {
                s[i] = x[k]
                k = p[k]
            }
            s
        }
    }
 
