fun validateInput(shell: Shell, str: String): Int {
    try {
        return str.toInt()
    } catch (e: NumberFormatException) {
        val dialog = MessageBox(shell, SWT.ICON_ERROR or SWT.OK)
        dialog.text = "Invalid value"
        dialog.open()
        return 0
    }
}
 
fun main(args: Array<String>) {
    val display = Display()
    val shell = Shell(display)
    shell.text = "Rosetta Code"
    val monitor = shell.display.getPrimaryMonitor()
    val location = monitor.getBounds()
    val size = shell.computeSize(SWT.DEFAULT, SWT.DEFAULT)
    shell.setBounds(location.x + (location.width - size.x) / 2, location.y + (location.height - size.y) / 2, size.x, size.y)
    shell.layout = GridLayout(4, false)
 
    val label = Label(shell, SWT.NONE)
    label.text = "Value:"
    val entry = Text(shell, SWT.BORDER)
    entry.text = "0" // initialize to zero
    entry.addSelectionListener(object : SelectionAdapter() {
        fun widgetSelected(e: SelectionEvent) {
            // read and validate the entered value
            val str = entry.text
            validateInput(shell, str)
        }
    })
 
    // button to increment
    val ib = Button(shell, SWT.PUSH)
    ib.text = "Increment"
    ib.addSelectionListener(object : SelectionAdapter() {
        fun widgetSelected(e: SelectionEvent) {
            // read and validate the entered value
            val str = entry.text
            if (validateInput(shell, str)!= 0) {
                entry.text = (str.toInt() + 1).toString()
            }
        }
    })
 
