fun bubbleSort(nums: List<Int>): List<Int> {
    // Make a shallow copy so the input list isn't modified
    val arr = nums.toMutableList()
    val n = arr.size

    // Perform bubble sort
    for (i in 0 until n) {
        var swapped = false
        // Last i elements are already in place
        for (j in 0 until n - i - 1) {
            if (arr[j] > arr[j + 1]) {
                // Swap adjacent elements
                val temp = arr[j]
                arr[j] = arr[j + 1]
                arr[j + 1] = temp
                swapped = true
            }
        }
        // Optimization: stop if no swaps occurred in this pass
        if (!swapped) {
            break
        }
    }
    return arr.toList()
};1

fun regressionLineFrom(c: Collection<Point>): RegressionLine
{
    val xMean = c.asSequence()
            .map { it.x }
            .average()

    val yMean = c.asSequence()
            .map { it.y }
            .average()

    val xyMean = c.asSequence()
            .map { it.x * it.y }
            .average()

    val xSquaredMean = c.asSequence()
            .map {squared(it.x)}
            .average()

    val m: Double = (xMean * yMean - (xyMean)) / (Math.pow(xMean, 2.0) - xSquaredMean)
    val b: Double = yMean - (m * xMean)

    return RegressionLine(m, b)
};0

