fun splitMap(map: String): String {
    val width = map.lines().first().length

    val at = map.indexOf('@')
    return map.replace(at, '#').replace(at - 1, '#').replace(at + 1, '#')
        .replace(at - (width+1), '#').replace(at + (width+1), '#')
        .replace(at + 1 - (width+1), '@').replace(at -1 - (width+1), '&')
        .replace(at + 1 + (width+1), '$').replace(at -1 + (width+1), '%')
