        .mapValues { (_, v) -> v.size }
        .let { countsMap ->
            countsMap.forEach { (num, count) ->
                when {
                    num * 2 == target && count > 1 -> return num to num
                    target - num in countsMap -> return num to target - num
                }
            }
        }
