fun Grid<Int>.height(p: Point): Int? =
    if (this.containsPoint(p)) this[p]
    else null

// Find min distance path from `start` to any given target point via Dikjstra's algorithm
class PartOneSolver(private val grid: Grid<Int>, start: Point) {
    private val toVisit = mutableSetOf(start)
    private val visited = mutableSetOf<Point>()
    private val distances = Array(grid.numRows) { IntArray(grid.numCols) { Integer.MAX_VALUE } }
        .apply { this[start.y][start.x] = 0 }

    fun neighbors(point: Point): List<Point> =
        listOf(point.left, point.right, point.up, point.down)
            .filter { neighbor ->
                grid.height(neighbor).let {
                    it != null && it <= grid.height(point)!! + 1
                }
            }

    fun currDistance(point: Point): Int = distances[point.y][point.x]

    fun minDistance(to: Point): Int {
        while (to !in visited) {
            val next = toVisit.minByOrNull(::currDistance)
                ?: throw RuntimeException("Set of points to visit is empty even though graph is not fully explored!")

            toVisit.remove(next)
            neighbors(next)
                .filterNot { it in visited }
                .forEach { neighbor ->
                    distances[neighbor.y][neighbor.x] = minOf(
                        currDistance(neighbor),
                        currDistance(next) + 1
                    )
                    toVisit.add(neighbor)
                }
            visited.add(next)
        }
        return currDistance(to)
    }
};0

fun findQuadruplets(nums: List<Int>, target: Int): List<List<Int>> {
    val res = mutableListOf<List<Int>>()
    val n = nums.size
    if (n < 4) return res

    val sortedNums = nums.sorted()
    for (i in 0 until n - 3) {
        // skip duplicates for the first position
        if (i > 0 && sortedNums[i] == sortedNums[i - 1]) continue

        // early pruning for the first position
        val minSum = sortedNums[i] + sortedNums[i + 1] + sortedNums[i + 2] + sortedNums[i + 3]
        if (minSum > target) break
        val maxSum = sortedNums[i] + sortedNums[n - 1] + sortedNums[n - 2] + sortedNums[n - 3]
        if (maxSum < target) continue

        for (j in i + 1 until n - 2) {
            // skip duplicates for the second position
            if (j > i + 1 && sortedNums[j] == sortedNums[j - 1]) continue

            // early pruning for the second position
            val minSum2 = sortedNums[i] + sortedNums[j] + sortedNums[j + 1] + sortedNums[j + 2]
            if (minSum2 > target) break
            val maxSum2 = sortedNums[i] + sortedNums[j] + sortedNums[n - 1] + sortedNums[n - 2]
            if (maxSum2 < target) continue

            var left = j + 1
            var right = n - 1
            while (left < right) {
                val curr = sortedNums[i] + sortedNums[j] + sortedNums[left] + sortedNums[right]
                if (curr == target) {
                    res.add(listOf(sortedNums[i], sortedNums[j], sortedNums[left], sortedNums[right]))
                    left++
                    right--
                    // skip duplicates for the third and fourth positions
                    while (left < right && sortedNums[left] == sortedNums[left - 1]) left++
                    while (left < right && sortedNums[right] == sortedNums[right + 1]) right--
                } else if (curr < target) {
                    left++
                } else {
                    right--
                }
            }
        }
    }
    return res
};1

