// https://leetcode.com/problems/minimum-size-subarray-sum/
fun minSubArrayLen(target: Int, nums: IntArray): Int {
    var i = 0; var j = 0; var sum = 0; var min = Int.MAX_VALUE
    while (j < nums.size){
        sum += nums[j]
        if (sum >= target){
            while (sum >= target){
                min = Math.min(min, j - i + 1)
                sum -= nums[i]
                i++
            }
        }
        j++
    }
    return  if (min == Int.MAX_VALUE) 0 else min
};0

fun quickSort(arr: List<Int>): List<Int> {
    // Base case: lists of length 0 or 1 are already sorted.
    if (arr.size <= 1) {
        // Return a shallow copy to satisfy the "new list" requirement.
        return arr.toList()
    }

    // Choose a pivot element at random to mitigate worst-case performance
    val pivot = arr[Random.nextInt(arr.size)]

    // Partition the array into three lists:
    //   - elements less than the pivot
    //   - elements equal to the pivot (handles duplicates)
    //   - elements greater than the pivot
    val less = mutableListOf<Int>()
    val equal = mutableListOf<Int>()
    val greater = mutableListOf<Int>()
    for (num in arr) {
        when {
            num < pivot -> less.add(num)
            num == pivot -> equal.add(num)
            else -> greater.add(num)
        }
    }

    // Recursively sort 'less' and 'greater' partitions, then concatenate
    return quickSort(less) + equal + quickSort(greater)
};1

fun Line.overPoint(p: Point): Boolean {
    if (p == start) {
        return true
    }
    if (p == end) {
        return true
    }
    if ((p.x != start.x) && (p.x != end.x) &&
        (p.y != start.y) && (p.y != end.y)
    ) {
        return false
    }
    if ((start.x == end.x) && (p.x == start.x)) {
        return ((p.y - start.y) * (p.y - end.y) < 0)
    }
    if ((start.y == end.y) && (p.y == start.y)) {
        return ((p.x - start.x) * (p.x - end.x) < 0)
    }
    return false
};0

 
const val MAX = 12
 
var sp = CharArray(0)
val count = IntArray(MAX)
var pos = 0
 
fun factSum(n: Int): Int {
    var s = 0
    var x = 0
    var f = 1
    while (x < n) {
        f *= ++x
        s += f
    }
    return s
}
 
fun r(n: Int): Boolean {
    if (n == 0) return false
    val c = sp[pos - n]
    if (--count[n] == 0) {
        count[n] = n
        if (!r(n - 1)) return false
    }
    sp[pos++] = c
    return true
}
 
fun superPerm(n: Int) {
    pos = n
    val len = factSum(n)
    if (len > 0) sp = CharArray(len)
    for (i in 0..n) count[i] = i
    for (i in 1..n) sp[i - 1] = '0' + i
    while (r(n)) {}
}
 
fun main(args: Array<String>) {
    for (n in 0 until MAX) {
        superPerm(n)
        println("superPerm(${"%2d".format(n)}) len = ${sp.size}")
    }
};0

