    while (true) {
        (1..((croot pow 2) - ((croot - 2) pow 2))).map { it - 1 }.map { it / (croot - 1) }.drop(1).extend(1).map { moves[it] }.map { cursor += it; cursor }.forEachIndexed { i, pos ->
