fun validateBinomConfInterval(
    n: Int,
    k: Int,
    confidenceLevel: Double,
    tail: String = "two-sided",
    method: String = "sterne"
): Boolean {
    // Validate n
    if (n < 0) {
        throw IllegalArgumentException("`n` must be a non-negative integer.")
    }

    // Validate k
    if (k < 0 || k > n) {
        throw IllegalArgumentException("`k` must be an integer with 0 ≤ k ≤ n.")
    }

    // Validate confidence level
    if (confidenceLevel <= 0.0 || confidenceLevel >= 1.0) {
        throw IllegalArgumentException("`confidenceLevel` must be a float strictly between 0 and 1.")
    }

    // Validate tail
    if (tail.lowercase() != "two-sided") {
        throw IllegalArgumentException("Only two-sided confidence intervals are supported for this method.")
    }

    // Validate method
    if (method.lowercase() != "sterne") {
        throw IllegalArgumentException("Only the 'sterne' method is supported.")
    }

    // If all checks passed, return true
    return true
};1

