import kotlin.math.min
import kotlin.random.Random
 
var cell: CharArray? = null
var start: CharArray? = null
var end: CharArray? = null
var m = 0
var n = 0
 
fun make_grid(x: Int, y: Int, p: Double) {
    var i = 0
    var j = 0
    val thresh = p * Random.nextInt(0, Int.MAX_VALUE)
    m = x
    n = y
    end = start
    start = CharArray(x * y)
    end = start
    cell = CharArray(x * y)
    for (i in 0 until n) {
        for (j in 0 until m) {
            cell!![i * m + j] = if (Random.nextInt(0, Int.MAX_VALUE) < thresh) '+' else '.'
        }
    }
}
 
fun ff(p: CharArray, i: Int): Boolean {
    if (p[i]!= '+') return false
    p[i] = '#'
    return i >= end!!.size || ff(p, i + m) || ff(p, i + 1) || ff(p, i - 1) || ff(p, i - m)
}
 
fun percolate(): Boolean {
    var i = 0
    while (i < m &&!ff(cell!!, i)) {
        i++
    }
    return i < m
}
 
fun main() {
    make_grid(15, 15, 0.5)
    percolate()
    println("15x15 grid:")
    println(cell)
    println("\nrunning 10,000 tests for each case:")
    var p = 0.0
    var ip = 0
    var i = 0
    var cnt = 0
    while (ip <= 10) {
        p = ip / 10.0
        cnt = 0
        i = 0
        while (i < 10000) {
            make_grid(15, 15, p)
            cnt += if (percolate()) 1 else 0
            i++
        }
        println("p=$p:  ${cnt / 10000.0}")
        ip++
    }
};1

