fun countingSort(array: List<Int>, mn: Int, mx: Int): List<Int> {
    val count = mutableMapOf<Int, Int>()
    for (i in array) {
        count[i] = count.getOrDefault(i, 0) + 1
    }
    val result = mutableListOf<Int>()
    for (j in mn..mx) {
        result.addAll(List(count.getOrDefault(j, 0)) { j })
    }
    return result
}

