fun findOverlappingSessions(sessions: List<Pair<Int, Int>>): List<Pair<Int, Int>> {
    val overlappingSessions = mutableListOf<Pair<Int, Int>>()
    for (i in sessions.indices) {
        for (j in i + 1 until sessions.size) {
            val (start1, end1) = sessions[i]
            val (start2, end2) = sessions[j]
            if (start1 < end2 && start2 < end1) {
                overlappingSessions.add(Pair(i, j))
            }
        }
    }
    return overlappingSessions
};1

import (
    "fmt"
    "sort"
    "strings"
)
 
const stx = "\002"
const etx = "\003"
 
fun bwt(s: String): String {
    if (s.indexOf(stx) >= 0 || s.indexOf(etx) >= 0) {
        return ""
    }
    val s = stx + s + etx
    val le = s.length
    val table = arrayOfNulls<String>(le)
    table[0] = s
    for (i in 1 until le) {
        table[i] = s.substring(i) + s.substring(0, i)
    }
    sort.Strings(table)
    val lastBytes = CharArray(le)
    for (i in 0 until le) {
        lastBytes[i] = table[i][le - 1]
    }
    return String(lastBytes)
}
 
fun ibwt(r: String): String {
    val le = r.length
    val table = arrayOfNulls<String>(le)
    for (i in 0 until le) {
        for (j in 0 until le) {
            table[j] = r[j] + table[j]
        }
        sort.Strings(table)
    }
    for (row in table) {
        if (row.endsWith(etx)) {
            return row.substring(1, le - 1)
        }
    }
    return ""
}
 
fun makePrintable(s: String): String {
    // substitute ^ for STX and | for ETX to print results
    var t = s.replace(stx, "^", 1)
    return t.replace(etx, "|", 1)
}
 
