fun processLogMessage(logMessage: String): String {
    // Regular expression to capture the control OID and subtree
    val regex = Regex("control OID (\\S+)\\s+for subtree\\s+(\\S+)")
    val matchResult = regex.find(logMessage)
    if (matchResult == null) {
        return "Unknown multiplexing configuration"
    }
    val (controlOid, originalSubtree) = matchResult.destructured
    // Remove trailing punctuation (like a comma, period or semicolon) from subtree if present
    val subtree = originalSubtree.trimEnd(',', '.', ';')
    // Determine the correct return value
    return when {
        controlOid == "A123" && subtree == "network" -> "Multiplexing disabled for network"
        controlOid == "B456" && subtree == "system" -> "Multiplexing disabled for system"
        else -> "Unknown multiplexing configuration"
    }
};1

