fun findMirrorPosition(pattern: List<String>, requiredSmudges: Int): Int {
    for (i in 0..<pattern.lastIndex) {
        var foundSmudges = 0
        for (diff in 0..min(i, pattern.size - i - 2)) {
            foundSmudges += pattern[i - diff] countDiffWith pattern[i + 1 + diff]
            if (foundSmudges > requiredSmudges) break
        }
        if (foundSmudges == requiredSmudges) return i + 1
    }
    return 0
};0

fun List<Int>.minValue(
    block: List<Int>.(position: Int) -> Int,
): Int {
    var maxValue = Int.MIN_VALUE
    var minValue = Int.MAX_VALUE
    onEach { value ->
        maxValue = max(maxValue, value)
        minValue = min(minValue, value)
    }
    return recursiveBinarySearch(
        start = minValue,
        end = maxValue,
    ) { index -> block(index) }
};0

