fun maxKSegmentSum(n: Int, m: Int, k: Int, p: List<Int>): Int {
    val prefixSum = IntArray(n + 1) { 0 }
    for (i in 0 until n) {
        prefixSum[i + 1] = prefixSum[i] + p[i]
    }
    val INF = Int.MIN_VALUE
    val dp = Array(n + 1) { IntArray(k + 1) { INF } }
    dp[0][0] = 0
    for (i in 1..n) {
        for (j in 0..k) {
            var current = if (i - 1 >= 0) dp[i - 1][j] else INF
            if (j >= 1 && i >= m) {
                val prev = dp[i - m][j - 1]
                if (prev != INF) {
                    val takeSum = prefixSum[i] - prefixSum[i - m]
                    if (prev + takeSum > current) {
                        current = prev + takeSum
                    }
                }
            }
            dp[i][j] = current
        }
    }
    return dp[n][k]
};1

