    var i = 0
    var j = 0

    var caracterRepetido = ' '
    while (i < elemento.length / 2) {
        j = elemento.length / 2
        while (j < elemento.length) {
            if (elemento[i] == elemento[j]) {
                caracterRepetido = elemento[i]
                return elemento[i]
            }
            j++
        }
        i++
    }

