import java.util.ArrayList
 
val TREE_LIST = ArrayList<Long>()
val OFFSET = ArrayList<Int>()
 
fun init() {
    for (i in 0..31) {
        if (i == 1) {
            OFFSET.add(1)
        } else {
            OFFSET.add(0)
        }
    }
}
 
fun append(t: Long) {
    TREE_LIST.add(1 or (t shl 1))
}
 
fun show(t: Long, l: Int) {
    var l = l
    while (l-- > 0) {
        if (t % 2 == 1L) {
            print('(')
        } else {
            print(')')
        }
        t = t shr 1
    }
}
 
fun listTrees(n: Int) {
    for (i in OFFSET[n] until OFFSET[n + 1]) {
        show(TREE_LIST[i], 2 * n)
        println()
    }
}
 
fun assemble(n: Int, t: Long, sl: Int, pos: Int, rem: Int) {
    if (rem == 0) {
        append(t)
        return
    }
 
    var pp = pos
    var ss = sl
 
    if (sl > rem) {
        ss = rem
        pp = OFFSET[ss]
    } else if (pp >= OFFSET[ss + 1]) {
        ss--
        if (ss == 0) {
            return
        }
        pp = OFFSET[ss]
    }
 
    assemble(n, t shl (2 * ss) or TREE_LIST[pp], ss, pp, rem - ss)
    assemble(n, t, ss, pp + 1, rem)
}
 
fun makeTrees(n: Int) {
    if (OFFSET[n + 1]!= 0) {
        return
    }
    if (n > 0) {
        makeTrees(n - 1)
    }
    assemble(n, 0, n - 1, OFFSET[n - 1], n - 1)
    OFFSET[n + 1] = TREE_LIST.size
}
 
fun test(n: Int) {
    if (n < 1 || n > 12) {
        throw RuntimeException("Argument must be between 1 and 12")
    }
 
    append(0)
 
    makeTrees(n)
    println("Number of $n-trees: ${OFFSET[n + 1] - OFFSET[n]}")
    listTrees(n)
}
 
