fun sd1(numbers: List<Double>): Pair<Double, Double> {
    if (numbers.isNotEmpty()) {
        val mean = numbers.sum() / numbers.size
        val sd = Math.sqrt(numbers.sumByDouble { (it - mean) * (it - mean) } / numbers.size)
        return Pair(sd, mean)
    } else {
        return Pair(0.0, 0.0)
    }
}
 
fun sd2(numbers: List<Double>): Pair<Double, Double> {
    if (numbers.isNotEmpty()) {
        var sx = 0.0
        var sxx = 0.0
        var n = 0
        for (x in numbers) {
            sx += x
            sxx += x * x
            n++
        }
        val sd = Math.sqrt(n * sxx - sx * sx) / n
        return Pair(sd, sx / n)
    } else {
        return Pair(0.0, 0.0)
    }
}
 
