fun monotonic(l: List<Int>, k: Int, strict: Boolean = false): Boolean {
    // 0 or 1 element is trivially monotonic
    if (l.size <= 1) {
        return true
    }

    // Check every adjacent pair
    for (i in 0 until l.size - 1) {
        val prev = l[i]
        val curr = l[i + 1]
        if (curr - prev != k) {
            return false
        }
        if (strict && curr == prev) {
            return false
        }
    }

    return true
};1

fun findFilesByExtension(fileList: List<String>, fileExtension: String): Any {
    // Normalize the extension to lower-case and strip a leading dot if provided.
    val ext = fileExtension.lowercase().removePrefix(".")

    // Collect files whose extension (part after the last '.') matches ext (case-insensitive)
    val matchedFiles = fileList.filter { fname ->
        fname.lowercase().substringAfterLast('.', "") == ext
    }

    return if (matchedFiles.isNotEmpty()) {
        matchedFiles
    } else {
        "There are no $ext files in the list"
    }
};1

 
