data class Point(val x: Float, val y: Float)
 
fun calculateConvexHull(points: List<Point>): List<Point> {
    //There must be at least 3 points
    if (points.size < 3) return points
 
    val hull = mutableListOf<Point>()
 
    //Find the left most point in the polygon
    val leftMostIdx = points.withIndex()
       .minBy { it.value.x }
       ?.index?: throw Exception("No left most point")
 
    var p = leftMostIdx
    var q = 0
 
    while (true) {
        //The left most point must be part of the hull
        hull.add(points[p])
 
        q = (p + 1) % points.size
 
        for (i in 0 until points.size) {
            if (orientation(points[p], points[i], points[q]) == 2) {
                q = i
            }
        }
 
        p = q
 
        //Break from loop once we reach the first point again
        if (p == leftMostIdx) break
    }
 
    return hull
}
 
//Calculate orientation for 3 points
//0 -> Straight line
//1 -> Clockwise
//2 -> Counterclockwise
fun orientation(p: Point, q: Point, r: Point): Int {
    val val = (q.y - p.y) * (r.x - q.x) -
        (q.x - p.x) * (r.y - q.y)
 
    return when {
        val == 0f -> 0
        val > 0f -> 1
        else -> 2
    }
}
 
