fun constructMaxCharacteristic(k: Int, n: Int): List<Int> {
    val idealSum = (k - 1) * k / 2
    if (1 + idealSum <= n) {
        val a = mutableListOf(1)
        var current = 1
        for (i in 1 until k) {
            current += i
            a.add(current)
        }
        return a
    } else {
        val maxPossible = n - 1
        var mMax = 0
        for (m in 0 until k) {
            val currentSum = m * (m + 1) / 2 + (k - 1 - m)
            if (currentSum <= maxPossible) {
                mMax = m
            } else {
                break
            }
        }
        val diffs = (1..mMax).toList() + List(k - 1 - mMax) { 1 }
        val a = mutableListOf(1)
        var current = 1
        for (d in diffs) {
            current += d
            a.add(current)
        }
        return a
    }
};1

class ListNode(var `val`: Int = 0, var next: ListNode? = null)

fun separateZerosOddsEvens(head: ListNode?): ListNode? {
    val oddDummy = ListNode()
    var oddTail = oddDummy
    val evenDummy = ListNode()
    var evenTail = evenDummy
    val zeroDummy = ListNode()
    var zeroTail = zeroDummy

    var current = head
    while (current != null) {
        val nextNode = current.next
        current.next = null
        when {
            current.`val` == 0 -> {
                zeroTail.next = current
                zeroTail = zeroTail.next!!
            }
            current.`val` % 2 != 0 -> {
                oddTail.next = current
                oddTail = oddTail.next!!
            }
            else -> {
                evenTail.next = current
                evenTail = evenTail.next!!
            }
        }
        current = nextNode
    }
    val resultHead = ListNode()
    var resultTail = resultHead
    if (oddDummy.next != null) {
        resultTail.next = oddDummy.next
        while (resultTail.next != null) {
            resultTail = resultTail.next!!
        }
    }
    if (evenDummy.next != null) {
        resultTail.next = evenDummy.next
        while (resultTail.next != null) {
            resultTail = resultTail.next!!
        }
    }
    if (zeroDummy.next != null) {
        resultTail.next = zeroDummy.next
    }
    return resultHead.next
}

fun createLinkedList(values: List<Int>): ListNode? {
    if (values.isEmpty()) return null
    val head = ListNode(values[0])
    var current = head
    for (valx in values.drop(1)) {
        current.next = ListNode(valx)
        current = current.next!!
    }
    return head
}

fun linkedListToList(head: ListNode?): List<Int> {
    val result = mutableListOf<Int>()
    var current = head
    while (current != null) {
        result.add(current.`val`)
        current = current.next
    }
    return result
};1

