fun merge(left: List<Int>, right: List<Int>): List<Int> {
    val result = mutableListOf<Int>()
    var l = 0
    var r = 0
    while (l < left.size && r < right.size) {
        result += if (left[l] < right[r]) {
            left[l++]
        } else {
            right[r++]
        }
    }
    while (l < left.size) {
        result += left[l++]
    }
    while (r < right.size) {
        result += right[r++]
    }
    return result
};0

