fun parseInput(lines: List<String>): Program {
    val programs = mutableMapOf<String, Program>()
    val parentToChild = mutableSetOf<Pair<Program, String>>()

    lines.forEach {
        val parsed = Regex("\\w+").findAll(it).map { it.value }.toList()
        val program = Program(parsed[0], parsed[1].toInt())

        programs.put(program.name, program)
        parsed.drop(2).forEach {
            parentToChild.add(program to it)
        }
    }

    parentToChild.forEach { (parent, child) ->
        programs[child]?.let {
            parent.supports.add(it)
            it.supportedBy = parent
        }
    }

    return programs.values.first { it.supportedBy == null }
};0

fun sortDicts(listOfDicts: List<Map<String, Any>>): List<Map<String, Any>> {
    if (listOfDicts.isEmpty()) {
        return emptyList()
    }
    val firstDict = listOfDicts[0]
    val keys = firstDict.keys.toList()

    // Find primary key (first numerical key)
    var primary: String? = null
    for (key in keys) {
        val value = firstDict[key]
        if (value is Int || value is Double) {
            // Exclude Boolean (which is a subclass of Int in Python, so check in Kotlin too)
            if (value !is Boolean) {
                primary = key
                break
            }
        }
    }
    if (primary == null) {
        throw IllegalArgumentException("No numerical key found")
    }

    // Find secondary key (first string key different from primary)
    var secondary: String? = null
    var foundPrimary = false
    for (key in keys) {
        if (key == primary) {
            foundPrimary = true
            continue
        }
        if (foundPrimary) {
            val value = firstDict[key]
            if (value is String) {
                secondary = key
                break
            }
        }
    }
    if (secondary == null) {
        for (key in keys) {
            if (key == primary) continue
            val value = firstDict[key]
            if (value is String) {
                secondary = key
                break
            }
        }
    }
    if (secondary == null) {
        throw IllegalArgumentException("No string key found")
    }

    return listOfDicts.sortedWith(compareBy(
        {
            val v = it[primary]
            when (v) {
                is Int -> v.toDouble()
                is Double -> v
                else -> Double.MAX_VALUE
            }
        },
        {
            val v = it[secondary]
            if (v is String) v else ""
        }
    ))
};1

fun parseWorkflows2(lines: List<String>): Map<String, List<Rule>> {
    return lines.map { line ->
        val parts = line.split("{", "}")
        val name = parts[0]
        val workflow = parts[1]

        val rules: List<Rule> = workflow.split(",").map rules@{ ruleStr ->
            val conditionAndTarget = ruleStr.split(":")

            if (conditionAndTarget.size == 1) {
                val target = conditionAndTarget[0]

                return@rules Rule(0, 'X', 'X', target)
            }

            val conditionStr = conditionAndTarget[0]
            val target = conditionAndTarget[1]

            return@rules Rule(
                conditionStr.substring(2).toInt(),
                conditionStr[0],
                conditionStr[1],
                target
            )
        }

        Pair(name, rules)
    }.toMap()
};0

 
