fun cusipCheck(cusip: String): Boolean {
    if (cusip.length!= 9) {
        return false
    }
    var v = 0
    val capitalCusip = cusip.toUpperCase()
    val charIndices = capitalCusip.asIterable().take(7)
    val total = charIndices.fold(0) { total, c ->
        v = when (c) {
            '*' -> 36
            '@' -> 37
            '#' -> 38
            in '0'..'9' -> c.digitToInt()
            in 'A'..'Z' -> c.toInt() - 'A'.toInt() + 1 + 9
            else -> v
        }
        if (charIndices.indexOf(c) % 2!= 0) {
            v *= 2
        }
        total + (v / 10) + v % 10
    }
    val check = (10 - (total % 10)) % 10
    return check.toString()[0] == cusip[cusip.length - 1]
}
 
