fun lcs(X: String, Y: String): String {
    val m = X.length
    val n = Y.length
    val dp = Array(m + 1) { IntArray(n + 1) }
    for (i in 1..m) {
        for (j in 1..n) {
            if (X[i - 1] == Y[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1
            } else {
                dp[i][j] = maxOf(dp[i - 1][j], dp[i][j - 1])
            }
        }
    }
    var i = m
    var j = n
    val lcsSequence = mutableListOf<Char>()
    while (i > 0 && j > 0) {
        if (X[i - 1] == Y[j - 1]) {
            lcsSequence.add(X[i - 1])
            i--
            j--
        } else {
            if (dp[i - 1][j] > dp[i][j - 1]) {
                i--
            } else {
                j--
            }
        }
    }
    lcsSequence.reverse()
    return lcsSequence.joinToString("")
};1

