fun removeAttr(obj: Any?, attr: String): Any? {
    when (obj) {
        is MutableMap<*, *> -> {
            // Safe cast to MutableMap<String, Any?> if possible
            @Suppress("UNCHECKED_CAST")
            val mapObj = obj as MutableMap<String, Any?>
            mapObj.remove(attr)
            // Recurse into all values
            val values = mapObj.values.toList()
            for (value in values) {
                removeAttr(value, attr)
            }
        }
        is MutableList<*> -> {
            // Iterate and recurse
            for (item in obj) {
                removeAttr(item, attr)
            }
        }
        is List<*> -> {
            for (item in obj) {
                removeAttr(item, attr)
            }
        }
        is Array<*> -> {
            for (item in obj) {
                removeAttr(item, attr)
            }
        }
        is Pair<*, *> -> {
            removeAttr(obj.first, attr)
            removeAttr(obj.second, attr)
        }
        is Triple<*, *, *> -> {
            removeAttr(obj.first, attr)
            removeAttr(obj.second, attr)
            removeAttr(obj.third, attr)
        }
        else -> {
            // Try to remove property via reflection
            try {
                val kClass = obj?.javaClass ?: return obj
                val field = kClass.declaredFields.firstOrNull { it.name == attr }
                if (field != null) {
                    field.isAccessible = true
                    field.set(obj, null)
                }
            } catch (e: Exception) {
                // Ignore problems with attribute removal
            }
        }
    }
    return obj
};1

 
