fun shellSort(v: Array<Int>) {
    var gap = v.size / 2
    val len = v.size
    while (gap > 0) {
        for (i in gap until len) {
            val temp = v[i]
            var j = i
            while (j >= gap && v[j - gap] > temp) {
                v[j] = v[j - gap]
                j -= gap
            }
            v[j] = temp
        }
        gap /= 2
    }
}
 
