fun loadChecks(checks: List<String>): List<String> {
    val validChecks = mutableListOf<String>()

    for (raw in checks) {
        val line = try {
            raw.trim()
        } catch (e: Exception) {
            continue
        }
        if (line.isEmpty()) continue
        if (line.startsWith("#")) continue
        if (!line.contains(":")) continue
        val parts = line.split(":", limit = 2)
        val namePart = parts.getOrNull(0)?.trim() ?: continue
        val descPart = parts.getOrNull(1)?.trim() ?: continue
        if (namePart.isEmpty() || descPart.isEmpty()) continue
        validChecks.add("$namePart: $descPart")
    }
    return validChecks
};1

