fun movingAverage(data: List<Int>, windowSize: Int): List<Double> {
    val movingAverages = mutableListOf<Double>()
    for (i in data.indices) {
        val start = maxOf(0, i - windowSize + 1)
        val window = data.subList(start, i + 1)
        val average = window.sum().toDouble() / window.size
        movingAverages.add(average)
    }
    return movingAverages
};1

