class Fractran {
    fun run(p: String, s: Int, l: Int) {
        var start = s
        var limit = l
        val tmp = ArrayList<String>()
        val iss = Scanner(p)
        while (iss.hasNext()) {
            tmp.add(iss.next())
        }
        val v = ArrayList<Pair<Float, Float>>()
        var a: Pair<Float, Float>
        for (i in tmp.indices) {
            val pos = tmp[i].indexOf('/')
            if (pos!= -1) {
                a = Pair(tmp[i].substring(0, pos).toFloat(), tmp[i].substring(pos + 1).toFloat())
                v.add(a)
            }
        }
        exec(v, start, limit)
    }
 
    fun exec(v: ArrayList<Pair<Float, Float>>, start: Int, limit: Int) {
        var cnt = 0
        while (cnt < limit) {
            println(cnt.toString() + " : " + start)
            cnt++
            var it = v.listIterator()
            var found = false
            var r: Float
            while (it.hasNext()) {
                r = start * (it.next().first / it.next().second)
                if (r == r.toInt().toFloat()) {
                    found = true
                    break
                }
            }
            if (found) start = r.toInt() else break
        }
    }
}
 
