fun swapRanges(A: List<Int>, swaps: List<Triple<Int, Int, Int>>): List<Int> {
    val result = A.toMutableList()
    for ((b, e, t) in swaps) {
        val length = e - b
        for (k in 0 until length) {
            val i = b + k
            val j = t + k
            val temp = result[i]
            result[i] = result[j]
            result[j] = temp
        }
    }
    return result
