fun minimalTotalInconvenience(testCases: List<Pair<Int, List<Int>>>): List<Int> {
    class FenwickTree(val n: Int) {
        private val tree = IntArray(n + 2)
        fun update(idx0: Int, delta: Int) {
            var idx = idx0
            while (idx <= n) {
                tree[idx] += delta
                idx += idx and -idx
            }
        }
        fun query(idx0: Int): Int {
            var idx = idx0
            var res = 0
            while (idx > 0) {
                res += tree[idx]
                idx -= idx and -idx
            }
            return res
        }
    }
    val res = mutableListOf<Int>()
    for ((m, a) in testCases) {
        val arr = a.mapIndexed { i, s -> Pair(s, -i) }.sortedWith(compareBy<Pair<Int, Int>> { it.first }.thenBy { it.second })
        val seatAssign = IntArray(m)
        arr.forEachIndexed { seatIdx, pair ->
            val origIdx = -pair.second
            seatAssign[origIdx] = seatIdx + 1 // seatIdx is 0-based; seat index is 1-based
        }
        val ft = FenwickTree(m)
        var total = 0
        for (i in 0 until m) {
            val seatIdx = seatAssign[i]
            total += ft.query(seatIdx - 1)
            ft.update(seatIdx, 1)
        }
        res.add(total)
    }
    return res
};1

