fun quickSort(arr: List<Int>): List<Int> {
    /**
     * Sorts a list of integers in ascending order using the QuickSort algorithm.
     *
     * @param arr The list of integers to sort.
     * @return A new list containing the sorted integers.
     */
    fun _quick(lst: List<Int>): List<Int> {
        // Base case: a list of length 0 or 1 is already sorted
        if (lst.size <= 1) {
            return lst
        }
        // Choose a random pivot to help avoid worst-case performance
        val pivot = lst[Random.nextInt(lst.size)]
        // Partition the list into three sublists
        val less = lst.filter { it < pivot }
        val equal = lst.filter { it == pivot }
        val greater = lst.filter { it > pivot }
        // Recursively sort the partitions and concatenate the results
        return _quick(less) + equal + _quick(greater)
    }
    // Call the recursive helper on the input list and return the result
    return _quick(arr)
};1

fun calculateAvgAnnualIncrease(data: List<Map<String, Int>>): Double {
    if (data.size < 2) return 0.0
    val yearDisasters = mutableMapOf<Int, Int>()
    for (entry in data) {
        for ((year, num) in entry) {
            yearDisasters[year.toInt()] = num
        }
    }
    val years = yearDisasters.keys.sorted()
    var totalIncrease = 0
    for (i in 1 until years.size) {
        totalIncrease += yearDisasters[years[i]]!! - yearDisasters[years[i - 1]]!!
    }
    val avgIncrease = totalIncrease.toDouble() / (years.size - 1)
    return avgIncrease
};1

 
