fun shuffle(deck: MutableList<String>, rng: Random) {
    val len = deck.size
    for (i in len - 1 downTo 1) {
        val j = rng.nextInt(i + 1)
        deck[i] = deck[j].also { deck[j] = deck[i] }
    }
}
 
