fun convertSizes(sizes: List<Int>): List<String> {
    val result = mutableListOf<String>()
    for (size in sizes) {
        when {
            size < 1024 -> {
                result.add(String.format("%.2f B", size.toDouble()))
            }
            size < 1024 * 1024 -> {
                result.add(String.format("%.2f KB", size.toDouble() / 1024))
            }
            size < 1024 * 1024 * 1024 -> {
                result.add(String.format("%.2f MB", size.toDouble() / (1024 * 1024)))
            }
            else -> {
                result.add(String.format("%.2f GB", size.toDouble() / (1024 * 1024 * 1024)))
            }
        }
    }
    return result
