fun isPrime(n: Int): Boolean {
    if (n < 2) return false
    if (n == 2 || n == 3) return true
    if (n % 2 == 0 || n % 3 == 0) return false

    val limit = sqrt(n.toDouble()).toInt()
    var i = 5
    var step = 2
    while (i <= limit) {
        if (n % i == 0) return false
        i += step
        step = 6 - step
    }
    return true
}

