fun powmod(base: Int, exp: Int, mod: Int): Int {
    var b = base.toLong()
    var e = exp
    var res = 1L
    val m = mod.toLong()
    while (e > 0) {
        if ((e and 1) == 1) res = (res * b) % m
        b = (b * b) % m
        e = e shr 1
    }
    return res.toInt()
}

fun countPossibleN(a: Int, b: Int, p: Int, x: Long): Long {
    val M = p.toLong() * (p - 1)
    var total = 0L
    var currentAm = 1L
    for (m in 0 until (p - 1)) {
        val invAm = powmod(currentAm.toInt(), p - 2, p)
        val r = (b.toLong() * invAm % p.toLong()).toInt()
        val k = ((m - r) % p + p) % p
        val s = m + k * (p - 1)
        val firstN = if (s == 0) M else s.toLong()
        val cnt = if (firstN <= x) ((x - firstN) / M + 1) else 0L
        total += cnt
        currentAm = (currentAm * a) % p
    }
    return total
};1

fun LineSegment.isDiagonal() =
    abs(start.x - end.x) == abs(start.y - end.y) || abs(start.x - start.y) == abs(end.x - end.y)

fun LineSegment.coveredPoints(): List<Coordinate> {
    val (x1, y1) = start
    val (x2, y2) = end
    val xRange = if (x1 <= x2) x1 .. x2 else x1 downTo x2
    val yRange = if (y1 <= y2) y1 .. y2 else y1 downTo y2
    return when {
        isHorizontalOrVertical() -> xRange.flatMap { x -> yRange.map { y -> Coordinate(x, y) } }
        isDiagonal() -> xRange.zip(yRange).map { (x, y) -> Coordinate(x, y) }
        else -> throw IllegalArgumentException("Invalid segment: $this")
    }
};0

 
fun cocktailSort(a: IntArray) {
    fun swap(i: Int, j: Int) {
        val temp = a[i]
        a[i] = a[j]
        a[j] = temp
    }
    do {
        var swapped = false
        for (i in 0 until a.size - 1)
            if (a[i] > a[i + 1]) {
                swap(i, i + 1)
                swapped = true
            }
        if (!swapped) break
        swapped = false
        for (i in a.size - 2 downTo 0)
            if (a[i] > a[i + 1]) {
                swap(i, i + 1)
                swapped = true
            }
    }
    while (swapped)
}
 
