fun valid(sailor: Int, nuts: Int): Boolean {
    var nuts = nuts
    for (i in 0 until sailor) {
        if ((nuts % sailor)!= 1) return false
        nuts -= 1 + nuts / sailor
    }
    return nuts > 0 && nuts % sailor == 0
}

fun main(args: Array<String>) {
    val sailors = intArrayOf(5, 6)
    for (sailor in sailors) {
        var n = sailor
        while (!valid(sailor, n)) {
            n++
        }
        println("\n$sailor sailors => $n coconuts")
        for (i in 0..sailor) {
            val div = n / sailor
            val mod = n % sailor
            println("  $n $div $mod")
            n -= 1 + div
        }
    }
};1

 
