fun maxSubarraySum(nums: List<Int>): Int {
    // Kadane's algorithm.
    // Initialize current running sum and best (maximum) sum seen so far
    var currentSum = nums[0]
    var bestSum = nums[0]

    for (n in nums.drop(1)) {
        // Either extend the existing subarray or start a new one at current element
        currentSum = maxOf(n, currentSum + n)
        // Update the bestSum if we've found a larger one
        bestSum = maxOf(bestSum, currentSum)
    }

    return bestSum
};1

import kotlin.math.floor
import kotlin.math.log10
import kotlin.math.pow
 
fun p(l: Int, n: Int, pwr: Int = 2): Int {
    var l = l
    l = Math.abs(l)
    val digitcount = floor(log10(l.toDouble())).toInt()
    val log10pwr = log10(pwr.toDouble())
    var raised = -1
    var found = 0
    while (found < n) {
        raised++
        val firstdigits = floor(10.0.pow(log10pwr * raised + digitcount))
        if (firstdigits == l) {
            found++
        }
    }
    return raised
}
 
fun main() {
    for (l in arrayOf(12, 12, 123, 123, 123)) {
        for (n in arrayOf(1, 2, 45, 12345, 678910)) {
            println("p($l, $n) = ${p(l, n)}")
        }
    }
};1

fun findCharacterAppearingInAll(vararg lines: String): Char? {
    val maps = lines.map { string ->
        string.groupBy { it }
    }
    val combinedString = lines.reduce { x1, x2 -> x1 + x2 }
    val combinedMap = combinedString.groupBy { it }

    combinedMap.keys.forEach { key ->
        if (maps.all { map -> map.contains(key) })
            return key
    }
    return null
};0

fun solve(): Int {
    val n = readInt()
    val c = readInts()
    val nei = List(n) { mutableListOf<Int>() }
    repeat(n - 1) {
        val (v, u) = readInts().map { it - 1 }
        nei[v].add(u)
        nei[u].add(v)
    }
    fun dfs(v: Int, p: Int): Int {
        return c[v] + ((nei[v] - p).maxOfOrNull { dfs(it, v) } ?: 0)
    }
    return c[0] + nei[0].map { dfs(it, 0) }.sorted().takeLast(2).sum()
};0

fun parseInput(name: String): Pair<MutableList<Stack>, List<StackMove>> {

    fun parseStacks(inputString: String): MutableList<Stack> {
        val stackValues = inputString.lines().dropLast(1)
            .map { line ->
                line.replace("    ", "[-]")
                    .remove("[^\\w-]".toRegex())
                    .toList()
            }
            .transpose()
            .map { stack -> stack.filter { it != '-' }.toMutableList() }

        return stackValues.toMutableList()
    }

    fun parseMoves(inputString: String): List<StackMove> {
        val lineRegex = "(\\d+)".toRegex()
        return inputString.lines()
            .map { line -> lineRegex.findAll(line).map { it.value.toInt() }.toList() }
            .map { (amount, from, to) -> StackMove(amount, from - 1, to - 1) }
    }

    val (stacks, moves) = readGroupedInput(name)
    return Pair(parseStacks(stacks), parseMoves(moves))
};0

 
import Color.*
 
enum class Color { R, B }
 
sealed class Tree<A : Comparable<A>> {
 
    fun insert(x: A): Tree<A> {
        val t = ins(x)
        return when (t) {
            is T -> {
                val (_, a, y, b) = t
                T(B, a, y, b)
            }
 
            is E -> E()
        }
    }
 
    abstract fun ins(x: A): Tree<A>
}
 
class E<A : Comparable<A>> : Tree<A>() {
 
    fun ins(x: A): Tree<A> = T(R, E(), x, E())
 
    fun toString() = "E"
}
 
data class T<A : Comparable<A>>(
    val cl: Color,
    val le: Tree<A>,
    val aa: A,
    val ri: Tree<A>
) : Tree<A>() {
 
    fun balance(): Tree<A> {
        if (cl != B) return this
        val res =
            if (le is T && le.le is T && le.cl == R && le.le.cl == R) {
               val (_, t, z, d) = this
               val (_, t2, y, c) = t as T
               val (_, a, x, b) = t2 as T
               T(R, T(B, a, x, b), y, T(B, c, z, d))
            }
            else if (le is T && le.ri is T && le.cl == R && le.ri.cl == R) {
               val (_, t, z, d) = this
               val (_, a, x, t2) = t as T
               val (_, b, y, c) = t2 as T
               T(R, T(B, a, x, b), y, T(B, c, z, d))
            }
            else if (ri is T && ri.le is T && ri.cl == R && ri.le.cl == R) {
               val (_, a, x, t) = this
               val (_, t2, z, d) = t as T
               val (_, b, y, c) = t2 as T
               T(R, T(B, a, x, b), y, T(B, c, z, d))
            }
            else if (ri is T && ri.ri is T && ri.cl == R && ri.ri.cl == R) {
               val (_, a, x, t) = this
               val (_, b, y, t2) = t as T
               val (_, c, z, d) = t2 as T
               T(R, T(B, a, x, b), y, T(B, c, z, d))
            }
            else this
        return res
    }
 
    fun ins(x: A): Tree<A> = when (x.compareTo(aa)) {
        -1   -> T(cl, le.ins(x), aa, ri).balance()
        +1   -> T(cl, le, aa, ri.ins(x)).balance()
        else -> this
    }
 
    fun toString() = "T($cl, $le, $aa, $ri)"
}
 
