fun chowla(n: Int): Int {
    var sum = 0
    var i = 2
    while (i * i <= n) {
        if (n % i == 0) {
            sum += i
            val j = n / i
            if (i!= j) {
                sum += j
            }
        }
        i++
    }
    return sum
}
 
fun main() {
    for (n in 1..37) {
        println("chowla($n) = %d".format(chowla(n)))
    }
 
    var count = 0
    var power = 100
    for (n in 2..10000000) {
        if (chowla(n) == 0) {
            count++
        }
        if (n % power == 0) {
            println("There are %d primes < %d".format(count, power))
            power *= 10
        }
    }
 
    count = 0
    val limit = 350000000
    var k = 2
    var kk = 3
    while (true) {
        val p = k * kk
        if (p > limit) {
            break
        }
        if (chowla(p) == p - 1) {
            println("%d is a perfect number".format(p))
            count++
        }
        k = kk + 1
        kk = kk + k
    }
    println("There are %d perfect numbers < %d".format(count, limit))
}
 
