fun State.next(): State {
    val thisState = this
    val nextState = mutableSetOf<Point>()
    val queue: Queue<Point> = ArrayDeque<Point>().apply {
        addAll(thisState)
    }
    val prevQueued = mutableSetOf<Point>().apply {
        addAll(thisState)
    }

    while (queue.isNotEmpty()) {
        queue.poll().let { point ->
            val (x, y, z) = point
            val activeNeighbors = (-1..1).sumOf { dx ->
                (-1..1).sumOf { dy ->
                    (-1..1).count { dz ->
                        val neighbor = Point(x + dx, y + dy, z + dz)
                        if (point in thisState && neighbor !in prevQueued) {
                            queue.add(neighbor)
                            prevQueued.add(neighbor)
                        }
                        neighbor != point && neighbor in thisState
                    }
                }
            }

            when {
                point in thisState && (activeNeighbors in setOf(2, 3)) ->
                    nextState.add(point)
                point !in thisState && activeNeighbors == 3 ->
                    nextState.add(point)
                else -> {} // don't add to next state
            }
        }
    }

    return nextState
};0

// from https://en.wikipedia.org/wiki/De_Bruijn_sequence
 
fun de_bruijn(k: Int, n: Int): String {
    val alphabet = (0..k).map { it.toString() }
    val a = IntArray(k * n)
    val sequence = mutableListOf<Int>()
 
    fun db(t: Int, p: Int) {
        if (t > n) {
            if (n % p == 0) {
                sequence.addAll(a.slice(1..p))
            }
        } else {
            a[t] = a[t - p]
            db(t + 1, p)
            for (j in a[t - p] + 1 until k) {
                a[t] = j
                db(t + 1, t)
            }
        }
    }
    db(1, 1)
    return sequence.joinToString("") { alphabet[it] }
}
 
