    val digits = "0123456789"
    val errorstrings = mutableListOf<String>()
 
    for (d1 in digits) {
        for (d2 in digits) {
            for (d3 in digits) {
                for (d4 in digits) {
                    val teststring = "$d1$d2$d3$d4"
                    if (teststring!in dbwithwrap) {
                        errorstrings.add(teststring)
                    }
                }
            }
        }
    }
 
    if (errorstrings.size > 0) {
        println("  ${errorstrings.size} errors found:")
        errorstrings.forEach { println("  PIN number $it  missing") }
    } else {
        println("  No errors found")
    }
}
 
