/**
 * Samples `n` distinct random elements `T` from a `Sequence<T>`
 */
fun <T> Sequence<T>.randomDistinct(sampleSize: Int) = toList().randomDistinct(sampleSize)

/**
 * Samples `n` distinct random elements `T` from an `Iterable<T>`
 */
fun <T> List<T>.randomDistinct(sampleSize: Int): List<T> {

    val cappedSampleSize = if (sampleSize > size) size else sampleSize

    return (0..Int.MAX_VALUE).asSequence().map {
        ThreadLocalRandom.current().nextInt(0,size)
    }.distinct()
     .take(cappedSampleSize)
     .map { this[it] }
     .toList()
};0

fun findClosestFrequency(frequencies: List<Float>, target: Float): Float {
    var closestFreq: Float? = null
    var minDiff = Float.POSITIVE_INFINITY
    for (freq in frequencies) {
        val diff = kotlin.math.abs(freq - target)
        if (diff < minDiff || (diff == minDiff && freq < (closestFreq ?: Float.POSITIVE_INFINITY))) {
            minDiff = diff
            closestFreq = freq
        }
    }
    return closestFreq!!
};1

fun List<String>.parseScanReport(): List<List<Point>> {
    val field = List(FIELD_SIZE) { MutableList(FIELD_SIZE) { Point.AIR } }

    fun range(v1: Int, v2: Int): IntRange {
        return if (v1 < v2) v1..v2 else v2..v1
    }

    this
        .map(String::parsePath)
        .forEach { path ->
            path.zipWithNext()
                .forEach { (pred, next) ->
                    for (y in range(pred.second, next.second)) {
                        for (x in range(pred.first, next.first)) {
                            field[y][x] = Point.ROCK
                        }
                    }
                }
        }
    return field
