fun evaluateSentiment(text: String, positiveWords: List<String>, negativeWords: List<String>): String {
    val lowerText = text.lowercase()
    val noPunctText = lowerText.replace(Regex("[\\p{Punct}]") , "")
    val words = noPunctText.split(" ").filter { it.isNotEmpty() }
    val positiveWordsSet = positiveWords.map { it.lowercase() }.toSet()
    val negativeWordsSet = negativeWords.map { it.lowercase() }.toSet()
    val positiveCount = words.count { it in positiveWordsSet }
    val negativeCount = words.count { it in negativeWordsSet }
    return when {
        positiveCount > negativeCount -> "positive"
        negativeCount > positiveCount -> "negative"
        else -> "neutral"
    }
};1

