fun largestDivisibleSubset(nums: IntArray): List<Int> {
    if (nums.isEmpty())
        return listOf()

    val dp = Array(nums.size) { 0 to 0 }
    var maxPair = -1 to -1

    nums.sort()
    nums.forEachIndexed { index, it ->
        var maxx = 0 to -1
        for (i in 0 until index) {
            if (it % nums[i] == 0 && dp[i] > maxx)
                maxx = dp[i].first to i
        }
        dp[index] = maxx.first + 1 to maxx.second
        if (dp[index] > maxPair) maxPair = dp[index].first to index
    }
    val ans = mutableListOf<Int>()
    var index = maxPair.second
    while (index != -1) {
        ans.add(nums[index])
        index = dp[index].second
    }
    return ans
};0

fun findNextInSpiralFor(num: Int): Int {
    val spiral: MutableMap<Coordinate, Int> = getInitialSpiralMap()
    var next = 1
    var radius = 1
    while (next < num) {
        for (y in ((-1 * radius) + 1) until radius) {
            next = spiral.calculateInSpiral(Coordinate(radius, y))
            if (next > num) return next
        }
        for (x in radius downTo (-1 * radius)) {
            next = spiral.calculateInSpiral(Coordinate(x, radius))
            if (next > num) return next
        }
        for (y in (radius - 1) downTo (-1 * radius)) {
            next = spiral.calculateInSpiral(Coordinate((-1 * radius), y))
            if (next > num) return next
        }
        for (x in ((-1 * radius) + 1) until (radius + 1)) {
            next = spiral.calculateInSpiral(Coordinate(x, (-1 * radius)))
            if (next > num) return next
        }
        radius++
    }
    return next
};0

 
