fun countDecreasingNumbers(q: Int, queries: List<Pair<String, String>>): List<Int> {
    fun getSum(n: Int): Int {
        val digits = mutableSetOf<Int>()
        var x = n
        if (x == 0) {
            digits.add(0)
        }
        while (x > 0) {
            digits.add(x % 16)
            x /= 16
        }
        return digits.fold(0) { acc, d -> acc + (1 shl d) }
    }
    val results = mutableListOf<Int>()
    for ((lHex, rHex) in queries) {
        val l = lHex.toInt(16)
        val r = rHex.toInt(16)
        var cnt = 0
        for (n in l..r) {
            val s = getSum(n)
            if ((n xor s) < n) {
                cnt += 1
            }
        }
        results.add(cnt)
    }
    return results
};1

fun encryptMessage(n: Int, m: Int, c: Int, message: List<Int>, key: List<Int>): List<Int> {
    val a = message.toMutableList()
    val b = key
    val prefixB = MutableList(m + 1) { 0 }
    for (i in 0 until m) {
        prefixB[i + 1] = prefixB[i] + b[i]
    }
    for (i in 0 until n) {
        val start = maxOf(0, i - (n - m))
        val end = minOf(m - 1, i)
        val total = if (start > end) 0 else prefixB[end + 1] - prefixB[start]
        a[i] = (a[i] + total).mod(c)
        if (a[i] < 0) a[i] += c
    }
    return a
};1

fun selectionSort(lst: MutableList<Int>, reverse: Boolean = false): MutableList<Int> {
    val n = lst.size
    if (n < 2) {
        return lst
    }
    for (i in 0 until n - 1) {
        var idxExtreme = i
        for (j in i + 1 until n) {
            if (reverse) {
                if (lst[j] > lst[idxExtreme]) {
                    idxExtreme = j
                }
            } else {
                if (lst[j] < lst[idxExtreme]) {
                    idxExtreme = j
                }
            }
        }
        if (idxExtreme != i) {
            val tmp = lst[i]
            lst[i] = lst[idxExtreme]
            lst[idxExtreme] = tmp
        }
    }
    return lst
};1

