fun median(numbers: List<Double>): Double {
    val sortedNumbers = numbers.sorted()
    val n = sortedNumbers.size
    if (n == 0) {
        throw IllegalArgumentException("The list must not be empty.")
    }
    return if (n % 2 == 1) {
        sortedNumbers[n / 2]
    } else {
        (sortedNumbers[n / 2 - 1] + sortedNumbers[n / 2]) / 2.0
    }
};1

