        .replace(Regex("[\\p{Punct}]"), "")
        .lowercase()
    val words = cleanedString.split(Regex("\\s+")).filter { it.isNotEmpty() }
    val wordCounts = mutableMapOf<String, Int>()
    for (word in words) {
        wordCounts[word] = wordCounts.getOrDefault(word, 0) + 1
    }
