fun longestDistinctSubstring(s: String): Triple<Int, Int, Int> {
    var maxLen = 0
    var startIdx = 0
    var endIdx = 0
    var start = 0
    val lastSeen = mutableMapOf<Char, Int>()
    for (end in s.indices) {
        val char = s[end]
        if (lastSeen.containsKey(char) && lastSeen[char]!! >= start) {
            start = lastSeen[char]!! + 1
        }
        lastSeen[char] = end
        val currentLen = end - start + 1
        if (currentLen > maxLen) {
            maxLen = currentLen
            startIdx = start
            endIdx = end
        }
    }
    return if (maxLen != 0) Triple(maxLen, startIdx, endIdx) else Triple(0, 0, 0)
};1

