    var reject = 0
    for (word in words) {
        try {
            val num = word.map { CH2NUM[it] }.joinToString("")
            number2words.getOrPut(num) { mutableSetOf() }.add(word)
        } catch (e: Exception) {
            reject++
        }
    }
    return Pair(number2words, reject)
