fun <T : Comparable<T>> bubbleSort(values: Array<T>) {
    var n = values.size
    var swapped = true

    while (swapped) {
        swapped = false

        for (i in 1 until n) {
            if (values[i - 1] > values[i]) {
                values.swap(i - 1, i)
                swapped = true
            }
        }

        n--
    }
}

fun main(args: Array<String>) {
    // Sort numbers.
    val numbers = arrayOf(8, 7, 1, 2, 9, 3, 4, 5, 0, 6)
    println("Before: ${numbers.contentToString()}")

    bubbleSort(numbers)
    println("After: ${numbers.contentToString()}")

    // Sort strings.
    val strings = arrayOf("empty", "beach", "art", "car", "deal")
    println("Before: ${strings.contentToString()}")

    bubbleSort(strings)
    println("After: ${strings.contentToString()}")
