import java.math.BigInteger
import kotlin.system.measureTimeMillis
 
fun partial(p1: Int, p2: Int): BigInteger {
    var aux = BigInteger.ONE
    val (_, hi) = primal.estimateNthPrime(p2.toLong())
    val sieve = primal.Sieve(hi.toInt())
    val prime1 = sieve.nthPrime(p1)
    val prime2 = sieve.nthPrime(p2)
 
    for (i in sieve.primesFrom(prime1).takeWhile { it <= prime2 }) {
        aux = aux.multiply(BigInteger.valueOf(i.toLong()))
    }
    return aux
}
 
