fun calculateAverageWordLength(inputString: String): Float {
    val words = inputString.split(" ")
    val cleanedWords = mutableListOf<String>()
    for (word in words) {
        val cleanedWord = word.filter { it.isLetter() }
        if (cleanedWord.isNotEmpty()) {
            cleanedWords.add(cleanedWord)
        }
    }
    if (cleanedWords.isEmpty()) {
        return 0.0f
    }
    val totalLength = cleanedWords.sumOf { it.length }
    val average = totalLength.toFloat() / cleanedWords.size.toFloat()
    return String.format("%.2f", average).toFloat()
};1

fun maxSubarraySum(numbers: List<Int>): Int {
    if (numbers.isEmpty()) {
        return 0
    }
    var maxSoFar = numbers[0]
    var currentMax = numbers[0]
    for (num in numbers.drop(1)) {
        currentMax = maxOf(num, currentMax + num)
        maxSoFar = maxOf(maxSoFar, currentMax)
    }
    return maxSoFar
