fun trackMovement(head: Location, tail: Location) {
    if (!head.isTouching(tail)) {
        if (head.x > tail.x) tail.x++
        if (head.y > tail.y) tail.y++
        if (head.x < tail.x) tail.x--
        if (head.y < tail.y) tail.y--
    }
};0

