fun isSubsequenceList(ss: List<List<Char>>, t: List<Char>, ALPHABET: String): List<Boolean> {
    fun isSubsequence(s: List<Char>, t: List<Char>, ALPHABET: String): Boolean {
        val indexMap = mutableMapOf<Char, Int>()
        for ((idx, char) in ALPHABET.withIndex()) {
            indexMap[char] = idx
        }
        var tPtr = 0
        for (charS in s) {
            if (charS !in indexMap) {
                return false
            }
            val targetIdx = indexMap[charS]
            var found = false
            while (tPtr < t.size) {
                val currentChar = t[tPtr]
                if (currentChar !in indexMap) {
                    tPtr += 1
                    continue
                }
                val currentIdx = indexMap[currentChar]
                tPtr += 1
                if (currentIdx == targetIdx) {
                    found = true
                    break
                }
            }
            if (!found) {
                return false
            }
        }
        return true
    }
    return ss.map { s -> isSubsequence(s, t, ALPHABET) }
};1

