// HFJS#3: Plot any matrix mat (filled with 0,1)
fun pmat01(mat: Array<IntArray>, color: String) {
  // DCLs
  val cvs = document.getElementById("cvsId") as HTMLCanvasElement
  val ctx = cvs.getContext("2d") as CanvasRenderingContext2D
  val w = cvs.width; val h = cvs.height
  val m = mat[0].size; val n = mat.size
  // Cleaning canvas and setting plotting color
  ctx.fillStyle="white"; ctx.fillRect(0.0,0.0,w.toDouble(),h.toDouble())
  ctx.fillStyle=color
  // MAIN LOOP
  for(i in 0..m-1) {
    for(j in 0..n-1) {
      if(mat[i][j]==1) { ctx.fillRect(i.toDouble(),j.toDouble(),1.0,1.0)};
    }//fend j
  }//fend i
}//func end
 
// Prime function
// Plotting Sierpinski triangle. aev 4/9/17
// ord - order, fn - file name, ttl - plot title, clr - color
fun pSierpinskiT() {
  val cvs=document.getElementById("cvsId") as HTMLCanvasElement
  val ctx=cvs.getContext("2d") as CanvasRenderingContext2D
  val w=cvs.width; val h=cvs.height
  val R=Array(w) {IntArray(w)}
  for (i in 0..w-1) {
    for (j in 0..w-1) {R[i][j]=0}
  }
  ctx.fillStyle="white"; ctx.fillRect(0.0,0.0,w.toDouble(),h.toDouble())
  for (y in 0..w-1) {
    for (x in 0..w-1) {
      if((x and y) == 0 ) {R[x][y]=1}
  }}
