fun <T : Comparable<T>> Array<T>.quickSort(): Array<T> {
    if (size <= 1) return this
    val pivot = this[0]
    val (less, greatereq) = this.sliceArray(1 until size).partition { it < pivot }
    return less.quickSort() + arrayOf(pivot) + greatereq.quickSort()
};1

