const rMax32 = math.MaxInt32
 
var seed = 1
 
fun rnd() : Int {
    seed = (seed*214013 + 2531011) and rMax32
    return seed shr 16
}
 
fun deal(s : Int) : IntArray {
    seed = s
    val t = IntArray(52)
    for (i in 0..51) {
        t[i] = 51 - i
    }
    for (i in 0..50) {
        val j = 51 - rnd() % (52 - i)
        val tmp = t[i]
        t[i] = t[j]
        t[j] = tmp
    }
    return t
}
 
