fun updateLuciTestAttributes(testAttributes: Map<String, Any>, newAttributes: Map<String, Any>): Map<String, Any> {
    // Disabled test variants: overwrite if provided
    val disabledTestVariants = if (newAttributes.containsKey("disabled_test_variants")) {
        @Suppress("UNCHECKED_CAST")
        (newAttributes["disabled_test_variants"] as? Collection<String>)?.toSet() ?: emptySet()
    } else {
        @Suppress("UNCHECKED_CAST")
        (testAttributes["disabled_test_variants"] as? Collection<String>)?.toSet() ?: emptySet()
    }

    // Issue keys: merge and deduplicate
    @Suppress("UNCHECKED_CAST")
    val currentIssueKeys = (testAttributes["issue_keys"] as? Collection<String>)?.toSet() ?: emptySet()
    @Suppress("UNCHECKED_CAST")
    val newIssueKeys = (newAttributes["issue_keys"] as? Collection<String>)?.toSet() ?: emptySet()
    val mergedIssueKeys = (currentIssueKeys + newIssueKeys).toList().sorted()

    // Tags: overwrite if provided, else keep existing
    val tags = if (newAttributes.containsKey("tags")) {
        @Suppress("UNCHECKED_CAST")
        ((newAttributes["tags"] as? Collection<String>)?.toList() ?: emptyList()).sorted()
    } else {
        @Suppress("UNCHECKED_CAST")
        ((testAttributes["tags"] as? Collection<String>)?.toList() ?: emptyList()).sorted()
    }

    return mapOf(
        "disabled_test_variants" to disabledTestVariants,
        "issue_keys" to mergedIssueKeys,
        "tags" to tags
    )
};1

