/**
 * Evolution algorithm
 *
 * Evolves `parent` to match `target`.  Returns the number of evolutions performed.
 */
fun evolve(
    target: String,
    parent: String,
    copies: Int,
    mutationRate: Int
): Int {
    var counter = 0
    var parentFitness = target.length + 1
 
    while (true) {
        counter++
 
        val (bestFitness, bestSentence) = (0 until copies)
           .map {
                // Copy and mutate a new sentence.
                val sentence = mutate(parent, mutationRate)
                // Find the fitness of the new mutation
                Pair(fitness(target, sentence), sentence)
            }
           .minBy { it.first } // find the closest mutation to the target
           ?: throw IllegalStateException("copies == 0") // fails if `copies == 0`
 
        // If the best mutation of this generation is better than `parent` then "the fittest
        // survives" and the next parent becomes the best of this generation.
        if (bestFitness < parentFitness) {
            parentFitness = bestFitness
            println("$parent : generation $counter with fitness $bestFitness")
 
            if (bestFitness == 0) {
                return counter
            }
        }
    }
}
 
/**
 * Computes the fitness of a sentence against a target string, returning the number of
 * incorrect characters.
 */
fun fitness(target: String, sentence: String): Int {
    return sentence
       .zip(target)
       .count { (c1, c2) -> c1 != c2 }
}
 
/**
 * Mutation algorithm.
 *
 * It mutates each character of a string, according to a `mutationRate`.
 */
fun mutate(sentence: String, mutationRate: Int): String {
    val maybeMutate = { c: Char ->
        if (Random.nextBoolean(1.0 / mutationRate)) {
            randomChar()
        } else {
            c
        }
    }
    return sentence.map(maybeMutate).joinToString("")
}
 
/**
 * Generates a random letter or space.
 */
fun randomChar(): Char {
    // Returns a value in the range [A, Z] + an extra slot for the space character.  (The `u8`
    // values could be cast to larger integers for a better chance of the RNG hitting the proper
    // range).
    return when (Random.nextInt(b'A'.toInt(), b'Z'.toInt() + 2)) {;1

fun factors(value: Long): Sequence<Long> {
  fun recur(n: Long, i: Long): Sequence<Long> = when {
    n < i * i -> sequenceOf<Long>()
    n == i * i -> sequenceOf(i)
    n % i == 0L -> sequence { yield(i); yield(n/i); yieldAll(recur(n, i + 1)) }
    else -> recur(n, i + 1)
  }
  return recur(value, 2)
};0

