fun reverseWords(s: CharArray) {
    fun reverse(start: Int, end: Int) {
        var left = start
        var right = end
        while (left < right) {
            val temp = s[left]
            s[left] = s[right]
            s[right] = temp
            left++
            right--
        }
    }
    val n = s.size
    var start = 0
    for (i in 0 until n) {
        if (s[i] == ' ') {
            reverse(start, i - 1)
            start = i + 1
        }
    }
    reverse(start, n - 1)
};1

class SimpleMovingAverage(val period: Int) {
    val numbers = mutableListOf<Int>()
 
    fun addNumber(number: Int): Double {
        numbers.add(number)
 
        if (numbers.size > period) {
            numbers.removeAt(0)
        }
 
        if (numbers.isEmpty()) {
            return 0.0
        } else {
            val sum = numbers.sum()
            return sum.toDouble() / numbers.size
        }
    }
}
 
