fun parseStacks(lines: List<String>): Map<Int, ArrayDeque<Char>> {
    val image = lines.takeWhile { line -> line.isNotBlank() }

    val numbersLine = image.last()
    val stackLookup = numbersLine.mapIndexed { i, c -> i to c.digitToIntOrNull() }
        .associate { pair -> pair }
        .filterValues { it != null }

    val stacks = (1..stackLookup.size).associateWith { ArrayDeque<Char>() }

    image.dropLast(1)
        .forEach { line ->
            stackLookup.filterKeys { it < line.length }
                .forEach { (index, stackNr) ->
                    val char = line[index]
                    if (!char.isWhitespace()) stacks[stackNr]?.addFirst(char)
                }
        }
    return stacks.toMap()
};0

 
data class IfBoth(val cond1: Boolean, val cond2: Boolean) {
    fun elseFirst(func: () -> Unit): IfBoth {
        if (cond1 && !cond2) func()
        return this
    }
 
    fun elseSecond(func: () -> Unit): IfBoth {
        if (cond2 && !cond1) func()
        return this
    }
 
    fun elseNeither(func: () -> Unit): IfBoth {
        if (!cond1 && !cond2) func()
        return this  // in case it's called out of order
    }
}
 
fun ifBoth(cond1: Boolean, cond2: Boolean, func: () -> Unit): IfBoth {
    if (cond1 && cond2) func()
    return IfBoth(cond1, cond2)
}
 
