fun decryptMessage(encryptedMessage: String, shift: Int): String {
    // Ensure the shift is within 0–25
    val fixedShift = ((shift % 26) + 26) % 26
    val decryptedChars = StringBuilder()
    for (ch in encryptedMessage) {
        if (ch == ' ') {
            decryptedChars.append(ch)
        } else {
            // Shift backwards in the alphabet
            val originalPos = (ch.code - 'a'.code - fixedShift + 26) % 26
            decryptedChars.append(('a'.code + originalPos).toChar())
        }
    }
    return decryptedChars.toString()
};1

