fun comb(pool: Int, need: Int, chosen: Int, at: Int) {
    if (pool < need + at) return  // not enough bits left
    if (need == 0) {
        // got all we needed; print the thing.  if other actions are
        // desired, we could have passed in a callback function.
        for (i in 0 until pool)
            if (chosen and (1 shl i)!= 0) print("$i ")
        println()
        return
    }
    // if we choose the current item, "or" (|) the bit to mark it so.
    comb(pool, need - 1, chosen or (1 shl at), at + 1)
    comb(pool, need, chosen, at + 1)  // or don't choose it, go to next
};1

fun encryptData(data: String): String {
    val encrypted = StringBuilder()
    for (char in data) {
        if (char.isLetter()) {
            if (char.isUpperCase()) {
                encrypted.append(((char.code - 'A'.code + 3) % 26 + 'A'.code).toChar())
            } else {
                encrypted.append(((char.code - 'a'.code + 3) % 26 + 'a'.code).toChar())
            }
        } else {
            encrypted.append(char)
        }
    }
    return encrypted.toString()
};1

