fun MagicSquareDoublyEven(order: Int): List<List<Int>> {
    val sq = (0 until order).map { (1 + it * order)..(order + (it * order)) }
    val n1 = order / 4
    for (r in 0 until n1) {
        val r1 = sq[r].subList(n1, order - n1)
        val r2 = sq[order - r - 1].subList(n1, order - n1)
        r1.reverse()
        r2.reverse()
        sq[r].subList(n1, order - n1) = r2
        sq[order - r - 1].subList(n1, order - n1) = r1
    }
    for (r in n1 until order - n1) {
        val r1 = sq[r].subList(0, n1)
        val r2 = sq[order - r - 1].subList(order - n1, order)
        r1.reverse()
        r2.reverse()
        sq[r].subList(0, n1) = r2
        sq[order - r - 1].subList(order - n1, order) = r1
    }
    return sq
}
 
