fun possibleArithmeticAdditions(n: Int, S: List<Int>): Pair<Int, List<Int>> {
    val sortedS = S.sorted()
    if (n == 1) {
        return Pair(-1, emptyList())
    }
    val diffs = mutableListOf<Int>()
    for (i in 0 until n - 1) {
        diffs.add(sortedS[i + 1] - sortedS[i])
    }
    val uniqueDiffs = diffs.toSet()
    if (uniqueDiffs.size == 1) {
        val d = diffs[0]
        if (n == 2) {
            val res = mutableSetOf<Int>()
            res.add(sortedS[0] - d)
            res.add(sortedS[1] + d)
            if ((sortedS[0] + sortedS[1]) % 2 == 0) {
                val mid = (sortedS[0] + sortedS[1]) / 2
                res.add(mid)
            }
            val result = res.sorted()
            return Pair(result.size, result)
        } else {
            val pre = sortedS[0] - d
            val post = sortedS[n - 1] + d
            if (pre == post) {
                return Pair(1, listOf(pre))
            } else {
                return Pair(2, listOf(pre, post).sorted())
            }
        }
    }
    val count = mutableMapOf<Int, Int>()
    for (d in diffs) {
        count[d] = (count[d] ?: 0) + 1
    }
    if (count.size > 2) {
        return Pair(0, emptyList())
    }
    if (count.size == 2) {
        val keys = count.keys.sorted()
        val d1 = keys[0]
        val d2 = keys[1]
        val c1 = count[d1] ?: 0
        val c2 = count[d2] ?: 0
        if (c2 == 1 && d2 == 2 * d1) {
            val idx = diffs.indexOf(d2)
            val missing = sortedS[idx] + d1
            return Pair(1, listOf(missing))
        }
        if (c1 == 1 && d1 == 2 * d2) {
            val idx = diffs.indexOf(d1)
            val missing = sortedS[idx] + d2
            return Pair(1, listOf(missing))
        }
        return Pair(0, emptyList())
    }
    return Pair(0, emptyList())
};1

fun foldHorizontally(original: Array<Array<Int>>, foldIndex: Int): Array<Array<Int>> {
    val y = original[0].size
    val array = Array(foldIndex) { Array(y) { 0 } }

    for (i in foldIndex + 1 until original.size) {
        for (j in 0 until y) {
            array[i - foldIndex - 1][j] = original[i][j] + original[(2 * foldIndex) - i][j]
        }
    }

    return array
};0

