fun jaro(str1: String, str2: String): Double {
    if (str1.length == 0 && str2.length == 0) {
        return 1.0
    }
    if (str1.length == 0 || str2.length == 0) {
        return 0.0
    }
    var matchDistance = str1.length
    if (str2.length > matchDistance) {
        matchDistance = str2.length
    }
    matchDistance = matchDistance / 2 - 1
    val str1Matches = BooleanArray(str1.length)
    val str2Matches = BooleanArray(str2.length)
    var matches = 0.0
    var transpositions = 0.0
    for (i in str1.indices) {
        val start = i - matchDistance
        var start = start
        if (start < 0) {
            start = 0
        }
        var end = i + matchDistance + 1
        if (end > str2.length) {
            end = str2.length
        }
        for (k in start until end) {
            if (str2Matches[k]) {
                continue
            }
            if (str1[i]!= str2[k]) {
                continue
            }
            str1Matches[i] = true
            str2Matches[k] = true
            matches++
            break
        }
    }
    if (matches == 0.0) {
        return 0.0
    }
    var k = 0
    for (i in str1.indices) {
        if (!str1Matches[i]) {
            continue
        }
        while (!str2Matches[k]) {
            k++
        }
        if (str1[i]!= str2[k]) {
            transpositions++
        }
        k++
    }
    transpositions /= 2
    return (matches / str1.length +
            matches / str2.length +
            (matches - transpositions) / matches) / 3
}
 
