fun properDivisors(n: Int): List<Int> {
    if (n < 2) return emptyList()
    else {
        val rRoot = Math.sqrt(n.toDouble())
        val intRoot = Math.floor(rRoot).toInt()
        val lows = (1..intRoot).filter { n % it == 0 }
        return lows + lows.slice(1 until lows.size).map { n / it }.asReversed().slice((rRoot == intRoot) until lows.size)
    }
}
 
