        "\n|-\n" + (if (blnHeaderRow && iRow == 0) "!" else "|") + " " + lstRow.map { v ->
            if (v == null) " " else v
        }.joinToString(" " + (if (blnHeaderRow && iRow == 0) "!!" else "||") + " ")
    }.joinToString("") + "\n|}"
};1

fun hofst_10k(n: Int): Int {
    var memo = arrayOf(1, 1)
    var a: (Int) -> Int = { n: Int ->
        var result = memo[n - 1]
        if (result!is Int) {
            result = a(a(n - 1)) + a(n - a(n - 1))
            memo[n - 1] = result
        }
        result
    }
    return a(n)
}
 
fun maxima_between_twos(exp: Int): Double {
    var current_max = 0.0
    for (i in Math.pow(2.0, exp.toDouble()) + 1..Math.pow(2.0, (exp + 1).toDouble())) {
        current_max = Math.max(current_max, hofst_10k(i.toInt()).toDouble() / i)
    }
    return current_max
}
 
