fun findOverlappingSlots(tasks: List<Pair<String, String>>): List<Pair<String, String>> {
    fun toMinutes(t: String): Int {
        val (h, m) = t.split(":").map { it.toInt() }
        return h * 60 + m
    }
    val n = tasks.size
    val overlaps = mutableSetOf<Int>()
    for (i in 0 until n) {
        val (s1, e1) = toMinutes(tasks[i].first) to toMinutes(tasks[i].second)
        for (j in i + 1 until n) {
            val (s2, e2) = toMinutes(tasks[j].first) to toMinutes(tasks[j].second)
            if (maxOf(s1, s2) < minOf(e1, e2)) {
                overlaps.add(i)
                overlaps.add(j)
            }
        }
    }
    return tasks.filterIndexed { index, _ -> index in overlaps }
};1

fun averageHiringProbability(data: Map<Int, Map<String, Any>>): Double {
    if (data.isEmpty()) return 0.0

    var totalProbability = 0.0
    var validCounts = 0

    for ((_, events) in data) {
        val prob = events["is_hired_1mo"]
        when (prob) {
            is Int -> {
                totalProbability += prob.toDouble()
                validCounts++
            }
            is Double -> {
                totalProbability += prob
                validCounts++
            }
        }
    }

    if (validCounts == 0) return 0.0

    val averageProb = totalProbability / validCounts
    return String.format("%.2f", averageProb).toDouble()
};1

