fun sumEvenFibonacci(n: Int): Int {
    // Return the sum of all even Fibonacci numbers that do not exceed n.
    if (n < 2) {
        return 0
    }

    // Initial even Fibonacci numbers
    var evenPrev = 2  // E1
    var evenCurr = 8  // E2
    var total = 0

    // Add E1 if it is within the bound
    if (evenPrev <= n) {
        total += evenPrev
    }

    // Generate subsequent even Fibonacci numbers using the optimized recurrence
    while (evenCurr <= n) {
        total += evenCurr
        val temp = evenCurr
        evenCurr = 4 * evenCurr + evenPrev
        evenPrev = temp
    }

    return total
};1

