class TreeNode(var `val`: Int) {
    var left: TreeNode? = null
    var right: TreeNode? = null
}

fun sumNumbers(root: TreeNode?): Int {
    fun dfs(node: TreeNode?, currentSum: Int): Int {
        if (node == null) return 0
        val newSum = currentSum * 10 + node.`val`
        if (node.left == null && node.right == null) {
            return newSum
        }
        return dfs(node.left, newSum) + dfs(node.right, newSum)
    }
    return dfs(root, 0)
}

fun buildTree(values: List<Int?>): TreeNode? {
    if (values.isEmpty()) return null
    val nodes = mutableListOf<TreeNode?>()
    for (v in values) {
        nodes.add(if (v != null) TreeNode(v) else null)
    }
    val kids = ArrayDeque(nodes.reversed())
    val root = kids.removeLast()
    for (node in nodes) {
        if (node != null) {
            if (kids.isNotEmpty()) node.left = kids.removeLast()
            if (kids.isNotEmpty()) node.right = kids.removeLast()
        }
    }
    return root
};1

