fun solve() {
    readln()
    val a = readInts()
    var ans = 1
    var nextHigh = a.last() + 1
    val seen = mutableSetOf<Pair<Int, Int>>()
    for (i in a.indices.reversed()) {
        for (t in 1 downTo 0) {
            val high = a[i] + t
            if (high > nextHigh) continue
            nextHigh = nextHigh.coerceAtMost(high - 1)
            var j = i
            var low = high
            while (true) {
                if (!seen.add(low to j)) break
                while (j > 0 && a[j] > low) j--
                if (j < 0 || a[j] < low - 1 || a[j] > low) break
                low--
                j--
            }
            ans = ans.coerceAtLeast(high - low)
        }
    }
    println(ans)
};0

fun ratePassword(password: String): String {
    val length = password.length

    // Rule 1: very short passwords are always weak
    if (length <= 8) {
        return "weak"
    }

    // Check the character classes
    val hasUpper = password.any { it.isUpperCase() }
    val hasLower = password.any { it.isLowerCase() }
    val hasDigit = password.any { it.isDigit() }
    val hasSpecial = password.any { !it.isLetterOrDigit() }

    // Rule 2: qualifies as strong only if it is long enough and has all character kinds
    if (length > 12 && hasUpper && hasLower && hasDigit && hasSpecial) {
        return "strong"
    }

    // Rule 3: everything else that wasn't weak or strong is average
    return "average"
};1

fun generateAnagrams(word: String): List<String> {
    // Generate all unique anagrams of the given word in lexicographical order.
    // For an empty input string, the list listOf("") is returned.

    // Create frequency map for each character
    val counter = mutableMapOf<Char, Int>()
    for (ch in word) {
        counter[ch] = counter.getOrDefault(ch, 0) + 1
    }
    val n = word.length
    val anagrams = mutableListOf<String>()

    fun backtrack(path: MutableList<Char>) {
        if (path.size == n) {
            anagrams.add(path.joinToString(""))
            return
        }
        for (ch in counter.keys.sorted()) {
            if (counter[ch] == 0) continue
            counter[ch] = counter[ch]!! - 1
            path.add(ch)
            backtrack(path)
            path.removeAt(path.size - 1)
            counter[ch] = counter[ch]!! + 1
        }
    }

    backtrack(mutableListOf())
    return anagrams
};1

fun PipeSystem.withSpacing(): PipeSystemWithSpacing {
    val spacedPipes = mutableMapOf<Pos, Pipe>()
    val spacedLoop = mutableSetOf<Pos>()
    val spacing = mutableSetOf<Pos>()
    for (x in 0 until 1 + maxX * 2) {
        for (y in 0 until 1 + maxY * 2) {
            val spacedPos = Pos(x, y)
            val oldPos = Pos(x / 2, y / 2).takeIf { x % 2 == 0 && y % 2 == 0 }
            val pipe = oldPos?.let { pipes.getValue(it) } ?: Pipe.empty
            spacedPipes += spacedPos to pipe
            if (oldPos == null) {
                spacing += spacedPos
            }
            if (oldPos in loop) {
                spacedLoop += spacedPos
            }
        }
    }

    for (spacePos in spacing) {
        val north = spacePos.north() in spacedLoop && spacedPipes.getValue(spacePos.north()).south
        val east = spacePos.east() in spacedLoop && spacedPipes.getValue(spacePos.east()).west
        val south = spacePos.south() in spacedLoop && spacedPipes.getValue(spacePos.south()).north
        val west = spacePos.west() in spacedLoop && spacedPipes.getValue(spacePos.west()).east
        val pipe = listOf(
            Pipe.vertical,
            Pipe.horizontal,
            Pipe.northEast,
            Pipe.northWest,
            Pipe.southWest,
            Pipe.southEast,
        ).firstOrNull { it.north == north && it.south == south && it.west == west && it.east == east }
        if (pipe != null) {
            spacedPipes += spacePos to pipe
            spacedLoop += spacePos
        }
    }

    return PipeSystemWithSpacing(spacedPipes, spacedLoop, spacing)
};0

fun is_balanced(s: String): String {
    var str = s
    if (str.isNotEmpty() && str.last() == '.')
        str = str.substring(0, str.length - 1)
    val stack = ArrayDeque<Char>()
    for (c in str) {
        when (c) {
            '(' -> stack.addLast('(')
            '[' -> stack.addLast('[')
            ')' -> {
                if (stack.isEmpty() || stack.last() != '(')
                    return "no"
                stack.removeLast()
            }
            ']' -> {
                if (stack.isEmpty() || stack.last() != '[')
                    return "no"
                stack.removeLast()
            }
        }
    }
    return if (stack.isEmpty()) "yes" else "no"
};1

import java.util.*
 
data class Card(val rank: String, val suit: String) {
    fun toString() = "$rank of $suit"
}
 
class Deck : Iterable<Card> {
    companion object {
        val ranks = arrayOf("Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Jack", "Queen", "King", "Ace")
        val suits = arrayOf("Clubs", "Diamonds", "Hearts", "Spades")
    }
 
    val cards: MutableList<Card> = mutableListOf()
 
    init {
        for (suit in suits) {
            for (rank in ranks) {
                cards.add(Card(rank, suit))
            }
        }
    }
 
    val count: Int
        get() = cards.size
 
    fun shuffle() {
        val random = Random()
        for (i in 0..cards.size - 1) {
            val r = random.nextInt(i..cards.size - 1)
            val temp = cards[i]
            cards[i] = cards[r]
            cards[r] = temp
        }
    }
 
    fun deal(): Card {
        val last = cards.size - 1
        val card = cards[last]
        cards.removeAt(last)
        return card
    }
 
    fun iterator(): Iterator<Card> {
        return cards.listIterator(cards.size)
    }
};1

