            lat < 45 && lon > -100 -> counts[2] = counts[2]!! + 1 // Class 2: express
            lat >= 45 && lon >= -100 -> counts[3] = counts[3]!! + 1 // Class 3: local
            // Any coordinate not matching the rules is ignored
        }
    }
    return counts
