fun numberOfCyclicPaths(n: Int): Int {
    val mod = 1000000007
    var aPrev = 1L
    var bPrev = 0L
    repeat(n) {
        val aCurr = (3 * bPrev) % mod
        val bCurr = (aPrev + 2 * bPrev) % mod
        aPrev = aCurr
        bPrev = bCurr
    }
    return (aPrev % mod).toInt()
};1

fun updateEmployee(records: MutableList<MutableMap<String, Any>>, id: Int, newData: Map<String, Any>): Map<String, Any> {
