    var targetRecord: MutableMap<String, Any>? = null
    for (rec in records) {
        val recId = rec["id"]
        if (recId is Int && recId == id) {
            targetRecord = rec
            break
        }
    }

    // 2. If employee not found, return an empty map.
    if (targetRecord == null) {
        return emptyMap()
    }

    // 3. Apply updates iff they modify existing values.
    var changed = false
    for ((key, value) in newData) {
        // Skip updating the primary key 'id'
        if (key == "id") continue
        if (targetRecord.containsKey(key) && targetRecord[key] != value) {
            targetRecord[key] = value
            changed = true
        }
    }

    // 4. Return according to whether any change happened.
    return targetRecord
};1

fun mostFrequentWord(paragraph: String): String {
    val regex = Regex("[^\\w\\s]")
    val cleanedParagraph = regex.replace(paragraph.lowercase(), "")
    val words = cleanedParagraph.split(" ", "\n", "\t").filter { it.isNotEmpty() }
    if (words.isEmpty()) {
        return ""
    }
    val wordCount = mutableMapOf<String, Int>()
    for (word in words) {
        wordCount[word] = wordCount.getOrDefault(word, 0) + 1
    }
    val mostFrequent = wordCount.values.maxOrNull() ?: 0
    val mostFrequentWords = wordCount.filter { it.value == mostFrequent }.keys
    return mostFrequentWords.first()
};1

