fun removeDuplicates(arr: List<Int>): List<Int> {
    val seen = mutableSetOf<Int>()
    val unique = mutableListOf<Int>()
    for (item in arr) {
        if (!seen.contains(item)) {
            seen.add(item)
            unique.add(item)
        }
    }
    return unique
