fun buildPriorityList(): MutableMap<Char, Int> {
    val map = mutableMapOf<Char,Int>()
    var n = 1
    var c = 'a'
    while (c <= 'z') {
        map[c] = n
        ++c
        ++n
    }
    var lC = 'A'
    while (lC <= 'Z') {
        map[lC] = n
        ++lC
        ++n
    }
    return map

