fun minkowskiDistance(a: List<Double>, b: List<Double>, p: Int): Double {
    // Basic validations
    if (p < 1) {
        throw IllegalArgumentException("Parameter p must be an integer >= 1.")
    }
    if (a.size != b.size) {
        throw IllegalArgumentException("Input lists must have the same length.")
    }
    var total = 0.0
    for (i in a.indices) {
        total += abs(a[i] - b[i]).pow(p.toDouble())
    }
    return total.pow(1.0 / p)
};1

fun calculateCrc8Checksum(dataPacket: List<Int>): Boolean {
    // A valid packet: 2-byte header + at least 1-byte data + 2-byte trailer
    if (dataPacket.size < 5) {
        return false
    }

    // Helper: classical CRC-8 (polynomial 0x07, init 0x00, no final xor)
    fun crc8(data: List<Int>): Int {
        var crc = 0x00
        for (byte in data) {
            crc = crc xor (byte and 0xFF)
            repeat(8) {
                crc = if ((crc and 0x80) != 0) {
                    ((crc shl 1) xor 0x07) and 0xFF
                } else {
                    (crc shl 1) and 0xFF
                }
            }
        }
        return crc
    }

    // Extract payload and stored checksum
    val dataSection = dataPacket.subList(2, dataPacket.size - 2) // between header and trailer
    val transmittedCrc = dataPacket.last() and 0xFF // last byte

    // Compare and return
    val calculatedCrc = crc8(dataSection)
    return calculatedCrc == transmittedCrc
};1

fun partOne(src: Reader): Set<IntPair> {
    val head = RopeKnot(0, 0)
    val tail = RopeKnot(0, 0)
    val tailVisited = mutableSetOf(tail.toPair())
    src.forEachLine { line ->
        val (cmd, moves) = line.split(" ")
        repeat(moves.toInt()) { iter ->
            when (cmd) {
                "R" -> head.x++
                "L" -> head.x--
                "U" -> head.y--
                "D" -> head.y++
                else -> TODO()
            }

            if (!head.isAdjacentTo(tail)) {
                tail.x += head.x.compareTo(tail.x)
                tail.y += head.y.compareTo(tail.y)
            }

            tailVisited += tail.toPair()
        }
    }
    return tailVisited
};0

