import kotlin.math.*
 
typealias Ifctn = (Double) -> Double
 
fun simpson38(f: Ifctn, a: Double, b: Double, n: Int): Double {
    val h = (b - a) / n.toDouble()
    val h1 = h / 3
    var sum = f(a) + f(b)
    for (j in 3 * n - 1 downTo 0) {
        if (j % 3 == 0) {
            sum += 2 * f(a + h1 * j.toDouble())
        } else {
            sum += 3 * f(a + h1 * j.toDouble())
        }
    }
    return h * sum / 8
}
 
fun gammaIncQ(a: Double, x: Double): Double {
    val aa1 = a - 1
    val f: Ifctn = { t: Double ->
        t.pow(aa1) * exp(-t)
    }
    var y = aa1
    var h = 1.5e-2
    while (f(y) * (x - y) > 2e-8 && y < x) {
        y +=.4
    }
    if (y > x) {
        y = x
    }
    return 1 - simpson38(f, 0.0, y, (y / h / gamma(a)).toInt())
}
 
fun chi2ud(ds: IntArray): Double {
    var sum = 0.0
    var expected = 0.0
    for (d in ds) {
        expected += d.toDouble()
    }
    expected /= ds.size.toDouble()
    for (d in ds) {
        val x = d.toDouble() - expected
        sum += x * x
    }
    return sum / expected
}
 
fun chi2p(dof: Int, distance: Double): Double {
    return gammaIncQ(.5 * dof.toDouble(),.5 * distance)
}
 
