fun utest(dset: IntArray) {
    println("Uniform distribution test")
    var sum = 0
    for (c in dset) {
        sum += c
    }
    println(" dataset: $dset")
    println(" samples: $sum")
    println(" categories: ${dset.size}")
 
    val dof = dset.size - 1
    println(" degrees of freedom: $dof")
 
    val dist = chi2ud(dset)
    println(" chi square test statistic: $dist")
 
    val p = chi2p(dof, dist)
    println(" p-value of test statistic: $p")
 
    val sig = p < sigLevel
    println(" significant at ${sigLevel * 100}% level? $sig")
    println(" uniform? ${!sig}\n")
};1

fun maxPrettinessContest(queries: List<List<Int>>): List<Int> {
    val result = mutableListOf<Int>()
    for (a in queries) {
        val s = a.toSet().sortedDescending()
        val candidates = s.take(200)
        var maxTotal = 0
        val n = candidates.size
        for (i in 0 until n) {
            val aI = candidates[i]
            if (aI > maxTotal) {
                maxTotal = aI
            }
            for (j in i+1 until n) {
                val aJ = candidates[j]
                if (aI % aJ == 0 || aJ % aI == 0) {
                    continue
                }
                val currentSum = aI + aJ
                if (currentSum > maxTotal) {
                    maxTotal = currentSum
                }
                for (k in j+1 until n) {
                    val aK = candidates[k]
                    if (
                        aI % aK == 0 || aK % aI == 0 ||
                        aJ % aK == 0 || aK % aJ == 0
                    ) {
                        continue
                    }
                    val currentSum3 = aI + aJ + aK
                    if (currentSum3 > maxTotal) {
                        maxTotal = currentSum3
                    }
                }
            }
        }
        result.add(maxTotal)
    }
    return result
};1

fun extractFirstAndLastNumber(row: String): Int {
    val numbersAsWords =
        listOf("one", "two", "three", "four", "five", "six", "seven", "eight", "nine")

    val leftNumberAsAWord = row.takeWhile { it.isLetter() }.findAnyOf(numbersAsWords)?.second
    val left =
        if (leftNumberAsAWord != null) {
            numbersAsWords.indexOf(leftNumberAsAWord) + 1
        } else {
            row.first { it.isDigit() }.digitToInt()
        }

    val rightNumberAsAWord =
        row.takeLastWhile { it.isLetter() }.findLastAnyOf(numbersAsWords)?.second
    val right =
        if (rightNumberAsAWord != null) {
            numbersAsWords.indexOf(rightNumberAsAWord) + 1
        } else {
            row.last { it.isDigit() }.digitToInt()
        }

    return "$left$right".toInt()
};0

