fun generateCombinations(n: Int, m: Int): List<List<Int>> {
    val result = mutableListOf<List<Int>>()
    fun backtrack(start: Int, curr: MutableList<Int>) {
        if (curr.size == m) {
            result.add(curr.toList())
            return
        }
        for (i in start..n) {
            curr.add(i)
            backtrack(i + 1, curr)
            curr.removeAt(curr.size - 1)
        }
    }
    backtrack(1, mutableListOf())
    return result
};1

