fun climbingAverage(grades: List<String>): Double? {
    val suffixMap = mapOf('a' to 0.1, 'b' to 0.2, 'c' to 0.3, 'd' to 0.4)
    val values = mutableListOf<Double>()
    for (grade in grades) {
        if (grade == "5.9") {
            values.add(9.0)
            continue
        }
        if (!grade.startsWith("5.")) {
            throw IllegalArgumentException("Invalid grade format: $grade")
        }
        val rest = grade.substring(2)
        var numPart = ""
        var letterPart = ""
        for (ch in rest) {
            if (ch.isDigit()) {
                numPart += ch
            } else {
                letterPart += ch
            }
        }
        if (numPart.isEmpty()) {
            throw IllegalArgumentException("Invalid grade number: $grade")
        }
        val base = numPart.toInt()
        val dec = if (letterPart.isNotEmpty()) {
            if (!suffixMap.containsKey(letterPart[0])) {
                throw IllegalArgumentException("Invalid grade suffix: $grade")
            }
            suffixMap[letterPart[0]] ?: 0.0
        } else {
            0.0
        }
        values.add(base + dec)
    }
    return if (values.isNotEmpty()) values.sum() / values.size else null
};1

fun canReorder(N: Int, A: List<Int>, B: List<Int>): Pair<String, List<Int>?> {
    val countA = mutableMapOf<Int, Int>()
    for (a in A) {
        countA[a] = (countA[a] ?: 0) + 1
    }
    val countB = mutableMapOf<Int, Int>()
    for (b in B) {
        countB[b] = (countB[b] ?: 0) + 1
    }
    for (x in countB.keys) {
        if ((countB[x] ?: 0) > N - (countA[x] ?: 0)) {
            return Pair("No", null)
        }
    }
    val B_sorted = B.sorted()
    val res = MutableList(N) { 0 }
    var left = 0
    var right = N - 1
    for (i in N - 1 downTo 0) {
        val current = B_sorted[i]
        if (left < N && current != A[left]) {
            res[left] = current
            left += 1
        } else {
            res[right] = current
            right -= 1
        }
    }
    for (i in 0 until N) {
        if (res[i] == A[i]) {
            return Pair("No", null)
        }
    }
    return Pair("Yes", res)
};1

fun assignUserRoles(usernames: List<String>, roles: List<String>): Map<String, String> {
    // 役割が空なら全員guest
    if (roles.isEmpty()) {
        return usernames.associateWith { "guest" }
    }
    val validRoles = roles.toSet()
    val paddedRoles = roles + List(maxOf(0, usernames.size - roles.size)) { null }
    val assignments = mutableMapOf<String, String>()
    for ((user, role) in usernames.zip(paddedRoles)) {
        assignments[user] = if (role != null && validRoles.contains(role)) role else "guest"
    }
    return assignments
};1

