import java.lang.StringBuilder
import java.util.*
 
enum class Rank {
    Ace,
    One,
    Two,
    Three,
    Four,
    Five,
    Six,
    Seven,
    Eight,
    Nine,
    Ten,
    Jack,
    Queen,
    King
}
 
enum class Suit {
    Clubs,
    Diamonds,
    Hearts,
    Spades
}
 
class Card(var rank: Rank, var suit: Suit) {
    companion object {
        private const val Ranks = "A23456789TJQK"
        private const val Suits = "CDHS"
    }
 
    fun nRank(): Int {
        return rank.ordinal
    }
 
    fun nSuit(): Int {
        return suit.ordinal
    }
 
    fun toString(): String {
        return StringBuilder().append(Ranks[nRank()]).append(Suits[nSuit()]).toString()
    }
}
 
class FreeCellDeal(iDeal: Int) {
    private val deck: MutableList<Card> = mutableListOf()
 
    init {
        val rng = RNG(iDeal)
 
        val rDeck = mutableListOf<Card>()
 
        for (rank in 0..12) {
            for (suit in 0..3) {
                rDeck.add(Card(Rank.values()[rank], Suit.values()[suit]))
            }
        }
 
        for (iCard in 51 downTo 0) {
            val iSwap = rng.next() % (iCard + 1)
            deck.add(rDeck[iSwap])
            rDeck[iSwap] = rDeck[iCard]
        }
    }
 
    fun toString(): String {
        val sb = StringBuilder()
        for (iRow in 0..5) {
            for (iCol in 0..7) {
                sb.append(deck[iRow * 8 + iCol]).append(" ")
            }
            sb.append("\n")
        }
        for (iCard in 48..51) {
            sb.append(deck[iCard]).append(" ")
        }
        return sb.toString()
    }
}
 
class RNG(n: Int) {
    private var state: Int = n
 
    fun next(): Int {
        return (state = 214013 * state + 2531011) and Int.MAX_VALUE shr 16
    }
}
 
fun main() {
    println(FreeCellDeal(1))
    println()
    println(FreeCellDeal(617))
};1

import java.util.Locale
 
fun solve(a: Array<DoubleArray>, b: Array<DoubleArray>): Double {
    if (a == null || b == null || a.size == 0 || b.size == 0) {
        throw IllegalArgumentException("Invalid dimensions")
    }
 
    val n = b.size
    val p = b[0].size
    if (a[0].size!= n) {
        throw IllegalArgumentException("Invalid dimensions")
    }
 
    var det = 1.0
 
    for (i in 0 until n - 1) {
        var k = i
        for (j in i + 1 until n) {
            if (Math.abs(a[j][i]) > Math.abs(a[k][i])) {
                k = j
            }
        }
 
        if (k!= i) {
            det = -det
 
            for (j in i until n) {
                val s = a[i][j]
                a[i][j] = a[k][j]
                a[k][j] = s
            }
 
            for (j in 0 until p) {
                val s = b[i][j]
                b[i][j] = b[k][j]
                b[k][j] = s
            }
        }
 
        for (j in i + 1 until n) {
            val s = a[j][i] / a[i][i]
            for (k in i + 1 until n) {
                a[j][k] -= s * a[i][k]
            }
 
            for (k in 0 until p) {
                b[j][k] -= s * b[i][k]
            }
        }
    }
 
    for (i in n - 1 downTo 0) {
        for (j in i + 1 until n) {
            val s = a[i][j]
            for (k in 0 until p) {
                b[i][k] -= s * b[j][k]
            }
        }
        val s = a[i][i]
        det *= s
        for (k in 0 until p) {
            b[i][k] /= s
        }
    }
 
    return det
}
 
fun main(args: Array<String>) {
    val a = arrayOf(doubleArrayOf(4.0, 1.0, 0.0, 0.0, 0.0),
                    doubleArrayOf(1.0, 4.0, 1.0, 0.0, 0.0),
                    doubleArrayOf(0.0, 1.0, 4.0, 1.0, 0.0),
                    doubleArrayOf(0.0, 0.0, 1.0, 4.0, 1.0),
                    doubleArrayOf(0.0, 0.0, 0.0, 1.0, 4.0))
 
    val b = arrayOf(doubleArrayOf(1.0 / 2.0),
                    doubleArrayOf(2.0 / 3.0),
                    doubleArrayOf(3.0 / 4.0),
                    doubleArrayOf(4.0 / 5.0),
                    doubleArrayOf(5.0 / 6.0))
 
    val x = doubleArrayOf(39.0 / 400.0,
                          11.0 / 100.0,
                          31.0 / 240.0,
                          37.0 / 300.0,
                          71.0 / 400.0)
 
    println("det: " + solve(a, b))
 
    for (i in 0 until 5) {
        println(String.format(Locale.US, "%12.8f %12.4e", b[i][0], b[i][0] - x[i]))
    }
};1

fun appearsInSequence(a: Int, b: Int, c: Int): String {
    if (a == b) {
        return "YES"
    } else if (c == 0) {
        return "NO"
    } else {
        val delta = b - a
        if (delta % c != 0) {
            return "NO"
        }
        val k = delta / c
        return if (k >= 0) "YES" else "NO"
