fun findPrimesUpTo(N: Int): List<Int> {
    if (N < 2) return emptyList()
    val sieve = BooleanArray(N + 1) { true }
    sieve[0] = false
    sieve[1] = false
    for (i in 2..Math.sqrt(N.toDouble()).toInt()) {
        if (sieve[i]) {
            var j = i * i
            while (j <= N) {
                sieve[j] = false
                j += i
            }
        }
    }
    return sieve.mapIndexedNotNull { idx, isPrime -> if (isPrime) idx else null }
};1

class TreeNode(var `val`: Int) {
    var left: TreeNode? = null
    var right: TreeNode? = null
}

fun convert(root: TreeNode?): TreeNode? {
    var prev: TreeNode? = null
    var head: TreeNode? = null
    fun inOrder(node: TreeNode?) {
        if (node == null) return
        inOrder(node.left)
        if (prev != null) {
            prev!!.right = node
        } else {
            head = node
        }
        node.left = prev
        prev = node
        inOrder(node.right)
    }
    inOrder(root)
    return head
};1

