class Data(var ptr: Int, var cells: HashMap<Int, Int>)
 
fun incPtr(nextCmd: (Data) -> Data): (Data) -> Data {
    return { data: Data -> nextCmd(data.copy(ptr = data.ptr + 1)) }
}
 
fun decPtr(nextCmd: (Data) -> Data): (Data) -> Data {
    return { data: Data -> nextCmd(data.copy(ptr = data.ptr - 1)) }
}
 
fun incCell(nextCmd: (Data) -> Data): (Data) -> Data {
    return { data: Data -> nextCmd(data.copy(cells = data.cells.plus(data.ptr to (data.cells[data.ptr]?: 0) + 1))) }
}
 
fun decCell(nextCmd: (Data) -> Data): (Data) -> Data {
    return { data: Data -> nextCmd(data.copy(cells = data.cells.plus(data.ptr to (data.cells[data.ptr]?: 0) - 1))) }
}
 
