fun inputCell(nextCmd: (Data) -> Data): (Data) -> Data {
    return { data: Data ->
        val input = readLine()!!.toInt()
        nextCmd(data.copy(cells = data.cells.plus(data.ptr to input)))
    }
}
 
fun ifLoop(nextCmd: (Data) -> Data, loopCmd: (Data) -> Data): (Data) -> Data {
    return { data: Data ->
        nextCmd(loop(data, loopCmd))
    }
}
 
fun loop(data: Data, loopCmd: (Data) -> Data): Data {
    return if (data.cells[data.ptr] == 0) {
        data
    } else {
        loop(loopCmd(data), loopCmd)
    }
}
 
fun terminate(data: Data): Data {
    return data
