fun splitCmds(cmds: String): Pair<String, String> {
    fun split(cmds: String, loopCmds: String): Pair<String, String> {
        if (cmds.isEmpty()) throw Exception("invalid commands: missing ]")
        return when (cmds[0]) {
            '[' -> {
                val (c, l) = splitCmds(cmds.substring(1))
                split(c, loopCmds + "[" + l + "]")
            }
            ']' -> Pair(cmds.substring(1), loopCmds)
            else -> split(cmds.substring(1), loopCmds + cmds[0])
        }
    }
    return split(cmds, "")
}
 
