import java.math.BigInteger
import java.util.*
import kotlin.coroutines.experimental.buildSequence
 
fun smoothGenerator(ar: List<BigInteger>): Sequence<BigInteger> {
    val queues = ar.map { Pair(it, LinkedList<BigInteger>()) }
    var nextSmooth = BigInteger.ONE
    return buildSequence {
        while (true) {
            yield(nextSmooth)
            queues.forEach { (m, queue) -> queue.add(nextSmooth * m) }
            nextSmooth = queues.map { (m, queue) -> queue.first() }.min()!!
            queues.forEach { (m, queue) -> if (queue.first() == nextSmooth) queue.removeFirst() }
        }
    }
}
 
fun pierpont(num: BigInteger = BigInteger.ONE): Sequence<BigInteger> {
    return buildSequence {
        smoothGenerator(listOf(BigInteger.valueOf(2), BigInteger.valueOf(3))).forEach { smooth ->
            if (smooth + num > BigInteger.ZERO && smooth + num.isProbablePrime(10)) yield(smooth + num)
        }
    }
}
 
