fun binary_search(arr: List<Int>, key: Int): Int {
    var low = 0
    var high = arr.size - 1
    while (low <= high) {
        val mid = (low + high) / 2
        if (arr[mid] == key) {
            return mid
        } else if (arr[mid] < key) {
            low = mid + 1
        } else {
            high = mid - 1
        }
    }
    return -1
};1

fun <T> findShortestPaths(node: GraphNode<T>): MutableMap<GraphNode<T>, Pair<Int, GraphNode<T>?>> {
    val shortestPaths = mutableMapOf<GraphNode<T>, Pair<Int, GraphNode<T>?>>()
    val toInspect =
        PriorityQueue<GraphNode<T>> { n1, n2 -> shortestPaths[n1]!!.first - shortestPaths[n2]!!.first }
    val inspected = mutableSetOf<GraphNode<T>>()
    shortestPaths[node] = 0 to null
    toInspect.add(node)
    while (toInspect.isNotEmpty()) {
        val inspect = toInspect.remove()
        val pathLength = shortestPaths[inspect]!!.first
        inspect.neighbours.forEach() { (weight, neighbour) ->
            if (!inspected.contains(neighbour)) {
                val newLength = pathLength + weight
                if (newLength < (shortestPaths[neighbour]?.first ?: Int.MAX_VALUE)) {
                    shortestPaths[neighbour] = newLength to inspect
                    toInspect.remove(neighbour)
                    toInspect.add(neighbour)
                }
            }
        }
        inspected.add(inspect)
    }

    return shortestPaths
};0

 
import java.awt.Color
import java.awt.Graphics
import javax.swing.JFrame
 
class DragonCurve(iter: Int) : JFrame("Dragon Curve") {
    private val turns: MutableList<Int>
    private val startingAngle: Double
    private val side: Double
 
    init {
        setBounds(100, 100, 800, 600)
        defaultCloseOperation = EXIT_ON_CLOSE
        turns = getSequence(iter)
        startingAngle = -iter * Math.PI / 4
        side = 400.0 / Math.pow(2.0, iter / 2.0)
    }
 
    fun getSequence(iterations: Int): MutableList<Int> {
        val turnSequence = mutableListOf<Int>()
        for (i in 0 until iterations) {
            val copy = mutableListOf<Int>()
            copy.addAll(turnSequence)
            copy.reverse()
            turnSequence.add(1)
            copy.mapTo(turnSequence) { -it }
        }
        return turnSequence
    }
 
    fun paint(g: Graphics) {
        g.color = Color.BLUE
        var angle = startingAngle
        var x1 = 230
        var y1 = 350
        var x2 = x1 + (Math.cos(angle) * side).toInt()
        var y2 = y1 + (Math.sin(angle) * side).toInt()
        g.drawLine(x1, y1, x2, y2)
        x1 = x2
        y1 = y2
        for (turn in turns) {
            angle += turn * Math.PI / 2.0
            x2 = x1 + (Math.cos(angle) * side).toInt()
            y2 = y1 + (Math.sin(angle) * side).toInt()
            g.drawLine(x1, y1, x2, y2)
            x1 = x2
            y1 = y2
        }
    }
}
 
