fun getRandomPrime(rangeMin: Int, rangeMax: Int): Int {
    if (rangeMax < 2 || rangeMin > rangeMax) {
        throw IllegalArgumentException("Invalid range for prime search")
    }
    val sieve = BooleanArray(rangeMax + 1) { true }
    if (sieve.size > 1) sieve[0] = false
    if (sieve.size > 2) sieve[1] = false
    for (current in 2..sqrt(rangeMax.toDouble()).toInt()) {
        if (sieve[current]) {
            var multiple = current * current
            while (multiple <= rangeMax) {
                sieve[multiple] = false
                multiple += current
            }
        }
    }
    val primes = (maxOf(rangeMin, 2)..rangeMax).filter { sieve[it] }
    if (primes.isEmpty()) {
        throw IllegalArgumentException("No primes in the specified range")
    }
    return primes[Random.nextInt(primes.size)]
};1

 
