fun compareVersions(version1: String, version2: String): Int {
    // Split by '.' and convert each segment to integer
    val v1Parts = version1.split(".").map { it.toInt() }.toMutableList()
    val v2Parts = version2.split(".").map { it.toInt() }.toMutableList()

    // Pad the shorter list with zeros so both lists are of equal length
    val maxLen = maxOf(v1Parts.size, v2Parts.size)
    while (v1Parts.size < maxLen) {
        v1Parts.add(0)
    }
    while (v2Parts.size < maxLen) {
        v2Parts.add(0)
    }

    // Compare each segment
    for (i in 0 until maxLen) {
        val p1 = v1Parts[i]
        val p2 = v2Parts[i]
        if (p1 > p2) {
            return 1
        } else if (p1 < p2) {
            return -1
        }
    }
    // All segments are equal
    return 0
};1

