/**
 * sorts array by Shell sort algorithm
 *
 * @param array which isn't sorted
 * @return sorted array
 */
fun shellSort(array: Array<Int>): Array<Int> {
    val size = array.size
    var j: Int
    var temp: Int
    var gap = 1

    while (gap <= size / 3) gap = 3 * gap + 1

    while (gap > 0) {
        for (i in gap until size) {
            temp = array[i]
            j = i

            while (j > gap - 1 && array[j - gap] >= temp) {
                array[j] =  array[j - gap]
                j -= gap
            }

            array[j] = temp
        }

        gap = (gap - 1) / 3
    }

    println("Shell sort: ")
    println(Arrays.toString(array))

    return array
};0

 
import java.awt.Color
import java.awt.Graphics
import javax.swing.JFrame
 
class GreyBars : JFrame("grey bars example!") {
    private val w: Int
    private val h: Int
 
    init {
        w = 640
        h = 320
        setSize(w, h)
        defaultCloseOperation = JFrame.EXIT_ON_CLOSE
        isVisible = true
    }
 
    fun paint(g: Graphics) {
        var run = 0
        var colorComp: Double  // component of the color
        var columnCount = 8
        while (columnCount < 128) {
            var colorGap = 255.0 / (columnCount - 1) // by this gap we change the background color
            val columnWidth = w / columnCount
            val columnHeight = h / 4
            if (run % 2 == 0)  // switches color directions with each iteration of while loop
                colorComp = 0.0
            else {
                colorComp = 255.0
                colorGap *= -1.0
            }
            val ystart = columnHeight * run
            var xstart = 0
            for (i in 0 until columnCount) {
                val iColor = Math.round(colorComp).toInt()
                val nextColor = Color(iColor, iColor, iColor)
                g.color = nextColor
                g.fillRect(xstart, ystart, columnWidth, columnHeight)
                xstart += columnWidth
            colorComp += colorGap
        }
            run++
            columnCount *= 2
        }
    }
}
 
