fun wordify(number: Int): String {
    val SMALL = arrayOf("zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen")
    val TENS = arrayOf("wrong", "wrong", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety")
    val BIG = arrayOf(null, "thousand", "m", "b", "tr", "quadr", "quint", "sext", "sept", "oct", "non", "dec")
    return when {
        number < 0 -> "negative ${wordify(-number)}"
        number < 20 -> SMALL[number]
        number < 100 -> {
            val div = number / 10
            val mod = number % 10
            TENS[div] + if (mod == 0) "" else "-${wordify(mod)}"
        }
        number < 1000 -> {
            val div = number / 100
            val mod = number % 100
            "${SMALL[div]} hundred" + if (mod == 0) "" else " and ${wordify(mod)}"
        }
        else -> {
            // separate into 3-digit chunks
            val chunks = mutableListOf<Int>()
            var div = number
            while (div!= 0) {
                div /= 1000
                chunks.add(div % 1000)
            }
            if (chunks.size > BIG.size) {
                throw IllegalArgumentException("Integer value too large.")
            }
            chunks.map { c -> wordify(c) }
                   .zip(BIG)
                   .filter { c -> c.first!= "zero" }
                   .map { c -> c.joinToString(" ") }
                   .reversed()
                   .joinToString(", ")
                   .trim()
        }
    }
}
 
