fun maxRectangleArea(heights: List<Int>): Int {
    // Gibt die größte Rechtecksfläche in einem Histogramm zurück, das durch "heights" gegeben ist.
    if (heights.isEmpty()) return 0

    var maxArea = 0
    val stack = mutableListOf<Int>() // Speichert die Indizes der Balken
    val n = heights.size

    for (i in 0..n) { // Gehe einen Schritt über das Ende hinaus, um den Stack zu leeren
        val currHeight = if (i < n) heights[i] else 0 // Nach dem letzten Balken 0 als Sentinel-Höhe
        while (stack.isNotEmpty() && currHeight < heights[stack.last()]) {
            val topIdx = stack.removeAt(stack.lastIndex)
            val height = heights[topIdx]
            val width = if (stack.isEmpty()) i else i - stack.last() - 1
            maxArea = maxOf(maxArea, height * width)
        }
        stack.add(i)
    }

    return maxArea
};1

fun isPermutation(arr: IntArray): Boolean {
    val n = arr.size
    val seen = mutableSetOf<Int>()
    for (value in arr) {
        if (value < 0 || value >= n) {
            return false
        }
        if (value in seen) {
            return false
        }
        seen.add(value)
    }
    return seen.size == n
};1

import java.util.ArrayList
import java.util.Arrays
 
val MAX = 12
 
var sp = ArrayList<Char>()
var count = IntArray(MAX)
var pos = 0
 
fun factSum(n: Int): Int {
    var s = 0
    var x = 0
    var f = 1
    while (x < n) {
        f *= ++x
        s += f
    }
    return s
}
 
fun r(n: Int): Boolean {
    if (n == 0) {
        return false
    }
    val c = sp[pos - n]
    if (--count[n] == 0) {
        count[n] = n
        if (!r(n - 1)) {
            return false
        }
    }
    sp[pos++] = c
    return true
}
 
fun superPerm(n: Int) {
    pos = n
    val len = factSum(n)
    if (len > 0) {
        sp = ArrayList(len)
    }
    for (i in 0..n) {
        count[i] = i
    }
    for (i in 1..n) {
        sp[i - 1] = ('0' + i).toChar()
    }
    while (r(n)) {}
}
 
fun main() {
    for (n in 0 until MAX) {
        superPerm(n)
        println("superPerm($n) len = ${sp.size}")
