fun findIndices(arr: List<Int>, targets: List<Int>): Map<Int, List<Int>> {
    val indexMap = mutableMapOf<Int, MutableList<Int>>()
    for ((idx, num) in arr.withIndex()) {
        if (num !in indexMap) {
            indexMap[num] = mutableListOf()
        }
        indexMap[num]!!.add(idx)
    }
    val result = mutableMapOf<Int, List<Int>>()
    for (target in targets) {
        result[target] = indexMap[target] ?: listOf()
    }
    return result
