/**
 * zipIf - integrates sequence with only those items from the other sequence which
 * satisfy the predicate
 */
fun <T, R> Sequence<T>.zipIf(
    other: Sequence<R>,
    predicate: (T, R) -> Boolean
): Sequence<Pair<T, R>> {

    fun recZipIf(
        s1: Sequence<T>,
        s2: Sequence<R>,
        pairs: Sequence<Pair<T, R>> = emptySequence()
    ): Sequence<Pair<T, R>> {
        val (f1, rs1) = s1.headTails()
        val (f2, rs2) = s2.dropWhile { f1 != null && !predicate(f1, it) }.headTails()

        return when {
            f1 == null || f2 == null -> pairs
            else -> recZipIf(rs1, rs2, pairs + (f1 to f2))
        }
    }

    return recZipIf(this, other)
};0

fun canFinish(numCourses: Int, prerequisites: List<List<Int>>, maxCourses: Int): Boolean {
    val adj = Array(numCourses) { mutableListOf<Int>() }
    val inDegree = IntArray(numCourses)
    for (pr in prerequisites) {
        val a = pr[0]
        val b = pr[1]
        adj[b].add(a)
        inDegree[a]++
    }
    val queue: Deque<Int> = ArrayDeque()
    for (i in 0 until numCourses) {
        if (inDegree[i] == 0) {
            queue.add(i)
        }
    }
    var count = 0
    while (queue.isNotEmpty()) {
        val levelSize = queue.size
        if (levelSize > maxCourses) {
            return false
        }
        count += levelSize
        repeat(levelSize) {
            val node = queue.removeFirst()
            for (neighbor in adj[node]) {
                inDegree[neighbor]--
                if (inDegree[neighbor] == 0) {
                    queue.add(neighbor)
                }
            }
        }
    }
    return count == numCourses
};1

 
class Brainf__k(val prog: String, memSize: Int) {
    private val mem = IntArray(memSize)
    private var ip = 0
    private var dp = 0
    private val memVal get() = mem.getOrElse(dp) { 0 }
 
    fun execute() {
        while (ip < prog.length) {
            when (prog[ip++]) {
                '>' -> dp++
                '<' -> dp--
                '+' -> mem[dp] = memVal + 1
                '-' -> mem[dp] = memVal - 1
                ',' -> mem[dp] = System.`in`.read()
                '.' -> print(memVal.toChar())
                '[' -> handleLoopStart()
                ']' -> handleLoopEnd()
            }
        }
    }
 
    fun handleLoopStart() {
        if (memVal != 0) return
        var depth = 1
        while (ip < prog.length) {
            when (prog[ip++]) {
                '[' -> depth++
                ']' -> if (--depth == 0) return
            }
        }
        throw IllegalStateException("Could not find matching end bracket")
    }
 
    fun handleLoopEnd() {
        var depth = 0
        while (ip >= 0) {
            when (prog[--ip]) {
                ']' -> depth++
                '[' -> if (--depth == 0) return
            }
        }
        throw IllegalStateException("Could not find matching start bracket")
    }
}
 
fun main(args: Array<String>) {
    val prog = "++++++++++[>+++++++>++++++++++>+++>+<<<<-]>++.>+.+++++++..+++.>++.<<+++++++++++++++.>.+++.------.--------.>+.>."
    Brainf__k(prog, 10).execute()
};0

 
typealias Table = List<List<String>>
 
/* Note that if ordering is specified, first two parameters are ignored */
fun Table.sort(
    column: Int = 0,
    reverse: Boolean = false,
    ordering: Comparator<List<String>> =
        if (!reverse) compareBy  { it[column] }
        else compareByDescending { it[column] }
) = this.sortedWith(ordering)
 
fun Table.print(title: String) {
    println(title)
    for (i in 0 until this.size) {
        for (j in 0 until this[0].size) System.out.print("%-3s  ".format(this[i][j]))
        println()
    }
    println()
}
 
fun main(args: Array<String>) {
    val table = listOf(
        listOf("a", "b", "c"),
        listOf("", "q", "z"),
        listOf("zap", "zip", "Zot")
    )
    table.print("Original:")
 
    val titles = listOf(
        "Sorted by col 0:", "Sorted by col 1:", "Sorted by col 2:",
        "Reverse sorted by col 0:", "Reverse sorted by col 1:", "Reverse Sorted by col 2"
    )
    val params = listOf(
        0 to false, 1 to false, 2 to false, 0 to true, 1 to true, 2 to true
    )
    for ((i, title) in titles.withIndex()) {
        val table2 = table.sort(params[i].first, params[i].second)
        table2.print(title)
    }
    // using non-default Comparator (case insensitive by col 2, reversed)
    val comp: Comparator<List<String>> = compareByDescending { it[2].toLowerCase() }
    val table3 = table.sort(ordering = comp)
    table3.print("Reverse case insensitive sort by col 2:")
};0

