import java.lang.Long
import java.lang.Math
import java.lang.System
 
fun kaprekar(n: Long, base: Int): Int {
    var nn: Long = n * n
    var r: Long
    var tens: Long = 1
    if ((nn - n) % (base - 1)!= 0L) return 0
    while (tens < n) tens *= base
    if (n == tens) return 1 == n
    while ((r = nn % tens) < n) {
        if (nn / tens + r == n) return tens.toInt()
        tens *= base
    }
    return 0
}
 
fun print_num(n: Long, base: Int) {
    var q: Long
    var div: Long = base
    while (div < n) div *= base
    while (n!= 0L && (div /= base)!= 0L) {
        q = n / div
        if (q < 10L) System.out.print(q + '0')
        else System.out.print(q + 'a' - 10)
        n -= q * div
    }
}
 
fun main(args: Array<String>) {
    var i: Long
    var tens: Long
    var cnt: Int = 0
    var base: Int = 10
    System.out.println("base 10:")
    for (i in 1..999999)
        if (kaprekar(i, base)!= 0)
            System.out.printf("%3d: %d\n", ++cnt, i)
    base = 17
    System.out.printf("\nbase %d:\n  1: 1\n", base)
    for (i in 2..999999)
        if ((tens = kaprekar(i, base).toLong())!= 0L) {
            System.out.printf("%3d: %d", ++cnt, i)
            System.out.print(" \t")
            print_num(i, base)
            System.out.print("\t")
            print_num(i * i, base)
            System.out.print("\t")
            print_num(i * i / tens, base)
            System.out.print(" + ")
            print_num(i * i % tens, base)
            System.out.print("\n")
        }
};1

fun stoogesort(L: List<Int>, i: Int = 0, j: Int? = null): List<Int> {
    var j = j
    if (j == null) {
        j = L.size - 1
    }
    if (L[j] < L[i]) {
        val temp = L[i]
        L[i] = L[j]
        L[j] = temp
    }
    if (j - i > 1) {
        val t = (j - i + 1) / 3
        stoogesort(L, i, j - t)
        stoogesort(L, i + t, j)
        stoogesort(L, i, j - t)
    }
    return L
};1

import java.util.Random
 
object BestShuffle {
    operator fun invoke(s1: String) : String {
        val s2 = s1.toCharArray()
        s2.shuffle()
        for (i in s2.indices)
            if (s2[i] == s1[i])
                for (j in s2.indices)
                    if (s2[i] != s2[j] && s2[i] != s1[j] && s2[j] != s1[i]) {
                        val tmp = s2[i]
                        s2[i] = s2[j]
                        s2[j] = tmp
                        break
                    }
        return s1 + ' ' + String(s2) + " (" + s2.count(s1) + ')'
    }
 
    fun CharArray.shuffle() {
        val rand = Random()
        for (i in size - 1 downTo 1) {
            val r = rand.nextInt(i + 1)
            val tmp = this[i]
            this[i] = this[r]
            this[r] = tmp
        }
    }
 
    fun CharArray.count(s1: String) : Int {
        var count = 0
        for (i in indices)
            if (s1[i] == this[i]) count++
        return count
    }
}
 
fun main(words: Array<String>) = words.forEach { println(BestShuffle(it)) };0

fun detectBrowser(userAgent: String?): String {
    // Very small (and far-from-perfect) browser detector.
    // Recognises: Internet Explorer, Firefox, Chrome, Safari, Opera
    // Returns 'Unknown' for anything else (e.g. Edge, Brave, etc.).

    if (userAgent == null || userAgent.isEmpty()) {
        return "Unknown"
    }

    val ua = userAgent.lowercase()

    // Internet Explorer (older ‘MSIE’ or IE11 with ‘Trident/’)
    if ("msie" in ua || "trident/" in ua) {
        return "Internet Explorer"
    }

    // Opera (old ‘opera’ or new ‘opr/’ token)
    if ("opr/" in ua || "opera" in ua) {
        return "Opera"
    }

    // Firefox
    if ("firefox/" in ua) {
        return "Firefox"
    }

    // Chrome (but ignore Edge or Opera, which also contain 'chrome/')
    if (("chrome/" in ua || "crios/" in ua) &&
        !ua.contains("edge/") && !ua.contains("edg/") && !ua.contains("opr/")) {
        return "Chrome"
    }

    // Safari (has 'safari/' but *not* chrome/opera/edge)
    if ("safari/" in ua &&
        !ua.contains("chrome/") && !ua.contains("crios/") &&
        !ua.contains("opr/") && !ua.contains("edge/") && !ua.contains("edg/")) {
        return "Safari"
    }

    return "Unknown"
};1

fun checkWin(board: List<List<Char>>, row: Int, col: Int, chance: Char): Boolean {
    if (board.isEmpty() || board[0].isEmpty()) {
        return false
    }

    val rows = board.size
    val cols = board[0].size

    // Four principal directions: horizontal, vertical, two diagonals.
    val directions = listOf(
        Pair(0, 1),   // horizontal
        Pair(1, 0),   // vertical
        Pair(1, 1),   // main diagonal
        Pair(1, -1)   // anti-diagonal
    )

    for ((dr, dc) in directions) {
        var count = 1 // include the last placed piece itself

        // Step in the positive direction
        var r = row + dr
        var c = col + dc
        while (r in 0 until rows && c in 0 until cols && board[r][c] == chance) {
            count += 1
            r += dr
            c += dc
        }

        // Step in the negative direction
        r = row - dr
        c = col - dc
        while (r in 0 until rows && c in 0 until cols && board[r][c] == chance) {
            count += 1
            r -= dr
            c -= dc
        }

        // Check if 4 or more in a row
        if (count >= 4) {
            return true
        }
    }
    return false
};1

 
import java.util.Random
 
fun IntArray.swap(i: Int, j: Int) {
    val temp = this[i]
    this[i] = this[j]
    this[j] = temp
}
 
fun mrUnrank1(rank: Int, n: Int, vec: IntArray) {
    if (n < 1) return
    val q = rank / n
    val r = rank % n
    vec.swap(r, n - 1)
    mrUnrank1(q, n - 1, vec)
}
 
fun mrRank1(n: Int, vec: IntArray, inv: IntArray): Int {
    if (n < 2) return 0
    val s = vec[n - 1]
    vec.swap(n - 1, inv[n - 1])
    inv.swap(s, n - 1)
    return s + n * mrRank1(n - 1, vec, inv)
}
 
fun getPermutation(rank: Int, n: Int, vec: IntArray) {
    for (i in 0 until n) vec[i] = i
    mrUnrank1(rank, n, vec)
}
 
fun getRank(n: Int, vec: IntArray): Int {
    val v   = IntArray(n)
    val inv = IntArray(n)
    for (i in 0 until n) {
        v[i] = vec[i]
        inv[vec[i]] = i
    }
    return mrRank1(n, v, inv)
}
 
fun main(args: Array<String>) {
    var tv = IntArray(3)
    for (r in 0..5) {
        getPermutation(r, 3, tv)
        System.out.printf("%2d -> %s -> %d\n", r, tv.contentToString(), getRank(3, tv))
