fun extractPackageInfo(packageInfo: String): Map<String, Any> {
    val lines = packageInfo.lines()

    // --- Extract GitHub stars from the first line ---
    val firstLine = lines[0].trim()
    val starRegex = Regex("<gh_stars>\\s*(\\d+)")
    val starMatch = starRegex.find(firstLine)
    if (starMatch == null) {
        throw IllegalArgumentException("Could not find GitHub stars line in the expected format.")
    }
    val githubStars = starMatch.groupValues[1].toInt()

    // --- Extract author name ---
    var authorName: String? = null
    for (line in lines) {
        val match = authorRegex.find(line)
        if (match != null) {
            authorName = match.groupValues[1].trim()
            break
        }
    }

    if (authorName == null) {
    }

    return mapOf("author" to authorName, "github_stars" to githubStars)
};1

