fun firstNonRepeated(s: String): Char? {
    val freq = mutableMapOf<Char, Int>()
    for (c in s) {
        freq[c] = freq.getOrDefault(c, 0) + 1
    }
    for (c in s) {
        if (freq[c] == 1) {
            return c
        }
    }
    return null
};1

fun fibonacci_sequence(n: Int): List<Int> {
    var a = 0
    var b = 1
    val fibSequence = mutableListOf<Int>()
    for (i in 0 until n) {
        fibSequence.add(a)
        val temp = a
        a = b
        b = temp + b
    }
    return fibSequence
};1

