import java.awt.Color
import java.awt.Graphics
import java.awt.image.BufferedImage
 
class BasicBitmapStorage(width: Int, height: Int) {
    val image = BufferedImage(width, height, BufferedImage.TYPE_3BYTE_BGR)
 
    fun fill(c: Color) {
        val g = image.graphics
        g.color = c
        g.fillRect(0, 0, image.width, image.height)
    }
 
    fun setPixel(x: Int, y: Int, c: Color) = image.setRGB(x, y, c.getRGB())
 
    fun getPixel(x: Int, y: Int) = Color(image.getRGB(x, y))
}
 
fun main(args: Array<String>) {
    // create BasicBitmapStorage object
    val width = 640
    val height = 640
    val bbs = BasicBitmapStorage(width, height)
    for (y in 0 until height) {
        for (x in 0 until width) {
            val c = Color(x % 256, y % 256, (x * y) % 256)
            bbs.setPixel(x, y, c)
        }
    }
 
    // now write the object in PPM format to ImageMagick's STDIN via a pipe
    // so it can be converted to a .jpg file and written to disk
    val pb = ProcessBuilder("convert", "-", "output_piped.jpg")
    pb.directory(null)
    pb.redirectInput(ProcessBuilder.Redirect.PIPE)
    val buffer = ByteArray(width * 3) // write one line at a time
    val proc = pb.start()
    val pStdIn = proc.outputStream
    pStdIn.use {
        val header = "P6\n$width $height\n255\n".toByteArray()
        with (it) {
            write(header)
            for (y in 0 until height) {
                for (x in 0 until width) {
                    val c = bbs.getPixel(x, y)
                    buffer[x * 3] = c.red.toByte()
                    buffer[x * 3 + 1] = c.green.toByte()
                    buffer[x * 3 + 2] = c.blue.toByte()
                }
                write(buffer)
            }
        }
    }
};0

fun countSteps(order: String, map: Map<String, LeftRightInstruction>): Long {
    var steps = 0L
    var currentNode = "AAA"

    while (currentNode != "ZZZ") {
        for (i in order.indices) {
            val nextNode = map[currentNode]!!

            currentNode = if (order[i] == 'R') {
                nextNode.right
            } else {
                nextNode.left
            }

            steps++
        }
    }

    return steps
};0

fun createRearrangements(seq: String): List<String> {
    if (seq.isEmpty()) return emptyList()
    val freq = mutableMapOf<Char, Int>()
    for (ch in seq) {
        freq[ch] = freq.getOrDefault(ch, 0) + 1
    }
    val chars = freq.keys.sorted()
    val n = seq.length
    val current = CharArray(n)
    val result = mutableListOf<String>()

    fun backtrack(pos: Int) {
        if (pos == n) {
            result.add(current.concatToString())
            return
        }
        for (ch in chars) {
            if (freq[ch] == 0) continue
            current[pos] = ch
            freq[ch] = freq[ch]!! - 1
            backtrack(pos + 1)
            freq[ch] = freq[ch]!! + 1
        }
    }

    backtrack(0)
    return result
};1

import kotlin.math.max
import kotlin.math.min
 
data class Point(var x: Int, var y: Int)
 
const val N = 32
const val K = 3
const val MAX = N * K
 
fun rot(n: Int, p: Point, rx: Int, ry: Int) {
    var t: Int
    if (ry == 0) {
        if (rx == 1) {
            p.x = n - 1 - p.x
            p.y = n - 1 - p.y
        }
        t = p.x
        p.x = p.y
        p.y = t
    }
}
 
fun d2pt(n: Int, d: Int, p: Point) {
    var s = 1
    var t = d
    var rx: Int
    var ry: Int
    p.x = 0
    p.y = 0
    while (s < n) {
        rx = 1 and (t / 2)
        ry = 1 and (t xor rx)
        rot(s, p, rx, ry)
        p.x += s * rx
        p.y += s * ry
        t /= 4
        s *= 2
    }
}
 
fun main() {
    var d: Int
    var x: Int
    var y: Int
    var cx: Int
    var cy: Int
    var px: Int
    var py: Int
    val pts = Array(MAX) { CharArray(MAX) {'' } }
    val curr = Point(0, 0)
    val prev = Point(0, 0)
    prev.x = prev.y = 0
    pts[0][0] = '.'
    for (d in 1 until N * N) {
        d2pt(N, d, curr)
        cx = curr.x * K
        cy = curr.y * K
        px = prev.x * K
        py = prev.y * K
        pts[cx][cy] = '.'
        if (cx == px) {
            if (py < cy) {
                for (y in py + 1 until cy) pts[cx][y] = '|'
            } else {
                for (y in cy + 1 until py) pts[cx][y] = '|'
            }
        } else {
            if (px < cx) {
                for (x in px + 1 until cx) pts[x][cy] = '_'
            } else {
                for (x in cx + 1 until px) pts[x][cy] = '_'
            }
        }
        prev.x = curr.x
        prev.y = curr.y
    }
    for (x in 0 until MAX) {
        for (y in 0 until MAX) print(pts[y][x])
        println()
    }
};1

 
