fun abundantOdd(searchFrom: Int, countFrom: Int, countTo: Int, printOne: Boolean): Int {
    var count = countFrom
    var n = searchFrom

    while (count < countTo) {
        val divs = divisors(n)
        val tot = divs.sum()
        if (tot > n) {
            count++
            if (!printOne || count >= countTo) {
                val s = divs.joinToString(" + ")
                if (printOne) {
                    println("$n < $s = $tot")
                } else {
                    println("%2d. %5d < %s = %d".format(count, n, s, tot))
                }
            }
        }

        n += 2
    }

    return n
};0

import kotlin.math.sqrt
 
val CHUNK_BYTES = 32 shl 8
val CHUNK_SIZE = CHUNK_BYTES shl 6
 
val field = IntArray(CHUNK_BYTES)
 
fun GET(x: Int) = field[x shr 6] and (1 shl (x shr 1 and 31))
fun SET(x: Int) { field[x shr 6] = field[x shr 6] or (1 shl (x shr 1 and 31)) }
 
class UArray(var e: IntArray = IntArray(16), var cap: Int = 16, var len: Int = 0)
 
fun push(a: UArray, n: Int) {
        if (a.len >= a.cap) {
                a.cap *= 2
                a.e = a.e.copyOf(a.cap)
        }
        a.e[a.len++] = n
}
 
var low = 0
fun init() {
        val f = BooleanArray(1 shl 16)
        push(primes, 2)
        push(offset, 0)
        for (p in 3 until 1 shl 16 step 2) {
                if (f[p]) continue
                for (q in p * p until 1 shl 16 step 2 * p) f[q] = true
                push(primes, p)
                push(offset, q)
        }
        low = 1 shl 16
}
 
fun sieve() {
        if (low == 0) init()
 
        field.fill(0)
 
        val hi = low + CHUNK_SIZE
        val ptop = sqrt(hi.toDouble()) * 2 + 1
 
        for (i in 1 until primes.len) {
                val p = primes.e[i] * 2
                if (p >= ptop) break
                for (q in offset.e[i] - low until CHUNK_SIZE step p)
                        SET(q)
                offset.e[i] = q + low
        }
 
        for (p in 1 until CHUNK_SIZE step 2)
                if (!GET(p)) push(primes, low + p)
 
        low = hi
}
 
val primes = UArray()
val offset = UArray()
 
fun main() {
        while (primes.len < 20) sieve()
        println("First 20:")
        for (i in 0 until 20)
                print(" ${primes.e[i]}")
        println()
 
        while (primes.e[primes.len - 1] < 150) sieve()
        println("Between 100 and 150:")
        for (i in 0 until primes.len) {
                val p = primes.e[i]
                if (p >= 100 && p < 150)
                        print(" $p")
        }
        println()
 
        while (primes.e[primes.len - 1] < 8000) sieve()
        var c = 0
        for (i in 0 until primes.len)
                if (primes.e[i] >= 7700 && primes.e[i] < 8000) c++
        println("$c primes between 7700 and 8000")
 
        for (c in 10..100000000 step 10) {
                while (primes.len < c) sieve()
                println("${c}th prime: ${primes.e[c - 1]}")
        }
};1

 
