    val input = readInputLines()[0]

    val groups = regex.matchEntire(input)!!.groups
    val (x0, x1) = groups[1]!!.value.substring(2).split("..").map { it.toInt() }
    val (y0, y1) = groups[2]!!.value.substring(2).split("..").map { it.toInt() }

