fun areSimilar(n: Int, points: List<Pair<Int, Int>>): String {
    if (n % 2 != 0) {
        return "NO"
    }
    val m = n / 2
    val sumX = points[0].first + points[m].first
    val sumY = points[0].second + points[m].second
    for (i in 0 until m) {
        val (x1, y1) = points[i]
        val (x2, y2) = points[i + m]
        if (x1 + x2 != sumX || y1 + y2 != sumY) {
            return "NO"
        }
    }
    return "YES"
};1

fun directedEulerianSegment(t: Int, cases: List<Triple<Int, Int, Int>>): List<List<Int>> {
    val result = mutableListOf<List<Int>>()
    for (case in cases) {
        val (n, l, r) = case
        val out = mutableListOf<Int>()
        val totalLen = n.toLong() * (n - 1) + 1
        fun findVertexAt(p: Long): Int {
            if (p == totalLen) {
                return 1
            }
            var count = 0L
            for (i in 1..n) {
                val cnt = 2L * (n - i)
                if (p <= count + cnt) {
                    val idx = p - count - 1
                    return if (idx % 2L == 0L) {
                        i
                    } else {
                        i + 1 + (idx / 2L).toInt()
                    }
                }
                count += cnt
            }
            return 1
        }
        for (pos in l..r) {
            out.add(findVertexAt(pos.toLong()))
        }
        result.add(out)
    }
    return result
};1

