fun generatePrimesDescSum(n: Int): Pair<List<Int>, Int> {
    fun isPrime(num: Int): Boolean {
        if (num < 2) return false
        if (num == 2) return true
        if (num % 2 == 0) return false
        var i = 3
        while (i * i <= num) {
            if (num % i == 0) return false
            i += 2
        }
        return true
    }
    val primes = (2..n).filter { isPrime(it) }.sortedDescending()
    val sumPrimes = primes.sum()
    return Pair(primes, sumPrimes)
};1

fun parseGrid2(map: List<String>): List<Tree> {
    val tmp = map.map { it.map { char -> char - '0' }.map { Tree(it) } }
    tmp.forEach { row -> row.zipWithNext().forEach { (prev, cur) -> cur.left = prev; prev.right = cur } }
    tmp.transpose().forEach { row -> row.zipWithNext().forEach { (prev, cur) -> cur.up = prev; prev.down = cur } }
    return tmp.flatten()
};0

import java.util.ArrayList
