fun main(args: Array<String>) {
    val digits = "123456789"
    val size = 4
    val choices = ArrayList<String>()
    for (i in 0..digits.length - size) {
        for (j in i + 1..digits.length - size + 1) {
            choices.add(digits.substring(i, j))
        }
    }
    Collections.shuffle(choices)
    val answers = ArrayList<String>()
    val scores = ArrayList<Pair<Int, Int>>()
    println("Playing Bulls & Cows with $size unique digits")
    while (true) {
        val ans = choices[0]
        answers.add(ans)
        val score = readLine()
        val bulls = score.substring(0, score.indexOf(',')).toInt()
        val cows = score.substring(score.indexOf(',') + 1).toInt()
        scores.add(Pair(bulls, cows))
        val found = bulls == size && cows == 0
        if (found) {
            println("Ye-haw!")
            break
        }
        choices.removeAll {
            scorecalc(it, ans)!= Pair(bulls, cows)
        }
        if (choices.isEmpty()) {
            println("Bad scoring? nothing fits those scores you gave:")
            for (i in 0..answers.size - 1) {
                println("${answers[i]} -> ${scores[i]}")
            }
            break
        }
    }
}
 
fun scorecalc(guess: String, chosen: String): Pair<Int, Int> {
    var bulls = 0
    var cows = 0
    for (i in 0..guess.length - 1) {
        if (guess[i] == chosen[i]) {
            bulls++
        } else if (chosen.contains(guess[i])) {
            cows++
        }
    }
    return Pair(bulls, cows)
};1

