class Queue {
    private val stack1 = ArrayDeque<Int>()
    private val stack2 = ArrayDeque<Int>()

    fun push(x: Int) {
        if (stack1.size + stack2.size >= 100) {
            return
        }
        stack1.addLast(x)
    }

    fun pop(): Int {
        if (stack2.isEmpty()) {
            while (stack1.isNotEmpty()) {
                stack2.addLast(stack1.removeLast())
            }
        }
        return stack2.removeLast()
    }

    fun peek(): Int {
        if (stack2.isEmpty()) {
            while (stack1.isNotEmpty()) {
                stack2.addLast(stack1.removeLast())
            }
        }
        return stack2.last()
    }

    fun empty(): Boolean {
        return stack1.isEmpty() && stack2.isEmpty()
    }

    // Exposing stacks for test inspection only
    val stack1View: List<Int> get() = stack1.toList()
    val stack2View: List<Int> get() = stack2.toList()
};1

