import java.util.*
 
object VarLenQuantity {
    fun toVlq(integer: Long): Long {
        val array = ByteArray(8)
        val buffer = toVlqCollection(integer)
               .dropWhile { b -> b == 0.toByte() }
               .reversed()
               .toByteArray()
        System.arraycopy(buffer, 0, array, 0, buffer.size)
        return java.lang.Long.parseLong(array.toString(), 16)
    }
 
    fun fromVlq(integer: Long): Long {
        val collection = java.lang.Long.toHexString(integer).reversed()
        return fromVlqCollection(collection)
    }
 
    fun toVlqCollection(integer: Long): List<Byte> {
        if (integer > Math.pow(2.0, 56.0))
            throw OverflowException("Integer exceeds max value.")
 
        var index = 7
        var significantBitReached = false
        var mask = 0x7fL shl (index * 7)
        val list = ArrayList<Byte>()
        while (index >= 0) {
            var buffer = mask and integer
            if (buffer > 0 || significantBitReached) {
                significantBitReached = true
                buffer = buffer shr index * 7
                if (index > 0)
                    buffer = buffer or 0x80.toLong()
                list.add(buffer.toByte())
            }
            mask = mask shr 7
            index--
        }
        return list
    }
 
    fun fromVlqCollection(vlq: String): Long {
        var integer = 0L
        var significantBitReached = false
 
        val enumerator = vlq.iterator()
        var index = 0
        while (enumerator.hasNext()) {
            var buffer = enumerator.next().toLong()
            if (buffer > 0 || significantBitReached) {
                significantBitReached = true
                integer = integer shl 7
                integer = integer or (buffer and 0x7fL)
            }
 
            if (++index == 8 || (significantBitReached && (buffer and 0x80L)!= 0x80L))
                break
        }
        return integer
    }
 
    @JvmStatic
    fun main(args: Array<String>) {
        val integers = longArrayOf(0x7fL shl 7 * 7, 0x80, 0x2000, 0x3FFF, 0x4000, 0x200000, 0x1fffff)
 
        for (original in integers) {
            println("Original: 0x" + java.lang.Long.toHexString(original))
 
            //collection
            val seq = toVlqCollection(original)
            println("Sequence: 0x" + seq.map { b -> b.toString(16) }.joinToString(""))
 
            val decoded = fromVlqCollection(seq.map { b -> b.toString(16) }.joinToString(""))
            println("Decoded: 0x" + java.lang.Long.toHexString(decoded))
 
