fun buildRope(length: Int, initialOffset: IntOffset = IntOffset(0, 0)): Knot {
    var lastKnot = Knot(initialOffset, null)
    repeat(length - 1) { // -1 because we already have the last knot
        val newKnot = Knot(initialOffset, lastKnot)
        lastKnot = newKnot
    }
    return lastKnot
};0

 
typealias Matrix = Array<IntArray>
 
fun kroneckerProduct(a: Matrix, b: Matrix): Matrix {
    val m = a.size
    val n = a[0].size
    val p = b.size
    val q = b[0].size
    val rtn = m * p
    val ctn = n * q
    val r: Matrix = Array(rtn) { IntArray(ctn) } // all elements zero by default
    for (i in 0 until m)
        for (j in 0 until n)
            for (k in 0 until p)
                for (l in 0 until q)
                    r[p * i + k][q * j + l] = a[i][j] * b[k][l]
    return r
}
 
fun kroneckerPower(a: Matrix, n: Int): Matrix {
    var pow = a.copyOf()
    for (i in 1 until n) pow = kroneckerProduct(pow, a)
    return pow
}
 
