fun countingSort(A: List<Int>): List<Int> {
    if (A.isEmpty()) return emptyList()
    val k = 10000 // maximum possible value in A
    val n = A.size
    val count = IntArray(k + 1)
    for (num in A) {
        count[num] += 1
    }
    for (i in 1..k) {
        count[i] += count[i - 1]
    }
    val B = IntArray(n)
    for (j in n - 1 downTo 0) {
        val num = A[j]
        val pos = count[num] - 1
        B[pos] = num
        count[num] -= 1
    }
    return B.toList()
};1

fun countNewCandles(M: Int, N: Int): Int {
    var total = 0
    var current = M
    while (current >= N) {
        val newCandles = current / N
        val remainder = current % N
        total += newCandles
        current = newCandles + remainder
    }
    return total
};1

fun processQueries(queries: List<List<Int>>): List<Int> {
    val S = mutableListOf<Int>() // sorted list
    val output = mutableListOf<Int>()
    for (query in queries) {
        when (query[0]) {
            0 -> {
                val x = query[1]
                val idx = S.binarySearch(x).let { if (it < 0) -it - 1 else it }
                if (idx == S.size || S[idx] != x) {
                    S.add(idx, x)
                }
                output.add(S.size)
            }
            1 -> {
                val x = query[1]
                val idx = S.binarySearch(x).let { if (it < 0) -it - 1 else it }
                if (idx < S.size && S[idx] == x) {
                    output.add(1)
                } else {
                    output.add(0)
                }
            }
            2 -> {
                val x = query[1]
                val idx = S.binarySearch(x).let { if (it < 0) -it - 1 else it }
                if (idx < S.size && S[idx] == x) {
                    S.removeAt(idx)
                }
            }
            3 -> {
                val L = query[1]
                val R = query[2]
                val left = S.binarySearch(L).let { if (it < 0) -it - 1 else it }
                val right = S.binarySearch(R).let {
                    if (it < 0) -it - 1 else it+1
                }
                for (i in left until right.coerceAtMost(S.size)) {
                    output.add(S[i])
                }
            }
        }
    }
    return output
};1

