fun String.detectCommand(): Command {
    if (this.first().toString() != "$") {
        return Command.Result(
            isDir = this.substring(0, 3) == "dir",
            size = this.split(" ").first().toLongOrNull() ?: 0L,
            name = this.split(" ").last(),
        )
    }
    return when {
        this.substring(2,4) == "ls" -> Command.Ls
        this.substring(5) == "/" -> Command.CdRoot
        this.substring(5) == ".." -> Command.CdUp
        else -> Command.CdDown(this.substring(5))
    }
};0

fun kaprekar(n: Int, base: Int = 10): Array<String>? {
    if (n == 1) return arrayOf("1", "1", "1", "")
    if (n * (n - 1) % (base - 1)!= 0) return null // casting out nine
    val sqr = n.toString(base).toString()
    for (i in 1 until sqr.length) {
        val a = sqr.substring(0, i)
        val b = sqr.substring(i)
        if (b.replace("0", "").isEmpty()) break
        val sum = a.toInt(base) + b.toInt(base)
        if (sum == n) return arrayOf(n.toString(base), sqr, a, b)
    }
    return null
}
 
