fun consolidate(sets: List<Set<String>>): List<Set<String>> {
    val setlist = sets.filter { it.isNotEmpty() }
    for (i in setlist.indices) {
        val s1 = setlist[i]
        if (s1.isNotEmpty()) {
            for (s2 in setlist.subList(i + 1, setlist.size)) {
                if (s1.disjoint(s2)) {
                    continue
                }
                s1.addAll(s2)
                s2.clear()
            }
        }
    }
    return setlist.filter { it.isNotEmpty() }
}
 
