fun filterProperties(properties: List<Map<String, Any?>>, filterArgs: Map<String, Any?>): List<Map<String, Any?>> {
    // Normalize filter arguments
    val cityPrefix = (filterArgs["city__startswith"]?.toString()?.lowercase())

    val countryRaw = filterArgs["country"]
    val countryFilter: Set<String>? = when (countryRaw) {
        null -> null
        is Iterable<*> -> countryRaw.mapNotNull { it?.toString()?.lowercase() }.toSet()
        else -> setOf(countryRaw.toString().lowercase())
    }

    val roomRaw = filterArgs["room_type"]
    val roomFilter: Set<String>? = when (roomRaw) {
        null -> null
        is Iterable<*> -> roomRaw.mapNotNull { it?.toString()?.lowercase() }.toSet()
        else -> setOf(roomRaw.toString().lowercase())
    }

    val priceLimit = when (val v = filterArgs["price__lte"]) {
        is Number -> v.toDouble()
        is String -> v.toDoubleOrNull()
        else -> null
    }

    fun passes(prop: Map<String, Any?>): Boolean {
        if (cityPrefix != null) {
            val cityVal = prop["city"]?.toString()?.lowercase()
            if (cityVal == null || !cityVal.startsWith(cityPrefix)) {
                return false
            }
        }
        if (countryFilter != null) {
            val countryVal = prop["country"]?.toString()?.lowercase()
            if (countryVal == null || countryVal !in countryFilter) {
                return false
            }
        }
        if (roomFilter != null) {
            val roomVal = prop["room_type"]?.toString()?.lowercase()
            if (roomVal == null || roomVal !in roomFilter) {
                return false
            }
        }
        if (priceLimit != null) {
            val priceRaw = prop["price"]
            val priceVal = when (priceRaw) {
                is Number -> priceRaw.toDouble()
                is String -> priceRaw.toDoubleOrNull()
                else -> null
            }
            if (priceVal == null || priceVal > priceLimit) {
                return false
            }
        }
        return true
    }
    return properties.filter { passes(it) }
};1

fun restsOn(current: Brick, other: Brick): Boolean {
