fun maxNonIncreasingLength(nums: List<Int>): Int {
    var maxLen = 0
    val n = nums.size
    for (i in 0 until n - 1) {
        if (nums[i] >= nums[i + 1]) {
            val current = n - i
            if (current > maxLen) {
                maxLen = current
            }
        }
    }
    return maxLen
};1

fun evaluate(x: Int, y: Int, z: Int): Any {
    // Case 1: x equals y
    if (x == y) {
        return if (x == 0) {
            "undefined"
        } else {
            Math.pow(x.toDouble(), z.toDouble()).toInt()
        }
    }
    // Case 2: x greater than y
    if (x > y) {
        return if (y == 0) {
            "undefined"
        } else {
            x % y
        }
    }
    // Case 3: x less than y
    if (x == 0) {
        return "undefined"
    }
    return y % x
};1

