import java.util.ArrayList
import java.util.List
 
/**
 * This class provides a main method that will, for each arg provided,
 * transform a String into a list of sub-strings, where each contiguous
 * series of characters is made into a String, then the next, and so on,
 * and then it will output them all separated by a comma and a space.
 */
object SplitStringByCharacterChange {
 
    @JvmStatic
    fun main(vararg args: String) {
        for (string in args) {
 
            val resultStrings = splitStringByCharacter(string)
            val output = formatList(resultStrings)
            println(output)
        }
    }
 
    /**
     * @param string String - String to split
     * @return List<\String> - substrings of contiguous characters
     */
    fun splitStringByCharacter(string: String): List<String> {
 
        val resultStrings = ArrayList<String>()
        val currentString = StringBuilder()
 
        for (pointer in 0 until string.length) {
 
            currentString.append(string[pointer])
 
            if (pointer == string.length - 1 || currentString[0]!= string[pointer + 1]) {
                resultStrings.add(currentString.toString())
                currentString.setLength(0)
            }
        }
 
        return resultStrings
    }
 
    /**
     * @param list List<\String> - list of strings to format as a comma+space-delimited string
     * @return String
     */
    fun formatList(list: List<String>): String {
 
        val output = StringBuilder()
 
        for (pointer in 0 until list.size) {
            output.append(list[pointer])
 
            if (pointer!= list.size - 1) {
                output.append(", ")
            }
        }
 
        return output.toString()
    }
};1

fun <T : Comparable<T>> sortList(arr: List<T>): List<T> {
    // Sorts a list of comparable elements (Int, Double, or String) in ascending order.
    // Assumes all elements are of a single, comparable type.
    return arr.sorted()
