import java.util.Arrays
import java.util.TreeSet
 
fun disjointSort(array: Array<Int>, indices: IntArray) {
    val sorted = indices.copyOf()
    Arrays.sort(sorted) { a, b -> array[a].compareTo(array[b]) }
    val swaps = TreeSet<Pair<Int, Int>>()
    for (i in indices.indices) {
        val a = indices[i]
        val b = sorted[i]
        if (a > b) {
            swaps.add(Pair(b, a))
        } else {
            swaps.add(Pair(a, b))
        }
    }
    for ((a, b) in swaps) {
        val temp = array[a]
        array[a] = array[b]
        array[b] = temp
    }
}
 
fun main() {
    val array = arrayOf(7, 6, 5, 4, 3, 2, 1, 0)
    val indices = intArrayOf(6, 1, 7)
    disjointSort(array, indices)
    println(Arrays.toString(array))
};1

import java.lang.Math.min
