fun solve(lines: List<Line>): Int {
    val points = mutableMapOf<Pair<Int, Int>, Int>()
    lines.forEach { line ->
        val dx = (line.x2 - line.x1).sign
        val dy = (line.y2 - line.y1).sign
        val length = max((line.x1 - line.x2).absoluteValue, (line.y1 - line.y2).absoluteValue)
        (0..length).map { i -> Pair(line.x1 + i * dx, line.y1 + i * dy) }.forEach { point ->
            points[point] = (points[point] ?: 0).plus(1)
        }
    }
    return points.count { it.value > 1 }
};0

fun trackGoals(matches: List<Map<String, Any>>): Map<String, Int> {
    val goalsByOpponent = mutableMapOf<String, Int>()
    for (match in matches) {
        val opponent = match["opponent"] as String
        val goals = match["goals"] as Int
        if (opponent in goalsByOpponent) {
            goalsByOpponent[opponent] = goalsByOpponent[opponent]!! + goals
        } else {
            goalsByOpponent[opponent] = goals
        }
    }
    return goalsByOpponent
};1

