fun isqrt(x: Int): Int {
    var q = 1
    var r = 0
    while (q <= x) {
        q = q shl 2
    }
    while (q > 1) {
        q = q shr 2
        val t = x - r - q
        r = r shr 1
        if (t >= 0) {
            x = t
            r = r + q
        }
    }
    return r
