//creates vector of length n, based on probability p for 1
fun createVector(n: Int, p: Double): List<Int> {
    val result = mutableListOf<Int>()
    for (i in 0 until n) {
        val number = Random.nextDouble()
        if (number <= p) {
            result.add(1)
        } else {
            result.add(0)
        }
    }
    return result
}
 
//find number of 1 runs in the vector
fun find_Runs(numberVector: List<Int>): Int {
    var runs = 0
    var found = 0
    while (found < numberVector.size) {
        if (numberVector[found] == 1) {
            runs++
            while (found < numberVector.size && numberVector[found] == 1) {
                found++
            }
        }
        found++
    }
    return runs
}
 
