fun appendCveToIps(ipList: List<Any>, cve: String): List<Map<String, List<String>>> {
    val ipToCves = mutableMapOf<String, MutableList<String>>()
    for (item in ipList) {
        if (item is Map<*, *>) {
            val ip = item["ip"]?.toString() ?: continue
            val cves = (item["cves"] as? List<*>)?.map { it.toString() } ?: emptyList()
            ipToCves.getOrPut(ip) { mutableListOf() }
            ipToCves[ip]?.addAll(cves.filter { it !in ipToCves[ip]!! })
        } else { // item is String (IP)
            val ip = item.toString()
            ipToCves.getOrPut(ip) { mutableListOf() }
        }
    }
    for ((ip, cves) in ipToCves) {
        if (cve !in cves) {
            cves.add(cve)
        }
    }
    return ipToCves.map { (ip, cves) -> mapOf("ip" to ip, "cves" to cves) }
};1

// 基于递归
fun printProbability1(number: Int) {
    if (number < 1) return
    val array = IntArray(number) { 1 }
    val sumArray = IntArray(MAX_VALUE * number - number + 1)
    fun sum(): Int {
        var sum = 0
        array.forEach { sum += it }
        return sum
    }
    fun printProbability(index: Int) {
        if (index >= number) {
            val sum = sum()
            sumArray[sum - number]++
            return
        }
        while (array[index] <= MAX_VALUE) {
            printProbability(index + 1)
            array[index]++
        }
        array[index] = 1
    }
    printProbability(0)
    var sum = 0
    sumArray.forEach { sum += it }
    for (i in sumArray.indices)
        println("和为：${i + number}，概率为：${sumArray[i]}/$sum")
};0

fun extractLayer(model: Any?, targetLayer: String): Any? {
    // If for some reason the current object isn't a Map, stop searching.
    if (model !is Map<*, *>) return null

    for ((layerName, subLayer) in model) {
        // Ensure key is a String
        if (layerName != targetLayer && layerName !is String) continue
        if (layerName == targetLayer) {
            return subLayer
        }
        // If the value is a map, descend recursively.
        if (subLayer is Map<*, *>) {
            val result = extractLayer(subLayer, targetLayer)
            if (result != null) {
                return result
            }
        }
    }
    // Layer not found in this branch.
    return null
};1

