    println("The first 30 gapful numbers are: ")
    /* Starting at 100, find 30 gapful numbers */
    findGap(100, 30)
 
    println("The first 15 gapful numbers > 1,000,000 are: ")
    findGap(1000000, 15)
 
    println("The first 10 gapful numbers > 1,000,000,000 are: ")
    findGap(1000000000, 10)
