fun firstNum(n: Int): Int {
    /*Divide by ten until the leading digit remains.*/
    var n = n
    while (n >= 10) {
        n /= 10
    }
    return n
}
 
fun lastNum(n: Int): Int {
    /*Modulo gives you the last digit. */
    return n % 10
}
 
fun findGap(n: Int, gaps: Int) {
    var count = 0
    while (count < gaps) {
 
        /* We have to convert our first and last digits to strings to concatenate.*/
        val concat = valueOf(firstNum(n)) + valueOf(lastNum(n))
        /* And then convert our concatenated string back to an integer. */
        val i = parseInt(concat)
 
        /* Modulo with our new integer and output the result. */
        if (n % i == 0) {
            print(n + " ")
            count++
            n++
        } else {
            n++
            continue
        }
    }
};1

fun replace_characters(text: String, characters: String, replacement: String): String {
    // Rule 1: `characters` is empty -> unchanged
    if (characters.isEmpty()) {
        return text
    }
    // Rule 2: `replacement` is empty -> remove all occurrences
    if (replacement.isEmpty()) {
        return text.filter { it !in characters }
    }
    // Rule 3: Length mismatch (and replacement isn't empty) -> unchanged
    if (characters.length != replacement.length) {
        return text
    }
    // Rule 4: Build a translation map and replace
    val mapping = characters.zip(replacement).toMap()
    return text.map { mapping[it] ?: it }.joinToString("")
};1

