import kotlin.math.sqrt
 
fun perfect(n: Int): Boolean {
    val max = sqrt(n.toDouble()).toInt() + 1
    var tot = 1
    var i = 2
    while (i < max) {
        if (n % i == 0) {
            tot += i
            val q = n / i
            if (q > i) {
                tot += q
            }
        }
        i++
    }
    return tot == n
}
 
