fun minimumDayToStart(n: Int, m: Int, k: List<Int>, offers: List<Pair<Int, Int>>): Int {
    val saleDays = MutableList(n) { mutableListOf<Int>() }
    for ((d, t) in offers) {
        saleDays[t - 1].add(d)
    }
    for (t in 0 until n) {
        saleDays[t].sort()
    }
    val sum2k = k.sumOf { 2 * it }
    val maxDj = offers.maxOfOrNull { it.first } ?: 0
    val upper = max(sum2k, maxDj)
    var low = 1
    var high = upper
    var answer = upper
    while (low <= high) {
        val mid = (low + high) / 2
        var sumTotal = 0
        for (i in 0 until n) {
            val ki = k[i]
            if (ki == 0) continue
            val idx = bisectRight(saleDays[i], mid) - 1
            val cost = if (idx < 0) {
                2 * ki
            } else {
                val d = saleDays[i][idx]
                val maxOnSale = minOf(ki, d)
                maxOnSale + 2 * (ki - maxOnSale)
            }
            sumTotal += cost
        }
        if (sumTotal <= mid) {
            answer = mid
            high = mid - 1
        } else {
            low = mid + 1
        }
    }
    return answer
}

fun bisectRight(a: List<Int>, x: Int): Int {
    var lo = 0
    var hi = a.size
    while (lo < hi) {
        val mid = (lo + hi) / 2
        if (x < a[mid]) hi = mid else lo = mid + 1
    }
    return lo
};1

fun canBeDissatisfaction(n: Int, k: Int, s: String): String {
    var currentStates = mutableSetOf<Pair<Int, Int>>()
    currentStates.add(Pair(0, 0))
    for (char in s) {
        val newStates = mutableSetOf<Pair<Int, Int>>()
        for ((cPrev, mPrev) in currentStates) {
            if (char == 'Y') {
                val newC = 0
                val newM = mPrev
                if (newC <= k && newM <= k) {
                    newStates.add(Pair(newC, newM))
                }
            } else if (char == 'N') {
                val newC = cPrev + 1
                val newM = maxOf(mPrev, newC)
                if (newC <= k && newM <= k) {
                    newStates.add(Pair(newC, newM))
                }
            } else {
                // char == '?'
                val newCY = 0
                val newMY = mPrev
                if (newCY <= k && newMY <= k) {
                    newStates.add(Pair(newCY, newMY))
                }
                val newCN = cPrev + 1
                val newMN = maxOf(mPrev, newCN)
                if (newCN <= k && newMN <= k) {
                    newStates.add(Pair(newCN, newMN))
                }
            }
        }
        currentStates = newStates
        if (currentStates.isEmpty()) {
            break
        }
    }
    val found = currentStates.any { (_, m) -> m == k }
    return if (found) "YES" else "NO"
};1

