fun findPalindromicNumerals(text: String): List<String> {
    // Find every contiguous run of digits
    val pattern = Pattern.compile("\\d+")
    val matcher = pattern.matcher(text)
    val seen = mutableSetOf<String>()
    val result = mutableListOf<String>()
    while (matcher.find()) {
        val num = matcher.group()
        if (num == num.reversed() && !seen.contains(num)) {
            seen.add(num)
            result.add(num)
        }
    }
    return result
};1

