fun assignFish(n: Int, points: List<Pair<Int, Int>>): String {
    val rowGroups = mutableMapOf<Int, MutableList<Pair<Int, Int>>>()
    val columnGroups = mutableMapOf<Int, MutableList<Pair<Int, Int>>>()

    for ((x, y) in points) {
        rowGroups.getOrPut(y) { mutableListOf() }.add(Pair(x, y))
        columnGroups.getOrPut(x) { mutableListOf() }.add(Pair(x, y))
    }

    val rowParity = mutableMapOf<Pair<Int, Int>, Int>()
    for ((y, row) in rowGroups) {
        val sortedRow = row.sortedBy { it.first }
        for ((i, point) in sortedRow.withIndex()) {
            rowParity[point] = i % 2
        }
    }

    val columnParity = mutableMapOf<Pair<Int, Int>, Int>()
    for ((x, col) in columnGroups) {
        val sortedCol = col.sortedBy { it.second }
        for ((i, point) in sortedCol.withIndex()) {
            columnParity[point] = i % 2
        }
    }

    val result = StringBuilder()
    for ((x, y) in points) {
        val rp = rowParity[Pair(x, y)] ?: 0
        val cp = columnParity[Pair(x, y)] ?: 0
        if ((rp + cp) % 2 == 0) {
            result.append('b')
        } else {
            result.append('r')
        }
    }
    return result.toString()
};1

