fun turn(base: Int, n: Int): Int {
    var sum = 0
    var n = n
    while (n!= 0) {
        val rem = n % base
        n /= base
        sum += rem
    }
    return sum % base
}
 
fun fairshare(base: Int, count: Int) {
    print("Base %2d: ".format(base))
    for (i in 0 until count) {
        val t = turn(base, i)
        print(" %2d".format(t))
    }
    println()
}
 
fun turnCount(base: Int, count: Int) {
    val cnt = IntArray(base)
 
    for (i in 0 until count) {
        val t = turn(base, i)
        cnt[t] = cnt[t] + 1
    }
 
    var minTurn = base * count
    var maxTurn = -1
    var portion = 0
    for (i in 0 until base) {
        if (cnt[i] > 0) {
            portion++
        }
        if (cnt[i] < minTurn) {
            minTurn = cnt[i]
        }
        if (cnt[i] > maxTurn) {
            maxTurn = cnt[i]
        }
    }
 
    print("  With %d people: ".format(base))
    if (0 == minTurn) {
        println("Only %d have a turn".format(portion))
    } else if (minTurn == maxTurn) {
        println("%d".format(minTurn))
    } else {
        println("%d or %d".format(minTurn, maxTurn))
    }
}
 
