fun diagonalSums(matrix: List<List<Int>>): Pair<Int, Int> {
    // Calculate the sums of the main diagonal and counter-diagonal
    // of a square 2-D list (matrix).
    val n = matrix.size
    var mainSum = 0
    var counterSum = 0

    for (i in 0 until n) {
        mainSum += matrix[i][i]              // (i, i) for main diagonal
        counterSum += matrix[i][n - 1 - i]   // (i, n-1-i) for counter-diagonal
    }

    return Pair(mainSum, counterSum)
};1

