fun getStatisticsPercentiles(
    dMin: Double?,
    stats: Map<String, Double?>,
    reference: Map<String, List<Double>>
): Map<String, Double?> {
    // If no resolution is supplied, nothing can be assessed
    if (dMin == null) {
        return stats.keys.associateWith { null }
    }

    val result = mutableMapOf<String, Double?>()
    for ((name, value) in stats) {
        // Missing value or no reference data → null
        if (value == null || !reference.containsKey(name) || reference[name]!!.isEmpty()) {
            result[name] = null
            continue
        }
        val refValues = reference[name]!!
        val total = refValues.size
        // Count how many reference values are <= the given statistic
        val countLe = refValues.count { it <= value }
        // Convert to percentile (0–100)
        val percentile = (countLe.toDouble() / total.toDouble()) * 100.0
        result[name] = percentile
    }
    return result
};1

