// Returns the index of first element greater than 'x' (number of elements <= x)
fun upperBound(list: List<Int>, x: Int): Int {
    var left = 0
    var right = list.size
    while (left < right) {
        val mid = (left + right) / 2
        if (list[mid] <= x) {
            left = mid + 1
        } else {
            right = mid
        }
    }
    return left
};1

