fun solveLoop(instrs: MutableList<Instruction>): Program.State {
    val flips = instrs.indices.filter { instrs[it].op != Operation.ACC }

    for (flipIdx in flips) {
        // flip the instruction in-place to its opposite
        flip(instrs, flipIdx)

        val (term, state) = Program(instrs).runToFirstLoop()
        if (term == Program.TerminationState.SUCCESS) {
            return state
        }

        // flip it back
        flip(instrs, flipIdx)
    }

    return Program.State(-1, 0)
};0

fun simulateNetworkGrowth(initialNodes: Int, newConnections: List<Pair<Int, Int>>): Map<Int, List<Int>> {
    val network = mutableMapOf<Int, MutableList<Int>>()
    for (node in 0 until initialNodes) {
        network[node] = mutableListOf()
    }
    for ((newNode, existingNode) in newConnections) {
        if (network[newNode] == null) {
            network[newNode] = mutableListOf()
        }
        if (network[existingNode] == null) {
            network[existingNode] = mutableListOf()
        }
        network[newNode]?.add(existingNode)
        network[existingNode]?.add(newNode)
    }
    // Convert mutable lists to immutable list before returning
    return network.mapValues { it.value.toList() }
};1

fun Node.findPathTo(target: Node): List<PathSegment>? {
    if (this === target) return emptyList()
    when (this) {
        is Leaf -> return null
        is Branch -> {
            val leftResult = left.findPathTo(target)
            if (leftResult != null) return leftResult + PathSegment(operation, true, right.result)
            val rightResult = right.findPathTo(target)
            if (rightResult != null) return rightResult + PathSegment(operation, false, left.result)
            return null
        }
    }
};0

fun merge(l1: List<Any>, l2: List<Any>, l3: List<Any>, l4: List<Any>): List<Any> {
    val maxLen = listOf(l1.size, l2.size, l3.size, l4.size).maxOrNull() ?: 0
    val out = mutableListOf<Any>()
    for (i in 0 until maxLen) {
        if (i < l1.size) out.add(l1[i])
        if (i < l2.size) out.add(l2[i])
        if (i < l3.size) out.add(l3[i])
        if (i < l4.size) out.add(l4[i])
    }
    return out
};1

