fun sonaPrimes(X: List<Int>): List<Int> {
    val n = X.size
    val primes = mutableListOf<Int>()
    for (i in 0 until n) {
        val current = X[i]
        var isPrime = true
        for (j in 0 until n) {
            if (i == j) continue
            if (current % X[j] == 0) {
                isPrime = false
                break
            }
        }
        if (isPrime) {
            primes.add(current)
        }
    }
    return primes
};1

import java.util.ArrayList
import java.util.HashMap
import java.util.function.Function
 
class Node(var length: Int, var edges: HashMap<Char, Int>, var suffix: Int) {
    constructor(l: Int) : this(l, HashMap(), 0)
    constructor(l: Int, m: HashMap<Char, Int>, s: Int) : this(l, m, s)
}
 
val evenRoot = 0
val oddRoot = 1
 
fun eertree(s: String): ArrayList<Node> {
    val tree = ArrayList<Node>()
    tree.add(Node(0, HashMap(), oddRoot))
    tree.add(Node(-1, HashMap(), oddRoot))
    var suffix = oddRoot
    var n: Int
    var k: Int
 
    for (i in 0 until s.length) {
        val c = s[i]
        for (n = suffix; ; n = tree[n].suffix) {
            k = tree[n].length
            val b = i - k - 1
            if (b >= 0 && s[b] == c) {
                break
            }
        }
 
        val it = tree[n].edges.entries.find { it.key == c }
        if (it!= null) {
            suffix = it.value
            continue
        }
        suffix = tree.size
        tree.add(Node(k + 2))
        tree[n].edges[c] = suffix
        if (tree[suffix].length == 1) {
            tree[suffix].suffix = 0
            continue
        }
        while (true) {
            n = tree[n].suffix
            val b = i - tree[n].length - 1
            if (b >= 0 && s[b] == c) {
                break
            }
        }
        tree[suffix].suffix = tree[n].edges[c]
    }
 
    return tree
}
 
fun subPalindromes(tree: ArrayList<Node>): ArrayList<String> {
    val s = ArrayList<String>()
 
    fun children(n: Int, p: String) {
        for ((c, m) in tree[n].edges) {
            val pl = c + p + c
            s.add(pl)
            children(m, pl)
        }
    }
    for ((c, n) in tree[1].edges) {
        val ct = c.toString()
        s.add(ct)
 
        children(n, ct)
    }
 
    return s
}
 
