fun calculateAverageScores(scores: List<Map<String, Any>>): Map<String, Double> {
    val studentScores = mutableMapOf<String, MutableList<Int>>()
    for (score in scores) {
        val name = score["name"] as String
        val scoreValue = when(val s = score["score"]) {
            is Int -> s
            is Number -> s.toInt()
            else -> 0
        }
        studentScores.getOrPut(name) { mutableListOf() }.add(scoreValue)
    }

    val averageScores = mutableMapOf<String, Double>()
    for ((name, scoresList) in studentScores) {
        val averageScore = scoresList.sum().toDouble() / scoresList.size
        averageScores[name] = "%.2f".format(averageScore).toDouble()
    }

    return averageScores
