data class Quadruple<A, B, C, D>(val first: A, val second: B, val third: C, val fourth: D)

fun listComparison(list1: List<Int>, list2: List<Int>): Quadruple<List<Int>, List<Int>, List<Int>, Int> {
    // Convert both lists to sets to obtain unique values.
    val set1 = list1.toSet()
    val set2 = list2.toSet()

    // Elements unique to list1 and list2
    val uniqueToList1 = (set1 - set2).toList()
    val uniqueToList2 = (set2 - set1).toList()

    // Common elements (without duplicates)
    val commonElements = (set1 intersect set2).toList()

    // Difference between sum(list1) and sum(list2)
    val sumDifference = list1.sum() - list2.sum()

    return Quadruple(uniqueToList1, uniqueToList2, commonElements, sumDifference)
};1

fun parseList(inp: String): Packet {
    val root = PacketList(null)
    var currentList = root
    val numberBuilder = NumberBuilder()

    inp.forEach {
        when (it) {
            '[' -> currentList = currentList.addList()
            ']' -> {
                numberBuilder.collectNumber()?.also { currentList.addElement(it) }
                currentList = currentList.parent!!
            }

            ' ' -> {}
            ',' -> numberBuilder.collectNumber()?.also { currentList.addElement(it) }
            else -> numberBuilder.addDigit(it - '0')
        }
    }
    return root.children[0]
};0

