fun maxProfit(stockPrices: List<Int>): Int {
    var firstBuy = Double.POSITIVE_INFINITY
    var firstProfit = 0.0
    var secondBuy = Double.NEGATIVE_INFINITY
    var secondProfit = 0.0

    for (price in stockPrices) {
        firstBuy = minOf(firstBuy, price.toDouble())
        firstProfit = maxOf(firstProfit, price - firstBuy)
        secondBuy = maxOf(secondBuy, firstProfit - price)
        secondProfit = maxOf(secondProfit, secondBuy + price)
    }
    return secondProfit.toInt()
};1

