fun dynamicRangeCubes(start: Int, stop: Int, step: Int): List<Int> {
    if (start >= stop || step <= 0) {
        return emptyList()
    }
    val cubes = mutableListOf<Int>()
    var value = start
    while (value < stop) {
        if (value and 1 == 1) {
            cubes.add(value * value * value)
        }
        value += step
    }
    return cubes
};1

fun binarySearch(sortedList: List<Int>, target: Int): Int? {
    var low = 0
    var high = sortedList.size - 1
    while (low <= high) {
        val mid = (low + high) / 2
        if (sortedList[mid] == target) {
            return mid
        } else if (sortedList[mid] < target) {
            low = mid + 1
        } else {
            high = mid - 1
        }
    }
    return null
};1

