fun num2ordinal(n: String): String {
    val conversion = n.toDouble().toInt()
    val num = spellInteger(conversion)
    val hyphen = num.split("-")
    val num2 = num.split(" ")
    var delim = " "
    if (num2[num2.size - 1].length > hyphen[hyphen.size - 1].length) {
        delim = "-"
    }
    if (num2[num2.size - 1] in irregularOrdinals) {
        num2[num2.size - 1] = delim + irregularOrdinals[num2[num2.size - 1]]
    } else if (num2[num2.size - 1].endsWith("y")) {
        num2[num2.size - 1] = delim + num2[num2.size - 1].substring(0, num2[num2.size - 1].length - 1) + "ieth"
    } else {
        num2[num2.size - 1] = delim + num2[num2.size - 1] + "th"
    }
    return num2.joinToString(" ")
}
 
