fun findMostCommonPattern(readings: List<String>): String? {
    val patternCounts = mutableMapOf<String, Int>()
    val firstSeen = mutableMapOf<String, Int>()
    for ((idx, pattern) in readings.withIndex()) {
        if (pattern !in patternCounts) {
            patternCounts[pattern] = 0
            firstSeen[pattern] = idx
        }
        patternCounts[pattern] = patternCounts[pattern]!! + 1
    }
    val maxCount = patternCounts.values.maxOrNull() ?: return null
    val candidates = patternCounts.filter { it.value == maxCount }.keys
    val sortedCandidates = candidates.sortedBy { firstSeen[it] }
    return sortedCandidates.firstOrNull()
};1

