import java.math.BigInteger
import java.util.*
 
// Return a vector of all fibonacci results from fib(1) to fib(n)
fun fib(n: Int): List<BigInteger> {
    val result = ArrayList<BigInteger>(n)
    var a = BigInteger.ZERO
    var b = BigInteger.ONE
 
    result.add(b)
 
    for (i in 1 until n) {
        val t = b
        b = a + b
        a = t
        result.add(b)
    }
 
    return result
}
 
// Return the first digit of a `BigInt`
fun firstDigit(x: BigInteger): Int {
    assert(x > BigInteger.ZERO)
 
    val s = x.toString(10)
 
    // parse the first digit of the stringified integer
    return s.substring(0, 1).toInt()
}
 
