    println("{:>13}    {:>10}".format("real", "predicted"))
    for (y in 1..9) {
        println("%d: %10.3f v. %10.3f".format(y, counter.getOrDefault(y, 0).toFloat() / N,
                (1.0 + 1.0 / (y.toFloat())).log10()))
    }
