fun maxOddSubarrays(testCases: List<Pair<Int, List<Int>>>): List<Int> {
    class FenwickTree(val size: Int) {
        private val tree = IntArray(size + 2) // 1-based indexing
        fun update(idxInput: Int, delta: Int) {
            var idx = idxInput
            while (idx <= size) {
                tree[idx] += delta
                idx += idx and -idx
            }
        }
        fun query(idxInput: Int): Int {
            var idx = idxInput
            var res = 0
            while (idx > 0) {
                res += tree[idx]
                idx -= idx and -idx
            }
            return res
        }
        fun rangeQuery(l: Int, r: Int): Int {
            if (l > r) return 0
            return query(r) - query(l - 1)
        }
    }
    val results = mutableListOf<Int>()
    for ((n, p) in testCases) {
        val ft = FenwickTree(n)
        var currentParity = 0
        var count = 0
        val currentElements = mutableListOf<Int>()
        for (x in p) {
            val c = ft.rangeQuery(x + 1, n)
            val newParity = (currentParity + c) % 2
            if (newParity == 1) {
                count += 1
                for (y in currentElements) {
                    ft.update(y, -1)
                }
                currentElements.clear()
                currentParity = 0
            } else {
                ft.update(x, 1)
                currentElements.add(x)
                currentParity = newParity
            }
        }
        results.add(count)
    }
    return results
};1

fun compareGeneticSimilarity(seq1: String, seq2: String): Double {
    val minLength = minOf(seq1.length, seq2.length)
    if (minLength == 0) {
        return 0.0
    }
    var matches = 0
    for (i in 0 until minLength) {
        if (seq1[i] == seq2[i]) {
            matches += 1
        }
    }
    val similarityPercentage = (matches.toDouble() / minLength.toDouble()) * 100.0
    return String.format("%.2f", similarityPercentage).toDouble()
};1

 
import java.math.BigInteger
 
val bigOne   = BigInteger.ONE
val bigTwo   = 2.toBigInteger()
val bigThree = 3.toBigInteger()
val bigTen   = BigInteger.TEN
 
class PExp(val prime: BigInteger, val exp: Long)
 
fun moTest(a: BigInteger, n: BigInteger) {
    if (!n.isProbablePrime(20)) {
        println("Not computed. Modulus must be prime for this algorithm.")
        return
    }
    if (a.bitLength() < 100) print("ord($a)") else print("ord([big])")
    if (n.bitLength() < 100) print(" mod $n ") else print(" mod [big] ")
    val mob = moBachShallit58(a, n, factor(n - bigOne))
    println("= $mob")
}
 
fun moBachShallit58(a: BigInteger, n: BigInteger, pf: List<PExp>): BigInteger {
    val n1 = n - bigOne
    var mo = bigOne
    for (pe in pf) {
        val y = n1 / pe.prime.pow(pe.exp.toInt())
        var o = 0L
        var x = a.modPow(y, n.abs())
        while (x > bigOne) {
            x = x.modPow(pe.prime, n.abs())
            o++
        }
        var o1 = o.toBigInteger()
        o1 = pe.prime.pow(o1.toInt())
        o1 /= mo.gcd(o1)
        mo *= o1
    }
    return mo
}
 
fun factor(n: BigInteger): List<PExp> {
    val pf = mutableListOf<PExp>()
    var nn = n
    var e = 0L
    while (!nn.testBit(e.toInt())) e++
    if (e > 0L) {
        nn = nn shr e.toInt()
        pf.add(PExp(bigTwo, e))
    }
    var s = bigSqrt(nn)
    var d = bigThree
    while (nn > bigOne) {
        if (d > s) d = nn
        e = 0L
        while (true) {
            val (q, r) = nn.divideAndRemainder(d)
            if (r.bitLength() > 0) break
            nn = q
            e++
        }
        if (e > 0L) {
            pf.add(PExp(d, e))
            s = bigSqrt(nn)
        }
        d += bigTwo
    }
    return pf
}
 
fun bigSqrt(n: BigInteger): BigInteger {
    var b = n
    while (true) {
        val a = b
        b = (n / a + a) shr 1
        if (b >= a) return a
    }
}
 
