    var b = bigTen.pow(100) + bigOne
    moTest(b, 7919.toBigInteger())
 
    b = bigTen.pow(1000) + bigOne
    moTest(b, BigInteger("15485863"))
 
    b = bigTen.pow(10000) - bigOne
    moTest(b, BigInteger("22801763489"))
 
