fun swapValues(lst: List<Any>, val1: Any, val2: Any): List<Any> {
    // Verify that both values are present at least once; otherwise throw
    if (!lst.contains(val1) || !lst.contains(val2)) {
        throw IllegalArgumentException("The list must contain both values to be swapped.")
    }
    // Construct the new list with swapped values
    return lst.map { item ->
        when (item) {
            val1 -> val2
            val2 -> val1
            else -> item
        }
    }
