import kotlin.system.measureTimeMillis
 
typealias Pancakes = List<Int>
 
fun flip(pancakes: Pancakes, position: Int): Pancakes {
    return pancakes.take(position).reversed() + pancakes.drop(position)
}
 
fun pancake(n: Int): Pair<Pancakes, Int> {
    val initStack = (1..n).toList()
    val stackFlips = mutableMapOf(initStack to 0)
    val queue = ArrayDeque<Pancakes>()
    queue.add(initStack)
 
    while (queue.isNotEmpty()) {
        val stack = queue.removeFirst()
        val flips = stackFlips[stack]!! + 1
 
        for (i in 2..n) {
            val flipped = flip(stack, i)
            if (flipped!in stackFlips) {
                stackFlips[flipped] = flips
                queue.add(flipped)
            }
        }
    }
 
    return stackFlips.maxBy { it.value }!!
}
 
fun main() {
    val time = measureTimeMillis {
        for (n in 1..9) {
            val (pancakes, p) = pancake(n)
            println("pancake($n) = $p. Example: $pancakes")
        }
    }
 
    println("\nTook $time milliseconds.")
};1

fun String.collapse(): String {
    var str = this
    for (i in 0 until str.length) {
        while (str[i] == str[i + 1]) str = str.substring(0, i) + str.substring(i + 1)
    }
    return str
}
 
