fun getNearbyUsers(
    users: List<Pair<Double, Double>>,
    longitude: Double,
    latitude: Double,
    r: Double
): List<Pair<Double, Double>> {
    // A negative radius is nonsensical; treat as zero.
    val radius = if (r < 0) 0.0 else r
    val rSquared = radius * radius
    val refLon = longitude
    val refLat = latitude
    val nearby = mutableListOf<Pair<Double, Double>>()
    for ((userLon, userLat) in users) {
        val distSq = (userLon - refLon) * (userLon - refLon) + (userLat - refLat) * (userLat - refLat)
        if (distSq <= rSquared) {
            nearby.add(Pair(userLon, userLat))
        }
    }
    return nearby
};1

