fun fibonacci(n: Int): List<Int> {
    if (n <= 0) {
        return emptyList()
    }

    val fibSequence = mutableListOf(0)
    if (n == 1) {
        return fibSequence
    }

    fibSequence.add(1)
    for (i in 2 until n) {
        fibSequence.add(fibSequence[fibSequence.size - 1] + fibSequence[fibSequence.size - 2])
    }
    return fibSequence
};1

fun determineStacks(
    positionToIndex: List<Pair<Int, Int>>,
    input: List<String>,
    splitIndex: Int
): Map<Int, Stack<Char>> {
    val stacks = buildMap<Int, Stack<Char>> {
        positionToIndex.forEach {
            this[it.first] = Stack()
        }
    }

    input.subList(0, splitIndex - 1)
        .reversed()
        .forEach {
            positionToIndex
                .forEach { p ->
                    if (p.second <= it.length && it[p.second].toString().trim().isNotEmpty()) {
                        val characterToStore = it[p.second]
                        stacks[p.first]?.push(characterToStore)
                    }
                }
        }

    return stacks
