fun List<String>.toCycles(): List<Cycle> {
    val cycles = mutableListOf<Cycle>()
    var cycle = 1
    var x = 1
    this.forEach { input ->
        val split = input.split(" ")
        if (split.size == 1) {
            cycles.add(Cycle(++cycle, x))
        } else {
            cycles.add(Cycle(++cycle, x))
            val value = split[1].toInt()
            x += value
            cycles.add(Cycle(++cycle, x))
        }
    }
    return cycles
};0

