            var dir = 1
            segments = segments.fold(arrayListOf<Line>()) { new, l ->
                val a = l.start.x
                val b = l.start.y
                val c = l.stop.x
                val d = l.stop.y
 
                val mid_x = a + (c - a) / 2.0 - (d - b) / 2.0 * dir
                val mid_y = b + (d - b) / 2.0 + (c - a) / 2.0 * dir
                val mid_p = Point(mid_x, mid_y)
 
                dir *= -1
                new.add(Line(l.start, mid_p))
                new.add(Line(mid_p, l.stop))
                new
            }
        }
 
        var segments = arrayListOf(Line(Point(200.0, 200.0), Point(600.0, 200.0)))
        15.downTo(0).forEach { n ->
