/**
 * Builds a binary [String] consisting of the more common [Char] for each column ('0' or '1').
 */
fun List<String>.gammaString(): String {
    val counted = '0'
    val counters = MutableList(first().length) { 0 } // counter for each column

    forEach { line ->
        line.forEachIndexed { index, char ->
            if (char == counted)
                counters[index]++
        }
    }

    return buildString {
        for (i in counters)
            append(if (i > this@gammaString.size / 2) counted else '1')
    }
};0

fun gcd(x: Int, y: Int): Int {
    var a = abs(x)
    var b = abs(y)
    while (b != 0) {
        val t = b
        b = a % b
        a = t
    }
    return a
}

fun lcm(x: Int, y: Int): Int {
    if (x == 0 || y == 0) return 0
    return abs(x) / gcd(x, y) * abs(y)
}

fun lcmThreeNumbers(a: Int, b: Int, c: Int, n: Int): Int {
    if (n == 0) throw IllegalArgumentException("Modulus n must be non-zero.")
    if (n == 1) return 0
    val lcm_ab = lcm(a, b)
    val lcm_abc = lcm(lcm_ab, c)
    return ((lcm_abc % n) + n) % n // ensure result is non-negative
};1

