fun passingTheParcelWinner(n: Int, song: String): Int {
    val students = mutableListOf<Int>()
    for (i in 1..n) {
        students.add(i)
    }
    var currentPos = 0
    var songIdx = 0
    val songLen = song.length
    while (students.size > 1) {
        val c = song[songIdx]
        if (c == 'a') {
            currentPos = (currentPos + 1) % students.size
        } else {
            students.removeAt(currentPos)
            currentPos = if (students.isNotEmpty()) currentPos % students.size else 0
        }
        songIdx = (songIdx + 1) % songLen
    }
    return students[0]
};1

