fun countDivisorsWithCommonDigit(x: Int): Int {
    val xDigits = x.toString().toSet()
    val divisors = mutableSetOf<Int>()
    val sqrtX = sqrt(x.toDouble()).toInt()
    for (i in 1..sqrtX) {
        if (x % i == 0) {
            divisors.add(i)
            divisors.add(x / i)
        }
    }
    var count = 0
    for (d in divisors) {
        if (d.toString().any { it in xDigits }) {
            count += 1
        }
    }
    return count
};1

