fun isPrime(n: Int): Boolean {
    if (n < 2) return false
    if (n == 2) return true
    if (n % 2 == 0) return false
    val limit = sqrt(n.toDouble()).toInt() + 1
    for (factor in 3..limit step 2) {
        if (n % factor == 0) return false
    }
    return true
}

