// Pre-defined, canonical tiers (order matters for the first–match rule)
private val PREDEFINED_TIERS: List<Triple<String, String, String>> = listOf(
    Triple("WebServer", "Standard",  "1.0"),
    Triple("Worker",    "SQS/HTTP",  "1.0"),
    Triple("Worker",    "SQS/HTTP",  "1.1"),
    Triple("Worker",    "SQS/HTTP",  "")           // empty version  ==> wildcard
)

fun splitIntoThree(s: String): Triple<String, String, String> {
    val parts = s.split(":")
    val list = when {
        parts.size > 3 -> parts.subList(0, 2) + listOf(parts.subList(2, parts.size).joinToString(":"))
        else -> parts
    }.toMutableList()
    while (list.size < 3) {
        list.add("")
    }
    return Triple(list[0], list[1], list[2])
}

fun parseTier(tierString: String?): Triple<String, String, String>? {
    if (tierString == null || tierString.trim().isEmpty()) {
        return null
    }

    val (inService, inDeployment, inVersion) = splitIntoThree(tierString.trim())

    if (inService.isEmpty()) {
        return null
    }

    val inServiceL = inService.lowercase()
    val inDeploymentL = inDeployment.lowercase()
    val inVersionL = inVersion.lowercase()

    for ((service, deployment, version) in PREDEFINED_TIERS) {
        // Service type must match
        if (inServiceL != service.lowercase()) {
            continue
        }

        // Deployment type must match if it is specified in the input
        if (inDeployment.isNotEmpty() && inDeploymentL != deployment.lowercase()) {
            continue
        }

        // Version checks
        if (inVersion.isNotEmpty()) {
            // Input specifies a version. It must match unless the predefined
            // version is a wildcard (empty).
            if (version.isNotEmpty() && inVersionL != version.lowercase()) {
                continue
            }
        }
        // else: input version omitted, so any predefined version matches

        // All checks passed - construct the result.
        val outDeployment = deployment
        val outVersion = if (version.isNotEmpty()) version else inVersion
        return Triple(service, outDeployment, outVersion)
    }
    return null
};1

fun calculateWordStats(text: String): Pair<Int, Double> {
    val words = text.split(" ").filter { it.isNotEmpty() }
    if (words.isEmpty()) {
        return Pair(0, 0.0)
    }
    val totalWords = words.size
    val wordLengthsSum = words.sumBy { it.length }
    val averageWordLength = (wordLengthsSum.toDouble() / totalWords).let { String.format("%.2f", it).toDouble() }
    return Pair(totalWords, averageWordLength)
};1

fun parseListPacket(line: String): ListPacket {
    val stack: Deque<ListPacket> = ArrayDeque()
    var isParsingNumber = false
    var number = 0

    fun pushChildUp() {
        if (stack.size > 1) {
            val inner = stack.pop()
            val outer = stack.pop()
            stack.push(outer.addChild(inner))
        }
    }

    fun pushNumber() {
        if (isParsingNumber) {
            val list = stack.pop()
            stack.push(list.addChild(IntPacket(number)))
            isParsingNumber = false
            number = 0
        }
    }

    for (c in line) {
        when (c) {
            '[' -> stack.push(ListPacket())
            ']' -> {
                pushNumber()
                pushChildUp()
            }
            ',' -> pushNumber()
            in '0'..'9' -> {
                isParsingNumber = true
                number = number * 10 + c.digitToInt()
            }
            else -> throw IllegalStateException("Unexpected character: '$c'")
        }
    }

    while (stack.size > 1) {
        pushChildUp()
    }

    return stack.single()
};0

