    var totalcount = 0
    val dates = HashMap<Int, String>()
 
    val inputStream: InputStream = File("readings.txt").inputStream()
    inputStream.bufferedReader().useLines { lines ->
        lines.forEach {
            var line = multiWhite.matcher(it).replaceAll(" ")
            val splitLine = line.split(" ")
            if (splitLine.size!= 49)
                missformcount++
            if (!dateEx.matcher(splitLine[0]).matches())
                missformcount++
            else
                dates.put(totalcount + 1, dateEx.matcher(splitLine[0]).group())
            var err = 0
            for (i in 1..splitLine.size - 1) {
                if (i % 2!= 0) {
                    if (!valEx.matcher(splitLine[i]).matches())
                        err++
                } else {
                    if (!flagEx.matcher(splitLine[i]).matches())
                        err++
                }
            }
            if (err!= 0) missformcount++
            totalcount++
        }
    }
 
    val goodEntries = totalcount - missformcount
    val dateReverse = HashMap<String, ArrayList<Int>>()
 
    for ((k, v) in dates) {
        if (!dateReverse.containsKey(v))
            dateReverse.put(v, ArrayList<Int>())
        dateReverse.get(v)?.add(k)
    }
 
    println(goodEntries + " valid Records out of " + totalcount)
 
    for ((k, v) in dateReverse) {
        if (v.size > 1)
            println("$k is duplicated at Lines : ${v.joinToString(",")}")
    }
};1

fun catchFish(fishWeights: List<Double>, targetWeight: Double): Double? {
