fun sumDigits(n: Long, base: Long): Long {
    var sum = 0L
    var n = n
    while (n > 0) {
        sum += n % base
        n /= base
    }
    return sum
}
 
// Returns tuple of (additive-persistence, digital-root)
fun digitalRoot(num: Long, base: Long): Pair<Long, Long> {
    var pers = 0L
    var num = num
    while (num >= base) {
        pers++
        num = sumDigits(num, base)
    }
    return Pair(pers, num)
}
 
