fun findPrefix(strs: List<String>): String {
    if (strs.isEmpty()) return ""
    val shortest = strs.minByOrNull { it.length } ?: return ""
    for ((i, c) in shortest.withIndex()) {
        for (other in strs) {
            if (other[i] != c) {
                return shortest.substring(0, i)
            }
        }
    }
    return shortest
}

fun longestCommonPrefix(strLists: List<List<String>>): List<String> {
    return strLists.map { findPrefix(it) }
