fun solve() {
    val n = readInt()
    val nei = List(n) { mutableListOf<Int>() }
    repeat(n - 1) {
        val (v, u) = readInts().map { it - 1 }
        nei[v].add(u)
        nei[u].add(v)
    }
    val kids = IntArray(n)
    val isLeaf = BooleanArray(n)
    val isBud = BooleanArray(n)
    var ans = 0
    fun dfs(v: Int, p: Int = -1) {
        var nonLeaves = false
        for (u in nei[v]) {
            if (u == p) continue
            dfs(u, v)
            if (isBud[u]) continue
            kids[v]++
            if (!isLeaf[u]) nonLeaves = true
        }
        isLeaf[v] = (p != -1 && kids[v] == 0)
        isBud[v] = (p != -1 && !nonLeaves && !isLeaf[v])
        if (isBud[v]) ans--
        if (isLeaf[v]) ans++
        if (v == 0 && kids[v] == 0) ans++
    }
    dfs(0)
    println(ans)
};0

 
fun expandRange(s: String): MutableList<Int> {
    val list = mutableListOf<Int>()
    val items = s.split(',')
    var first: Int
    var last:  Int
    for (item in items) {
        val count = item.count { it == '-' }
        if (count == 0 || (count == 1 && item[0] == '-'))
            list.add(item.toInt())
        else {
            val items2 = item.split('-')
            if (count == 1) {
                first = items2[0].toInt()
                last  = items2[1].toInt()
            }
            else if (count == 2) {
                first = items2[1].toInt() * -1
                last  = items2[2].toInt()
            }
            else {
                first = items2[1].toInt() * -1
                last  = items2[3].toInt() * -1
            }
            for (i in first..last) list.add(i)
        }
    }
    return list
}
 
