fun decimalToBinary(n: Int): String {
    if (n == 0) return "0"
    val binary = mutableListOf<String>()
    var num = n
    while (num > 0) {
        val remainder = num % 2
        binary.add(remainder.toString())
        num /= 2
    }
    return binary.reversed().joinToString("")
