fun IntArray.nextInCycle(index: Int) = this[index % this.size]
 
fun IntArray.kolakoski(len: Int): IntArray {
    val s = IntArray(len)
    var i = 0
    var k = 0
    while (true) {
        s[i] = this.nextInCycle(k)
        if (s[k] > 1) {
            repeat(s[k] - 1) {
                if (++i == len) return s
                s[i] = s[i - 1]
            }
        }
        if (++i == len) return s
        k++
    }
}
 
fun IntArray.possibleKolakoski(): Boolean {
    val len = this.size
    val rle = mutableListOf<Int>()
    var prev = this[0]
    var count = 1
    for (i in 1 until len) {
        if (this[i] == prev) {
            count++
        }
        else {
            rle.add(count)
            count = 1
            prev = this[i]
        }
    }
    // no point adding final 'count' to rle as we're not going to compare it anyway
    for (i in 0 until rle.size) {
        if (rle[i] != this[i]) return false
    }
    return true
}
 
fun main(args: Array<String>) {
    val ias = listOf(
        intArrayOf(1, 2), intArrayOf(2, 1),
        intArrayOf(1, 3, 1, 2), intArrayOf(1, 3, 2, 1)
    )
    val lens = intArrayOf(20, 20, 30, 30)
    for ((i, ia) in ias.withIndex()) {
        val len = lens[i]
        val kol = ia.kolakoski(len)
        println("First $len members of the sequence generated by ${ia.asList()}:")
        println(kol.asList())
        val p = kol.possibleKolakoski()
        println("Possible Kolakoski sequence? ${if (p) "Yes" else "No"}\n")
    }
};0

import java.lang.Boolean
import java.lang.String
import java.lang.System
 
/// <summary>
/// Extension methods on nullable bool.
/// </summary>
/// <remarks>
/// The operators !, & and | are predefined.
/// </remarks>
object NullableBoolExtension {
    fun Boolean?.implies(right: Boolean?): Boolean? {
        return!this or right
    }
 
    fun Boolean?.isEquivalentTo(right: Boolean?): Boolean? {
        return if (this!= null && right!= null) this == right else null
    }
 
    fun Boolean?.format(): String {
        return if (this!= null) this.toString() else "Maybe"
    }
}
 
object Program {
    @JvmStatic
    fun main(args: Array<String>) {
        val values = arrayOf(true, null, false)
 
        for (left in values) {
            println("¬" + left.format() + " = " + (!left).format())
            for (right in values) {
                println(left.format() + " & " + right.format() + " = " + (left and right).format())
                println(left.format() + " | " + right.format() + " = " + (left or right).format())
                println(left.format() + " → " + right.format() + " = " + left.implies(right).format())
                println(left.format() + " ≡ " + right.format() + " = " + left.isEquivalentTo(right).format())
            }
        }
    }
};1

