fun summarizeProjects(projects: List<Map<String, Any>>): Map<String, Map<String, Any>> {
    val summary = mutableMapOf<String, MutableMap<String, Any>>()
    for (project in projects) {
        val region = project["region"] as String
        val budget = project["budget"] as Double
        val completed = project["completed"] as Boolean
        if (!summary.containsKey(region)) {
            summary[region] = mutableMapOf("total_budget" to 0.0, "completed_projects" to 0)
        }
        val regionSummary = summary[region]!!
        regionSummary["total_budget"] = (regionSummary["total_budget"] as Double) + budget
        if (completed) {
            regionSummary["completed_projects"] = (regionSummary["completed_projects"] as Int) + 1
        }
    }
    return summary
};1

