    bucket: String?,
    tarball: String?
): String {
    // Select the correct config file
    val (config, extraSub) = if (bucket != null) {
        Pair(
            "$bazelToolchainsBaseDir/container/cloudbuild.yaml",
            ",_BUCKET=$bucket,_TARBALL=$tarball"
        )
    } else {
        Pair(
            "$bazelToolchainsBaseDir/container/cloudbuild_no_bucket.yaml",
            ""
        )
    }

    // Decide whether to append the async flag
    val asyncFlag = if (async_) " --async" else ""

    // Assemble the command
    val command = buildString {
        append("gcloud builds submit . ")
        append("--config=$config ")
        append("--substitutions ")
        append("_PROJECT=$project,_CONTAINER=$container,")
        append("_BAZEL_VERSION=$bazelVersion,_TAG=$tag,")
        append("_PACKAGE=$pkg,_TARGET=$target")
        append(extraSub)
        append(" --machine-type=n1-highcpu-32")
        append(asyncFlag)
    }

    return command
};1

