// This is a template function that works for any array-like object
fun <Array> demonstrate(array: Array)
{
  // Array element access
  array[2] = "Three"  // Fast, but unsafe - if the index is out of bounds you
                      // get undefined behaviour
  array.at(1) = "Two" // *Slightly* less fast, but safe - if the index is out
                      // of bounds, an exception is thrown
 
  // Arrays can be used with standard algorithms
  array.reverse()
  array.forEach { element ->
    println(element)
  }
 
  println()
}
 
fun main()
{
  // Compile-time sized fixed-size array
  val fixed_size_array = arrayOf("One", "Four", "Eight")
  // If you do not supply enough elements, the remainder are default-initialized
 
  // Dynamic array
  val dynamic_array = mutableListOf("One", "Four")
  dynamic_array.add("Eight") // Dynamically grows to accept new element
 
  // All types of arrays can be used more or less interchangeably
  demonstrate(fixed_size_array)
  demonstrate(dynamic_array)
};1

fun addTranslation(
    translations: MutableList<MutableMap<String, String>>?,
    newTranslation: String,
    langCode: String
): MutableList<MutableMap<String, String>> {
    // Guard against null; treat it as an empty list
    val result = translations ?: mutableListOf()
    for (entry in result) {
        if (entry["language"] == langCode) {
            entry["text"] = newTranslation
            return result
        }
    }
    // Language not found → append a new entry
    result.add(mutableMapOf("language" to langCode, "text" to newTranslation))
    return result
};1

