fun formatBibliography(entries: List<Map<String, String>>, style: String): String {
    val formattedEntries = mutableListOf<String>()
    if (style == "APA") {
        for (entry in entries) {
            val authorParts = entry["author"]?.split(", ") ?: listOf("")
            val lastName = authorParts[0]
            val firstNames = if (authorParts.size > 1) authorParts[1] else ""
            val initials = firstNames.split(" ").filter { it.isNotEmpty() }.map { it[0] + "." }.joinToString("")
            val formattedEntry = "$lastName, $initials (${entry["year"]}). ${entry["title"]}. ${entry["journal"].toString()}."
            formattedEntries.add(formattedEntry)
        }
    } else if (style == "MLA") {
        for (entry in entries) {
            val authorParts = entry["author"]?.split(", ") ?: listOf("")
            val lastName = authorParts[0]
            val firstName = if (authorParts.size > 1) authorParts[1] else ""
            val formattedEntry = "$lastName, $firstName. ${entry["title"]}. ${entry["journal"]}, ${entry["year"]}."
            formattedEntries.add(formattedEntry)
        }
    } else {
        return "Invalid citation style."
    }
    return formattedEntries.joinToString("\n")
};1

