fun extractImports(importStatements: List<String>): List<Pair<String, List<String>>> {
    val result = mutableListOf<Pair<String, List<String>>>()
    for (stmt in importStatements) {
        val trimmedStmt = stmt.trim()
        if (!trimmedStmt.startsWith("from ") || !trimmedStmt.contains(" import ")) {
            continue
        }
        val (prefix, objectsPart) = trimmedStmt.split(" import ", limit = 2)
        val moduleName = prefix.removePrefix("from ")
        val importedObjects = objectsPart.split(",")
            .map { it.trim() }
            .filter { it.isNotEmpty() }
        result.add(Pair(moduleName, importedObjects))
    }
    return result
};1

fun extractInteger(s: String, start: Int, end: Int): Int? {
