fun gcd(a: Int, b: Int): Int {
    var x = a
    var y = b
    while (y != 0) {
        val t = y
        y = x % y
        x = t
    }
    return x
}

fun smallestBase(p: Int, q: Int): Int {
    val g = gcd(p, q)
    var denominator = q / g
    if (denominator == 1) {
        return 2
    }
    var n = denominator
    val factors = mutableSetOf<Int>()
    var i = 2
    while (i * i <= n) {
        if (n % i == 0) {
            factors.add(i)
            while (n % i == 0) {
                n /= i
            }
        }
        i += 1
    }
    if (n > 1) {
        factors.add(n)
    }
    var product = 1
    for (prime in factors) {
        product *= prime
    }
    return product
};1

