fun solveDiagonal(n: Int, d0: Int, d1: Int): List<IntArray>? {
    val code = "$n $d0 $d1"
    if (code in memo) return memo[code]
    val a = List(n) { IntArray(n) { -1 } }
    a.indices.forEach { i -> a[i][i] = 0 }
    a[0][0] = d0
    a[1][1] = d1
    memo[code] = if (d1 >= n) null else search(a)
    return memo[code]
};0

import java.math.BigInteger
