fun findIntersection(nums1: List<Int>, nums2: List<Int>, maxIntersectionSize: Int): Pair<List<Int>, Boolean> {
    val set1 = mutableMapOf<Int, Boolean>()
    for (n in nums1) {
        if (!set1.containsKey(n)) {
            set1[n] = true
        }
    }
    val set2 = mutableMapOf<Int, Boolean>()
    for (n in nums2) {
        if (!set2.containsKey(n)) {
            set2[n] = true
        }
    }
    val intersectionSet = mutableListOf<Int>()
    for ((key, _) in set1) {
        if (set2.containsKey(key)) {
            intersectionSet.add(key)
        }
    }
    val seen = mutableMapOf<Int, Boolean>()
    val uniqueList = mutableListOf<Int>()
    for (x in intersectionSet) {
        if (!seen.containsKey(x)) {
            uniqueList.add(x)
            seen[x] = true
        }
    }
    return if (uniqueList.size > maxIntersectionSize) Pair(emptyList(), true) else Pair(uniqueList, false)
};1

 
