fun MutableMap<Coordinate, Int>.calculateInSpiral(position: Coordinate): Int {
    var sum = 0
    for (x in (position.x - 1)..(position.x + 1)) {
        for (y in (position.y - 1)..(position.y + 1)) {
            sum += this[Coordinate(x,y)] ?: 0
        }
    }
    this[position] = sum
    return sum
