fun squeeze(s: String, c: Char): String {
    if (s.isEmpty()) return ""
    return s[0] + IntStream.range(1, s.length - 1)
           .filter { s[it]!= c && s[it]!= s[it - 1] }
           .mapToObj { s[it] }
           .collect(StringBuilder(), StringBuilder::append, StringBuilder::append)
           .toString()
