// Helper class to represent complex numbers in Kotlin

data class Complex(val real: Double, val imag: Double) {
    fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is Complex) return false
        // To match Python's complex number string representation
        // and to compare with test cases
        return this.real == other.real && this.imag == other.imag
    }
    fun toString(): String {
        val imagPart = if (imag >= 0) "+${imag}j" else "${imag}j"
        return "${real}${imagPart}"
    }
}

fun roundComplexNumbers(items: List<Any?>): List<Complex> {
    val rounded = mutableListOf<Complex>()
    for (value in items) {
        if (value is Complex) {
            // Round the real part, keep imag unchanged
            // Kotlin's round line behaves as Python's round (ties to even)
            val newVal = Complex(kotlin.math.round(value.real).toDouble(), value.imag)
            rounded.add(newVal)
        }
    }
    return rounded
};1

