    for (a in binaries) {
        val gray = StringBuilder()
        gray.append(a[0])
        for (i in 1 until a.length) {
            val prev = a[i-1].digitToInt()
            val curr = a[i].digitToInt()
            gray.append((prev xor curr).toString())
        }
        results.add(gray.toString())
    }
