fun convertToColumnHeaders(proposedHeaders: List<String>): List<String> {
    // Helper function to sanitize names
    fun sanitize(name: String): String {
        val cleaned = name.lowercase().filter { it.isLetterOrDigit() }
        return if (cleaned.isEmpty()) "obfuscated_value" else cleaned
    }
    val counts = mutableMapOf<String, Int>()
    val result = mutableListOf<String>()
    for (raw in proposedHeaders) {
        val base = sanitize(raw)
        val header = if (counts.containsKey(base)) {
            counts[base] = counts[base]!! + 1
            "${base}_${counts[base]}"
        } else {
            counts[base] = 0
            base
        }
        result.add(header)
    }
    return result
};1

