    for (customer in customerData) {
        val name = customer["name"] ?: ""
        val email = customer["email"] ?: ""
        val phone = customer["phone"] ?: ""
        val anonymizedName = if (name.isNotEmpty()) name[0] + "*".repeat(name.length - 1) else ""
        val anonymizedEmail = if ("@" in email) {
            val parts = email.split("@", limit=2)
            "*".repeat(parts[0].length) + "@" + parts[1]
        } else {
            "*".repeat(email.length)
        }
        val anonymizedCustomer = mapOf(
            "name" to anonymizedName,
            "email" to anonymizedEmail,
            "phone" to phone
        )
        anonymizedData.add(anonymizedCustomer)
    }
    return anonymizedData
