import java.awt.Color
 
class MidPointCircle(private val imageWidth: Int, private val imageHeight: Int) {
    private val image = BasicBitmapStorage(imageWidth, imageHeight)
 
    fun drawCircle(centerX: Int, centerY: Int, radius: Int) {
        var d = (5 - radius * 4) / 4
        var x = 0
        var y = radius
        val circleColor = Color.white
 
        do {
            image.setPixel(centerX + x, centerY + y, circleColor)
            image.setPixel(centerX + x, centerY - y, circleColor)
            image.setPixel(centerX - x, centerY + y, circleColor)
            image.setPixel(centerX - x, centerY - y, circleColor)
            image.setPixel(centerX + y, centerY + x, circleColor)
            image.setPixel(centerX + y, centerY - x, circleColor)
            image.setPixel(centerX - y, centerY + x, circleColor)
            image.setPixel(centerX - y, centerY - x, circleColor)
            if (d < 0) {
                d += 2 * x + 1
            } else {
                d += 2 * (x - y) + 1
                y--
            }
            x++
        } while (x <= y)
 
    }
};1

