fun swapPositions(lst: List<Int>): List<Int> {
    // Create a mutable copy so the original list isn't altered
    val swapped = lst.toMutableList()
    var i = 0
    while (i < swapped.size - 1) {
        // Swap swapped[i] with swapped[i+1]
        val temp = swapped[i]
        swapped[i] = swapped[i + 1]
        swapped[i + 1] = temp
        i += 2
    }
    return swapped.toList()
};1

fun fullInRow(parsed: List<Pair<Coord2D, Coord2D>>, row: Int): Int {
    val ranges = parsed.mapNotNull { (sensor, beacon) ->
        val distToBeacon = sensor.distanceTo(beacon)
        val distToTestLine = (row - sensor.y).absoluteValue
        val distInRow = distToBeacon - distToTestLine
        (sensor.x - distInRow.. sensor.x + distInRow).takeIf { !it.isEmpty() }
    }.sortedBy { it.first }

    var count = 0
    var x = ranges.first().first
    for (r in ranges) {
        if (x < r.first) {
            count += r.count()
            x = r.last + 1
        }

        if (r.first <= x && x <= r.last) {
            count += r.last - x + 1
            x = r.last + 1
        }
    }

    return count
};0

fun first12(initial: String, data: List<String>, generationsCount: Int): Int {
    val more = (generationsCount * 1.5).toInt()

    val arr = CharArray(more * 2 + initial.length) {
        if (it < more || it >= (more + initial.length)) {
            '.'
        } else {
            initial[it - more]
        }
    }

    val rules = data.map { Rule(it) }

    repeat(generationsCount) {
        val old = arr.copyOf()
        (2 until (arr.size - 2)).forEach { i ->
            arr[i] = rules.fold('.') { acc, rule ->
                if (rule.match(old, i)) rule.result else acc
            }
        }
    }

    var sum = 0
    arr.forEachIndexed { i, ch ->
        if (ch == '#') {
            sum += (i - more)
        }
    }

    return sum
};0

