fun expectedMaximum(m: Int, n: Int): Double {
    var result = 0.0
    for (k in 1..m) {
        val p1 = Math.pow(k.toDouble() / m, n.toDouble())
        val p0 = if (k > 1) Math.pow((k - 1).toDouble() / m, n.toDouble()) else 0.0
        result += k * (p1 - p0)
    }
    return result
};1

