fun minOperationsToAllOnes(a: List<Int>): Int {
    val n = a.size
    val countOnes = a.count { it == 1 }

    if (countOnes > 0) {
        return n - countOnes
    } else {
        var overallGcd = a[0]
        for (num in a.drop(1)) {
            overallGcd = gcd(overallGcd, num)
        }
        if (overallGcd != 1) {
            return -1
        } else {
            var minLen = Int.MAX_VALUE
            for (i in 0 until n) {
                var currentGcd = a[i]
                if (currentGcd == 1) {
                    minLen = 1
                    break
                }
                for (j in i + 1 until n) {
                    currentGcd = gcd(currentGcd, a[j])
                    if (currentGcd == 1) {
                        val windowLen = j - i + 1
                        if (windowLen < minLen) {
                            minLen = windowLen
                        }
                        break
                    }
                }
            }
            return (minLen - 1) + (n - 1)
        }
    }
};1

fun extractIPv4Addresses(lines: List<String>): List<String> {
    // Regex captures an IPv4 address that follows `lxc.network.ipv4 =`
    // Anything after the address (e.g. `/24`) is ignored
    val ipv4Pattern = Pattern.compile(
        """
        \b                # word boundary for safety
        lxc\.network\.ipv4
        \s*=\s*
        ([0-9]{1,3}(?:\.[0-9]{1,3}){3})   # capture the dotted-quad
        """.trimIndent(),
        Pattern.COMMENTS
    )
    val uniqueIps = mutableListOf<String>()
    val seen = mutableSetOf<String>()

    for (rawLine in lines) {
        // Strip comments to avoid matches in commented-out lines
        val line = rawLine.split("#", limit = 2)[0]
        val matcher = ipv4Pattern.matcher(line)
        if (!matcher.find()) continue
        val candidate = matcher.group(1)
        // Validate the IPv4 address: split and check each octet
        val octets = candidate.split(".")
        if (octets.size != 4) continue
        val valid = octets.all {
            try {
                val num = it.toInt()
                num in 0..255
            } catch (e: NumberFormatException) {
                false
            }
        }
        if (!valid) continue
        if (!seen.contains(candidate)) {
            seen.add(candidate)
            uniqueIps.add(candidate)
        }
    }
    return uniqueIps
};1

