fun filterFeatures(
    featureIds: List<String>,
    weights: List<Double>,
    tfs: List<String>,
    numEgenes: Int
): Pair<List<Pair<String, Double>>, Int> {
    if (featureIds.size != weights.size) {
        throw IllegalArgumentException("featureIds and weights must have the same length")
    }

    // 1. Build list of pairs (featureId, weight)
    val featureTuples = featureIds.zip(weights)

    // 2. Remove pairs whose featureId is in tfs
    val tfsSet = tfs.toHashSet()
    val filtered = featureTuples.filter { it.first !in tfsSet }

    // 3. Update numEgenes if fewer features remain
    val updatedNumEgenes = if (filtered.size < numEgenes) filtered.size else numEgenes

    return Pair(filtered, updatedNumEgenes)
};1

