import java.io.ByteArrayOutputStream
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.util.*
 
fun main(args: Array<String>) {
    val data = intArrayOf(170, 45, 75, -90, -802, 24, 2, 66)
    val buf = ByteArrayOutputStream()
    val ds = Array(data.size) { ByteArray(4) }
    for (i in data.indices) {
        val x = data[i]
        val b = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN).putInt(x.inv()).array()
        buf.write(b)
        ds[i] = b
    }
    val bins = Array(256) { ArrayList<ByteArray>() }
    for (i in 0..3) {
        for (b in ds) {
            bins[b[i].toInt() and 0xff].add(b)
        }
        var j = 0
        for (k in bins.indices) {
            val bs = bins[k]
            for (b in bs) {
                ds[j++] = b
            }
            bs.clear()
        }
    }
    println("original: " + Arrays.toString(data))
    val w = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN)
    for (i in ds.indices) {
        val b = ds[i]
        buf.write(b)
        w.put(b)
        w.flip()
        data[i] = w.int.inv()
        w.clear()
    }
    println("sorted:   " + Arrays.toString(data))
};1

 
var count = 0
var c = IntArray(0)
var f = ""
 
fun nQueens(row: Int, n: Int) {
    outer@ for (x in 1..n) {
        for (y in 1..row - 1) {
            if (c[y] == x) continue@outer
            if (row - y == Math.abs(x - c[y])) continue@outer
        }
        c[row] = x
        if (row < n) nQueens(row + 1, n)
        else if (++count == 1) f = c.drop(1).map { it - 1 }.toString()
    }
}
 
