class ListNode(var time: Int = 0, var next: ListNode? = null) {
    fun equals(other: Any?): Boolean {
        if (other !is ListNode) return false
        var a: ListNode? = this
        var b: ListNode? = other
        while (a != null && b != null) {
            if (a.time != b.time) return false
            a = a.next
            b = b.next
        }
        return a == null && b == null
    }
    fun toString(): String {
        val out = mutableListOf<String>()
        var node: ListNode? = this
        while (node != null) {
            out.add(node.time.toString())
            node = node.next
        }
        return out.joinToString(" -> ")
    }
}

fun reverseLinkedListByTime(head: ListNode?): ListNode? {
    fun split(node: ListNode?): ListNode? {
        if (node == null || node.next == null) return node
        var slow = node
        var fast = node.next
        while (fast != null && fast.next != null) {
            slow = slow.next!!
            fast = fast.next!!.next
        }
        val mid = slow.next
        slow.next = null
        return mid
    }

    fun merge(left: ListNode?, right: ListNode?): ListNode? {
        val dummy = ListNode()
        var current = dummy
        var l = left
        var r = right
        while (l != null && r != null) {
            if (l.time > r.time) {
                current.next = l
                l = l.next
            } else if (l.time < r.time) {
                current.next = r
                r = r.next
            } else {
                current.next = l
                l = l.next
            }
            current = current.next!!
        }
        current.next = l ?: r
        return dummy.next
    }

    fun mergeSort(node: ListNode?): ListNode? {
        if (node == null || node.next == null) return node
        val mid = split(node)
        val left = mergeSort(node)
        val right = mergeSort(mid)
        return merge(left, right)
    }
    return mergeSort(head)
};1

