fun benfordDistribution(): FloatArray {
    val prob = FloatArray(9)
    for (i in 1..9) {
        prob[i - 1] = log10(1 + 1.0 / i).toFloat()
    }
    return prob
}
 
fun getActualDistribution(fn: String): FloatArray {
    val input = File(fn).inputStream()
    val tally = IntArray(9)
    var total = 0
    var c: Int
    while (input.read().also { c = it }!= -1) {
        /* get the first nonzero digit on the current line */
        while (c < '1'.code || c > '9'.code) {
            c = input.read()
        }
        tally[c - '1'.code]++
        total++
        /* discard rest of line */
        while (input.read().also { c = it }!= '\n'.code && c!= -1) {
        }
    }
    input.close()
    val freq = FloatArray(9)
    for (i in 0..8) {
        freq[i] = tally[i] / total.toFloat()
    }
    return freq
}
 
