fun stringXor(a: String, b: String): String {
    // ---------- Validation ----------
    val maxLenAllowed = 1000
    if (a.length > maxLenAllowed || b.length > maxLenAllowed) {
        throw IllegalArgumentException("Input strings must not exceed 1000 characters.")
    }
    val validChars = setOf('0', '1')
    if (a.any { it !in validChars } || b.any { it !in validChars }) {
        throw IllegalArgumentException("Input strings must contain only '0' or '1'.")
    }
    // ---------- Padding ----------
    val maxLen = maxOf(a.length, b.length)
    val aPadded = a.padStart(maxLen, '0')
    val bPadded = b.padStart(maxLen, '0')
    // ---------- XOR computation ----------
    val result = StringBuilder()
    for (i in 0 until maxLen) {
        result.append(if (aPadded[i] != bPadded[i]) '1' else '0')
    }
    return result.toString()
};1

