fun isomorphicMapping(s: String, t: String): Any {
    if (s.length != t.length) {
        return "The strings are not isomorphic."
    }
    val sToT = mutableMapOf<Char, Char>()
    val tMapped = mutableSetOf<Char>()
    for ((sc, tc) in s.zip(t)) {
        if (sToT.containsKey(sc)) {
            if (sToT[sc] != tc) {
                return "The strings are not isomorphic."
            }
        } else {
            if (tc in tMapped) {
                return "The strings are not isomorphic."
            }
            sToT[sc] = tc
            tMapped.add(tc)
        }
    }
    return sToT
};1

