// compile with -Xcoroutines=enable flag from command line
 
import kotlin.coroutines.experimental.buildSequence
 
fun r2cf(frac: Pair<Int, Int>) =
    buildSequence {
        var num = frac.first
        var den = frac.second
        while (Math.abs(den) != 0) {
            val div = num / den
            val rem = num % den
            num = den
            den = rem
            yield(div)
        }
    }
 
fun iterate(seq: Sequence<Int>) {
    for (i in seq) print("$i ")
    println()
}
 
