    val wordPattern = Pattern.compile("[A-Za-z0-9']+")
    val counts = mutableMapOf<String, Int>()
    for (line in textList) {
        // Gjør linje til små bokstaver og trekk ut alle ord
        val matcher = wordPattern.matcher(line.lowercase())
