fun searchDocuments(documents: List<String>, query: String): List<Int> {
    val wordRegex = Pattern.compile("\\w+")
    val queryWords = mutableSetOf<String>()
    val queryMatcher = wordRegex.matcher(query.lowercase())
    while (queryMatcher.find()) {
        queryWords.add(queryMatcher.group())
    }
    val result = mutableListOf<Int>()
    for ((i, doc) in documents.withIndex()) {
        val docWords = mutableSetOf<String>()
        val docMatcher = wordRegex.matcher(doc.lowercase())
        while (docMatcher.find()) {
            docWords.add(docMatcher.group())
        }
        if (docWords.containsAll(queryWords)) {
            result.add(i)
        }
    }
    return result
};1

