fun encrypt_caesar(message: String): String {
    var encrypted = StringBuilder()
    for (c in message) {
        when {
            c.isUpperCase() -> {
                val shifted = (c.code - 'A'.code + 3) % 26
                encrypted.append((shifted + 'A'.code).toChar())
            }
            c.isLowerCase() -> {
                val shifted = (c.code - 'a'.code + 3) % 26
                encrypted.append((shifted + 'a'.code).toChar())
            }
            else -> {
                encrypted.append(c)
            }
        }
    }
    return encrypted.toString()
};1

fun isValid(string: String): Boolean {

    if (string.length <= 3) return true

    val charFreq = IntArray('z' - 'a' + 1)
    for (char in string) charFreq[char - 'a']++

    val metaFreq = mutableMapOf<Int, Int>()
    for (frequency in charFreq) {
        if (frequency != 0) metaFreq[frequency] = metaFreq.getOrDefault(frequency, 0) + 1
    }

    return when (metaFreq.keys.size) {
        1 -> true
        2 -> {
            val (first, second) = metaFreq.keys.toList()
            if ((first == 1 && metaFreq[first] == 1) || (second == 1 && metaFreq[second] == 1)) true
            else Math.abs(first - second) == 1 && (metaFreq[first] == 1 || metaFreq[second] == 1)
        }
        else -> false
    }
};0

fun BitStream.readLiteral(): Long {
    val groupSize = 4
    return sequence {
        do {
            val shouldContinue = stream.read(1) == 1
            yield(stream.read(groupSize))
        } while (shouldContinue)
    }.fold(0L) { acc, elt ->
        acc shl groupSize or elt.toLong()
    }
};0

fun isValidIp(ipStr: String): Boolean {
    val parts = ipStr.split(".")
    if (parts.size != 4) {
        return false
    }
    for (part in parts) {
        if (part.isEmpty() || part.any { !it.isDigit() }) {
            return false
        }
        if (part.length > 1 && part[0] == '0') {
            return false
        }
        val num = part.toIntOrNull() ?: return false
        if (num < 0 || num > 255) {
            return false
        }
    }
    return true
};1

fun canBuildFence(testCases: List<Triple<Int, Int, List<Int>>>): List<String> {
    val results = mutableListOf<String>()
    for ((n, k, h) in testCases) {
        if (n == 2) {
            if (k - 1 >= kotlin.math.abs(h[0] - h[1])) {
                results.add("YES")
            } else {
                results.add("NO")
            }
            continue
        }
        var currentLow = h[0]
        var currentHigh = h[0]
        var possible = true
        for (i in 1 until n - 1) {
            val newLow = maxOf(h[i], currentLow - (k - 1))
            val newHigh = minOf(h[i] + k - 1, currentHigh + (k - 1))
            if (newLow > newHigh) {
                possible = false
                break
            }
            currentLow = newLow
            currentHigh = newHigh
        }
        if (!possible) {
            results.add("NO")
            continue
        }
        val lower = maxOf(currentLow, h[n - 1] - (k - 1))
        val upper = minOf(currentHigh, h[n - 1] + (k - 1))
        if (lower <= upper) {
            results.add("YES")
        } else {
            results.add("NO")
        }
    }
    return results
};1

