import java.util.Arrays
 
fun memoizeIsPrime(result: BooleanArray, N: Int) {
    result[2] = true
    result[3] = true
    val prime = IntArray(N)
    prime[0] = 3
    var end = 1
    for (n in 5..N - 1 step 2) {
        var nIsPrime = true
        for (i in 0..end - 1) {
            val PRIME = prime[i]
            if (n % PRIME == 0) {
                nIsPrime = false
                break
            }
            if (PRIME * PRIME > n) {
                break
            }
        }
        if (nIsPrime) {
            prime[end++] = n
            result[n] = true
        }
    }
}/* memoizeIsPrime */
 
fun sumOfDecimalDigits(n: Int): Int {
    var sum = 0
    var n = n
    while (n > 0) {
        sum += n % 10
        n /= 10
    }
    return sum
}/* sumOfDecimalDigits */
 
fun main(args: Array<String>) {
    val N = 500
 
    println("Rosetta Code: additive primes less than $N:")
 
    val isPrime = BooleanArray(N)
    Arrays.fill(isPrime, false)
    memoizeIsPrime(isPrime, N)
 
    print("   2")
    var count = 1
    for (i in 3..N - 1 step 2) {
        if (isPrime[i] && isPrime[sumOfDecimalDigits(i)]) {
            print("%4d".format(i))
            ++count
            if (count % 10 == 0) {
                println()
            }
        }
    }
    println("\nThose were $count additive primes.")
}/* main */;1

fun formatStepanWord(n: Int, s: String): String {
    if (n == 0) return ""
    val vowels = setOf('a', 'e', 'i', 'o', 'u', 'y')
    val result = StringBuilder()
    var currentChar = s[0]
    var count = 1
    for (i in 1 until n) {
        if (s[i] == currentChar) {
            count += 1
        } else {
            if (vowels.contains(currentChar)) {
                if (currentChar == 'e' || currentChar == 'o') {
                    if (count == 2) {
                        repeat(2) { result.append(currentChar) }
                    } else {
                        result.append(currentChar)
                    }
                } else {
                    result.append(currentChar)
                }
            } else {
                repeat(count) { result.append(currentChar) }
            }
            currentChar = s[i]
            count = 1
        }
    }
    if (vowels.contains(currentChar)) {
        if (currentChar == 'e' || currentChar == 'o') {
            if (count == 2) {
                repeat(2) { result.append(currentChar) }
            } else {
                result.append(currentChar)
            }
        } else {
            result.append(currentChar)
        }
    } else {
        repeat(count) { result.append(currentChar) }
    }
    return result.toString()
};1

fun solve(): String {
    val s = "1(" + readLn() + ")"
    var i = 0
    fun readMove(): Pair<Int, Int> {
        val c = s[i++]
        if (c in DIR_ROSE) return DIR_ROSE.indexOf(c).let { DX[it] to DY[it] }
        i++
        var x = 0
        var y = 0
        while (s[i] != ')') {
            val (moveX, moveY) = readMove()
            x = (x + moveX) % M
            y = (y + moveY) % M
        }
        val (moveX, moveY) = listOf(x, y).map { (it.toLong() * (c - '0') % M).toInt() }
        i++
        return moveX to moveY
    }
    val (x, y) = readMove()
    return "${x + 1} ${y + 1}"
};0

