fun getSets(deal: List<IntArray>): List<List<IntArray>> {
    val goodFeatureCount = setOf(1, 3)
    val sets = ArrayList<List<IntArray>>()
    for (i in 0 until deal.size - 2) {
        for (j in i + 1 until deal.size - 1) {
            for (k in j + 1 until deal.size) {
                val comb = listOf(deal[i], deal[j], deal[k])
                if (comb.all { feature ->
                    goodFeatureCount.contains(feature.toSet().size)
                }) {
                    sets.add(comb)
                }
            }
        }
    }
    return sets
}
 
