fun longestSubstring(s: String): String {
    // Map to store the most recent index at which each character was seen
    val lastSeen = mutableMapOf<Char, Int>()

    var left = 0            // Left boundary of the current window
    var bestStart = 0       // Start index of the best (longest) substring found so far
    var bestLen = 0         // Length of the best substring

    for ((right, char) in s.withIndex()) {
        // If we have seen this character and it's inside the current window
        if (lastSeen.containsKey(char) && lastSeen[char]!! >= left) {
            // Move the left boundary right past the previous occurrence
            left = lastSeen[char]!! + 1
        }
        // Update the last seen index of the current character
        lastSeen[char] = right
        // Current window length
        val currentLen = right - left + 1
        // Update best substring if longer (first occurrence is kept)
        if (currentLen > bestLen) {
            bestLen = currentLen
            bestStart = left
        }
    }
    // Slice out the best substring
    return s.substring(bestStart, bestStart + bestLen)
};1

fun calculateValue(
    m8: Double,
    L88: Double,
    d_gap: Double,
    k: Double,
    Cp: Double,
    h_gap: Double
): Double? {
    // Kontrollera ogiltiga värden som ger division med noll
    if (m8 == 0.0 || Cp == 0.0 || L88 == 0.0) {
        return null
    }
    return try {
        val term1 = (2 * h_gap * L88) / (m8 * Cp)
        val term2 = (2 * k * d_gap) / (m8 * Cp * L88)
        val denominator = term1 + term2
        if (denominator == 0.0) {
            null
        } else {
            1.0 / denominator
        }
    } catch (e: ArithmeticException) {
        null
    }
};1

