/**
 * Longest contiguous duration
 */
fun <T> List<InstantState<T>>.maxContiguousDurations(
    maxTtl: Duration,
): List<DurationState<T>> {
    val maxContiguous = mutableMapOf<T, Duration>()
    this.distinctBy { it.state }.forEach {
        maxContiguous[it.state] = Duration.ZERO
    }
    var currentState: T? = null
    var currentDuration: Duration = Duration.ZERO
    this.zipWithNext().forEach { (event0, event1): Pair<InstantState<T>, InstantState<T>> ->
        val (ts0, state0) = event0
        val (ts1, _) = event1
        if (currentState != state0) {
            currentState = state0
            currentDuration = Duration.ZERO
        }
        currentDuration += Duration.between(ts0, ts1).coerceAtMost(maxTtl)
        if (currentDuration > maxContiguous[currentState]) {
            maxContiguous[currentState!!] = currentDuration
        }
    }
    return maxContiguous.map {
        DurationState(
            duration = it.value,
            state = it.key
        )
    }
};0

fun search(graph: Graph, time: Int, players: Int): Long {
    val start = State(graph, time, p2dist = if (players == 1) time * 2 else -1)

    val comparator = compareByDescending<State> { it.score }

    val queue = PriorityQueue(comparator).apply { offer(start) }

    var result = 0L
    while (queue.isNotEmpty()) {
        val curr = queue.poll()
        if (result < curr.score) {
            result = curr.score
        }
        curr.possibleActions()
            .map { curr + it }
            .forEach { if (it.score + it.potential > result) queue.offer(it) }
    }
    return result
};0

