fun findMaxDestinationFlights(flights: List<Pair<String, Int>>): Pair<String?, Int> {
    if (flights.isEmpty()) {
        return Pair(null, 0)
    }
    val totals = mutableMapOf<String, Int>()
    for ((country, count) in flights) {
        totals[country] = totals.getOrDefault(country, 0) + count
    }
    val maxEntry = totals.maxByOrNull { it.value }
    return if (maxEntry != null) Pair(maxEntry.key, maxEntry.value) else Pair(null, 0)
}

