class VectorProds {
    class Vector3D<T : Number>(a: T, b: T, c: T) {
        private val a: T = a
        private val b: T = b
        private val c: T = c

        fun dot(vec: Vector3D<*>): Double {
            return a.toDouble() * vec.a.toDouble() + b.toDouble() * vec.b.toDouble() + c.toDouble() * vec.c.toDouble()
        }

        fun cross(vec: Vector3D<*>): Vector3D<Double> {
            val newA = b.toDouble() * vec.c.toDouble() - c.toDouble() * vec.b.toDouble()
            val newB = c.toDouble() * vec.a.toDouble() - a.toDouble() * vec.c.toDouble()
            val newC = a.toDouble() * vec.b.toDouble() - b.toDouble() * vec.a.toDouble()
            return Vector3D(newA, newB, newC)
        }

        fun scalTrip(vecB: Vector3D<*>, vecC: Vector3D<*>): Double {
            return dot(vecB.cross(vecC))
        }

        fun vecTrip(vecB: Vector3D<*>, vecC: Vector3D<*>): Vector3D<Double> {
            return cross(vecB.cross(vecC))
        }

        fun toString(): String {
            return "<" + a.toString() + ", " + b.toString() + ", " + c.toString() + ">"
        }
    }

    companion object {
        @JvmStatic
        fun main(args: Array<String>) {
            val a = Vector3D(3, 4, 5)
            val b = Vector3D(4, 3, 5)
            val c = Vector3D(-5, -12, -13)

            println(a.dot(b))
            println(a.cross(b))
            println(a.scalTrip(b, c))
            println(a.vecTrip(b, c))
        }
    }
};1

 
fun heapSort(a: IntArray) {
    heapify(a)
    var end = a.size - 1
    while (end > 0) {
        val temp = a[end]
        a[end] = a[0]
        a[0] = temp
        end--
        siftDown(a, 0, end)
    }
}
 
fun heapify(a: IntArray) {
    var start = (a.size - 2) / 2
    while (start >= 0) {
        siftDown(a, start, a.size - 1)
        start--
    }
}
 
fun siftDown(a: IntArray, start: Int, end: Int) {
    var root = start
    while (root * 2 + 1 <= end) {
        var child = root * 2 + 1
        if (child + 1 <= end && a[child] < a[child + 1]) child++
        if (a[root] < a[child]) {
            val temp = a[root]
            a[root] = a[child]
            a[child] = temp
            root = child
        }
        else return
    }
}
 
