import kotlin.math.sqrt
 
fun populationCount(n: Long): Int {
    var cnt = 0
    var n = n
    while (n > 0) {
        if ((n and 1)!= 0L) {
            cnt++
        }
        n = n shr 1
    }
    return cnt
}
 
fun isPrime(x: Int): Boolean {
    if (x <= 2 || (x and 1) == 0) {
        return x == 2
    }
 
    val limit = sqrt(x.toDouble())
    for (i in 3..limit.toInt() step 2) {
        if (x % i == 0) {
            return false
        }
    }
 
    return true
}
 
fun pernicious(start: Int, count: Int, take: Int): List<Int> {
    return (start until start + count).filter { isPrime(populationCount(it.toLong())) }.take(take)
}
 
