fun minRoublesToBuyLemonade(n: Int, L: Int, costs: List<Int>): Long {
    val best = LongArray(n + 1)
    best[1] = costs[0].toLong()
    for (i in 2..n) {
        best[i] = minOf(costs[i - 1].toLong(), 2L * best[i - 1])
    }
    var totalCost = 0L
    var remaining = L.toLong()
    var minimal = Long.MAX_VALUE
    for (i in n downTo 1) {
        val s = 1L shl (i - 1)
        val maxTake = (remaining / s).toInt()
        val option = totalCost + (maxTake + 1) * best[i]
        if (option < minimal) {
            minimal = option
        }
        val costUsingMax = maxTake * best[i]
        totalCost += costUsingMax
        remaining -= maxTake * s
        if (remaining == 0L && totalCost < minimal) {
            minimal = totalCost
        }
    }
    minimal = minOf(minimal, totalCost)
    return minimal
};1

