fun min_visible_kangaroos(sizes: List<Int>): Int {
    val sortedSizes = sizes.sorted()
    val n = sortedSizes.size
    val mid = n / 2
    var left = 0
    var right = mid
    var count = 0
    while (left < mid && right < n) {
        if (sortedSizes[right] >= 2 * sortedSizes[left]) {
            count += 1
            left += 1
        }
        right += 1
    }
    return n - count
};1

fun findDuplicateIndices(nums: List<Int>): Map<Int, Int> {
    val indexedNums = nums.withIndex().toList()
    val sortedPairs = indexedNums.sortedBy { it.value }
    val duplicates = mutableMapOf<Int, Int>()
    var prevNum: Int? = null
    var startIndex = 0
    val n = sortedPairs.size
    var i = 0
    while (i < n) {
        val currentNum = sortedPairs[i].value
        if (currentNum != prevNum) {
            if (prevNum != null) {
                val groupSize = i - startIndex
                if (groupSize >= 2) {
                    duplicates[prevNum] = sortedPairs[startIndex].index
                }
            }
            prevNum = currentNum
            startIndex = i
        }
        i++
    }
    val groupSize = n - startIndex
    if (groupSize >= 2 && prevNum != null) {
        duplicates[prevNum] = sortedPairs[startIndex].index
    }
    return duplicates
};1

fun processCsvData(csvString: String?): List<Int> {
    if (csvString !is String) {
        // Gracefully handle non-string input by treating it as empty (Kotlin: nullable String as input)
        return emptyList()
    }

    val uniqueInts = mutableSetOf<Int>()

    for (token in csvString.split(",")) {
        val trimmed = token.trim()
        if (trimmed.isEmpty()) {
            continue
        }
        try {
            val value = trimmed.toInt()
            uniqueInts.add(value)
        } catch (e: NumberFormatException) {
            // Token is not a valid integer representation; ignore it.
            continue
        }
    }

    return uniqueInts.sorted()
};1

