fun settleBricks(bricks: List<Brick>): List<Brick> {
    var settledBricks = bricks.toMutableList()
    val changedBricks = mutableListOf<Brick>()

    while (true) {
        for (i in settledBricks.indices) {
            val minZ = min(settledBricks[i].start.z, settledBricks[i].end.z)
            if (minZ == 1) {
                changedBricks.add(settledBricks[i])
                continue
            }

            var isBlocked = false
            for (j in settledBricks.indices) {
                if (i == j) {
                    continue
                }

                if (restsOn(settledBricks[i], settledBricks[j])) {
                    isBlocked = true
                }
            }

            if (!isBlocked) {
                changedBricks.add(moveDown(settledBricks[i]))
            } else {
                changedBricks.add(settledBricks[i])
            }
        }

        if (settledBricks == changedBricks) {
            break
        }
        settledBricks = changedBricks.toMutableList()
        changedBricks.clear()
    }

    return settledBricks
};0

fun countIslands(grid: List<List<Int>>): Int {
    if (grid.isEmpty() || grid[0].isEmpty()) return 0
    val n = grid.size
    val m = grid[0].size
    val visited = Array(n) { BooleanArray(m) { false } }

    fun bfs(i: Int, j: Int) {
        val queue: Queue<Pair<Int, Int>> = LinkedList()
        queue.add(Pair(i, j))
        visited[i][j] = true
        val directions = arrayOf(Pair(-1,0), Pair(1,0), Pair(0,-1), Pair(0,1))
        while (queue.isNotEmpty()) {
            val (x, y) = queue.remove()
            for ((dx, dy) in directions) {
                val nx = x + dx
                val ny = y + dy
                if (nx in 0 until n && ny in 0 until m && !visited[nx][ny] && grid[nx][ny] == 1) {
                    visited[nx][ny] = true
                    queue.add(Pair(nx, ny))
                }
            }
        }
    }

    var count = 0
    for (i in 0 until n) {
        for (j in 0 until m) {
            if (!visited[i][j] && grid[i][j] == 1) {
                count += 1
                bfs(i, j)
            }
        }
    }
    return count
};1

fun validateCredentials(credentials: List<Map<String, String>>): List<Map<String, String>> {
    val hasUpper = Regex("[A-Z]")
    val hasLower = Regex("[a-z]")
    val hasDigit = Regex("\\d")
    val hasSpecial = Regex("[^A-Za-z0-9]") // any non-alphanumeric

    val validCredentials = mutableListOf<Map<String, String>>()

    for (cred in credentials) {
        val username = cred["username"]
        val password = cred["password"]
        val token = cred["token"]

        // Rule 1: username must be a non-empty string
        if (username == null || username.trim().isEmpty()) {
            continue
        }
        // Rule 3: token must be a non-empty string
        if (token == null || token.trim().isEmpty()) {
            continue
        }
        // Rule 2: password complexity
        if (password != null &&
            password.length >= 8 &&
            hasUpper.containsMatchIn(password) &&
            hasLower.containsMatchIn(password) &&
            hasDigit.containsMatchIn(password) &&
            hasSpecial.containsMatchIn(password)) {
            validCredentials.add(cred)
        }
    }
    return validCredentials
};1

