fun dpcmMinError(datasets: List<Map<String, Any>>): List<Int> {
    val results = mutableListOf<Int>()
    for (data in datasets) {
        val N = data["N"] as Int
        val M = data["M"] as Int
        val C = data["codebook"] as List<Int>
        val xs = data["signal"] as List<Int>
        val INF = 1L shl 60
        var prevDp = LongArray(256) { INF }
        prevDp[128] = 0L
        for (x in xs) {
            val currentDp = LongArray(256) { INF }
            for (yPrev in 0..255) {
                if (prevDp[yPrev] == INF) continue
                for (c in C) {
                    var y = yPrev + c
                    if (y < 0) y = 0
                    if (y > 255) y = 255
                    val err = (x - y).toLong() * (x - y)
                    val total = prevDp[yPrev] + err
                    if (total < currentDp[y]) {
                        currentDp[y] = total
                    }
                }
            }
            prevDp = currentDp
        }
        results.add(prevDp.minOrNull()!!.toInt())
    }
    return results
};1

