fun taroVsJiro(a: List<Int>): Long {
    val n = a.size
    val dp = Array(n) { LongArray(n) }
    for (i in 0 until n) {
        dp[i][i] = a[i].toLong()
    }
    for (l in 2..n) {
        for (i in 0..n - l) {
            val j = i + l - 1
            dp[i][j] = maxOf(
                a[i].toLong() - dp[i + 1][j],
                a[j].toLong() - dp[i][j - 1]
            )
        }
    }
    return dp[0][n - 1]
};1

