fun censorContig(contigEnd: String,
                 uContigs: List<String>,
                 oDict: Map<String, Map<String, Any>>
): Pair<List<String>, Map<String, Map<String, Any>>> {
    // Work on copies so the originals stay intact outside this function.
    val newContigs = uContigs.toMutableList()
    val newODict = mutableMapOf<String, MutableMap<String, Any>>()

    // 1. Remove the contig end from the list if present.
    if (newContigs.contains(contigEnd)) {
        newContigs.remove(contigEnd)
    }

    // 2. Build a cleaned-up overlap map.
    for ((key, inner) in oDict) {
        // Skip the entire entry if the top-level key matches contigEnd.
        if (key == contigEnd) continue

        // Copy the inner map, omitting any reference to contigEnd.
        val cleanedInner = inner.filterKeys { it != contigEnd }.toMutableMap()
        newODict[key] = cleanedInner
    }

    return Pair(newContigs, newODict)
};1

