fun convexHull(p: List<Point>): List<Point> {
    if (p.isEmpty()) return emptyList()
    val sorted = p.sorted()
    val h = ArrayList<Point>()
 
    // lower hull
    for (pt in sorted) {
        while (h.size >= 2 &&!ccw(h[h.size - 2], h[h.size - 1], pt)) {
            h.removeAt(h.size - 1)
        }
        h.add(pt)
    }
 
    // upper hull
    var t = h.size + 1
    for (i in p.size - 1 downTo 0) {
        val pt = p[i]
        while (h.size >= t &&!ccw(h[h.size - 2], h[h.size - 1], pt)) {
            h.removeAt(h.size - 1)
        }
        h.add(pt)
    }
 
    h.removeAt(h.size - 1)
    return h
}
 
// ccw returns true if the three points make a counter-clockwise turn
fun ccw(a: Point, b: Point, c: Point): Boolean {
    return ((b.x - a.x) * (c.y - a.y)) > ((b.y - a.y) * (c.x - a.x))
}
 
private class Point(val x: Int, val y: Int) : Comparable<Point> {
    fun compareTo(o: Point): Int {
        return Integer.compare(x, o.x)
    }
 
    fun toString(): String {
        return String.format("(%d, %d)", x, y)
    }
};1

import kotlin.math.sqrt
 
/* kind of function that returns a series of coefficients */
typealias CoeffFunc = (n: Int) -> Double
 
/* calculates the specified number of expansions of the continued fraction
 * described by the coefficient series f_a and f_b */
fun calc(f_a: CoeffFunc, f_b: CoeffFunc, expansions: Int): Double {
    var a = 0.0
    var b = 0.0
    var r = 0.0
 
    for (i in expansions downTo 1) {
        a = f_a(i)
        b = f_b(i)
        r = b / (a + r)
    }
    a = f_a(0)
 
    return a + r
}
 
/* series for sqrt(2) */
fun sqrt2_a(n: Int): Double {
    return if (n > 0) 2.0 else 1.0
}
 
fun sqrt2_b(n: Int): Double {
    return 1.0
}
 
/* series for the napier constant */
fun napier_a(n: Int): Double {
    return if (n > 0) n.toDouble() else 2.0
}
 
fun napier_b(n: Int): Double {
    return if (n > 1) n - 1.0 else 1.0
}
 
/* series for pi */
fun pi_a(n: Int): Double {
    return if (n > 0) 6.0 else 3.0
}
 
fun pi_b(n: Int): Double {
    val c = 2.0 * n - 1.0
 
    return c * c
}
 
fun main() {
    val sqrt2 = calc(::sqrt2_a, ::sqrt2_b, 1000)
    val napier = calc(::napier_a, ::napier_b, 1000)
    val pi = calc(::pi_a, ::pi_b, 1000)
 
    println("%12.10g\n%12.10g\n%12.10g\n".format(sqrt2, napier, pi))
};1

fun solve(): String {
    val (a, b, qIn) = readLn().split(" ")
    val leftMost = HashMap<Long, Int>(a.length * a.length)
    for (i in a.indices) {
        var h = 0L
        for (j in i until a.length) {
            h = mix(h + a[j].code)
            leftMost.putIfAbsent(h, j + 1)
        }
    }
    val ans = List(qIn.toInt()) {
        val (aLen, bLen) = readInts()
        val bStart = b.length - bLen
        var h = 0L
        for (j in bStart until b.length) {
            h = mix(h + b[j].code)
            val pos = leftMost.get(h) ?: (a.length + 1)
            if (pos > aLen) {
                return@List j - bStart
            }
        }
        bLen
    }
    return ans.joinToString(" ")
};0

 
import java.math.BigInteger
 
fun nextLeftTruncatablePrimes(n: BigInteger, radix: Int, certainty: Int): List<BigInteger> {
    val probablePrimes = mutableListOf<BigInteger>()
    val baseString = if (n == BigInteger.ZERO) "" else n.toString(radix)
    for (i in 1 until radix) {
        val p = BigInteger(i.toString(radix) + baseString, radix)
        if (p.isProbablePrime(certainty)) probablePrimes.add(p)
    }
    return probablePrimes
}
 
fun largestLeftTruncatablePrime(radix: Int, certainty: Int): BigInteger? {
    var lastList: List<BigInteger>? = null
    var list = nextLeftTruncatablePrimes(BigInteger.ZERO, radix, certainty)
    while (!list.isEmpty()) {
        lastList = list
        list = mutableListOf()
        for (n in lastList) list.addAll(nextLeftTruncatablePrimes(n, radix, certainty))
    }
    if (lastList == null) return null
    return lastList.sorted().last()
}
 
fun main(args: Array<String>) {
    print("Enter maximum radix : ")
    val maxRadix = readLine()!!.toInt()
