        val largest = largestLeftTruncatablePrime(radix, certainty)
        print("Base = ${"%-2d".format(radix)} : ")
        if (largest == null)
            println("No left truncatable prime")
        else
            println("${largest.toString().padEnd(35)} -> ${largest.toString(radix)}")
    }
};0

