fun unionSortedSets(A: List<Int>, B: List<Int>): List<Int> {
    val n = A.size
    val m = B.size
    var i = 0
    var j = 0
    val result = mutableListOf<Int>()
    while (i < n && j < m) {
        val a = A[i]
        val b = B[j]
        if (a < b) {
            result.add(a)
            i++
        } else if (a > b) {
            result.add(b)
            j++
        } else {
            result.add(a)
            i++
            j++
        }
    }
    while (i < n) {
        result.add(A[i])
        i++
    }
    while (j < m) {
        result.add(B[j])
        j++
    }
    return result
};1

