fun rot13(c: Char): Char {
    if (c in 'a'..'m' || c in 'A'..'M') {
        return (c + 13).toChar()
    }
    if (c in 'n'..'z' || c in 'N'..'Z') {
        return (c - 13).toChar()
    }
    return c
}
 
fun rot13(s: String): String {
    return s.map { rot13(it) }.joinToString("")
}
 
