fun <T> getPropertyValues(obj: T, flags: BindingFlags): List<Pair<String, Any?>> {
    val properties = if (flags.hasFlag(BindingFlags.DeclaredOnly)) {
        obj::class.declaredMemberProperties
    } else {
        obj::class.memberProperties
    }
    return properties.filter {
        it.isAccessible = true
        it.parameters.isEmpty()
    }.map { it.name to it.getter.call(obj) }
}
 
fun <T> getFieldValues(obj: T, flags: BindingFlags): List<Pair<String, Any?>> {
    val fields = if (flags.hasFlag(BindingFlags.DeclaredOnly)) {
        obj::class.java.declaredFields
    } else {
        obj::class.java.fields
    }
    return fields.filter {
        it.isAccessible = true
        it.name!= "INSTANCE_LOCK"
    }.map { it.name to it.get(obj) }
}
 
