fun nodeIdAtCells(shape: Pair<Int, Int>): List<List<Int>> {
    val (nRows, nCols) = shape

    // No interior cells if either dimension is less than or equal to 2
    if (nRows <= 2 || nCols <= 2) {
        return emptyList()
    }

    val innerIds = mutableListOf<List<Int>>()
    // Loop over interior rows and columns (skip first and last in each case)
    for (r in 1 until nRows - 1) {
        val rowIds = mutableListOf<Int>()
        val base = r * nCols
        for (c in 1 until nCols - 1) {
            rowIds.add(base + c)
        }
        innerIds.add(rowIds)
    }
    return innerIds
};1

fun minimumGiftCost(testCases: List<Pair<Pair<Int, Int>, Triple<Int, Int, Int>>>): List<Int> {
    val results = mutableListOf<Int>()
    for ((bw, xyz) in testCases) {
        val (b, w) = bw
        val (x, y, z) = xyz
        val costBlack = minOf(x, y + z)
        val costWhite = minOf(y, x + z)
        val total = b * costBlack + w * costWhite
        results.add(total)
    }
    return results
};1

