fun processNamesAndValues(names: List<String>, values: List<List<Double>>): List<Pair<String, Double>> {
    // Guard against mismatched lengths by iterating up to the shorter one.
    val length = minOf(names.size, values.size)
    val result = mutableListOf<Pair<String, Double>>()

    for (i in 0 until length) {
        val vals = values[i]
        if (vals.isNotEmpty()) {
            val avg = vals.sum() / vals.size
            result.add(Pair(names[i], avg))
        }
    }
    // Sort by the name (first element of the pair)
    return result.sortedBy { it.first }
};1

