fun convertInt(num: Int, numBytes: Int, byteOrder: String): Pair<ByteArray, Int> {
    require(byteOrder == "big" || byteOrder == "little") {
        "byteOrder must be either 'big' or 'little'."
    }
    val bytes = ByteArray(numBytes)
    if (byteOrder == "big") {
        for (i in 0 until numBytes) {
            bytes[numBytes - i - 1] = ((num ushr (8 * i)) and 0xFF).toByte()
        }
    } else {
        for (i in 0 until numBytes) {
            bytes[i] = ((num ushr (8 * i)) and 0xFF).toByte()
        }
    }
    // Convert back to int
    var recovered = 0
    if (byteOrder == "big") {
        for (i in 0 until numBytes) {
            recovered = (recovered shl 8) or (bytes[i].toInt() and 0xFF)
        }
    } else {
        for (i in (numBytes - 1) downTo 0) {
            recovered = (recovered shl 8) or (bytes[i].toInt() and 0xFF)
        }
    }
    return Pair(bytes, recovered)
};1

fun expm(m: DoubleMatrix, tolerance: Double = 1e-15): DoubleMatrix {
    fun DoubleMatrix.correctZerosForTolerance(tol: Double) {
        for (r in 0 until this.rowLength) {
            for (c in 0 until this.colLength) {
                this[r, c] = if(abs(this[r, c]) < tol) 0.0 else this[r, c]
            }
        }
    }
    require(m.isSquare()) {
        "Matrix exponentiation only operates on square matrices"
    }

    var curr = DoubleMatrix.zeros(m.shape)
    var prev = DoubleMatrix.zeros(m.shape)
    val factorial = mutableListOf<Double>()

    var i = 0
    while (i == 0 || !checkForConvergence(curr, prev, tolerance)) {
        factorial += if (i == 0) 1.0 else i.toDouble() * factorial[i - 1]

        prev = curr
        curr = curr + (m.pow(i) / factorial[i])

        curr.correctZerosForTolerance(tolerance)

        i++
    }

    return curr
};0

