fun mergeSort(arr: List<Int>): List<Int> {
    // Base case: a list of length 0 or 1 is already sorted.
    if (arr.size <= 1) {
        return arr.toList()
    }
    // Divide: split the list into two roughly equal halves.
    val mid = arr.size / 2
    val leftHalf = mergeSort(arr.subList(0, mid))
    val rightHalf = mergeSort(arr.subList(mid, arr.size))
    // Conquer (merge): merge the two sorted halves.
    return merge(leftHalf, rightHalf)
}

fun merge(left: List<Int>, right: List<Int>): List<Int> {
    val merged = mutableListOf<Int>()
    var i = 0
    var j = 0
    while (i < left.size && j < right.size) {
        if (left[i] <= right[j]) { // "<=" ensures duplicates are preserved.
            merged.add(left[i])
            i++
        } else {
            merged.add(right[j])
            j++
        }
    }
    while (i < left.size) {
        merged.add(left[i])
        i++
    }
    while (j < right.size) {
        merged.add(right[j])
        j++
    }
    return merged
};1

fun isSelfDescribing(a: Int): Boolean {
    val s = a.toString()
    for (i in 0 until s.length) {
        val s0 = s[i].toString()
        val b = s0.toInt() // number of times i-th digit must occur for it to be a self describing number
        var count = 0
        for (j in 0 until s.length) {
            val temp = s[j].toString().toInt()
            if (temp == i) {
                count++
            }
            if (count > b) return false
        }
        if (count!= b) return false
    }
    return true
}

