fun simulateVehicles(vehicles: List<Pair<Pair<Int, Int>, String>>): List<Pair<Int, Int>> {
    fun move(position: Pair<Int, Int>, command: Char): Pair<Int, Int> {
        val (x, y) = position
        return when (command) {
            'N' -> Pair(x, y + 1)
            'S' -> Pair(x, y - 1)
            'E' -> Pair(x + 1, y)
            'W' -> Pair(x - 1, y)
            else -> Pair(x, y)
        }
    }

    val finalPositions = mutableListOf<Pair<Int, Int>>()
    for ((startPosition, commands) in vehicles) {
        var currentPosition = startPosition
        for (command in commands) {
            currentPosition = move(currentPosition, command)
        }
        finalPositions.add(currentPosition)
    }
    return finalPositions
};1

