fun findKthPositive(nums: List<Int>, k: Int): Int {
    var left = 0
    var right = nums.size - 1
    var res = nums.size
    while (left <= right) {
        val mid = (left + right) / 2
        val missing = nums[mid] - (mid + 1)
        if (missing >= k) {
            res = mid
            right = mid - 1
        } else {
            left = mid + 1
        }
    }
    return if (res != nums.size) res + k else nums.size + k
};1

 
