fun findMinMaxPeterChoice(n: Int, m: Int, variableDescriptions: List<String>): Pair<String, String> {
    val variables = mutableListOf<List<Pair<Int, Int>>>()
    val varDict = mutableMapOf<String, Int>()
    for (i in 0 until n) {
        val line = variableDescriptions[i].trim()
        val partsRest = line.split(" := ")
        val name = partsRest[0]
        val expr = partsRest[1]
        if (expr[0] == '0' || expr[0] == '1') {
            val binStr = expr
            val bits = MutableList(m) { 0 to 0 }
            for (j in 0 until m) {
                val c = binStr[m - 1 - j]
                val bit = c.toString().toInt()
                bits[j] = Pair(bit, bit)
            }
            variables.add(bits)
            varDict[name] = variables.size - 1
        } else {
            val innerParts = expr.split(' ')
            val op1 = innerParts[0]
            val op = innerParts[1]
            val op2 = innerParts[2]
            val bits = MutableList(m) { 0 to 0 }
            for (j in 0 until m) {
                val (op1_0, op1_1) = if (op1 == "?") Pair(0, 1)
                    else variables[varDict[op1]!!][j]
                val (op2_0, op2_1) = if (op2 == "?") Pair(0, 1)
                    else variables[varDict[op2]!!][j]
                val (bit0, bit1) = when(op) {
                    "AND" -> Pair(op1_0 and op2_0, op1_1 and op2_1)
                    "OR" -> Pair(op1_0 or op2_0, op1_1 or op2_1)
                    "XOR" -> Pair(op1_0 xor op2_0, op1_1 xor op2_1)
                    else -> Pair(0, 0)
                }
                bits[j] = Pair(bit0, bit1)
            }
            variables.add(bits)
            varDict[name] = variables.size - 1
        }
    }
    val sum0 = IntArray(m) { 0 }
    val sum1 = IntArray(m) { 0 }
    for (j in 0 until m) {
        for (varBits in variables) {
            sum0[j] += varBits[j].first
            sum1[j] += varBits[j].second
        }
    }
    val minP = StringBuilder()
    val maxP = StringBuilder()
    for (j in (m - 1) downTo 0) {
        if (sum0[j] < sum1[j]) {
            minP.append('0')
        } else if (sum0[j] > sum1[j]) {
            minP.append('1')
        } else {
            minP.append('0')
        }
        if (sum1[j] > sum0[j]) {
            maxP.append('1')
        } else if (sum1[j] < sum0[j]) {
            maxP.append('0')
        } else {
            maxP.append('0')
        }
    }
    return Pair(minP.toString(), maxP.toString())
};1

