fun encrypt(text: String, key: String): String {
    var res = ""
    val text = text.toUpperCase()
    for (i in 0 until text.length) {
        val c = text[i]
        if (c < 'A' || c > 'Z') continue
        res += (c + key[i % key.length] - 2 * 'A') % 26 + 'A'
    }
    return res
}
 
fun decrypt(text: String, key: String): String {
    var res = ""
    val text = text.toUpperCase()
    for (i in 0 until text.length) {
        val c = text[i]
        if (c < 'A' || c > 'Z') continue
        res += (c - key[i % key.length] + 26) % 26 + 'A'
    }
    return res
};1

