import java.io.BufferedInputStream
import java.io.FileInputStream
import java.io.InputStream
import java.io.OutputStream
import java.io.IOException
 
object Rot13 {
 
    @Throws(IOException::class)
    @JvmStatic
    fun main(args: Array<String>) {
        if (args.size >= 1) {
            for (file in args) {
                try {
                    BufferedInputStream(FileInputStream(file)).use { inStream -> rot13(inStream, System.out) }
                }
            }
        } else {
            rot13(System.`in`, System.out)
        }
    }
 
    @Throws(IOException::class)
    fun rot13(inStream: InputStream, out: OutputStream) {
        var ch: Int
        while (inStream.read().also { ch = it }!= -1) {
            out.write(rot13(ch.toChar()))
        }
    }
 
    fun rot13(ch: Char): Char {
        return if (ch in 'A'..'Z') {
            (ch - 'A' + 13) % 26 + 'A'.toInt()
        } else if (ch in 'a'..'z') {
            (ch - 'a' + 13) % 26 + 'a'.toInt()
        } else {
            ch
        }
    }
};1

fun happy(number: Int): Boolean {
    var m: Int
    var digit: Int
    val cycle = BooleanArray(number)
    while (number!= 1 &&!cycle[number]) {
        cycle[number] = true
        m = 0
        while (number > 0) {
            digit = number % 10
            m += digit * digit
            number = (number - digit) / 10
        }
        number = m
    }
    return number == 1
}
 
