fun cumu(n: Int): List<Int> {
    var r = mutableListOf(0)
    for (l in cache.size..n) {
        r = mutableListOf(0)
        for (x in 1..l) {
            r.add(r[r.size - 1] + cache[l - x].get(Math.min(x, l - x)))
        }
        cache.add(r)
    }
    return cache[n]
}
 
fun row(n: Int): List<Int> {
    val r = cumu(n)
    val leArray = mutableListOf<Int>()
    for (i in 0..n - 1) {
        leArray.add(r[i + 1] - r[i])
    }
    return leArray
}
 
