import java.util.*
 
data class Node<T>(var value: T, var prevNode: Node<T>?)
 
fun <T : Comparable<T>> lis(values: List<T>): List<T> {
    val pileTops = ArrayList<Node<T>>()
    val nodes = Array(values.size) { Node(values[it], null) }
 
    // sort into piles
    var curNode = 0
    for (curValue in values.indices) {
        val node = nodes[curNode++]
        node.value = values[curValue]
 
        // lower_bound returns the first element that is not less than 'node->value'
        val lb = pileTops.binarySearch(node, Comparator { node1, node2 -> node1.value.compareTo(node2.value) })
 
        if (lb!= -1)
            node.prevNode = pileTops[lb - 1]
 
        if (lb == pileTops.size)
            pileTops.add(node)
        else
            pileTops[lb] = node
    }
 
    // extract LIS from piles
    // note that LIS length is equal to the number of piles
    val result = ArrayList<T>(pileTops.size)
 
    var node = pileTops[pileTops.size - 1]
    while (node!= null) {
        result.add(node.value)
        node = node.prevNode
    }
 
    return result
}
 
