fun allocatePort(socketEnabled: Boolean): Int {
    if (!socketEnabled) {
        return -1
    }

    var port: Int
    try {
        ServerSocket(0).use { serverSocket ->
            port = serverSocket.localPort
        }
    } catch (e: Exception) {
        // If any exception occurs, fallback to random port
        port = Random.nextInt(1024, 65536)
    }
    // Just in case the OS gives us a port below 1024, fallback to a random one
    if (port < 1024) {
        port = Random.nextInt(1024, 65536)
    }
    return port
};1

fun parseLicenseDescriptions(descriptions: List<String>): Map<String, List<String>> {
    val licenseMap = mutableMapOf<String, MutableList<String>>()
    for (description in descriptions) {
        val idx = description.indexOf("License Type: ")
        if (idx == -1) continue
        val typeStart = idx + "License Type: ".length
        val typeEnd = description.indexOf(',', typeStart).let { if (it == -1) description.length else it }
        val licenseType = description.substring(typeStart, typeEnd).trim()
        if (licenseType in licenseMap) {
            licenseMap[licenseType]?.add(description)
        } else {
            licenseMap[licenseType] = mutableListOf(description)
        }
    }
    return licenseMap
};1

//private fun Int.toModular() = toDouble(); typealias Modular = Double
fun Int.toModular() = Modular(this)//toDouble()
private class Modular {
    companion object {
        const val M = 998244353
    }
    val x: Int
    @Suppress("ConvertSecondaryConstructorToPrimary")
    constructor(value: Int) { x = (value % M).let { if (it < 0) it + M else it } }
    operator fun plus(that: Modular) = Modular((x + that.x) % M)
    operator fun minus(that: Modular) = Modular((x + M - that.x) % M)
    operator fun times(that: Modular) = (x.toLong() * that.x % M).toInt().toModular()
    fun modInverse() = Modular(x.toBigInteger().modInverse(M.toBigInteger()).toInt())
    operator fun div(that: Modular) = times(that.modInverse())
    fun toString() = x.toString()
};0

fun parseLine(lineStr : String) : Pair<Pair<Int, Int>, Pair<Int, Int>>? {
    val regex = """(?<startX>\d+),(?<startY>\d+) -> (?<endX>\d+),(?<endY>\d+)""".toRegex()
    val result = regex.matchEntire(lineStr)!!.groups as? MatchNamedGroupCollection
    if (result != null) {
        return Pair(Pair(result["startX"]!!.value.toInt(), result["startY"]!!.value.toInt()),
            Pair(result["endX"]!!.value.toInt(), result["endY"]!!.value.toInt()))
    }
    return null
};0

fun mergeSortedLists(lst1: List<Int>, lst2: List<Int>): List<Int> {
    var i = 0
    var j = 0
    val merged = mutableListOf<Int>()

    while (i < lst1.size && j < lst2.size) {
        if (lst1[i] <= lst2[j]) {
            merged.add(lst1[i])
            i++
        } else {
            merged.add(lst2[j])
            j++
        }
    }
    if (i < lst1.size) {
        merged.addAll(lst1.subList(i, lst1.size))
    }
    if (j < lst2.size) {
        merged.addAll(lst2.subList(j, lst2.size))
    }
    return merged
};1

