fun mergeSort(data: List<String>): List<String> {
    // A list of size 0 or 1 is already sorted
    if (data.size <= 1) {
        return data.toList() // return a *new* list (copy)
    }

    // 1. Divide: split the list into two roughly equal halves
    val mid = data.size / 2
    val leftHalf = mergeSort(data.subList(0, mid)) // recursively sort left sub-list
    val rightHalf = mergeSort(data.subList(mid, data.size)) // recursively sort right sub-list

    // 2. Conquer (Merge): merge the two sorted halves into one
    val merged = mutableListOf<String>()
    var i = 0
    var j = 0

    // Merge until one side is exhausted
    while (i < leftHalf.size && j < rightHalf.size) {
        if (leftHalf[i] <= rightHalf[j]) {
            merged.add(leftHalf[i])
            i += 1
        } else {
            merged.add(rightHalf[j])
            j += 1
        }
    }

    // Append any remaining elements (only one of these will execute)
    if (i < leftHalf.size) {
        merged.addAll(leftHalf.subList(i, leftHalf.size))
    }
    if (j < rightHalf.size) {
        merged.addAll(rightHalf.subList(j, rightHalf.size))
    }

    return merged
};1

