fun Pascal_Triangle(size: Int) {
    val a = Array(100) { IntArray(100) }
    var i = 0
    var j = 0
    //first row and first coloumn has the same value=1
    i = 1
    while (i <= size) {
        a[i][1] = a[1][i] = 1
        i++
    }
    //Generate the full Triangle
    i = 2
    while (i <= size) {
        j = 2
        while (j <= size - i) {
            if (a[i - 1][j] == 0 || a[i][j - 1] == 0) {
                break
            }
            a[i][j] = a[i - 1][j] + a[i][j - 1]
            j++
        }
        i++
    }
    /*
      1 1 1 1
      1 2 3
      1 3
      1
 
    first print as above format-->
 
    for (i = 1; i < size; i++) {
        for (j = 1; j < size; j++) {
            if (a[i][j] == 0) {
                    break;
            }
                printf("%8d",a[i][j]);
        }
            cout<<"\n\n";
    }*/
    // standard Pascal Triangle Format
    i = 1
    while (i < size) {
        var space = i
        var row = i
        j = 1
        while (space <= size + (size - i) + 1) {
            print(" ")
            space++
        }
        while (j <= i) {
            if (a[row][j] == 0) {
                break
            }
            if (j == 1) {
                print(a[row--][j++])
            } else {
                print("%6d".format(a[row--][j++]))
            }
        }
        println("\n\n")
        i++
    }
};1

