            .boxed()
            .toArray()
    recursive(array)
    println()
    loop(array)
}
 
fun recursive(array: Array<Any>) {
    recursive(array, array.size, true)
}
 
fun recursive(array: Array<Any>, n: Int, plus: Boolean) {
    if (n == 1) {
        output(array, plus)
    } else {
        for (i in 0 until n) {
            recursive(array, n - 1, i == 0)
            swap(array, if (n % 2 == 0) i else 0, n - 1)
        }
    }
}
 
fun output(array: Array<Any>, plus: Boolean) {
    println(Arrays.toString(array) + if (plus) " +1" else " -1")
}
 
fun swap(array: Array<Any>, a: Int, b: Int) {
    val o = array[a]
    array[a] = array[b]
    array[b] = o
}
 
fun loop(array: Array<Any>) {
    loop(array, array.size)
}
 
fun loop(array: Array<Any>, n: Int) {
    val c = IntArray(n)
    output(array, true)
    var plus = false
    for (i in 0 until n) {
        if (c[i] < i) {
            if (i % 2 == 0) {
                swap(array, 0, i)
            } else {
                swap(array, c[i], i)
            }
            output(array, plus)
            plus =!plus
            c[i]++
            i = 0
        } else {
            c[i] = 0
            i++
        }
    }
};1

