fun rotateLoads(graph: List<Pair<Int, Int>>, loads: List<Int>): List<Int> {
    val n = loads.size
    val adj = MutableList(n) { mutableListOf<Int>() }
    for ((u, v) in graph) {
        adj[u].add(v)
    }
    val newLoads = MutableList(n) { 0 }
    for (u in 0 until n) {
        val outDeg = adj[u].size
        if (outDeg == 0) {
            newLoads[u] += loads[u]
        } else {
            val base = loads[u] / outDeg
            val rem = loads[u] % outDeg
            for ((idx, v) in adj[u].withIndex()) {
                val add = base + if (idx < rem) 1 else 0
                newLoads[v] += add
            }
        }
    }
    return newLoads
};1

fun canMakePaliQueries(s: String, queries: List<List<Int>>): List<Boolean> {
    val n = s.length
    val prefix = IntArray(n + 1)
    var mask = 0
    for (i in s.indices) {
        val ch = s[i]
        mask = mask xor (1 shl (ch - 'a'))
        prefix[i + 1] = mask
    }

    fun popcount(x: Int): Int {
        return Integer.bitCount(x)
    }

    val ans = mutableListOf<Boolean>()
    for (query in queries) {
        val left = query[0]
        val right = query[1]
        val k = query[2]
        val m = prefix[right + 1] xor prefix[left]
        val oddCount = popcount(m)
        val length = right - left + 1
        ans.add(oddCount <= 2 * k + (length and 1))
    }
    return ans
};1

