fun validateAndCleanData(data: List<Map<String, Any?>>): Pair<List<Map<String, Any>>, Boolean> {
    val validUsers = mutableListOf<Map<String, Any>>()
    val emailRegex = Pattern.compile("^[^@\s]+@[^@\s]+\\.[^@\s]+$")

    for (user in data) {
        val userId = user["id"]
        val name = user["name"]
        val email = user["email"]

        // Validate 'id'
        if (userId !is Int || userId <= 0) {
            continue
        }
        // Validate 'name'
        if (name !is String || name.trim().isEmpty()) {
            continue
        }
        // Validate 'email'
        if (email !is String || !emailRegex.matcher(email.trim()).matches()) {
            continue
        }
        val cleanedUser = mapOf(
            "id" to userId,
            "name" to name.trim(),
            "email" to email.trim()
        )
        validUsers.add(cleanedUser)
    }
    val allValid = validUsers.size == data.size
    return Pair(validUsers, allValid)
};1

