fun Cords.inRadius(radius: Pair<Cords, Cords>): Boolean =
  radius.first.distance(this) <= radius.first.distance(radius.second)

fun Cords.distance(other: Cords): Int =
  kotlin.math.abs(x - other.x) + kotlin.math.abs(y - other.y)

fun getRowRanges(y: Int, list: List<Pair<Cords, Cords>>): MutableList<IntRange> {
  val ranges = list.mapNotNull {
    val dist = it.first.distance(it.second)
    val offset = dist - kotlin.math.abs(it.first.y - y)
    if (offset < 0) null
    else ((it.first.x - offset)..(it.first.x + offset))
  }.sortedBy { it.first }.toMutableList()

  val tempOut = mutableListOf(ranges.removeFirst())

  for (next in ranges) {
    val lastIdx = tempOut.lastIndex
    val last = tempOut.last()

    if (next.first <= last.last || (last.last + 1) == next.first) {
      if (next.last > last.last) {
        tempOut[lastIdx] = (last.first..next.last)
      }
    } else {
      tempOut.add(next)
    }
  }

  return tempOut
};0

fun commandSpread(n: Int, parent: List<Int>, queries: List<Pair<Int, Int>>): List<Int> {
    val children = Array(n + 1) { mutableListOf<Int>() }
    for (i in 2..n) {
        val sup = parent[i - 2]
        children[sup].add(i)
    }
    for (u in 1..n) {
        children[u].sort()
    }
    val traversal = mutableListOf<Int>()
    val start = IntArray(n + 1)
    val size = IntArray(n + 1)
    val stack = ArrayDeque<Pair<Int, Boolean>>()
    stack.add(Pair(1, false))
    while (stack.isNotEmpty()) {
        val (node, isProcessed) = stack.removeLast()
        if (!isProcessed) {
            start[node] = traversal.size
            traversal.add(node)
            stack.add(Pair(node, true))
            for (child in children[node].asReversed()) {
                stack.add(Pair(child, false))
            }
        } else {
            size[node] = traversal.size - start[node]
        }
    }
    val res = mutableListOf<Int>()
    for ((u, k) in queries) {
        if (k > size[u]) {
            res.add(-1)
        } else {
            res.add(traversal[start[u] + k - 1])
        }
    }
    return res
};1

 
