fun filterRssFeeds(urls: List<String>): List<String> {
    // Filter and return a sorted list of unique RSS feed URLs.
    // A URL is considered a valid RSS feed link if it ends with
    // '.rss', '.xml', or '.feed' (case–insensitive).
    val validSuffixes = listOf(".rss", ".xml", ".feed")
    val seen = mutableSetOf<String>()
    for (url in urls) {
        val lowerUrl = url.lowercase()
        if (validSuffixes.any { lowerUrl.endsWith(it) }) {
            seen.add(url)
        }
    }
    return seen.toList().sorted()
};1

fun incrementRecursively(energyLevels: Array<IntArray>, flashed: Array<BooleanArray>, i: Int, j: Int) {
    val outOfBounds = outOfBounds(i, j, energyLevels.size, energyLevels[0].size)
    if (outOfBounds || flashed[i][j]) {
        return
    }
    energyLevels[i][j]++
    if (energyLevels[i][j] <= 9) {
        return
    }
    flashed[i][j] = true
    energyLevels[i][j] = 0
    for (di in -1..1) {
        for (dj in -1..1) {
            incrementRecursively(energyLevels, flashed, i + di, j + dj)
        }
    }
};0

fun createStack(list: List<String>): MutableMap<Int, MutableList<Char>> {
    val stack = mutableMapOf<Int, MutableList<Char>>()

    list
        .takeWhile { it.isNotBlank() }
        .dropLast(1)
        .map { it.chunked(4) }
        .map { it.map { box -> box[1] } }
        .forEach {
            it.forEachIndexed { idx, box ->
                if (!box.isWhitespace()) {
                    stack[idx + 1]?.add(0, box) ?: mutableListOf(box)
                }
            }
        }

    return stack
};0

