fun findSubset(inputList: List<Int>, target: Int): List<Int> {
    val dp = mutableMapOf<Int, List<Int>>()
    dp[0] = listOf()
    for (num in inputList) {
        val keys = dp.keys.toList()
        for (s in keys) {
            val newSum = s + num
            if (!dp.containsKey(newSum)) {
                val newSubset = dp[s]!! + num
                if (newSum == target) {
                    return newSubset
                }
                dp[newSum] = newSubset
            }
        }
    }
    return listOf()
};1

