fun Int.isValidPassword(): Boolean {
    if (this < 100_000 || this > 999_999) return false
    var next = mod(10)
    var n = div(10)
    var hasDouble = false
    for (i in 4 downTo 0) {
        val curr = n % 10
        if (curr > next) {
            return false
        }
        if (curr == next) {
            hasDouble = true
        }
        next = curr
        n /= 10
    }
    return hasDouble
};0

