// returns all ancestors of n. n is not its own ancestor.
fun get_ancestors(ancestor: List<integer>, n: integer): List<integer> {
    val result = ArrayList<integer>()
    var a = ancestor[n.toInt()]
    while (a!= 0L && a!= n) {
        n = a
        a = ancestor[n.toInt()]
        result.add(n)
    }
    return result
}
 
