fun is_prime(n: integer): Boolean {
    if (n < 2)
        return false
    if (n % 2 == 0L)
        return n == 2L
    var p = 3L
    while (p * p <= n) {
        if (n % p == 0L)
            return false
        p += 2
    }
    return true
}
 
fun main(args: Array<String>) {
    val limit = 100L
 
    val ancestor = Array(limit.toInt(), { 0L })
    val descendants = Array(limit.toInt(), { ArrayList<integer>() })
 
    for (prime in 0 until limit) {
        if (!is_prime(prime))
            continue
        descendants[prime.toInt()].add(prime)
        for (i in 0 until limit - prime) {
            val s = i + prime
            for (n in descendants[i.toInt()]) {
                val prod = n * prime
                descendants[s.toInt()].add(prod)
                if (prod < limit)
                    ancestor[prod.toInt()] = s
            }
        }
    }
 
    // print the results
    var total_descendants = 0
    for (i in 1 until limit) {
        val ancestors = get_ancestors(ancestor.toList(), i)
        println("[$i] Level: ${ancestors.size}")
        println("Ancestors: ")
        ancestors.sort()
        print_vector(ancestors)
 
        println("Descendants: ${descendants[i.toInt()].size}")
        total_descendants += descendants[i.toInt()].size
        if (descendants[i.toInt()].isNotEmpty())
            print_vector(descendants[i.toInt()])
        println()
    }
    println("Total descendants: $total_descendants")
};1

 
