val MAX_SIZE = 100
 
fun move_to_front(str: String, c: Char): Int {
    var shift = 0
    val p = str.toCharArray()
    val q = str.indexOf(c)
    shift = q
    val temp = p[0]
    p[0] = c
    for (i in 1..q) {
        p[i] = temp
    }
    return shift
}
 
fun decode(pass: IntArray, size: Int, sym: CharArray) {
    var index = 0
    var c: Char
    val table = "abcdefghijklmnopqrstuvwxyz"
    for (i in 0..size - 1) {
        c = table[pass[i]]
        index = move_to_front(table, c)
        if (pass[i]!= index) {
            System.out.println("there is an error")
        }
        sym[i] = c
    }
    sym[size] = '\u0000'
}
 
fun encode(sym: CharArray, size: Int, pass: IntArray) {
    var i = 0
    var c: Char
    val table = "abcdefghijklmnopqrstuvwxyz"
    for (i in 0..size - 1) {
        c = sym[i]
        pass[i] = move_to_front(table, c)
    }
}
 
fun check(sym: CharArray, size: Int, pass: IntArray): Int {
    val pass2 = IntArray(size)
    val sym2 = CharArray(size)
    var i = 0
    var val_ = 1
 
    encode(sym, size, pass2)
    i = 0
    while (i < size && pass[i] == pass2[i]) {
        i++
    }
    if (i!= size) {
        val_ = 0
    }
 
    decode(pass, size, sym2)
    if (String(sym)!= String(sym2)) {
        val_ = 0
    }
 
    return val_
}
 
fun main(args: Array<String>) {
    val sym = arrayOf("broood", "bananaaa", "hiphophiphop")
    val pass = IntArray(MAX_SIZE)
