    var len = 0
    var j = 0
    for (i in 0..2) {
        len = sym[i].length
        encode(sym[i].toCharArray(), len, pass)
        System.out.print(sym[i] + " : [")
        for (j in 0..len - 1) {
            System.out.print(pass[j] + " ")
        }
        System.out.println("]")
        if (check(sym[i].toCharArray(), len, pass) == 1) {
            System.out.println("Correct :)")
        } else {
