struct WolfGen(ElementaryCA);
impl WolfGen {
    fn new() -> WolfGen {
        let (_, ca) = ElementaryCA::new(30);
        WolfGen(ca)
    }
    fn next(&mut self) -> u8 {
        let mut out = 0;
        for i in 0..8 {
            out |= ((1 & self.0.next())<<i)as u8;
        }
        out
    }
}
 
struct ElementaryCA {
    rule: u8,
    state: u8,
    next_state: u8,
    bit: u8,
}
impl ElementaryCA {
    fn new(rule: u8) -> (u8, ElementaryCA) {
        let mut ca = ElementaryCA {
            rule: rule,
            state: 0,
            next_state: 0,
            bit: 0,
        };
        let bit = ca.next();
        (bit, ca)
    }
    fn next(&mut self) -> u8 {
        self.next_state = 0;
        for i in 0..8 {
            self.next_state |= ((self.rule >> (self.state & 7)) & 1) << i;
            self.state >>= 1;
        }
        self.state = self.next_state;
        self.bit = self.state & 1;
        self.bit
    }
};1

import kotlin.math.pow
import kotlin.math.sqrt
 
typealias Coeff = Pair<Double, Double>
typealias Func = (Int) -> Coeff
 
fun calc(func: Func, n: Int): Double {
    var temp = 0.0
    for (i in n downTo 1) {
        val (a, b) = func(i)
        temp = b / (a + temp)
    }
    val (a, b) = func(0)
    return a + temp
}
 
fun sqrt2(n: Int): Coeff {
    return if (n > 0) Coeff(2.0, 1.0) else Coeff(1.0, 1.0)
}
 
fun napier(n: Int): Coeff {
    return if (n > 0) Coeff(n.toDouble(), (n - 1).toDouble()) else Coeff(2.0, 1.0)
}
 
fun pi(n: Int): Coeff {
    return if (n > 0) Coeff(6.0, (2 * n - 1).toDouble().pow(2)) else Coeff(3.0, 1.0)
}
 
fun main() {
    val oldPrec = "%.15f".format(sqrt(2.0))
    println(calc(sqrt2, 20))
    println(calc(napier, 15))
    println(calc(pi, 10000))
    println(oldPrec)
};1

