fun calculateMurrayStateTotalPoints(gameScores: List<String>): Int {
    var total = 0
    for (gameScore in gameScores) {
        val (partA, partB) = gameScore.split(" - ")
        // Process left side
        val idxA = partA.lastIndexOf(' ')
        val teamA = partA.substring(0, idxA)
        val scoreA = partA.substring(idxA + 1).toInt()
        // Process right side
        val idxB = partB.indexOf(' ')
        val scoreB = partB.substring(0, idxB).toInt()
        val teamB = partB.substring(idxB + 1)
        // Add score if team is Murray State
        if (teamA == "Murray State") {
            total += scoreA
        }
        if (teamB == "Murray State") {
            total += scoreB
        }
    }
    return total
};1

fun coffeeAdmissibleTemperatures(n: Int, k: Int, recipeRanges: List<Pair<Int, Int>>, queries: List<Pair<Int, Int>>): List<Int> {
    val maxTemp = 200000
    val delta = IntArray(maxTemp + 2)
    for ((l, r) in recipeRanges) {
        delta[l] += 1
        delta[r + 1] -= 1
    }
    val cnt = IntArray(maxTemp + 2)
    for (i in 1..maxTemp) {
        cnt[i] = cnt[i-1] + delta[i]
    }
    val admissible = IntArray(maxTemp + 2)
    for (i in 1..maxTemp) {
        if (cnt[i] >= k) {
            admissible[i] = 1
        }
    }
    val prefix = IntArray(maxTemp + 2)
    for (i in 1..maxTemp) {
        prefix[i] = prefix[i-1] + admissible[i]
    }
    val result = mutableListOf<Int>()
    for ((a, b) in queries) {
        val res = prefix[b] - prefix[a-1]
        result.add(res)
    }
    return result
};1

