fun minimumSeconds(k: Int, b: Int, n: Int, t: Int): Int {
    // Compute final bacteria z after n seconds in experiment 1 (with 1 initial)
    var x = 1
    repeat(n) {
        x = k * x + b
    }
    val z = x
    // Now starting with t, find minimal m s.t. after m seconds, bacteria >= z
    var m = 0
    var y = t
    while (y < z) {
        y = k * y + b
        m += 1
    }
    return m
};1

 
fun binomial(n: Int, k: Int) = when {
    n < 0 || k < 0 -> throw IllegalArgumentException("negative numbers not allowed")
    n == k         -> 1L
    else           -> {
        val kReduced = min(k, n - k)    // minimize number of steps
        var result = 1L
        var numerator = n
        var denominator = 1
        while (denominator <= kReduced)
            result = result * numerator-- / denominator++
        result
    }
}
 
