/**
 * Given an integer array nums of length n and an integer target, find three integers in nums such that the sum is closest to target.
 * Return the sum of the three integers.
 *
 * [Source](https://leetcode.com/problems/3sum-closest/)
 */
fun threeSumClosest(nums: IntArray, target: Int): Int {
    require(nums.size >= 3)
    val sorted = nums.sorted()
    var closest = sorted[0] + sorted[1] + sorted.last()

    for (i in 0..sorted.lastIndex) {
        // `i` is fixed, left & right keeps converging to middle
        var left = i + 1
        var right = sorted.lastIndex
        while (left < right) {
            // sum right now
            val sums = sorted[left] + sorted[right] + sorted[i]
            if (sums == target) {
                // closest value is 0 so return immediately
                println("${sorted[left]} ${sorted[right]} ${sorted[i]}")
                return sums
            } else if (abs(sums - target) < abs(closest - target)) {
                // update if closer value is found
                println("${sorted[left]} ${sorted[right]} ${sorted[i]}")
                closest = sums
            }
            if (sums > target) {
                // Sum is larger so decrease right index
                right -= 1
            } else if (sums < target) {
                // Smaller so increase left index
                left += 1
            }
        }
    }
    return closest
};0

fun getNewList(list: List<String>, position: Int, criteria: Char, length: Int): List<String> {
    if (list.size == 1) return list
    val criteriaBit = getBit(list, position, criteria) //get the new criteria bit which will determine the new list for the next step of the recursion.
    val shorterList = mutableListOf<String>()
    list.forEach { //if the position in each number matches the criteria bit, append the number to the new list.
        if (it[position] == criteriaBit) shorterList += it
    }
    return getNewList(shorterList, position + 1, criteria, length) //next step of the recursion with the new list and the next position.
};0

fun organizeTestResults(testResults: List<Map<String, String>>): Map<String, Map<String, Int>> {
    val athleteResults = mutableMapOf<String, MutableMap<String, Int>>()
    for (result in testResults) {
        val athlete = result["athlete"]!!
        val testResult = result["result"]!!
        if (athlete !in athleteResults) {
            athleteResults[athlete] = mutableMapOf(
                "total_tests" to 0,
                "positive_tests" to 0,
                "negative_tests" to 0
            )
        }
        athleteResults[athlete]!!["total_tests"] = athleteResults[athlete]!!["total_tests"]!! + 1
        if (testResult == "positive") {
            athleteResults[athlete]!!["positive_tests"] = athleteResults[athlete]!!["positive_tests"]!! + 1
        } else {
            athleteResults[athlete]!!["negative_tests"] = athleteResults[athlete]!!["negative_tests"]!! + 1
        }
    }
    // Convert the mutable maps to regular maps in the result
    return athleteResults.mapValues { it.value.toMap() }
};1

fun buildMaxHeap(openSet: ArrayList<Pair<Int, Int>>, fScore: HashMap<Pair<Int, Int>, Double>): ArrayList<Pair<Int, Int>> {
