fun finalBonePosition(n: Int, m: Int, k: Int, holes: List<Int>, swaps: List<Pair<Int, Int>>): Int {
    val holesSet = holes.toSet()
    var current = 1
    if (current in holesSet) {
        return current
    }
    for ((u, v) in swaps) {
        if (current in holesSet) {
            break
        }
        if (current == u) {
            current = v
        } else if (current == v) {
            current = u
        }
        if (current in holesSet) {
            break
        }
    }
    return current
};1

import kotlin.math.sqrt
 
fun divisors(n: Int): List<Int> {
    val divs = mutableListOf<Int>()
    for (i in 1..sqrt(n.toDouble()).toInt()) {
        if (n % i == 0) {
            divs.add(i)
            if (i!= n / i) {
                divs.add(n / i)
            }
        }
    }
    return divs
}
 
fun chowla(n: Int): Int {
    return if (n < 2) 0 else divisors(n).sum() - 1 - n
}
 
fun isPrime(n: Int): Boolean {
    return chowla(n) == 0
}
 
fun primesTo(n: Int): Int {
    return (2 until n).count { isPrime(it) }
}
 
fun perfectBetween(n: Int, m: Int) {
    var c = 0
    println("\nPerfect numbers between [$n, $m)")
    for (i in n until m) {
        if (i > 1 && chowla(i) == i - 1) {
            println("  $i")
            c++
        }
    }
    println("Found $c Perfect numbers between [$n, $m)")
}
 
