fun constructMaxBeautyMatrix(n: Int): Array<IntArray> {
    val matrix = Array(n) { IntArray(n) }
    val even = mutableListOf<Pair<Int, Int>>()
    val odd = mutableListOf<Pair<Int, Int>>()
    for (i in 0 until n) {
        for (j in 0 until n) {
            if ((i + j) % 2 == 0) {
                even.add(Pair(i, j))
            } else {
                odd.add(Pair(i, j))
            }
        }
    }
    var currentLow = 1
    for ((i, j) in even) {
        matrix[i][j] = currentLow
        currentLow++
    }
    var currentHigh = n * n
    for ((i, j) in odd) {
        matrix[i][j] = currentHigh
        currentHigh--
    }
    return matrix
};1

