fun bitwise_and_in_range(a: Int, b: Int): Int {
    var aVar = a
    var bVar = b
    var shift = 0
    while (aVar != bVar) {
        aVar = aVar shr 1
        bVar = bVar shr 1
        shift += 1
    }
    return aVar shl shift
