fun minPowerToDestroyBase(n: Int, k: Int, A: Int, B: Int, avengers: List<Int>): Long {
    val sortedAvengers = avengers.sorted()
    val length = 1 shl n

    fun helper(start: Int, end: Int): Long {
        val left = Collections.binarySearch(sortedAvengers, start).let {
            if (it < 0) -it - 1 else it
        }
        val rightIdx = Collections.binarySearch(sortedAvengers, end + 1).let {
            if (it < 0) -it - 1 else it
        }
        val count = rightIdx - left
        if (count == 0) {
            return A.toLong()
        }
        val currentLen = end - start + 1
        val burn = B.toLong() * count * currentLen
        if (currentLen == 1) {
            return burn
        }
        val mid = (start + end) / 2
        val split = helper(start, mid) + helper(mid + 1, end)
        return minOf(burn, split)
    }

    return helper(1, length)
};1

