fun isPositive(num: Any): Boolean {
    /**
     * Return true if num is strictly greater than zero, false otherwise.
     * Will throw a ClassCastException or Exception if the supplied argument cannot be compared
     * with zero (this is fine—validateData will treat it as a failure).
     */
    if (num is Number) {
        return num.toDouble() > 0
    } else {
        throw IllegalArgumentException("Not a number")
    }
}

fun isEven(num: Any): Boolean {
    /**
     * Return true if num is an even integer, false otherwise.
     * Exception (e.g., for non-numeric data) is allowed and will be
     * handled by validateData as a failed validation.
     */
    if (num is Number) {
        // Get the integer value
        val intVal = when(num) {
            is Byte -> num.toInt()
            is Short -> num.toInt()
            is Int -> num
            is Long -> num.toInt()
            is Float -> num.toInt()
            is Double -> num.toInt()
            else -> throw IllegalArgumentException("Not a numeric value")
        }
        return intVal % 2 == 0
    } else {
        throw IllegalArgumentException("Not a number")
    }
}

fun isAlphabetic(string: Any): Boolean {
    /**
     * Return true if the given string consists only of alphabetic
     * characters (at least one), false otherwise.
     * Non-string inputs will throw an exception, which counts
     * as a failure inside validateData.
     */
    if (string is String) {
        return string.isNotEmpty() && string.all { it.isLetter() }
    } else {
        throw IllegalArgumentException("Not a string")
    }
}

fun validateData(inputData: List<Any>, vararg validators: (Any) -> Boolean): Map<String, Int> {
    /**
     * Validate every element in `inputData` using each function supplied in `validators`.
     *
     * Returns
     * -------
     * Map with keys:
     *     "passed" : total number of successful validations
     *     "failed" : total number of failed validations, including
     *                those where the validator threw an exception.
     */
    val results = mutableMapOf("passed" to 0, "failed" to 0)
    for (item in inputData) {
        for (validator in validators) {
            try {
                if (validator(item)) {
                    results["passed"] = results["passed"]!! + 1
                } else {
                    results["failed"] = results["failed"]!! + 1
                }
            } catch (e: Exception) {
                results["failed"] = results["failed"]!! + 1
            }
        }
    }
    return results
};1

fun minimal_conversions(str1: String, str2: String): Int {
    val n = str1.length
    var minTotal = Int.MAX_VALUE
    val indices = (0 until n).toList()
    fun <T> permutations(list: List<T>): List<List<T>> {
        if (list.isEmpty()) return listOf(emptyList())
        return list.flatMap { item ->
            permutations(list - item).map { sub -> listOf(item) + sub }
        }
    }
    for (perm in permutations(indices)) {
        // Permute str1 according to perm
        val permStr = perm.map { str1[it] }
        var sumSteps = 0
        for (i in 0 until n) {
            val c1 = permStr[i]
            val c2 = str2[i]
            sumSteps += abs(c1.code - c2.code)
        }
        // Count swaps as n - number of cycles in the permutation
        val visited = BooleanArray(n) { false }
        var cycles = 0
        for (i in 0 until n) {
            if (!visited[i]) {
                cycles += 1
                var j = i
                while (!visited[j]) {
                    visited[j] = true
                    j = perm[j]
                }
            }
        }
        val swapSteps = n - cycles
        val total = sumSteps + swapSteps
        if (total < minTotal) {
            minTotal = total
        }
    }
    return minTotal
};1

import kotlin.math.*
 
fun Legendre(n: Int, x: Double): Double {
    if (n == 0) {
        return 1.0
    } else if (n == 1) {
        return x
    } else {
        return ((2.0 * n - 1.0) * x * Legendre(n - 1, x) - (n - 1) * Legendre(n - 2, x)) / n
    }
}
 
fun DLegendre(n: Int, x: Double): Double {
    if (n == 0) {
        return 0.0
    } else if (n == 1) {
        return 1.0
    } else {
        return (n / (x * x - 1.0)) * (x * Legendre(n, x) - Legendre(n - 1, x))
    }
}
 
fun LegendreRoots(polyorder: Int, tolerance: Double = 1e-20): Pair<List<Double>, Int> {
    if (polyorder < 2) {
        return Pair(emptyList(), 1)
    } else {
        val roots = mutableListOf<Double>()
        for (i in 1..(polyorder / 2 + 1)) {
            var x = cos(PI * (i - 0.25) / (polyorder + 0.5))
            var error = 10 * tolerance
            var iters = 0
            while (error > tolerance && iters < 1000) {
                val dx = -Legendre(polyorder, x) / DLegendre(polyorder, x)
                x += dx
                iters++
                error = abs(dx)
            }
            roots.add(x)
        }
        val rootsArray = roots.toDoubleArray()
        if (polyorder % 2 == 0) {
            rootsArray.reverse()
            return Pair((-1.0 * rootsArray).toList() + rootsArray.toList(), 0)
        } else {
            rootsArray.reverse()
            return Pair((-1.0 * rootsArray).toList() + listOf(0.0) + rootsArray.toList(), 0)
        }
    }
}
 
fun GaussLegendreWeights(polyorder: Int): Pair<List<Double>, List<Double>> {
    val (xis, err) = LegendreRoots(polyorder)
    if (err == 0) {
        val Ws = mutableListOf<Double>()
        for (xi in xis) {
            Ws.add(2.0 / ((1.0 - xi * xi) * (DLegendre(polyorder, xi) * DLegendre(polyorder, xi))))
        }
        return Pair(Ws, xis)
    } else {
        return Pair(emptyList(), emptyList())
    }
}
 
fun GaussLegendreQuadrature(func: (Double) -> Double, polyorder: Int, a: Double, b: Double): Pair<Double, Int> {
    val (Ws, xs, err) = GaussLegendreWeights(polyorder)
    if (err == 0) {
        var ans = 0.0
        for (i in 0 until Ws.size) {
            ans += Ws[i] * func((b - a) * 0.5 * xs[i] + (b + a) * 0.5)
        }
        return Pair((b - a) * 0.5 * ans, 0)
    } else {
        return Pair(0.0, 1)
    }
}
 
