class Rectangle(dimensions: Pair<Int, Int>) {
    var width: Int = dimensions.first
    var height: Int = dimensions.second

    init {
        if (!(width is Int && height is Int && listOf(width, height).all { it > 0 })) {
            throw IllegalArgumentException("Both width and height must be positive integers")
        }
    }

    fun area(): Int {
        return listOf(width * height).sum()
    }

    fun isSquare(): Boolean {
        if (!listOf(width, height).all { it is Int && it > 0 }) {
            throw IllegalArgumentException("Both width and height must be positive integers")
        }
        return width == height
    }
