fun hcfTwo(a: Int, b: Int): Int {
    var aAbs = Math.abs(a)
    var bAbs = Math.abs(b)
    while (bAbs != 0) {
        val temp = bAbs
        bAbs = aAbs % bAbs
        aAbs = temp
    }
    return aAbs
}

fun hcfOfThree(a: Int, b: Int, c: Int): Int {
    val hcfAB = hcfTwo(a, b)
    val hcfABC = hcfTwo(hcfAB, c)
    return hcfABC
