fun deal(deck: ArrayList<Card>, size: Int, target: Int, random: Random) {
    val sets = ArrayList<(Card, Card, Card)>()
    do {
        shuffle(deck, random)
        for (i in 0 until size - 2) {
            for (j in i + 1 until size - 1) {
                for (k in j + 1 until size) {
                    val t = Triple(deck[i], deck[j], deck[k])
                    if (isSet(t)) {
                        sets.add(t)
                    }
                }
            }
        }
    } while (sets.size!= target)
    println("The board:")
    for (card in deck.subList(0, size)) {
        println(card)
    }
    println()
    println("Sets:")
    for (s in sets) {
        println(s)
    }
}
 
fun shuffle(array: ArrayList<Card>, random: Random) {
    for (i in 0 until array.size) {
        val r = random.nextInt(i, array.size)
        val temp = array[r]
        array[r] = array[i]
        array[i] = temp
    }
}
 
