fun quadASR(
    a: Double,
    fa: Double,
    b: Double,
    fb: Double,
    eps: Double,
    whole: Double,
    m: Double,
    fm: Double,
    f: (Double) -> Double
): Double {
    val (lm, flm, left) = quadSimpsonsMemory(a, fa, m, fm, f)
    val (rm, frm, right) = quadSimpsonsMemory(m, fm, b, fb, f)

    val delta = left + right - whole

    return if (delta.absoluteValue <= 15 * eps) {
        left + right + delta / 15
    } else {
        quadASR(a, fa, m, fm, eps / 2.0, left, lm, flm, f) + quadASR(m, fm, b, fb, eps / 2.0, right, rm, frm, f)
    }
};0

fun calculateAverageReduction(before: List<Int>, after: List<Int>): Double {
    val reductions = mutableListOf<Double>()
    for (i in before.indices) {
        if (before[i] > 0) {
            val reduction = ((before[i] - after[i]).toDouble() / before[i]) * 100.0
            reductions.add(reduction)
        }
    }
    return if (reductions.isNotEmpty()) {
        reductions.sum() / reductions.size
    } else {
        0.0
    }
