fun calculateSiteAreas(sites: List<Map<String, Any>>): Map<String, Number> {
    val areas = mutableMapOf<String, Number>()
    for (site in sites) {
        val name = site["name"] as String
        val length = site["length"]
        val width = site["width"]
        val area = when {
            length is Int && width is Int -> length * width
            length is Double && width is Double -> length * width
            length is Int && width is Double -> length * width
            length is Double && width is Int -> length * width
            else -> throw IllegalArgumentException("Invalid length or width type.")
        }
        areas[name] = area
    }
    return areas
