fun check(a: Int, b: Int, s: String): Boolean {
    return when {
        a > b * 2 -> {
            println("\"$s\" is plausible ($a vs $b).")
            true
        }
        a >= b -> {
            println("\"$s\" is implausible ($a vs $b).")
            false
        }
        else -> {
            println("\"$s\" is implausible and contra-indicated ($a vs $b).")
            false
        }
    }
