fun cubicRootOdd(value: Any?): Any {
    // 1. Input validation
    if (value == null || value is Boolean || value !is Int) {
        return "Invalid input"
    }

    // 2. Work with the absolute value
    val n = kotlin.math.abs(value)

    // 3. Obtain an integer candidate for the cube root
    val root = if (n == 0) {
        0
    } else {
        var r = Math.round(Math.pow(n.toDouble(), 1.0 / 3.0)).toInt()
        while (r * r * r < n) {
            r += 1
        }
        while (r * r * r > n) {
            r -= 1
        }
        r
    }

    // 4. Decide perfect cube status and oddness of the root
    if (root * root * root != n) {
        return false
    }
    return root % 2 != 0
};1

