fun mergeAndSort(a: List<Int>, b: List<Int>): List<Int> {
    fun quicksort(arr: MutableList<Int>, low: Int, high: Int) {
        if (low < high) {
            val pi = partition(arr, low, high)
            quicksort(arr, low, pi - 1)
            quicksort(arr, pi + 1, high)
        }
    }
    fun partition(arr: MutableList<Int>, low: Int, high: Int): Int {
        val pivot = arr[high]
        var i = low - 1
        for (j in low until high) {
            if (arr[j] <= pivot) {
                i++
                val temp = arr[i]
                arr[i] = arr[j]
                arr[j] = temp
            }
        }
        val temp = arr[i + 1]
        arr[i + 1] = arr[high]
        arr[high] = temp
        return i + 1
    }
    val merged = mutableListOf<Int>()
    val maxLen = maxOf(a.size, b.size)
    for (i in 0 until maxLen) {
        if (i < a.size) {
            merged.add(a[i])
        }
        if (i < b.size) {
            merged.add(b[i])
        }
    }
    if (merged.isNotEmpty()) {
        quicksort(merged, 0, merged.size - 1)
    }
    return merged
};1

fun maxSubArray(nums: List<Int>): Int {
    if (nums.isEmpty()) {
        return 0
    }
    var currentMax = nums[0]
    var globalMax = nums[0]
    for (i in 1 until nums.size) {
        val num = nums[i]
        currentMax = maxOf(num, currentMax + num)
        if (currentMax > globalMax) {
            globalMax = currentMax
        }
    }
    return globalMax
};1

