fun fillDatabase(
    filePath: String,
    settingsConfig: Map<String, Any>,
    measurementInputs: Map<String, Any>,
    gridConfig: Map<String, Any>,
    parentLocationId: Int,
    sexId: Int,
    childPrior: Map<String, Any>,
    multiCovariatePrior: Map<Any, Any>
): Map<String, Any> {
    if (filePath !is String) {
        throw IllegalArgumentException("filePath must be a String.")
    }
    if (parentLocationId !is Int) {
        throw IllegalArgumentException("parentLocationId must be an Int.")
    }
    if (sexId !is Int) {
        throw IllegalArgumentException("sexId must be an Int.")
    }
    // Make deep copies to prevent mutation.
    val result: MutableMap<String, Any> = HashMap()
    result["path"] = filePath
    result["settings"] = deepCopy(settingsConfig)
    result["measurement_inputs"] = deepCopy(measurementInputs)
    result["parent_location_id"] = parentLocationId
    result["sex_id"] = sexId
    return result
}

@Suppress("UNCHECKED_CAST")
fun deepCopy(map: Map<String, Any>): Map<String, Any> {
    val result = HashMap<String, Any>()
    for ((k, v) in map) {
        result[k] = when (v) {
            is Map<*, *> -> deepCopy(v as Map<String, Any>)
            is List<*> -> v.map { item -> when(item) {
                is Map<*, *> -> deepCopy(item as Map<String, Any>)
                else -> item
            } }
            else -> v
        }
    }
    return result
};1

fun maxProfit(prices: IntArray): Int {
    val futureSellPrices = Array<Int>(prices.size) { Integer.MIN_VALUE }
    val futureBuyPrices = Array<Int>(prices.size) { Integer.MAX_VALUE }
    for (index in prices.lastIndex downTo 0) {
        futureSellPrices[index] = maxOf(futureSellPrices.getOrNull(index + 1) ?: Integer.MIN_VALUE, prices[index])
        futureBuyPrices[index] = minOf(futureBuyPrices.getOrNull(index + 1) ?: Integer.MAX_VALUE, prices[index])
    }

    var result = 0
    var boughtAt: Int? = null
    for (index in 0..prices.lastIndex) {
        val maxSell = futureSellPrices[index] // max sell price in future
        val minBuy = futureBuyPrices[index] // min buy price in future
        val current = prices[index]
        if (boughtAt == null) { // haven't bought yet
            if (current == maxSell) { // if this is maxSell price, then don't buy
                boughtAt = null
            } else if (current in minBuy until maxSell) { // buy if you can sell it at higher price in future
                boughtAt = current
            }
        } else { // if already bought, see if you can sell
            if (current == maxSell) { // this is max sell price, then sell it!
                result += (current - boughtAt) // sold
            } else if (current > boughtAt && current in minBuy until maxSell) { // sell if there's profit
                result += (current - boughtAt) //sold
            }
            if (current in minBuy until maxSell) { // re-buy it if you can have profit in the future
                boughtAt = current // re-bought at the same day
            } else {
                boughtAt = null // sold
            }
        }

    }
    return result
};0

fun addAndOptimizeSet(optimizedSet: MutableSet<IntRange>, rangeToAdd: IntRange) {
    var newRangeStart = rangeToAdd.start
    var newRangeEnd = rangeToAdd.endInclusive
    for (intRange in optimizedSet.toSet()) {
        val intersection = intRange.intersect(rangeToAdd)
        if (!intersection.isEmpty()) {
            optimizedSet.remove(intRange)
            newRangeStart = minOf(intRange.start, newRangeStart)
            newRangeEnd = maxOf(intRange.endInclusive, newRangeEnd)
        }
    }

    optimizedSet.add(IntRange(newRangeStart, newRangeEnd))
};0

 
