fun nextInt(size: Int): Int {
    return Random.nextInt(size)
}
 
var cylinder = BooleanArray(6)
 
fun rshift() {
    val t = cylinder[5]
    for (i in 4 downTo 0) {
        cylinder[i + 1] = cylinder[i]
    }
    cylinder[0] = t
}
 
fun unload() {
    for (i in 0..5) {
        cylinder[i] = false
    }
}
 
fun load() {
    while (cylinder[0]) {
        rshift()
    }
    cylinder[0] = true
    rshift()
}
 
fun spin() {
    val lim = nextInt(6) + 1
    for (i in 1 until lim) {
        rshift()
    }
}
 
fun fire(): Boolean {
    val shot = cylinder[0]
    rshift()
    return shot
}
 
fun method(s: String): Int {
    unload()
    for (c in s) {
        when (c) {
            'L' -> load()
            'S' -> spin()
            'F' -> if (fire()) {
                return 1
            }
        }
    }
    return 0
}
 
fun append(out: StringBuilder, txt: String) {
    if (out.isNotEmpty()) {
        out.append(", ")
    }
    out.append(txt)
}
 
fun mstring(s: String): String {
    val out = StringBuilder()
    for (c in s) {
        when (c) {
            'L' -> append(out, "load")
            'S' -> append(out, "spin")
            'F' -> append(out, "fire")
        }
    }
    return out.toString()
}
 
