val filename = "readings.txt"
val showLines = 5
val fileStats = FileStats()
 
val scanner = Scanner(File(filename))
while (scanner.hasNextLine()) {
    val line = scanner.nextLine()
    lineStats(line, showLines-- > 0)
}
scanner.close()
 
println(
    "\nFile(s)  = $filename\n" +
    "Total    = ${dec3(fileStats.total)}\n" +
    "Readings = ${fileStats.numReadings}\n" +
    "Average  = ${dec3(fileStats.total / fileStats.numReadings)}\n\n" +
    "Maximum run of ${fileStats.rejectRunMax} " +
    "consecutive false readings ends at ${fileStats.rejectRunDate}"
)
 
fun lineStats(line: String, printLine: Boolean) {
    var readings = 0
    var rejects = 0
    var total = 0.0
    val fields = line.split("\t".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()
    val date = fields[0]
 
    for (i in 1..fields.size - 1 step 2) {
        val value = fields[i].toDouble()
        val flag = fields[i + 1].toInt()
        readings++
        if (flag <= 0) {
            rejects++
            fileStats.rejectRun++
        } else {
            total += value
            if (fileStats.rejectRun > fileStats.rejectRunMax) {
                fileStats.rejectRunMax = fileStats.rejectRun
                fileStats.rejectRunDate = date
            }
            fileStats.rejectRun = 0
        }
    }
 
    fileStats.numReadings += readings - rejects
    fileStats.total += total
 
    if (printLine) {
        println(
            "Line: $date\t" +
            "Reject: $rejects\t" +
            "Accept: ${readings - rejects}\t" +
            "Line_tot: ${dec3(total)}\t" +
            "Line_avg: ${if (readings == rejects) "0.0" else dec3(total / (readings - rejects))}"
        )
    }
}
 
// round a number to 3 decimal places
fun dec3(value: Double) = Math.round(value * 1e3) / 1e3
 
