/**
 * Build a group concept structure from the provided elements.
 * By default the element type of the group will be found from the first element,
 * however, it can be set/overridden as an optional parameter.
 */
fun buildGroup(elements: List<Concept>, elementType: Concept? = null): Concept {
    val root = Concept(GroupConcept.Group.name)
    val elementsField = buildConceptList(elements, GroupConcept.Values.name)
    root.with(Slot(GroupFields.Elements, elementsField))
    val t = elementType ?: (elements.firstOrNull()?.let { extractConceptHead.transform(it)})
    t?.let { root.value(GroupFields.ElementsType, t) }
    return root
};0

fun Device(lines: List<String>): Map<String,Int> =  buildMap {
    var wd = ""
    val idxCmds = lines.mapIndexedNotNull { idx, line -> if (line[0]=='$' && idx>0) idx else null }
    idxCmds.forEachIndexed { idx, idxCmd ->
        val cmdLine = lines[idxCmd].substringAfter("$ ")
        when (cmdLine.substringBefore(' ')) {
            "ls" -> {
                val size = lines
                    .subList(idxCmd + 1, if (idx < idxCmds.lastIndex) idxCmds[idx + 1] else lines.size)
                    .filter { !it.startsWith("dir") }.sumOf { it.substringBefore(' ').toInt() }
                var dir = wd
                while(true) {
                    put(dir, (get(dir) ?: 0) + size)
                    if (dir=="" || size==0) break
                    dir = dir.substringBeforeLast('/')
                }
            }
            "cd" -> wd = when (val name = cmdLine.substringAfter(' ')) {
                ".." -> wd.substringBeforeLast('/')
                else -> "$wd/$name"
            }
        }
    }
};0

fun quad(top: Int = 2200): List<Int> {
    val r = BooleanArray(top)
    val ab = BooleanArray(top * 2 * top * 2)
    for (a in 1 until top) {
        for (b in a until top) {
            ab[a * a + b * b] = true
        }
    }
    var s = 3
    for (c in 1 until top) {
        var s1 = s
        s += 2
        var s2 = s + 2
        for (d in c + 1 until top) {
            if (ab[s1]) {
                r[d] = true
            }
            s1 += s2
            s2 += 2
        }
    }
    return r.mapIndexed { i, val -> if (!val && i > 0) i else null }.filterNotNull()
}
 
