fun countSpruces(testCases: List<Triple<Int, Int, List<String>>>): List<Int> {
    val res = mutableListOf<Int>()
    for ((n, m, grid) in testCases) {
        val dp = Array(n) { IntArray(m) {0} }
        var total = 0
        for (i in n - 1 downTo 0) {
            for (j in 0 until m) {
                if (grid[i][j] == '.') {
                    dp[i][j] = 0
                } else {
                    if (i == n - 1) {
                        dp[i][j] = 1
                    } else {
                        val left = if (j - 1 >= 0) dp[i + 1][j - 1] else 0
                        val center = dp[i + 1][j]
                        val right = if (j + 1 < m) dp[i + 1][j + 1] else 0
                        dp[i][j] = 1 + minOf(left, center, right)
                    }
                    total += dp[i][j]
                }
            }
        }
        res.add(total)
    }
    return res
};1

fun exp(x: Double, n: Int): Double {
    /**
     * Approximate e^x using the first `n` terms of its Taylor series.
     *
     * @param x The exponent in e^x.
     * @param n Number of terms to include in the Taylor series (must be > 0).
     * @return Approximated value of e^x.
     */
    if (n <= 0) {
        throw IllegalArgumentException("n must be a positive integer")
    }

    // Term 0
    var total = 1.0      // running sum of the series
    var term = 1.0       // current term (x^k / k!)

    // Compute terms 1 .. n-1
    for (k in 1 until n) {
        term *= x / k
        total += term
    }

    return total
};1

fun k(n: Int): Int? {
    val n2 = n * n
    for (i in 0..n2.toString().length) {
        val a = n2.toString().substring(0, i).toIntOrNull()?: 0
        val b = n2.toString().substring(i).toIntOrNull()?: 0
        if (b!= 0 && a + b == n) {
            return n
        }
    }
    return null
}

