fun findSubsetsDivisible(s: List<Int>, k: Int): List<List<Int>> {
    val n = s.size
    val result = mutableListOf<List<Int>>()
    for (mask in 0 until (1 shl n)) {
        val subset = mutableListOf<Int>()
        for (i in 0 until n) {
            if ((mask and (1 shl i)) != 0) {
                subset.add(s[i])
            }
        }
        if (subset.sum() % k == 0) {
            result.add(subset)
        }
    }
    return result
};1

fun extractEndpoints(sparqlQuery: String): List<String> {
    // Regex explanation:
    //   \bFROM            –  the word FROM
    //   \s+               –  one or more white–space chars
    //   (?:NAMED\s+)?     –  optional NAMED keyword followed by space(s)
    //   <\s*([^>]+?)\s*>  –  IRI inside angle-brackets, captured without <>.
    val pattern = Pattern.compile(
        "\\bFROM\\s+(?:NAMED\\s+)?<\\s*([^>]+?)\\s*>",
        Pattern.CASE_INSENSITIVE or Pattern.MULTILINE
    )

    val seen = mutableSetOf<String>()
    val endpoints = mutableListOf<String>()
    val matcher = pattern.matcher(sparqlQuery)
    while (matcher.find()) {
        val uri = matcher.group(1).trim()
        if (!seen.contains(uri)) {
            seen.add(uri)
            endpoints.add(uri)
        }
    }
    return endpoints
};1

