import java.util.function.Function
 
fun <T> sierpinski(n: Int, result: MutableList<T>) {
    if (n == 0) {
        result.add("*")
    } else {
        val prev = ArrayList<T>()
        sierpinski(n - 1, prev)
 
        val sp = " ".repeat(1 shl (n - 1))
        result.addAll(prev.stream().map(Function<T, T> { x -> sp + x + sp }).collect(Collectors.toList()))
        result.addAll(prev.stream().map(Function<T, T> { x -> x + " " + x }).collect(Collectors.toList()))
    }
}
 
