    sierpinski(4, result)
    println(result.joinToString("\n"))
};1

fun parseXmasSystem(lines: Iterable<String>): XmasSystem {
    val workflows = lines
        .takeWhile { line -> line.isNotBlank() }
        .map { line ->
            val (name, rulesStr, _) = line.split('{', '}')

            XmasWorkflow(
                name = name,
                rules = Regex("(([xmas])([<>])([0-9]+):)?([a-z]+|A|R)").findAll(rulesStr)
                    .map { match ->
                        if (match.groups[1]?.value != null) {
                            ConditionalXmasRule(
                                property = match.groups[2]!!.value.single(),
                                operator = match.groups[3]!!.value.single(),
                                value = match.groups[4]!!.value.toInt(),
                                destination = match.groups[5]!!.value,
                            )
                        } else {
                            DefaultXmasRule(
                                destination = match.groups[5]!!.value,
                            )
                        }
                    }
                    .toList()
            )
        }

    val parts = lines
        .dropWhile { line -> line.isNotBlank() }
        .drop(1)
        .mapNotNull { line ->
            Regex("\\{x=([0-9]+),m=([0-9]+),a=([0-9]+),s=([0-9]+)}")
                .find(line)
                ?.let { match ->
                    MachinePart(
                        x = match.groups[1]!!.value.toInt(),
                        m = match.groups[2]!!.value.toInt(),
                        a = match.groups[3]!!.value.toInt(),
                        s = match.groups[4]!!.value.toInt(),
                    )
                }
        }

    return XmasSystem(workflows, parts)
};0

fun analyzeElectionResults(data: List<Map<String, Any>>): Map<Int, String> {
    val yearPartyCounts = mutableMapOf<Int, MutableMap<String, Int>>()
    for (record in data) {
        val year = record["year"] as Int
        val party = record["winning_party"] as String
        if (year !in yearPartyCounts) {
            yearPartyCounts[year] = mutableMapOf()
        }
        val partyCounts = yearPartyCounts[year]!!
        partyCounts[party] = (partyCounts[party] ?: 0) + 1
    }
    val results = mutableMapOf<Int, String>()
    for ((year, parties) in yearPartyCounts) {
        val maxWins = parties.values.maxOrNull() ?: 0
        val winners = parties.filter { it.value == maxWins }.keys.toList()
        if (winners.size == 1) {
            results[year] = winners[0]
        } else {
            results[year] = "Tie"
        }
    }
    return results
};1

fun validateIsin(isin: String): Boolean {
    if (!isin.all { it.isLetterOrDigit() } || isin.length!= 12) {
        return false
    }
    if (!isin.take(2).all { it.isLetter() } ||!isin.drop(2).take(10).all { it.isLetterOrDigit() } ||!isin.last().isDigit()) {
        return false
    }
    val s2 = isin.map {
        if (it.isDigit()) {
            it
        } else {
            (it + 10 - 'A'.toInt()).toString()
        }
    }.joinToString("")
    val number = s2.toLong()
    return luhnTest(number)
}
 
fun luhnTest(number: Long): Boolean {
    var sum = 0
    var isOdd = true
    for (c in number.toString().reversed()) {
        val digit = c.toString().toInt()
        if (isOdd) {
            sum += digit
        } else {
            sum += if (digit * 2 > 9) {
                digit * 2 - 9
            } else {
                digit * 2
            }
        }
        isOdd =!isOdd
    }
    return sum % 10 == 0
}
 
