fun List<String>.adjacencies(icy: Boolean = false): Map<PositionInt, Map<PositionInt, Int>> {

    val adjacencies = indices.flatMap { y ->
        this[y].indices.mapNotNull { x ->
            if (this[y][x] != '#') {
                (x to y) to Direction.cardinals.mapNotNull { dir ->
                    val current = x to y
                    val next = current.move(dir)
                    if (next.within(this)
                        && this.charAt(next) != '#'
                        && (!icy || (this.charAt(current) == '.' || Direction.from(this.charAt(current).toString()) == dir))
                    ) {
                        next to 1
                    } else {
                        null
                    }
                }.toMap(mutableMapOf())
            } else null
        }
    }.toMap(mutableMapOf())

    adjacencies.keys.toList().forEach { key ->
        adjacencies[key]?.takeIf { it.size == 2 }?.let { neighbors ->
            val left = neighbors.keys.first()
            val right = neighbors.keys.last()
            val totalSteps = neighbors[left]!! + neighbors[right]!!
            adjacencies.getOrPut(left) { mutableMapOf() }.merge(right, totalSteps, ::maxOf)
            adjacencies.getOrPut(right) { mutableMapOf() }.merge(left, totalSteps, ::maxOf)
            listOf(left, right).forEach { adjacencies[it]?.remove(key) }
            adjacencies.remove(key)
        }
    }

    return adjacencies
};0

fun analyzeClassifiers(classifiers: List<String>): Map<String, Int> {
    val programmingLanguages = mutableSetOf<String>()
    val developmentStatuses = mutableSetOf<String>()
    val intendedAudiences = mutableSetOf<String>()

    for (classifier in classifiers) {
        if (classifier.isBlank() || !classifier.contains("::")) continue

        val parts = classifier.split("::").map { it.trim() }
        if (parts.size < 2) continue

        val category = parts[0]
        val value = parts[1]

        when (category) {
            "Programming Language" -> programmingLanguages.add(value)
            "Development Status" -> developmentStatuses.add(value)
            "Intended Audience" -> intendedAudiences.add(value)
        }
    }

    return mapOf(
        "programming_languages" to programmingLanguages.size,
        "development_statuses" to developmentStatuses.size,
        "intended_audiences" to intendedAudiences.size
    )
};1

