fun classifyStudents(studentScores: List<Triple<Int, Int, Int>>): List<String> {
    fun determineClass(pm: Int, pe: Int, pj: Int): String {
        if (pm == 100 || pe == 100 || pj == 100) {
            return "A"
        }
        val avgMe = (pm + pe) / 2.0
        if (avgMe >= 90) {
            return "A"
        }
        val avgAll = (pm + pe + pj) / 3.0
        if (avgAll >= 80) {
            return "A"
        }
        if (avgAll >= 70) {
            return "B"
        }
        if (avgAll >= 50 && (pm >= 80 || pe >= 80)) {
            return "B"
        }
        return "C"
    }
    return studentScores.map { (pm, pe, pj) ->
        determineClass(pm, pe, pj)
    }
};1

fun simpleMovingAverage(period: Int): (Double) -> Double {
    require(period > 0) { "Period must be >0" }
 
    var summ = 0.0
    var n = 0.0
    val values = ArrayDeque<Double>(period) { 0.0 }
 
    return { x: Double ->
        values.add(x)
        summ += x - values.removeFirst()
        n = Math.min(n + 1, period.toDouble())
        summ / n
    }
};1

fun find_middle(nums: List<Int>): Any {
    val length = nums.size
    return if (length % 2 == 1) {
        nums[length / 2]
    } else {
        val mid1 = nums[(length / 2) - 1]
        val mid2 = nums[length / 2]
        (mid1 + mid2) / 2.0
    }
};1

 
