fun displayRanges(ranges: List<Range>) {
    println(String.format("ranges = %-70s, colsolidated = %s", ranges, Range.consolidate(ranges)))
}
 
private class RangeSorter : Comparator<Range> {
    fun compare(o1: Range, o2: Range): Int {
        return (o1.left - o2.left).toInt()
    }
}
 
private class Range {
