fun checkCoinSystem(cases: List<List<Int>>): List<String> {
    val results = mutableListOf<String>()
    for ((caseNum, origCoins) in cases.withIndex()) {
        val coins = origCoins.sorted()
        val n = coins.size
        if (coins[0] != 1) {
            results.add("Case #${caseNum + 1}: Cannot pay some amount")
            continue
        }
        val maxCoin = coins.last()
        val reachable = BooleanArray(maxCoin + 1)
        reachable[0] = true
        for (coin in coins) {
            for (i in coin..maxCoin) {
                if (reachable[i - coin]) {
                    reachable[i] = true
                }
            }
        }
        val allReachable = (1..maxCoin).all { reachable[it] }
        if (!allReachable) {
            results.add("Case #${caseNum + 1}: Cannot pay some amount")
            continue
        }
        if (n == 1) {
            results.add("Case #${caseNum + 1}: OK")
            continue
        }
        val sumMax = coins[coins.size - 1] + coins[coins.size - 2]
        val dp = IntArray(sumMax + 1) { Int.MAX_VALUE }
        dp[0] = 0
        for (coin in coins) {
            for (i in coin..sumMax) {
                if (dp[i - coin] != Int.MAX_VALUE && dp[i - coin] + 1 < dp[i]) {
                    dp[i] = dp[i - coin] + 1
                }
            }
        }
        val sortedCoinsDesc = coins.sortedDescending()
        var greedyOk = true
        loop@ for (amount in 1..sumMax) {
            var remaining = amount
            var count = 0
            for (coin in sortedCoinsDesc) {
                if (remaining == 0) break
                if (coin > remaining) continue
                val num = remaining / coin
                count += num
                remaining -= num * coin
            }
            if (dp[amount] < count) {
                greedyOk = false
                break@loop
            }
        }
        if (greedyOk) {
            results.add("Case #${caseNum + 1}: OK")
        } else {
            results.add("Case #${caseNum + 1}: Cannot use greedy algorithm")
        }
    }
    return results
};1

import java.lang.Math.*
 
class Complex(val re: Double, val im: Double) {
    operator infix fun plus(x: Complex) = Complex(re + x.re, im + x.im)
    operator infix fun minus(x: Complex) = Complex(re - x.re, im - x.im)
    operator infix fun times(x: Double) = Complex(re * x, im * x)
    operator infix fun times(x: Complex) = Complex(re * x.re - im * x.im, re * x.im + im * x.re)
    operator infix fun div(x: Double) = Complex(re / x, im / x)
    val exp: Complex by lazy { Complex(cos(im), sin(im)) * (cosh(re) + sinh(re)) }
 
    fun toString() = when {
        b == "0.000" -> a
        a == "0.000" -> b + 'i'
        im > 0 -> a + " + " + b + 'i'
        else -> a + " - " + b + 'i'
    }
 
    private val a = "%1.3f".format(re)
    private val b = "%1.3f".format(abs(im))
};0

