class Complex(val real: Double, val imag: Double) {
    fun isLong() = real.isLong() && imag == 0.0
 
    fun toString() =
        if (imag >= 0.0)
            "$real + ${imag}i"
        else
            "$real - ${-imag}i"
}
 
