import java.util.ArrayList
import java.util.List
 
object FindPalindromicNumbers {
    @JvmStatic
    fun main(args: Array<String>) {
        val query = palindromicTernaries()
               .filter { isPalindromicBinary(it) }
               .take(6)
        for (x in query) {
            println("Decimal: " + x)
            println("Ternary: " + toTernary(x))
            println("Binary: " + Integer.toString(x, 2))
            println()
        }
    }
 
    fun palindromicTernaries(): Sequence<Long> {
        return generateSequence(0L) {
            if (it == 0L) 1L
            else if (it == 1L) 13L
            else if (it == 13L) 23L
            else {
                val f = ArrayList<Long>()
                var fMiddle = 9L
                while (true) {
                    for (edge in 1L..2L) {
                        var i: Int
                        do {
                            //construct the result
                            var result = fMiddle
                            var fLeft = fMiddle * 3
                            var fRight = fMiddle / 3
                            for (j in f.size - 1 downTo 0) {
                                result += (fLeft + fRight) * f[j]
                                fLeft *= 3
                                fRight /= 3
                            }
                            result += (fLeft + fRight) * edge
                            return@generateSequence result
 
                            //next permutation
                            for (i in f.size - 1 downTo 0) {
                                if (f[i] == 2L) {
                                    f[i] = 0L
                                } else {
                                    f[i]++
                                    break
                                }
                            }
                        } while (i >= 0)
                    }
                    f.add(0L)
                    fMiddle *= 3
                }
            }
        }
    }
 
    fun isPalindromicBinary(number: Long): Boolean {
        var n = number
        var reverse = 0L
        while (n!= 0L) {
            reverse = reverse shl 1
            if ((n and 1L) == 1L) reverse++
            n = n shr 1
        }
        return reverse == number
    }
 
    fun toTernary(n: Long): String {
        if (n == 0L) return "0"
        var result = ""
        var n = n
        while (n > 0) {
            result = (n % 3) + result
            n /= 3
        }
        return result
    }
};1

