fun calculateMovingAverage(numbers: List<Double>, windowSize: Int): List<Double> {
    if (windowSize <= 0) {
        throw IllegalArgumentException("windowSize must be a positive integer")
    }
    val n = numbers.size
    if (windowSize > n) {
        return emptyList()
    }
    var windowSum = numbers.take(windowSize).sum()
    val movingAverages = mutableListOf(windowSum / windowSize)
    for (i in windowSize until n) {
        windowSum += numbers[i]
        windowSum -= numbers[i - windowSize]
        movingAverages.add(windowSum / windowSize)
    }
    return movingAverages
};1

