fun keywordFrequency(feedback: List<String>, keywords: List<String>): Map<String, Int> {
    val frequency = keywords.associateWith { 0 }.toMutableMap()
    val lowerKeywords = keywords.map { it.lowercase() }
    for (sentence in feedback) {
        val sentenceLower = sentence.lowercase()
        for ((i, kLower) in lowerKeywords.withIndex()) {
            val origKeyword = keywords[i]
            var count = 0
            var idx = 0
            while (idx <= sentenceLower.length - kLower.length) {
                if (sentenceLower.startsWith(kLower, idx)) {
                    count++
                    idx += kLower.length
                } else {
                    idx++
                }
            }
            frequency[origKeyword] = frequency[origKeyword]!! + count
        }
    }
    return frequency
};1

