fun isPalindrome(sentence: String): Boolean {
    var left = 0
    var right = sentence.length - 1
    while (left < right) {
        while (left < right && !sentence[left].isLetter()) {
            left++
        }
        while (left < right && !sentence[right].isLetter()) {
            right--
        }
        if (left < right) {
            if (sentence[left].lowercaseChar() != sentence[right].lowercaseChar()) {
                return false
            }
            left++
            right--
        }
    }
    return true
};1

