fun sumWrongModAdd(a: List<Int>, queries: List<Pair<Int, Int>>, p: Int): List<Int> {
    val n = a.size
    val prefixSum = IntArray(n + 1)
    for (i in 0 until n) {
        prefixSum[i + 1] = prefixSum[i] + a[i]
    }
    val result = mutableListOf<Int>()
    for ((l, r) in queries) {
        val res = prefixSum[r] - prefixSum[l - 1]
        result.add(res)
    }
    return result
};1

fun leveinshteinDistance(source: String, target: String): Int {
    // If either string is empty, the distance is the other string's length.
    if (source == target) return 0
    if (source.isEmpty()) return target.length
    if (target.isEmpty()) return source.length

    // Ensure `source` is the shorter string to minimize memory usage
    var s = source
    var t = target
    if (s.length > t.length) {
        val temp = s
        s = t
        t = temp
    }

    val m = s.length
    val n = t.length

    var previousRow = IntArray(m + 1) { it }
    var currentRow = IntArray(m + 1)

    for (j in 1..n) {
        currentRow[0] = j
        val targetChar = t[j - 1]

        for (i in 1..m) {
            val sourceChar = s[i - 1]
            val costDelete = previousRow[i] + 1       // Deletion
            val costInsert = currentRow[i - 1] + 1    // Insertion
            val costSubstitute = previousRow[i - 1] + if (sourceChar != targetChar) 1 else 0
            currentRow[i] = minOf(costDelete, costInsert, costSubstitute)
        }
        // Swap previousRow and currentRow
        val temp = previousRow
        previousRow = currentRow
        currentRow = temp
    }
    // The result is in previousRow after the last swap
    return previousRow[m]
};1

class FenwickTreeMax(val size: Int) {
    private val tree = IntArray(size + 1) { -1 }
    fun update(idx0: Int, value: Int) {
        var idx = idx0
        while (idx <= size) {
            if (tree[idx] < value) {
                tree[idx] = value
            } else {
                break
            }
            idx += idx and -idx
        }
    }
    fun query(idx0: Int): Int {
        var res = -1
        var idx = idx0
        while (idx > 0) {
            res = max(res, tree[idx])
            idx -= idx and -idx
        }
        return res
    }
}

fun walrusDispleasure(n: Int, ages: List<Int>): List<Int> {
    val sortedUnique = ages.toSortedSet().toList()
    val m = sortedUnique.size
    val ft = FenwickTreeMax(m)
    val ans = MutableList(n) { -1 }
    for (i in (n - 1) downTo 0) {
        val x = ages[i]
        val p = sortedUnique.binarySearch(x).let { if (it < 0) -(it + 1) else it }
        var resJ = -1
        if (p > 0) {
            val maxJ = ft.query(p)
            if (maxJ != -1) {
                resJ = maxJ
            }
        }
        ans[i] = if (resJ != -1) resJ - i - 1 else -1
        val rank = p + 1
        ft.update(rank, i)
    }
    return ans
};1

