};1

fun minPathSum2(grid: Array<IntArray>): Int {
    val r = grid.size
    val c = grid[0].size
    for (i in 1 until c) {
        grid[0][i] += grid[0][i - 1]
    }
    for (i in 1 until r) {
        grid[i][0] += grid[i - 1][0]
    }
    for (i in 1 until r) {
        for (j in 1 until c) {
            grid[i][j] += min(grid[i - 1][j], grid[i][j - 1])
        }
    }
    return grid[r - 1][c - 1]
};0

import java.util.Arrays
import java.util.List

class ListOrder {
    fun ordered(first: DoubleArray, second: DoubleArray): Boolean {
        if (first.size == 0) return true
        if (second.size == 0) return false
        if (first[0] == second[0])
            return ordered(Arrays.copyOfRange(first, 1, first.size),
                    Arrays.copyOfRange(second, 1, second.size))
        return first[0] < second[0]
    }

    fun <T : Comparable<T>> ordered(first: List<T>, second: List<T>): Boolean {
        var i = 0
        while (i < first.size && i < second.size) {
            val cmp = first[i].compareTo(second[i])
            if (cmp == 0) {
                i++
                continue
            }
            if (cmp < 0) return true
            return false
        }
        return i == first.size
    }

    fun ordered2(first: DoubleArray, second: DoubleArray): Boolean {
        var i = 0
        while (i < first.size && i < second.size) {
            if (first[i] == second[i]) {
                i++
                continue
            }
            if (first[i] < second[i]) return true
            return false
        }
        return i == first.size
    }
};1

