fun String.tokenize(separator: Char, escape: Char): List<String> {
    if (this == null) return ArrayList()
    val buffer = StringBuilder()
    var escaping = false
    for (c in this) {
        if (escaping) {
            buffer.append(c)
            escaping = false
        } else if (c == escape) {
            escaping = true
        } else if (c == separator) {
            yield(buffer.flush())
        } else {
            buffer.append(c)
        }
    }
    if (buffer.length > 0 || this[this.length - 1] == separator) yield(buffer.flush())
    return ArrayList()
}
 
fun StringBuilder.flush(): String {
    val result = this.toString()
    this.clear()
    return result
}
 
fun <T> yield(value: T): T {
    return value
};1

