import java.util.Arrays
 
enum class Mode {
    ENCRYPT,
    DECRYPT
}
 
private const val L_ALPHABET = "HXUCZVAMDSLKPEFJRIGTWOBNYQ"
private const val R_ALPHABET = "PTLNBQDEOYSFAVZKGJRIHWXUMC"
 
fun indexOf(a: CharArray, c: Char): Int {
    for (i in a.indices) {
        if (a[i] == c) {
            return i
        }
    }
    return -1
}
 
fun exec(text: String, mode: Mode): String {
    return exec(text, mode, false)
}
 
fun exec(text: String, mode: Mode, showSteps: Boolean): String {
    var left = L_ALPHABET.toCharArray()
    var right = R_ALPHABET.toCharArray()
    val eText = CharArray(text.length)
    val temp = CharArray(26)
 
    for (i in text.indices) {
        if (showSteps) {
            println(String(left) + "  " + String(right))
        }
        var index: Int
        index = if (mode == Mode.ENCRYPT) {
            indexOf(right, text[i])
        } else {
            indexOf(left, text[i])
        }
        eText[i] = if (mode == Mode.ENCRYPT) {
            left[index]
        } else {
            right[index]
        }
        if (i == text.length - 1) {
            break
        }
 
        // permute left
 
        if (26 - index >= 0) System.arraycopy(left, index, temp, 0, 26 - index)
        System.arraycopy(left, 0, temp, 26 - index, index)
        var store = temp[1]
        System.arraycopy(temp, 2, temp, 1, 12)
        temp[13] = store
        left = Arrays.copyOf(temp, temp.size)
 
        // permute right
 
        if (26 - index >= 0) System.arraycopy(right, index, temp, 0, 26 - index)
        System.arraycopy(right, 0, temp, 26 - index, index)
        store = temp[0]
        System.arraycopy(temp, 1, temp, 0, 25)
        temp[25] = store
        store = temp[2]
        System.arraycopy(temp, 3, temp, 2, 11)
        temp[13] = store
        right = Arrays.copyOf(temp, temp.size)
    }
 
    return String(eText)
}
 
fun main(args: Array<String>) {
    val plainText = "WELLDONEISBETTERTHANWELLSAID"
    println("The original plaintext is : $plainText")
    println("\nThe left and right alphabets after each permutation during encryption are:")
    val cipherText = exec(plainText, Mode.ENCRYPT, true)
    println("\nThe cipher text is : $cipherText")
    val plainText2 = exec(cipherText, Mode.DECRYPT)
    println("\nThe recovered plaintext is : $plainText2")
};1

fun processCommits(
    commits: List<Map<String, String>>,
    signedAuthors: List<String>,
    signed: MutableList<Pair<String, String>>,
    missing: MutableList<Pair<String, String>>
) {
    val signedSet = signedAuthors.map { it.lowercase() }.toSet()
    for (commit in commits) {
        try {
            val cid = commit["id"] ?: continue
            val email = commit["author_email"]?.lowercase() ?: continue
            val name = commit["author_name"] ?: continue
            if (email in signedSet) {
                signed.add(Pair(cid, name))
            } else {
                missing.add(Pair(cid, name))
            }
        } catch (e: Exception) {
            // Skip malformed commit.
            continue
        }
    }
