fun leastSuperLucky(n: Int): Long {
    val nStr = n.toString()
    var m = nStr.length
    var startLength = if (m % 2 == 0) m else m + 1
    var currentLength = startLength
    while (true) {
        val k = currentLength / 2
        val indices = (0 until currentLength).toList()
        val combinations = combinations(indices, k)
        for (positions in combinations) {
            val numList = MutableList(currentLength) { '7' }
            for (pos in positions) {
                numList[pos] = '4'
            }
            val numStr = numList.joinToString("")
            val num = numStr.toLong()
            if (num >= n.toLong()) {
                return num
            }
        }
        currentLength += 2
    }
}

// Helper function to generate combinations of indices
fun <T> combinations(list: List<T>, k: Int): List<List<T>> {
    val result = mutableListOf<List<T>>()
    fun combine(start: Int, combo: MutableList<T>) {
        if (combo.size == k) {
            result.add(combo.toList())
            return
        }
        for (i in start until list.size) {
            combo.add(list[i])
            combine(i + 1, combo)
            combo.removeAt(combo.size - 1)
        }
    }
    combine(0, mutableListOf())
    return result
};1

