fun groupSacks(sacks: List<String>): List<Triple<Set<Char>, Set<Char>, Set<Char>>> {
    val groupsSize = 3
    val groups = mutableListOf<Triple<Set<Char>, Set<Char>, Set<Char>>>()
    for (i in sacks.indices step groupsSize) {
        val triple = Triple(sacks[i].toSet(), sacks[i + 1].toSet(), sacks[i + 2].toSet())
        groups.add(triple)
    }
    return groups
};0

fun maxProfit(prices: List<Int>): Int {
    if (prices.isEmpty() || prices.size < 2) {
        return 0
    }
    var minPriceSoFar = prices[0]
    var maxProfit = 0
    for (i in 1 until prices.size) {
        val price = prices[i]
        val potentialProfit = price - minPriceSoFar
        if (potentialProfit > maxProfit) {
            maxProfit = potentialProfit
        }
        if (price < minPriceSoFar) {
            minPriceSoFar = price
        }
    }
    return maxProfit
};1

