fun countElements(numbers: List<Any?>): Map<Int, Int> {
    val result = mutableMapOf<Int, Int>()
    for (num in numbers) {
        when (num) {
            is Pair<*, *> -> {
                val first = num.first
                val second = num.second
                if (first is Int)
                    result[first] = result.getOrDefault(first, 0) + 1
                if (second is Int)
                    result[second] = result.getOrDefault(second, 0) + 1
            }
            is Triple<*, *, *> -> {
                val first = num.first
                val second = num.second
                val third = num.third
                if (first is Int)
                    result[first] = result.getOrDefault(first, 0) + 1
                if (second is Int)
                    result[second] = result.getOrDefault(second, 0) + 1
                if (third is Int)
                    result[third] = result.getOrDefault(third, 0) + 1
            }
            is Int -> {
                result[num] = result.getOrDefault(num, 0) + 1
            }
        }
    }
    return result
};1

