import java.awt.Color
import java.awt.image.BufferedImage
import java.io.File
import javax.imageio.ImageIO
 
fun floodFill(fileName: String, initNode: Pair<Int, Int>, targetColor: Color, replaceColor: Color): BufferedImage {
    val img = ImageIO.read(File(fileName))
    val pix = img.getRGB(0, 0, img.width, img.height, null, 0, img.width)
    val xsize = img.width
    val ysize = img.height
    val Q = mutableListOf<Pair<Int, Int>>()
    if (pix[initNode.first * ysize + initNode.second]!= targetColor.rgb) {
        return img
    }
    Q.add(initNode)
    while (Q.isNotEmpty()) {
        val node = Q.removeAt(0)
        if (pix[node.first * ysize + node.second] == targetColor.rgb) {
            var W = node
            if (node.first + 1 < xsize) {
                var E = Pair(node.first + 1, node.second)
            } else {
                var E = node
            }
            // Move west until color of node does not match targetColor
            while (pix[W.first * ysize + W.second] == targetColor.rgb) {
                pix[W.first * ysize + W.second] = replaceColor.rgb
                if (W.second + 1 < ysize) {
                    if (pix[W.first * ysize + W.second + 1] == targetColor.rgb) {
                        Q.add(Pair(W.first, W.second + 1))
                    }
                }
                if (W.second - 1 >= 0) {
                    if (pix[W.first * ysize + W.second - 1] == targetColor.rgb) {
                        Q.add(Pair(W.first, W.second - 1))
                    }
                }
                if (W.first - 1 >= 0) {
                    W = Pair(W.first - 1, W.second)
                } else {
                    break
                }
            }
            // Move east until color of node does not match targetColor
            while (pix[E.first * ysize + E.second] == targetColor.rgb) {
                pix[E.first * ysize + E.second] = replaceColor.rgb
                if (E.second + 1 < ysize) {
                    if (pix[E.first * ysize + E.second + 1] == targetColor.rgb) {
                        Q.add(Pair(E.first, E.second + 1))
                    }
                }
                if (E.second - 1 >= 0) {
                    if (pix[E.first * ysize + E.second - 1] == targetColor.rgb) {
                        Q.add(Pair(E.first, E.second - 1))
                    }
                }
                if (E.first + 1 < xsize) {
                    E = Pair(E.first + 1, E.second)
                } else {
                    break
                }
            }
        }
    }
    return img
};1

fun isEsthetic(n: Int, b: Int): Boolean {
    if (n == 0) {
        return false
    }
    var i = n % b
    var n2 = (n / b).toInt()
    while (n2 > 0) {
        val j = n2 % b
        if (Math.abs(i - j)!= 1) {
            return false
        }
        n2 /= b
        i = j
    }
    return true
}
 
fun listEsths(n: Int, n2: Int, m: Int, m2: Int, perLine: Int, all: Boolean) {
    val esths = ArrayList<Int>()
    val dfs = { n: Int, m: Int, i: Int ->
        if (n <= i && i <= m) {
            esths.add(i)
        }
        if (i == 0 || i > m) {
            return@dfs
        }
        val d = i % 10
        val i1 = i * 10 + d - 1
        val i2 = i1 + 2
        if (d == 0) {
            dfs(n, m, i2)
        } else if (d == 9) {
            dfs(n, m, i1)
        } else {
            dfs(n, m, i1)
            dfs(n, m, i2)
        }
    }
    for (i in 0..9) {
        dfs(n2, m2, i)
    }
    val le = esths.size
    println("Base 10: %d esthetic numbers between %d and %d:".format(le, n, m))
    if (all) {
        esths.forEachIndexed { idx, esth ->
            print("%d ".format(esth))
            if ((idx + 1) % perLine == 0) {
                print("\n")
            }
        }
        print("\n")
    } else {
        for (i in 0 until perLine) {
            print("%d ".format(esths[i]))
        }
        print("\n............\n")
        for (i in esths.size - perLine until esths.size) {
            print("%d ".format(esths[i]))
        }
        print("\n")
    }
    print("\n")
}
 
