fun calculateStdDev(numberList: List<Double>): Double {
    val N = numberList.size
    // A sample standard deviation is undefined for N < 2;
    // here we choose to return 0.0 in that situation.
    if (N < 2) {
        return 0.0
    }
    // Step 1: Compute the mean (μ)
    var total = 0.0
    for (x in numberList) {
        total += x
    }
    val mean = total / N
    // Step 2: Compute the sum of squared deviations
    var squaredDiffSum = 0.0
    for (x in numberList) {
        val diff = x - mean
        squaredDiffSum += diff * diff
    }
    // Step 3: Divide by (N - 1) to get the variance, then take the square root
    val variance = squaredDiffSum / (N - 1)
    val stdDev = Math.sqrt(variance)
    return stdDev
};1

