fun caesarCipher(text: String, shift: Int): String {
    val result = StringBuilder()
    for (char in text) {
        when {
            char.isUpperCase() -> {
                val offset = 'A'.code
                val original = char.code - offset
                val shifted = (original + shift).mod(26)
                val newChar = (shifted + offset).toChar()
                result.append(newChar)
            }
            char.isLowerCase() -> {
                val offset = 'a'.code
                val original = char.code - offset
                val shifted = (original + shift).mod(26)
                val newChar = (shifted + offset).toChar()
                result.append(newChar)
            }
            else -> {
                result.append(char)
            }
        }
    }
    return result.toString()
};1

fun analyzeMovementData(movementData: List<Pair<String, Double>>): Pair<Double, Double> {
    var totalDistance = 0.0
    var previousPosition: Double? = null
    var startTime: String? = null
    var endTime: String? = null

    for ((timestamp, position) in movementData) {
        if (previousPosition != null) {
            totalDistance += kotlin.math.abs(position - previousPosition)
        }
        previousPosition = position
        if (startTime == null) {
            startTime = timestamp
        }
        endTime = timestamp
    }

    val startTimeParts = startTime!!.split(":").map { it.toInt() }
    val endTimeParts = endTime!!.split(":").map { it.toInt() }
    val startSeconds = startTimeParts[0] * 3600 + startTimeParts[1] * 60 + startTimeParts[2]
    val endSeconds = endTimeParts[0] * 3600 + endTimeParts[1] * 60 + endTimeParts[2]
    val totalDuration = endSeconds - startSeconds
    val averageSpeed = totalDistance / totalDuration
    return Pair(totalDistance, averageSpeed)
};1

fun minimalMoves(n: Int, m: Int): Int {
    val kMin = (n + 1) / 2
    val remainder = kMin % m
    val firstK = if (remainder == 0) kMin else kMin + (m - remainder)
    return if (firstK <= n) firstK else -1
};1

// find the number of the islands
// e.x. should return 5 for `testMap`
fun Array<IntArray>.countIslands(): Int {
    val m = this.size
    val n = this[0].size

    var count = 0

    val hasVisited = Array(m, { Array(n) { false } })
    for (row in 0 until m) {
        for (col in 0 until n) {
            // new island!
            if (this[row][col] == 1 && !hasVisited[row][col]) {
                count++
                // this.dfs(row, col, hasVisited)
                this.bfs(row, col, hasVisited)
            }
        }
    }

    return count
};0

