fun validateName(name: String): Pair<Boolean, Int> {
    // Condition 1: exact length of 5
    if (name.length != 5) {
        return Pair(false, 0)
    }
    // Condition 2: all alphabetic
    if (!name.all { it.isLetter() }) {
        return Pair(false, 0)
    }
    // Condition 3: starts with uppercase
    if (!name[0].isUpperCase()) {
        return Pair(false, 0)
    }
    // Count vowels (both cases)
    val vowels = setOf('a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U')
    val vowelCount = name.count { it in vowels }
    return Pair(true, vowelCount)
};1

