fun printFactors(nr: Long) {
    if (nr < 1) {
        println("\nFactors of $nr not computed")
        return
    }
    println("\nFactors of $nr: ")
    val fs = mutableListOf(1L)
    val apf = { p: Long, e: Int ->
        val n = fs.size
        for (i in 0 until e) {
            val pp = p.pow(i + 1)
            for (j in 0 until n) {
                fs.add(fs[j] * pp)
            }
        }
    }
    var e = 0
    while (nr and 1 == 0L) {
        e++
        nr shr= 1
    }
    apf(2, e)
    var d = 3L
    while (nr > 1) {
        if (d * d > nr) {
            d = nr
        }
        e = 0
        while (nr % d == 0L) {
            e++
            nr /= d
        }
        if (e > 0) {
            apf(d, e)
        }
        d += 2
    }
    println(fs)
    println("Number of factors = ${fs.size}")
}
 
fun Long.pow(e: Int): Long {
    var r = 1L
    for (i in 0 until e) {
        r *= this
    }
    return r
};1

fun topKFrequent(nums: IntArray, k: Int): IntArray {
    if (k == nums.size) {
        return nums
    }

    val count = nums.groupBy { it }.mapValues { it.value.size }

    val heap = PriorityQueue<Int> { n1, n2 -> (count[n1]!! - count[n2]!!) }

    for (n in count.keys) {
        heap.add(n)
        if (heap.size > k) heap.poll()
    }

    val top = IntArray(k)
    for (i in k - 1 downTo 0) {
        top[i] = heap.poll()
    }
    return top
};0

