fun isPrime(n: Int): Boolean {
    // Primes are greater than 1
    if (n <= 1) {
        return false
    }
    // 2 and 3 are the smallest primes
    if (n <= 3) {
        return true
    }
    // Eliminate even numbers and multiples of 3 quickly
    if (n % 2 == 0 || n % 3 == 0) {
        return false
    }
    var i = 5
    while (i * i <= n) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false
        }
        i += 6
    }
    return true
};1

/**
 * 859. Buddy Strings.
 * <br/>
 * Given two strings A and B of lowercase letters,
 * return true if you can swap two letters in A so the result is equal to B,
 * otherwise, return false.
 * Swapping letters is defined as taking two indices
 * i and j (0-indexed) such that i != j and swapping the characters
 * at A[i] and A[j]. For example, swapping at indices
 * 0 and 2 in "abcd" results in "cbad".
 * <br/>
 * https://leetcode.com/problems/buddy-strings/
 */
fun buddyStrings(A: String, B: String): Boolean {
    if(A.length != B.length || A.length < 2) return false
    var l1 = -1
    var l2 = -1
    for(i in A.indices) {
        if(A[i] != B[i]) {
            if(l1 == -1) {
                l1 = i
                continue
            }
            if(l2 == -1) {
                l2 = i
                if(A[l1] != B[l2] || A[l2] != B[l1]) return false //swap doesn't help
                continue
            }
            return false //more than 2 chars are diff
        }
    }
    if (l1 == -1) { //same, but maybe we could swap two similar letters
        return A.groupBy { it.toInt() }.any { (_, v) -> v.size > 1 }
    }
    if(l2 == -1) return false
    return A[l1] == B[l2] && A[l2] == B[l1]
};0

fun calculateAverageDistance(landmarks: List<Triple<Double, Double, Double>>): Double {
    val distances = mutableListOf<Double>()
    val n = landmarks.size
    for (i in 0 until n) {
        for (j in i + 1 until n) {
            val (x1, y1, z1) = landmarks[i]
            val (x2, y2, z2) = landmarks[j]
            val distance = sqrt((x2 - x1)*(x2 - x1) + (y2 - y1)*(y2 - y1) + (z2 - z1)*(z2 - z1))
            distances.add(distance)
        }
    }
    return if (distances.isNotEmpty()) distances.sum() / distances.size else 0.0
};1

