// group by dept, and sort by salary
fun group_by_dept(data: List<Employee>): Map<String, List<Employee>> {
    val by_dept = mutableMapOf<String, MutableList<Employee>>()
    for (emp in data) {
        val dept = emp.dept
        if (!by_dept.containsKey(dept)) {
            by_dept[dept] = mutableListOf()
        }
        by_dept[dept]!!.add(emp)
    }
    for (dept in by_dept.keys) {
        // numeric sort
        by_dept[dept]!!.sortByDescending { it.salary }
    }
    return by_dept
}
 
