fun updateInventory(inventory: MutableMap<String, Int>, sales: List<Map<String, Any>>): MutableMap<String, Int> {
    for (sale in sales) {
        val ingredients = sale["ingredients"] as? Map<*, *> ?: continue
        for ((ingredientObj, quantityObj) in ingredients) {
            val ingredient = ingredientObj as? String ?: continue
            val quantity = when (quantityObj) {
                is Int -> quantityObj
                is Number -> quantityObj.toInt()
                else -> continue
            }
            if (ingredient in inventory) {
                inventory[ingredient] = inventory[ingredient]!! - quantity
            }
        }
    }
    return inventory
};1

