fun generateStatistics(n: Int) {
    var sum = 0.0
    var sum2 = 0.0
    val hist = IntArray(10)
    for (i in 0 until n) {
        val r = Math.random()
        sum += r
        sum2 += r * r
        hist[(10 * r).toInt()]++
    }
    val mean = sum / n
    val stddev = Math.sqrt(sum2 / n - mean * mean)
    println("size: $n")
    println("mean:   $mean")
    println("stddev: $stddev")
    for (i in hist.indices) {
        println("%.1f:%s".format(0.1 * i, "=" * (70 * hist[i] / hist.max())))
    }
    println()
}
 
