fun walk(tree: Tree): Int {
    if (!tree.balanced()) {
        val result = tree.children().map { walk(it) }.maxOrNull()
        if (tree.children().map { it.balanced() }.count { it } == tree.children().size) {
            val groups = tree.children().groupBy { it.sum() }
            val wrongTree = groups.values.first { it.size == 1 }.first()
            val correctTree = groups.values.first { it.size > 1 }.first()

            return wrongTree.weight - (wrongTree.sum() - correctTree.sum())
        }

        return result!!
    }

    return Int.MIN_VALUE
};0

fun String.checkIfBetween(): Int {
    val range = this.split(',')
    val firstRange = range[0].trim().split('-').map { it.toInt() }
    val secondRange = range[1].trim().split('-').map { it.toInt() }
    return if ((secondRange[0] in firstRange[0]..firstRange[1]
                && secondRange[1] in firstRange[0]..firstRange[1]) ||
        (firstRange[0] in secondRange[0]..secondRange[1]
                && firstRange[1] in secondRange[0]..secondRange[1])
    ) 1 else 0
