fun allocateResources(projects: List<Pair<Int, Int>>, totalResources: Int): List<Int> {
    val n = projects.size
    val indexedProjects = projects.withIndex().toList().sortedBy { it.value.first }
    val allocation = MutableList(n) { 0 }
    var remainingResources = totalResources
    // Allocate min_required first to as many projects as possible
    for ((index, pair) in indexedProjects) {
        val (minRequired, _) = pair
        if (remainingResources >= minRequired) {
            allocation[index] = minRequired
            remainingResources -= minRequired
        } else {
            break
        }
    }
    // Allocate extra resources, up to max_possible
    for ((index, pair) in indexedProjects) {
        val (minRequired, maxPossible) = pair
        val cur = allocation[index]
        if (cur < minRequired) continue
        val extra = minOf(maxPossible - cur, remainingResources)
        allocation[index] += extra
        remainingResources -= extra
        if (remainingResources == 0) break
    }
    return allocation
};1

class AvlTree {
    private var root: Node? = null
 
    private class Node(var key: Int, var parent: Node?) {
        var balance: Int = 0
        var left : Node? = null
        var right: Node? = null
    }
 
    fun insert(key: Int): Boolean {
        if (root == null)
            root = Node(key, null)
        else {
            var n: Node? = root
            var parent: Node
            while (true) {
                if (n!!.key == key) return false
                parent = n
                val goLeft = n.key > key
                n = if (goLeft) n.left else n.right
                if (n == null) {
                    if (goLeft)
                        parent.left  = Node(key, parent)
                    else
                        parent.right = Node(key, parent)
                    rebalance(parent)
                    break
                }
            }
        }
        return true
    }
 
    fun delete(delKey: Int) {
        if (root == null) return
        var n:       Node? = root
        var parent:  Node? = root
        var delNode: Node? = null
        var child:   Node? = root
        while (child != null) {
            parent = n
            n = child
            child = if (delKey >= n.key) n.right else n.left
            if (delKey == n.key) delNode = n
        }
        if (delNode != null) {
            delNode.key = n!!.key
            child = if (n.left != null) n.left else n.right
            if (0 == root!!.key.compareTo(delKey)) {
                root = child
 
                if (null != root) {
                    root!!.parent = null
                }
 
            } else {
                if (parent!!.left == n)
                    parent.left = child
                else
                    parent.right = child
 
                if (null != child) {
                    child.parent = parent
                }
 
                rebalance(parent)
            }
    }
 
    fun rebalance(n: Node) {
        setBalance(n)
        var nn = n
        if (nn.balance == -2)
            if (height(nn.left!!.left) >= height(nn.left!!.right))
                nn = rotateRight(nn)
            else
                nn = rotateLeftThenRight(nn)
        else if (nn.balance == 2)
            if (height(nn.right!!.right) >= height(nn.right!!.left))
                nn = rotateLeft(nn)
            else
                nn = rotateRightThenLeft(nn)
        if (nn.parent != null) rebalance(nn.parent!!)
        else root = nn
    }
 
