import java.util.PriorityQueue
import java.util.TreeMap
 
fun huffmanEncoding(str: String): Map<Char, String> {
    val charCount = TreeMap<Char, Int>()
    str.forEach { charCount.put(it, charCount.getOrDefault(it, 0) + 1) }
 
    val pq = PriorityQueue<Any>(charCount.size, Comparator { o1, o2 ->
        when {
            o1 is Char && o2 is Char -> charCount[o1]!! - charCount[o2]!!
            o1 is Char && o2 is Pair<*, *> -> charCount[o1]!! - charCount[o2.first]!!
            o2 is Char && o1 is Pair<*, *> -> charCount[o1.first]!! - charCount[o2]!!
            else -> (o1 as Pair<*, *>).second as Int - (o2 as Pair<*, *>).second as Int
        }
    })
    charCount.forEach { pq.add(it.key) }
 
    while (pq.size > 1) {
        val key1 = pq.poll()
        val key2 = pq.poll()
        pq.add(Pair(key1, key2))
    }
 
    return generateEncoding(pq.peek())
}
 
fun generateEncoding(ary: Any, prefix: String = ""): Map<Char, String> {
    return when (ary) {
        is Char -> mapOf(ary to prefix)
        is Pair<*, *> -> generateEncoding(ary.first, "$prefix0") + generateEncoding(ary.second, "$prefix1")
        else -> throw IllegalArgumentException()
    }
}
 
fun encode(str: String, encoding: Map<Char, String>): String {
    return str.map { encoding[it]!! }.joinToString("")
}
 
fun decode(encoded: String, encoding: Map<Char, String>): String {
    val revEnc = encoding.map { it.value to it.key }.toMap()
    var decoded = ""
    var pos = 0
    while (pos < encoded.length) {
        var key = ""
        while (revEnc[key] == null) {
            key += encoded[pos]
            pos++
        }
        decoded += revEnc[key]
    }
    return decoded
}
 
