fun updateAdjacencyMatrix(dp: Array<DoubleArray>, n: Int): Array<DoubleArray> {
    for (k in 0 until n) {
        for (i in 0 until n) {
            val dik = dp[i][k]
            if (dik == Double.POSITIVE_INFINITY) {
                continue
            }
            for (j in 0 until n) {
                if (dik + dp[k][j] < dp[i][j]) {
                    dp[i][j] = dik + dp[k][j]
                }
            }
        }
    }
    return dp
};1

