fun normalizeData(data: List<Int>): List<Double> {
    // Normalize a list of integers to the range [0, 1].
    // Each element x is transformed as: (x - min_val) / (max_val - min_val)
    // Special cases:
    // - If data is empty, return an empty list.
    // - If all elements are identical (max_val == min_val), return a list of 0.5s with the same length as data.
    if (data.isEmpty()) {
        return emptyList()
    }
    val minVal = data.minOrNull() ?: return emptyList()
    val maxVal = data.maxOrNull() ?: return emptyList()
    if (maxVal == minVal) {
        return List(data.size) { 0.5 }
    }
    val rangeVal = maxVal - minVal
    return data.map { (it - minVal).toDouble() / rangeVal }
};1

 
const val SPE = "\ufffe"  // unused unicode char in Specials block
const val SPF = "\uffff"  // ditto
 
fun tokenize(str: String, sep: Char, esc: Char): List<String> {
    var s = str.replace("$esc$esc", SPE).replace("$esc$sep", SPF)
    s = if (s.last() == esc) // i.e. 'esc' not escaping anything
        s.dropLast(1).replace("$esc", "") + esc
    else
        s.replace("$esc", "")
    return s.split(sep).map { it.replace(SPE, "$esc").replace(SPF, "$sep") }
}
 
