fun createReview(content: String?, rating: Int, userId: Int, appId: Int): Review {
    // Validate rating
    if (rating !in 1..5) {
        throw IllegalArgumentException("Rating must be between 1 and 5.")
    }
    // Validate content
    if (content == null || content.trim().isEmpty()) {
        throw IllegalArgumentException("Content must not be empty.")
    }
    val newId = Review.nextId()
    return Review(
        id = newId,
        content = content.trim(),
        rating = rating,
        userId = userId,
        appId = appId
    )
