import java.util.ArrayList
import java.util.Stack
 
fun combinations(m: Int, n: Int): List<IntArray> {
    val result = IntArray(m)
    val stack = Stack<Int>()
    stack.push(0)
 
    val combinations = ArrayList<IntArray>()
 
    while (stack.size > 0) {
        val index = stack.size - 1
        var value = stack.pop()
 
        while (value < n) {
            result[index] = ++value
            stack.push(value)
 
            if (index == m - 1) {
                combinations.add(result.clone())
                break
            }
        }
    }
 
    return combinations
}
 
