fun XY.adjacent() = setOf(XY(x - 1, y), XY(x + 1, y), XY(x, y + 1), XY(x, y - 1))

private class PuzzleInput(lines_: List<String>) {
  val lines = lines_
  val width = lines[0].length
  val height = lines.size

  fun height(pos: XY): Int {
