fun addToPartitions(partitions: List<Any>, number: Int): Map<List<Int>, Int> {
    val result = mutableMapOf<List<Int>, Int>()

    for (part in partitions) {
        val newPart: List<Int> = when (part) {
            is Int -> listOf(part + number)
            is Iterable<*> -> (part as Iterable<Int>).map { it + number }
            is Array<*> -> (part as Array<Int>).map { it + number }
            else -> throw IllegalArgumentException("Unsupported partition type: ${part::class}")
        }
        result[newPart] = result.getOrDefault(newPart, 0) + 1
    }

    return result
};1

