fun hasBalancedParentheses(s: String): Boolean {
    val stack = mutableListOf<Char>()
    for (char in s) {
        if (char == '(') {
            stack.add(char)
        } else if (char == ')') {
            if (stack.isEmpty()) {
                return false
            }
            stack.removeAt(stack.size - 1)
        }
    }
    return stack.isEmpty()
