fun isPalindrome(num: Int): Boolean {
    /**
     * Determine whether an integer is a palindrome.
     *
     * An integer is considered a palindrome if it reads the same backward as forward.
     * This function treats negative numbers the same as their positive counterparts,
     * so -121 is viewed as a palindrome because 121 is a palindrome.
     *
     * @param num The integer to evaluate.
     * @return True if the integer is a palindrome, False otherwise.
     */
    // Strip any leading minus sign by taking the absolute value.
    val s = Math.abs(num).toString()
    // A number is a palindrome if the string equals its reverse.
    return s == s.reversed()
};1

