fun isqrt(x: Int): Int {
    var q = 1
    while (q <= x) {
        q *= 4
    }
    var z = x
    var r = 0
    while (q > 1) {
        q /= 4
        val t = z - r - q
        r /= 2
        if (t >= 0) {
            z = t
            r += q
        }
    }
    return r
}

