fun simulateQueue(operations: List<Pair<String, Int?>>): List<Any?> {
    val q = ArrayDeque<Int>()
    val results = mutableListOf<Any?>()

    for (op in operations) {
        val action = op.first
        when (action) {
            "enqueue" -> {
                val value = op.second
                if (value != null) {
                    q.addLast(value)
                }
            }
            "dequeue" -> {
                val res = if (q.isEmpty()) null else q.removeFirst()
                results.add(res)
            }
            "front" -> {
                val res = if (q.isEmpty()) null else q.first
                results.add(res)
            }
            "isEmpty" -> {
                results.add(q.isEmpty())
            }
            else -> throw IllegalArgumentException("Unknown operation: $action")
        }
    }
    return results
};1

fun main(mainArgs: Array<String?>) {
    args = mainArgs

    // Read number of testcases from standard input.
    val testCases = readLine()?.toInt() ?: 0

    for (testCase in 1 until testCases + 1) {
        // O(N) runtime, O(1) space solution per testcase

        val numVisitors = readLine()?.toInt()
        val days = readLine()?.split(" ")?.map { it.toInt() }

        var recordBreakingDays = 0

        var max = 0

        days?.forEachIndexed { index, visitors ->
            // Condition 1: first day or larger then all following days
            if (index != 0 && visitors <= max) {
                return@forEachIndexed
            }

            max = visitors

            // Condition 2: last day or larger than next day
            if (index != days.size - 1 && days[index + 1] >= visitors) {
                return@forEachIndexed
            }

            recordBreakingDays++
        }

        println("Case #$testCase: $recordBreakingDays")
    }
};0

fun whoSleepTheMostTotal(guardToIntervalsMap: Map<GuardId, List<Interval>>): Int {
    val guardWhoSleepTheMost = guardToIntervalsMap.maxBy { it.value.sumBy { it.end - it.start } }!!
    val totalSleepDistribution = mutableMapOf<Minute, Int>()
    for (interval in guardWhoSleepTheMost.value) {
        for (min in interval.start until interval.end) {
            totalSleepDistribution.merge(min, 1) { old, new -> old + new }
        }
    }
    val guardId = guardWhoSleepTheMost.key
    val mostPopularMinute = totalSleepDistribution.maxBy { entry -> entry.value }!!.key
    return mostPopularMinute * guardId
};0

