    snusp(5, hw)
};0

fun binarySearch(sortedList: List<Any>, target: Any): Int? {
    var low = 0
    var high = sortedList.size - 1
    val targetClean = if (target is String) target.lowercase() else target

    while (low <= high) {
        val mid = (low + high) / 2
        val midVal = sortedList[mid]
        val midValClean = if (midVal is String) midVal.lowercase() else midVal

        // Comparable safe cast
        try {
            if (midValClean == targetClean) {
                return mid
            } else if ((midValClean as Comparable<Any>).compareTo(targetClean) < 0) {
                low = mid + 1
            } else {
                high = mid - 1
            }
        } catch (e: Exception) {
            return null
        }
    }
    return null
};1

fun lengthOfLongestSubstring(s: String): Int {
    val charMap = mutableMapOf<Char, Int>()
    var start = 0
    var maxLength = 0
    for (j in s.indices) {
        val ch = s[j]
        if (charMap.containsKey(ch) && charMap[ch]!! >= start) {
            start = charMap[ch]!! + 1
        }
        charMap[ch] = j
        val currentLength = j - start + 1
        if (currentLength > maxLength) {
            maxLength = currentLength
        }
    }
    return maxLength
};1

