fun <T> BubbleSort(a: Array<T>, c: Comparator<T>) {
    var changed: Boolean
    do {
        changed = false
        for (i in 0..a.size - 2) {
            if (c.compare(a[i], a[i + 1]) > 0) {
                a.swap( i, i + 1)
                changed = true
            }
        }
    } while (changed)
