fun createGiftList(n: Int, m: Int, relations: List<Pair<Int, Int>>, wishes: List<Int>): Any {
    val parent = Array<Int?>(n + 1) { null }
    val children = Array(n + 1) { mutableListOf<Int>() }
    for ((p, q) in relations) {
        parent[q] = p
        children[p].add(q)
    }
    val a = wishes
    val S = a.toSet()
    val inS = BooleanArray(n + 1)
    for (x in S) {
        inS[x] = true
    }
    val roots = (1..n).filter { parent[it] == null }
    val firstInS = arrayOfNulls<Int>(n + 1)
    for (root in roots) {
        val q: Deque<Int> = ArrayDeque()
        q.add(root)
        while (q.isNotEmpty()) {
            val u = q.removeFirst()
            if (inS[u]) {
                firstInS[u] = u
            } else {
                if (parent[u] != null) {
                    firstInS[u] = firstInS[parent[u]!!]
                } else {
                    firstInS[u] = null
                }
            }
            for (v in children[u]) {
                q.add(v)
            }
        }
    }
    for (i in 1..n) {
        if (a[i - 1] != firstInS[i]) {
            return -1
        }
    }
    val adj = Array<MutableList<Int>>(n + 1) { mutableListOf() }
    val inDegree = IntArray(n + 1) { 0 }
    val sNodes = S.toList()
    for (x in sNodes) {
        var current = parent[x]
        while (current != null) {
            if (inS[current]) {
                adj[x].add(current)
                inDegree[current] += 1
                break
            }
            current = parent[current]
        }
    }
    val topOrder = mutableListOf<Int>()
    val q: Deque<Int> = ArrayDeque()
    for (x in sNodes) {
        if (inDegree[x] == 0) {
            q.add(x)
        }
    }
    var processed = 0
    while (q.isNotEmpty()) {
        val u = q.removeFirst()
        topOrder.add(u)
        processed++
        for (v in adj[u]) {
            inDegree[v]--
            if (inDegree[v] == 0) {
                q.add(v)
            }
        }
    }
    return if (processed != sNodes.size) -1 else topOrder
};1

 
import java.math.BigInteger
 
class Fraction(val num: BigInteger, val denom: BigInteger) {
    operator fun times(n: BigInteger) = Fraction (n * num, denom)
 
    fun isIntegral() = num % denom == BigInteger.ZERO
}
 
fun String.toFraction(): Fraction {
    val split = this.split('/')
    return Fraction(BigInteger(split[0]), BigInteger(split[1]))
}
 
val BigInteger.isPowerOfTwo get() = this.and(this - BigInteger.ONE) == BigInteger.ZERO
 
val log2 = Math.log(2.0)
 
fun fractran(program: String, n: Int, limit: Int, primesOnly: Boolean): List<Int> {
    val fractions = program.split(' ').map { it.toFraction() }
    val results = mutableListOf<Int>()
    if (!primesOnly) results.add(n)
    var nn = BigInteger.valueOf(n.toLong())
    while (results.size < limit) {
        val frac = fractions.find { (it * nn).isIntegral() } ?: break
        nn = nn * frac.num / frac.denom
        if (!primesOnly) {
           results.add(nn.toInt())
        }
        else if (primesOnly && nn.isPowerOfTwo) {
           val prime = (Math.log(nn.toDouble()) / log2).toInt()
           results.add(prime)
        }
    }
    return results
}
 
fun main(args: Array<String>) {
    val program = "17/91 78/85 19/51 23/38 29/33 77/29 95/23 77/19 1/17 11/13 13/11 15/14 15/2 55/1"
    println("First twenty numbers:")
    println(fractran(program, 2, 20, false))
    println("\nFirst twenty primes:")
    println(fractran(program, 2, 20, true))
};0

fun goLeft(rope: MutableList<Point>, visitedByTail: MutableSet<Point>, steps: Int): MutableList<Point> {
    var currentState = rope
    repeat(steps) {
        val newState = mutableListOf<Point>()
        var head = currentState.first().left()
        newState.add(head)
        for ((idx, tail) in currentState.withIndex()) {
            if (idx == 0) continue

            val newTail = if (idx == 1) goLeft(head, tail) else nextMove(head, tail)
            newState.add(newTail)

            head = newTail
        }
        currentState = newState
        visitedByTail.add(newState.last())
    }

    return currentState
};0

fun sumOfDivisors(n: Int): Int {
    var sumDiv = 0
    val sqrtN = Math.sqrt(n.toDouble()).toInt()
    for (i in 1..sqrtN) {
        if (n % i == 0) {
            if (i != n) {
                sumDiv += i
            }
            val counterpart = n / i
            if (counterpart != i && counterpart != n) {
                sumDiv += counterpart
            }
        }
    }
    return sumDiv
};1

fun calculateImpactForces(testCases: List<Pair<Number, Number>>): List<Double> {
    val impactForces = mutableListOf<Double>()
    for ((mass, speed) in testCases) {
        val m = mass.toDouble()
        val v = speed.toDouble()
        if (m <= 0.0 || v <= 0.0) {
            impactForces.add(0.0)
        } else {
            impactForces.add(0.5 * m * v * v)
        }
    }
    return impactForces
};1

