fun checkPrimeInRange(number: Int, lowerRange: Int, upperRange: Int): Pair<Boolean, Int> {
    fun isPrime(n: Int): Boolean {
        if (n < 2) return false
        if (n == 2) return true
        if (n % 2 == 0) return false
        var i = 3
        while (i * i <= n) {
            if (n % i == 0) return false
            i += 2
        }
        return true
    }
    var isPrimeInR = false
    if (number >= lowerRange && number <= upperRange) {
        isPrimeInR = isPrime(number)
    }
    var primeCount = 0
    for (num in lowerRange..upperRange) {
        if (isPrime(num)) {
            primeCount += 1
        }
    }
    return Pair(isPrimeInR, primeCount)
};1

fun processExperiment(exp: Map<String, Any?>): Map<String, Any?> {
    // Make a shallow copy to avoid mutating the original
    val result = exp.toMutableMap()

    // 1) Ensure cluster starts with 'urn' if it doesn't already
    val clusterVal = result["cluster"] as? String ?: ""
    if (!clusterVal.contains("urn")) {
        result["cluster"] = if (clusterVal.isNotEmpty()) "urn$clusterVal" else clusterVal
    }

    // 2) Ensure profile has a project prefix (separated by a comma)
    val profileVal = result["profile"] as? String ?: ""
    if (!profileVal.contains(",")) {
        result["profile"] = "default_project,$profileVal"
    }

    // 3) Default username
    if (result["username"] == null) {
        result["username"] = "default_user"
    }

    // 4) Default project
    if (result["project"] == null) {
        result["project"] = "default_project"
    }

    return result
};1

 
