const val N = 32
const val N2 = N * (N - 1) / 2
const val STEP = 0.05
 
val xval = DoubleArray(N)
val tsin = DoubleArray(N)
val tcos = DoubleArray(N)
val ttan = DoubleArray(N)
val rsin = DoubleArray(N2) { Double.NaN }
val rcos = DoubleArray(N2) { Double.NaN }
val rtan = DoubleArray(N2) { Double.NaN }
 
fun rho(x: DoubleArray, y: DoubleArray, r: DoubleArray, i: Int, n: Int): Double {
    if (n < 0) return 0.0
    if (n == 0) return y[i]
    val idx = (N - 1 - n) * (N - n) / 2 + i
    if (r[idx].isNaN()) {
        r[idx] = (x[i] - x[i + n]) /
                 (rho(x, y, r, i, n - 1) - rho(x, y, r, i + 1, n - 1)) +
                  rho(x, y, r, i + 1, n - 2)
    }
    return r[idx]
}
 
fun thiele(x: DoubleArray, y: DoubleArray, r: DoubleArray, xin: Double, n: Int): Double {
    if (n > N - 1) return 1.0
    return rho(x, y, r, 0, n) - rho(x, y, r, 0, n - 2) +
           (xin - x[n]) / thiele(x, y, r, xin, n + 1)
}
 
fun main(args: Array<String>) {
    for (i in 0 until N) {
        xval[i] = i * STEP
        tsin[i] = Math.sin(xval[i])
        tcos[i] = Math.cos(xval[i])
        ttan[i] = tsin[i] / tcos[i]
    }
    println("%16.14f".format(6 * thiele(tsin, xval, rsin, 0.5, 0)))
    println("%16.14f".format(3 * thiele(tcos, xval, rcos, 0.5, 0)))
    println("%16.14f".format(4 * thiele(ttan, xval, rtan, 1.0, 0)))
};0

fun Forest.getVisibleCoords(): Set<Pair<Int, Int>> {
    val foundInvisible = mutableSetOf<Pair<Int, Int>>()
    for (x in this.indices) {
        for (y in this[x].indices) {
            if (isVisible(x, y)) {
                foundInvisible.add(x to y)
            }
        }
    }
    return foundInvisible
};0

fun ireject(predicate: ((Any?) -> Boolean)?, iterable: List<Any?>): List<Any?> {
    return if (predicate == null) {
        iterable.filter { item ->
            // In Kotlin, consider falsy: false, 0, 0L, 0.0, 0.0f, "", null
            when(item) {
                null -> true
                is Boolean -> !item
                is Number -> when(item) {
                    is Int -> item == 0
                    is Long -> item == 0L
                    is Float -> item == 0.0f
                    is Double -> item == 0.0
                    else -> false
                }
                is String -> item.isEmpty()
                else -> false
            }
        }
    } else {
        iterable.filter { item -> !predicate(item) }
    }
};1

 
/** overload ++ operator to increment a numeric string */
operator fun String.inc(): String =
    try {
        val num = this.toInt()
        (num + 1).toString()
    }
    catch(e: NumberFormatException) {
        this  // return string unaltered
    }
 
fun main(args: Array<String>) {
    var ns = "12345"
    println(++ns)
    ns = "ghijk"  // not numeric, so won't be changed by increment operator
    println(++ns)
};0

fun List<Elf>.print()  {
    val x = this.map { it.pos.x }
    val y = this.map { it.pos.y }
    val minX = x.min() - 1
    val maxX = x.max() + 1
    val minY = y.min() - 1
    val maxY = y.max() + 1
    val result = List(maxY - minY + 1) {
        MutableList(maxX - minX + 1){
            "."
        }
    }
    map { result[it.pos.y - minY][it.pos.x - minX] = "#" }
    println(result.joinToString("\n") {it.joinToString("") } + "\n")
};0
